class Config:
    """Defaults of the program, stored as JSON in the user's home folder."""

    def __init__(self, path=CONFIG_FILE):
        self.path = Path(path)
        self.data = copy.deepcopy(DEFAULTS)
        self.load()

    def load(self):
        try:
            with open(self.path, "r", encoding="utf-8") as handle:
                stored = json.load(handle)
        except (OSError, ValueError):
            return False
        for section, values in (stored or {}).items():
            if section in self.data and isinstance(values, dict):
                for key, value in values.items():
                    if key in self.data[section]:
                        self.data[section][key] = value
        return True

    def save(self):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with open(self.path, "w", encoding="utf-8") as handle:
            json.dump(self.data, handle, indent=2, sort_keys=True)

    def reset(self):
        self.data = copy.deepcopy(DEFAULTS)

    def get(self, section, key):
        return self.data[section][key]

    def section(self, name):
        return dict(self.data[name])

    def set(self, section, key, value):
        self.data[section][key] = value


# --------------------------------------------------------------------------
# the picture of the program itself
# --------------------------------------------------------------------------

def icon_spectrum(x):
    """The curve drawn in the icon: a few peaks over a broad shoulder."""
    values = np.zeros_like(np.asarray(x, dtype=float))
    for centre, width, height in APP_ICON_PEAKS:
        values = values + height * np.exp(-0.5 * ((x - centre) / width) ** 2)
    top = float(np.max(values)) or 1.0
    return values / top


def app_icon_png(size=APP_ICON_SIZE):
    """The icon of the program as the bytes of a PNG file.

    It is the spectrum itself and nothing else: the blue body of the curve
    with its orange outline, filling a rounded square.  The square does not
    reach the edge of the picture: `APP_ICON_MARGIN` of free border is left
    around it, the way macOS draws its own icons, so that APlot sits at the
    same size as its neighbours in the Dock.  It is drawn rather than
    carried as a picture file, so the one file of the program stays the
    only thing that has to be copied, and the icon is sharp at whatever
    size the system asks for.
    """
    size = max(16, int(size))
    fig = Figure(figsize=(size / 100.0, size / 100.0), dpi=100)
    FigureCanvasAgg(fig)                     # a figure that is never shown
    ax = fig.add_axes([0.0, 0.0, 1.0, 1.0])
    ax.set_axis_off()
    ax.set_xlim(0.0, 1.0)
    ax.set_ylim(0.0, 1.0)
    # everything is drawn inside the square, which is itself inside the
    # picture: `inside` turns a place on the square into a place on it
    margin = min(0.45, max(0.0, float(APP_ICON_MARGIN)))
    span = 1.0 - 2.0 * margin

    def inside(value):
        return margin + span * np.asarray(value, dtype=float)

    # the rounded square is the paper the spectrum is drawn on, and it is
    # also what everything is cut to: nothing reaches over its corners
    panel = FancyBboxPatch(
        (margin, margin), span, span,
        boxstyle=f"round,pad=0,rounding_size={APP_ICON_ROUNDING * span}",
        facecolor=APP_ICON_PANEL, edgecolor="none", zorder=1)
    ax.add_patch(panel)
    # it runs off both sides, the way a spectrum fills a window
    x = np.linspace(-0.12, 1.12, 900)
    y = icon_spectrum(x)
    py = APP_ICON_FLOOR + y * (APP_ICON_CEILING - APP_ICON_FLOOR)
    body = ax.fill_between(inside(x), inside(-0.2), inside(py),
                           facecolor=APP_ICON_FILL, edgecolor="none", zorder=2)
    outline, = ax.plot(inside(x), inside(py), color=APP_ICON_LINE,
                       linewidth=size * span / 46.0,
                       solid_joinstyle="round", solid_capstyle="round",
                       zorder=3)
    for artist in (body, outline):
        artist.set_clip_path(panel)
    holder = io.BytesIO()
    fig.savefig(holder, format="png", dpi=100, transparent=True)
    return holder.getvalue()


DOCUMENT_ICON_PAGE = "#ffffff"   # the sheet of paper of an .aplt file
DOCUMENT_ICON_EDGE = "#b9b9b9"   # its outline
DOCUMENT_ICON_FOLD = "#e3e3e3"   # the corner folded over


def document_icon_png(size=APP_ICON_SIZE):
    """The icon of an `.aplt` file as the bytes of a PNG file.

    A sheet of paper with its top right corner folded over - the way macOS
    draws a document - and the spectrum of the program's own icon across
    its lower part, so that a graph is told from its program at a glance.
    Finder shows it for every graph that has no picture of its own (a file
    of an older version, or when the Quick Look viewer is not installed).
    """
    size = max(16, int(size))
    fig = Figure(figsize=(size / 100.0, size / 100.0), dpi=100)
    FigureCanvasAgg(fig)
    ax = fig.add_axes([0.0, 0.0, 1.0, 1.0])
    ax.set_axis_off()
    ax.set_xlim(0.0, 1.0)
    ax.set_ylim(0.0, 1.0)
    left, right, bottom, top = 0.17, 0.83, 0.06, 0.94
    fold = 0.18 * (right - left)
    line = max(0.8, size / 170.0)
    outline = [(left, bottom), (right, bottom), (right, top - fold),
               (right - fold, top), (left, top)]
    page = Polygon(outline, closed=True, facecolor=DOCUMENT_ICON_PAGE,
                   edgecolor=DOCUMENT_ICON_EDGE, linewidth=line,
                   joinstyle="round", zorder=1)
    ax.add_patch(page)
    corner = Polygon([(right - fold, top), (right - fold, top - fold),
                      (right, top - fold)], closed=True,
                     facecolor=DOCUMENT_ICON_FOLD,
                     edgecolor=DOCUMENT_ICON_EDGE, linewidth=line,
                     joinstyle="round", zorder=4)
    ax.add_patch(corner)
    # the spectrum across the lower part of the sheet, cut to the sheet
    x = np.linspace(-0.05, 1.05, 700)
    floor, ceiling = bottom + 0.04, bottom + 0.52
    py = floor + icon_spectrum(x) * (ceiling - floor)
    px = left + x * (right - left)
    body = ax.fill_between(px, bottom - 0.1, py, facecolor=APP_ICON_FILL,
                           edgecolor="none", zorder=2)
    curve, = ax.plot(px, py, color=APP_ICON_LINE,
                     linewidth=size * (right - left) / 50.0,
                     solid_joinstyle="round", solid_capstyle="round",
                     zorder=3)
    for artist in (body, curve):
        artist.set_clip_path(page)
    holder = io.BytesIO()
    fig.savefig(holder, format="png", dpi=100, transparent=True)
    return holder.getvalue()


_ICON_PHOTO = {}                 # size -> the Tk picture, which Tk may not lose


def app_icon_photo(size=APP_ICON_SIZE):
    """The icon as a Tk picture, or None when Tk cannot read a PNG."""
    size = int(size)
    if size in _ICON_PHOTO:
        return _ICON_PHOTO[size]
    try:
        photo = tk.PhotoImage(
            data=base64.b64encode(app_icon_png(size)).decode("ascii"))
    except (tk.TclError, ValueError, OSError, RuntimeError):
        return None
    _ICON_PHOTO[size] = photo
    return photo


def apply_app_icon(window, size=APP_ICON_SIZE):
    """Give a window - and the Dock or the task bar - the icon of APlot.

    `wm iconphoto` is what every system understands: on macOS Tk hands the
    picture to the Dock, on Linux and Windows it becomes the icon of the
    window.  `default=True` gives it to every window opened afterwards as
    well, so the diagrams carry it too.
    """
    photo = app_icon_photo(size)
    if photo is None:
        return False
    try:
        window.iconphoto(True, photo)
    except (tk.TclError, AttributeError):
        return False
    return True


def write_icon_file(path, size=APP_ICON_SIZE):
    """Write the icon into a PNG file; returns the path, or None."""
    try:
        target = Path(str(path)).expanduser()
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(app_icon_png(size))
    except (OSError, ValueError):
        return None
    return target


def write_icns(folder, name=APP_NAME, painter=None):
    """Build the `.icns` macOS wants, from the drawn icon; the path or None.

    macOS builds it out of a folder of PNGs with `iconutil`; when that tool
    is missing the largest PNG is written instead, which is enough for the
    Dock of most systems.  `painter(size)` draws one size (the icon of the
    program unless another is given - the one of a document, say).
    """
    painter = painter or app_icon_png
    folder = Path(str(folder)).expanduser()
    iconset = folder / f"{name}.iconset"
    try:
        iconset.mkdir(parents=True, exist_ok=True)
        for one in APP_ICON_SIZES:      # the names Apple's iconutil expects
            (iconset / f"icon_{one}x{one}.png").write_bytes(painter(one))
            (iconset / f"icon_{one}x{one}@2x.png").write_bytes(
                painter(one * 2))
    except (OSError, ValueError):
        return None
    target = folder / f"{name}.icns"
    try:
        done = subprocess.run(["iconutil", "-c", "icns", str(iconset),
                               "-o", str(target)],
                              capture_output=True, text=True, timeout=120)
        if done.returncode == 0 and target.is_file():
            shutil.rmtree(iconset, ignore_errors=True)
            return target
    except (OSError, subprocess.SubprocessError):
        pass
    shutil.rmtree(iconset, ignore_errors=True)
    fallback = folder / f"{name}.png"
    try:
        fallback.write_bytes(painter(APP_ICON_SIZE))
    except OSError:
        return None
    return fallback


APP_PLIST = """<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" \
"http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleName</key><string>{name}</string>
    <key>CFBundleDisplayName</key><string>{name}</string>
    <key>CFBundleExecutable</key><string>{name}</string>
    <key>CFBundleIdentifier</key><string>{identifier}</string>
    <key>CFBundleIconFile</key><string>{icon}</string>
    <key>CFBundleInfoDictionaryVersion</key><string>6.0</string>
    <key>CFBundlePackageType</key><string>APPL</string>
    <key>CFBundleShortVersionString</key><string>{version}</string>
    <key>CFBundleVersion</key><string>{version}</string>
    <key>LSMinimumSystemVersion</key><string>10.13</string>
    <key>NSHighResolutionCapable</key><true/>
{documents}
</dict>
</plist>
"""

# the kind of file APlot writes, told to macOS: its name (a "uniform type
# identifier"), its extension, and that APlot is the program that owns it.
# It is plain data to the system - not a ZIP archive - so that neither the
# Archive Utility nor the preview of ZIP files takes it for its own.
APP_PLIST_DOCUMENTS = """\
    <key>UTExportedTypeDeclarations</key>
    <array>
        <dict>
            <key>UTTypeIdentifier</key><string>{uti}</string>
            <key>UTTypeDescription</key><string>{name} graph</string>
            <key>UTTypeConformsTo</key>
            <array><string>public.data</string><string>public.content</string></array>
            <key>UTTypeIconFile</key><string>{icon}</string>
            <key>UTTypeTagSpecification</key>
            <dict>
                <key>public.filename-extension</key><array><string>{suffix}</string></array>
                <key>public.mime-type</key><array><string>{mime}</string></array>
            </dict>
        </dict>
    </array>
    <key>CFBundleDocumentTypes</key>
    <array>
        <dict>
            <key>CFBundleTypeName</key><string>{name} graph</string>
            <key>CFBundleTypeRole</key><string>Editor</string>
            <key>CFBundleTypeIconFile</key><string>{icon}</string>
            <key>LSHandlerRank</key><string>Owner</string>
            <key>LSItemContentTypes</key><array><string>{uti}</string></array>
        </dict>
    </array>"""
DOCUMENT_ICON_NAME = f"{APP_NAME}Document"   # the .icns of the graph files


def app_plist(name=APP_NAME, icon=None, document_icon=None):
    """The Info.plist of APlot.app, with the kind of file it owns."""
    documents = APP_PLIST_DOCUMENTS.format(
        uti=PROJECT_UTI, name=name, suffix=PROJECT_SUFFIX.lstrip("."),
        mime=PROJECT_MIMETYPE,
        icon=document_icon or f"{DOCUMENT_ICON_NAME}.icns")
    return APP_PLIST.format(name=name, identifier=APP_ID,
                            icon=icon or f"{name}.icns", documents=documents,
                            version=APP_VERSION)


def make_macos_app(folder=None, name=APP_NAME):
    """Build `APlot.app` around this very file; returns the path, or None.

    A program started as `python3 aplot.py` belongs to the interpreter as
    far as macOS is concerned: the Dock shows the icon and the name of
    Python.  A tiny application bundle - a folder with the right shape -
    gives it its own icon and its own name for good.  Nothing is compiled
    and nothing is copied: the bundle starts this same file.
    """
    if sys.platform != "darwin":
        return None
    home = Path(folder).expanduser() if folder else Path.home() / "Applications"
    bundle = home / f"{name}.app"
    macos, resources = bundle / "Contents" / "MacOS", bundle / "Contents" / "Resources"
    script = Path(__file__).resolve()
    try:
        macos.mkdir(parents=True, exist_ok=True)
        resources.mkdir(parents=True, exist_ok=True)
        icon = write_icns(resources, name)
        # the graph files get an icon of their own: a sheet with the curve
        document_icon = write_icns(resources, DOCUMENT_ICON_NAME,
                                   painter=document_icon_png)
        (bundle / "Contents" / "Info.plist").write_text(
            app_plist(name, icon=icon.name if icon else None,
                      document_icon=(document_icon.name if document_icon
                                     else None)),
            encoding="utf-8")
        launcher = macos / name
        launcher.write_text(
            "#!/bin/sh\n"
            f"export {BUNDLE_MARK}=1\n"     # the program knows it is in a bundle
            f'exec {shlex.quote(sys.executable)} {shlex.quote(str(script))} "$@"\n',
            encoding="utf-8")
        launcher.chmod(0o755)
        # macOS keeps what it knows about a bundle: it is told to look again
        subprocess.run(["touch", str(bundle)], capture_output=True, timeout=30)
        register_with_launch_services(bundle)
    except (OSError, ValueError, subprocess.SubprocessError):
        return None
    return bundle


LSREGISTER = ("/System/Library/Frameworks/CoreServices.framework/Frameworks/"
              "LaunchServices.framework/Support/lsregister")


def register_with_launch_services(bundle):
    """Tell macOS at once which files the bundle opens (and their icon).

    Without it the system learns it the first time the bundle is opened
    from the Finder, which is enough as well; this only saves the wait.
    """
    if not os.path.exists(LSREGISTER):
        return False
    try:
        done = subprocess.run([LSREGISTER, "-f", str(bundle)],
                              capture_output=True, timeout=60)
    except (OSError, subprocess.SubprocessError):
        return False
    return done.returncode == 0


# --------------------------------------------------------------------------
# the graph files on a Linux desktop: kind of file, icon, thumbnail
# --------------------------------------------------------------------------
# `python3 aplot.py --install-desktop` writes the few small files the
# freedesktop.org standards ask for, so that the file managers of Linux
# (GNOME Files, Nemo, Caja, Thunar, PCManFM...) know an .aplt file: its
# name, its icon, the picture of the graph as its thumbnail, and APlot as
# the program that opens it.  Nothing is compiled; `--uninstall-desktop`
# takes everything away again.

DESKTOP_ID = "aplot"                          # aplot.desktop, the icon names
DESKTOP_MIME_ICON = "application-x-aplot"     # the icon of the graph files
DESKTOP_ICON_SIZES = (16, 24, 32, 48, 64, 128, 256, 512)
THUMBNAILER_NAME = "aplot-thumbnailer"
PREVIEW_NAME = "aplot-preview"              # every diagram, in the PDF viewer
PREVIEW_MENU_NAME = "Preview all graphs (APlot)"   # the GNOME Files script
SUSHI_VIEWER_NAME = f"{DESKTOP_ID}.js"      # ~/.local/share/sushi/viewers

DESKTOP_MIME_XML = """<?xml version="1.0" encoding="UTF-8"?>
<!-- Written by aplot.py (install-desktop): the kind of file APlot writes. -->
<mime-info xmlns="http://www.freedesktop.org/standards/shared-mime-info">
  <mime-type type="{mime}">
    <comment>{name} graph</comment>
    <icon name="{icon}"/>
    <glob pattern="*{suffix}"/>
    <magic priority="60">
      <match type="string" offset="30" value="mimetype{mime}"/>
    </magic>
  </mime-type>
</mime-info>
"""

DESKTOP_THUMBNAILER = """[Thumbnailer Entry]
TryExec={script}
Exec={command} %i %o %s
MimeType={mime};
"""

DESKTOP_ENTRY = """[Desktop Entry]
Type=Application
Name={name}
GenericName=Data plotting
Comment=Spreadsheet and publication quality diagrams
Exec={command} %f
Icon={icon}
Terminal=false
StartupNotify=true
Categories=Science;DataVisualization;
MimeType={mime};
"""

THUMBNAILER_SCRIPT = '''#!/usr/bin/env python3
"""aplot-thumbnailer - the picture of an APlot graph, for the file managers.

Written by `aplot.py --install-desktop`.  A file manager calls it as

    aplot-thumbnailer INPUT OUTPUT SIZE

and it copies the picture APlot stores in every graph it saves (the entry
Thumbnails/thumbnail.png of the .aplt ZIP container) into OUTPUT, as a PNG
no larger than SIZE pixels.  A graph without a picture - one saved by an
older APlot, which is plain JSON - is refused, and the file manager shows
the icon of the kind of file instead.  Only the standard library is
needed; Pillow, when it is there, makes the picture exactly SIZE large.
"""
import io
import sys
import zipfile
from urllib.parse import unquote, urlparse

ENTRY = "Thumbnails/thumbnail.png"


def main(argv):
    if len(argv) < 3:
        sys.stderr.write("usage: aplot-thumbnailer INPUT OUTPUT [SIZE]\\n")
        return 2
    source, target = argv[1], argv[2]
    if source.startswith("file://"):         # some file managers pass a URI
        source = unquote(urlparse(source).path)
    try:
        size = int(argv[3]) if len(argv) > 3 else 256
    except ValueError:
        size = 256
    try:
        with zipfile.ZipFile(source) as archive:
            data = archive.read(ENTRY)
    except (OSError, KeyError, zipfile.BadZipFile):
        return 1                              # no picture in this file
    try:
        from PIL import Image
    except ImportError:
        Image = None
    if Image is not None and size > 0:
        try:
            picture = Image.open(io.BytesIO(data))
            picture.load()
            picture.thumbnail((size, size))
            picture.save(target, "PNG")
            return 0
        except (OSError, ValueError):
            pass                              # the plain copy below
    with open(target, "wb") as handle:
        handle.write(data)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
'''


PREVIEW_SCRIPT = '''#!/usr/bin/env python3
"""aplot-preview - every diagram of APlot graphs, in the PDF viewer.

Written by `aplot.py --install-desktop`.  It is what "Preview all graphs"
runs - in the "Open With" list of the file managers, as a script of GNOME
Files and in the menu of KDE's Dolphin:

    aplot-preview GRAPH.aplt [MORE.aplt ...]

APlot stores every diagram of a graph as one page of a PDF inside the
.aplt file (Thumbnails/preview.pdf).  That PDF is copied into a folder of
its own and opened with the PDF viewer of the desktop, where the diagrams
are paged through and zoomed as in any document.  A graph saved by an
older APlot has only the picture of one diagram, which is opened instead.

    aplot-preview --extract GRAPH.aplt

only copies the PDF (or the picture) out and prints where it is: that is
how the Space bar preview of GNOME Files (Sushi) gets it.
"""
import os
import shutil
import subprocess
import sys
import tempfile
import zipfile
from urllib.parse import unquote, urlparse

ENTRIES = (("Thumbnails/preview.pdf", ".pdf"), ("Thumbnails/thumbnail.png", ".png"))


def say(message):
    """Tell the user - in a desktop notification when there is one."""
    sys.stderr.write(message + "\\n")
    if shutil.which("notify-send"):
        subprocess.run(["notify-send", "APlot", message], check=False)


def folder():
    base = os.environ.get("XDG_RUNTIME_DIR") or tempfile.gettempdir()
    place = os.path.join(base, "aplot-preview")
    os.makedirs(place, exist_ok=True)
    return place


def show(path):
    """Open one file with the program the desktop chose for it."""
    for command in (["xdg-open", path], ["gio", "open", path]):
        if shutil.which(command[0]):
            subprocess.Popen(command, stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL, start_new_session=True)
            return True
    say("There is no program to open " + path)
    return False


def copy_out(source):
    """The PDF (or else the picture) of the graph `source`, copied into a
    file of its own; its path, or None when the graph carries neither."""
    if source.startswith("file://"):
        source = unquote(urlparse(source).path)
    name = os.path.splitext(os.path.basename(source))[0] or "graph"
    try:
        with zipfile.ZipFile(source) as archive:
            names = set(archive.namelist())
            for entry, suffix in ENTRIES:
                if entry in names:
                    target = os.path.join(folder(), name + suffix)
                    part = target + ".part"
                    with open(part, "wb") as handle:
                        handle.write(archive.read(entry))
                    os.replace(part, target)
                    return target
    except (OSError, KeyError, zipfile.BadZipFile):
        pass
    return None


def preview(source):
    target = copy_out(source)
    if target is not None:
        return show(target)
    say(os.path.basename(source) + " carries no preview: open it in APlot "
        "and save it once.")
    return False


def main(argv):
    if len(argv) == 3 and argv[1] == "--extract":
        target = copy_out(argv[2])
        if target is None:
            return 1
        print(target)
        return 0
    if len(argv) < 2 or argv[1].startswith("--"):
        sys.stderr.write("usage: aplot-preview GRAPH.aplt [MORE.aplt ...]\\n"
                         "       aplot-preview --extract GRAPH.aplt\\n")
        return 2
    shown = [preview(one) for one in argv[1:]]
    return 0 if all(shown) else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv))
'''

DESKTOP_PREVIEW_ENTRY = """[Desktop Entry]
Type=Application
Name=Preview all graphs ({name})
Comment=Every diagram of the graph, in the PDF viewer
Exec={command} %F
Icon={icon}
Terminal=false
NoDisplay=true
MimeType={mime};
"""

DESKTOP_SERVICE_MENU = """[Desktop Entry]
Type=Service
MimeType={mime};
Actions=aplotPreview;
X-KDE-Priority=TopLevel

[Desktop Action aplotPreview]
Name=Preview all graphs ({name})
Icon={icon}
Exec={command} %F
"""

NAUTILUS_SCRIPT = """#!/bin/sh
# Written by aplot.py (install-desktop): every diagram of the chosen graphs.
exec {command} "$@"
"""

# The Space bar preview of GNOME Files is Sushi (the "NautilusPreviewer").
# It loads extra viewers written in JavaScript from
# ~/.local/share/sushi/viewers - for one user only - and this one hands
# the PDF of a graph to Sushi's own document viewer.
SUSHI_VIEWER = """// aplot.js - APlot graphs in the Space bar preview of GNOME Files (Sushi).
//
// Written by `aplot.py --install-desktop`.  Sushi loads every viewer it
// finds in ~/.local/share/sushi/viewers; this one takes the graphs of
// APlot ({mime}).  The PDF that APlot stores in a graph - one page for
// every diagram (Thumbnails/preview.pdf) - is copied out by aplot-preview
// and shown by Sushi's own document viewer, with its page buttons.  A graph
// with only a picture shows the picture, and a graph with neither (plain
// JSON, saved by an older APlot) what Sushi shows for any other file.

const {{Gio, GLib}} = imports.gi;
const ByteArray = imports.byteArray;

const HELPER = {helper};

var mimeTypes = [{mimes}];

function copiedOut(file) {{
    let path = file.get_path();
    if (!path)
        return null;
    try {{
        let [, out] = GLib.spawn_sync(null, [HELPER, '--extract', path], null,
                                      GLib.SpawnFlags.DEFAULT, null);
        let copy = ByteArray.toString(out).trim();
        if (copy && GLib.file_test(copy, GLib.FileTest.IS_REGULAR))
            return Gio.File.new_for_path(copy);
    }} catch (e) {{
        logError(e, 'APlot: the preview of ' + path + ' cannot be copied out');
    }}
    return null;
}}

// Sushi calls `new Klass(file, fileInfo)`; what this returns is one of
// Sushi's own viewers, given the copied-out preview instead of the graph.
var Klass = function APlotRenderer(file, fileInfo) {{
    let copy = copiedOut(file);
    if (copy) {{
        let info = copy.query_info('standard::*', Gio.FileQueryInfoFlags.NONE, null);
        let kind = info.get_content_type();
        if (Gio.content_type_is_a(kind, 'application/pdf'))
            return new imports.viewers.evince.Klass(copy, info);
        if (Gio.content_type_is_a(kind, 'image/png'))
            return new imports.viewers.image.Klass(copy, info);
    }}
    return new imports.ui.fallbackRenderer.FallbackRenderer(file, fileInfo);
}};
"""


def desktop_quote(argument):
    """One argument of an `Exec=` line, quoted as the Desktop Entry
    specification asks (and escaped once more for the key file)."""
    text = str(argument)
    if text and not any(ch in text for ch in ' \t\n"\'\\><~|&;$*?#()`'):
        quoted = text
    else:
        inner = (text.replace("\\", "\\\\").replace('"', '\\"')
                 .replace("`", "\\`").replace("$", "\\$"))
        quoted = f'"{inner}"'
    return quoted.replace("\\", "\\\\").replace("%", "%%")


def _sudo_user():
    """(home, uid, gid) of the user who ran `sudo`, or None."""
    name = os.environ.get("SUDO_USER")
    if not name or name == "root":
        return None
    try:
        import pwd
        entry = pwd.getpwnam(name)
    except (ImportError, KeyError):
        return None
    return Path(entry.pw_dir), entry.pw_uid, entry.pw_gid


def sushi_viewer_path(system=False, prefix=None):
    """Where the Space bar viewer of GNOME Files (Sushi) goes, or None.

    Sushi reads extra viewers only from the data folder of the user
    (~/.local/share/sushi/viewers), never from a folder for everybody, so
    an install for every user puts it into the home of the one who ran
    `sudo` - and there is none to put it into when root ran it directly.
    """
    tail = Path("share") / "sushi" / "viewers" / SUSHI_VIEWER_NAME
    if prefix is not None:
        return Path(prefix).expanduser() / tail
    if not system:
        return Path.home() / ".local" / tail
    user = _sudo_user()
    return None if user is None else user[0] / ".local" / tail


def linux_desktop_paths(system=False, prefix=None):
    """Where every file of the desktop integration goes.

    For one user (the default) everything lies under ~/.local; with
    `system` (run through sudo) under /usr/local, for every user of the
    computer - which is what GNOME Files needs for the thumbnails, because
    it runs a thumbnailer in a sandbox that cannot look into the home
    folder.  `prefix` puts it all somewhere else (used by the tests).
    """
    if prefix is not None:
        root = Path(prefix).expanduser()
    elif system:
        root = Path("/usr/local")
    else:
        root = Path.home() / ".local"
    share = root / "share"
    paths = {
        "root": root, "share": share,
        "mime": share / "mime" / "packages" / f"{DESKTOP_ID}.xml",
        "mime_db": share / "mime",
        "script": root / "bin" / THUMBNAILER_NAME,
        "thumbnailer": share / "thumbnailers" / f"{DESKTOP_ID}.thumbnailer",
        "desktop": share / "applications" / f"{DESKTOP_ID}.desktop",
        "applications": share / "applications",
        # "Preview all graphs": the program, its line in "Open With", the
        # menu of Dolphin (both kinds of KDE) and a script of GNOME Files
        "preview": root / "bin" / PREVIEW_NAME,
        "preview_desktop": share / "applications" / f"{DESKTOP_ID}-preview.desktop",
        "service_menu": share / "kio" / "servicemenus" / f"{DESKTOP_ID}-preview.desktop",
        "service_menu_5": share / "kservices5" / "ServiceMenus" / f"{DESKTOP_ID}-preview.desktop",
        "nautilus": share / "nautilus" / "scripts" / PREVIEW_MENU_NAME,
        "icons": share / "icons" / "hicolor",
        # the Space bar of GNOME Files (None: there is no user to give it to)
        "sushi": sushi_viewer_path(system, prefix),
    }
    for size in DESKTOP_ICON_SIZES:
        folder = paths["icons"] / f"{size}x{size}"
        paths[f"mime_icon_{size}"] = folder / "mimetypes" / f"{DESKTOP_MIME_ICON}.png"
        paths[f"app_icon_{size}"] = folder / "apps" / f"{DESKTOP_ID}.png"
    return paths


def _run_quietly(command):
    """Run a helper of the desktop, if it is installed; True when it worked."""
    if shutil.which(command[0]) is None:
        return False
    try:
        done = subprocess.run(command, capture_output=True, timeout=120)
    except (OSError, subprocess.SubprocessError):
        return False
    return done.returncode == 0


def install_linux_desktop(system=False, prefix=None, program=None,
                          python=None, refresh=True):
    """Write the kind of file, its icon, the thumbnailer and APlot's entry.

    `program` is the aplot.py that the double click starts (this file by
    default) and `python` the interpreter that runs it (the one running
    now).  Returns the list of the files written.
    """
    paths = linux_desktop_paths(system, prefix)
    program = Path(program or __file__).resolve()
    python = python or sys.executable or "python3"
    written = []

    def write(key, content, mode=0o644, owner=None):
        target = paths[key]
        made = [folder for folder in reversed(target.parents)
                if not folder.exists()]
        target.parent.mkdir(parents=True, exist_ok=True)
        if isinstance(content, bytes):
            target.write_bytes(content)
        else:
            target.write_text(content, encoding="utf-8")
        os.chmod(target, mode)
        if owner is not None:           # a file in the home of someone else
            for one in made + [target]:
                try:
                    os.chown(one, *owner)
                except OSError:
                    pass
        written.append(target)

    write("mime", DESKTOP_MIME_XML.format(
        mime=PROJECT_MIMETYPE, name=APP_NAME, icon=DESKTOP_MIME_ICON,
        suffix=PROJECT_SUFFIX))
    write("script", THUMBNAILER_SCRIPT, mode=0o755)
    write("thumbnailer", DESKTOP_THUMBNAILER.format(
        script=paths["script"], command=desktop_quote(paths["script"]),
        mime=PROJECT_MIMETYPE))
    write("desktop", DESKTOP_ENTRY.format(
        name=APP_NAME, icon=DESKTOP_ID, mime=PROJECT_MIMETYPE,
        command=f"{desktop_quote(python)} {desktop_quote(program)}"))
    write("preview", PREVIEW_SCRIPT, mode=0o755)
    preview = desktop_quote(paths["preview"])
    write("preview_desktop", DESKTOP_PREVIEW_ENTRY.format(
        name=APP_NAME, icon=DESKTOP_ID, mime=PROJECT_MIMETYPE,
        command=preview))
    # KDE only runs the menu files of a user that may be run (executable)
    for key in ("service_menu", "service_menu_5"):
        write(key, DESKTOP_SERVICE_MENU.format(
            name=APP_NAME, icon=DESKTOP_ID, mime=PROJECT_MIMETYPE,
            command=preview), mode=0o755)
    if not system:                      # GNOME Files keeps scripts per user
        write("nautilus", NAUTILUS_SCRIPT.format(
            command=shlex.quote(str(paths["preview"]))), mode=0o755)
    if paths["sushi"] is not None:      # the Space bar of GNOME Files
        user = _sudo_user() if system and prefix is None else None
        write("sushi", SUSHI_VIEWER.format(
            mime=PROJECT_MIMETYPE, mimes=json.dumps(PROJECT_MIMETYPE),
            helper=json.dumps(str(paths["preview"]))),
            owner=None if user is None else user[1:])
    for size in DESKTOP_ICON_SIZES:
        write(f"mime_icon_{size}", document_icon_png(size))
        write(f"app_icon_{size}", app_icon_png(size))
    if refresh:
        _run_quietly(["update-mime-database", str(paths["mime_db"])])
        _run_quietly(["update-desktop-database", str(paths["applications"])])
        _run_quietly(["gtk-update-icon-cache", "-f", "-t", str(paths["icons"])])
        if not system and prefix is None:  # APlot opens the graphs of this user
            _run_quietly(["xdg-mime", "default", f"{DESKTOP_ID}.desktop",
                          PROJECT_MIMETYPE])
    return written


def uninstall_linux_desktop(system=False, prefix=None, refresh=True):
    """Take away everything `install_linux_desktop` wrote; the files removed."""
    paths = linux_desktop_paths(system, prefix)
    keys = ["mime", "script", "thumbnailer", "desktop", "preview",
            "preview_desktop", "service_menu", "service_menu_5", "nautilus",
            "sushi"]
    keys += [f"{kind}_icon_{size}" for size in DESKTOP_ICON_SIZES
             for kind in ("mime", "app")]
    removed = []
    for key in keys:
        target = paths[key]
        if target is None:
            continue
        try:
            if target.is_file():
                target.unlink()
                removed.append(target)
        except OSError:
            continue
    if refresh:
        _run_quietly(["update-mime-database", str(paths["mime_db"])])
        _run_quietly(["update-desktop-database", str(paths["applications"])])
        _run_quietly(["gtk-update-icon-cache", "-f", "-t", str(paths["icons"])])
    return removed


def running_from_bundle():
    """True when this program was started from its own `APlot.app`."""
    if os.environ.get(BUNDLE_MARK):
        return True
    if sys.platform != "darwin":
        return False
    try:                       # started by hand from inside the bundle
        return f"/{APP_NAME}.app/Contents/" in str(Path(sys.argv[0]).resolve())
    except (OSError, ValueError):
        return False


# --------------------------------------------------------------------------
# taking a step back, and taking it again
# --------------------------------------------------------------------------

class UndoStep:
    """One change: what there was before it, and what there is after it.

    `restore` is the function that puts one of the two back, so a step
    knows nothing about what it holds - a whole sheet, one diagram - and
    the same list can carry every kind of change.
    """

    __slots__ = ("label", "before", "after", "restore")

    def __init__(self, label, before, after, restore):
        self.label = str(label)
        self.before = before
        self.after = after
        self.restore = restore


class UndoStack:
    """The steps that can be taken back, and the ones taken back already.

    Doing something new throws the second list away, as everywhere else:
    once the work has gone another way there is nothing to redo.
    """

    def __init__(self, limit=UNDO_STEPS):
        self.limit = max(1, int(limit))
        self.done = []
        self.undone = []
        self.blocked = 0        # while a step is applied nothing is recorded

    # -- recording ---------------------------------------------------------
    def busy(self):
        """True while a step is being applied, or recording is switched off."""
        return self.blocked > 0

    def hold(self):
        """Switch recording off; `release` switches it on again."""
        self.blocked += 1
        return self

    def release(self):
        self.blocked = max(0, self.blocked - 1)
        return self

    def __enter__(self):
        return self.hold()

    def __exit__(self, *_error):
        self.release()
        return False

    def push(self, step):
        if self.busy() or step is None:
            return None
        self.done.append(step)
        del self.done[:-self.limit]
        self.undone.clear()
        return step

    def clear(self):
        self.done.clear()
        self.undone.clear()
        return True

    # -- using it ----------------------------------------------------------
    def can_undo(self):
        return bool(self.done)

    def can_redo(self):
        return bool(self.undone)

    def undo_label(self):
        return self.done[-1].label if self.done else ""

    def redo_label(self):
        return self.undone[-1].label if self.undone else ""

    def undo(self):
        if not self.done:
            return None
        step = self.done.pop()
        self.hold()
        try:
            step.restore(step.before)
        finally:
            self.release()
        self.undone.append(step)
        return step

    def redo(self):
        if not self.undone:
            return None
        step = self.undone.pop()
        self.hold()
        try:
            step.restore(step.after)
        finally:
            self.release()
        self.done.append(step)
        return step


class PlotChange:
    """One command on a diagram, remembered so that it can be taken back.

    It is used as `with window.changed("the drawing"):` around whatever
    changes the diagram.  Commands that call one another nest: only the
    outermost one becomes a step, so pasting an object is one step and not
    two.
    """

    def __init__(self, window, label):
        self.window = window
        self.label = str(label)
        self.before = None

    def _app(self):
        return getattr(self.window, "app", None)

    def __enter__(self):
        window = self.window
        window._change_depth = getattr(window, "_change_depth", 0) + 1
        app = self._app()
        if window._change_depth == 1 and app is not None and not app.undo.busy():
            try:
                self.before = app.plot_document(window)
            except (AttributeError, tk.TclError, ValueError):
                self.before = None
        return self

    def __exit__(self, *_error):
        window = self.window
        window._change_depth = max(0, getattr(window, "_change_depth", 1) - 1)
        if window._change_depth == 0 and self.before is not None:
            app = self._app()
            if app is not None:
                try:
                    app.record_plot(window, self.label, self.before)
                except (AttributeError, tk.TclError, ValueError):
                    pass
        return False


def set_macos_app_name(name=APP_NAME):
    """Make macOS call this program `name` instead of the interpreter.

    Must run before the first Tk window is created.  Two things are told:
    the **bundle** the process belongs to - which is what the bold
    application menu reads - and the **process name**, which is one of the
    things the Dock reads.  It needs pyobjc (`pip install
    pyobjc-framework-Cocoa`); without it nothing here happens and the
    program works exactly as before.

    Neither of them is the whole answer: a program started as
    `python3 aplot.py` is the Python interpreter as far as Launch Services
    is concerned, and the label under the Dock icon can come from there.
    `make_macos_app` builds the small bundle that settles it for good.
    """
    if sys.platform != "darwin":
        return False
    done = False
    try:
        from Foundation import NSBundle  # type: ignore
        bundle = NSBundle.mainBundle()
        info = bundle.localizedInfoDictionary() or bundle.infoDictionary()
        if info is not None:
            info["CFBundleName"] = name
            info["CFBundleDisplayName"] = name
            info["CFBundleExecutable"] = name
            info["CFBundleIdentifier"] = APP_ID
            done = True
    except Exception:
        pass
    try:                    # what the Dock and the Activity Monitor show
        from Foundation import NSProcessInfo  # type: ignore
        NSProcessInfo.processInfo().setProcessName_(name)
        done = True
    except Exception:
        pass
    return done


def macos_name_is_borrowed():
    """True while macOS is still calling this program by another name.

    That is the case whenever it runs as a plain script: the Dock then
    labels it after the interpreter (`python3.12`).  Inside `APlot.app` the
    name is the program's own and there is nothing to mend.
    """
    return sys.platform == "darwin" and not running_from_bundle()


# --------------------------------------------------------------------------
# reusable widgets
# --------------------------------------------------------------------------

class PairedFields:
    """Sections whose lines may carry two settings, aligned across sections.

    Every section is a grid of four columns: label, widget, label, widget.
    `align_columns` gives a group of sections the same column widths, so the
    second setting of every shared line starts at the same place - the
    labels and the boxes behind them alike.
    """

    @staticmethod
    def _padding(info):
        """The horizontal padding of one grid cell, whatever Tk reports."""
        value = info.get("padx", 0)
        if isinstance(value, (list, tuple)):
            parts = [str(one) for one in value]
        else:
            parts = str(value).split()
        total = 0
        for part in parts:
            try:
                total += int(float(part))
            except (TypeError, ValueError):
                pass
        return total

    @staticmethod
    def _pair(box, row, first_text, first_widget, second_text, second_widget,
              pady=2):
        """Two settings on one line: label, widget, label, widget."""
        if isinstance(first_text, str):
            label1 = ttk.Label(box, text=first_text)
            text1 = first_text
        else:
            label1 = first_text
            text1 = first_text.cget("text")
            
        label1.grid(row=row, column=0, sticky="w", padx=(0, 4), pady=pady)
        first_widget.grid(row=row, column=1, sticky="w", pady=pady)
        if text1 and first_widget:
            try:
                Tooltip(first_widget, "Set the " + text1.rstrip(":").replace(" [px]", " in pixels").lower())
            except Exception: pass
            
        if isinstance(second_text, str):
            label2 = ttk.Label(box, text=second_text)
            text2 = second_text
        else:
            label2 = second_text
            text2 = second_text.cget("text")
            
        label2.grid(row=row, column=2, sticky="w", padx=(8, 4), pady=pady)
        second_widget.grid(row=row, column=3, sticky="w", pady=pady)
        if text2 and second_widget:
            try:
                Tooltip(second_widget, "Set the " + text2.rstrip(":").replace(" [px]", " in pixels").lower())
            except Exception: pass
        return first_widget, second_widget

    @staticmethod
    def _wide(widget, row, pady=(6, 0), columnspan=4):
        """One widget across the whole width of a section."""
        widget.grid(row=row, column=0, columnspan=columnspan, sticky="ew",
                    pady=pady)
        try:
            if isinstance(widget, ttk.Checkbutton):
                Tooltip(widget, "Toggle " + widget.cget("text").lower())
        except Exception:
            pass
        return widget

    def _align_columns(self, boxes):
        """Give a group of sections the same first three column widths."""
        try:      # the colour boxes only know their size once they are laid out
            self.update_idletasks()
        except tk.TclError:
            pass
        # column 2 carries the second label of a shared line ("Colour:",
        # "To:", "Minor ticks:"); it has to be as wide everywhere, or the
        # widget behind it would start at a different place in every section
        widest = {0: 0, 1: 0, 2: 0}
        for box in boxes:
            for child in box.winfo_children():
                info = child.grid_info()
                if not info or int(info.get("columnspan", 1)) != 1:
                    continue
                column = int(info.get("column", 0))
                if column in widest:
                    # the free space around the widget belongs to the cell
                    needed = child.winfo_reqwidth() + self._padding(info)
                    widest[column] = max(widest[column], needed)
        for box in boxes:
            for column, width in widest.items():
                box.grid_columnconfigure(column, minsize=width + 4)


class Tooltip:
    """A small yellow hint that appears while the pointer rests on a widget."""

    def __init__(self, widget, text, delay=TOOLTIP_DELAY):
        self.widget = widget
        self.text = str(text)
        self.delay = int(delay)
        self._timer = None
        self._window = None
        widget.tooltip = self          # the hint of a button can be asked for
        widget.bind("<Enter>", self._entered, add="+")
        widget.bind("<Leave>", self._left, add="+")
        widget.bind("<ButtonPress>", self._left, add="+")
        widget.bind("<Destroy>", self._left, add="+")

    # -- the pointer comes and goes ----------------------------------------
    def _entered(self, _event=None):
        self._cancel()
        try:
            self._timer = self.widget.after(self.delay, self.show)
        except tk.TclError:
            self._timer = None

    def _left(self, _event=None):
        self._cancel()
        self.hide()

    def _cancel(self):
        if self._timer is not None:
            try:
                self.widget.after_cancel(self._timer)
            except tk.TclError:
                pass
            self._timer = None

    # -- the hint itself ---------------------------------------------------
    def visible(self):
        return bool(self._window is not None and self._window.winfo_exists())

    def show(self):
        """Show the hint right below the widget; returns the little window."""
        self._timer = None
        if self.visible() or not self.text:
            return self._window
        try:
            if not self.widget.winfo_exists():
                return None
            x = self.widget.winfo_rootx()
            y = self.widget.winfo_rooty() + self.widget.winfo_height() + 3
            if self._pointer_elsewhere():
                return None          # the pointer has already moved on
            window = tk.Toplevel(self.widget)
            window.wm_overrideredirect(True)
            window.wm_geometry(f"+{x}+{y}")
            label = tk.Label(window, text=self.text, justify="left",
                             background=TOOLTIP_BACKGROUND, foreground="#000000",
                             relief="solid", borderwidth=1, padx=5, pady=2)
            label.pack()
            self._window = window
            self.label = label
            self._poll_leave()
        except tk.TclError:
            self._window = None
        return self._window

    def _pointer_elsewhere(self):
        """True only while the pointer is known to be over something else.

        A pointer that is not over this program at all says nothing: the
        hint of a widget under an open menu, or of a window that does not
        have the pointer, is left alone rather than refused.
        """
        try:
            under = self.widget.winfo_containing(*self.widget.winfo_pointerxy())
        except (tk.TclError, TypeError):
            return False
        if under is None:
            return False
        while under is not None:
            if under is self.widget:
                return False
            under = getattr(under, "master", None)
        return True

    def _poll_leave(self):
        """Hide the hint even when the <Leave> event is lost."""
        if not self.visible():
            return
        try:
            if not self.widget.winfo_exists():
                self.hide()
                return
            if self._pointer_elsewhere():
                self.hide()
            else:
                self.widget.after(250, self._poll_leave)
        except tk.TclError:
            pass

    def hide(self):
        window, self._window = self._window, None
        if window is not None:
            try:
                if window.winfo_exists():
                    window.destroy()
            except tk.TclError:
                pass
        return None

    def set_text(self, text):
        self.text = str(text)
        if self.visible():
            self.hide()
            self.show()


class ColorSwatch(ttk.Frame):
    """Colour preview + 'Choose...' button. Cross platform (uses a Canvas)."""

    def __init__(self, master, color=PALETTE_FALLBACK, command=None):
        super().__init__(master)
        self._color = safe_hex(color)
        self._command = command

        self.preview = tk.Canvas(self, width=32, height=18, cursor="hand2",
                                 highlightthickness=1, highlightbackground="#777")
        self.preview.pack(side="left")
        self.preview.bind("<Button-1>", lambda _e: self.choose())
        ttk.Button(self, text="Choose...", width=6, command=self.choose).pack(
            side="left", padx=(5, 0))
        self._redraw()

    @property
    def color(self):
        return self._color

    def set_color(self, color, notify=False):
        self._color = safe_hex(color, self._color)
        self._redraw()
        if notify and self._command:
            self._command(self._color)

    def _redraw(self):
        self.preview.configure(background=self._color)

    def choose(self):
        _rgb, hex_value = colorchooser.askcolor(color=self._color,
                                                parent=self.winfo_toplevel())
        if hex_value:
            self.set_color(hex_value, notify=True)


class SwatchField:
    """A colour swatch that answers like a tk variable: get() and set()."""

    def __init__(self, swatch):
        self.swatch = swatch

    def get(self):
        return safe_hex(self.swatch.color, "#000000")

    def set(self, value):
        self.swatch.set_color(value)


def field_number(value, fallback=""):
    """A number the way the dialogs write it into a box: 11, 1.5, 0.35."""
    try:
        return f"{float(value):g}"
    except (TypeError, ValueError):
        return fallback


class DiagramMirror:
    """A dialog (or one page of it) that keeps showing what the diagram says.

    A properties window holds a **copy** of the settings it shows, and its
    Apply sends that whole copy back.  While it stands open the diagram
    keeps changing without it: a title written on the graph itself, a
    legend renamed there, a text box turned by its handle, `Resize graph`,
    a step of Undo.  A copy that stayed as it was when the window opened
    would put all of that back to the old values at the next Apply, next to
    the one thing the user really meant to change.

    So every field is compared with the diagram each time the diagram is
    drawn, and follows it - with one exception: a field the user has
    changed in the window and not applied yet is theirs, and is left alone
    until Apply takes it.

    `_diagram_fields()` gives, for every field, the variable (or a
    `SwatchField`) and the value the diagram has for it right now, written
    exactly the way the field writes it.  `None` means "the diagram has no
    opinion here" (a colour of something transparent, say).
    """

    def _diagram_fields(self):
        return {}

    def _mirrored(self, names):
        """Some fields were refreshed: tidy whatever depends on them."""
        return None

    def _mirror_book(self):
        book = self.__dict__.get("_mirror_state")
        if book is None:
            book = self.__dict__["_mirror_state"] = ({}, {})
        return book

    def mirror(self, force=False, only=None):
        """Let the fields follow the diagram; the names that changed.

        `force` refreshes a field even while the user is editing it - used
        right after Apply, when the diagram holds what the window said.
        """
        try:
            fields = self._diagram_fields()
        except (AttributeError, KeyError, IndexError, TypeError, ValueError,
                tk.TclError):
            return []
        seen, shown_then = self._mirror_book()
        changed = []
        for name, (field, value) in fields.items():
            if value is None or (only is not None and name not in only):
                continue
            try:
                shown = field.get()
            except (tk.TclError, ValueError):
                continue
            if shown == value:
                # the window and the diagram agree: nothing of the user's
                # is waiting in this field
                seen[name] = shown_then[name] = value
                continue
            if not force and name in seen:
                if value == seen[name]:
                    continue        # the diagram did not move: the user did
                if shown != shown_then.get(name, shown):
                    seen[name] = value
                    continue        # typed in and not applied yet: theirs
            try:
                field.set(value)
            except (tk.TclError, ValueError):
                continue
            seen[name] = shown_then[name] = value
            changed.append(name)
        if changed:
            self._mirrored(changed)
        return changed

    def mirror_rebase(self, names):
        """These fields were rewritten by the window itself (another unit):
        what they show now counts as what the diagram said."""
        seen, shown_then = self._mirror_book()
        fields = self._diagram_fields()
        for name in names:
            if name in fields:
                try:
                    shown_then[name] = fields[name][0].get()
                except (tk.TclError, ValueError):
                    pass
                seen[name] = fields[name][1]


class ShapeToolButton(tk.Canvas):
    """Toolbar button with an icon and a small menu arrow on its right.

    Clicking the icon starts drawing with the object that is shown; clicking
    the arrow opens the list of the available objects.  `family` selects
    what the icon draws: the shapes or the arrow heads.
    """

    ARROW_ZONE = 14
    LINE = ICON_ADD_EDGE            # the outline of the shape it draws
    FILL = ICON_BLUE                # ...and what stands inside it
    MENU = ICON_EDGE                # the little arrow that opens the list

    def __init__(self, master, kind="rect", size=ICON_SIZE + 4, family="shape",
                 background=None, on_draw=None, on_menu=None):
        self._background = background or master.cget("background")
        super().__init__(master, width=size + ShapeToolButton.ARROW_ZONE,
                         height=size, highlightthickness=0, borderwidth=0,
                         background=self._background, cursor="hand2")
        self._size = size
        self.family = family
        self.kind = kind
        self._on_draw = on_draw
        self._on_menu = on_menu
        self.bind("<Button-1>", self._clicked)
        self.set_shape(kind)

    # -- drawing the icon --------------------------------------------------
    def set_shape(self, kind):
        self.kind = kind
        self.delete("icon")
        pad = 4
        x0, y0 = pad, pad
        x1, y1 = self._size - pad, self._size - pad
        style = {"outline": self.LINE, "width": 2, "fill": self.FILL,
                 "tags": "icon"}
        if self.family == "arrow":
            self._draw_arrow_icon(kind, x0, y0, x1, y1)
        elif kind == "triangle":
            self.create_polygon([(x0 + x1) / 2, y0, x0, y1, x1, y1],
                                outline=self.LINE, fill=self.FILL, width=2,
                                tags="icon")
        elif kind == "line":
            self.create_line(x0, y1, x1, y0, fill=self.LINE, width=3,
                             tags="icon")
        elif kind == "circle":
            self.create_oval(x0, y0, x1, y1, **style)
        elif kind == "ellipse":
            self.create_oval(x0, y0 + 3, x1, y1 - 3, **style)
        else:
            self.create_rectangle(x0, y0 + 2, x1, y1 - 2, **style)
        self._draw_menu_arrow()

    def _draw_arrow_icon(self, kind, x0, y0, x1, y1):
        """A right pointing arrow whose head shows the selected type."""
        middle = (y0 + y1) / 2
        # the head grows with the button
        tip, back = x1, x1 - round(self._size * 0.32)
        half = round(self._size * 0.2)
        self.create_line(x0, middle, back, middle, fill=self.LINE, width=3,
                         tags="icon")
        if kind == "chevron":
            self.create_line(back, middle - half, tip, middle, back,
                             middle + half, fill=self.LINE, width=3,
                             tags="icon")
            return
        if kind == "concave":
            points = [tip, middle, back, middle - half,
                      back + 3, middle, back, middle + half]
        elif kind == "convex":
            points = [tip, middle, back, middle - half,
                      back - 2, middle, back, middle + half]
        else:                                    # triangle
            points = [tip, middle, back, middle - half, back, middle + half]
        self.create_polygon(points, fill=self.FILL, outline=self.LINE,
                            width=2, tags="icon")

    def _draw_menu_arrow(self):
        self.delete("arrow")
        width = int(self["width"])
        height = int(self["height"])
        x, y = width - 4, height - 4
        self.create_polygon([x - 7, y - 5, x, y - 5, x - 3.5, y],
                            fill=self.MENU, outline=self.MENU, tags="arrow")

    def set_active(self, active):
        self.configure(background=ICON_ARMED if active else self._background)

    # -- behaviour ---------------------------------------------------------
    def _clicked(self, event):
        if event.x >= int(self["width"]) - ShapeToolButton.ARROW_ZONE:
            if self._on_menu:
                self._on_menu(event)
        elif self._on_draw:
            self._on_draw()
        return "break"


class PlotSplitButton(ttk.Button):
    """The Plot button: a little picture of the style it will draw.

    The icon follows the chosen style - a line, a pie, a staircase - and the
    arrow on its right opens the list of the nine of them.
    """

    LABEL = "  Plot"            # the word beside the picture
    ARROW = "  \u23f7"          # the small triangle of the split button

    def __init__(self, master, style="line_symbol", width=0, height=26,
                 background=None, on_plot=None, on_menu=None):
        super().__init__(master, text=self.LABEL + self.ARROW, width=0,
                         style=TOOLBAR_STYLE, compound="left", command=on_plot)
        self.style = style
        self.icon_img = None
        self.on_menu = on_menu
        self.bind("<ButtonPress-1>", self._clicked)
        self.tooltip = Tooltip(self, "")
        self.set_style(style)

    def _clicked(self, event):
        # The right 20 pixels are the dropdown zone
        if event.x > self.winfo_width() - 20:
            if self.on_menu:
                self.on_menu(self)
            return "break"

    def set_style(self, style):
        self.style = style
        picture = plot_style_icon(style)
        if picture is not None:
            self.icon_img = picture          # kept, or Tk lets it go
            self.configure(image=picture, text=self.LABEL + self.ARROW,
                           compound="left")
        else:                                # no Pillow: a plain text button
            self.configure(text=self.LABEL + self.ARROW)
        style_desc = dict((code, label) for label, code, *_ in PLOT_STYLES).get(style, "Plot")
        self.tooltip.set_text(f"Plot: {style_desc} (click arrow to change)")
        return picture


# --------------------------------------------------------------------------
# the little pictures on the toolbar buttons
# --------------------------------------------------------------------------
# They are drawn by the program itself - no picture files to carry around -
# four times as big as they are shown and then shrunk, which is what makes
# the edges smooth.  The colours are clear and flat, each shape with a
# darker edge of its own colour, so the buttons are easy to see and still
# stay quiet beside the table.


class _WeightedDraw:
    """An `ImageDraw` whose lines come out stronger (`ICON_LINE_WEIGHT`).

    The drawings give their lines as fractions of the icon; this makes the
    thin outlines thicker and the strokes of the curves a little thicker,
    in one place, so that every icon of the program gets the same weight.
    """

    def __init__(self, draw, box):
        self._draw = draw
        self._box = float(box)

    def __getattr__(self, name):
        method = getattr(self._draw, name)
        if not callable(method):
            return method

        def weighted(*args, **kwargs):
            width = kwargs.get("width")
            if width:
                outline = width <= ICON_OUTLINE_LIMIT * self._box
                grow = ICON_LINE_WEIGHT if outline else ICON_STROKE_WEIGHT
                kwargs["width"] = max(1, int(round(width * grow)))
            return method(*args, **kwargs)

        return weighted



def _icon_photo(painter, size=ICON_SIZE):
    """Paint a small icon through `painter(draw, box)` and hand it to Tk.

    `box` is the size of the big picture it is painted on; it is shrunk to
    `size` afterwards, so everything drawn comes out with smooth edges.
    Without Pillow there is no picture at all and the button keeps its text.
    """
    if Image is None or ImageTk is None or ImageDraw is None:
        return None
    box = size * ICON_SCALE
    picture = Image.new("RGBA", (box, box), (0, 0, 0, 0))
    try:
        painter(_WeightedDraw(ImageDraw.Draw(picture), box), box)
        picture = picture.resize((size, size), Image.Resampling.LANCZOS)
        photo = ImageTk.PhotoImage(picture)
        photo.source = picture          # the painting behind the Tk picture
        return photo
    except (OSError, ValueError, TypeError, AttributeError):
        return None


def _bar(draw, box, x0, y0, x1, y1, fill, outline=None, width=None, radius=0):
    """A rectangle in fractions of the icon (0 = left / top, 1 = right)."""
    shape = [x0 * box, y0 * box, x1 * box, y1 * box]
    line = max(1, int(round((width if width is not None else 0.035) * box)))
    if radius:
        draw.rounded_rectangle(shape, radius=radius * box, fill=fill,
                               outline=outline, width=line if outline else 0)
    else:
        draw.rectangle(shape, fill=fill, outline=outline,
                       width=line if outline else 0)
    return shape


def _path(draw, box, points, color=ICON_INK, width=0.09):
    draw.line([(x * box, y * box) for x, y in points], fill=color,
              width=max(1, int(round(width * box))), joint="curve")


def _dots(draw, box, points, color=ICON_BLUE, radius=0.1, outline=ICON_INK):
    for x, y in points:
        r = radius * box
        draw.ellipse([x * box - r, y * box - r, x * box + r, y * box + r],
                     fill=color, outline=outline,
                     width=max(1, int(round(0.022 * box))))


# -- the nine plot styles ---------------------------------------------------
# every one of them is a tiny picture of the diagram it draws
_CURVE = [(0.12, 0.78), (0.34, 0.44), (0.56, 0.60), (0.80, 0.20)]


def _paint_line(draw, box):
    _path(draw, box, _CURVE, ICON_STROKE, 0.11)


def _paint_line_symbol(draw, box):
    _path(draw, box, _CURVE, ICON_STROKE, 0.085)
    _dots(draw, box, _CURVE, ICON_BLUE, 0.11, ICON_STROKE)


def _paint_scatter(draw, box):
    _dots(draw, box, [(0.18, 0.74), (0.40, 0.32), (0.62, 0.64),
                      (0.82, 0.22)], ICON_BLUE, 0.125, ICON_STROKE)


def _paint_bar(draw, box):
    for x, top, color in ((0.14, 0.52, ICON_BLUE), (0.40, 0.26, ICON_SAGE),
                          (0.66, 0.62, ICON_SAND)):
        _bar(draw, box, x, top, x + 0.20, 0.86, color, ICON_INK, 0.028)


def _paint_histogram(draw, box):
    for x, top, color in ((0.10, 0.60, ICON_BLUE), (0.32, 0.30, ICON_BLUE),
                          (0.54, 0.42, ICON_BLUE), (0.76, 0.70, ICON_BLUE)):
        _bar(draw, box, x, top, x + 0.22, 0.86, color, ICON_INK, 0.026)


def _paint_errorbar(draw, box):
    for x, y, span in ((0.24, 0.62, 0.22), (0.50, 0.40, 0.26),
                       (0.76, 0.52, 0.18)):
        _path(draw, box, [(x, y - span), (x, y + span)], ICON_INK, 0.05)
        _path(draw, box, [(x - 0.09, y - span), (x + 0.09, y - span)],
              ICON_INK, 0.05)
        _path(draw, box, [(x - 0.09, y + span), (x + 0.09, y + span)],
              ICON_INK, 0.05)
    _dots(draw, box, [(0.24, 0.62), (0.50, 0.40), (0.76, 0.52)],
          ICON_BLUE, 0.10)


def _paint_errorbar_pm(draw, box):
    """The same points, with the bar longer downwards than upwards."""
    for x, y, up, down in ((0.24, 0.62, 0.12, 0.28), (0.50, 0.42, 0.10, 0.24),
                           (0.76, 0.54, 0.09, 0.22)):
        _path(draw, box, [(x, y - down), (x, y + up)], ICON_INK, 0.05)
        _path(draw, box, [(x - 0.09, y - down), (x + 0.09, y - down)],
              ICON_INK, 0.05)
        _path(draw, box, [(x - 0.09, y + up), (x + 0.09, y + up)],
              ICON_INK, 0.05)
    _dots(draw, box, [(0.24, 0.62), (0.50, 0.42), (0.76, 0.54)],
          ICON_BLUE, 0.10)


def _paint_stairs(draw, box):
    _path(draw, box, [(0.10, 0.78), (0.34, 0.78), (0.34, 0.48),
                      (0.58, 0.48), (0.58, 0.64), (0.84, 0.64),
                      (0.84, 0.20)], ICON_STROKE, 0.105)


def _paint_hist2d(draw, box):
    shades = ((ICON_MUTED, ICON_BLUE, ICON_MUTED),
              (ICON_BLUE, ICON_LILAC, ICON_SAGE),
              (ICON_MUTED, ICON_SAGE, ICON_MUTED))
    for row in range(3):
        for column in range(3):
            x = 0.14 + column * 0.245
            y = 0.14 + row * 0.245
            _bar(draw, box, x, y, x + 0.225, y + 0.225, shades[row][column],
                 ICON_PAPER, 0.02)


def _paint_pie(draw, box):
    low, high = 0.11 * box, 0.89 * box
    draw.pieslice([low, low, high, high], 0, 360, fill=ICON_BLUE,
                  outline=ICON_INK, width=max(1, int(round(0.03 * box))))
    draw.pieslice([low, low, high, high], -108, -18, fill=ICON_SAND,
                  outline=ICON_INK, width=max(1, int(round(0.03 * box))))
    draw.pieslice([low, low, high, high], -18, 62, fill=ICON_ROSE,
                  outline=ICON_INK, width=max(1, int(round(0.03 * box))))


PLOT_ICON_PAINTERS = {
    "line_symbol": _paint_line_symbol,
    "line": _paint_line,
    "scatter": _paint_scatter,
    "bar": _paint_bar,
    "errorbar": _paint_errorbar,
    "errorbar_pm": _paint_errorbar_pm,
    "histogram": _paint_histogram,
    "stairs": _paint_stairs,
    "hist2d": _paint_hist2d,
    "pie": _paint_pie,
}


def plot_style_icon(style, size=ICON_SIZE):
    """A little picture of the diagram one plot style draws."""
    painter = PLOT_ICON_PAINTERS.get(str(style), _paint_line_symbol)
    return _icon_photo(painter, size)


# -- the two file tools, in the same shades ---------------------------------

def _paint_open(draw, box):
    """An open folder: the data file that is read."""
    _bar(draw, box, 0.07, 0.22, 0.50, 0.34, ICON_SAND, ICON_EDGE, 0.022,
         radius=0.05)
    _bar(draw, box, 0.07, 0.28, 0.93, 0.82, ICON_SAND, ICON_EDGE, 0.026,
         radius=0.06)
    draw.polygon([(0.17 * box, 0.44 * box), (1.03 * box, 0.44 * box),
                  (0.85 * box, 0.84 * box), (0.02 * box, 0.84 * box)],
                 fill=ICON_PAPER, outline=ICON_EDGE,
                 width=max(1, int(round(0.026 * box))))


def _paint_save(draw, box):
    """A floppy disk: the data file that is written."""
    _bar(draw, box, 0.08, 0.08, 0.92, 0.92, ICON_BLUE, ICON_STROKE, 0.028,
         radius=0.09)
    _bar(draw, box, 0.28, 0.10, 0.72, 0.40, ICON_PAPER, ICON_STROKE, 0.022,
         radius=0.03)
    _bar(draw, box, 0.55, 0.14, 0.66, 0.34, ICON_MUTED, None, 0)
    _bar(draw, box, 0.22, 0.54, 0.78, 0.90, ICON_PAPER, ICON_STROKE, 0.022,
         radius=0.03)


def _paint_import(draw, box):
    """A data file flowing into the sheet: an arrow pointing into paper."""
    _bar(draw, box, 0.40, 0.05, 0.98, 0.95, ICON_PAPER, ICON_EDGE, 0.026,
         radius=0.07)
    for index in range(4):              # the lines of numbers on the sheet
        y = 0.19 + index * 0.185
        _bar(draw, box, 0.50, y, 0.90, y + 0.09, ICON_MUTED, None, 0,
             radius=0.02)
    width = max(1, int(round(0.024 * box)))
    _bar(draw, box, 0.02, 0.42, 0.26, 0.58, ICON_ADD_COLOR, ICON_ADD_EDGE,
         0.024, radius=0.03)
    draw.polygon([(0.20 * box, 0.26 * box), (0.20 * box, 0.74 * box),
                  (0.50 * box, 0.50 * box)],
                 fill=ICON_ADD_COLOR, outline=ICON_ADD_EDGE, width=width)


FILE_ICON_PAINTERS = {"open": _paint_open, "save": _paint_save,
                      "import": _paint_import}


# -- the tools of a diagram window, in the very same shades ----------------

def _paint_home(draw, box):
    """A little house: the whole diagram, back as it was."""
    width = max(1, int(round(0.03 * box)))
    draw.polygon([(0.50 * box, 0.08 * box), (0.97 * box, 0.50 * box),
                  (0.03 * box, 0.50 * box)],
                 fill=ICON_ADD_COLOR, outline=ICON_ADD_EDGE, width=width)
    _bar(draw, box, 0.18, 0.46, 0.82, 0.93, ICON_PAPER, ICON_EDGE, 0.028,
         radius=0.05)
    _bar(draw, box, 0.41, 0.64, 0.59, 0.93, ICON_MUTED, ICON_EDGE, 0.022)


def _paint_step(draw, box, forward=True):
    """One step back or forward through the views that were looked at."""
    width = max(1, int(round(0.026 * box)))
    if forward:
        _bar(draw, box, 0.10, 0.41, 0.56, 0.59, ICON_ADD_COLOR, ICON_ADD_EDGE,
             0.026, radius=0.04)
        points = [(0.94, 0.50), (0.50, 0.20), (0.50, 0.80)]
    else:
        _bar(draw, box, 0.44, 0.41, 0.90, 0.59, ICON_ADD_COLOR, ICON_ADD_EDGE,
             0.026, radius=0.04)
        points = [(0.06, 0.50), (0.50, 0.20), (0.50, 0.80)]
    draw.polygon([(x * box, y * box) for x, y in points],
                 fill=ICON_ADD_COLOR, outline=ICON_ADD_EDGE, width=width)


def _paint_back(draw, box):
    _paint_step(draw, box, forward=False)


def _paint_forward(draw, box):
    _paint_step(draw, box, forward=True)


def _paint_pan(draw, box):
    """Four arrows out of one point: the diagram is pushed about."""
    width = max(1, int(round(0.026 * box)))
    _bar(draw, box, 0.42, 0.20, 0.58, 0.80, ICON_ADD_COLOR, ICON_ADD_EDGE, 0.024)
    _bar(draw, box, 0.20, 0.42, 0.80, 0.58, ICON_ADD_COLOR, ICON_ADD_EDGE, 0.024)
    for points in (((0.50, 0.03), (0.30, 0.25), (0.70, 0.25)),
                   ((0.50, 0.97), (0.30, 0.75), (0.70, 0.75)),
                   ((0.03, 0.50), (0.25, 0.30), (0.25, 0.70)),
                   ((0.97, 0.50), (0.75, 0.30), (0.75, 0.70))):
        draw.polygon([(x * box, y * box) for x, y in points],
                     fill=ICON_ADD_COLOR, outline=ICON_ADD_EDGE, width=width)


def _paint_zoom(draw, box):
    """A magnifier: a piece of the diagram is pulled closer."""
    draw.line([(0.56 * box, 0.56 * box), (0.92 * box, 0.92 * box)],
              fill=ICON_EDGE, width=max(2, int(round(0.14 * box))))
    draw.ellipse([0.06 * box, 0.06 * box, 0.70 * box, 0.70 * box],
                 fill=ICON_BLUE, outline=ICON_ADD_EDGE,
                 width=max(1, int(round(0.055 * box))))
    draw.ellipse([0.17 * box, 0.17 * box, 0.59 * box, 0.59 * box],
                 fill=ICON_PAPER)


def _paint_subplots(draw, box):
    """The plot area and its two handles: where it sits on the paper."""
    _bar(draw, box, 0.04, 0.04, 0.96, 0.96, ICON_PAPER, ICON_EDGE, 0.028,
         radius=0.07)
    _bar(draw, box, 0.30, 0.16, 0.86, 0.68, ICON_BLUE, ICON_ADD_EDGE, 0.026,
         radius=0.04)
    _bar(draw, box, 0.10, 0.16, 0.20, 0.68, ICON_MUTED, ICON_EDGE, 0.022,
         radius=0.03)
    _bar(draw, box, 0.30, 0.78, 0.86, 0.90, ICON_MUTED, ICON_EDGE, 0.022,
         radius=0.03)


def _paint_text_tool(draw, box):
    """A sheet with a T on it: a text box is placed on the diagram."""
    _bar(draw, box, 0.06, 0.08, 0.94, 0.92, ICON_PAPER, ICON_EDGE, 0.028,
         radius=0.08)
    _bar(draw, box, 0.20, 0.22, 0.80, 0.36, ICON_ADD_COLOR, ICON_ADD_EDGE,
         0.024, radius=0.03)
    _bar(draw, box, 0.43, 0.30, 0.57, 0.80, ICON_ADD_COLOR, ICON_ADD_EDGE,
         0.024, radius=0.03)




def _paint_picture(draw, box):
    """A framed picture: two hills and a sun, as small as it goes."""
    _bar(draw, box, 0.06, 0.14, 0.94, 0.86, ICON_PAPER, ICON_EDGE, 0.03,
         radius=0.07)
    draw.ellipse([0.20 * box, 0.26 * box, 0.36 * box, 0.42 * box],
                 fill=ICON_SAND, outline=ICON_EDGE,
                 width=max(1, int(round(0.02 * box))))
    draw.polygon([(0.10 * box, 0.80 * box), (0.40 * box, 0.46 * box),
                  (0.64 * box, 0.80 * box)], fill=ICON_SAGE)
    draw.polygon([(0.46 * box, 0.80 * box), (0.68 * box, 0.54 * box),
                  (0.90 * box, 0.80 * box)], fill=ICON_BLUE)
    _bar(draw, box, 0.06, 0.14, 0.94, 0.86, None, ICON_EDGE, 0.03, radius=0.07)


def picture_tool_icon(size=ICON_SIZE):
    """The icon of the "insert picture" button of a diagram window."""
    return _icon_photo(_paint_picture, size)


PLOT_TOOL_PAINTERS = {
    "home": _paint_home, "back": _paint_back, "forward": _paint_forward,
    "pan": _paint_pan, "zoom": _paint_zoom, "subplots": _paint_subplots,
    "save": _paint_save, "text": _paint_text_tool,
    "picture": _paint_picture,
}
# the names matplotlib gives its own buttons, and the icons that replace them
TOOLBAR_ICONS = {"Home": "home", "Back": "back", "Forward": "forward",
                 "Pan": "pan", "Zoom": "zoom", "Subplots": "subplots",
                 "Save": "save"}


def plot_tool_icon(name, size=ICON_SIZE, armed=False):
    """One tool icon of a diagram window, or None without Pillow.

    `armed` paints the light plate behind it that says the tool is waiting
    for a click in the diagram.
    """
    painter = PLOT_TOOL_PAINTERS.get(str(name))
    if painter is None:
        return None
    if not armed:
        return _icon_photo(painter, size)

    def lit(draw, box):
        _bar(draw, box, 0.0, 0.0, 1.0, 1.0, ICON_ARMED, ICON_ADD_EDGE, 0.03,
             radius=0.18)
        painter(draw, box)

    return _icon_photo(lit, size)


# -- the drawings and the arrow heads, as their split buttons list them ----

def _paint_shape(kind):
    """The painter of one drawing object: its outline, with a light fill."""
    def paint(draw, box):
        width = max(1, int(round(0.07 * box)))
        low, high = 0.14 * box, 0.86 * box
        if kind == "triangle":
            draw.polygon([(0.5 * box, low), (high, high), (low, high)],
                         fill=ICON_BLUE, outline=ICON_ADD_EDGE, width=width)
        elif kind == "circle":
            draw.ellipse([low, low, high, high], fill=ICON_BLUE,
                         outline=ICON_ADD_EDGE, width=width)
        elif kind == "ellipse":
            draw.ellipse([0.06 * box, 0.26 * box, 0.94 * box, 0.74 * box],
                         fill=ICON_BLUE, outline=ICON_ADD_EDGE, width=width)
        elif kind == "line":
            draw.line([(low, high), (high, low)], fill=ICON_ADD_EDGE,
                      width=max(1, int(round(0.10 * box))))
        else:                                       # a rectangle
            draw.rectangle([0.08 * box, 0.22 * box, 0.92 * box, 0.78 * box],
                           fill=ICON_BLUE, outline=ICON_ADD_EDGE, width=width)
    return paint


def _paint_arrow_head(head):
    """A right pointing arrow whose head is the one of the list.

    The head has the very shape the diagram draws (see `_head_polygon`),
    only a little taller, so that the four kinds are told apart at a
    glance even this small.
    """
    def paint(draw, box):
        middle = 0.5 * box
        tip = 0.95 * box
        size = 0.50 * box
        half = size * 0.55
        base = tip - size
        left, right = (base, middle - half), (base, middle + half)
        line = max(1, int(round(0.09 * box)))
        if head == "chevron":
            draw.line([(0.05 * box, middle), (tip - 0.05 * box, middle)],
                      fill=ICON_ADD_EDGE, width=line)
            draw.line([left, (tip, middle), right], fill=ICON_ADD_EDGE,
                      width=line, joint="curve")
            return
        draw.line([(0.05 * box, middle), (base + size * 0.15, middle)],
                  fill=ICON_ADD_EDGE, width=line)
        if head == "concave":
            points = [(tip, middle), left, (base + size * 0.35, middle), right]
        elif head == "convex":
            points = [(tip, middle), left, (base - size * 0.22, middle), right]
        else:                                        # a plain triangle
            points = [(tip, middle), left, right]
        draw.polygon(points, fill=ICON_ADD_EDGE, outline=ICON_ADD_EDGE,
                     width=max(1, int(round(0.03 * box))))
    return paint


def shape_tool_icon(kind, size=ICON_SIZE):
    """The little picture of one drawing object (rectangle, circle, line...)."""
    return _icon_photo(_paint_shape(str(kind)), size)


def arrow_head_icon(head, size=ICON_SIZE):
    """The little picture of an arrow with one kind of head."""
    return _icon_photo(_paint_arrow_head(str(head)), size)


def popup_icon_menu(master, entries, where):
    """A popup list whose lines carry a little picture beside the name.

    `entries` is a list of (label, picture, command); a line without a
    picture (no Pillow) keeps just its name.  The pictures are kept on the
    menu itself, or Tk would let them go while the list is open.
    """
    menu = tk.Menu(master, tearoff=0)
    menu._pictures = []
    for label, picture, command in entries:
        if picture is not None:
            menu._pictures.append(picture)
            menu.add_command(label=label, image=picture,
                             compound="left", command=command)
        else:
            menu.add_command(label=label, command=command)
    if where is not None:
        try:
            menu.tk_popup(*where)
        finally:
            menu.grab_release()
    return menu


def file_tool_icon(name, size=ICON_SIZE):
    """The icon of the "open data file" / "save data file" buttons."""
    painter = FILE_ICON_PAINTERS.get(str(name))
    return _icon_photo(painter, size) if painter else None


# -- the four row and column tools ------------------------------------------

def _badge(draw, box, action, center=(0.79, 0.79), radius=0.20):
    """The small `+` or `-` that says whether something comes or goes."""
    fill = ICON_ADD_COLOR if action == "add" else ICON_DELETE_COLOR
    edge = ICON_ADD_EDGE if action == "add" else ICON_DELETE_EDGE
    x, y = center[0] * box, center[1] * box
    r = radius * box
    draw.ellipse([x - r, y - r, x + r, y + r], fill=fill, outline=edge,
                 width=max(1, int(round(0.03 * box))))
    arm = r * 0.52
    thick = max(1, int(round(0.045 * box)))
    draw.line([x - arm, y, x + arm, y], fill="#ffffff", width=thick)
    if action == "add":
        draw.line([x, y - arm, x, y + arm], fill="#ffffff", width=thick)


def _band_places(action, where):
    """Which of the three bands is painted, and whether it stands apart.

    The picture says where the new row or column will appear: at the near
    end, at the far end, or - standing apart from the other two - at the
    very end of the whole sheet.
    """
    if action != "add":
        return 1, False                     # the middle one goes away
    place = str(where or "below")
    if place in ("above", "before"):
        return 0, False
    if place == "end":
        return 2, True
    return 2, False


def drawn_tool_icon(kind, action, size=ICON_SIZE, where=None):
    """A sheet of three bands: the painted one is what the button does.

    Lying down for the rows, standing up for the columns.  A blue
    band is the row or column that appears, a red one is the one
    that is taken away, and the others are grey.
    """
    painted, apart = _band_places(action, where)
    color = ICON_ADD_COLOR if action == "add" else ICON_DELETE_COLOR
    edge = ICON_ADD_EDGE if action == "add" else ICON_DELETE_EDGE

    def painter(draw, box):
        # the sheet, with its bottom right corner left free for the badge
        _bar(draw, box, 0.04, 0.04, 0.80, 0.80, ICON_PAPER, ICON_EDGE,
             0.026, radius=0.09)
        thick, gap = 0.165, 0.055
        first = 0.105
        for index in range(3):
            start = first + index * (thick + gap)
            if apart and index == 2:
                start += 0.055          # the far end of the whole sheet
            end = start + thick
            fill = color if index == painted else ICON_MUTED
            line = edge if index == painted else ICON_EDGE
            if kind == "row":
                _bar(draw, box, 0.11, start, 0.73, end, fill, line, 0.02,
                     radius=0.03)
            else:
                _bar(draw, box, start, 0.11, end, 0.73, fill, line, 0.02,
                     radius=0.03)
        _badge(draw, box, action, center=(0.755, 0.755), radius=0.225)

    return _icon_photo(painter, size)


# --------------------------------------------------------------------------
# the row of sheet tabs under the spreadsheet
# --------------------------------------------------------------------------

TAB_BAR_HEIGHT = 26          # the height of the row of tabs, in pixels
TAB_PAD = 12                 # the room left and right of a tab's name
TAB_SCROLL_STEP = 80         # how far one click on an arrow scrolls, pixels
TAB_GAP = 2                  # the free room between two tabs
TAB_DRAG_START = 6           # pixels the pointer moves before a tab is dragged
TAB_DROP_MARK = "#2f80d9"    # the line that shows where a dragged tab lands
# the tabs wear the dark grey of the buttons of the toolbar (as macOS draws
# them) with light writing; the one in front is a shade lighter and bold
TAB_FACE = "#56565a"         # a tab that is not in front
TAB_FACE_ACTIVE = "#737378"  # ... and the one that is
TAB_HOVER = "#636368"        # a tab under the pointer
TAB_EDGE = "#3c3c3f"         # the thin line around them
TAB_TEXT = "#e4e4e7"         # the name on a tab
TAB_TEXT_ACTIVE = "#ffffff"  # ... and on the one in front


class SheetNotebook(ttk.Notebook):
    """A notebook that says when its tabs change.

    It holds the sheets and knows which one is in front, as a notebook
    does; its own row of tabs is not drawn (see `SheetTabBar`), so every
    change of a tab - a new one, a new name, a colour, another one in front
    - is announced to the row that is drawn instead.
    """

    def __init__(self, master, on_tabs=None, **options):
        super().__init__(master, **options)
        self._on_tabs = on_tabs

    def _changed(self):
        if self._on_tabs is not None:
            try:
                self._on_tabs()
            except tk.TclError:
                pass

    def add(self, child, **options):
        done = super().add(child, **options)
        self._changed()
        return done

    def insert(self, pos, child, **options):
        done = super().insert(pos, child, **options)
        self._changed()
        return done

    def forget(self, tab_id):
        done = super().forget(tab_id)
        self._changed()
        return done

    def tab(self, tab_id, option=None, **options):
        done = super().tab(tab_id, option, **options)
        if options:
            self._changed()
        return done

    def select(self, tab_id=None):
        done = super().select(tab_id)
        if tab_id is not None:
            self._changed()
        return done


class TabEvent:
    """A pointer event of the tab row, told in the row's own pixels."""

    def __init__(self, x, y, x_root=0, y_root=0):
        self.x, self.y = int(x), int(y)
        self.x_root, self.y_root = int(x_root), int(y_root)


class SheetTabBar(ttk.Frame):
    """The tabs of the sheets: one row that scrolls when it is too long.

    A notebook of Tk wraps nothing and scrolls nothing - once its tabs are
    wider than the window the last ones, and the `+` after them, simply
    slide out of sight.  This row is drawn instead.  When the tabs fit, the
    `+` stands right after the last one; when they do not, the row scrolls
    and two arrows appear at its right end, with the `+` beside them, so it
    never leaves the window.  The wheel (or a sideways swipe) over the row
    scrolls it as well, and the tab that comes to the front is always
    brought into view.

    Everything else - which sheet a tab stands for, its name and colour,
    what a click does - belongs to the program (`handlers`); the row only
    draws and tells where the pointer is.
    """

    def __init__(self, master, notebook, names, colors, plus_frame=None,
                 handlers=None):
        super().__init__(master)
        self.notebook = notebook
        self._names = names          # () -> the names of the sheets
        self._colors = colors        # (index) -> a colour or None
        self.plus_frame = plus_frame
        self.handlers = dict(handlers or {})
        self._spans = []             # (left, right) of every tab, canvas x
        self._hover = None
        self._tab_drag = None        # a tab being carried to another place
        self._pending = None
        self._shown = None           # the tab that was in front last time
        background = self._background(master)
        self.canvas = tk.Canvas(self, height=TAB_BAR_HEIGHT, width=40,
                                highlightthickness=0, borderwidth=0,
                                background=background, xscrollincrement=1)
        self.canvas.grid(row=0, column=0, sticky="w")
        font = tkfont.nametofont("TkDefaultFont")
        self.font = font
        self.bold = font.copy()
        self.bold.configure(weight="bold")
        self.arrow_font = font.copy()     # the two arrows: large and clear
        self.arrow_font.configure(size=max(8, int(abs(font.cget("size")) * 0.85)))
        self.arrows = ttk.Frame(self)
        self.left_button = tk.Button(
            self.arrows, text="\u25c0", width=2, relief="flat",
            borderwidth=0, highlightthickness=0, repeatdelay=350,
            repeatinterval=60, command=lambda: self.scroll_by(-TAB_SCROLL_STEP))
        self.right_button = tk.Button(
            self.arrows, text="\u25b6", width=2, relief="flat",
            borderwidth=0, highlightthickness=0, repeatdelay=350,
            repeatinterval=60, command=lambda: self.scroll_by(TAB_SCROLL_STEP))
        self.left_button.pack(side="left")
        self.right_button.pack(side="left")
        self.plus_button = ttk.Button(self, text="+", width=2,
                                      style="Toolbutton",
                                      command=self._plus_clicked)
        self.plus_button.grid(row=0, column=2, sticky="w", padx=(4, 0))
        self.columnconfigure(3, weight=1)
        for button in (self.left_button, self.right_button):
            button.configure(font=self.arrow_font, foreground=ICON_EDGE,
                             disabledforeground=ICON_MUTED)

        canvas = self.canvas
        canvas.bind("<ButtonPress-1>", self._pressed)
        canvas.bind("<B1-Motion>", self._dragged)
        canvas.bind("<ButtonRelease-1>", self._released)
        canvas.bind("<Double-Button-1>", self._double)
        for sequence in ("<Button-2>", "<Button-3>"):
            canvas.bind(sequence, self._menu)
        if sys.platform == "darwin":        # Control and the one button
            canvas.bind("<Control-Button-1>", self._menu)
        canvas.bind("<Motion>", self._moved)
        canvas.bind("<Leave>", lambda _e: self._hover_on(None))
        for widget in (canvas, self, self.plus_button, self.left_button,
                       self.right_button):
            for sequence in ("<MouseWheel>", "<Shift-MouseWheel>"):
                widget.bind(sequence, self._wheel, add="+")
            widget.bind("<Button-4>", lambda _e: self.scroll_by(-40), add="+")
            widget.bind("<Button-5>", lambda _e: self.scroll_by(40), add="+")
        self.bind("<Configure>", lambda _e: self._fit())
        self.refresh()

    @staticmethod
    def _background(master):
        try:
            return str(master.winfo_toplevel().cget("background"))
        except (tk.TclError, AttributeError):
            return "#ececec"

    # -- drawing -----------------------------------------------------------
    def refresh(self, later=True):
        """Draw the row again (soon, once, however often it is asked)."""
        if not later:
            if self._pending is not None:
                try:
                    self.after_cancel(self._pending)
                except tk.TclError:
                    pass
                self._pending = None
            return self._draw()
        if self._pending is None:
            try:
                self._pending = self.after_idle(self._redraw_now)
            except tk.TclError:
                self._pending = None
        return None

    def _redraw_now(self):
        self._pending = None
        try:
            self._draw()
        except tk.TclError:
            pass

    def flush(self):
        """Draw now if a drawing is waiting - before anything is measured."""
        if self._pending is not None:
            self.refresh(later=False)

    def selected(self):
        try:
            return int(self.notebook.index("current"))
        except (tk.TclError, ValueError):
            return 0

    def _draw(self):
        canvas = self.canvas
        canvas.delete("all")
        names = list(self._names())
        current = self.selected()
        height = TAB_BAR_HEIGHT
        spans, x = [], 0
        for index, name in enumerate(names):
            font = self.bold if index == current else self.font
            color = self._colors(index)
            width = font.measure(str(name)) + 2 * TAB_PAD
            if color:
                width += 18
            spans.append((x, x + width))
            x += width + TAB_GAP        # flat tabs, a little apart
        total = max(1, x - TAB_GAP)
        self._spans = spans
        for index, (name, (left, right)) in enumerate(zip(names, spans)):
            front = index == current
            face = (TAB_FACE_ACTIVE if front else
                    TAB_HOVER if index == self._hover else TAB_FACE)
            canvas.create_rectangle(left, 1, right - 1, height - 3, fill=face,
                                    outline=TAB_EDGE if front else face,
                                    tags=(f"tab{index}",))
            text_x = left + TAB_PAD
            color = self._colors(index)
            if color:
                canvas.create_rectangle(text_x, (height - 3) / 2 - 6,
                                        text_x + 12, (height - 3) / 2 + 6,
                                        fill=color, outline=TAB_TEXT,
                                        tags=(f"tab{index}",))
                text_x += 18
            canvas.create_text(text_x, (height - 3) / 2, anchor="w",
                               text=str(name),
                               fill=TAB_TEXT_ACTIVE if front else TAB_TEXT,
                               font=self.bold if front else self.font,
                               tags=(f"tab{index}",))
        canvas.configure(scrollregion=(0, 0, total, height))
        self._total = total
        self._fit()
        if current != self._shown:
            self._shown = current
            self.see(current)
        return spans

    def _fit(self):
        """The canvas as wide as the tabs, or as the room there is.

        When everything fits the `+` stands right after the last tab; when
        it does not, the arrows come in and the tabs scroll.
        """
        try:
            room = int(self.winfo_width())
        except tk.TclError:
            return False
        if room <= 1:
            room = int(self.winfo_reqwidth()) or 400
        total = getattr(self, "_total", 1)
        plus = max(24, int(self.plus_button.winfo_reqwidth())) + 4
        arrows = max(40, int(self.arrows.winfo_reqwidth()))
        overflow = total > room - plus
        if overflow:
            width = max(40, room - plus - arrows - 2)
            if not self.arrows.winfo_ismapped():
                self.arrows.grid(row=0, column=1, sticky="w", padx=(2, 0))
        else:
            width = total
            if self.arrows.winfo_manager():
                self.arrows.grid_remove()
        if int(self.canvas.cget("width")) != width:
            self.canvas.configure(width=width)
        self.overflow = overflow
        self._clamp()
        self._arrow_states()
        return overflow

    # -- scrolling ---------------------------------------------------------
    def view_width(self):
        return max(1, int(self.canvas.cget("width")))

    def offset(self):
        """How far the row is scrolled, in pixels."""
        return int(round(self.canvas.canvasx(0)))

    def scroll_to(self, left):
        total = getattr(self, "_total", 1)
        left = max(0, min(int(left), max(0, total - self.view_width())))
        self.canvas.xview_moveto(left / float(max(1, total)))
        self._arrow_states()
        return left

    def scroll_by(self, pixels):
        return self.scroll_to(self.offset() + int(pixels))

    def _clamp(self):
        self.scroll_to(self.offset())

    def see(self, index):
        """Scroll so that the whole tab `index` is in view."""
        if not (0 <= index < len(self._spans)):
            return False
        left, right = self._spans[index]
        start, width = self.offset(), self.view_width()
        if left < start:
            self.scroll_to(left)
        elif right > start + width:
            self.scroll_to(right - width + 1)
        return True

    def _arrow_states(self):
        start = self.offset()
        end = start + self.view_width()
        total = getattr(self, "_total", 1)
        try:
            self.left_button.configure(state="normal" if start > 0 else "disabled")
            self.right_button.configure(
                state="normal" if end < total else "disabled")
        except tk.TclError:
            pass

    def _wheel(self, event):
        delta = int(getattr(event, "delta", 0) or 0)
        if not delta:
            return "break"
        # Windows counts a notch as 120, macOS in small steps
        pixels = delta / 3.0 if abs(delta) >= 120 else delta * 8
        self.scroll_by(-pixels)
        return "break"

    # -- where the pointer is ----------------------------------------------
    def plus_index(self):
        if self.plus_frame is None:
            return None
        try:
            return int(self.notebook.index(self.plus_frame))
        except (tk.TclError, ValueError):
            return None

    def tab_at(self, x, y):
        """The number of the tab at a point of the row, or None.

        The `+` counts as the tab it stands for in the notebook.
        """
        self.flush()
        if not (-2 <= y <= TAB_BAR_HEIGHT + 2):
            return None
        plus = self.plus_button
        if plus.winfo_ismapped():
            px, pw = plus.winfo_x(), plus.winfo_width()
            if px <= x < px + max(pw, 1):
                return self.plus_index()
        cx0, cw = self.canvas.winfo_x(), self.view_width()
        if not (cx0 <= x < cx0 + cw):
            return None
        inside = x - cx0 + self.offset()
        for index, (left, right) in enumerate(self._spans):
            if left <= inside < right:
                return index
        return None

    def tab_box(self, index):
        """(x, y, width, height) of one tab in the row, scrolled into view."""
        self.flush()
        self.update_idletasks()
        if index is not None and index == self.plus_index():
            plus = self.plus_button
            return (plus.winfo_x(), plus.winfo_y(),
                    max(16, plus.winfo_width()), max(16, plus.winfo_height()))
        if not (0 <= int(index) < len(self._spans)):
            return None
        self.see(int(index))
        left, right = self._spans[int(index)]
        x = self.canvas.winfo_x() + left - self.offset()
        return (x, self.canvas.winfo_y(), right - left, TAB_BAR_HEIGHT - 3)

    def _event(self, event):
        return TabEvent(event.x + self.canvas.winfo_x(),
                        event.y + self.canvas.winfo_y(),
                        getattr(event, "x_root", 0), getattr(event, "y_root", 0))

    def _call(self, name, event):
        handler = self.handlers.get(name)
        return handler(event) if handler else None

    def _pressed(self, event):
        here = self._event(event)
        index = self.tab_at(here.x, here.y)
        if index is not None and index != self.selected():
            self.notebook.select(index)
        plus = self.plus_index()
        self._tab_drag = (None if index is None or index == plus else
                          {"index": index, "x": here.x, "moving": False,
                           "target": index})
        return self._call("press", here)

    # -- carrying a tab to another place -----------------------------------
    def drop_place(self, x):
        """Where a tab dropped at `x` (pixels of the row) would stand.

        The answer is the number the tab gets once it is there; it is found
        from the middles of the other tabs, as in a web browser.
        """
        self.flush()
        drag = self._tab_drag or {}
        source = drag.get("index")
        inside = x - self.canvas.winfo_x() + self.offset()
        before = sum(1 for index, (left, right) in enumerate(self._spans)
                     if index != source and (left + right) / 2.0 < inside)
        return before

    def _dragged(self, event):
        drag = self._tab_drag
        if drag is None:
            return None
        here = self._event(event)
        if not drag["moving"]:
            if abs(here.x - drag["x"]) < TAB_DRAG_START:
                return None
            drag["moving"] = True
            try:
                self.canvas.configure(cursor="sb_h_double_arrow")
            except tk.TclError:
                pass
        # near an end of the row it scrolls, so a far place can be reached
        left_edge = self.canvas.winfo_x()
        right_edge = left_edge + self.view_width()
        if self.overflow:
            if here.x < left_edge + 18:
                self.scroll_by(-12)
            elif here.x > right_edge - 18:
                self.scroll_by(12)
        drag["target"] = self.drop_place(here.x)
        self._show_drop(drag["target"])
        return "break"

    def _show_drop(self, place):
        """A line in the gap where the tab would land."""
        canvas = self.canvas
        canvas.delete("drop")
        drag = self._tab_drag or {}
        others = [span for index, span in enumerate(self._spans)
                  if index != drag.get("index")]
        if not others:
            return None
        if place <= 0:
            x = others[0][0] - 1
        elif place >= len(others):
            x = others[-1][1] + 1
        else:
            x = (others[place - 1][1] + others[place][0]) / 2.0
        canvas.create_line(x, 0, x, TAB_BAR_HEIGHT - 2, fill=TAB_DROP_MARK,
                           width=3, tags="drop")
        return x

    def _end_drag(self):
        drag, self._tab_drag = self._tab_drag, None
        try:
            self.canvas.delete("drop")
            self.canvas.configure(cursor="")
        except tk.TclError:
            pass
        return drag

    def _released(self, event):
        drag = self._end_drag()
        if drag is not None and drag["moving"]:
            if drag["target"] != drag["index"]:
                self._call("move", (drag["index"], drag["target"]))
            return "break"           # a drag is not a click (no renaming)
        return self._call("click", self._event(event))

    def _double(self, event):
        return self._call("double", self._event(event))

    def _menu(self, event):
        self._call("menu", self._event(event))
        return "break"

    def _plus_clicked(self):
        return self._call("plus", None)

    def _moved(self, event):
        here = self._event(event)
        index = self.tab_at(here.x, here.y)
        if index == self.plus_index():
            index = None
        self._hover_on(index)

    def _hover_on(self, index):
        if index != self._hover:
            self._hover = index
            self.refresh()


class TableToolButton(ttk.Button):
    """Toolbar button of the spreadsheet."""
    def __init__(self, master, kind="row", action="add", where=None,
                 background=None, command=None, on_menu=None):
        self.kind = kind
        self.action = action
        self.split = on_menu is not None
        self.on_menu = on_menu

        self.where = where or ("below" if kind == "row" else "after")
        self.icon_img = drawn_tool_icon(kind, action, where=self.where)

        full_text = " \u23f7" if self.split else ""
        if self.icon_img is None:            # no Pillow: words instead
            full_text = ("Add " if action == "add" else "Delete ") + kind \
                + full_text
        super().__init__(master, text=full_text, image=self.icon_img,
                         compound="left", width=0, style=TOOLBAR_STYLE,
                         command=command)
        
        if self.split:
            self.bind("<ButtonPress-1>", self._clicked)
            
        self.tooltip = Tooltip(self, "")
        default = "below" if kind == "row" else "after"
        self.set_where(where or default)

    def _clicked(self, event):
        if event.x > self.winfo_width() - 20:
            if self.on_menu:
                self.on_menu(self)
            return "break"

    def set_where(self, where):
        """The place a new row or column goes - the icon shows it too."""
        self.where = where
        picture = drawn_tool_icon(self.kind, self.action, where=where)
        if picture is not None:
            self.icon_img = picture
            self.configure(image=picture)
        self.tooltip.set_text(self.describe())
        return picture

    def describe(self):
        """The words of the tooltip: what this button does."""
        if self.action == "delete":
            return "Delete row(s)" if self.kind == "row" else "Delete column"
        places = {"above": "above", "below": "below", "before": "before", "after": "after", "end": "at the end"}
        thing = "row" if self.kind == "row" else "column"
        text = f"Insert {thing} {places.get(self.where, '')}"
        if self.split:
            text += " (click arrow for options)"
        return text

# --------------------------------------------------------------------------
# pictures dropped into a diagram
# --------------------------------------------------------------------------

PICTURE_KIND = "image"          # a drawn object that carries a picture
PICTURE_MAX_SIDE = 1600         # a picture is kept no larger than this
PICTURE_START_WIDTH = 0.35      # how wide a new one is, as a part of the axes
PICTURE_SUFFIXES = (".png", ".jpg", ".jpeg", ".gif", ".bmp", ".tif", ".tiff",
                    ".webp", ".ppm", ".pgm")
PICTURE_PATTERNS = [("Pictures", " ".join("*" + one for one in PICTURE_SUFFIXES)),
                    ("All files", "*.*")]


def picture_file(path):
    """The name of a picture file, or None when it is something else."""
    try:
        name = Path(str(path).strip().strip('"').strip("'"))
    except (TypeError, ValueError):
        return None
    if name.suffix.lower() not in PICTURE_SUFFIXES:
        return None
    return name if name.is_file() else None


def open_picture(source):
    """A picture from a file, from bytes, or from a picture itself.

    Everything a drop, a paste or a file dialog can hand over ends up here,
    and what comes back is always a Pillow picture in RGBA - or None when
    there was no picture in it.
    """
    if Image is None or source is None:
        return None
    try:
        if isinstance(source, Image.Image):
            picture = source
        elif isinstance(source, (bytes, bytearray)):
            picture = Image.open(io.BytesIO(bytes(source)))
        elif isinstance(source, np.ndarray):
            values = np.asarray(source)
            if values.dtype != np.uint8:
                values = np.clip(values * 255.0, 0, 255).astype(np.uint8)
            picture = Image.fromarray(values)
        else:
            name = picture_file(source)
            if name is None:
                return None
            picture = Image.open(name)
        picture.load()
        return picture.convert("RGBA")
    except (OSError, ValueError, TypeError, AttributeError):
        return None


def picture_as_text(picture, max_side=PICTURE_MAX_SIDE):
    """One picture packed into a line of text, for the `.aplt` file.

    A photograph out of a camera is far bigger than any diagram needs, so
    it is made smaller first: the file stays a sensible size and the
    picture is still sharper than the screen.
    """
    picture = open_picture(picture)
    if picture is None:
        return None
    longest = max(picture.width, picture.height)
    if longest > int(max_side):
        scale = float(max_side) / float(longest)
        picture = picture.resize((max(1, int(picture.width * scale)),
                                  max(1, int(picture.height * scale))),
                                 Image.Resampling.LANCZOS)
    holder = io.BytesIO()
    picture.save(holder, format="PNG")
    return base64.b64encode(holder.getvalue()).decode("ascii")


PICTURE_SMALLEST = 48        # pixels: no smaller copy of a picture is made


def picture_levels(values):
    """The picture, then copies of it each half as large (a "mipmap").

    Drawing a picture of 300 dpi into a box a few hundred pixels wide
    makes matplotlib shrink millions of pixels on every drawing of the
    diagram - which is what made dragging slow.  From these copies the
    smallest one that is still at least as large as the box is shrunk
    instead: the same sharp result for a fraction of the work.
    """
    levels = [values]
    current = values
    while min(current.shape[0], current.shape[1]) >= 2 * PICTURE_SMALLEST:
        smaller = None
        if current.dtype == np.uint8 and (current.ndim == 2 or (
                current.ndim == 3 and current.shape[2] in (3, 4))):
            try:
                from PIL import Image
                smaller = np.asarray(Image.fromarray(current).reduce(2))
            except (ImportError, ValueError, TypeError, OSError):
                smaller = None
        if smaller is None:               # anything else: the mean of 2 x 2
            rows = current.shape[0] // 2 * 2
            cols = current.shape[1] // 2 * 2
            cut = current[:rows, :cols].astype(np.float64)
            smaller = ((cut[0::2, 0::2] + cut[1::2, 0::2]
                        + cut[0::2, 1::2] + cut[1::2, 1::2]) / 4.0
                       ).astype(current.dtype)
        levels.append(smaller)
        current = smaller
    return levels


class PictureImage(BboxImage):
    """A picture in its box, shrunk from the right copy of it.

    It draws exactly as a `BboxImage` of the whole picture does, but it
    first picks, from `picture_levels`, the smallest copy that still has
    at least as many pixels as the box it fills - on the screen at any
    zoom, and in an exported file at any resolution alike, since both
    say how many pixels they need.
    """

    def __init__(self, bbox, levels, **kwargs):
        super().__init__(bbox, **kwargs)
        self._levels = list(levels)
        self.set_data(self._levels[0])

    def level_for(self, width, height):
        """The copy to shrink into a box of `width` x `height` pixels."""
        chosen = self._levels[0]
        for level in self._levels:
            if level.shape[1] >= width and level.shape[0] >= height:
                chosen = level
            else:
                break
        return chosen

    def make_image(self, renderer, magnification=1.0, unsampled=False):
        width, height = renderer.get_canvas_width_height()
        bbox_in = self.get_window_extent(renderer).frozen()
        bbox_out = self.get_window_extent(renderer)
        needed = (abs(bbox_out.width) * magnification,
                  abs(bbox_out.height) * magnification)
        values = self.level_for(*needed)
        bbox_in._points /= [width, height]
        clip = Bbox([[0, 0], [width, height]])
        self._transform = BboxTransformTo(clip)
        return self._make_image(values, bbox_in, bbox_out, clip,
                                magnification, unsampled=unsampled)


def picture_from_text(text):
    """The picture of a `.aplt` file, as the numbers matplotlib draws."""
    if not text:
        return None
    try:
        raw = base64.b64decode(str(text), validate=False)
    except (ValueError, TypeError):
        return None
    picture = open_picture(raw)
    if picture is None:
        return None
    return np.asarray(picture, dtype=np.uint8)


def clipboard_picture(widget=None):
    """The picture on the clipboard, or None.

    Pillow reads the clipboard of macOS and of Windows itself (and of X11
    when `xclip` is there).  A file copied in the Finder arrives as a name
    instead of pixels, and X11 sometimes offers the picture as a PNG
    selection - both are taken as well.
    """
    grabbed = None
    try:
        from PIL import ImageGrab
        grabbed = ImageGrab.grabclipboard()
    except (ImportError, OSError, NotImplementedError, AttributeError):
        grabbed = None
    if isinstance(grabbed, list):            # names of files, not pixels
        for one in grabbed:
            picture = open_picture(one)
            if picture is not None:
                return picture
        grabbed = None
    picture = open_picture(grabbed)
    if picture is not None:
        return picture
    if widget is None:
        return None
    for flavour in ("image/png", "image/PNG", "PNG"):
        try:
            raw = widget.tk.call("clipboard", "get", "-type", flavour)
        except tk.TclError:
            continue
        if not raw:
            continue
        data = raw if isinstance(raw, (bytes, bytearray)) else \
            str(raw).encode("latin-1", "ignore")
        picture = open_picture(data)
        if picture is not None:
            return picture
    try:                                     # a file name as plain text
        return open_picture(widget.clipboard_get())
    except (tk.TclError, TypeError):
        return None


class QuietDraws:
    """Hold back the redrawing while a diagram is being rebuilt.

    Resizing the canvas makes matplotlib ask for a new drawing, and so
    does everything the program does afterwards - which would paint the
    whole diagram two or three times over for one turn of the wheel.  Used
    as `with QuietDraws(window):`, the asking is swallowed and one drawing
    is made at the end, where it belongs.
    """

    def __init__(self, window):
        self.window = window
        self.kept = None

    def __enter__(self):
        canvas = getattr(self.window, "canvas", None)
        if canvas is None:
            return self
        waiting = getattr(canvas, "_idle_draw_id", None)
        if waiting:                       # one was already on its way
            try:
                canvas._tkcanvas.after_cancel(waiting)
            except (AttributeError, tk.TclError):
                pass
            canvas._idle_draw_id = None
        self.kept = canvas.draw_idle
        canvas.draw_idle = lambda *_a, **_k: None
        self.window._quiet_draws = True
        return self

    def __exit__(self, *_error):
        canvas = getattr(self.window, "canvas", None)
        if canvas is not None and self.kept is not None:
            canvas.draw_idle = self.kept
        self.window._quiet_draws = False
        return False


class PointerSpot:
    """Where the pointer is, in the shape the handlers expect of an event."""

    __slots__ = ("x_root", "y_root")

    def __init__(self, x_root, y_root):
        self.x_root = float(x_root)
        self.y_root = float(y_root)


def e_power_text(value):
    """One number of a `Log (natural)` axis, written as a power of `e`.

    Such an axis is read in powers, not in numbers: `e^{2}` says what
    7.389 does not.  A tick that does not fall on a whole power keeps its
    exponent to two decimals.
    """
    try:
        value = float(value)
    except (TypeError, ValueError):
        return ""
    if value <= 0 or not np.isfinite(value):
        return ""
    power = math.log(value)
    whole = round(power)
    # `mathdefault` keeps the letters in the font of the rest of the axis,
    # the way matplotlib writes 10 to the power of something
    if abs(power - whole) < 1e-6:
        return "$\\mathdefault{e^{%d}}$" % int(whole)
    return "$\\mathdefault{e^{%.2f}}$" % power


class NaturalLogFormatter(Formatter):
    """Writes the numbers of a `Log (natural)` axis as e, e squared, ..."""

    def __call__(self, value, pos=None):
        return e_power_text(value)


def gestures_reach_tk():
    """Whether the system hands pinch gestures to Tk.  It does not.

    macOS sends a pinch to **Cocoa**, and Tk never sees it.  It can be
    picked up from Cocoa with pyobjc - and that is what an earlier version
    of this program did - but the callback then arrives from inside Tk's
    own event loop, where Python has released the interpreter lock: the
    program dies at once with

        Fatal Python error: PyEval_RestoreThread: the function must be
        called with the GIL held ... the GIL is released

    There is no way to make that safe while Tk runs the loop, so the
    gesture is not listened for at all.  What a trackpad *does* send to Tk
    is the wheel, so two fingers zoom by sliding them with `Ctrl`/`Cmd`
    held - and the toolbar has -, the zoom and + for the same thing.
    """
    return False


def clipboard_serial(widget=None):
    """A mark that changes whenever the clipboard of the system changes.

    It answers one question: *has another program put something on the
    clipboard since this program last copied?*  Stamps of time cannot
    answer it - a picture copied in PowerPoint or in a browser carries no
    time of its own - so what is compared is the clipboard itself.

    macOS keeps a counter for exactly this purpose (`changeCount` of the
    pasteboard, raised by every copy anywhere in the system); it is read
    when pyobjc is there, because it is quick and needs no picture.  Where
    that counter is not available the picture on the clipboard is read and
    boiled down to a short fingerprint instead.  `None` comes back when
    neither way works, and then nothing is assumed.
    """
    if sys.platform == "darwin":
        try:
            from AppKit import NSPasteboard  # type: ignore
            return f"count:{int(NSPasteboard.generalPasteboard().changeCount())}"
        except (ImportError, AttributeError, ValueError, TypeError):
            pass
    picture = clipboard_picture(widget)
    if picture is None:
        return "empty" if Image is not None else None
    try:                        # a small thumbnail is enough to tell apart
        small = picture.convert("RGB").resize((16, 16), Image.Resampling.NEAREST)
        return (f"{picture.width}x{picture.height}:"
                f"{hashlib.md5(small.tobytes()).hexdigest()}")
    except (OSError, ValueError, TypeError, AttributeError):
        return f"{picture.width}x{picture.height}"


def dropped_names(data):
    """The file names of a drop, which Tk hands over as one Tcl list."""
    text = str(data or "").strip()
    if not text:
        return []
    names = []
    rest = text
    while rest:
        rest = rest.lstrip()
        if rest.startswith("{"):
            end = rest.find("}")
            if end < 0:
                names.append(rest[1:])
                break
            names.append(rest[1:end])
            rest = rest[end + 1:]
        else:
            piece, _sep, rest = rest.partition(" ")
            if piece:
                names.append(piece)
    return [one for one in names if one]


def enable_file_drop(widget, handler):
    """Let files be dropped on a widget; True when the system allows it.

    Tk itself cannot take a drop.  The `tkdnd` extension can, and it comes
    with the `tkinterdnd2` package (`pip install tkinterdnd2`); without it
    the program works exactly as before and pictures arrive by pasting or
    through the menu.
    """
    try:
        widget.tk.call("package", "require", "tkdnd")
    except tk.TclError:
        try:
            import tkinterdnd2  # type: ignore[import-not-found]
            tkinterdnd2.TkinterDnD._require(widget)
        except (ImportError, AttributeError, tk.TclError, OSError):
            return False
    try:
        widget.tk.call("tkdnd::drop_target", "register", widget, ("DND_Files",))
        # bound through Tcl, so the names of the files (%D) and the place of
        # the pointer (%X, %Y) really arrive
        command = widget.register(handler)
        widget.tk.call("bind", widget, "<<Drop>>", command + " %D %X %Y")
    except (tk.TclError, AttributeError):
        return False
    return True


class ToolDialog(tk.Toplevel):
    """Base class of the small property windows.

    These windows are ordinary windows, not transient children, so the
    diagram can be brought in front of them while the settings stay open.
    `Property windows always on top` in the settings restores the old
    behaviour for those who prefer it.
    """

    def __init__(self, master, title, on_close=None):
        super().__init__(master)
        self.title(title)
        self.resizable(False, False)
        self._on_close = on_close
        if self.keep_on_top(master):
            self.transient(master)      # stays above the diagram window
        self.body = ttk.Frame(self, padding=12)
        self.body.pack(fill="both", expand=True)
        self.bind("<Escape>", lambda _e: self.close())
        self.protocol("WM_DELETE_WINDOW", self.close)
        self.after_idle(self.place_beside_parent)

    @staticmethod
    def keep_on_top(master):
        settings = getattr(master, "settings", None)
        try:
            return bool(settings.get("window", "dialogs_on_top"))
        except (AttributeError, KeyError, TypeError):
            return False

    def place_beside_parent(self):
        """Open next to the parent window instead of on top of it."""
        try:
            self.update_idletasks()
            parent = self.master.winfo_toplevel()
            px, py = parent.winfo_rootx(), parent.winfo_rooty()
            width, height = self.winfo_width(), self.winfo_height()
            screen_w = self.winfo_screenwidth()
            screen_h = self.winfo_screenheight()

            x = px + parent.winfo_width() + 12          # to the right
            if x + width > screen_w - 8:
                x = px - width - 12                     # or to the left
            if x < 8:
                x = max(8, screen_w - width - 8)
            y = min(max(8, py + 24), max(8, screen_h - height - 48))
            self.geometry(f"+{int(x)}+{int(y)}")
        except tk.TclError:
            pass

    def close(self):
        if self._on_close:
            self._on_close(self)
        self.destroy()
        # the diagram gets the keyboard back, so the arrow keys and the
        # copy/paste shortcuts keep working after a property window was used
        take_focus = getattr(self.master, "take_focus", None)
        if callable(take_focus):
            take_focus()

    @staticmethod
    def field(parent, row, text, widget, pady=2):
        ttk.Label(parent, text=text).grid(row=row, column=0, sticky="w",
                                          padx=(0, 4), pady=pady)
        widget.grid(row=row, column=1, sticky="w", pady=pady)
        if text and widget:
            try:
                Tooltip(widget, "Set the " + text.rstrip(":").replace(" [px]", " in pixels").lower())
            except Exception: pass
        return widget


class ArrowDialog(DiagramMirror, ToolDialog):
    """Head, line and colour of one arrow.

    `source`, when given, returns the state of the arrow as it is now (or
    None once it is gone), so the window follows it while open.
    """

    def __init__(self, master, state, on_apply, on_delete=None, on_close=None,
                 source=None):
        super().__init__(master, "Arrow properties", on_close=on_close)
        self.on_apply = on_apply
        self.on_delete = on_delete
        self.source = source

        self.head_var = tk.StringVar(
            value=name_of(ARROW_HEADS, state["head"], "Triangle head"))
        self.size_var = tk.StringVar(value=f"{state['size']:g}")
        self.style_var = tk.StringVar(
            value=name_of(LINE_STYLES, state["style"], "Solid"))
        self.width_var = tk.StringVar(value=f"{state['width']:g}")

        head = ttk.LabelFrame(self.body, text="Arrow head", padding=8)
        head.pack(fill="x")
        combo = ttk.Combobox(head, textvariable=self.head_var, state="readonly",
                             values=names(ARROW_HEADS), width=16)
        self.field(head, 0, "Type:", combo)
        combo.bind("<<ComboboxSelected>>", lambda _e: self.apply())
        self.field(head, 1, "Size [px]:",
                   ttk.Spinbox(head, from_=2, to=80, increment=1, width=8,
                               textvariable=self.size_var, command=self.apply))

        line = ttk.LabelFrame(self.body, text="Line", padding=8)
        line.pack(fill="x", pady=(10, 0))
        style = ttk.Combobox(line, textvariable=self.style_var, state="readonly",
                             values=names(LINE_STYLES), width=16)
        self.field(line, 0, "Style:", style)
        style.bind("<<ComboboxSelected>>", lambda _e: self.apply())
        self.field(line, 1, "Thickness:",
                   ttk.Spinbox(line, from_=0.2, to=20, increment=0.2, width=8,
                               textvariable=self.width_var, command=self.apply))
        self.color = ColorSwatch(line, state["color"],
                                 command=lambda _c: self.apply())
        self.field(line, 2, "Colour:", self.color)

        ttk.Label(self.body, foreground="#666", justify="left",
                  text="Drag the arrow to move it, drag the handle on its tip\n"
                       "or on its tail to change the direction and length."
                  ).pack(anchor="w", pady=(8, 0))

        bar = ttk.Frame(self.body)
        bar.pack(fill="x", pady=(12, 0))
        ttk.Button(bar, text="Apply", command=self.apply).pack(side="left")
        if on_delete is not None:
            ttk.Button(bar, text="Delete", command=self._delete).pack(
                side="left", padx=(6, 0))
        ttk.Button(bar, text="Close", command=self.close).pack(side="right")
        self.mirror(force=True)

    def _diagram_fields(self):
        state = self.source() if self.source is not None else None
        if not state:
            return {}
        return {
            "head": (self.head_var, name_of(ARROW_HEADS, state.get("head"), None)),
            "size": (self.size_var, field_number(state.get("size"), None)),
            "style": (self.style_var, name_of(LINE_STYLES, state.get("style"),
                                              None)),
            "width": (self.width_var, field_number(state.get("width"), None)),
            "color": (SwatchField(self.color), safe_hex(state.get("color"), None)),
        }

    def values(self):
        return {
            "head": code_of(ARROW_HEADS, self.head_var.get(), "triangle"),
            "size": max(2.0, to_float(self.size_var.get(), 14.0)),
            "style": code_of(LINE_STYLES, self.style_var.get(), "-"),
            "width": max(0.2, to_float(self.width_var.get(), 1.6)),
            "color": self.color.color,
        }

    def apply(self):
        self.mirror()           # catch up with the diagram first
        self.on_apply(self.values())

    def _delete(self):
        if self.on_delete:
            self.on_delete()
        self.close()


class ShapeDialog(DiagramMirror, ToolDialog):
    """Line and fill properties of one drawn object (or of a picture).

    `source`, when given, returns the state of the object as it is now (or
    None once it is gone): a shape turned by its handle, `Resize graph` or
    Undo show up in the window while it stays open.
    """

    def __init__(self, master, state, on_apply, on_delete=None, on_close=None,
                 on_fit=None, source=None):
        picture = state["kind"] == PICTURE_KIND
        title = ("Picture" if picture
                 else name_of(SHAPE_KINDS, state["kind"], "Shape"))
        super().__init__(master, f"{title} properties", on_close=on_close)
        self.source = source
        self.on_apply = on_apply
        self.on_delete = on_delete
        self.on_fit = on_fit
        self.picture = picture

        self.kind = state["kind"]
        self.line_on_var = tk.BooleanVar(
            value=not SeriesStyleDialog.is_off(state["style"]))
        self.style_var = tk.StringVar(
            value=SeriesStyleDialog.first_choice(LINE_STYLES, state["style"],
                                                 "Solid"))
        self.width_var = tk.StringVar(value=f"{state['width']:g}")
        self.alpha_var = tk.StringVar(value=f"{state.get('alpha', 0.6):g}")
        self.fill_on_var = tk.BooleanVar(value=state["face"] != "none")
        self.angle_var = tk.StringVar(value=f"{float(state.get('angle', 0.0)):g}")

        line = self._section("Frame" if picture else "Line", self.line_on_var)
        combo = ttk.Combobox(line, textvariable=self.style_var, state="readonly",
                             values=drawn_names(LINE_STYLES), width=14)
        self.field(line, 0, "Style:", combo)
        combo.bind("<<ComboboxSelected>>", lambda _e: self.apply())
        self.field(line, 1, "Thickness:",
                   ttk.Spinbox(line, from_=0, to=20, increment=0.5, width=8,
                               textvariable=self.width_var, command=self.apply))
        self.edge_color = ColorSwatch(line, state["edge"],
                                      command=lambda _c: self.apply())
        self.field(line, 2, "Colour:", self.edge_color)

        # a picture fills its own box: it has no colour to choose, only
        # how much of what is behind it shows through
        self.fill_box = None
        if picture:
            box = ttk.LabelFrame(self.body, text="Picture", padding=8)
            box.pack(fill="x", pady=(10, 0))
            self.field(box, 0, "Opacity (0-1):",
                       ttk.Spinbox(box, from_=0, to=1, increment=0.05, width=8,
                                   textvariable=self.alpha_var,
                                   command=self.apply))
            ttk.Button(box, text="Its own proportions",
                       command=self._fit).grid(row=0, column=2, padx=(8, 0))
            self.face_color = ColorSwatch(self.body, "#cfe3f7")
            self.face_color.pack_forget()
            self.fill_on_var.set(False)
        elif self.kind not in OPEN_SHAPES:
            fill = self._section("Fill", self.fill_on_var, pady=(10, 0))
            self.fill_box = fill
            self.face_color = ColorSwatch(
                fill, "#cfe3f7" if state["face"] == "none" else state["face"],
                command=lambda _c: self.apply())
            self.field(fill, 0, "Colour:", self.face_color)
            self.field(fill, 1, "Opacity (0-1):",
                       ttk.Spinbox(fill, from_=0, to=1, increment=0.05, width=8,
                                   textvariable=self.alpha_var,
                                   command=self.apply))
        else:
            self.face_color = ColorSwatch(self.body, "#cfe3f7")
            self.face_color.pack_forget()
            self.fill_on_var.set(False)

        # a line has no rotation of its own: its two ends give the direction,
        # and a picture is always upright
        if picture:
            hint = ("Drag the picture to move it, drag a square handle to\n"
                    "resize it.  \"Frame\" draws a line around it, and\n"
                    "\"Its own proportions\" undoes a squeeze.")
        elif self.kind not in OPEN_SHAPES:
            turn = ttk.LabelFrame(self.body, text="Rotation", padding=8)
            turn.pack(fill="x", pady=(10, 0))
            self.field(turn, 0, "Angle [deg]:",
                       ttk.Spinbox(turn, from_=-360, to=360, increment=5,
                                   width=8, textvariable=self.angle_var,
                                   command=self.apply))
            ttk.Button(turn, text="Upright",
                       command=lambda: (self.angle_var.set("0"),
                                        self.apply())).grid(row=0, column=2,
                                                            padx=(8, 0))
            hint = ("Switch \"Line\" or \"Fill\" off to leave that part out.\n"
                    "Drag the object to move it, drag a square handle to\n"
                    "resize it and the round one above it to turn it\n"
                    "(Shift: 15 degree steps).")
        else:
            hint = ("Switch \"Line\" off to hide it.\n"
                    "Drag the line to move it, drag one of its two ends to\n"
                    "change its length and direction\n"
                    "(Shift: 45 degree steps).")
        ttk.Label(self.body, foreground="#666", justify="left",
                  text=hint).pack(anchor="w", pady=(8, 0))

        bar = ttk.Frame(self.body)
        bar.pack(fill="x", pady=(12, 0))
        ttk.Button(bar, text="Apply", command=self.apply).pack(side="left")
        if on_delete is not None:
            ttk.Button(bar, text="Delete", command=self._delete).pack(
                side="left", padx=(6, 0))
        ttk.Button(bar, text="Close", command=self.close).pack(side="right")
        self.mirror(force=True)

    def _diagram_fields(self):
        state = self.source() if self.source is not None else None
        if not state:
            return {}
        style = state.get("style", "-")
        face = state.get("face", "none")
        fields = {
            "line_on": (self.line_on_var,
                        not SeriesStyleDialog.is_off(style)),
            "style": (self.style_var, None if SeriesStyleDialog.is_off(style)
                      else name_of(LINE_STYLES, style, None)),
            "width": (self.width_var, field_number(state.get("width"), None)),
            "edge": (SwatchField(self.edge_color),
                     safe_hex(state.get("edge"), None)),
            "alpha": (self.alpha_var, field_number(state.get("alpha", 0.6),
                                                   None)),
            "angle": (self.angle_var, field_number(
                float(state.get("angle", 0.0) or 0.0) % 360.0, None)),
        }
        if self.fill_box is not None:
            fields["fill_on"] = (self.fill_on_var, face != "none")
            fields["face"] = (SwatchField(self.face_color),
                              None if face == "none" else safe_hex(face, None))
        return fields

    def _section(self, title, variable, **pack):
        """A section whose title is its own check button."""
        box = ttk.LabelFrame(self.body, padding=8)
        check = ttk.Checkbutton(box, text=title, variable=variable,
                                command=self.apply)
        box.configure(labelwidget=check)
        box.pack(fill="x", **pack)
        return box

    def _fit(self):
        if self.on_fit:
            self.on_fit()
        return None

    def values(self):
        return {
            "style": (code_of(LINE_STYLES, self.style_var.get(), "-")
                      if self.line_on_var.get() else "none"),
            "width": max(0.0, to_float(self.width_var.get(), 1.5)),
            "edge": self.edge_color.color,
            "face": (self.face_color.color if self.fill_on_var.get() else "none"),
            "alpha": min(1.0, max(0.0, to_float(self.alpha_var.get(), 0.6))),
            "angle": to_float(self.angle_var.get(), 0.0) % 360.0,
        }

    def apply(self):
        self.mirror()           # catch up with the diagram first
        self.on_apply(self.values())

    def _delete(self):
        if self.on_delete:
            self.on_delete()
        self.close()


# --------------------------------------------------------------------------
# settings (configuration file editor)
# --------------------------------------------------------------------------

class SettingsDialog(ToolDialog):
    """Edits every default of the program and writes the configuration file."""

    def __init__(self, master, config: Config, on_saved=None, on_close=None):
        super().__init__(master, f"{APP_NAME} settings", on_close=on_close)
        self.config_obj = config
        self.on_saved = on_saved
        self._getters = {}

        notebook = ttk.Notebook(self.body)
        notebook.pack(fill="both", expand=True)
        self.notebook = notebook
        for section, title, fields in SETTINGS_SPEC:
            page = ttk.Frame(notebook, padding=12)
            notebook.add(page, text=title)
            for row, entry in enumerate(fields):
                self._add_row(page, row, section, entry)

        info = ttk.Label(self.body, foreground="#666", justify="left",
                         text=f"Saved to: {config.path}\n"
                              "Window sizes and plot defaults are used by "
                              "windows opened after saving.")
        info.pack(anchor="w", pady=(10, 0))

        bar = ttk.Frame(self.body)
        bar.pack(fill="x", pady=(12, 0))
        ttk.Button(bar, text="Restore defaults", command=self._restore).pack(side="left")
        ttk.Button(bar, text="Cancel", command=self.close).pack(side="right")
        ttk.Button(bar, text="Save", command=self._save).pack(side="right", padx=(0, 6))

    # -- construction ------------------------------------------------------
    # a number needs far less room than a sentence
    NUMBER_WIDTH = 9
    TEXT_WIDTH = 22
    CHOICE_WIDTH = 16
    FONT_WIDTH = 24            # font names are long

    def _add_row(self, page, row, section, entry):
        """One line of a settings page: one setting, or two side by side."""
        if isinstance(entry, (list,)) and entry and isinstance(entry[0], tuple):
            for half, spec in enumerate(entry[:2]):
                self._add_field(page, row, section, spec, half=half)
            return len(entry[:2])
        self._add_field(page, row, section, entry)
        return 1

    def _add_field(self, page, row, section, spec, half=0):
        key, label, kind = spec[0], spec[1], spec[2]
        extra = spec[3] if len(spec) > 3 else None
        value = self.config_obj.get(section, key)
        # the left half of a line uses columns 0 and 1, the right half 2 and 3
        column = 2 * int(half)
        pad = (16, 8) if half else (0, 8)

        if kind == "bool":
            var = tk.BooleanVar(value=bool(value))
            widget = ttk.Checkbutton(page, text=label, variable=var)
            widget.grid(row=row, column=column, columnspan=2, sticky="w",
                        padx=(pad[0], 0), pady=3)
            getter = var.get
        else:
            if kind in ("choice", "font"):
                if kind == "font":
                    extra = font_families()
                    value = known_font_family(value) or DEFAULT_FONT_FAMILY
                var = tk.StringVar(value=str(value))
                widget = ttk.Combobox(page, textvariable=var, state="readonly",
                                      values=extra,
                                      width=(self.FONT_WIDTH if kind == "font"
                                             else self.CHOICE_WIDTH))
                getter = var.get
            elif kind == "color":
                widget = ColorSwatch(page, safe_hex(value))
                getter = lambda w=widget: w.color
            else:
                var = tk.StringVar(value=str(value))
                width = (self.TEXT_WIDTH if kind not in ("int", "float")
                         else self.NUMBER_WIDTH)
                widget = ttk.Entry(page, textvariable=var, width=width)
                if kind == "int":
                    getter = lambda v=var, la=label: self._parse(v.get(), la, int)
                elif kind == "float":
                    getter = lambda v=var, la=label: self._parse(v.get(), la,
                                                                float)
                else:
                    getter = var.get
            ttk.Label(page, text=label).grid(row=row, column=column, sticky="w",
                                             padx=pad, pady=3)
            widget.grid(row=row, column=column + 1, sticky="w", pady=3)
        self._getters[(section, key)] = getter
        return widget

    @staticmethod
    def _parse(text, label, kind):
        value = to_float(text, None)
        if value is None:
            raise ValueError(f"'{label}' is not a number: {text!r}")
        return kind(round(value)) if kind is int else kind(value)

    # -- behaviour ---------------------------------------------------------
    def _restore(self):
        if not messagebox.askyesno(
                "Restore defaults",
                "Reset every setting to the built-in default value?", parent=self):
            return
        self.config_obj.reset()
        self._write_file()
        if self.on_saved:
            self.on_saved()
        self.close()

    def _save(self):
        try:
            values = {key: getter() for key, getter in self._getters.items()}
        except ValueError as error:
            messagebox.showerror("Invalid value", str(error), parent=self)
            return
        for (section, key), value in values.items():
            self.config_obj.set(section, key, value)
        if not self._write_file():
            return
        if self.on_saved:
            self.on_saved()
        self.close()

    def _write_file(self):
        try:
            self.config_obj.save()
            return True
        except OSError as error:
            messagebox.showerror("Error",
                                 f"The settings could not be saved:\n{error}",
                                 parent=self)
            return False


# --------------------------------------------------------------------------
# text + font size (title, axis labels, legend entries)
# --------------------------------------------------------------------------

class TextStyleDialog(DiagramMirror, ToolDialog):
    """One text with its font size and colour: `on_apply(text, size, colour)`.

    `source`, when given, tells what the diagram says now - (text, size,
    colour, distance) - so that the window follows the text while open.
    """

    def __init__(self, master, title, text, size, on_apply,
                 color="#000000", distance=None, distance_label="Distance [px]:",
                 hint=None, on_close=None, source=None):
        super().__init__(master, title, on_close=on_close)
        self.on_apply = on_apply
        self.source = source
        self.text_var = tk.StringVar(value=text)
        self.size_var = tk.StringVar(value=str(int(size)))
        self.distance_var = (tk.StringVar(value=f"{float(distance):g}")
                             if distance is not None else None)

        box = ttk.Frame(self.body)
        box.pack(fill="x")
        entry = self.field(box, 0, "Text:",
                           ttk.Entry(box, textvariable=self.text_var, width=34))
        self.field(box, 1, "Font size:",
                   ttk.Spinbox(box, from_=4, to=72, increment=1, width=8,
                               textvariable=self.size_var, command=self.apply))
        self.color = ColorSwatch(box, color, command=lambda _c: self.apply())
        self.field(box, 2, "Font colour:", self.color)
        if self.distance_var is not None:
            self.field(box, 3, distance_label,
                       ttk.Spinbox(box, from_=-200, to=400, increment=1, width=8,
                                   textvariable=self.distance_var,
                                   command=self.apply))
        if hint:
            ttk.Label(self.body, text=hint, foreground="#666").pack(
                anchor="w", pady=(6, 0))

        bar = ttk.Frame(self.body)
        bar.pack(fill="x", pady=(12, 0))
        ttk.Button(bar, text="Apply", command=self.apply).pack(side="left")
        ttk.Button(bar, text="Close", command=self.close).pack(side="right")
        ttk.Button(bar, text="OK", command=self._ok).pack(side="right", padx=(0, 6))
        self.bind("<Return>", lambda _e: self.apply())
        entry.focus_set()
        entry.select_range(0, "end")
        self.mirror(force=True)

    def _diagram_fields(self):
        if self.source is None:
            return {}
        text, size, color, distance = self.source()
        fields = {"text": (self.text_var, str(text)),
                  "size": (self.size_var, field_number(size, None)),
                  "color": (SwatchField(self.color), safe_hex(color, "#000000"))}
        if self.distance_var is not None and distance is not None:
            fields["distance"] = (self.distance_var, field_number(distance, None))
        return fields

    def apply(self):
        self.mirror()           # catch up with the diagram first
        distance = (to_float(self.distance_var.get(), 0.0)
                    if self.distance_var is not None else None)
        self.on_apply(self.text_var.get(), to_int(self.size_var.get(), 10),
                      self.color.color, distance)

    def _ok(self):
        self.apply()
        self.close()


# --------------------------------------------------------------------------
# curve (line + marker) properties
# --------------------------------------------------------------------------

class SeriesStyleDialog(DiagramMirror, PairedFields, ToolDialog):
    """Line, marker, bar, and error properties of one curve; changes are applied live."""

    def __init__(self, master, line: Line2D, on_change, on_close=None,
                 legend_size=None, legend_color="#000000", on_legend_style=None,
                 fill=None, on_fill=None,
                 plot_style="line_symbol", on_plot_style=None,
                 bar_cfg=None, on_bar_cfg=None,
                 error_cfg=None, on_error_cfg=None,
                 histogram_cfg=None, on_histogram_cfg=None,
                 stairs_cfg=None, on_stairs_cfg=None,
                 hist2d_cfg=None, on_hist2d_cfg=None,
                 pie_cfg=None, on_pie_cfg=None,
                 available_columns=None):
        super().__init__(master, "Curve properties", on_close=on_close)
        self.line = line
        self.on_change = on_change
        self.on_legend_style = on_legend_style
        self.on_fill = on_fill
        self._fill = dict(fill or {})
        self.plot_style_var = tk.StringVar(
            value=name_of(PLOT_STYLES, plot_style, "Line + Symbol"))
        self.on_plot_style = on_plot_style
        self.bar_cfg = dict(bar_cfg or {})
        self.on_bar_cfg = on_bar_cfg
        self.hist_cfg = dict(histogram_cfg or {})
        self.on_histogram_cfg = on_histogram_cfg
        self.stairs_cfg = dict(stairs_cfg or {})
        self.on_stairs_cfg = on_stairs_cfg
        self.hist2d_cfg = dict(hist2d_cfg or {})
        self.on_hist2d_cfg = on_hist2d_cfg
        self.pie_cfg = dict(pie_cfg or {})
        self.on_pie_cfg = on_pie_cfg
        self.error_cfg = dict(error_cfg or {})
        self.on_error_cfg = on_error_cfg
        self.available_columns = list(available_columns or [])
        self.legend_size_var = tk.StringVar(
            value=str(int(legend_size if legend_size is not None else 10)))
        self._legend_color = safe_hex(legend_color, "#000000")
        self._loading = True

        label = line.get_label()
        self.column = getattr(line, "aplot_series", None)
        self.label_var = tk.StringVar(value="" if label.startswith("_") else label)

        # every section has its own check button: off means the line, the
        # marker, the legend box or the fill is simply not drawn
        self.line_on_var = tk.BooleanVar(value=not self.is_off(line.get_linestyle()))
        self.marker_on_var = tk.BooleanVar(value=not self.is_off(line.get_marker()))
        self.legend_on_var = tk.BooleanVar(value=not label.startswith("_"))

        self.lstyle_var = tk.StringVar(
            value=self.first_choice(LINE_STYLES, line.get_linestyle(), "Solid"))
        self.lwidth_var = tk.StringVar(value=f"{line.get_linewidth():g}")
        self.mstyle_var = tk.StringVar(
            value=self.first_choice(MARKERS, line.get_marker(),
                                    self.default_marker()))
        self.msize_var = tk.StringVar(value=f"{line.get_markersize():g}")
        self.mwidth_var = tk.StringVar(value=f"{line.get_markeredgewidth():g}")

        face = line.get_markerfacecolor()
        self.hollow_var = tk.BooleanVar(
            value=isinstance(face, str) and face == "none")

        self.fill_on_var = tk.BooleanVar(value=bool(self._fill.get("on")))
        self.fill_follow_var = tk.BooleanVar(value=bool(self._fill.get("follow", True)))
        self.fill_alpha_var = tk.StringVar(value=f"{self._fill.get('alpha', 0.35):g}")
        self.fill_hatch_var = tk.StringVar(
            value=name_of(HATCH_PATTERNS, self._fill.get("hatch", ""),
                          names(HATCH_PATTERNS)[0]))
        # a check button instead of a list: on means the zero line, off (the
        # default) means the bottom of the axes
        self.fill_zero_var = tk.BooleanVar(
            value=str(self._fill.get("base", "bottom")) == "zero")

        line_color = safe_hex(line.get_color())
        self._build_style_box()
        self._build_legend_box()
        self._build_line_box(line_color)
        self._build_marker_box(line_color, face)
        self._build_bar_box(line_color)
        self._build_error_box(line_color)
        self._build_stairs_box(line_color)
        self._build_hist2d_box()
        self._build_pie_box(line_color)
        self._build_fill_box(line_color)
        self._align_columns((self.legend_box, self.line_box,
                             self.marker_box, self.bar_box,
                             self.error_box, self.stairs_box,
                             self.hist2d_box, self.pie_box, self.fill_box))
        self._update_section_visibility()
        self._build_buttons()
        self.mirror(force=True)
        self._loading = False

    # -- following the diagram ---------------------------------------------
    def _diagram_fields(self):
        """What the curve looks like on the diagram right now.

        The window applies every change at once, and it applies all of its
        fields together: a legend renamed on the graph, a colour chosen
        from the menu of the curve or `Resize graph` has to be in these
        fields before the next change made here sends them back.
        """
        line = self.line
        plot = self.master
        column = self.column
        label = str(line.get_label())
        hidden = label.startswith("_")
        line_style = line.get_linestyle()
        marker = line.get_marker()
        face = line.get_markerfacecolor()
        hollow = isinstance(face, str) and face == "none"
        line_color = safe_hex(line.get_color())
        fields = {
            "label": (self.label_var, None if hidden else label),
            "legend_on": (self.legend_on_var, not hidden),
            "line_on": (self.line_on_var, not self.is_off(line_style)),
            "line_style": (self.lstyle_var, None if self.is_off(line_style)
                           else name_of(LINE_STYLES, line_style, "Solid")),
            "line_width": (self.lwidth_var, field_number(line.get_linewidth(), None)),
            "line_color": (SwatchField(self.line_color), line_color),
            "marker_on": (self.marker_on_var, not self.is_off(marker)),
            "marker": (self.mstyle_var, None if self.is_off(marker)
                       else name_of(MARKERS, marker, self.default_marker())),
            "marker_size": (self.msize_var,
                            field_number(line.get_markersize(), None)),
            "marker_edge_width": (self.mwidth_var,
                                  field_number(line.get_markeredgewidth(), None)),
            "hollow": (self.hollow_var, hollow),
            "face_color": (SwatchField(self.face_color),
                           None if hollow else safe_hex(face, line_color)),
            "edge_color": (SwatchField(self.edge_color),
                           safe_hex(line.get_markeredgecolor(), line_color)),
        }
        state = (getattr(plot, "legend_state", None) or {}).get(column)
        if state:
            fields["legend_size"] = (self.legend_size_var,
                                     field_number(state.get("size"), None))
            fields["legend_color"] = (SwatchField(self.legend_color),
                                      safe_hex(state.get("color"), "#000000"))
        styles = getattr(plot, "series_style", None)
        if styles is not None and column is not None:
            style = styles.get(column, getattr(plot, "plot_style", None))
            if style:
                fields["plot_style"] = (self.plot_style_var,
                                        name_of(PLOT_STYLES, style, None))

        def numbers(holder, pairs):
            for key, (name, variable) in pairs.items():
                if isinstance(holder, dict) and holder.get(key) is not None:
                    fields[name] = (variable, field_number(holder[key], None))

        def colour(holder, key, name, swatch):
            if isinstance(holder, dict) and holder.get(key) not in (None, "none"):
                fields[name] = (SwatchField(swatch), safe_hex(holder[key], None))

        error = (getattr(plot, "error_cfg", None) or {}).get(column)
        numbers(error, {"capsize": ("err_capsize", self.err_capsize_var),
                        "capthick": ("err_capthick", self.err_capthick_var),
                        "elinewidth": ("err_width", self.err_elinewidth_var)})
        colour(error, "color", "err_color", self.err_color)
        histogram = self.style_code() == "histogram"
        bars = (getattr(plot, "histogram_cfg" if histogram else "bar_cfg",
                        None) or {}).get(column)
        numbers(bars, {"edgewidth": ("bar_edge_width", self.bar_edge_width_var)})
        stairs = (getattr(plot, "stairs_cfg", None) or {}).get(column)
        numbers(stairs, {"width": ("stairs_width", self.stairs_width_var)})
        pie = (getattr(plot, "pie_cfg", None) or {}).get(column)
        numbers(pie, {"edgewidth": ("pie_edge_width", self.pie_edge_width_var),
                      "name_size": ("pie_name_size", self.pie_name_size_var),
                      "pct_size": ("pie_pct_size", self.pie_number_size_var)})
        return fields

    def mirror(self, force=False, only=None):
        # the fields apply themselves when they change: not while they are
        # only being told what the diagram already says
        loading, self._loading = self._loading, True
        try:
            return DiagramMirror.mirror(self, force, only)
        finally:
            self._loading = loading

    def _mirrored(self, names):
        if "plot_style" in names:
            self._update_section_visibility()

    # -- helpers -----------------------------------------------------------
    @staticmethod
    def is_off(code):
        """True for every way matplotlib writes "not drawn"."""
        return str(code).strip().lower() in ("none", "", " ", "nothing")

    @staticmethod
    def first_choice(table, code, fallback):
        """The name of `code`, or `fallback` when it is switched off."""
        if SeriesStyleDialog.is_off(code):
            names_left = drawn_names(table)
            return fallback if fallback in names_left else names_left[0]
        return name_of(table, code, fallback)

    def default_marker(self):
        """The marker a curve gets when the marker is switched on."""
        settings = getattr(self.master, "settings", None)
        try:
            wanted = str(settings.get("plot", "marker"))
        except (AttributeError, KeyError, TypeError):
            wanted = ""
        choices = drawn_names(MARKERS)
        return wanted if wanted in choices else choices[0]

    def _section(self, title, variable, **pack):
        """A section whose title is its own check button."""
        box = ttk.LabelFrame(self.body, padding=8)
        check = ttk.Checkbutton(box, text=title, variable=variable,
                                command=self._apply)
        box.configure(labelwidget=check)
        box.pack(fill="x", **pack)
        return box

    # -- construction ------------------------------------------------------
    def _build_style_box(self):
        box = ttk.LabelFrame(self.body, text="Plot Style", padding=8)
        self.style_box = box
        box.pack(fill="x", pady=(0, 10))
        combo = ttk.Combobox(box, textvariable=self.plot_style_var, state="readonly",
                             values=[label for label, *_ in PLOT_STYLES], width=24)
        combo.pack(fill="x")
        combo.bind("<<ComboboxSelected>>", self._on_style_changed)

    LEGEND_HINT = "Switch \"Legend\" off to hide this curve's box."
    PIE_LEGEND_HINT = ("A pie's box lists every slice on its own row, so it\n"
                       "has no single text.  The names come from the first\n"
                       "column of the table; to change just one of them,\n"
                       "click its row in the box, wait, and click it again.")

    def _build_legend_box(self):
        box = self._section("Legend", self.legend_on_var)
        self.legend_box = box
        ttk.Label(box, text="Text:").grid(row=0, column=0, sticky="w",
                                          padx=(0, 8), pady=3)
        self.label_entry = ttk.Entry(box, textvariable=self.label_var, width=30)
        self.label_entry.grid(row=0, column=1, columnspan=3, sticky="ew",
                              pady=3)
        self.label_var.trace_add("write", self._apply)
        # the size of the text and its colour stand side by side
        self.legend_color = ColorSwatch(box, self._legend_color,
                                        command=lambda _c: self._apply())
        self._pair(box, 1,
                   "Font size:",
                   ttk.Spinbox(box, from_=4, to=72, increment=1, width=SPIN_WIDTH,
                               textvariable=self.legend_size_var,
                               command=self._apply),
                   "Colour:", self.legend_color)
        self.legend_size_var.trace_add("write", self._apply)
        self.legend_hint = ttk.Label(
            box, text=self.LEGEND_HINT, foreground="#666", justify="left")
        self._wide(self.legend_hint, 2, pady=(4, 0))

    def _build_line_box(self, line_color):
        box = self._section("Line", self.line_on_var, pady=(10, 0))
        self.line_box = box

        combo = ttk.Combobox(box, textvariable=self.lstyle_var, state="readonly",
                             values=drawn_names(LINE_STYLES), width=COMBO_WIDTH)
        self.field(box, 0, "Style:", combo)
        combo.bind("<<ComboboxSelected>>", self._apply)

        # the thickness of the line and its colour stand side by side
        self.line_color = ColorSwatch(box, line_color,
                                      command=lambda _c: self._apply())
        self._pair(box, 1,
                   "Width:",
                   ttk.Spinbox(box, from_=0, to=20, increment=0.5,
                               width=SPIN_WIDTH, textvariable=self.lwidth_var,
                               command=self._apply),
                   "Colour:", self.line_color)
        self.lwidth_var.trace_add("write", self._apply)

    def _build_marker_box(self, line_color, face):
        box = self._section("Marker", self.marker_on_var, pady=(10, 0))
        self.marker_box = box

        # an outlined marker has no fill at all: the switch belongs on top
        self._wide(ttk.Checkbutton(box, text="Hollow (no fill)",
                                   variable=self.hollow_var,
                                   command=self._apply), 0, pady=(0, 4))

        combo = ttk.Combobox(box, textvariable=self.mstyle_var, state="readonly",
                             values=drawn_names(MARKERS), width=COMBO_WIDTH)
        self.field(box, 1, "Style:", combo)
        combo.bind("<<ComboboxSelected>>", self._apply)

        self.face_color = ColorSwatch(box, safe_hex(face, line_color),
                                      command=lambda _c: self._apply())
        self._pair(box, 2,
                   "Size:",
                   ttk.Spinbox(box, from_=0, to=40, increment=1,
                               width=SPIN_WIDTH, textvariable=self.msize_var,
                               command=self._apply),
                   "Fill colour:", self.face_color)
        self.msize_var.trace_add("write", self._apply)

        self.edge_color = ColorSwatch(
            box, safe_hex(self.line.get_markeredgecolor(), line_color),
            command=lambda _c: self._apply())
        self._pair(box, 3,
                   "Edge width:",
                   ttk.Spinbox(box, from_=0, to=10, increment=0.5,
                               width=SPIN_WIDTH, textvariable=self.mwidth_var,
                               command=self._apply),
                   "Edge colour:", self.edge_color)
        self.mwidth_var.trace_add("write", self._apply)

    def _build_bar_box(self, line_color):
        """Bars: shared by the bar chart and the histogram.

        The two differ in one field only: a bar chart has a width, while
        the bars of a histogram touch and it is the **number of bins** that
        can be set instead.  So the first line of the section carries
        whichever of the two belongs to the style of this curve.
        """
        box = ttk.LabelFrame(self.body, text="Bar properties", padding=8)
        self.bar_box = box
        histogram = self.style_code() == "histogram"
        # a histogram curve reads its colours from its own settings
        source = self.hist_cfg if histogram else self.bar_cfg
        self.bar_width_var = tk.StringVar(value=str(self.bar_cfg.get("width", 0.8)))
        self.hist_bins_var = tk.StringVar(
            value=str(int(self.hist_cfg.get("bins", HISTOGRAM_BINS))))
        self.bar_alpha_var = tk.StringVar(value=str(source.get("alpha", 0.85)))
        self.bar_edge_width_var = tk.StringVar(value=str(source.get("edgewidth", 1.0)))
        self.bar_color = ColorSwatch(box, source.get("color", line_color),
                                     command=lambda _c: self._apply())
        self.bar_edge_color = ColorSwatch(
            box, source.get("edgecolor", "#ffffff" if histogram else line_color),
            command=lambda _c: self._apply())

        self.bar_width_spin = ttk.Spinbox(
            box, from_=0.05, to=10, increment=0.05, width=SPIN_WIDTH,
            textvariable=self.bar_width_var, command=self._apply)
        self._pair(box, 0, "Width:", self.bar_width_spin,
                   "Bar colour:", self.bar_color)
        self.bar_width_label = box.grid_slaves(row=0, column=0)[0]
        self.bar_width_var.trace_add("write", self._apply)

        # the number of bins takes the same place when this is a histogram
        self.hist_bins_label = ttk.Label(box, text="Bins:")
        self.hist_bins_spin = ttk.Spinbox(
            box, from_=1, to=MAX_HISTOGRAM_BINS, increment=1, width=SPIN_WIDTH,
            textvariable=self.hist_bins_var, command=self._apply)
        self.hist_bins_var.trace_add("write", self._apply)

        self._pair(box, 1,
                   "Opacity (0-1):",
                   ttk.Spinbox(box, from_=0, to=1, increment=0.05,
                               width=SPIN_WIDTH, textvariable=self.bar_alpha_var,
                               command=self._apply),
                   "Edge colour:", self.bar_edge_color)
        self.bar_alpha_var.trace_add("write", self._apply)

        self._pair(box, 2,
                   "Edge width:",
                   ttk.Spinbox(box, from_=0, to=10, increment=0.5,
                               width=SPIN_WIDTH, textvariable=self.bar_edge_width_var,
                               command=self._apply),
                   "", ttk.Label(box, text=""))
        self.bar_edge_width_var.trace_add("write", self._apply)

        # a pattern over the colour, the same choice a filled area has
        self.bar_hatch_var = tk.StringVar(
            value=name_of(HATCH_PATTERNS, source.get("hatch", ""),
                          names(HATCH_PATTERNS)[0]))
        pattern = ttk.Combobox(box, textvariable=self.bar_hatch_var,
                               state="readonly", values=names(HATCH_PATTERNS),
                               width=22)
        self.field(box, 3, "Pattern:", pattern)
        pattern.bind("<<ComboboxSelected>>", self._apply)

    def _build_error_box(self, line_color):
        box = ttk.LabelFrame(self.body, text="Error bar properties", padding=8)
        self.error_box = box
        err_type = self.error_cfg.get("type", "pair")
        self.err_type_var = tk.StringVar(
            value=name_of(ERROR_SOURCES, err_type, names(ERROR_SOURCES)[0]))
        self.err_val_var = tk.StringVar(value=str(self.error_cfg.get("value", 5.0)))
        self.err_col_var = tk.StringVar(value=str(self.error_cfg.get("column", "")))
        self.err_capsize_var = tk.StringVar(value=str(self.error_cfg.get("capsize", 4.0)))
        self.err_capthick_var = tk.StringVar(value=str(self.error_cfg.get("capthick", 1.5)))
        self.err_elinewidth_var = tk.StringVar(value=str(self.error_cfg.get("elinewidth", 1.5)))
        self.err_color = ColorSwatch(box, self.error_cfg.get("color", line_color),
                                     command=lambda _c: self._apply())

        combo = ttk.Combobox(box, textvariable=self.err_type_var, state="readonly",
                             values=names(ERROR_SOURCES), width=COMBO_WIDTH)
        self.field(box, 0, "Source:", combo)
        combo.bind("<<ComboboxSelected>>", self._on_err_type_changed)

        self._err_val_spin = ttk.Spinbox(box, from_=0.01, to=1000, increment=0.5,
                                         width=SPIN_WIDTH, textvariable=self.err_val_var,
                                         command=self._apply)
        self._pair(box, 1, "Value / %:", self._err_val_spin,
                   "Colour:", self.err_color)
        self.err_val_var.trace_add("write", self._apply)

        cols = [c for c in self.available_columns if str(c) != str(self.column)]
        if not cols:
            cols = list(self.available_columns)
        self._err_col_combo = ttk.Combobox(box, textvariable=self.err_col_var, state="readonly",
                                           values=cols, width=COMBO_WIDTH)
        self.field(box, 2, "Column:", self._err_col_combo)
        self._err_col_combo.bind("<<ComboboxSelected>>", self._apply)

        self._pair(box, 3,
                   "Cap width:",
                   ttk.Spinbox(box, from_=0, to=20, increment=1,
                               width=SPIN_WIDTH, textvariable=self.err_capsize_var,
                               command=self._apply),
                   "Line width:",
                   ttk.Spinbox(box, from_=0.5, to=10, increment=0.5,
                               width=SPIN_WIDTH, textvariable=self.err_elinewidth_var,
                               command=self._apply))
        self.err_capsize_var.trace_add("write", self._apply)
        self.err_elinewidth_var.trace_add("write", self._apply)

        # the thickness of the caps themselves: it was in the settings all
        # along, but there was no field for it
        self._pair(box, 4,
                   "Cap thickness:",
                   ttk.Spinbox(box, from_=0, to=10, increment=0.5,
                               width=SPIN_WIDTH,
                               textvariable=self.err_capthick_var,
                               command=self._apply),
                   "", ttk.Label(box, text=""))
        self.err_capthick_var.trace_add("write", self._apply)

    def _build_stairs_box(self, line_color):
        """Stairs: where the steps stand, and how the staircase is drawn."""
        box = ttk.LabelFrame(self.body, text="Stairs properties", padding=8)
        self.stairs_box = box
        cfg = self.stairs_cfg
        self.stairs_edges_var = tk.StringVar(
            value=name_of(STAIRS_EDGES, cfg.get("edges", "mid"),
                          names(STAIRS_EDGES)[0]))
        self.stairs_width_var = tk.StringVar(value=str(cfg.get("width", 1.8)))
        self.stairs_alpha_var = tk.StringVar(value=str(cfg.get("alpha", 0.35)))
        self.stairs_fill_var = tk.BooleanVar(value=bool(cfg.get("fill", False)))
        self.stairs_base_var = tk.BooleanVar(
            value=bool(cfg.get("baseline", False)))
        self.stairs_hatch_var = tk.StringVar(
            value=name_of(HATCH_PATTERNS, cfg.get("hatch", ""),
                          names(HATCH_PATTERNS)[0]))
        self.stairs_color = ColorSwatch(box, cfg.get("color", line_color),
                                        command=lambda _c: self._apply())

        combo = ttk.Combobox(box, textvariable=self.stairs_edges_var,
                             state="readonly", values=names(STAIRS_EDGES),
                             width=28)
        self._wide(combo, 0, pady=(0, 4))
        combo.bind("<<ComboboxSelected>>", self._apply)

        self._pair(box, 1,
                   "Line width:",
                   ttk.Spinbox(box, from_=0, to=10, increment=0.2,
                               width=SPIN_WIDTH,
                               textvariable=self.stairs_width_var,
                               command=self._apply),
                   "Colour:", self.stairs_color)
        self.stairs_width_var.trace_add("write", self._apply)

        self._pair(box, 2,
                   "Fill it:", ttk.Checkbutton(box, variable=self.stairs_fill_var,
                                               command=self._apply),
                   "Opacity (0-1):",
                   ttk.Spinbox(box, from_=0, to=1, increment=0.05,
                               width=SPIN_WIDTH,
                               textvariable=self.stairs_alpha_var,
                               command=self._apply))
        self.stairs_alpha_var.trace_add("write", self._apply)

        pattern = ttk.Combobox(box, textvariable=self.stairs_hatch_var,
                               state="readonly", values=names(HATCH_PATTERNS),
                               width=22)
        self.field(box, 3, "Pattern:", pattern)
        pattern.bind("<<ComboboxSelected>>", self._apply)

        self._wide(ttk.Checkbutton(box, text="Close it down to the zero line",
                                   variable=self.stairs_base_var,
                                   command=self._apply), 4, pady=(4, 0))

    def _build_hist2d_box(self):
        """2D histogram: the grid, the colour scale and the colour bar."""
        box = ttk.LabelFrame(self.body, text="2D histogram properties",
                             padding=8)
        self.hist2d_box = box
        cfg = self.hist2d_cfg
        self.h2_xbins_var = tk.StringVar(
            value=str(int(cfg.get("xbins", HIST2D_BINS))))
        self.h2_ybins_var = tk.StringVar(
            value=str(int(cfg.get("ybins", HIST2D_BINS))))
        self.h2_alpha_var = tk.StringVar(value=str(cfg.get("alpha", 1.0)))
        self.h2_cmap_var = tk.StringVar(
            value=name_of(COLOR_MAPS, cfg.get("cmap", "viridis"),
                          names(COLOR_MAPS)[0]))
        self.h2_bar_var = tk.BooleanVar(value=bool(cfg.get("colorbar", False)))
        self.h2_empty_var = tk.BooleanVar(
            value=bool(cfg.get("hide_empty", True)))

        self._pair(box, 0,
                   "Bins across X:",
                   ttk.Spinbox(box, from_=1, to=MAX_HIST2D_BINS, increment=1,
                               width=SPIN_WIDTH, textvariable=self.h2_xbins_var,
                               command=self._apply),
                   "Bins up Y:",
                   ttk.Spinbox(box, from_=1, to=MAX_HIST2D_BINS, increment=1,
                               width=SPIN_WIDTH, textvariable=self.h2_ybins_var,
                               command=self._apply))
        self.h2_xbins_var.trace_add("write", self._apply)
        self.h2_ybins_var.trace_add("write", self._apply)

        combo = ttk.Combobox(box, textvariable=self.h2_cmap_var,
                             state="readonly", values=names(COLOR_MAPS),
                             width=22)
        self.field(box, 1, "Colour scale:", combo)
        combo.bind("<<ComboboxSelected>>", self._apply)

        self._pair(box, 2,
                   "Opacity (0-1):",
                   ttk.Spinbox(box, from_=0, to=1, increment=0.05,
                               width=SPIN_WIDTH, textvariable=self.h2_alpha_var,
                               command=self._apply),
                   "Colour bar:",
                   ttk.Checkbutton(box, variable=self.h2_bar_var,
                                   command=self._apply))
        self.h2_alpha_var.trace_add("write", self._apply)

        self._wide(ttk.Checkbutton(box, text="Leave the empty cells white",
                                   variable=self.h2_empty_var,
                                   command=self._apply), 3, pady=(4, 0))

    def _build_pie_box(self, line_color):
        """Pie: the slices, their names and the numbers written on them."""
        box = ttk.LabelFrame(self.body, text="Pie properties", padding=8)
        self.pie_box = box
        cfg = self.pie_cfg
        self.pie_cmap_var = tk.StringVar(
            value=name_of(COLOR_MAPS, cfg.get("cmap", "tab10"),
                          names(COLOR_MAPS)[0]))
        self.pie_labels_var = tk.StringVar(
            value=name_of(PIE_LABELS, cfg.get("labels", "column"),
                          names(PIE_LABELS)[0]))
        self.pie_start_var = tk.StringVar(
            value=f"{float(cfg.get('start', PIE_START_ANGLE)):g}")
        self.pie_hole_var = tk.StringVar(value=str(cfg.get("hole", 0.0)))
        self.pie_explode_var = tk.StringVar(value=str(cfg.get("explode", 0.0)))
        self.pie_percent_var = tk.BooleanVar(
            value=bool(cfg.get("percent", True)))
        self.pie_names_on_var = tk.BooleanVar(
            value=(bool(cfg.get("names_on", True))
                   and str(cfg.get("labels", "column")) != "none"))
        self.pie_decimals_var = tk.StringVar(
            value=str(int(cfg.get("decimals", 1))))
        self.pie_size_var = tk.StringVar(
            value=str(int(cfg.get("label_size", 11))))
        name_size, name_color = PlotWindow.pie_text_style(cfg, "name")
        pct_size, pct_color = PlotWindow.pie_text_style(cfg, "pct")
        self.pie_name_size_var = tk.StringVar(value=str(name_size))
        self.pie_number_size_var = tk.StringVar(value=str(pct_size))
        self.pie_clock_var = tk.BooleanVar(
            value=bool(cfg.get("clockwise", True)))
        self.pie_edge_width_var = tk.StringVar(
            value=str(cfg.get("edgewidth", 1.0)))
        self.pie_name_at_var = tk.StringVar(
            value=str(cfg.get("labeldistance", PIE_LABEL_DISTANCE)))
        self.pie_number_at_var = tk.StringVar(
            value=str(cfg.get("pctdistance", PIE_PCT_DISTANCE)))
        self.pie_turn_names_var = tk.BooleanVar(
            value=bool(cfg.get("rotate_labels", False)))
        self.pie_turn_numbers_var = tk.BooleanVar(
            value=bool(cfg.get("rotate_numbers", False)))
        self.pie_edge_color = ColorSwatch(
            box, cfg.get("edgecolor", "#ffffff"),
            command=lambda _c: self._apply())
        self.pie_name_color = ColorSwatch(box, name_color,
                                          command=lambda _c: self._apply())
        self.pie_number_color = ColorSwatch(box, pct_color,
                                            command=lambda _c: self._apply())

        combo = ttk.Combobox(box, textvariable=self.pie_cmap_var,
                             state="readonly", values=names(COLOR_MAPS),
                             width=22)
        self.field(box, 0, "Slice colours:", combo)
        combo.bind("<<ComboboxSelected>>", self._apply)

        self._pair(box, 1,
                   "Start angle:",
                   ttk.Spinbox(box, from_=-360, to=360, increment=15,
                               width=SPIN_WIDTH, textvariable=self.pie_start_var,
                               command=self._apply),
                   "Edge colour:", self.pie_edge_color)
        self.pie_start_var.trace_add("write", self._apply)

        self._pair(box, 2,
                   "Hole (0-0.9):",
                   ttk.Spinbox(box, from_=0, to=0.9, increment=0.05,
                               width=SPIN_WIDTH, textvariable=self.pie_hole_var,
                               command=self._apply),
                   "Edge width:",
                   ttk.Spinbox(box, from_=0, to=10, increment=0.5,
                               width=SPIN_WIDTH,
                               textvariable=self.pie_edge_width_var,
                               command=self._apply))
        self.pie_hole_var.trace_add("write", self._apply)
        self.pie_edge_width_var.trace_add("write", self._apply)

        self.field(box, 3, "Pull out the first:",
                   ttk.Spinbox(box, from_=0, to=0.5, increment=0.05,
                               width=SPIN_WIDTH,
                               textvariable=self.pie_explode_var,
                               command=self._apply))
        self.pie_explode_var.trace_add("write", self._apply)

        # the names standing around the pie: switched off with the check
        # button of their own little group
        self.pie_names_group = ttk.Checkbutton(
            box, text="The names of the slices:",
            variable=self.pie_names_on_var, command=self._apply)
        self._wide(self.pie_names_group, 4, pady=(10, 2))
        names_combo = ttk.Combobox(box, textvariable=self.pie_labels_var,
                                   state="readonly", values=names(PIE_LABELS),
                                   width=26)
        self._wide(names_combo, 5, pady=(0, 4))
        names_combo.bind("<<ComboboxSelected>>", self._apply)
        self._pair(box, 6,
                   "Distance:",
                   ttk.Spinbox(box, from_=0, to=2.5, increment=0.05,
                               width=SPIN_WIDTH,
                               textvariable=self.pie_name_at_var,
                               command=self._apply),
                   "Font size:",
                   ttk.Spinbox(box, from_=4, to=48, increment=1,
                               width=SPIN_WIDTH,
                               textvariable=self.pie_name_size_var,
                               command=self._apply))
        self.pie_name_at_var.trace_add("write", self._apply)
        self.pie_name_size_var.trace_add("write", self._apply)
        self._pair(box, 7,
                   "Colour:", self.pie_name_color,
                   "Turn them:",
                   ttk.Checkbutton(box, variable=self.pie_turn_names_var,
                                   command=self._apply))

        # ... and the numbers written on the slices, the same way
        self.pie_numbers_group = ttk.Checkbutton(
            box, text="The numbers on the slices:",
            variable=self.pie_percent_var, command=self._apply)
        self._wide(self.pie_numbers_group, 8, pady=(10, 2))
        self._pair(box, 9,
                   "Distance:",
                   ttk.Spinbox(box, from_=0, to=2.5, increment=0.05,
                               width=SPIN_WIDTH,
                               textvariable=self.pie_number_at_var,
                               command=self._apply),
                   "Font size:",
                   ttk.Spinbox(box, from_=4, to=48, increment=1,
                               width=SPIN_WIDTH,
                               textvariable=self.pie_number_size_var,
                               command=self._apply))
        self.pie_number_at_var.trace_add("write", self._apply)
        self.pie_number_size_var.trace_add("write", self._apply)
        self._pair(box, 10,
                   "Colour:", self.pie_number_color,
                   "Turn them:",
                   ttk.Checkbutton(box, variable=self.pie_turn_numbers_var,
                                   command=self._apply))
        self.field(box, 11, "Decimals:",
                   ttk.Spinbox(box, from_=0, to=4, increment=1,
                               width=SPIN_WIDTH,
                               textvariable=self.pie_decimals_var,
                               command=self._apply))
        self.pie_decimals_var.trace_add("write", self._apply)

        self._wide(ttk.Label(box, foreground="#666",
                             text="A distance of 1.0 is the rim of the pie."),
                   12, pady=(8, 0))

        self._wide(ttk.Checkbutton(box, text="Go round anticlockwise",
                                   variable=self.pie_clock_var,
                                   command=self._apply), 13, pady=(4, 0))

    def _on_err_type_changed(self, _event=None):
        src = code_of(ERROR_SOURCES, self.err_type_var.get(), "pair")
        if src == "column":
            self._err_col_combo.configure(state="readonly")
            self._err_val_spin.configure(state="disabled")
        elif src in ("std", "pair"):
            self._err_col_combo.configure(state="disabled")
            self._err_val_spin.configure(state="disabled")
        else:
            self._err_col_combo.configure(state="disabled")
            self._err_val_spin.configure(state="normal")
        self._apply()

    def style_code(self):
        """The plot style this curve is drawn with, as a code."""
        return code_of(PLOT_STYLES, self.plot_style_var.get(), "line_symbol")

    def _show_bar_fields(self, histogram):
        """A histogram has a number of bins where a bar chart has a width."""
        self.bar_box.configure(text="Histogram properties" if histogram
                               else "Bar properties")
        if histogram:
            self.bar_width_label.grid_remove()
            self.bar_width_spin.grid_remove()
            self.hist_bins_label.grid(row=0, column=0, sticky="w",
                                      padx=(0, 8), pady=3)
            self.hist_bins_spin.grid(row=0, column=1, sticky="w", pady=3)
        else:
            self.hist_bins_label.grid_remove()
            self.hist_bins_spin.grid_remove()
            self.bar_width_label.grid()
            self.bar_width_spin.grid()

    # which sections belong to which plot style, in the order they appear
    SECTIONS = {
        "line_symbol": ("line_box", "marker_box", "fill_box"),
        "line": ("line_box", "fill_box"),
        "scatter": ("marker_box", "fill_box"),
        "bar": ("bar_box",),
        "histogram": ("bar_box",),
        "errorbar": ("marker_box", "line_box", "error_box"),
        "errorbar_pm": ("marker_box", "line_box", "error_box"),
        "stairs": ("stairs_box",),
        "hist2d": ("hist2d_box",),
        "pie": ("pie_box",),
    }

    def _update_section_visibility(self):
        """Show exactly the sections the plot style of this curve can use."""
        st = self.style_code()
        for name in ("line_box", "marker_box", "bar_box", "error_box",
                     "stairs_box", "hist2d_box", "pie_box", "fill_box"):
            getattr(self, name).pack_forget()
        if st in ("bar", "histogram"):
            self._show_bar_fields(st == "histogram")
        for name in self.SECTIONS.get(st, self.SECTIONS["line_symbol"]):
            getattr(self, name).pack(fill="x", pady=(10, 0))
        # a pie has one legend row per slice: a single text would be a lie
        pie = st == "pie"
        self.label_entry.configure(state="disabled" if pie else "normal")
        self.legend_hint.configure(text=self.PIE_LEGEND_HINT if pie
                                   else self.LEGEND_HINT)

    def _on_style_changed(self, _event=None):
        st = self.style_code()
        if st == "line":
            self.line_on_var.set(True)
            self.marker_on_var.set(False)
        elif st == "scatter":
            self.line_on_var.set(False)
            self.marker_on_var.set(True)
        elif st == "line_symbol":
            self.line_on_var.set(True)
            self.marker_on_var.set(True)
        elif st in ("bar", "histogram", "stairs", "hist2d", "pie"):
            # these draw an artist of their own instead of the curve
            self.line_on_var.set(False)
            self.marker_on_var.set(False)
        elif st in ERROR_STYLES:
            self.marker_on_var.set(True)
        self._update_section_visibility()
        self._apply()

    def _build_fill_box(self, line_color):
        box = self._section("Fill under the curve", self.fill_on_var,
                            pady=(10, 0))
        self.fill_box = box

        self._wide(ttk.Checkbutton(box, text="Same colour as the curve",
                                   variable=self.fill_follow_var,
                                   command=self._apply), 0, pady=(0, 4))
        # the colour of the area and how transparent it is belong together
        self.fill_color = ColorSwatch(box, self._fill.get("color", line_color),
                                      command=lambda _c: self._apply())
        self._pair(box, 1,
                   "Fill colour:", self.fill_color,
                   "Opacity (0-1):",
                   ttk.Spinbox(box, from_=0, to=1, increment=0.05,
                               width=SPIN_WIDTH,
                               textvariable=self.fill_alpha_var,
                               command=self._apply))
        self.fill_alpha_var.trace_add("write", self._apply)

        pattern = ttk.Combobox(box, textvariable=self.fill_hatch_var,
                               state="readonly", values=names(HATCH_PATTERNS),
                               width=22)
        ttk.Label(box, text="Pattern:").grid(row=2, column=0, sticky="w",
                                             padx=(0, 8), pady=3)
        pattern.grid(row=2, column=1, columnspan=3, sticky="w", pady=3)
        pattern.bind("<<ComboboxSelected>>", self._apply)

        self.fill_zero_check = self._wide(
            ttk.Checkbutton(box, text="Fill down to zero line",
                            variable=self.fill_zero_var, command=self._apply),
            3, pady=(4, 0))
        self._wide(ttk.Label(
            box, foreground="#666", justify="left",
            text="Switched off, the area is filled down to the axis."), 4)

    def _build_buttons(self):
        # pinned to the bottom of the window: the sections that appear and
        # disappear with the plot style are packed above it, never below
        bar = ttk.Frame(self.body)
        bar.pack(side="bottom", fill="x", pady=(12, 0))
        self.button_bar = bar
        ttk.Button(bar, text="Marker colour = line colour",
                   command=self._sync_colors).pack(side="left")
        ttk.Button(bar, text="Close", command=self.close).pack(side="right")

    # -- behaviour ---------------------------------------------------------
    def _sync_colors(self):
        color = self.line_color.color
        self.face_color.set_color(color)
        self.edge_color.set_color(color)
        self.bar_color.set_color(color)
        self.bar_edge_color.set_color(color)
        self.err_color.set_color(color)
        self._apply()

    def _apply(self, *_args):
        if self._loading:
            return
        # whatever changed on the diagram since this window last looked is
        # taken in first: only the field the user has just changed here is
        # sent back as the window has it
        self.mirror()
        line = self.line

        line.set_linestyle(code_of(LINE_STYLES, self.lstyle_var.get(), "-")
                           if self.line_on_var.get() else "none")
        line.set_linewidth(to_float(self.lwidth_var.get(), line.get_linewidth()))
        line.set_color(self.line_color.color)

        line.set_marker(code_of(MARKERS, self.mstyle_var.get(), "o")
                        if self.marker_on_var.get() else "None")
        line.set_markersize(to_float(self.msize_var.get(), line.get_markersize()))
        line.set_markerfacecolor("none" if self.hollow_var.get()
                                 else self.face_color.color)
        line.set_markeredgecolor(self.edge_color.color)
        line.set_markeredgewidth(to_float(self.mwidth_var.get(),
                                          line.get_markeredgewidth()))

        text = self.label_var.get().strip()
        if self.legend_on_var.get():
            if not text and self.column:     # switched on with an empty text
                self._loading = True         # the column name is a good start
                self.label_var.set(str(self.column))
                self._loading = False
                text = str(self.column)
            line.set_label(text if text else "_nolegend_")
        else:
            line.set_label("_nolegend_")
        if self.on_legend_style:
            self.on_legend_style(to_int(self.legend_size_var.get(), 10),
                                 self.legend_color.color)
        if self.on_fill:
            self.on_fill({
                "on": self.fill_on_var.get(),
                "follow": self.fill_follow_var.get(),
                "color": self.fill_color.color,
                "alpha": to_float(self.fill_alpha_var.get(), 0.35),
                "hatch": code_of(HATCH_PATTERNS, self.fill_hatch_var.get(), ""),
                "base": "zero" if self.fill_zero_var.get() else "bottom",
            })
        st_code = code_of(PLOT_STYLES, self.plot_style_var.get(), "line_symbol")
        if self.on_plot_style:
            self.on_plot_style(st_code)
        if self.on_bar_cfg:
            self.on_bar_cfg({
                "width": to_float(self.bar_width_var.get(), 0.8),
                "alpha": to_float(self.bar_alpha_var.get(), 0.85),
                "edgewidth": to_float(self.bar_edge_width_var.get(), 1.0),
                "color": self.bar_color.color,
                "edgecolor": self.bar_edge_color.color,
                "hatch": code_of(HATCH_PATTERNS, self.bar_hatch_var.get(), ""),
            })
        if self.on_histogram_cfg:
            # the same fields serve the histogram; only the number of bins
            # is its own
            self.on_histogram_cfg({
                "bins": max(1, min(to_int(self.hist_bins_var.get(),
                                          HISTOGRAM_BINS),
                                   MAX_HISTOGRAM_BINS)),
                "alpha": to_float(self.bar_alpha_var.get(), 0.85),
                "edgewidth": to_float(self.bar_edge_width_var.get(), 1.0),
                "color": self.bar_color.color,
                "edgecolor": self.bar_edge_color.color,
                "hatch": code_of(HATCH_PATTERNS, self.bar_hatch_var.get(), ""),
            })
        if self.on_stairs_cfg:
            self.on_stairs_cfg({
                "edges": code_of(STAIRS_EDGES, self.stairs_edges_var.get(), "mid"),
                "width": to_float(self.stairs_width_var.get(), 1.8),
                "fill": bool(self.stairs_fill_var.get()),
                "alpha": to_float(self.stairs_alpha_var.get(), 0.35),
                "hatch": code_of(HATCH_PATTERNS, self.stairs_hatch_var.get(), ""),
                "baseline": bool(self.stairs_base_var.get()),
                "color": self.stairs_color.color,
            })
        if self.on_hist2d_cfg:
            self.on_hist2d_cfg({
                "xbins": max(1, min(to_int(self.h2_xbins_var.get(),
                                           HIST2D_BINS), MAX_HIST2D_BINS)),
                "ybins": max(1, min(to_int(self.h2_ybins_var.get(),
                                           HIST2D_BINS), MAX_HIST2D_BINS)),
                "cmap": code_of(COLOR_MAPS, self.h2_cmap_var.get(), "viridis"),
                "alpha": to_float(self.h2_alpha_var.get(), 1.0),
                "colorbar": bool(self.h2_bar_var.get()),
                "hide_empty": bool(self.h2_empty_var.get()),
            })
        if self.on_pie_cfg:
            self.on_pie_cfg({
                "cmap": code_of(COLOR_MAPS, self.pie_cmap_var.get(), "tab10"),
                "labels": code_of(PIE_LABELS, self.pie_labels_var.get(), "column"),
                "names_on": bool(self.pie_names_on_var.get()),
                "start": to_float(self.pie_start_var.get(), PIE_START_ANGLE),
                "percent": bool(self.pie_percent_var.get()),
                "decimals": max(0, to_int(self.pie_decimals_var.get(), 1)),
                "hole": to_float(self.pie_hole_var.get(), 0.0),
                "explode": to_float(self.pie_explode_var.get(), 0.0),
                "label_size": max(4, to_int(self.pie_size_var.get(), 11)),
                "clockwise": bool(self.pie_clock_var.get()),
                "edgecolor": self.pie_edge_color.color,
                "edgewidth": to_float(self.pie_edge_width_var.get(), 1.0),
                "labeldistance": max(0.0, to_float(self.pie_name_at_var.get(),
                                                   PIE_LABEL_DISTANCE)),
                "pctdistance": max(0.0, to_float(self.pie_number_at_var.get(),
                                                 PIE_PCT_DISTANCE)),
                "rotate_labels": bool(self.pie_turn_names_var.get()),
                "rotate_numbers": bool(self.pie_turn_numbers_var.get()),
                "name_size": max(1, to_int(self.pie_name_size_var.get(), 11)),
                "name_color": self.pie_name_color.color,
                "pct_size": max(1, to_int(self.pie_number_size_var.get(), 11)),
                "pct_color": self.pie_number_color.color,
            })
        if self.on_error_cfg:
            self.on_error_cfg({
                "type": code_of(ERROR_SOURCES, self.err_type_var.get(), "pair"),
                "value": to_float(self.err_val_var.get(), 5.0),
                "column": self.err_col_var.get(),
                "capsize": to_float(self.err_capsize_var.get(), 4.0),
                "capthick": to_float(self.err_capthick_var.get(), 1.5),
                "elinewidth": to_float(self.err_elinewidth_var.get(), 1.5),
                "color": self.err_color.color,
            })
        self.on_change()


# --------------------------------------------------------------------------
# axes properties: one window, one tab per axis
# --------------------------------------------------------------------------

class AxisTab(DiagramMirror, PairedFields, ttk.Frame):
    """One page of the axes dialog (X or Y)."""

    def __init__(self, master, plot, which):
        super().__init__(master, padding=12)
        self.plot = plot
        self.which = which

        cfg = plot.axis_cfg[which]
        low, high = plot.current_limits(which)
        grid = cfg["grid"]

        self.label_var = tk.StringVar(value=plot.axis_label(which))
        self.label_size_var = tk.StringVar(value=str(cfg["label_size"]))
        self.tick_size_var = tk.StringVar(value=str(cfg["tick_size"]))
        self._label_color = cfg["label_color"]
        self._tick_color = cfg["tick_color"]
        self.label_pad_var = tk.StringVar(value=f"{cfg['label_pad']:g}")
        self.tick_pad_var = tk.StringVar(value=f"{cfg['tick_pad']:g}")
        self.auto_var = tk.BooleanVar(value=cfg["auto"])
        self.min_var = tk.StringVar(value=f"{low:g}")
        self.max_var = tk.StringVar(value=f"{high:g}")
        self.step_var = tk.StringVar(
            value="" if cfg["step"] in (None, 0) else f"{cfg['step']:g}")
        self.step_note_var = tk.StringVar(value="")
        self.minor_var = tk.StringVar(value=str(cfg["minor"]))
        # a number that means decades on a logarithmic axis and units on a
        # linear one is not the same number: each scale keeps its own, so
        # that switching between them does not leave 100 powers of ten
        self._kept_steps = {"linear": "", "log": "1"}
        self._kept_steps["log" if cfg["scale"] != "linear" else "linear"] = \
            self.step_var.get()
        self._axis_color = safe_hex(cfg.get("axis_color", "#000000"), "#000000")
        self.label_on_var = tk.BooleanVar(value=cfg.get("label_on", True))
        self.ticks_on_var = tk.BooleanVar(value=cfg.get("ticks_on", True))
        self.tick_labels_on_var = tk.BooleanVar(value=cfg.get("tick_labels_on", True))
        self.gmajor_var = tk.BooleanVar(value=grid["major"])
        self.gminor_var = tk.BooleanVar(value=grid["minor"])
        self.direction_var = tk.StringVar(
            value=self.direction_name(plot.axis_direction(which)))
        self.scale_var = tk.StringVar(
            value=name_of(AXIS_SCALES, plot.axis_scale(which), "Linear"))
        self.gstyle_var = tk.StringVar(value=name_of(GRID_STYLES, grid["style"], "Dotted"))
        self.gwidth_var = tk.StringVar(value=f"{grid['width']:g}")

        self._step_mode = "log" if cfg["scale"] != "linear" else "linear"
        self._build_top_box()
        self._build_label_box()
        self._build_range_box()
        self._build_grid_box(grid["color"])
        self._align_columns((self.label_box, self.range_box,
                             self.grid_box))
        self._toggle_auto()
        self._show_step_note()
        self.mirror(force=True)

    # -- following the diagram ---------------------------------------------
    def _diagram_fields(self):
        """Everything this page shows, as the axis has it right now."""
        plot, which = self.plot, self.which
        cfg = plot.axis_cfg[which]
        grid = cfg.get("grid") or {}
        step = cfg.get("step")
        return {
            "label": (self.label_var, str(plot.axis_label(which))),
            "label_size": (self.label_size_var,
                           field_number(cfg.get("label_size"), None)),
            "tick_size": (self.tick_size_var,
                          field_number(cfg.get("tick_size"), None)),
            "label_color": (SwatchField(self.label_color),
                            safe_hex(cfg.get("label_color"), None)),
            "tick_color": (SwatchField(self.tick_color),
                           safe_hex(cfg.get("tick_color"), None)),
            "label_pad": (self.label_pad_var,
                          field_number(cfg.get("label_pad"), None)),
            "tick_pad": (self.tick_pad_var,
                         field_number(cfg.get("tick_pad"), None)),
            "auto": (self.auto_var, bool(cfg.get("auto", True))),
            "step": (self.step_var, "" if step in (None, 0)
                     else field_number(step, None)),
            "minor": (self.minor_var, field_number(cfg.get("minor"), None)),
            "axis_color": (SwatchField(self.axis_color),
                           safe_hex(cfg.get("axis_color", "#000000"), None)),
            "label_on": (self.label_on_var, bool(cfg.get("label_on", True))),
            "ticks_on": (self.ticks_on_var, bool(cfg.get("ticks_on", True))),
            "tick_labels_on": (self.tick_labels_on_var,
                               bool(cfg.get("tick_labels_on", True))),
            "grid_major": (self.gmajor_var, bool(grid.get("major", False))),
            "grid_minor": (self.gminor_var, bool(grid.get("minor", False))),
            "direction": (self.direction_var,
                          self.direction_name(plot.axis_direction(which))),
            "scale": (self.scale_var,
                      name_of(AXIS_SCALES, plot.axis_scale(which), None)),
            "grid_style": (self.gstyle_var,
                           name_of(GRID_STYLES, grid.get("style"), None)),
            "grid_width": (self.gwidth_var,
                           field_number(grid.get("width"), None)),
            "grid_color": (SwatchField(self.grid_color),
                           safe_hex(grid.get("color"), None)),
        }

    def _mirrored(self, names):
        if "scale" in names:
            # the interval box counts decades on a logarithmic axis
            self._step_mode = "log" if self.scale_code() != "linear" \
                else "linear"
            self._kept_steps[self._step_mode] = self.step_var.get()
            self._show_step_note()
        elif "step" in names:
            self._kept_steps[self._step_mode] = self.step_var.get()
        if "auto" in names:
            self._toggle_auto()

    def mirror(self, force=False, only=None):
        """The fields, and the two ends of the range, as the axis has them."""
        changed = DiagramMirror.mirror(self, force, only)
        if only is None or "range" in only:
            if self.sync_range(force=force):
                changed.append("range")
        return changed

    # -- the direction of the axis and the scale of its numbers -----------
    def direction_names(self):
        """The three choices of the direction box of this axis."""
        return [AXIS_OFF_NAMES.get(self.which, "No axis"), "Standard",
                "Reverse"]

    def direction_name(self, code):
        """The words of one direction code, for this axis."""
        names = self.direction_names()
        return names[AXIS_DIRECTIONS.index(code)] \
            if code in AXIS_DIRECTIONS else names[1]

    def direction_code(self):
        """"off", "standard" or "reverse", as the box stands now."""
        try:
            return AXIS_DIRECTIONS[self.direction_names().index(
                self.direction_var.get())]
        except ValueError:
            return "standard"

    def _build_top_box(self):
        """The two choices that decide what the axis looks like at all."""
        box = ttk.Frame(self)
        box.pack(fill="x", pady=(0, 10))
        ttk.Label(box, text="Direction:").grid(row=0, column=0, sticky="w",
                                               padx=(0, 6))
        self.direction_box = ttk.Combobox(
            box, textvariable=self.direction_var, state="readonly",
            values=self.direction_names(), width=16)
        self.direction_box.grid(row=0, column=1, sticky="w")
        ttk.Label(box, text="Scale:").grid(row=0, column=2, sticky="w",
                                           padx=(18, 6))
        self.scale_box = ttk.Combobox(
            box, textvariable=self.scale_var, state="readonly",
            values=names(AXIS_SCALES), width=14)
        self.scale_box.grid(row=0, column=3, sticky="w")
        self.scale_box.bind("<<ComboboxSelected>>", self._scale_chosen)
        self.top_box = box
        return box

    def scale_code(self):
        """"linear", "log10", "log2" or "ln", as the box stands now."""
        return code_of(AXIS_SCALES, self.scale_var.get(), "linear")

    def _scale_chosen(self, _event=None):
        """Another scale: the interval means something else now.

        A hundred is a sensible interval between the ticks of a linear
        axis and an absurd one between powers of ten, so each scale keeps
        the number that was last typed for it and the note below the box
        says what that number counts.
        """
        wanted = "log" if self.scale_code() != "linear" else "linear"
        if wanted != self._step_mode:
            self._kept_steps[self._step_mode] = self.step_var.get()
            self.step_var.set(self._kept_steps.get(wanted, ""))
            self._step_mode = wanted
        self._show_step_note()
        return True

    def _show_step_note(self):
        """The line under the interval box: what the number counts."""
        scale = self.scale_code()
        self.step_note_var.set("" if scale == "linear"
                               else f"powers of {LOG_BASE_NAMES.get(scale, '10')}")
        return self.step_note_var.get()

    # -- construction ------------------------------------------------------
    def _section(self, title, variable, **pack):
        """A section whose title is its own check button."""
        box = ttk.LabelFrame(self, padding=8)
        if variable is not None:
            check = ttk.Checkbutton(box, text=title, variable=variable)
            box.configure(labelwidget=check)
        else:
            box.configure(text=title)
            check = None
        box.pack(fill="x", **pack)
        return box, check

    def _build_label_box(self):
        """The axis label: its text, its font and how far it sits."""
        box, check = self._section("Axis label and fonts", self.label_on_var)
        self.label_box, self.label_check = box, check
        ttk.Label(box, text="Label text:").grid(row=0, column=0, sticky="w",
                                                padx=(0, 8), pady=3)
        # the text field reaches across the whole section, so the colour of
        # the row below it does not get pushed to the far right
        ttk.Entry(box, textvariable=self.label_var, width=30).grid(
            row=0, column=1, columnspan=3, sticky="ew", pady=3)
        # the size and the colour of the label stand side by side
        self.label_color = ColorSwatch(box, self._label_color)
        self._pair(box, 1,
                   "Label font size:",
                   ttk.Spinbox(box, from_=4, to=48, increment=1, width=SPIN_WIDTH,
                               textvariable=self.label_size_var),
                   "Colour:", self.label_color)
        ToolDialog.field(box, 2, "Label offset [px]:",
                         ttk.Spinbox(box, from_=-200, to=400, increment=1,
                                     width=SPIN_WIDTH,
                                     textvariable=self.label_pad_var))

    def _build_range_box(self):
        """The numbers on the axis: their font, the range and the ticks."""
        box, check_section = self._section("Tick range, labels and fonts",
                                           self.ticks_on_var, pady=(10, 0))
        self.range_box, self.ticks_check = box, check_section
        # the size and the colour of the numbers stand side by side
        self.tick_color = ColorSwatch(box, self._tick_color)
        check = ttk.Checkbutton(box, text="Numbers font size:", variable=self.tick_labels_on_var)
        self._pair(box, 0,
                   check,
                   ttk.Spinbox(box, from_=4, to=48, increment=1, width=SPIN_WIDTH,
                               textvariable=self.tick_size_var),
                   "Colour:", self.tick_color)
        ToolDialog.field(box, 1, "Number offset [px]:",
                         ttk.Spinbox(box, from_=-200, to=400, increment=1,
                                     width=SPIN_WIDTH,
                                     textvariable=self.tick_pad_var))
        self._wide(ttk.Separator(box, orient="horizontal"), 2, pady=(8, 6))
        self._wide(ttk.Checkbutton(box, text="Automatic range and ticks",
                                   variable=self.auto_var,
                                   command=self._toggle_auto), 3, pady=(0, 4))
        # the two ends of the range share one line
        self.min_entry, self.max_entry = self._pair(
            box, 4,
            "From:", ttk.Entry(box, textvariable=self.min_var, width=ENTRY_WIDTH),
            "To:", ttk.Entry(box, textvariable=self.max_var, width=ENTRY_WIDTH))
        # the interval of the major ticks and the number of minor ones
        # between them belong together: one line
        self.step_entry, _minor = self._pair(
            box, 5,
            "Major ticks interval:",
            ttk.Entry(box, textvariable=self.step_var, width=ENTRY_WIDTH),
            "Minor ticks:",
            ttk.Spinbox(box, from_=0, to=20, increment=1, width=SPIN_WIDTH,
                        textvariable=self.minor_var))
        # what that number counts: nothing on a linear axis, powers on a
        # logarithmic one - which is the one thing a reader cannot guess
        self.step_note = ttk.Label(box, textvariable=self.step_note_var)
        self.step_note.grid(row=6, column=1, columnspan=3, sticky="w",
                            pady=(0, 2))
        self._wide(ttk.Separator(box, orient="horizontal"), 7, pady=(8, 6))
        self.axis_color = ColorSwatch(box, self._axis_color)
        ToolDialog.field(box, 8, "Axis colour:", self.axis_color)

    def _build_grid_box(self, color):
        """The grid: the section title switches the major lines on."""
        box, check = self._section("Grid of this axis", self.gmajor_var,
                                   pady=(10, 0))
        self.grid_box, self.grid_check = box, check
        ttk.Checkbutton(box, text="Minor grid lines", variable=self.gminor_var
                        ).grid(row=0, column=0, columnspan=4, sticky="w")
        # the style of the lines and their colour stand side by side
        self.grid_color = ColorSwatch(box, color)
        self._pair(box, 1,
                   "Style:",
                   ttk.Combobox(box, textvariable=self.gstyle_var,
                                state="readonly", values=names(GRID_STYLES),
                                width=ENTRY_WIDTH),
                   "Colour:", self.grid_color)
        ToolDialog.field(box, 2, "Width:",
                         ttk.Spinbox(box, from_=0.2, to=5, increment=0.2,
                                     width=SPIN_WIDTH,
                                     textvariable=self.gwidth_var))

    # -- behaviour ---------------------------------------------------------
    def _toggle_auto(self):
        automatic = bool(self.auto_var.get())
        state = "disabled" if automatic else "normal"
        for widget in (self.min_entry, self.max_entry, self.step_entry):
            widget.configure(state=state)
        # the two numbers follow the switch at once: turning the automatic
        # range on shows the range the data gives, turning it off starts
        # from the range that is on the screen.  Leaving the numbers of a
        # range that is no longer in force standing in the boxes is how a
        # dialog comes to say something the diagram does not.
        limits = (self.plot.automatic_limits(self.which) if automatic
                  else self.plot.current_limits(self.which))
        if limits is not None:
            self._show_range(*limits)

    def _show_range(self, low, high):
        """Put one range into the two boxes, if it is not already there."""
        try:
            wanted = (f"{float(low):g}", f"{float(high):g}")
        except (TypeError, ValueError):
            return False
        self._range_shown = wanted
        if (self.min_var.get(), self.max_var.get()) == wanted:
            return False
        self.min_var.set(wanted[0])
        self.max_var.set(wanted[1])
        return True

    def sync_range(self, force=False):
        """Show the range the axis really has at this moment.

        The boxes of an **automatic** axis are a report, not a setting:
        the axis works its two ends out from the data, and they change
        under an open dialog whenever the diagram does - new data, a curve
        moved to the other scale, a step of Undo, the zoom tool of the
        toolbar.  They are therefore read again every time the diagram is
        drawn.

        While the range is set **by hand** the boxes follow the axis too
        (a step of Undo may have given it other ends) - but only as long
        as nothing has been typed into them: numbers typed in belong to the
        user until Apply.  `force` (used right after Apply) reads them
        again anyway, so that what the axis took is what they show.
        """
        if not (force or self.auto_var.get()):
            typed = (self.min_var.get(), self.max_var.get())
            if typed != getattr(self, "_range_shown", None):
                return False
        try:
            low, high = self.plot.current_limits(self.which)
        except (AttributeError, TypeError, ValueError, tk.TclError):
            return False
        return self._show_range(low, high)

    def values(self):
        low, high = self.plot.current_limits(self.which)
        return {
            "auto": self.auto_var.get(),
            "min": to_float(self.min_var.get(), low),
            "max": to_float(self.max_var.get(), high),
            "step": to_float(self.step_var.get(), None),
            "minor": max(0, to_int(self.minor_var.get(), 0)),
            "label": self.label_var.get(),
            "label_size": to_int(self.label_size_var.get(), 11),
            "tick_size": to_int(self.tick_size_var.get(), 10),
            "label_color": self.label_color.color,
            "tick_color": self.tick_color.color,
            "label_pad": to_float(self.label_pad_var.get(), 5.5),
            "tick_pad": to_float(self.tick_pad_var.get(), 5.0),
            "axis_color": self.axis_color.color,
            "label_on": bool(self.label_on_var.get()),
            "ticks_on": bool(self.ticks_on_var.get()),
            "tick_labels_on": bool(self.tick_labels_on_var.get()),
            "direction": self.direction_code(),
            "scale": code_of(AXIS_SCALES, self.scale_var.get(), "linear"),
            "grid": {
                "major": self.gmajor_var.get(),
                "minor": self.gminor_var.get(),
                "color": self.grid_color.color,
                "style": code_of(GRID_STYLES, self.gstyle_var.get(), ":"),
                "width": to_float(self.gwidth_var.get(), 0.8),
            },
        }


class FrameTab(DiagramMirror, ttk.Frame):
    """Frame (spines) and the size/position of the axes on the page."""

    def __init__(self, master, plot):
        super().__init__(master, padding=12)
        self.plot = plot
        cfg = plot.frame_cfg

        self.style_var = tk.StringVar(
            value=name_of(FRAME_STYLES, cfg["style"], names(FRAME_STYLES)[0]))
        self.width_var = tk.StringVar(value=f"{cfg['width']:g}")
        self.major_len_var = tk.StringVar(value=f"{cfg['major_tick_length']:g}")
        self.minor_len_var = tk.StringVar(value=f"{cfg['minor_tick_length']:g}")
        background = cfg.get("background", "#ffffff")
        self.transparent_var = tk.BooleanVar(value=background == "none")
        # the paper around the plot area can be left away as well, which is
        # what makes a copied or saved picture transparent
        self.clear_figure_var = tk.BooleanVar(
            value=cfg.get("figure_background", "#ffffff") == "none")
        self.unit_var = tk.StringVar(value=SIZE_UNITS[0])
        self._unit = SIZE_UNITS[0]

        left, bottom, width, height = plot.ax.get_position().bounds
        self._fractions = {"left": left, "bottom": bottom,
                           "x_length": width, "y_length": height}
        self.value_vars = {key: tk.StringVar() for key in self._fractions}

        self._build_frame_box()
        self._build_background_box(cfg)
        self._build_size_box()
        self._show_values()
        self.mirror(force=True)

    # -- following the diagram ---------------------------------------------
    POSITION_KEYS = ("left", "bottom", "x_length", "y_length")

    def _diagram_fields(self):
        cfg = self.plot.frame_cfg
        background = cfg.get("background", "#ffffff")
        paper = cfg.get("figure_background", "#ffffff")
        fields = {
            "style": (self.style_var,
                      name_of(FRAME_STYLES, cfg.get("style", "none"), None)),
            "width": (self.width_var, field_number(cfg.get("width"), None)),
            "major_tick_length": (self.major_len_var,
                                  field_number(cfg.get("major_tick_length"),
                                               None)),
            "minor_tick_length": (self.minor_len_var,
                                  field_number(cfg.get("minor_tick_length"),
                                               None)),
            "transparent": (self.transparent_var, background == "none"),
            "background": (SwatchField(self.background),
                           None if background == "none"
                           else safe_hex(background, None)),
            "clear_figure": (self.clear_figure_var, paper == "none"),
            "figure_background": (SwatchField(self.figure_background),
                                  None if paper == "none"
                                  else safe_hex(paper, None)),
        }
        bounds = dict(zip(self.POSITION_KEYS,
                          self.plot.ax.get_position().bounds))
        for key, var in self.value_vars.items():
            fields[key] = (var, f"{bounds[key] * self._factor(key):.4g}")
        return fields

    def _mirrored(self, names):
        if any(key in names for key in self.POSITION_KEYS):
            self._read_values()
            self._show_hint()

    # -- construction ------------------------------------------------------
    def _build_frame_box(self):
        box = ttk.LabelFrame(self, text="Frame", padding=8)
        box.pack(fill="x")
        ToolDialog.field(box, 0, "Style:",
                         ttk.Combobox(box, textvariable=self.style_var,
                                      state="readonly", values=names(FRAME_STYLES),
                                      width=26))
        ToolDialog.field(box, 1, "Thickness:",
                         ttk.Spinbox(box, from_=0, to=10, increment=0.2, width=SPIN_WIDTH,
                                     textvariable=self.width_var))
        ToolDialog.field(box, 2, "Major tick length:",
                         ttk.Spinbox(box, from_=0, to=30, increment=0.5, width=SPIN_WIDTH,
                                     textvariable=self.major_len_var))
        ToolDialog.field(box, 3, "Minor tick length:",
                         ttk.Spinbox(box, from_=0, to=30, increment=0.5, width=SPIN_WIDTH,
                                     textvariable=self.minor_len_var))

    def _build_background_box(self, cfg):
        box = ttk.LabelFrame(self, text="Background", padding=8)
        box.pack(fill="x", pady=(10, 0))
        background = cfg.get("background", "#ffffff")
        self.background = ColorSwatch(
            box, "#ffffff" if background == "none" else background)
        ToolDialog.field(box, 0, "Plot area:", self.background)
        ToolDialog.field(box, 1, "",
                         ttk.Checkbutton(box, text="Transparent plot area",
                                         variable=self.transparent_var))
        figure_background = cfg.get("figure_background", "#ffffff")
        self.figure_background = ColorSwatch(
            box, "#ffffff" if figure_background == "none" else figure_background)
        ToolDialog.field(box, 2, "Around the axes:", self.figure_background)
        ToolDialog.field(box, 3, "",
                         ttk.Checkbutton(box, text="Transparent around the axes",
                                         variable=self.clear_figure_var))

    def _build_size_box(self):
        box = ttk.LabelFrame(self, text="Size and origin of the axes", padding=8)
        box.pack(fill="x", pady=(10, 0))

        units = ttk.Combobox(box, textvariable=self.unit_var, state="readonly",
                             values=SIZE_UNITS, width=COMBO_WIDTH)
        ToolDialog.field(box, 0, "Units:", units)
        units.bind("<<ComboboxSelected>>", self._change_unit)

        labels = [("x_length", "Width (length of the X axis):"),
                  ("y_length", "Height (length of the Y axis):"),
                  ("left", "Y axis distance from the left:"),
                  ("bottom", "X axis distance from the bottom:")]
        for row, (key, text) in enumerate(labels, start=1):
            ToolDialog.field(box, row, text,
                             ttk.Entry(box, textvariable=self.value_vars[key],
                                       width=ENTRY_WIDTH))
        ttk.Button(box, text="Default layout", command=self._reset).grid(
            row=5, column=1, sticky="w", pady=(6, 0))
        self.hint = ttk.Label(box, foreground="#666")
        self.hint.grid(row=6, column=0, columnspan=2, sticky="w", pady=(6, 0))

    # -- units -------------------------------------------------------------
    def _factor(self, key, unit=None):
        unit = unit or self._unit
        if unit == SIZE_UNITS[0]:
            return 1.0
        cm_size = self.plot.page_size          # the page, not the window
        size = cm_size[0] if key in ("left", "x_length") else cm_size[1]
        return size / 2.54 if unit == "inch" else size

    def _show_values(self):
        for key, var in self.value_vars.items():
            var.set(f"{self._fractions[key] * self._factor(key):.4g}")
        self._show_hint()

    def _show_hint(self):
        width_cm = self._fractions["x_length"] * self._factor("x_length", "cm")
        height_cm = self._fractions["y_length"] * self._factor("y_length", "cm")
        self.hint.configure(
            text=f"Current size on the page: {width_cm:.1f} x {height_cm:.1f} cm")

    def _read_values(self):
        for key, var in self.value_vars.items():
            value = to_float(var.get(), None)
            if value is not None:
                self._fractions[key] = value / self._factor(key)

    def _change_unit(self, _event=None):
        # the numbers the user has not touched are the diagram's own, in
        # another unit: they stay the diagram's (and keep following it)
        _seen, shown_then = self._mirror_book()
        untouched = [key for key, var in self.value_vars.items()
                     if var.get() == shown_then.get(key)]
        self._read_values()                 # still in the previous unit
        self._unit = self.unit_var.get()
        self._show_values()
        self.mirror_rebase(untouched)

    def _reset(self):
        self._fractions = dict(zip(("left", "bottom", "x_length", "y_length"),
                                   self.plot.default_position))
        self._show_values()

    def sync_position(self):
        """Read the place of the plot area again - it was dragged.

        Dragging the graph is the latest word of the user on where it
        stands, so it wins even over a number typed in and not applied.
        """
        left, bottom, width, height = self.plot.ax.get_position().bounds
        self._fractions = {"left": left, "bottom": bottom,
                           "x_length": width, "y_length": height}
        self._show_values()
        self.mirror(force=True, only=self.POSITION_KEYS)

    def sync_all(self):
        """Read the whole page again: the frame, the colours and the size.

        This page holds a copy of everything it shows, and what it holds is
        what `Apply` sends back to the diagram.  So whenever the diagram
        changes underneath it - `Resize graph`, an axis pulled by its end,
        a step of `Undo`, a file opened - the copy has to follow, or the
        next `Apply` would quietly put the old size and the old colours
        back alongside the one thing the user really changed.  A field
        the user is changing here is left as it is (see `DiagramMirror`).
        """
        try:
            self.mirror()
        except (tk.TclError, TypeError, ValueError):
            return False
        return True

    # -- result ------------------------------------------------------------
    def values(self):
        self._read_values()
        return {
            "style": code_of(FRAME_STYLES, self.style_var.get(), "none"),
            "width": max(0.0, to_float(self.width_var.get(), 1.0)),
            # the colour lives on the three axis pages now
            "color": self.plot.frame_cfg.get("color", "#000000"),
            "major_tick_length": max(0.0, to_float(self.major_len_var.get(), 3.5)),
            "minor_tick_length": max(0.0, to_float(self.minor_len_var.get(), 2.0)),
            "background": ("none" if self.transparent_var.get()
                           else self.background.color),
            "figure_background": ("none" if self.clear_figure_var.get()
                                  else self.figure_background.color),
            "left": self._fractions["left"], "bottom": self._fractions["bottom"],
            "x_length": self._fractions["x_length"],
            "y_length": self._fractions["y_length"],
        }


class AxesDialog(ToolDialog):
    """Both axes and the frame in a single window, selected with the tabs."""

    def __init__(self, master, plot, initial="x", on_close=None):
        super().__init__(master, "Axes properties", on_close=on_close)
        self.plot = plot

        notebook = ttk.Notebook(self.body)
        notebook.pack(fill="both", expand=True)
        # the title and the fonts first, then one page per axis
        self.title_tab = TitleTab(notebook, plot)
        notebook.add(self.title_tab, text="Title and fonts")
        self.tabs = {}
        for which, words in (("x", "X axis"), ("y", "Left Y axis"),
                             ("y2", "Right Y axis")):
            # the right hand page is always there: its Direction box says
            # whether that axis is drawn at all
            tab = AxisTab(notebook, plot, which)
            notebook.add(tab, text=words)
            self.tabs[which] = tab
        self.frame_tab = FrameTab(notebook, plot)
        notebook.add(self.frame_tab, text="Frame and origin")
        self.notebook = notebook
        self.select_tab(initial)

        bar = ttk.Frame(self.body)
        bar.pack(fill="x", pady=(12, 0))
        ttk.Button(bar, text="Apply", command=self.apply).pack(side="left")
        ttk.Button(bar, text="Close", command=self.close).pack(side="right")
        ttk.Button(bar, text="OK", command=self._ok).pack(side="right", padx=(0, 6))
        self.bind("<Return>", lambda _e: self.apply())

    def sync_ranges(self, force=False):
        """Let every axis page show the range its axis really has."""
        for tab in self.tabs.values():
            try:
                tab.sync_range(force=force)
            except tk.TclError:
                pass

    def pages(self):
        """The title page, the three axis pages and the frame page."""
        return [self.title_tab, *self.tabs.values(), self.frame_tab]

    def mirror(self, force=False):
        """Every page shows what the diagram says now (see `DiagramMirror`).

        A title or a label written on the graph itself, `Resize graph`, a
        step of Undo: all of it appears here while the window stays open,
        so that the next Apply does not put the old texts and sizes back.
        """
        changed = []
        for page in self.pages():
            try:
                changed.extend(page.mirror(force=force))
            except tk.TclError:
                pass
        return changed

    def select_tab(self, which):
        """which: 'title', 'x', 'y', 'y2' or 'frame'."""
        if which == "frame":
            self.notebook.select(self.frame_tab)
        elif which == "title":
            self.notebook.select(self.title_tab)
        else:
            self.notebook.select(self.tabs.get(which, self.tabs["x"]))

    def apply(self):
        """Everything the four pages say, in one step of Undo."""
        # anything changed on the diagram since the pages last looked comes
        # in first; what the user has changed here stays theirs
        self.mirror()
        with self.plot.changed("the axes and the frame"):
            return self._apply()

    def _apply(self):
        self.title_tab.apply()
        for which, tab in self.tabs.items():
            cfg = tab.values()
            if not cfg["auto"] and cfg["min"] == cfg["max"]:
                messagebox.showwarning(
                    "Axis range",
                    f"'From' and 'To' must be different on the "
                    f"{AXIS_NAMES.get(which, which.upper())}.", parent=self)
                return False
            self.plot.apply_axis(which, cfg, redraw=False)

        frame = self.frame_tab.values()
        problem = self.plot.check_frame(frame)
        if problem:
            messagebox.showwarning("Frame and origin", problem, parent=self)
            return False
        self.plot.apply_frame(frame, redraw=False)
        self.frame_tab._show_values()
        self.plot.draw()
        # an automatic axis has just worked its range out again, and a
        # range given by hand may have been tidied: the boxes show what
        # the axes took, never what they were asked for - and every other
        # field reads the diagram again as well
        self.mirror(force=True)
        return True

    def _ok(self):
        if self.apply():
            self.close()


class TextBoxDialog(DiagramMirror, ToolDialog):
    """A legend box or a free text box: text, font, frame and background.

    `source`, when given, tells what the diagram says now - (text, state),
    or None once the box is gone - so the window follows the box while
    it stands open (a text written on the graph, a box turned by its
    handle, `Resize graph`, Undo).
    """

    def __init__(self, master, title, text, state, on_apply, on_close=None,
                 hint=None, on_delete=None, rotation=False, source=None):
        super().__init__(master, title, on_close=on_close)
        self.on_apply = on_apply
        self.source = source
        self.on_delete = on_delete
        self.rotation = rotation
        self.angle_var = tk.StringVar(
            value=f"{float(state.get('angle', 0.0) or 0.0):g}")

        self.text_var = tk.StringVar(value=text)
        self.size_var = tk.StringVar(value=str(int(state.get("size", 10))))
        edge = state.get("edge", "#000000")
        face = state.get("face", "#ffffff")
        self.frame_var = tk.BooleanVar(value=edge != "none")
        self.transparent_var = tk.BooleanVar(value=face == "none")

        box = ttk.LabelFrame(self.body, text="Text", padding=8)
        box.pack(fill="x")
        entry = self.field(box, 0, "Text:",
                           ttk.Entry(box, textvariable=self.text_var, width=32))
        self.field(box, 1, "Font size:",
                   ttk.Spinbox(box, from_=4, to=72, increment=1, width=8,
                               textvariable=self.size_var, command=self.apply))
        self.color = ColorSwatch(box, state.get("color", "#000000"),
                                 command=lambda _c: self.apply())
        self.field(box, 2, "Font colour:", self.color)
        ttk.Label(box, text=hint or "An empty text hides this box.",
                  foreground="#666", justify="left").grid(
            row=3, column=0, columnspan=2, sticky="w", pady=(4, 0))

        # the name of the section is its own check button: no frame when off
        frame_box = ttk.LabelFrame(self.body, padding=8)
        frame_check = ttk.Checkbutton(frame_box, text="Surrounding box",
                                      variable=self.frame_var,
                                      command=self.apply)
        frame_box.configure(labelwidget=frame_check)
        frame_box.pack(fill="x", pady=(10, 0))
        self.frame_check = frame_check
        self.edge_color = ColorSwatch(frame_box, "#000000" if edge == "none" else edge,
                                      command=lambda _c: self.apply())
        self.field(frame_box, 0, "Frame colour:", self.edge_color)
        self.face_color = ColorSwatch(frame_box,
                                      "#ffffff" if face == "none" else face,
                                      command=lambda _c: self.apply())
        self.field(frame_box, 1, "Background colour:", self.face_color)
        self.field(frame_box, 2, "",
                   ttk.Checkbutton(frame_box, text="Transparent background",
                                   variable=self.transparent_var,
                                   command=self.apply))
        ttk.Label(frame_box, text="Drag the box with the pointer to move it.",
                  foreground="#666").grid(row=3, column=0, columnspan=2,
                                          sticky="w", pady=(4, 0))

        if rotation:
            turn = ttk.LabelFrame(self.body, text="Rotation", padding=8)
            turn.pack(fill="x", pady=(10, 0))
            self.field(turn, 0, "Angle [deg]:",
                       ttk.Spinbox(turn, from_=-360, to=360, increment=5,
                                   width=8, textvariable=self.angle_var,
                                   command=self.apply))
            ttk.Button(turn, text="Upright",
                       command=lambda: (self.angle_var.set("0"),
                                        self.apply())).grid(row=0, column=2,
                                                            padx=(8, 0))
            ttk.Label(turn, foreground="#666", justify="left",
                      text="Or drag the round handle above the box\n"
                           "(Shift: 15 degree steps).").grid(
                row=1, column=0, columnspan=3, sticky="w", pady=(4, 0))

        bar = ttk.Frame(self.body)
        bar.pack(fill="x", pady=(12, 0))
        ttk.Button(bar, text="Apply", command=self.apply).pack(side="left")
        if on_delete is not None:
            ttk.Button(bar, text="Delete", command=self._delete).pack(side="left",
                                                                      padx=(6, 0))
        ttk.Button(bar, text="Close", command=self.close).pack(side="right")
        ttk.Button(bar, text="OK", command=self._ok).pack(side="right", padx=(0, 6))
        self.bind("<Return>", lambda _e: self.apply())
        entry.focus_set()
        entry.select_range(0, "end")
        self.mirror(force=True)

    def _diagram_fields(self):
        now = self.source() if self.source is not None else None
        if now is None:
            return {}
        text, state = now
        edge = state.get("edge", "#000000")
        face = state.get("face", "#ffffff")
        fields = {
            "text": (self.text_var, str(text)),
            "size": (self.size_var, field_number(state.get("size"), None)),
            "color": (SwatchField(self.color),
                      safe_hex(state.get("color"), None)),
            "frame": (self.frame_var, edge != "none"),
            "edge": (SwatchField(self.edge_color),
                     None if edge == "none" else safe_hex(edge, None)),
            "transparent": (self.transparent_var, face == "none"),
            "face": (SwatchField(self.face_color),
                     None if face == "none" else safe_hex(face, None)),
        }
        if self.rotation:
            fields["angle"] = (self.angle_var, field_number(
                float(state.get("angle", 0.0) or 0.0) % 360.0, None))
        return fields

    def values(self):
        values = {
            "text": self.text_var.get(),
            "size": to_int(self.size_var.get(), 10),
            "color": self.color.color,
            "edge": self.edge_color.color if self.frame_var.get() else "none",
            "face": "none" if self.transparent_var.get() else self.face_color.color,
        }
        if self.rotation:
            values["angle"] = to_float(self.angle_var.get(), 0.0) % 360.0
        return values

    def apply(self):
        self.mirror()           # catch up with the diagram first
        self.on_apply(self.values())

    def _delete(self):
        if self.on_delete:
            self.on_delete()
        self.close()

    def _ok(self):
        self.apply()
        self.close()


class TitleTab(DiagramMirror, ttk.Frame):
    """The title of the diagram and the fonts that belong to no axis.

    It is one page of the axes dialog and the whole of the `Title and
    fonts` window, so that both show exactly the same settings.
    """

    def __init__(self, master, plot, padding=12):
        super().__init__(master, padding=padding)
        self.plot = plot

        self.title_var = tk.StringVar(value=plot.ax.get_title())
        self.title_size_var = tk.StringVar(value=str(plot.fonts["title"]))
        self.legend_size_var = tk.StringVar(value=str(plot.fonts["legend"]))
        self.legend_loc_var = tk.StringVar(value=plot.legend_loc)
        self.legend_visible_var = tk.BooleanVar(value=plot.legend_visible)
        self.title_pad_var = tk.StringVar(value=f"{plot.fonts['title_pad']:g}")

        field = ToolDialog.field
        box = ttk.LabelFrame(self, text="Title", padding=8)
        box.pack(fill="x")
        field(box, 0, "Text:", ttk.Entry(box, textvariable=self.title_var,
                                         width=34))
        field(box, 1, "Font size:",
              ttk.Spinbox(box, from_=4, to=48, increment=1, width=SPIN_WIDTH,
                          textvariable=self.title_size_var))
        self.title_color = ColorSwatch(
            box, safe_hex(plot.fonts["title_color"], "#000000"))
        field(box, 2, "Font colour:", self.title_color)
        field(box, 3, "Distance from the axes [px]:",
              ttk.Spinbox(box, from_=-200, to=400, increment=1, width=SPIN_WIDTH,
                          textvariable=self.title_pad_var))
        ttk.Button(box, text="Reset dragged texts",
                   command=plot.reset_text_offsets).grid(row=4, column=1,
                                                         sticky="w",
                                                         pady=(6, 0))

        legend_box = ttk.LabelFrame(self, text="Legend boxes", padding=8)
        legend_box.pack(fill="x", pady=(10, 0))
        field(legend_box, 0, "",
              ttk.Checkbutton(legend_box, text="Show legends",
                              variable=self.legend_visible_var))
        field(legend_box, 1, "Font size (all):",
              ttk.Spinbox(legend_box, from_=4, to=72, increment=1, width=SPIN_WIDTH,
                          textvariable=self.legend_size_var))
        self.legend_color = ColorSwatch(
            legend_box, safe_hex(plot.fonts["legend_color"], "#000000"),
            command=lambda _c: self._touch_legend("color"))
        field(legend_box, 2, "Font colour (all):", self.legend_color)
        field(legend_box, 3, "Start position:",
              ttk.Combobox(legend_box, textvariable=self.legend_loc_var,
                           state="readonly", values=LEGEND_LOCATIONS, width=COMBO_WIDTH))
        ttk.Button(legend_box, text="Reset positions",
                   command=self._reset_positions).grid(row=4, column=1,
                                                       sticky="w", pady=(6, 0))
        self.title_box, self.legend_box = box, legend_box
        # "(all)" means all the legend boxes - when the user sets it here.
        # Which of the two was set is noted, so that an Apply made for
        # anything else does not flatten the sizes given in curve windows.
        self._legend_touched = set()
        self._quiet = False
        self.legend_size_var.trace_add(
            "write", lambda *_a: self._touch_legend("size"))
        self.mirror(force=True)

    def _touch_legend(self, what):
        if not self._quiet:
            self._legend_touched.add(what)

    def mirror(self, force=False, only=None):
        quiet, self._quiet = self._quiet, True      # the diagram speaking
        try:
            return DiagramMirror.mirror(self, force, only)
        finally:
            self._quiet = quiet

    def _diagram_fields(self):
        plot = self.plot
        fonts = plot.fonts
        return {
            "title": (self.title_var, str(plot.ax.get_title())),
            "title_size": (self.title_size_var,
                           field_number(fonts.get("title"), None)),
            "title_color": (SwatchField(self.title_color),
                            safe_hex(fonts.get("title_color"), None)),
            "title_pad": (self.title_pad_var,
                          field_number(fonts.get("title_pad"), None)),
            "legend_size": (self.legend_size_var,
                            field_number(fonts.get("legend"), None)),
            "legend_color": (SwatchField(self.legend_color),
                             safe_hex(fonts.get("legend_color"), None)),
            "legend_loc": (self.legend_loc_var, str(plot.legend_loc)),
            "legend_visible": (self.legend_visible_var,
                               bool(plot.legend_visible)),
        }

    def apply(self):
        plot = self.plot
        plot.fonts["title"] = to_int(self.title_size_var.get(),
                                     plot.fonts["title"])
        plot.fonts["title_color"] = self.title_color.color
        size = to_int(self.legend_size_var.get(), plot.fonts["legend"])
        color = self.legend_color.color
        # one size and one colour for all the legend boxes - when they are
        # set here.  Applying this window for anything else leaves a legend
        # that was given a size of its own in its curve window alone.
        touched = getattr(self, "_legend_touched", {"size", "color"})
        new_size = "size" in touched or size != plot.fonts["legend"]
        new_color = ("color" in touched
                     or safe_hex(color) != safe_hex(plot.fonts["legend_color"]))
        touched.clear()
        plot.fonts["legend"] = size
        plot.fonts["legend_color"] = color
        for state in plot.legend_state.values():
            if new_size:
                state["size"] = size
            if new_color:
                state["color"] = color
        plot.legend_loc = self.legend_loc_var.get()
        plot.legend_visible = self.legend_visible_var.get()
        plot.fonts["title_pad"] = to_float(self.title_pad_var.get(),
                                           plot.fonts["title_pad"])
        plot.ax.set_title(self.title_var.get(), fontsize=plot.fonts["title"],
                          color=plot.fonts["title_color"],
                          pad=plot.page_points(plot.fonts["title_pad"]))
        plot.ax.title.set_picker(True)
        plot.apply_text_offset("title")
        plot.refresh_legend()
        return True

    def _reset_positions(self):
        self.plot.legend_loc = self.legend_loc_var.get()
        self.plot.reset_legend_positions()


class TitleFontDialog(ToolDialog):
    """Plot title text and the font sizes that do not belong to an axis."""

    # the fields the window lends from its page, so that everything that
    # knows the window keeps working
    SHARED = ("title_var", "title_size_var", "title_pad_var", "title_color",
              "legend_size_var", "legend_loc_var", "legend_visible_var",
              "legend_color")

    def __init__(self, master, plot, on_close=None):
        super().__init__(master, "Title and fonts", on_close=on_close)
        self.plot = plot
        self.tab = TitleTab(self.body, plot, padding=0)
        self.tab.pack(fill="both", expand=True)
        for name in self.SHARED:
            setattr(self, name, getattr(self.tab, name))

        bar = ttk.Frame(self.body)
        bar.pack(fill="x", pady=(12, 0))
        ttk.Button(bar, text="Apply", command=self.apply).pack(side="left")
        ttk.Button(bar, text="Close", command=self.close).pack(side="right")
        self.bind("<Return>", lambda _e: self.apply())

    def mirror(self, force=False):
        """The page follows the diagram while the window stands open."""
        return self.tab.mirror(force=force)

    def apply(self):
        self.mirror()            # take in what changed on the diagram
        with self.plot.changed("the title and the fonts"):
            self.tab.apply()
            self.plot.draw()
        self.mirror(force=True)
        return True

    def _reset_positions(self):
        self.tab._reset_positions()


# --------------------------------------------------------------------------
# excel formula engine & column operations
# --------------------------------------------------------------------------

def col_to_letter(col_idx: int) -> str:
    """Convert 0-based column index to Excel column letter (0->A, 25->Z, 26->AA)."""
    result = []
    col_idx += 1
    while col_idx > 0:
        col_idx, remainder = divmod(col_idx - 1, 26)
        result.append(chr(65 + remainder))
    return "".join(reversed(result))


def letter_to_col(letters: str) -> int:
    """Convert Excel column letter to 0-based index (A->0, Z->25, AA->26)."""
    result = 0
    for ch in str(letters).upper().strip():
        if 'A' <= ch <= 'Z':
            result = result * 26 + (ord(ch) - ord('A') + 1)
    return max(0, result - 1)


REF_PATTERN = re.compile(r'(\$?)([A-Za-z]+)(\$?)(\d+)')
# a cell reference *inside a formula*: not a piece of a longer word, and not
# the name of a function that happens to end in digits (log10, log2)
CELL_IN_FORMULA = re.compile(
    r'(?<![A-Za-z0-9_"\'])(\$?)([A-Za-z]+)(\$?)(\d+)'
    r'(?![A-Za-z0-9_"\'])(?!\s*\()')
# an error left in a formula by a deleted row or column
BROKEN_REF = re.compile(r'#[A-Za-z]+[!?]')


def renumber_formula_rows(formula: str, at_row: int, delta: int) -> str:
    """Move the row references of a formula when rows come or go.

    `at_row` is the **1-based** row where the change happens and `delta`
    how many rows appear (positive) or disappear (negative).  A reference
    to that row, or to one below it, moves with its data - the fixed ones
    (`$A$14`) as well, because it is the values themselves that moved.  A
    reference to a row that was deleted becomes `#REF!`.
    """
    def repl(match):
        col_fixed, letters, row_fixed, digits = match.groups()
        row = int(digits)
        if row < at_row:
            return match.group(0)
        if delta < 0 and row < at_row - delta:
            return "#REF!"
        return f"{col_fixed}{letters}{row_fixed}{row + delta}"

    return CELL_IN_FORMULA.sub(repl, formula)


def renumber_formula_columns(formula: str, at_col: int, delta: int) -> str:
    """The same for the columns; `at_col` is 0-based, as in the table."""
    def repl(match):
        col_fixed, letters, row_fixed, digits = match.groups()
        index = letter_to_col(letters.upper())
        if index < at_col:
            return match.group(0)
        if delta < 0 and index < at_col - delta:
            return "#REF!"
        return (f"{col_fixed}{col_to_letter(index + delta)}"
                f"{row_fixed}{digits}")

    return CELL_IN_FORMULA.sub(repl, formula)


def adjust_formula_references(formula: str, delta_row: int, delta_col: int = 0) -> str:
    """Adjust unanchored cell references in an Excel formula when filling or copying."""
    def repl(match):
        col_fixed = bool(match.group(1))
        col_letters = match.group(2).upper()
        row_fixed = bool(match.group(3))
        row_num = int(match.group(4))

        new_col = col_letters
        if not col_fixed and delta_col != 0:
            c_idx = max(0, letter_to_col(col_letters) + delta_col)
            new_col = col_to_letter(c_idx)

        new_row = row_num
        if not row_fixed and delta_row != 0:
            new_row = max(1, row_num + delta_row)

        c_prefix = "$" if col_fixed else ""
        r_prefix = "$" if row_fixed else ""
        return f"{c_prefix}{new_col}{r_prefix}{new_row}"

    return CELL_IN_FORMULA.sub(repl, formula)


RANDOM_IN_FORMULA = re.compile(r"\brandn?\s*\(", re.IGNORECASE)


def new_random_seed():
    """A fresh seed for the random numbers of one sheet."""
    return int(np.random.SeedSequence().entropy % (1 << 63))


class FormulaEvaluator:
    """Safe AST-based Excel formula evaluator with full mathematical and range support."""

    SAFE_FUNCS = {
        'sin': math.sin, 'cos': math.cos, 'tan': math.tan,
        'asin': math.asin, 'acos': math.acos, 'atan': math.atan,
        'sinh': math.sinh, 'cosh': math.cosh, 'tanh': math.tanh,
        'sqrt': math.sqrt, 'exp': math.exp,
        'log': math.log, 'ln': math.log, 'log10': math.log10, 'log2': math.log2,
        'abs': abs, 'round': round, 'floor': math.floor, 'ceil': math.ceil,
        'mod': lambda a, b: a % b, 'power': pow,
        'pi': lambda: math.pi, 'e': lambda: math.e,
        'radians': math.radians, 'degrees': math.degrees,
        'if': lambda cond, a, b: a if cond else b,
        'sum': lambda vals: float(sum(v for v in vals if not math.isnan(v))) if len(vals) else 0.0,
        'average': lambda vals: (float(sum(v for v in vals if not math.isnan(v))) / len([v for v in vals if not math.isnan(v)])) if any(not math.isnan(v) for v in vals) else 0.0,
        'mean': lambda vals: (float(sum(v for v in vals if not math.isnan(v))) / len([v for v in vals if not math.isnan(v)])) if any(not math.isnan(v) for v in vals) else 0.0,
        'min': lambda vals: float(min(v for v in vals if not math.isnan(v))) if any(not math.isnan(v) for v in vals) else 0.0,
        'max': lambda vals: float(max(v for v in vals if not math.isnan(v))) if any(not math.isnan(v) for v in vals) else 0.0,
        'count': lambda vals: float(len([v for v in vals if not math.isnan(v)])),
        'std': lambda vals: float(math.sqrt(sum((x - sum(vals)/len(vals))**2 for x in vals)/(len(vals)-1))) if len(vals) > 1 else 0.0,
        'stdev': lambda vals: float(math.sqrt(sum((x - sum(vals)/len(vals))**2 for x in vals)/(len(vals)-1))) if len(vals) > 1 else 0.0,
        'median': lambda vals: float(sorted(vals)[len(vals)//2]) if len(vals) else 0.0,
    }

    # names that stand for a number on their own, so that a formula such as
    # =sin((B1+C1)+pi/6) means what it says
    CONSTANTS = {'pi': math.pi, 'tau': math.tau, 'e': math.e}
    # ... but a bare column letter always wins over a constant: in a sheet
    # with five columns "e" is column E of the current row
    LETTER_CONSTANTS = ('e',)

    # the two random functions: RAND() / RAND(low, high) is uniform,
    # RANDN() / RANDN(mean, sd) is normal.  They are handled apart from the
    # other functions because their number depends on the cell they stand in.
    RANDOM_FUNCS = ('rand', 'randn')

    def __init__(self, df: pd.DataFrame, cell_formulas: dict, seed=0):
        self.df = df
        self.cell_formulas = cell_formulas
        self._eval_stack = set()
        # every sheet has a seed of its own: RAND() in a cell is drawn from
        # the seed, the row, the column and which RAND() of the formula it
        # is.  So a number stays what it is when the sheet is worked out
        # again (after any edit, Undo, opening the file), a formula filled
        # down gives a different number in every row, and `New random
        # numbers` (F9) draws them all anew by changing the seed.
        self.seed = abs(int(seed or 0)) % (1 << 63)
        self._random_calls = []        # how many were drawn, per formula

    def random_value(self, name, args, row, col):
        """One number of RAND or RANDN, in the cell (row, col)."""
        if self._random_calls:
            count = self._random_calls[-1]
            self._random_calls[-1] = count + 1
        else:
            count = 0
        for value in args:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError("#VALUE!")
        generator = np.random.default_rng(
            [self.seed, max(0, int(row)), max(0, int(col)), count,
             1 if name == 'randn' else 0])
        if name == 'rand':
            if len(args) not in (0, 2):
                raise ValueError("#VALUE!")
            low, high = (0.0, 1.0) if not args else (float(args[0]),
                                                     float(args[1]))
            return low + (high - low) * float(generator.random())
        if len(args) not in (0, 2):
            raise ValueError("#VALUE!")
        mean, spread = (0.0, 1.0) if not args else (float(args[0]),
                                                    float(args[1]))
        if spread < 0:
            raise ValueError("#NUM!")
        return mean + spread * float(generator.standard_normal())

    def get_cell_value(self, row: int, col: int):
        if (row, col) in self._eval_stack:
            raise ValueError("#CYCLE!")
        if not (0 <= row < len(self.df) and 0 <= col < len(self.df.columns)):
            raise ValueError("#REF!")

        if (row, col) in self.cell_formulas:
            formula = self.cell_formulas[(row, col)]
            self._eval_stack.add((row, col))
            try:
                val = self.evaluate(formula, row, col)
            finally:
                self._eval_stack.discard((row, col))
            return val
        else:
            raw = self.df.iat[row, col]
            if raw == "" or raw is None or pd.isna(raw):
                return 0.0
            try:
                return float(raw)
            except (ValueError, TypeError):
                return str(raw)

    def get_range_values(self, start_ref: str, end_ref: str):
        m1 = REF_PATTERN.match(start_ref)
        m2 = REF_PATTERN.match(end_ref)
        if not m1 or not m2:
            raise ValueError("#REF!")
        c0 = letter_to_col(m1.group(2))
        r0 = int(m1.group(4)) - 1
        c1 = letter_to_col(m2.group(2))
        r1 = int(m2.group(4)) - 1

        c_start, c_end = sorted((c0, c1))
        r_start, r_end = sorted((r0, r1))

        values = []
        for r in range(r_start, r_end + 1):
            for c in range(c_start, c_end + 1):
                try:
                    val = self.get_cell_value(r, c)
                    if isinstance(val, (int, float)):
                        v = float(val)
                        if not math.isnan(v) and not math.isinf(v):
                            values.append(v)
                except Exception:
                    pass
        return values

    def evaluate(self, expr_str: str, current_row: int = 0, current_col: int = 0):
        s = str(expr_str).strip()
        if s.startswith("="):
            s = s[1:].strip()
        if not s:
            return ""

        # a reference that a deleted row or column has broken says so
        broken = BROKEN_REF.search(s)
        if broken:
            return broken.group(0).upper()

        # Replace ^ with ** for power, and <> with !=
        s = s.replace("^", "**")
        s = s.replace("<>", "!=")

        # Replace range arguments: e.g. SUM(A1:A5) -> SUM(__range__("A1", "A5"))
        range_re = re.compile(r'([A-Za-z_][A-Za-z0-9_]*)\s*\(\s*(\$?[A-Za-z]+\$?\d+)\s*:\s*(\$?[A-Za-z]+\$?\d+)\s*\)', re.IGNORECASE)
        s = range_re.sub(r'\1(__range__("\2", "\3"))', s)

        # Replace column name references in brackets e.g. [X], [Y1] with cell in current row
        cols = [str(c) for c in self.df.columns]
        for c_idx, c_name in enumerate(cols):
            c_letter = col_to_letter(c_idx)
            s = s.replace(f"[{c_name}]", f"{c_letter}{current_row + 1}")

        # Replace single cell references with __cell__("A1").  A function
        # whose name ends in digits (log10, log2) is not a cell reference,
        # so a name followed by "(" is left alone.
        s = CELL_IN_FORMULA.sub(r'__cell__("\1\2\3\4")', s)

        # Parse AST
        try:
            tree = ast.parse(s, mode='eval')
        except SyntaxError:
            return "#ERROR!"

        was_in_stack = (current_row, current_col) in self._eval_stack
        if not was_in_stack:
            self._eval_stack.add((current_row, current_col))
        self._random_calls.append(0)    # the RAND()s of this formula count anew
        try:
            res = self._eval_ast(tree.body, current_row, current_col)
            if isinstance(res, str) and res.startswith("#"):
                return res
            if isinstance(res, (int, float)):
                res = float(res)
                if math.isnan(res):
                    return "#NUM!"
                if math.isinf(res):
                    return "#DIV/0!"
                if res.is_integer():
                    return int(res)
                return round(res, 8)
            return res
        except ZeroDivisionError:
            return "#DIV/0!"
        except ValueError as err:
            err_msg = str(err)
            return err_msg if err_msg.startswith("#") else "#VALUE!"
        except Exception:
            return "#VALUE!"
        finally:
            self._random_calls.pop()
            if not was_in_stack:
                self._eval_stack.discard((current_row, current_col))

    def _eval_ast(self, node, current_row, current_col):
        if isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            name = node.id.lower()
            cols_lower = [str(c).lower() for c in self.df.columns]
            # a constant used as a value (pi, e, tau) comes first, so that
            # "pi/6" is a number and not the function pi() divided by six -
            # unless the sheet really has a column of that name, or the
            # letter is a column letter (E is column 5)
            if name in self.CONSTANTS:
                if name in cols_lower:
                    return self.get_cell_value(current_row,
                                               cols_lower.index(name))
                if name in self.LETTER_CONSTANTS:
                    c_idx = letter_to_col(name)
                    if 0 <= c_idx < len(self.df.columns):
                        return self.get_cell_value(current_row, c_idx)
                return self.CONSTANTS[name]
            if name in self.SAFE_FUNCS:
                return self.SAFE_FUNCS[name]
            elif name in ('true', 'false'):
                return name == 'true'
            # If name is a column name or column letter, resolve for current row
            if name in cols_lower:
                c_idx = cols_lower.index(name)
                return self.get_cell_value(current_row, c_idx)
            # Check single letter column (A, B, C...)
            if len(name) <= 2 and name.isalpha():
                c_idx = letter_to_col(name)
                if 0 <= c_idx < len(self.df.columns):
                    return self.get_cell_value(current_row, c_idx)
            raise ValueError(f"#NAME? ({node.id})")
        elif isinstance(node, ast.UnaryOp):
            val = self._eval_ast(node.operand, current_row, current_col)
            if isinstance(val, str) and val.startswith("#"):
                return val
            if isinstance(node.op, ast.UAdd):
                return +val
            elif isinstance(node.op, ast.USub):
                return -val
            elif isinstance(node.op, ast.Not):
                return not val
        elif isinstance(node, ast.BinOp):
            left = self._eval_ast(node.left, current_row, current_col)
            if isinstance(left, str) and left.startswith("#"):
                return left
            right = self._eval_ast(node.right, current_row, current_col)
            if isinstance(right, str) and right.startswith("#"):
                return right
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                if right == 0:
                    raise ZeroDivisionError("#DIV/0!")
                return left / right
            elif isinstance(node.op, ast.FloorDiv):
                if right == 0:
                    raise ZeroDivisionError("#DIV/0!")
                return left // right
            elif isinstance(node.op, ast.Mod):
                if right == 0:
                    raise ZeroDivisionError("#DIV/0!")
                return left % right
            elif isinstance(node.op, ast.Pow):
                return left ** right
        elif isinstance(node, ast.Compare):
            left = self._eval_ast(node.left, current_row, current_col)
            if isinstance(left, str) and left.startswith("#"):
                return left
            for op, comparator in zip(node.ops, node.comparators):
                right = self._eval_ast(comparator, current_row, current_col)
                if isinstance(right, str) and right.startswith("#"):
                    return right
                if isinstance(op, ast.Eq):
                    if not (left == right): return False
                elif isinstance(op, ast.NotEq):
                    if not (left != right): return False
                elif isinstance(op, ast.Lt):
                    if not (left < right): return False
                elif isinstance(op, ast.LtE):
                    if not (left <= right): return False
                elif isinstance(op, ast.Gt):
                    if not (left > right): return False
                elif isinstance(op, ast.GtE):
                    if not (left >= right): return False
                left = right
            return True
        elif isinstance(node, ast.Call):
            func = None
            if isinstance(node.func, ast.Name):
                fname = node.func.id.lower()
                if fname == '__cell__':
                    ref = self._eval_ast(node.args[0], current_row, current_col)
                    m = REF_PATTERN.match(ref)
                    if not m: raise ValueError("#REF!")
                    col = letter_to_col(m.group(2))
                    row = int(m.group(4)) - 1
                    return self.get_cell_value(row, col)
                elif fname == '__range__':
                    r1 = self._eval_ast(node.args[0], current_row, current_col)
                    r2 = self._eval_ast(node.args[1], current_row, current_col)
                    return self.get_range_values(r1, r2)
                elif fname in self.RANDOM_FUNCS:
                    args = [self._eval_ast(a, current_row, current_col)
                            for a in node.args]
                    for a in args:
                        if isinstance(a, str) and a.startswith("#"):
                            return a
                    return self.random_value(fname, args, current_row,
                                             current_col)
                elif fname in self.SAFE_FUNCS:
                    func = self.SAFE_FUNCS[fname]
                else:
                    raise ValueError(f"#NAME? ({fname})")
            else:
                func = self._eval_ast(node.func, current_row, current_col)

            args = [self._eval_ast(a, current_row, current_col) for a in node.args]
            for a in args:
                if isinstance(a, str) and a.startswith("#"):
                    return a
            return func(*args)
        elif isinstance(node, ast.IfExp):
            cond = self._eval_ast(node.test, current_row, current_col)
            if isinstance(cond, str) and cond.startswith("#"):
                return cond
            return self._eval_ast(node.body, current_row, current_col) if cond else self._eval_ast(node.orelse, current_row, current_col)

        raise ValueError("#EXPR!")


def eval_column_math(df: pd.DataFrame, expr_str: str):
    """Evaluate a mathematical expression across columns, supporting numpy/vector functions."""
    s = str(expr_str).strip()
    if s.startswith("="):
        s = s[1:].strip()
    if not s:
        return np.zeros(len(df))

    s = s.replace("^", "**")
    s = s.replace("<>", "!=")

    context = {
        'np': np, 'math': math,
        'sin': np.sin, 'cos': np.cos, 'tan': np.tan,
        'asin': np.arcsin, 'acos': np.arccos, 'atan': np.arctan,
        'sinh': np.sinh, 'cosh': np.cosh, 'tanh': np.tanh,
        'sqrt': np.sqrt, 'exp': np.exp,
        'log': np.log, 'ln': np.log, 'log10': np.log10, 'log2': np.log2,
        'abs': np.abs, 'round': np.round, 'floor': np.floor, 'ceil': np.ceil,
        'pi': np.pi, 'e': np.e,
        'mean': lambda x: np.nanmean(x),
        'std': lambda x: np.nanstd(x),
        'sum': lambda x: np.nansum(x),
        'min': lambda x: np.nanmin(x),
        'max': lambda x: np.nanmax(x),
        'normalize': lambda x: (x - np.nanmin(x)) / (np.nanmax(x) - np.nanmin(x)) if (np.nanmax(x) != np.nanmin(x)) else np.zeros_like(x),
        'standardize': lambda x: (x - np.nanmean(x)) / np.nanstd(x) if np.nanstd(x) != 0 else np.zeros_like(x),
        'cumsum': lambda x: np.nancumsum(x),
        'diff': lambda x: np.gradient(x) if len(x) > 1 else np.zeros_like(x),
        'smooth': lambda x, w=5: pd.Series(x).rolling(max(1, int(w)), center=True, min_periods=1).mean().to_numpy(),
        'linspace': lambda a, b: np.linspace(a, b, len(df)),
        # one random number for every row: uniform (0..1, or low..high)
        # and normal (mean 0 and sd 1, or the two given)
        'rand': lambda low=0.0, high=1.0: np.random.default_rng().uniform(
            low, high, len(df)),
        'randn': lambda mean=0.0, sd=1.0: np.random.default_rng().normal(
            mean, sd, len(df)),
    }

    # Bind column names and letters as numpy arrays
    for col_idx, col_name in enumerate(df.columns):
        arr = pd.to_numeric(df[col_name], errors='coerce').to_numpy(float)
        # replace NaN with 0 for computation
        arr = np.nan_to_num(arr, nan=0.0)
        context[str(col_name)] = arr
        c_letter = col_to_letter(col_idx)
        context[c_letter] = arr
        context[c_letter.lower()] = arr

    # Evaluate safely
    result = eval(s, {"__builtins__": {}}, context)
    if isinstance(result, (int, float)):
        result = np.full(len(df), float(result))
    return np.asarray(result, dtype=float)


class FormulaBar(ttk.Frame):
    """Excel-style formula bar with Cell Address Box, fx indicator, and formula entry."""

    def __init__(self, master, on_commit=None, on_cancel=None, on_fill_down=None, on_math=None):
        super().__init__(master, padding=(4, 2))
        self.master_table = master
        self.on_commit = on_commit
        self.on_cancel = on_cancel
        self.on_fill_down = on_fill_down
        self.on_math = on_math

        # Cell name / address box
        self.name_var = tk.StringVar(value="A1")
        self.name_box = ttk.Entry(self, textvariable=self.name_var, width=13, justify="center")
        self.name_box.pack(side="left", padx=(0, 4))
        self.name_box.bind("<Return>", self._jump_to_cell)
        Tooltip(self.name_box, "Go to cell (e.g. B5)")

        # fx indicator
        fx_label = tk.Label(self, text="fx", font=("TkDefaultFont", 11, "bold", "italic"),
                            foreground="#1a5fb4")
        fx_label.pack(side="left", padx=(2, 6))

        # Formula / value entry
        self.formula_var = tk.StringVar()
        self.entry = ttk.Entry(self, textvariable=self.formula_var)
        self.entry.pack(side="left", fill="x", expand=True, padx=(0, 4))
        self.entry.bind("<Return>", self._commit)
        self.entry.bind("<KP_Enter>", self._commit)
        self.entry.bind("<Escape>", self._cancel)

        # Buttons: Commit (✓) and Cancel (✕).  Filling down and the column
        # operations live on the keyboard (Ctrl/Cmd+D) and in the right
        # click menus of the cells and the headings, where they belong.
        btn_commit = ttk.Button(self, text="✓", width=0, command=self._commit)
        btn_commit.pack(side="left", padx=(0, 2))
        Tooltip(btn_commit, "Accept (Enter)")

        btn_cancel = ttk.Button(self, text="✕", width=0, command=self._cancel)
        btn_cancel.pack(side="left", padx=(0, 4))
        Tooltip(btn_cancel, "Cancel (Esc)")

    def set_cell(self, address_str, formula_or_val):
        self.name_var.set(address_str)
        self.formula_var.set(formula_or_val)

    def get_text(self):
        return self.formula_var.get()

    def _commit(self, _event=None):
        if self.on_commit:
            self.on_commit(self.formula_var.get())
        return "break"

    def _cancel(self, _event=None):
        if self.on_cancel:
            self.on_cancel()
        return "break"

    def _fill_down(self):
        if self.on_fill_down:
            self.on_fill_down()

    def _math(self):
        if self.on_math:
            self.on_math()

    def _jump_to_cell(self, _event=None):
        addr = self.name_var.get().strip().upper()
        m = REF_PATTERN.match(addr)
        if m and hasattr(self.master_table, "select_cell_by_address"):
            self.master_table.select_cell_by_address(m.group(2), int(m.group(4)))
        return "break"


class ColumnMathDialog(ToolDialog):
    """Excel-style column operations / formula calculator."""

    def __init__(self, master, table, on_applied=None, on_close=None):
        super().__init__(master, "Column Operations (Math & Formulas)", on_close=on_close)
        self.table = table
        self.on_applied = on_applied
        self.df = table.df

        columns = [str(c) for c in self.df.columns]
        current_col = table.current_column or (columns[1] if len(columns) > 1 else (columns[0] if columns else "Y1"))
        if current_col not in columns and columns:
            current_col = columns[0]

        self.target_var = tk.StringVar(value=str(current_col))
        self.expr_var = tk.StringVar(value="")
        self.dynamic_var = tk.BooleanVar(value=True)

        # Top frame: Target Column
        top_frame = ttk.LabelFrame(self.body, text="Target Column", padding=8)
        top_frame.pack(fill="x")

        ttk.Label(top_frame, text="Calculate column:").grid(row=0, column=0, sticky="w", padx=(0, 6))
        self.target_combo = ttk.Combobox(top_frame, textvariable=self.target_var, state="readonly",
                                         values=columns, width=16)
        self.target_combo.grid(row=0, column=1, sticky="w")
        ttk.Button(top_frame, text="+ New Column", command=self._add_new_column).grid(row=0, column=2, padx=(8, 0))

        # Formula input frame
        formula_frame = ttk.LabelFrame(self.body, text="Formula / Expression", padding=8)
        formula_frame.pack(fill="x", pady=(8, 0))

        ttk.Label(formula_frame, text="Formula (Excel or Python):").pack(anchor="w")
        self.expr_entry = ttk.Entry(formula_frame, textvariable=self.expr_var, width=46)
        self.expr_entry.pack(fill="x", pady=(3, 6))
        self.expr_entry.focus_set()

        # Preset Operations Combobox
        preset_frame = ttk.Frame(formula_frame)
        preset_frame.pack(fill="x", pady=(0, 6))
        ttk.Label(preset_frame, text="Presets:").pack(side="left", padx=(0, 6))
        self.preset_combo = ttk.Combobox(preset_frame, state="readonly", width=36, values=[
            "Choose a preset operation...",
            "Scale by factor: Col * k",
            "Offset by constant: Col + k",
            "Add two columns: Col1 + Col2",
            "Subtract two columns: Col1 - Col2",
            "Multiply two columns: Col1 * Col2",
            "Divide two columns: Col1 / Col2",
            "Normalize to [0, 1]: (Col - min)/(max - min)",
            "Standardize (Z-score): (Col - mean)/std",
            "Subtract mean / baseline: Col - mean",
            "Cumulative sum: cumsum(Col)",
            "Derivative / Difference: diff(Col)",
            "Moving average smooth: smooth(Col, 5)",
            "Linear sequence: linspace(start, stop)",
        ])
        self.preset_combo.current(0)
        self.preset_combo.pack(side="left", fill="x", expand=True)
        self.preset_combo.bind("<<ComboboxSelected>>", self._apply_preset)

        # Quick Insert Column buttons
        col_btn_frame = ttk.Frame(formula_frame)
        col_btn_frame.pack(fill="x", pady=(2, 4))
        ttk.Label(col_btn_frame, text="Columns:").pack(side="left", padx=(0, 6))
        for col_name in columns[:6]:
            letter = col_to_letter(columns.index(col_name))
            btn = ttk.Button(col_btn_frame, text=f"{col_name} ({letter})", width=len(col_name) + 5,
                             command=lambda c=col_name: self._insert_text(f"{c} "))
            btn.pack(side="left", padx=2)

        # Quick Math buttons
        math_btn_frame = ttk.Frame(formula_frame)
        math_btn_frame.pack(fill="x", pady=(2, 4))
        ttk.Label(math_btn_frame, text="Math:").pack(side="left", padx=(0, 6))
        for op in ["+", "-", "*", "/", "^", "(", ")", "sin", "cos", "exp", "log10", "sqrt", "abs", "mean", "std"]:
            ttk.Button(math_btn_frame, text=op, width=max(2, len(op) + 1),
                       command=lambda o=op: self._insert_text(f"{o}(" if len(o) > 1 and o not in ("+", "-", "*", "/", "^", "(", ")") else f" {o} ")).pack(side="left", padx=1)

        # Dynamic formula checkbox
        ttk.Checkbutton(formula_frame, text="Apply as dynamic Excel formulas (recalculated when data changes)",
                        variable=self.dynamic_var).pack(anchor="w", pady=(6, 0))

        # Preview frame
        self.preview_frame = ttk.LabelFrame(self.body, text="Preview (first rows)", padding=6)
        self.preview_frame.pack(fill="x", pady=(8, 0))
        self.preview_label = ttk.Label(self.preview_frame, text="Enter a formula to see preview...", justify="left", foreground="#444")
        self.preview_label.pack(anchor="w")
        self.expr_var.trace_add("write", lambda *_: self._update_preview())
        self.target_var.trace_add("write", lambda *_: self._update_preview())

        # Buttons: Calculate, Close
        bar = ttk.Frame(self.body)
        bar.pack(fill="x", pady=(10, 0))
        ttk.Button(bar, text="Calculate & Apply", command=self.apply).pack(side="left")
        ttk.Button(bar, text="Close", command=self.close).pack(side="right")
        self.bind("<Return>", lambda _e: self.apply())

    def _insert_text(self, text):
        self.expr_entry.insert("insert", text)
        self.expr_entry.focus_set()

    def _add_new_column(self):
        new_name = f"Y{len(self.df.columns)}"
        name = simpledialog.askstring("New Column", "Column name:", initialvalue=new_name, parent=self)
        if name and self.table.add_column(name):
            cols = [str(c) for c in self.table.df.columns]
            self.target_combo.configure(values=cols)
            self.target_var.set(name)

    def _apply_preset(self, _event=None):
        idx = self.preset_combo.current()
        target = self.target_var.get()
        cols = [str(c) for c in self.df.columns]
        other_col = cols[1] if len(cols) > 1 and cols[0] == target else (cols[0] if cols else "X")

        presets = {
            1: f"{target} * 2",
            2: f"{target} + 10",
            3: f"{target} + {other_col}",
            4: f"{target} - {other_col}",
            5: f"{target} * {other_col}",
            6: f"{target} / {other_col}",
            7: f"normalize({target})",
            8: f"standardize({target})",
            9: f"{target} - mean({target})",
            10: f"cumsum({target})",
            11: f"diff({target})",
            12: f"smooth({target}, 5)",
            13: "linspace(0, 10)",
        }
        if idx in presets:
            self.expr_var.set(presets[idx])

    def _update_preview(self):
        expr = self.expr_var.get().strip()
        if not expr:
            self.preview_label.configure(text="Enter a formula to see preview...")
            return
        try:
            arr = eval_column_math(self.table.df, expr)
            preview_vals = [f"{arr[i]:.4g}" if np.isfinite(arr[i]) else "NaN" for i in range(min(5, len(arr)))]
            self.preview_label.configure(text=f"First rows: [ {', '.join(preview_vals)} ... ]")
        except Exception as err:
            self.preview_label.configure(text=f"Error: {err}")

    def apply(self):
        expr = self.expr_var.get().strip()
        if not expr:
            return
        target = self.target_var.get()
        if target not in self.table.df.columns:
            if not self.table.add_column(target):
                messagebox.showerror("Error", f"Could not create column '{target}'", parent=self)
                return

        target_idx = list(self.table.df.columns).index(target)
        target_letter = col_to_letter(target_idx)
        is_array_func = any(fn in expr.lower() for fn in ("smooth", "cumsum", "diff", "linspace", "normalize", "standardize"))

        if self.dynamic_var.get() and not is_array_func:
            # Build row-specific Excel formulas
            expr_clean = expr[1:].strip() if expr.startswith("=") else expr
            # Convert column names and letters into row placeholders
            # E.g. [Y1] -> Col letter
            cols = [str(c) for c in self.table.df.columns]
            for c_idx, c_name in enumerate(cols):
                c_letter = col_to_letter(c_idx)
                # replace column name surrounded by word boundary
                expr_clean = re.sub(rf'\b{re.escape(c_name)}\b', f"__{c_letter}__", expr_clean)

            # Apply row by row
            for r in range(len(self.table.df)):
                row_expr = expr_clean
                for c_idx in range(len(cols)):
                    c_letter = col_to_letter(c_idx)
                    row_expr = row_expr.replace(f"__{c_letter}__", f"{c_letter}{r + 1}")
                    # Also replace standalone column letters
                    row_expr = re.sub(rf'\b{c_letter}\b', f"{c_letter}{r + 1}", row_expr)
                    row_expr = re.sub(rf'\b{c_letter.lower()}\b', f"{c_letter}{r + 1}", row_expr)

                formula_str = f"={row_expr}"
                self.table.cell_formulas[(r, target_idx)] = formula_str

            self.table.recalculate_all()
        else:
            # Apply as static values
            try:
                arr = eval_column_math(self.table.df, expr)
                for r in range(min(len(self.table.df), len(arr))):
                    self.table.cell_formulas.pop((r, target_idx), None)
                    v = arr[r]
                    val = int(v) if (isinstance(v, float) and v.is_integer()) else round(float(v), 8)
                    self.table.df.iat[r, target_idx] = val
                    if self.table.tree.exists(str(r)):
                        self.table.tree.set(str(r), target, str(val))
            except Exception as err:
                messagebox.showerror("Math Error", f"Could not calculate expression:\n{err}", parent=self)
                return

        self.table._changed()
        if self.on_applied:
            self.on_applied()
        self.close()


# --------------------------------------------------------------------------
# curve fitting
# --------------------------------------------------------------------------

FIT_POINTS = 100           # how many points the fitted curve is drawn with
FIT_MARGIN = 5.0           # ... over the range of the data, widened by this %
MAX_FIT_POINTS = 10000
MAX_POLY_ORDER = 10
MOVING_WINDOW = 5          # a moving average covers this many points


def finite_pairs(x, y):
    """The X/Y pairs that are numbers on both sides, in the order given."""
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    if x.size != y.size:
        size = min(x.size, y.size)
        x, y = x[:size], y[:size]
    good = np.isfinite(x) & np.isfinite(y)
    return x[good], y[good]


def least_squares(function, x, y, start, hold=None, max_iter=300, tol=1e-12):
    """Levenberg-Marquardt: the parameters that fit `function` best.

    Written out here so the program needs nothing but numpy: the sum of the
    squared distances between the data and the curve is made as small as it
    goes, starting from `start`.  A parameter whose `hold` is True is kept
    at its starting value and is not fitted.

    Returns (parameters, worked, iterations).
    """
    params = np.array(start, dtype=float)
    hold = (np.zeros(params.size, dtype=bool) if hold is None
            else np.asarray(hold, dtype=bool))
    free = np.nonzero(~hold)[0]

    def cost_of(values):
        try:
            model = np.asarray(function(x, values), dtype=float)
        except (ValueError, ZeroDivisionError, FloatingPointError):
            return None, None
        if model.shape != y.shape or not np.all(np.isfinite(model)):
            return None, None
        residual = y - model
        return residual, float(np.dot(residual, residual))

    residual, cost = cost_of(params)
    if residual is None:
        return params, False, 0
    if not free.size:
        return params, True, 0

    lam = 1e-3
    done = 0
    for done in range(1, max_iter + 1):
        jacobian = np.zeros((x.size, free.size))
        for column, index in enumerate(free):
            step = 1e-7 * max(1.0, abs(float(params[index])))
            moved = params.copy()
            moved[index] += step
            shifted, _ = cost_of(moved)
            if shifted is None:
                return params, False, done
            jacobian[:, column] = (residual - shifted) / step
        normal = jacobian.T @ jacobian
        gradient = jacobian.T @ residual
        diagonal = np.diag(np.maximum(np.diag(normal), 1e-12))
        improved = False
        for _ in range(30):            # bigger damping until a step helps
            try:
                step_values = np.linalg.solve(normal + lam * diagonal, gradient)
            except np.linalg.LinAlgError:
                lam *= 10.0
                continue
            candidate = params.copy()
            candidate[free] += step_values
            new_residual, new_cost = cost_of(candidate)
            if new_residual is not None and new_cost < cost:
                relative = (cost - new_cost) / max(cost, 1e-300)
                params, residual, cost = candidate, new_residual, new_cost
                lam = max(lam / 10.0, 1e-12)
                improved = True
                if relative < tol:
                    return params, True, done
                break
            lam *= 10.0
            if lam > 1e12:
                break
        if not improved:
            return params, True, done       # nothing better to be found
    return params, True, done


def linear_least_squares(design, y, start=None, hold=None):
    """The exact solution of a model that is linear in its parameters."""
    design = np.asarray(design, dtype=float)
    y = np.asarray(y, dtype=float)
    count = design.shape[1]
    params = (np.zeros(count) if start is None
              else np.array(start, dtype=float))
    hold = (np.zeros(count, dtype=bool) if hold is None
            else np.asarray(hold, dtype=bool))
    free = np.nonzero(~hold)[0]
    if not free.size:
        return params, True
    target = y - design[:, hold] @ params[hold] if hold.any() else y
    try:
        solution, *_ = np.linalg.lstsq(design[:, free], target, rcond=None)
    except np.linalg.LinAlgError:
        return params, False
    params[free] = solution
    return params, True


def moving_average(y, window):
    """The running mean of `window` points, centred on every point.

    The ends are averaged over what is really there, so the smoothed curve
    is as long as the data and has no gaps at its two ends.
    """
    y = np.asarray(y, dtype=float)
    window = max(1, int(window))
    if window <= 1 or y.size == 0:
        return y.copy()
    half = window // 2
    out = np.empty(y.size, dtype=float)
    for index in range(y.size):
        low = max(0, index - half)
        high = min(y.size, index + half + 1)
        piece = y[low:high]
        piece = piece[np.isfinite(piece)]
        out[index] = float(np.mean(piece)) if piece.size else np.nan
    return out


def _safe_exp(values):
    """exp() that does not blow up while a fit is still far from home."""
    return np.exp(np.clip(np.asarray(values, dtype=float), -700.0, 700.0))


def _trend(x, y):
    """(slope, intercept) of the straight line through the points."""
    if x.size < 2 or np.ptp(x) <= 0:
        return 0.0, (float(np.mean(y)) if y.size else 0.0)
    design = np.column_stack([x, np.ones_like(x)])
    params, _ok = linear_least_squares(design, y)
    return float(params[0]), float(params[1])


def _half_way(x, y, level):
    """The X where the data first passes `level` (linear in between)."""
    if x.size < 2:
        return float(x[0]) if x.size else 0.0
    order = np.argsort(x)
    xs, ys = x[order], y[order]
    for index in range(1, xs.size):
        low, high = ys[index - 1], ys[index]
        if (low - level) * (high - level) <= 0 and low != high:
            part = (level - low) / (high - low)
            return float(xs[index - 1] + part * (xs[index] - xs[index - 1]))
    return float(np.mean(xs))



FIT_NAME_COLUMN = "Parameter"   # the column of the parameter names
FIT_BLANK_COLUMN = " "          # the empty column between curve and parameters
FIT_TAB_PREFIX = "Fit"


def rounded(value, digits=10):
    """A number kept to `digits` figures, so a cell is not a wall of noise."""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return value
    if not np.isfinite(number):
        return ""
    return float(f"{number:.{digits}g}")


def short_number(value, digits=6):
    """A number written for a person: no tail of zeros, no noise."""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return "" if value is None else str(value)
    if not np.isfinite(number):
        return ""
    return f"{number:.{digits}g}"


class FitModel:
    """One way of fitting a curve: its formula, its parameters and a start.

    `function(x, params)` is the curve itself, `guess(x, y, options)` gives
    the starting values the fit sets out from, and `derived(params, x, y)`
    returns the numbers that follow from the fit (a half-life, a width...)
    which are written under the parameters.
    """

    def __init__(self, code, label, formula, params, function, guess,
                 about="", derived=None, linear=None, settings=(),
                 extrapolates=True):
        self.code = code
        self.label = label
        self.formula = formula
        self.params = list(params)
        self.function = function
        self.guess = guess
        self.about = about
        self.derived = derived
        self.linear = linear
        self.settings = list(settings)
        self.extrapolates = extrapolates

    def parameter_names(self, options=None):
        """The names of the parameters; a polynomial has as many as its order."""
        if self.params and callable(self.params[0]):
            return list(self.params[0](options or {}))
        return list(self.params)

    def fit(self, x, y, options=None, start=None, hold=None):
        """Fit this curve to the points and say how well it did."""
        options = dict(options or {})
        x, y = finite_pairs(x, y)
        names = self.parameter_names(options)
        result = {"code": self.code, "label": self.label, "names": names,
                  "points": int(x.size), "ok": False, "message": "",
                  "params": [float("nan")] * len(names), "derived": [],
                  "x": x, "y": y}
        if x.size < max(2, len(names)):
            result["message"] = (f"{self.label} needs at least "
                                 f"{max(2, len(names))} points, "
                                 f"{x.size} were found.")
            return result

        starting = list(self.guess(x, y, options))
        if start is not None:
            for index, value in enumerate(start[:len(starting)]):
                if value is not None and np.isfinite(value):
                    starting[index] = float(value)
        held = ([bool(one) for one in (hold or ())]
                + [False] * len(starting))[:len(starting)]

        if self.linear is not None:
            design = self.linear(x, options)
            params, worked = linear_least_squares(
                design, y, start=starting, hold=held)
            rounds = 0
        else:
            params, worked, rounds = least_squares(
                self.function, x, y, starting, hold=held)
        params = np.asarray(params, dtype=float)
        model = np.asarray(self.function(x, params), dtype=float)
        if not worked or not np.all(np.isfinite(params)):
            result["message"] = (f"{self.label} could not be fitted to these "
                                 "points.  Try other starting values.")
            return result

        residual = y - model
        sse = float(np.dot(residual, residual))
        spread = float(np.sum((y - np.mean(y)) ** 2))
        freedom = max(1, x.size - sum(1 for one in held if not one))
        result.update({
            "ok": True, "params": [float(one) for one in params],
            "start": starting, "hold": held, "rounds": rounds,
            "sse": sse, "rmse": float(np.sqrt(sse / freedom)),
            "r2": (1.0 - sse / spread) if spread > 0 else float("nan"),
            "model": model,
        })
        if self.derived:
            result["derived"] = list(self.derived(params, x, y))
        return result

    def curve(self, params, grid):
        return np.asarray(self.function(np.asarray(grid, dtype=float),
                                        np.asarray(params, dtype=float)),
                          dtype=float)


# -- the models themselves -------------------------------------------------

def _line_guess(x, y, _options):
    slope, intercept = _trend(x, y)
    return [slope, intercept]


def _poly_names(options):
    order = max(1, min(int(options.get("order", 2) or 2), MAX_POLY_ORDER))
    names = ["c0 (constant)", "c1 (x)"]
    names += [f"c{index} (x^{index})" for index in range(2, order + 1)]
    return names[:order + 1]


def _poly_guess(x, y, options):
    return [0.0] * len(_poly_names(options))


def _poly_design(x, options):
    order = max(1, min(int(options.get("order", 2) or 2), MAX_POLY_ORDER))
    return np.vander(x, order + 1, increasing=True)


def _growth_guess(x, y, _options):
    positive = y > 0
    if positive.sum() >= 2:
        rate, constant = _trend(x[positive], np.log(y[positive]))
        start = float(np.exp(constant))
        if np.isfinite(rate) and np.isfinite(start) and start > 0:
            return [start, rate]
    span = max(np.ptp(x), 1e-9)
    return [max(float(y[0]), 1e-6), 1.0 / span]


def _decay_guess(x, y, _options):
    order = np.argsort(x)
    xs, ys = x[order], y[order]
    plateau = float(ys[-1])
    start = float(ys[0])
    level = plateau + (start - plateau) / 2.0
    half = _half_way(xs, ys, level) - float(xs[0])
    rate = np.log(2.0) / half if half > 0 else 1.0 / max(np.ptp(x), 1e-9)
    return [start, plateau, float(abs(rate))]


def _decay2_guess(x, y, options):
    start, plateau, rate = _decay_guess(x, y, options)
    span = start - plateau
    return [plateau, span / 2.0, rate * 3.0, span / 2.0, rate / 3.0]


def _logistic_guess(x, y, _options):
    bottom, top = float(np.min(y)), float(np.max(y))
    middle = _half_way(x, y, (bottom + top) / 2.0)
    slope, _intercept = _trend(x, y)
    span = max(np.ptp(x), 1e-9)
    rate = 4.0 / span
    return [bottom, top, middle, float(rate if slope >= 0 else -rate)]


def _gauss_guess(x, y, _options):
    baseline = float(np.min(y))
    peak = int(np.argmax(y))
    amplitude = float(y[peak] - baseline)
    weights = np.clip(y - baseline, 0.0, None)
    total = float(np.sum(weights))
    mean = float(np.sum(weights * x) / total) if total > 0 else float(x[peak])
    if total > 0:
        variance = float(np.sum(weights * (x - mean) ** 2) / total)
        width = np.sqrt(variance) if variance > 0 else np.ptp(x) / 6.0
    else:
        width = np.ptp(x) / 6.0
    return [baseline, amplitude if amplitude else 1.0, mean,
            float(width if width > 0 else 1.0)]


def _moving_guess(x, y, options):
    return [float(max(1, int(options.get("window", MOVING_WINDOW) or 1)))]


def _half_life(rate):
    rate = float(rate)
    return np.log(2.0) / rate if rate not in (0.0,) and np.isfinite(rate) \
        else float("nan")


FIT_MODELS = [
    FitModel(
        "line", "Straight line", "y = a*x + b",
        ["a (slope)", "b (intercept)"],
        lambda x, p: p[0] * x + p[1],
        _line_guess,
        about="The line of least squares through the points.",
        linear=lambda x, _o: np.column_stack([x, np.ones_like(x)]),
        derived=lambda p, x, y: [("x where y = 0",
                                  (-p[1] / p[0]) if p[0] else float("nan"))],
    ),
    FitModel(
        "poly", "Polynomial", "y = c0 + c1*x + c2*x^2 + ...",
        [_poly_names],
        lambda x, p: np.polyval(list(p)[::-1], x),
        _poly_guess,
        about="A curve of the order you choose, fitted exactly.",
        linear=_poly_design,
        settings=[("order", "Order:", "int", 2, 1, MAX_POLY_ORDER)],
    ),
    FitModel(
        "growth", "Exponential growth", "y = Y0 * exp(k*x)",
        ["Y0 (at x = 0)", "k (rate)"],
        lambda x, p: p[0] * _safe_exp(p[1] * x),
        _growth_guess,
        about="Something that grows by the same factor in equal steps.",
        derived=lambda p, x, y: [("Doubling time", _half_life(p[1]))],
    ),
    FitModel(
        "decay1", "One phase decay", "y = (Y0 - Plateau) * exp(-K*x) + Plateau",
        ["Y0 (at x = 0)", "Plateau", "K (rate)"],
        lambda x, p: (p[0] - p[1]) * _safe_exp(-p[2] * x) + p[1],
        _decay_guess,
        about="One process running down towards a plateau.",
        derived=lambda p, x, y: [("Half life", _half_life(p[2])),
                                 ("Span", float(p[0] - p[1]))],
    ),
    FitModel(
        "decay2", "Two phase decay",
        "y = Plateau + Fast*exp(-Kf*x) + Slow*exp(-Ks*x)",
        ["Plateau", "Span fast", "Kf (fast rate)", "Span slow",
         "Ks (slow rate)"],
        lambda x, p: (p[0] + p[1] * _safe_exp(-p[2] * x)
                      + p[3] * _safe_exp(-p[4] * x)),
        _decay2_guess,
        about="Two processes running down at once, one quick, one slow.",
        derived=lambda p, x, y: [
            ("Half life fast", _half_life(p[2])),
            ("Half life slow", _half_life(p[4])),
            ("Per cent fast", 100.0 * abs(p[1]) / max(abs(p[1]) + abs(p[3]),
                                                      1e-300))],
    ),
    FitModel(
        "logistic", "Logistic curve",
        "y = Bottom + (Top - Bottom) / (1 + exp(-k*(x - x50)))",
        ["Bottom", "Top", "x50 (midpoint)", "k (steepness)"],
        lambda x, p: p[0] + (p[1] - p[0]) / (1.0 + _safe_exp(-p[3] * (x - p[2]))),
        _logistic_guess,
        about="An S shaped curve between two plateaus.",
        derived=lambda p, x, y: [("Span", float(p[1] - p[0])),
                                 ("Slope at x50",
                                  float((p[1] - p[0]) * p[3] / 4.0))],
    ),
    FitModel(
        "gauss", "Gaussian distribution",
        "y = Base + A * exp(-(x - Mean)^2 / (2*SD^2))",
        ["Baseline", "A (amplitude)", "Mean", "SD (width)"],
        lambda x, p: p[0] + p[1] * _safe_exp(
            -((x - p[2]) ** 2) / (2.0 * max(abs(p[3]), 1e-12) ** 2)),
        _gauss_guess,
        about="A bell shaped peak over a flat baseline.",
        derived=lambda p, x, y: [
            ("FWHM", float(2.0 * np.sqrt(2.0 * np.log(2.0)) * abs(p[3]))),
            ("Area under the peak",
             float(abs(p[1]) * abs(p[3]) * np.sqrt(2.0 * np.pi)))],
    ),
    FitModel(
        "movavg", "Moving average", "the running mean of n points",
        ["n (window)"],
        None,                       # smoothing, not a formula with parameters
        _moving_guess,
        about="Smoothing: every point is the mean of its neighbours.",
        settings=[("window", "Window (points):", "int", MOVING_WINDOW, 2, 999)],
        extrapolates=False,
    ),
]

FIT_BY_CODE = {model.code: model for model in FIT_MODELS}


def fit_column(code, x, y, options=None, start=None, hold=None):
    """Fit one column with one of the methods; a moving average is smoothed."""
    model = FIT_BY_CODE.get(str(code))
    if model is None:
        return {"ok": False, "message": f"Unknown fitting method: {code}",
                "names": [], "params": [], "derived": []}
    options = dict(options or {})
    if model.code == "movavg":
        x, y = finite_pairs(x, y)
        window = max(2, int(options.get("window", MOVING_WINDOW) or MOVING_WINDOW))
        result = {"code": "movavg", "label": model.label, "names": ["n (window)"],
                  "params": [float(window)], "derived": [], "x": x, "y": y,
                  "points": int(x.size), "ok": x.size >= 2, "message": "",
                  "hold": [True], "start": [float(window)], "rounds": 0}
        if not result["ok"]:
            result["message"] = "A moving average needs at least two points."
            return result
        order = np.argsort(x)
        smooth = np.empty_like(y)
        smooth[order] = moving_average(y[order], window)
        residual = y - smooth
        sse = float(np.dot(residual, residual))
        spread = float(np.sum((y - np.mean(y)) ** 2))
        result.update({"model": smooth, "sse": sse,
                       "rmse": float(np.sqrt(sse / max(1, x.size))),
                       "r2": (1.0 - sse / spread) if spread > 0 else float("nan")})
        return result
    return model.fit(x, y, options=options, start=start, hold=hold)


def fit_grid(x, points=FIT_POINTS, margin=FIT_MARGIN):
    """The X values the fitted curve is written with.

    `points` of them, over the range of the data widened by `margin` per
    cent at both ends, so the curve reaches a little past the measurements.
    """
    x = np.asarray(x, dtype=float)
    x = x[np.isfinite(x)]
    points = max(2, min(int(points or FIT_POINTS), MAX_FIT_POINTS))
    if not x.size:
        return np.linspace(0.0, 1.0, points)
    low, high = float(np.min(x)), float(np.max(x))
    if high <= low:
        step = abs(low) * 0.05 or 0.5
        low, high = low - step, high + step
    extra = (high - low) * float(margin) / 100.0
    return np.linspace(low - extra, high + extra, points)


def fitted_curve(result, grid):
    """The fitted curve on `grid`, with gaps where it says nothing."""
    grid = np.asarray(grid, dtype=float)
    if not result.get("ok"):
        return np.full(grid.shape, np.nan)
    model = FIT_BY_CODE.get(result.get("code"))
    if model is None:
        return np.full(grid.shape, np.nan)
    if model.code == "movavg":
        # a moving average says nothing outside the measurements: it is
        # written along the data and left empty past their two ends
        x, smooth = np.asarray(result["x"], float), np.asarray(result["model"], float)
        order = np.argsort(x)
        out = np.interp(grid, x[order], smooth[order], left=np.nan, right=np.nan)
        out[(grid < np.min(x)) | (grid > np.max(x))] = np.nan
        return out
    try:
        values = model.curve(result["params"], grid)
    except (ValueError, TypeError, ZeroDivisionError):
        return np.full(grid.shape, np.nan)
    return np.where(np.isfinite(values), values, np.nan)


class RegressionDialog(ToolDialog):
    """Fit a curve to the columns of one sheet.

    The methods stand on the left; choosing one shows, on the right, what
    it needs: its own settings, the columns it will be fitted to and the
    starting value of every parameter (which may be held fixed).  `Fit`
    writes the answer into a new sheet: the fitted curve drawn with many
    points, and beside it the parameters with their names.
    """

    def __init__(self, master, app, on_close=None):
        super().__init__(master, "Regression", on_close=on_close)
        self.app = app
        self.model = FIT_MODELS[0]
        self.setting_vars = {}
        self.start_vars = []
        self.hold_vars = []
        self._results = []

        self.points_var = tk.StringVar(value=str(FIT_POINTS))
        self.margin_var = tk.StringVar(value=f"{FIT_MARGIN:g}")
        self.plot_var = tk.BooleanVar(value=True)

        columns = ttk.Frame(self.body)
        columns.pack(fill="both", expand=True)

        # -- the methods, on the left
        left = ttk.LabelFrame(columns, text="Fitting method", padding=8)
        left.pack(side="left", fill="y")
        self.method_list = tk.Listbox(left, height=len(FIT_MODELS), width=24,
                                      exportselection=False,
                                      activestyle="dotbox")
        for one in FIT_MODELS:
            self.method_list.insert("end", one.label)
        self.method_list.selection_set(0)
        self.method_list.pack(fill="y")
        self.method_list.bind("<<ListboxSelect>>", self._method_chosen)

        # -- everything the chosen method needs, on the right
        right = ttk.Frame(columns)
        right.pack(side="left", fill="both", expand=True, padx=(12, 0))
        self.right = right

        head = ttk.LabelFrame(right, text="What it fits", padding=8)
        head.pack(fill="x")
        self.formula_label = ttk.Label(head, text="", font=("TkFixedFont", 11))
        self.formula_label.pack(anchor="w")
        self.about_label = ttk.Label(head, text="", foreground="#666",
                                     justify="left", wraplength=330)
        self.about_label.pack(anchor="w", pady=(4, 0))

        self.settings_box = ttk.LabelFrame(right, text="Settings", padding=8)
        self.settings_box.pack(fill="x", pady=(10, 0))

        data_box = ttk.LabelFrame(right, text="Columns to fit", padding=8)
        self.data_box = data_box
        data_box.pack(fill="x", pady=(10, 0))
        self.column_list = tk.Listbox(data_box, height=4, selectmode="extended",
                                      exportselection=False)
        self.column_list.pack(fill="x")
        self.x_label = ttk.Label(data_box, text="", foreground="#666")
        self.x_label.pack(anchor="w", pady=(4, 0))

        self.params_box = ttk.LabelFrame(
            right, text="Parameters (empty = worked out from the data)",
            padding=8)
        self.params_box.pack(fill="x", pady=(10, 0))

        curve = ttk.LabelFrame(right, text="The curve that is written",
                               padding=8)
        self.curve_box = curve
        curve.pack(fill="x", pady=(10, 0))
        ttk.Label(curve, text="Points:").grid(row=0, column=0, sticky="w",
                                              padx=(0, 8), pady=3)
        ttk.Spinbox(curve, from_=2, to=MAX_FIT_POINTS, increment=10, width=8,
                    textvariable=self.points_var).grid(row=0, column=1,
                                                       sticky="w", pady=3)
        ttk.Label(curve, text="Past the data (%):").grid(
            row=0, column=2, sticky="w", padx=(16, 8), pady=3)
        ttk.Spinbox(curve, from_=0, to=100, increment=1, width=8,
                    textvariable=self.margin_var).grid(row=0, column=3,
                                                       sticky="w", pady=3)
        ttk.Checkbutton(curve, variable=self.plot_var,
                        text="Draw it with the data at once").grid(
            row=1, column=0, columnspan=4, sticky="w", pady=(6, 0))

        self.result_label = ttk.Label(right, text="", justify="left",
                                      wraplength=330)
        self.result_label.pack(anchor="w", pady=(10, 0))

        buttons = ttk.Frame(self.body)
        buttons.pack(side="bottom", fill="x", pady=(12, 0))
        self.fit_button = ttk.Button(buttons, text="Fit", command=self.run_fit)
        self.fit_button.pack(side="left")
        ttk.Button(buttons, text="Close", command=self.close).pack(side="right")

        self.refresh_columns()
        self._show_method()

    # -- what the sheet offers ---------------------------------------------
    def source_table(self):
        return self.app.table

    def column_names(self):
        """The Y columns of the sheet: everything after the first one."""
        table = self.source_table()
        if table is None:
            return []
        names = [str(one) for one in table.df.columns]
        return names[1:]

    def x_name(self):
        table = self.source_table()
        names = [str(one) for one in (table.df.columns if table is not None else [])]
        return names[0] if names else ""

    def refresh_columns(self):
        """The list of columns, with the ticked ones already chosen."""
        table = self.source_table()
        names = self.column_names()
        self.column_list.delete(0, "end")
        for name in names:
            self.column_list.insert("end", name)
        errors = self.error_columns()
        frame = None if table is None else table.df

        def worth_fitting(name):
            """A column of error bars, or an empty one, is not fitted."""
            if str(name) in errors:
                return False
            if frame is None or str(name) not in frame.columns:
                return True
            return PlotWindow.has_numbers(frame, name)

        chosen = []
        for index, name in enumerate(names):
            if not worth_fitting(name):
                continue
            if table is not None and table.column_axis(name) in ("L", "R"):
                chosen.append(index)
        if not chosen:
            chosen = [index for index, name in enumerate(names)
                      if worth_fitting(name)] or list(range(len(names)))
        for index in chosen:
            self.column_list.selection_set(index)
        self.x_label.configure(
            text=(f"X values: the first column, \"{self.x_name()}\""
                  if names else "This sheet has no column to fit."))
        return names

    def error_columns(self):
        """The columns that hold the error bars of another column.

        A curve drawn with error bars reads the length of its bars from a
        column of its own.  That column is the scatter of the measurement,
        not a measurement in its own right, so a curve fitted to it would
        be a curve fitted to the noise: it is left out of the choice when
        the window opens.  It is still in the list and can be ticked by
        hand, and nothing stops a fit of it then.
        """
        found = set()
        for window in self.app.open_windows():
            try:
                for _mean, error in dict(window.error_partner).items():
                    found.add(str(error))
                for _mean, low in dict(window.error_partner_low).items():
                    found.add(str(low))
                for column, style in dict(window.series_style).items():
                    if style not in ERROR_STYLES:
                        continue
                    cfg = window.error_cfg.get(column) or {}
                    kind = str(cfg.get("type", "pair"))
                    if kind == "column" and cfg.get("column"):
                        found.add(str(cfg["column"]))
                    elif kind == "pair":
                        for partner in (window.partner_column(column),
                                        window.partner_low_column(column)):
                            if partner:
                                found.add(str(partner))
            except (AttributeError, TypeError, ValueError):
                continue
        return found

    def chosen_columns(self):
        names = self.column_names()
        picked = [names[index] for index in self.column_list.curselection()
                  if index < len(names)]
        return picked or names

    # -- the method and its parameters -------------------------------------
    def _method_chosen(self, _event=None):
        picked = self.method_list.curselection()
        if not picked:
            return
        self.model = FIT_MODELS[int(picked[0])]
        self._show_method()

    def options(self):
        """The settings of this method, as the engine wants them."""
        out = {}
        for name, variable, kind, default, low, high in self._setting_specs():
            text = variable.get()
            if kind == "int":
                value = to_int(text, int(default))
                value = max(int(low), min(int(value), int(high)))
            else:
                value = to_float(text, float(default))
            out[name] = value
        return out

    def _setting_specs(self):
        return [(name, self.setting_vars[name], kind, default, low, high)
                for name, _label, kind, default, low, high in self.model.settings
                if name in self.setting_vars]

    def _show_method(self):
        """Build the right hand side for the method that was chosen."""
        self.formula_label.configure(text=self.model.formula)
        self.about_label.configure(text=self.model.about)

        for child in self.settings_box.winfo_children():
            child.destroy()
        self.setting_vars = {}
        if self.model.settings:
            self.settings_box.pack(fill="x", pady=(10, 0), before=self.data_box)
            for row, (name, label, kind, default, low, high) in enumerate(
                    self.model.settings):
                variable = tk.StringVar(value=str(default))
                self.setting_vars[name] = variable
                ttk.Label(self.settings_box, text=label).grid(
                    row=row, column=0, sticky="w", padx=(0, 8), pady=3)
                spin = ttk.Spinbox(self.settings_box, from_=low, to=high,
                                   increment=1, width=8, textvariable=variable,
                                   command=self._rebuild_params)
                spin.grid(row=row, column=1, sticky="w", pady=3)
                variable.trace_add("write", lambda *_a: self._rebuild_params())
        else:
            self.settings_box.pack_forget()
        self._rebuild_params()

    def _rebuild_params(self, *_args):
        """One row per parameter: its name, a starting value and a hold."""
        for child in self.params_box.winfo_children():
            child.destroy()
        self.start_vars, self.hold_vars = [], []
        names = self.model.parameter_names(self.options())
        if self.model.code == "movavg":
            self.params_box.pack_forget()
            return names
        self.params_box.pack(fill="x", pady=(10, 0), before=self.curve_box)
        ttk.Label(self.params_box, text="Start value", foreground="#666").grid(
            row=0, column=1, sticky="w", padx=(0, 8))
        ttk.Label(self.params_box, text="Hold", foreground="#666").grid(
            row=0, column=2, sticky="w")
        for row, name in enumerate(names, start=1):
            ttk.Label(self.params_box, text=name).grid(
                row=row, column=0, sticky="w", padx=(0, 8), pady=2)
            start = tk.StringVar(value="")
            hold = tk.BooleanVar(value=False)
            self.start_vars.append(start)
            self.hold_vars.append(hold)
            ttk.Entry(self.params_box, textvariable=start, width=12).grid(
                row=row, column=1, sticky="w", padx=(0, 8), pady=2)
            ttk.Checkbutton(self.params_box, variable=hold).grid(
                row=row, column=2, sticky="w", pady=2)
        return names

    def starting_values(self):
        """(start, hold) as the engine wants them; empty means automatic."""
        start, hold = [], []
        for index, variable in enumerate(self.start_vars):
            text = str(variable.get()).strip()
            value = to_float(text, None) if text else None
            start.append(value if (value is not None
                                   and np.isfinite(value)) else None)
            hold.append(bool(self.hold_vars[index].get()))
        if any(hold[index] and start[index] is None for index in range(len(hold))):
            # a parameter can only be held at a value that was typed in
            hold = [hold[index] and start[index] is not None
                    for index in range(len(hold))]
        return start, hold

    # -- doing it ----------------------------------------------------------
    def run_fit(self):
        table = self.source_table()
        if table is None or not len(table.df.columns):
            messagebox.showinfo("Regression", "There is nothing to fit yet.",
                                parent=self)
            return None
        table._commit_edit()
        if not self.column_list.size():
            self.refresh_columns()
        columns = self.chosen_columns()
        if not columns:
            messagebox.showinfo("Regression",
                                "This sheet has no column to fit.\n"
                                "The first column holds the X values and "
                                "every column after it can be fitted.",
                                parent=self)
            return None

        frame = table.df
        x_name = self.x_name()
        x_values = pd.to_numeric(frame[x_name], errors="coerce").to_numpy(float)
        if not np.isfinite(x_values).any():
            # a first column of names is no X axis: the row numbers are
            x_values = np.arange(1, len(frame) + 1, dtype=float)
            x_name = ROW_AXIS_LABEL

        options = self.options()
        start, hold = self.starting_values()
        results, failed = [], []
        for name in columns:
            y_values = pd.to_numeric(frame[name], errors="coerce").to_numpy(float)
            result = fit_column(self.model.code, x_values, y_values,
                                options=options, start=start, hold=hold)
            result["column"] = str(name)
            results.append(result)
            if not result.get("ok"):
                failed.append(f"{name}: {result.get('message', 'it did not fit')}")

        good = [one for one in results if one.get("ok")]
        if not good:
            messagebox.showerror("Regression",
                                 "Nothing could be fitted.\n\n" + "\n".join(failed),
                                 parent=self)
            return None

        self._results = good
        sheet, names_off = self.build_sheet(good, x_name, options)
        self.app.add_fit_tab(sheet, names_off, plot=bool(self.plot_var.get()))
        self.result_label.configure(text=self.summary(good, failed))
        return good

    def summary(self, results, failed=()):
        lines = []
        for result in results:
            values = ", ".join(
                f"{name} = {short_number(value)}"
                for name, value in zip(result["names"], result["params"]))
            lines.append(f"{result['column']}: {values}"
                         f"   (R² = {short_number(result.get('r2'))})")
        lines += list(failed)
        return "\n".join(lines)

    def build_sheet(self, results, x_name, options):
        """The new sheet: the curve, a blank column, then the parameters.

        Returns the table itself and the names of the columns that hold the
        parameters - those are not data to plot, so their check buttons are
        switched off.
        """
        points = to_int(self.points_var.get(), FIT_POINTS)
        margin = to_float(self.margin_var.get(), FIT_MARGIN)
        if not self.model.extrapolates:
            margin = 0.0
        base = results[0]["x"]
        for one in results[1:]:
            base = np.concatenate([base, one["x"]])
        grid = fit_grid(base, points=points, margin=margin)

        sheet = {x_name: [rounded(one) for one in grid]}
        for result in results:
            curve = fitted_curve(result, grid)
            sheet[f"{result['column']} fit"] = [
                "" if not np.isfinite(one) else rounded(one) for one in curve]

        # the parameters stand beside the curve, one blank column between
        rows = []
        for index, name in enumerate(results[0]["names"]):
            rows.append((name, [result["params"][index] if
                                index < len(result["params"]) else float("nan")
                                for result in results]))
        for index, (name, _value) in enumerate(results[0].get("derived") or []):
            rows.append((name, [(result.get("derived") or [])[index][1]
                                if index < len(result.get("derived") or [])
                                else float("nan") for result in results]))
        rows.append(("R squared", [result.get("r2") for result in results]))
        rows.append(("RMSE", [result.get("rmse") for result in results]))
        rows.append(("Points fitted", [result.get("points") for result in results]))
        rows.append(("Method", [self.model.label for _ in results]))

        height = len(grid)
        blank = FIT_BLANK_COLUMN
        sheet[blank] = [""] * height
        parameter_columns = [blank, FIT_NAME_COLUMN]
        sheet[FIT_NAME_COLUMN] = [
            rows[index][0] if index < len(rows) else "" for index in range(height)]
        for column, result in enumerate(results):
            name = f"{result['column']} value"
            parameter_columns.append(name)
            values = []
            for index in range(height):
                if index >= len(rows):
                    values.append("")
                    continue
                value = rows[index][1][column]
                if isinstance(value, str):
                    values.append(value)
                elif value is None or not np.isfinite(float(value)):
                    values.append("")
                elif float(value).is_integer() and abs(float(value)) < 1e15:
                    values.append(int(value))
                else:
                    values.append(rounded(value))
            sheet[name] = values
        return pd.DataFrame(sheet), parameter_columns


# --------------------------------------------------------------------------
# data table
# --------------------------------------------------------------------------

class DataTable(ttk.Frame):
    """Treeview based table with in-place cell editing."""

    def __init__(self, master, config: Config, on_change=None, on_rename=None,
                 on_add_column=None, on_delete_column=None):
        super().__init__(master)
        self.config_obj = config
        self.on_change = on_change
        self.on_rename = on_rename
        # the program adds and deletes columns (it asks for the name)
        self.on_add_column = on_add_column
        self.on_delete_column = on_delete_column
        self.df = pd.DataFrame()
        # the widths the user gave columns by dragging the edge of their
        # heading: {column name: pixels}.  They are kept through every
        # redrawing of the sheet and written into the .aplt file.
        self.column_widths = {}
        self._resizing = None           # the heading edge being dragged
        self.current_column = None      # column of the last clicked cell/heading
        self._editor = None
        self._heading_editor = None
        self.cell_formulas: dict = {}   # (row, col) -> formula string (e.g. "=A1+B1")
        self.random_seed = new_random_seed()   # what RAND() of this sheet draws from
        self.plot_with_previous_var = tk.BooleanVar(value=False)
        # the highlighted block of cells: (row0, col0, row1, col1)
        self.block = None
        self.anchor = (0, 0)            # where Shift+arrows measure from
        self.cursor = (0, 0)            # the cell the keyboard works on
        self._outline = []              # the four frames around the block
        self._fill_handle = None        # black square at bottom-right corner of selection
        # the blank starting sheet grows columns to fill the window
        self.auto_columns = False
        self._grow_timer = None
        self._fill_feedback = []        # 4 thin frames indicating fill extent
        self._fill_dragging = False
        self._fill_start_bounds = None
        self._fill_target_row = None
        self._fill_point = None         # where the handle is being held
        self._fill_auto_scroll_timer = None
        self._row_selecting = False
        self._row_press = None
        self._letter_selecting = False  # a range of columns is being dragged
        self._letter_press = None       # the column the drag started on
        self._col_labels: dict = {}     # column name -> the label of its letter
        self._selecting = False         # a block is being dragged out
        self._press = None              # (x, cell) of the press that started it
        self._text_dragging = False     # the pointer is selecting cell text
        self._drag_point = None         # last pointer position of the drag
        self._auto_scroll = None        # the running auto-scroll timer

        self.style = ttk.Style(self)
        self.tree = ttk.Treeview(self, show="headings", selectmode="none",
                                 style="APlot.Treeview", takefocus=True)
        self.tree.tag_configure("block", background=BLOCK_TINT)

        # Row line numbers (1, 2, 3...) at the left side of the spreadsheet panel
        self.corner_box = tk.Frame(self, width=ROW_HEADER_WIDTH,
                                   height=CHECK_BAR_HEIGHT,
                                   relief="groove", borderwidth=1,
                                   cursor="hand2")
        self.corner_box.grid_propagate(False)
        self.corner_box_label = ttk.Label(self.corner_box, text="◢", foreground="#888888",
                                          font=("TkDefaultFont", 8))
        self.corner_box_label.place(relx=0.5, rely=0.5, anchor="center")
        self.corner_box.bind("<Button-1>", lambda _e: self.select_all_cells())
        self.corner_box_label.bind("<Button-1>", lambda _e: self.select_all_cells())

        self.row_tree = ttk.Treeview(self, show="headings", selectmode="none",
                                     style="APlot.RowHeader.Treeview", takefocus=False)
        self.row_tree["columns"] = ("#",)
        self.row_tree.heading("#", text="#", anchor="center", command=self.select_all_cells)
        self.row_tree.column("#", width=ROW_HEADER_WIDTH, minwidth=ROW_HEADER_WIDTH,
                             stretch=False, anchor="center")
        self.row_tree.tag_configure("active_row", background=HEADER_ACTIVE,
                                    foreground="#000000")

        self.row_tree.bind("<Button-1>", self._on_row_tree_click)
        self.row_tree.bind("<B1-Motion>", self._on_row_tree_drag)
        self.row_tree.bind("<ButtonRelease-1>", self._on_row_tree_release)
        self.row_tree.bind("<MouseWheel>", self._on_row_tree_wheel)
        self.row_tree.bind("<Button-4>", self._on_row_tree_wheel)
        self.row_tree.bind("<Button-5>", self._on_row_tree_wheel)

        v_scroll = ttk.Scrollbar(self, orient="vertical", command=self._yview)
        h_scroll = ttk.Scrollbar(self, orient="horizontal", command=self._xview)
        self.tree.configure(yscrollcommand=self._y_scrolled,
                            xscrollcommand=self._x_scrolled)
        self._v_scroll, self._h_scroll = v_scroll, h_scroll

        # Formula bar above the check bar and headings
        self.formula_bar = FormulaBar(self, on_commit=self._formula_bar_commit,
                                      on_cancel=self._formula_bar_cancel,
                                      on_fill_down=self.fill_down,
                                      on_math=self.open_column_math)
        self.formula_bar.grid(row=0, column=0, columnspan=3, sticky="ew", pady=(0, 2))

        # Corner box above row numbers, and check bar above column data
        self.corner_box.grid(row=1, column=0, sticky="nsew")
        self.check_bar = tk.Frame(self, height=CHECK_BAR_HEIGHT)
        self.check_bar.grid(row=1, column=1, sticky="ew")
        self.check_bar.grid_propagate(False)

        # column name -> {"B"/"T" or "L"/"R": BooleanVar} and the two widgets
        self.axis_vars: dict = {}
        self._checks: dict = {}

        self.row_tree.grid(row=2, column=0, sticky="ns")
        self.tree.grid(row=2, column=1, sticky="nsew")
        v_scroll.grid(row=2, column=2, sticky="ns")
        h_scroll.grid(row=3, column=1, sticky="ew")

        # Summary status bar at the bottom (Sum, Average, Count, Min, Max).
        # The strip keeps the plain background of the window; only its
        # writing is blue - the blue of the row numbers and the column
        # letters, so the numbers about a block and the heads of that block
        # are plainly the same family.
        self.status_bar = ttk.Frame(self)
        self.status_bar.grid(row=4, column=0, columnspan=3, sticky="ew", pady=(2, 0))
        self.status_label = ttk.Label(self.status_bar, text="",
                                      foreground=STATUS_TEXT_COLOR,
                                      font=("TkDefaultFont", 9))
        self.status_label.pack(side="left", padx=4)

        self.rowconfigure(2, weight=1)
        self.columnconfigure(0, weight=0)
        self.columnconfigure(1, weight=1)
        self.columnconfigure(2, weight=0)

        self.tree.bind("<Button-1>", self._on_click)
        self.tree.bind("<Shift-Button-1>", self._on_shift_click)
        self.tree.bind("<B1-Motion>", self._on_drag)
        self.tree.bind("<ButtonRelease-1>", self._on_drag_end)
        for seq in ("<Button-2>", "<Button-3>", "<Control-Button-1>"):
            self.tree.bind(seq, self._show_context_menu)
        self.tree.bind("<Configure>", lambda _e: self._layout_changed())
        self.tree.bind("<MouseWheel>", lambda _e: self.after(1, self._refresh_outline),
                       add="+")
        self._bind_grid_keys()
        self.apply_config()

    # -- which columns are plotted, and against which axis ------------------
    def _is_x_column(self, name):
        columns = [str(one) for one in self.df.columns]
        return bool(columns) and str(name) == columns[0]

    def _axis_family(self, index):
        """The first column belongs to the X axes, every other one to the Y."""
        return "x" if index == 0 else "y"

    def _build_checks(self, check_all=False):
        """Two check buttons and column letters per column, in the strip above the headings."""
        wanted = [str(name) for name in self.df.columns]
        previous = {name: self.column_axis(name) for name in self.axis_vars}
        for widgets in self._checks.values():
            for widget in widgets.values():
                widget.destroy()
        self._checks.clear()
        for lbl in getattr(self, "_col_labels", {}).values():
            lbl.destroy()
        self._col_labels = {}
        self.axis_vars = {}
        for index, name in enumerate(wanted):
            family = self._axis_family(index)
            first_code = AXIS_TAGS[family][0][0]
            if check_all or name not in previous:
                chosen = first_code            # a new column: the first axis
            else:
                chosen = previous[name]        # keep the choice, "none" too
            if family == "x" and chosen not in X_SIDES:
                chosen = "B"                   # the X column always feeds one
            variables, widgets = {}, {}
            for code, text, hint in AXIS_TAGS[family]:
                variable = tk.BooleanVar(value=(code == chosen))
                check = ttk.Checkbutton(
                    self.check_bar, variable=variable, text=text,
                    takefocus=False, style="APlot.Axis.TCheckbutton",
                    command=lambda n=name, c=code: self._axis_clicked(n, c))
                check.tooltip = Tooltip(check, hint)
                variables[code] = variable
                widgets[code] = check
            self.axis_vars[name] = variables
            self._checks[name] = widgets

            # the letter of the column: clicking it selects the whole column,
            # exactly as the number beside a row selects the whole row
            c_letter = col_to_letter(index)
            lbl = tk.Label(self.check_bar, text=c_letter,
                           font=("TkDefaultFont", 10, "bold"),
                           foreground=HEADER_COLOR,
                           background=self.header_background(),
                           cursor="hand2")
            lbl.bind("<Button-1>", lambda e, i=index: self._on_letter_click(i, e))
            lbl.bind("<Shift-Button-1>",
                     lambda e, i=index: self._on_letter_shift_click(i, e))
            lbl.bind("<B1-Motion>", self._on_letter_drag)
            lbl.bind("<ButtonRelease-1>", self._on_letter_release)
            lbl.bind("<Button-3>",
                     lambda e, i=index: self._show_header_context_menu(i, e))
            lbl.bind("<Button-2>",
                     lambda e, i=index: self._show_header_context_menu(i, e))
            lbl.tooltip = Tooltip(lbl, f"Select column {c_letter}")
            self._col_labels[name] = lbl
        self._place_checks()

    def header_background(self):
        """The colour of the strip the check buttons and letters sit on."""
        try:
            return str(self.check_bar.cget("background"))
        except (tk.TclError, AttributeError):
            return "#f0f0f0"

    def _axis_clicked(self, name, code):
        """One axis per column: ticking one check button clears the other."""
        variables = self.axis_vars.get(str(name)) or {}
        variable = variables.get(code)
        if variable is None:
            return
        if variable.get():                      # it was just switched on
            for other, one in variables.items():
                if other != code:
                    one.set(False)
        elif self._is_x_column(name):
            variable.set(True)         # the data has to have an X axis
            return                     # nothing changed: no replot needed
        self._changed()

    def _place_checks(self):
        """Put the two check buttons of every column over its middle, and column letter below."""
        if not self._checks:
            return
        rows = self.tree.get_children()
        offset = 0
        try:
            offset = int(self.tree.winfo_rootx() - self.check_bar.winfo_rootx())
        except tk.TclError:
            offset = 0
        width = self.check_bar.winfo_width() or self.winfo_width()
        for index, (name, widgets) in enumerate(self._checks.items()):
            box = None
            for row in rows:            # a visible row gives the exact place
                box = self.tree.bbox(row, f"#{index + 1}")
                if box:
                    break
            if not box:
                box = self._column_span(index)
            pair = list(widgets.values())
            lbl = getattr(self, "_col_labels", {}).get(name)
            if box is None:
                for check in pair:
                    check.place_forget()
                if lbl:
                    lbl.place_forget()
                continue
            x = offset + box[0] + box[2] / 2
            if x < 0 or (width and x > width):
                for check in pair:
                    check.place_forget()
                if lbl:
                    lbl.place_forget()
                continue
            pair[0].place(x=int(x) - 2, y=12, anchor="e")
            pair[1].place(x=int(x) + 2, y=12, anchor="w")
            if lbl:
                # a strip as wide as the letter needs to be easy to hit
                strip = max(24, min(int(box[2]) - 8, LETTER_WIDTH))
                lbl.place(x=int(x), y=32, anchor="center",
                          width=strip, height=17)

    def _column_span(self, index):
        """(x, y, width, height) of one column when no row is visible."""
        columns = self.tree["columns"]
        if index >= len(columns):
            return None
        start = 0
        for other in columns[:index]:
            start += int(self.tree.column(other, "width"))
        try:
            first = float(self.tree.xview()[0])
        except (tk.TclError, ValueError, IndexError):
            first = 0.0
        total = sum(int(self.tree.column(one, "width")) for one in columns) or 1
        return (int(start - first * total), 0,
                int(self.tree.column(columns[index], "width")), 0)

    def column_axis(self, name):
        """"B"/"T" for the X column, "L"/"R" for a Y column, None if unused."""
        for code, variable in (self.axis_vars.get(str(name)) or {}).items():
            try:
                if bool(variable.get()):
                    return code
            except tk.TclError:
                return None
        return None

    def set_column_axis(self, name, code):
        """Tick one of the two check buttons of a column (None: neither)."""
        variables = self.axis_vars.get(str(name))
        if variables is None:
            return False
        if code is not None and code not in variables:
            return False
        for one, variable in variables.items():
            variable.set(one == code)
        if code is None and self._is_x_column(name):
            variables["B"].set(True)       # the X column keeps an axis
        self._changed()
        return True

    def axis_check(self, name, code):
        """The check button widget itself - used by the hints and the tests."""
        return (self._checks.get(str(name)) or {}).get(code)

    def plot_columns(self):
        """The X column plus every Y column that has an axis ticked."""
        names = [str(name) for name in self.df.columns]
        if not names:
            return []
        chosen = [names[0]]
        for name in names[1:]:
            if self.column_axis(name) in Y_SIDES:
                chosen.append(name)
        return chosen

    def plot_layout(self):
        """Which axis every plotted column belongs to."""
        names = [str(name) for name in self.df.columns]
        if not names:
            return {"x": None, "x_side": "bottom", "y": {}}
        x_name = names[0]
        x_side = X_SIDES.get(self.column_axis(x_name) or "B", "bottom")
        sides = {}
        for name in names[1:]:
            code = self.column_axis(name)
            if code in Y_SIDES:
                sides[name] = Y_SIDES[code]
        return {"x": x_name, "x_side": x_side, "y": sides}

    def plot_dataframe(self, least=1):
        """The data of the ticked columns only.

        `least` is how many columns the diagram needs.  One is enough for
        every style now: a histogram counts a single column of raw values,
        and every other diagram draws it against the row numbers.
        """
        columns = self.plot_columns()
        if len(columns) < max(1, int(least)):
            return self.df.iloc[:, :0]
        return self.df[columns].copy()

    def set_plot_column(self, name, plotted=True):
        """Plot this column on its first axis, or not at all."""
        if not plotted and self._is_x_column(name):
            return False
        if plotted:
            index = [str(one) for one in self.df.columns].index(str(name)) \
                if str(name) in [str(one) for one in self.df.columns] else 1
            return self.set_column_axis(name,
                                        AXIS_TAGS[self._axis_family(index)][0][0])
        return self.set_column_axis(name, None)

    def check_all_columns(self):
        """Every column on its first axis: the bottom X and the left Y."""
        for index, name in enumerate(self._checks):
            variables = self.axis_vars[name]
            first = AXIS_TAGS[self._axis_family(index)][0][0]
            for code, variable in variables.items():
                variable.set(code == first)
        self._changed()

    # -- the highlighted block of cells ------------------------------------
    def _bind_grid_keys(self):
        """Keys of the table itself, when no cell editor is open."""
        tree = self.tree

        def wrap(function, *args):
            def handler(_event=None):
                function(*args)
                return "break"
            return handler

        steps = {"Left": (0, -1), "Right": (0, 1), "Up": (-1, 0), "Down": (1, 0)}
        for name, (d_row, d_col) in steps.items():
            tree.bind(f"<{name}>", wrap(self.move_cursor, d_row, d_col))
            tree.bind(f"<Shift-{name}>", wrap(self.extend_block, d_row, d_col))
        tree.bind("<Return>", wrap(self.edit_cursor))
        tree.bind("<KP_Enter>", wrap(self.edit_cursor))
        tree.bind("<F2>", wrap(self.edit_cursor))
        for modifier in ("Control", "Command"):
            tree.bind(f"<{modifier}-a>", wrap(self.select_all_cells))
            tree.bind(f"<{modifier}-A>", wrap(self.select_all_cells))
            tree.bind(f"<{modifier}-c>", wrap(self.copy_block))
            tree.bind(f"<{modifier}-C>", wrap(self.copy_block))
            tree.bind(f"<{modifier}-v>", wrap(self.paste_block))
            tree.bind(f"<{modifier}-V>", wrap(self.paste_block))
            tree.bind(f"<{modifier}-x>", wrap(self.cut_block))
            tree.bind(f"<{modifier}-X>", wrap(self.cut_block))
            # Duplicate, as in the Edit menu; filling down keeps its own
            # button in the formula bar
            tree.bind(f"<{modifier}-d>", wrap(self.duplicate_block))
            tree.bind(f"<{modifier}-D>", wrap(self.duplicate_block))
            tree.bind(f"<{modifier}-space>", wrap(self.select_columns_of_block))
        tree.bind("<Shift-space>", wrap(self.select_rows_of_block))
        for sequence in ("<Delete>", "<BackSpace>"):
            tree.bind(sequence, wrap(self.clear_block))
        # anything else that is a character starts writing the cell
        tree.bind("<Key>", self._on_grid_typing)

    def _shape(self):
        return len(self.df), len(self.df.columns)

    def block_bounds(self):
        """The block as (row0, col0, row1, col1), clamped to the table."""
        rows, columns = self._shape()
        if not rows or not columns:
            return None
        if self.block is None:
            row, col = self.cursor
            self.block = (row, col, row, col)
        r0, c0, r1, c1 = self.block
        r0, r1 = sorted((max(0, min(rows - 1, r0)), max(0, min(rows - 1, r1))))
        c0, c1 = sorted((max(0, min(columns - 1, c0)),
                         max(0, min(columns - 1, c1))))
        self.block = (r0, c0, r1, c1)
        return self.block

    def block_cells(self):
        """Number of cells, rows and columns in the block."""
        bounds = self.block_bounds()
        if bounds is None:
            return (0, 0, 0)
        r0, c0, r1, c1 = bounds
        return ((r1 - r0 + 1) * (c1 - c0 + 1), r1 - r0 + 1, c1 - c0 + 1)

    def select_block(self, r0, c0, r1, c1, anchor=None, cursor=None):
        """Highlight a rectangular block of cells."""
        rows, columns = self._shape()
        if not rows or not columns:
            return None
        self.block = (r0, c0, r1, c1)
        bounds = self.block_bounds()
        self.anchor = anchor if anchor is not None else (bounds[0], bounds[1])
        self.cursor = cursor if cursor is not None else (bounds[2], bounds[3])
        self._refresh_block()
        self._update_formula_bar()
        self._update_status_bar()
        return bounds

    def select_cell(self, row, col):
        """One cell: it becomes the block, the anchor and the cursor."""
        return self.select_block(row, col, row, col,
                                 anchor=(row, col), cursor=(row, col))

    def extend_block_to(self, row, col):
        """Stretch the block from the anchor to this cell."""
        rows, columns = self._shape()
        row = max(0, min(rows - 1, int(row)))
        col = max(0, min(columns - 1, int(col)))
        a_row, a_col = self.anchor
        return self.select_block(a_row, a_col, row, col,
                                 anchor=self.anchor, cursor=(row, col))

    def extend_block(self, d_row, d_col):
        """Shift+arrow: one row or column more (or less) in the block.

        The sheet follows the end of the block in both directions, so
        holding Shift and an arrow walks the selection into the rows and
        the columns that were not on the screen.
        """
        rows, columns = self._shape()
        if not rows or not columns:
            return False
        self.block_bounds()
        row, col = self.cursor
        row = max(0, min(rows - 1, row + d_row))
        col = max(0, min(columns - 1, col + d_col))
        self.extend_block_to(row, col)
        self.see_cell(row, col)
        self._refresh_outline()
        return True

    def see_cell(self, row, col):
        """Scroll until this cell is really on the screen, both ways."""
        try:
            self.tree.see(str(int(row)))
        except (tk.TclError, ValueError):
            pass
        return self.see_column(col)

    def see_column(self, col):
        """Scroll sideways until this column is fully in view.

        `Treeview.see` knows about rows only, so the sideways part is
        worked out from the widths of the columns: where the wanted one
        begins and ends against the strip that is on the screen.
        """
        try:
            names = list(self.tree["columns"])
            index = int(col)
        except (tk.TclError, TypeError, ValueError):
            return False
        if not (0 <= index < len(names)):
            return False
        try:
            widths = [float(self.tree.column(one, "width")) for one in names]
            first, last = (float(one) for one in self.tree.xview())
        except (tk.TclError, TypeError, ValueError):
            return False
        total = sum(widths)
        if total <= 0 or last - first >= 1.0:
            return False              # everything fits: nothing to scroll
        start = sum(widths[:index])
        end = start + widths[index]
        shown = (last - first) * total
        if start < first * total - 0.5:
            self.tree.xview_moveto(max(0.0, start / total))
        elif end > last * total + 0.5:
            self.tree.xview_moveto(max(0.0, (end - shown) / total))
        else:
            return False
        self.after(1, self._refresh_outline)
        return True

    def move_cursor(self, d_row, d_col):
        """An arrow key without Shift: one cell, and the block collapses."""
        rows, columns = self._shape()
        if not rows or not columns:
            return False
        row, col = self.cursor
        row = max(0, min(rows - 1, row + d_row))
        col = max(0, min(columns - 1, col + d_col))
        self.select_cell(row, col)
        self.see_cell(row, col)
        return True

    def select_all_cells(self):
        rows, columns = self._shape()
        if not rows or not columns:
            return False
        self.select_block(0, 0, rows - 1, columns - 1,
                          anchor=(0, 0), cursor=(rows - 1, columns - 1))
        return True

    def select_rows_of_block(self):
        """Shift+Space: the whole rows the block touches."""
        bounds = self.block_bounds()
        if bounds is None:
            return False
        r0, _c0, r1, _c1 = bounds
        self.select_block(r0, 0, r1, len(self.df.columns) - 1,
                          anchor=(r0, 0), cursor=self.cursor)
        return True

    def select_columns_of_block(self):
        """Ctrl/Cmd+Space: the whole columns the block touches."""
        bounds = self.block_bounds()
        if bounds is None:
            return False
        _r0, c0, _r1, c1 = bounds
        self.select_block(0, c0, len(self.df) - 1, c1,
                          anchor=(0, c0), cursor=self.cursor)
        return True

    def selected_rows(self):
        """Row indices of the block."""
        bounds = self.block_bounds()
        return [] if bounds is None else list(range(bounds[0], bounds[2] + 1))

    def selected_columns(self):
        """Column names of the block."""
        bounds = self.block_bounds()
        if bounds is None:
            return []
        return [str(name) for name in self.df.columns[bounds[1]:bounds[3] + 1]]

    def edit_cursor(self):
        row, col = self.cursor
        self._begin_edit(str(row), col)
        return True

    def take_keyboard(self):
        """Give the keyboard to this sheet, with a cell under the cursor.

        Tk hands a new window to no widget in particular, so until a cell
        had been clicked the arrow keys went nowhere and nothing typed
        arrived anywhere.  The sheet asks for the keyboard itself instead -
        when the program starts, when another sheet comes to the front and
        after a file has been opened - and the cell the cursor is on is
        highlighted, ready to be typed into.
        """
        if self._editor is not None or self._heading_editor is not None:
            return False              # an open cell keeps the keyboard
        try:
            if not self.tree.winfo_exists():
                return False
            self.tree.focus_set()
        except tk.TclError:
            return False
        rows, columns = self._shape()
        if rows and columns:
            row, col = self.cursor
            if self.block is None or not (0 <= row < rows and 0 <= col < columns):
                self.select_cell(0, 0)
        return True

    def _on_grid_typing(self, event):
        """A character typed on the grid opens the cell and goes into it.

        The arrows, Enter, Delete and the commands of Ctrl / Cmd have their
        own bindings and never reach this one: Tk offers a key press to the
        closest pattern it finds.  What is left is the ordinary typing, and
        it starts writing the cell the cursor is on, as a spreadsheet does.
        """
        if self._editor is not None or self._heading_editor is not None:
            return None
        try:                     # Ctrl / Alt / Cmd: a command, not a letter
            if int(event.state or 0) & (TYPING_COMMAND_KEYS):
                return None
        except (TypeError, ValueError):
            pass
        text = str(event.char or "")
        if len(text) != 1 or not text.isprintable():
            return None
        rows, columns = self._shape()
        row, col = self.cursor
        if not (0 <= row < rows and 0 <= col < columns):
            return None
        self._begin_edit(str(row), col)
        if self._editor is None:
            return None
        entry = self._editor[0]
        try:
            entry.delete(0, "end")
            entry.insert(0, text)
            entry.icursor("end")
        except tk.TclError:
            return None
        return "break"

    # -- how the block is shown -------------------------------------------
    def covers_whole_rows(self):
        """True when the block reaches from the first to the last column."""
        bounds = self.block_bounds()
        if bounds is None:
            return False
        return bounds[1] == 0 and bounds[3] == len(self.df.columns) - 1

    def covers_whole_columns(self):
        """True when the block reaches from the first to the last row."""
        bounds = self.block_bounds()
        if bounds is None:
            return False
        return bounds[0] == 0 and bounds[2] == len(self.df) - 1

    def _refresh_block(self):
        """Show the block: whole rows are tinted, a part of a row outlined.

        A row can only be coloured as a whole, so the tint is used only when
        the block really covers every column of those rows (Shift+Space, a
        drag across all the columns, Ctrl/Cmd+A).  A single cell or a few
        columns of it are marked by the blue rectangle alone, which keeps
        editing one cell quiet.
        """
        bounds = self.block_bounds()
        rows = set()
        if bounds is not None and self.covers_whole_rows():
            rows = set(range(bounds[0], bounds[2] + 1))
        for item in self.tree.get_children():
            wanted = ("block",) if int(item) in rows else ()
            if tuple(self.tree.item(item, "tags")) != wanted:
                self.tree.item(item, tags=wanted)

        if hasattr(self, "row_tree"):
            active_rows = set(range(bounds[0], bounds[2] + 1)) if bounds is not None else set()
            for item in self.row_tree.get_children():
                wanted = ("active_row",) if int(item) in active_rows else ()
                if tuple(self.row_tree.item(item, "tags")) != wanted:
                    self.row_tree.item(item, tags=wanted)

        self._refresh_letters(bounds)
        self._refresh_outline()

    def _refresh_letters(self, bounds=None):
        """Tint the letter of every column the block touches."""
        labels = getattr(self, "_col_labels", None)
        if not labels:
            return
        if bounds is None:
            bounds = self.block_bounds()
        active = set(range(bounds[1], bounds[3] + 1)) if bounds is not None \
            else set()
        quiet = self.header_background()
        for index, name in enumerate(str(one) for one in self.df.columns):
            label = labels.get(name)
            if label is None:
                continue
            wanted = HEADER_ACTIVE if index in active else quiet
            try:
                if str(label.cget("background")) != wanted:
                    label.configure(background=wanted)
            except tk.TclError:
                continue

    def _outline_frames(self):
        if not self._outline:
            self._outline = [tk.Frame(self.tree, background=SELECT_COLOR)
                             for _ in range(4)]
        return self._outline

    def _hide_outline(self):
        for frame in self._outline:
            frame.place_forget()
        if hasattr(self, "_fill_handle") and self._fill_handle is not None:
            self._fill_handle.place_forget()
        self._hide_fill_feedback()

    def _layout_changed(self):
        self._refresh_outline()
        self._place_checks()
        if getattr(self, "auto_columns", False):
            # the window became wider: a blank sheet fills it with columns
            if self._grow_timer is not None:
                try:
                    self.after_cancel(self._grow_timer)
                except tk.TclError:
                    pass
            self._grow_timer = self.after(60, self._grow_now)

    def _grow_now(self):
        self._grow_timer = None
        self.grow_columns_to_fit()

    def _draw_gridlines(self):
        if not hasattr(self, "_grid_lines"):
            self._grid_lines = []
            
        try:
            first_frac, last_frac = self.tree.yview()
        except Exception:
            return
            
        children = self.tree.get_children()
        num_items = len(children)
        if num_items == 0: 
            return
            
        first_idx = max(0, int(first_frac * num_items) - 2)
        last_idx = min(num_items - 1, int(last_frac * num_items) + 2)
        
        needed = (last_idx - first_idx + 1) + len(self.tree["displaycolumns"])
        while len(self._grid_lines) < needed:
            self._grid_lines.append(tk.Frame(self.tree, background="#e8e8e8"))
            
        for f in self._grid_lines:
            f.place_forget()
            
        f_idx = 0
        tree_h = self.tree.winfo_height()
        
        # Draw vertical lines
        try:
            for col in self.tree["displaycolumns"]:
                bbox = self.tree.bbox(children[0], col)
                if bbox:
                    x = bbox[0] + bbox[2]
                    self._grid_lines[f_idx].place(x=x-1, y=0, width=1, height=tree_h)
                    f_idx += 1
        except tk.TclError:
            pass
                
        # Draw horizontal lines
        try:
            for i in range(first_idx, last_idx + 1):
                bbox = self.tree.bbox(children[i], self.tree["displaycolumns"][0])
                if bbox:
                    y = bbox[1] + bbox[3]
                    self._grid_lines[f_idx].place(x=0, y=y-1, relwidth=1, height=1)
                    f_idx += 1
        except (tk.TclError, IndexError):
            pass

    def _refresh_outline(self):
        """Draw the blue rectangle around the visible part of the block and the fill handle."""
        self._draw_gridlines()
        bounds = self.block_bounds()
        if bounds is None or not self.tree.get_children():
            self._hide_outline()
            return
        r0, c0, r1, c1 = bounds
        try:
            self.tree.update_idletasks()
        except tk.TclError:
            return
        first = self._visible_cell(r0, r1, c0)
        last = self._visible_cell(r1, r0, c1, from_bottom=True)
        if first is None or last is None:
            self._hide_outline()
            return
        x0, y0 = first[0], first[1]
        x1 = last[0] + last[2]
        y1 = last[1] + last[3]
        if x1 <= x0 or y1 <= y0:
            self._hide_outline()
            return
        top, bottom, left, right = self._outline_frames()
        width, height = x1 - x0, y1 - y0
        top.place(x=x0, y=y0, width=width, height=BLOCK_LINE)
        bottom.place(x=x0, y=y1 - BLOCK_LINE, width=width, height=BLOCK_LINE)
        left.place(x=x0, y=y0, width=BLOCK_LINE, height=height)
        right.place(x=x1 - BLOCK_LINE, y=y0, width=BLOCK_LINE, height=height)

        # Black square fill handle at the bottom-right corner of the selection
        handle = self._get_fill_handle()
        handle.place(x=x1 - 4, y=y1 - 4,
                     width=FILL_HANDLE_SIZE, height=FILL_HANDLE_SIZE)
        self._lift_overlays()

    def _lift_overlays(self):
        """Keep the fill handle above the cell editor.

        The editor of a cell is a child of the table too, and it is built
        after the outline, so without this it would lie on top of the black
        fill handle - the pointer would reach the text field instead of the
        handle, and the selection could not be pulled down any more.

        Only the handle is raised, never the blue frames: those carry no
        binding of their own, so above the editor they would only make a
        two pixel dead border around the text.
        """
        handle = getattr(self, "_fill_handle", None)
        if handle is not None:
            try:
                handle.lift()
            except tk.TclError:
                pass

    def _visible_cell(self, row, other, col, from_bottom=False):
        """bbox of a cell, walking towards `other` until one is on screen."""
        step = -1 if row > other else 1
        current = row
        while True:
            if self.tree.exists(str(current)):
                bbox = self.tree.bbox(str(current), f"#{col + 1}")
                if bbox:
                    return bbox
            if current == other:
                return None
            current += step

    # -- fill handle interaction -------------------------------------------
    def _get_fill_handle(self):
        if not hasattr(self, "_fill_handle") or self._fill_handle is None:
            self._fill_handle = tk.Frame(self.tree, background="#000000", cursor="crosshair")
            self._fill_handle.bind("<Button-1>", self._on_fill_press)
            self._fill_handle.bind("<B1-Motion>", self._on_fill_drag)
            self._fill_handle.bind("<ButtonRelease-1>", self._on_fill_release)
            self._fill_handle.bind("<Double-Button-1>", self._on_fill_double_click)
            self._fill_handle.bind("<Alt-Double-Button-1>", self._on_fill_double_click)
        return self._fill_handle

    def _get_fill_feedback(self):
        if not hasattr(self, "_fill_feedback") or not self._fill_feedback:
            self._fill_feedback = [tk.Frame(self.tree, background="#555555")
                                   for _ in range(4)]
        return self._fill_feedback

    def _show_fill_feedback(self, r0, r1, c0, c1):
        first = self._visible_cell(r0, r1, c0)
        last = self._visible_cell(r1, r0, c1, from_bottom=True)
        if first is None or last is None:
            self._hide_fill_feedback()
            return
        x0, y0 = first[0], first[1]
        x1 = last[0] + last[2]
        y1 = last[1] + last[3]
        if x1 <= x0 or y1 <= y0:
            self._hide_fill_feedback()
            return
        frames = self._get_fill_feedback()
        w, h = x1 - x0, y1 - y0
        frames[0].place(x=x0, y=y0, width=w, height=1)
        frames[1].place(x=x0, y=y1 - 1, width=w, height=1)
        frames[2].place(x=x0, y=y0, width=1, height=h)
        frames[3].place(x=x1 - 1, y=y0, width=1, height=h)

    def _hide_fill_feedback(self):
        if hasattr(self, "_fill_feedback") and self._fill_feedback:
            for f in self._fill_feedback:
                f.place_forget()

    def _on_fill_press(self, event):
        self._commit_edit()
        bounds = self.block_bounds()
        if bounds is None:
            return "break"
        self._fill_dragging = True
        self._fill_start_bounds = bounds
        self._fill_target_row = bounds[2]
        self._fill_target_col = bounds[3]
        self._fill_direction = None        # nothing from an earlier pull
        self._fill_point = None
        try:
            self._fill_press = (event.x_root - self.tree.winfo_rootx(),
                                event.y_root - self.tree.winfo_rooty())
        except (tk.TclError, AttributeError, TypeError):
            self._fill_press = None
        self._show_fill_feedback(bounds[2], bounds[2], bounds[1], bounds[3])
        return "break"

    def _on_fill_drag(self, event):
        if not getattr(self, "_fill_dragging", False):
            return "break"
        try:
            tree_x = event.x_root - self.tree.winfo_rootx()
            tree_y = event.y_root - self.tree.winfo_rooty()
        except (tk.TclError, AttributeError):
            tree_x = event.x
            tree_y = event.y
        # held against the bottom (or the top) edge, the table scrolls on
        # by itself, so a series can be pulled far past the rows that
        # happen to be on the screen
        self._fill_point = (tree_x, tree_y)
        if self._fill_edge_step(tree_y) or self._fill_side_step(tree_x):
            self._start_fill_auto_scroll()
        else:
            self._stop_fill_auto_scroll()
        return self._aim_fill(tree_x, tree_y)

    def _row_near(self, y, widget=None):
        """The row at that height, or the nearest one above it.

        The last row of a sheet rarely ends exactly at the bottom of the
        table, and below it there is no row to identify at all.  Pulling
        the pointer into that empty strip means the last row, not
        "nowhere".  `widget` is the table itself or the strip of row
        numbers beside it - the two are always scrolled together.
        """
        widget = self.tree if widget is None else widget
        for step in range(0, 240, 4):
            try:
                row_id = widget.identify_row(max(0, y - step))
            except tk.TclError:
                return None
            if row_id and self.tree.exists(row_id):
                try:
                    return int(row_id)
                except (TypeError, ValueError):
                    return None
        return None

    def _fill_side_step(self, x):
        """1 right, -1 left, 0 when the pointer is not at a side edge."""
        try:
            width = self.tree.winfo_width()
        except tk.TclError:
            return 0
        if x > width - AUTO_SCROLL_EDGE:
            return 1
        if x < AUTO_SCROLL_EDGE:
            return -1
        return 0

    def _fill_edge_step(self, y):
        """1 down, -1 up, 0 when the pointer is not at an edge of the table."""
        try:
            height = self.tree.winfo_height()
            header = self._header_height()
        except tk.TclError:
            return 0
        if y > height - AUTO_SCROLL_EDGE:
            return 1
        if y < header + AUTO_SCROLL_EDGE:
            return -1
        return 0

    def _aim_fill(self, tree_x, tree_y):
        """Where the handle is being pulled to, and what that would fill.

        The pointer is pulled back inside the table first: past the edge
        there is no row to ask about, and the row wanted there is the last
        one on the screen - which the automatic scrolling keeps replacing
        with the next one.
        """
        try:
            header = self._header_height()
            tree_y = min(max(tree_y, header + 2),
                         max(header + 2, self.tree.winfo_height() - 2))
            tree_x = min(max(tree_x, 2), max(2, self.tree.winfo_width() - 2))
        except tk.TclError:
            pass

        r0, c0, r1, c1 = self._fill_start_bounds
        press = getattr(self, "_fill_press", None)
        if press is not None and abs(tree_x - press[0]) < FILL_DRAG_START \
                and abs(tree_y - press[1]) < FILL_DRAG_START:
            # still where the button went down: a click, not a pull
            self._fill_direction = None
            self._fill_target_row, self._fill_target_col = r1, c1
            self._hide_fill_feedback()
            return "break"

        col_id = self.tree.identify_column(tree_x)

        target_r = r1
        target_c = c1

        hovered = self._row_near(tree_y)
        hover_r = r1 if hovered is None else hovered


        if col_id:
            hover_c = int(col_id.replace('#', '')) - 1
        else:
            hover_c = c1
            
        dr_down = max(0, hover_r - r1)
        dr_up = max(0, r0 - hover_r)
        dc_right = max(0, hover_c - c1)
        dc_left = max(0, c0 - hover_c)
        
        max_d = max(dr_down, dr_up, dc_right, dc_left)
        
        if max_d == 0:
            self._fill_direction = None
            self._hide_fill_feedback()
            self._update_status_bar()
            return "break"
            
        if max_d == dr_down:
            self._fill_direction = "down"
            target_r = r1 + dr_down
            self._show_fill_feedback(r1 + 1, target_r, c0, c1)
            self._show_fill_hint(r0, r1, c0, target_r)
        elif max_d == dr_up:
            self._fill_direction = "up"
            target_r = r0 - dr_up
            self._show_fill_feedback(target_r, r0 - 1, c0, c1)
            self._update_status_bar()
        elif max_d == dc_right:
            self._fill_direction = "right"
            target_c = c1 + dc_right
            self._show_fill_feedback(r0, r1, c1 + 1, target_c)
            self._update_status_bar()
        elif max_d == dc_left:
            self._fill_direction = "left"
            target_c = c0 - dc_left
            self._show_fill_feedback(r0, r1, target_c, c0 - 1)
            self._update_status_bar()
            
        self._fill_target_row = target_r
        self._fill_target_col = target_c
        return "break"

    def _show_fill_hint(self, r0, r1, column, target_r):
        """Say in the status bar what pulling the handle down will write."""
        if not hasattr(self, "status_label"):
            return
        rows = target_r - r1
        step = self.series_step(r0, r1, column)
        anchor = self.cell_number(r1, column)
        if step is None or anchor is None:
            self.status_label.configure(
                text=f"Fill down: the value is copied into {rows} more "
                     f"row{'s' if rows != 1 else ''}")
            return
        preview = ", ".join(
            self._number_text(self.series_value(anchor, step, one))
            for one in range(1, min(rows, 3) + 1))
        if rows > 3:
            preview += ", ..."
        self.status_label.configure(
            text=f"Series, step {self._number_text(step)}:  {preview}"
                 f"   ({rows} row{'s' if rows != 1 else ''})")

    def _on_fill_release(self, _event=None):
        if not getattr(self, "_fill_dragging", False):
            return "break"
        self._stop_fill_auto_scroll()
        self._hide_fill_feedback()
        self._fill_dragging = False

        r0, c0, r1, c1 = self._fill_start_bounds
        direction = getattr(self, "_fill_direction", None)
        target_r = getattr(self, "_fill_target_row", r1)
        target_c = getattr(self, "_fill_target_col", c1)
        
        if direction:
            self._execute_fill(r0, c0, r1, c1, target_r, target_c, direction)
            if direction == "down":
                self.select_block(r0, c0, target_r, c1, anchor=(r0, c0), cursor=(target_r, c1))
                self.tree.see(str(target_r))
            elif direction == "up":
                self.select_block(target_r, c0, r1, c1, anchor=(r1, c1), cursor=(target_r, c0))
                self.tree.see(str(target_r))
            elif direction == "right":
                self.select_block(r0, c0, r1, target_c, anchor=(r0, c0), cursor=(r1, target_c))
            elif direction == "left":
                self.select_block(r0, target_c, r1, c1, anchor=(r1, c1), cursor=(r0, target_c))
        else:
            self._update_status_bar()
        return "break"

    def _on_fill_double_click(self, _event=None):
        """Fill the selected column(s) down as far as the neighbours go.

        Only the columns of the selection are filled - a single cell fills
        its own column and nothing beside it.
        """
        self._commit_edit()
        self._fill_dragging = False        # the second click is no pull
        self._fill_direction = None
        bounds = self.block_bounds()
        if bounds is None:
            return "break"
        r0, c0, r1, c1 = bounds
        target_r = self._find_neighbor_extent(r1, c0, c1)
        if target_r > r1:
            self._execute_fill(r0, c0, r1, c1, target_r, c1, "down")
            self.select_block(r0, c0, target_r, c1, anchor=(r0, c0), cursor=(target_r, c1))
            self.tree.see(str(target_r))
        return "break"

    def _find_neighbor_extent(self, r1, c0, c1):
        """Find how far down adjacent columns have non-empty data."""
        rows_count = len(self.df)
        if rows_count <= r1 + 1:
            return r1

        left_c = c0 - 1
        left_extent = r1
        if left_c >= 0:
            r = r1 + 1
            while r < rows_count:
                val = self.df.iat[r, left_c]
                if pd.isna(val) or str(val).strip() == "":
                    break
                left_extent = r
                r += 1

        right_c = c1 + 1
        right_extent = r1
        if right_c < len(self.df.columns):
            r = r1 + 1
            while r < rows_count:
                val = self.df.iat[r, right_c]
                if pd.isna(val) or str(val).strip() == "":
                    break
                right_extent = r
                r += 1

        if left_extent > r1:
            return left_extent
        if right_extent > r1:
            return right_extent

        return rows_count - 1

    def cell_number(self, row, column):
        """The value of one cell as a number, or None if it is not one."""
        if not (0 <= row < len(self.df) and 0 <= column < len(self.df.columns)):
            return None
        value = self.df.iat[row, column]
        if isinstance(value, bool):
            return None
        if isinstance(value, (int, float, np.integer, np.floating)):
            number = float(value)
        else:
            text = str(value).strip()
            if not text:
                return None
            number = to_float(text)
        if number is None or not np.isfinite(number):
            return None
        return number

    def series_step(self, r0, r1, column):
        """The step of the numbers selected in one column, or None.

        **Two or more numbers** in a column are read as a mathematical
        series, and the step is their average difference - so 1 and 3 go on
        as 5, 7, 9, ... and 10, 8 as 6, 4, 2, ...  Anything that is not a
        plain number (a formula, a text, an empty cell) has no step: such a
        cell is copied, exactly as before.
        """
        if r1 <= r0:
            return None                # one single cell is copied
        values = []
        for row in range(r0, r1 + 1):
            if (row, column) in self.cell_formulas:
                return None            # a formula is carried on, not counted
            number = self.cell_number(row, column)
            if number is None:
                return None
            values.append(number)
        if len(values) < 2:
            return None
        return (values[-1] - values[0]) / (len(values) - 1)

    @staticmethod
    def series_value(anchor, step, distance):
        """The `distance`-th member of the series that follows `anchor`."""
        anchor, step = float(anchor), float(step)
        value = round(anchor + step * int(distance), 10)
        if anchor.is_integer() and step.is_integer():
            return int(round(value))
        return value

    @staticmethod
    def _number_text(value):
        """A number the way it is written into a cell."""
        number = float(value)
        if number.is_integer():
            return str(int(number))
        return f"{round(number, 10):g}"

    def _set_cell_value(self, row, column, value):
        """Write one value into the frame and into the row on the screen."""
        name = self.df.columns[column]
        try:
            self.df.iat[row, column] = value
        except (ValueError, TypeError):
            self.df[name] = self.df[name].astype(object)
            self.df.iat[row, column] = value
        if self.tree.exists(str(row)):
            try:
                empty = value is None or pd.isna(value)
            except (TypeError, ValueError):
                empty = False
            self.tree.set(str(row), name, "" if empty else str(value))

    def _execute_fill(self, r0, c0, r1, c1, target_r, target_c, direction):
        if direction == "down":
            s_r0, s_r1, s_c0, s_c1 = r1, r1, c0, c1
            range_r = range(r1 + 1, target_r + 1)
            range_c = range(c0, c1 + 1)
            delta_sign_r = 1
            delta_sign_c = 0
        elif direction == "up":
            s_r0, s_r1, s_c0, s_c1 = r0, r0, c0, c1
            range_r = range(r0 - 1, target_r - 1, -1)
            range_c = range(c0, c1 + 1)
            delta_sign_r = -1
            delta_sign_c = 0
        elif direction == "right":
            s_r0, s_r1, s_c0, s_c1 = r0, r1, c1, c1
            range_r = range(r0, r1 + 1)
            range_c = range(c1 + 1, target_c + 1)
            delta_sign_r = 0
            delta_sign_c = 1
        elif direction == "left":
            s_r0, s_r1, s_c0, s_c1 = r0, r1, c0, c0
            range_r = range(r0, r1 + 1)
            range_c = range(c0 - 1, target_c - 1, -1)
            delta_sign_r = 0
            delta_sign_c = -1
            
        import copy
        
        
        for r in range_r:
            for c in range_c:
                if direction in ("up", "down"):
                    src_r = s_r0
                    src_c = c
                    step = self.series_step(r0, r1, c) if r0 != r1 else None
                else:
                    src_r = r
                    src_c = s_c0
                    step = None
                
                source_formula = self.cell_formulas.get((src_r, src_c))
                source_val = self.df.iat[src_r, src_c]
                
                if step is not None:
                    anchor = self.cell_number(src_r, src_c)
                    self.cell_formulas.pop((r, c), None)
                    self._set_cell_value(r, c, self.series_value(anchor, step, abs(r - src_r)))
                elif source_formula is not None:
                    delta_row = r - src_r
                    delta_col = c - src_c
                    adj = adjust_formula_references(source_formula, delta_row=delta_row, delta_col=delta_col)
                    self.cell_formulas[(r, c)] = adj
                else:
                    self.cell_formulas.pop((r, c), None)
                    self._set_cell_value(r, c, copy.deepcopy(source_val))

        self.recalculate_all()
        self._changed()
        self._update_formula_bar()
        self._update_status_bar()
        self._refresh_outline()

    def _start_fill_auto_scroll(self):
        if getattr(self, "_fill_auto_scroll_timer", None) is None:
            self._fill_auto_scroll_timer = self.after(AUTO_SCROLL_MS, self._fill_auto_scroll_step)

    def _stop_fill_auto_scroll(self):
        timer = getattr(self, "_fill_auto_scroll_timer", None)
        if timer is not None:
            try:
                self.after_cancel(timer)
            except (tk.TclError, ValueError):
                pass
            self._fill_auto_scroll_timer = None

    def _fill_auto_scroll_step(self):
        """One row of scrolling while the handle is held against an edge."""
        self._fill_auto_scroll_timer = None
        if not getattr(self, "_fill_dragging", False):
            return
        point = getattr(self, "_fill_point", None)
        step = self._fill_edge_step(point[1]) if point else 0
        sideways = self._fill_side_step(point[0]) if point else 0
        first, last = self.tree.yview()
        if step > 0 and last >= 1.0:
            step = 0            # the last row of the sheet is on the screen
        if step < 0 and first <= 0.0:
            step = 0            # the first one is
        left, right = self.tree.xview()
        if (sideways > 0 and right >= 1.0) or (sideways < 0 and left <= 0.0):
            sideways = 0
        if not (step or sideways):
            return
        if step:
            self._yview("scroll", step, "units")
        if sideways:
            self.tree.xview_scroll(sideways * AUTO_SCROLL_PIXELS, "units")
        try:
            self.tree.update_idletasks()
        except tk.TclError:
            return
        # the row that has just come into view is the one being pulled to
        self._aim_fill(*point)
        self._start_fill_auto_scroll()

    # -- row tree interactions (line numbers on the left) ------------------
    def _on_row_tree_wheel(self, event):
        if sys.platform == "darwin":
            delta = -int(event.delta)
        elif getattr(event, "num", None) == 4:
            delta = -1
        elif getattr(event, "num", None) == 5:
            delta = 1
        else:
            delta = -int(event.delta / 120)
        self.tree.yview_scroll(delta, "units")
        if hasattr(self, "row_tree"):
            self.row_tree.yview_scroll(delta, "units")
        self.after(1, self._refresh_outline)
        return "break"

    def _on_row_tree_click(self, event):
        row_id = self.row_tree.identify_row(event.y)
        if row_id and self.row_tree.exists(row_id):
            r = int(row_id)
            if 0 <= r < len(self.df) and len(self.df.columns):
                self._commit_edit()
                self.select_block(r, 0, r, len(self.df.columns) - 1,
                                  anchor=(r, 0), cursor=(r, len(self.df.columns) - 1))
                self._row_selecting = True
                self._row_press = r
        return "break"

    def _on_row_tree_drag(self, event):
        """Pulling along the numbers takes every row it passes.

        Held against the bottom (or the top) edge, the sheet scrolls on by
        itself, so a block can reach far past the rows that happen to be
        on the screen - exactly as the fill handle does.
        """
        if not getattr(self, "_row_selecting", False):
            return "break"
        self._row_point = event.y
        if self._row_edge_step(event.y):
            self._start_edge_scroll()
        else:
            self._stop_edge_scroll()
        self._aim_row_drag(event.y)
        return "break"

    def _row_edge_step(self, y):
        """1 down, -1 up, 0 while the pointer is inside the numbers."""
        try:
            height = self.row_tree.winfo_height()
            header = self._header_height()
        except tk.TclError:
            return 0
        if y > height - AUTO_SCROLL_EDGE:
            return 1
        if y < header + AUTO_SCROLL_EDGE:
            return -1
        return 0

    def _aim_row_drag(self, y):
        """Stretch the block of rows to the number under the pointer."""
        if not getattr(self, "_row_selecting", False):
            return False
        if not len(self.df.columns):
            return False
        try:
            header = self._header_height()
            y = min(max(y, header + 2),
                    max(header + 2, self.row_tree.winfo_height() - 2))
        except tk.TclError:
            pass
        row = self._row_near(y, self.row_tree)
        if row is None or not (0 <= row < len(self.df)):
            return False
        start = getattr(self, "_row_press", row)
        first, last = min(start, row), max(start, row)
        self.select_block(first, 0, last, len(self.df.columns) - 1,
                          anchor=(start, 0),
                          cursor=(row, len(self.df.columns) - 1))
        return True

    def _on_row_tree_release(self, _event=None):
        self._row_selecting = False
        self._stop_edge_scroll()
        return "break"

    # -- clicking a column letter selects the whole column ------------------
    def _column_at_root(self, x_root):
        """Which column is under this screen position (the nearest one)."""
        columns = self.tree["columns"]
        if not columns:
            return None
        try:
            x = int(x_root - self.tree.winfo_rootx())
            width = int(self.tree.winfo_width())
        except tk.TclError:
            return None
        x = max(0, min(x, max(0, width - 1)))     # past the edge: stay inside
        column_id = self.tree.identify_column(x)
        try:
            index = int(str(column_id)[1:]) - 1
        except (TypeError, ValueError):
            return None
        if 0 <= index < len(self.df.columns):
            return index
        return None

    def select_whole_columns(self, c0, c1=None, anchor_col=None):
        """Highlight one column - or a range of them - from top to bottom."""
        rows, columns = self._shape()
        if not rows or not columns:
            return False
        c0 = max(0, min(columns - 1, int(c0)))
        c1 = c0 if c1 is None else max(0, min(columns - 1, int(c1)))
        start = c0 if anchor_col is None else max(0, min(columns - 1,
                                                         int(anchor_col)))
        self.select_block(0, c0, rows - 1, c1,
                          anchor=(0, start), cursor=(rows - 1, c1))
        return True

    def _hide_letter_tooltip(self, index):
        """A press on the letter puts its own hint away."""
        names = [str(one) for one in self.df.columns]
        label = (getattr(self, "_col_labels", {}) or {}).get(
            names[index] if 0 <= index < len(names) else None)
        tooltip = getattr(label, "tooltip", None)
        if tooltip is not None:
            tooltip._left()

    def _on_letter_click(self, index, _event=None):
        """A click on A, B, C, ... takes the whole column."""
        self._hide_letter_tooltip(index)
        if not len(self.df.columns) or not len(self.df):
            return "break"
        self._commit_edit()
        self.current_column = str(self.df.columns[index]) \
            if index < len(self.df.columns) else self.current_column
        self.select_whole_columns(index)
        self._letter_selecting = True
        self._letter_press = index
        self.tree.focus_set()
        return "break"

    def _on_letter_shift_click(self, index, _event=None):
        """Shift+click on a letter stretches the block of columns."""
        self._hide_letter_tooltip(index)
        if not len(self.df.columns) or not len(self.df):
            return "break"
        self._commit_edit()
        start = self.anchor[1] if self.anchor else index
        self.select_whole_columns(start, index, anchor_col=start)
        self._letter_selecting = True
        self._letter_press = start
        self.tree.focus_set()
        return "break"

    def _on_letter_drag(self, event):
        """Dragging along the letters selects a range of columns.

        Held against the left or the right edge of the table, it scrolls
        sideways by itself, so the block can reach the columns that are
        not on the screen.
        """
        if not getattr(self, "_letter_selecting", False):
            return "break"
        self._letter_point = event.x_root
        if self._letter_edge_step(event.x_root):
            self._start_edge_scroll()
        else:
            self._stop_edge_scroll()
        self._aim_letter_drag(event.x_root)
        return "break"

    def _letter_edge_step(self, x_root):
        """1 to the right, -1 to the left, 0 inside the table."""
        try:
            x = int(x_root) - self.tree.winfo_rootx()
            width = self.tree.winfo_width()
        except tk.TclError:
            return 0
        if x > width - AUTO_SCROLL_EDGE:
            return 1
        if x < AUTO_SCROLL_EDGE:
            return -1
        return 0

    def _aim_letter_drag(self, x_root):
        """Stretch the block of columns to the letter under the pointer."""
        if not getattr(self, "_letter_selecting", False):
            return False
        try:                      # past the edge there is no letter to find
            left = self.tree.winfo_rootx()
            width = self.tree.winfo_width()
            x_root = min(max(int(x_root), left + 2), left + max(2, width - 2))
        except tk.TclError:
            pass
        index = self._column_at_root(x_root)
        if index is None:
            return False
        start = getattr(self, "_letter_press", index)
        self.select_whole_columns(start, index, anchor_col=start)
        return True

    def _on_letter_release(self, _event=None):
        self._letter_selecting = False
        self._stop_edge_scroll()
        return "break"

    # -- a header drag held past an edge keeps the sheet moving ------------
    def _start_edge_scroll(self):
        if getattr(self, "_edge_scroll_timer", None) is None:
            self._edge_scroll_timer = self.after(AUTO_SCROLL_MS,
                                                 self._edge_scroll_step)

    def _stop_edge_scroll(self):
        timer = getattr(self, "_edge_scroll_timer", None)
        if timer is not None:
            try:
                self.after_cancel(timer)
            except (tk.TclError, ValueError):
                pass
            self._edge_scroll_timer = None

    def _edge_scroll_step(self):
        """One row (or one column) of scrolling, then aim again."""
        self._edge_scroll_timer = None
        if getattr(self, "_row_selecting", False):
            point = getattr(self, "_row_point", None)
            step = self._row_edge_step(point) if point is not None else 0
            if not step:
                return
            first, last = self.tree.yview()
            if (step > 0 and last >= 1.0) or (step < 0 and first <= 0.0):
                return                  # the end of the sheet is on the screen
            self._yview("scroll", step, "units")
            try:
                self.tree.update_idletasks()
            except tk.TclError:
                return
            self._aim_row_drag(point)
        elif getattr(self, "_letter_selecting", False):
            point = getattr(self, "_letter_point", None)
            step = self._letter_edge_step(point) if point is not None else 0
            if not step:
                return
            first, last = self.tree.xview()
            if (step > 0 and last >= 1.0) or (step < 0 and first <= 0.0):
                return
            self.tree.xview_scroll(step * AUTO_SCROLL_PIXELS, "units")
            try:
                self.tree.update_idletasks()
            except tk.TclError:
                return
            self._aim_letter_drag(point)
        else:
            return
        self._start_edge_scroll()

    # -- scrolling keeps the outline in place ------------------------------
    def _yview(self, *args):
        self.tree.yview(*args)
        if hasattr(self, "row_tree"):
            self.row_tree.yview(*args)
        self.after(1, self._refresh_outline)

    def _xview(self, *args):
        self.tree.xview(*args)
        self.after(1, self._layout_changed)

    def _y_scrolled(self, first, last):
        self._v_scroll.set(first, last)
        if hasattr(self, "row_tree"):
            self.row_tree.yview_moveto(first)
        self.after(1, self._refresh_outline)

    def _x_scrolled(self, first, last):
        self._h_scroll.set(first, last)
        self.after(1, self._layout_changed)

    # -- appearance --------------------------------------------------------
    def apply_config(self):
        size = max(6, int(self.config_obj.get("table", "font_size")))
        row_height = int(size * 2.2)
        self.style.configure("APlot.Treeview", font=("TkDefaultFont", size),
                             rowheight=row_height)
        self.style.configure("APlot.Treeview.Heading", font=("TkDefaultFont", size))
        # the row numbers take the very background of the table itself: the
        # themes of the systems differ (the one of macOS is a dark grey), and
        # a hard coded light grey strip beside a dark table looks broken
        paper = self.table_background()
        ink = self.dim_foreground(paper)
        self.style.configure("APlot.RowHeader.Treeview", font=("TkDefaultFont", size),
                             rowheight=row_height, background=paper,
                             fieldbackground=paper, foreground=ink)
        self.style.configure("APlot.RowHeader.Treeview.Heading",
                             font=("TkDefaultFont", size, "bold"))
        self.style.map("APlot.RowHeader.Treeview",
                       background=[("selected", paper)],
                       foreground=[("selected", ink)])
        try:
            self.corner_box.configure(background=paper)
        except (tk.TclError, AttributeError):
            pass
        # the little x_B / x_T / y_L / y_R switches above the columns keep
        # their own, readable size whatever the table font is
        self.style.configure("APlot.Axis.TCheckbutton",
                             font=("TkDefaultFont", AXIS_CHECK_FONT), padding=0)
        for column in self.tree["columns"]:
            self.tree.column(column, width=self.column_width(column),
                             minwidth=MIN_COLUMN_WIDTH,
                             stretch=str(column) not in self.column_widths)
        self.after(1, self._place_checks)

    def table_background(self):
        """The colour the table itself is painted with, whatever the theme."""
        for style_name, option in (("APlot.Treeview", "fieldbackground"),
                                   ("APlot.Treeview", "background"),
                                   ("Treeview", "fieldbackground"),
                                   ("Treeview", "background")):
            try:
                found = self.style.lookup(style_name, option)
            except tk.TclError:
                found = None
            if found:
                text = str(found).strip()
                if text and text.lower() not in ("none", "systemtransparent"):
                    return text
        try:      # the last resort: ask Tk what an empty table looks like
            return str(self.tree.cget("background"))
        except tk.TclError:
            return "#ffffff"

    @staticmethod
    def dim_foreground(_background=None):
        """The colour of the row numbers: the one of the column letters."""
        return HEADER_COLOR

    def column_width(self, name=None):
        """The width of one column: never narrower than its check buttons.

        A column the user has made wider or narrower keeps that width
        (`column_widths`); every other one has the width of the settings.
        """
        wanted = int(self.config_obj.get("table", "column_width"))
        if name is not None and str(name) in self.column_widths:
            wanted = int(self.column_widths[str(name)])
        return max(MIN_COLUMN_WIDTH, wanted)

    def _column_of(self, column_id):
        """The name of the column `#3` stands for, or None."""
        try:
            index = int(str(column_id).lstrip("#")) - 1
        except (TypeError, ValueError):
            return None
        columns = list(self.df.columns)
        return str(columns[index]) if 0 <= index < len(columns) else None

    def keep_column_width(self, name, width=None):
        """Hold one column at the width it was dragged to (or `width`).

        Such a column stops stretching with the window - otherwise Tk would
        share the room out again at the next redrawing and pull the edge
        back to where it was.  The other columns still fill the window;
        when the columns are wider than it, the table scrolls sideways.
        """
        name = str(name)
        if name not in [str(one) for one in self.df.columns]:
            return None
        try:
            if width is None:
                width = int(self.tree.column(name, "width"))
            width = max(MIN_COLUMN_WIDTH, int(width))
            self.tree.column(name, width=width, stretch=False)
        except (tk.TclError, TypeError, ValueError):
            return None
        self.column_widths[name] = width
        self.after(1, self._place_checks)
        self.after(1, self._refresh_outline)
        return width

    def forget_column_width(self, name):
        """Let one column follow the settings and the window again."""
        if self.column_widths.pop(str(name), None) is None:
            return False
        try:
            self.tree.column(str(name), width=self.column_width(),
                             stretch=True)
        except tk.TclError:
            return False
        self.after(1, self._place_checks)
        return True

    # -- data --------------------------------------------------------------
    def set_dataframe(self, df, check_all=False, blank=False,
                      keep_formulas=False):
        """Show a data frame; `check_all` ticks every column again.

        `blank` marks the empty sheet the program starts with: only that one
        grows more columns by itself when the window is made wider.  Data
        that was loaded or typed is never touched.

        A new table also starts with **no stored formulas**: they belong to
        the cells of the table that is being replaced, and left behind they
        would overwrite the values that have just arrived.  The operations
        that only reshape the same table (inserting a row, deleting a
        column, sorting) pass `keep_formulas=True` and move them themselves.
        """
        self.df = df.reset_index(drop=True)
        self.df.columns = self._unique_columns(self.df.columns)
        if not keep_formulas:
            self.cell_formulas = {}
        self.auto_columns = bool(blank)
        self.refresh(check_all=check_all)
        if self.auto_columns:
            self.after_idle(self.grow_columns_to_fit)

    # -- a blank sheet fills the window with columns ------------------------
    def blank_sheet(self):
        """True while nothing has been typed into the table."""
        if not getattr(self, "auto_columns", False):
            return False
        if self.df.empty or not len(self.df.columns):
            return True
        for row in self.df.itertuples(index=False, name=None):
            for value in row:
                if value is None:
                    continue
                if isinstance(value, float) and pd.isna(value):
                    continue
                if str(value).strip():
                    return False
        return True

    def columns_that_fit(self):
        """How many columns of the normal width the table can show."""
        try:
            width = int(self.tree.winfo_width())
        except tk.TclError:
            return 0
        if width <= 1:
            return 0
        return max(1, width // max(1, self.column_width()))

    def next_column_name(self):
        """`Y1`, `Y2`, ... - the next name that is still free."""
        taken = {str(one) for one in self.df.columns}
        index = len(taken)
        while True:
            name = f"Y{index}"
            if name not in taken:
                return name
            index += 1

    def grow_columns_to_fit(self):
        """Give the blank starting sheet as many columns as the window shows.

        Widening the window brings more columns; narrowing it keeps the ones
        that are there, so nothing a user may have typed can be lost.
        """
        if not self.blank_sheet():
            return 0
        wanted = min(self.columns_that_fit(), MAX_AUTO_COLUMNS)
        have = len(self.df.columns)
        if wanted <= have:
            return 0
        for _ in range(wanted - have):
            self.df[self.next_column_name()] = ["" for _ in range(len(self.df))]
        # check_all=False keeps the ticks the user set on the sheet so far;
        # the new columns get the first axis, as any new column does
        self.refresh(check_all=False)
        return wanted - have

    @staticmethod
    def _unique_columns(columns):
        seen, result = {}, []
        for col in columns:
            name = str(col)
            if name in seen:
                seen[name] += 1
                name = f"{name}.{seen[name]}"
            else:
                seen[name] = 0
            result.append(name)
        return result

    def refresh(self, check_all=False):
        self._cancel_edit()
        self._cancel_heading_edit()
        self.tree.delete(*self.tree.get_children())
        if hasattr(self, "row_tree"):
            self.row_tree.delete(*self.row_tree.get_children())
        columns = list(self.df.columns)
        self.tree["columns"] = columns
        # a column that is gone takes its width with it
        for name in [one for one in self.column_widths
                     if one not in [str(col) for col in columns]]:
            del self.column_widths[name]
        for idx, col in enumerate(columns):
            c_letter = col_to_letter(idx)
            self.tree.heading(col, text=f"{c_letter}  ({col})")
            # minwidth keeps the two check buttons - and the numbers under
            # them - readable however narrow the window is made; the
            # horizontal scroll bar takes over from there.  A column the
            # user has sized keeps its width and does not stretch.
            sized = str(col) in self.column_widths
            self.tree.column(col, width=self.column_width(col),
                             minwidth=MIN_COLUMN_WIDTH,
                             anchor="center", stretch=not sized)
        self.update_idletasks()
        for index, row in enumerate(self.df.itertuples(index=False, name=None)):
            self.tree.insert("", "end", iid=str(index),
                             values=["" if pd.isna(v) else str(v) for v in row])
            if hasattr(self, "row_tree"):
                self.row_tree.insert("", "end", iid=str(index),
                                     values=[str(index + 1)])
        self._build_checks(check_all=check_all)
        self._refresh_block()
        self._changed()

    def _changed(self):
        if self.on_change:
            self.on_change()

    def selected_row(self):
        """The first row of the highlighted block."""
        rows = self.selected_rows()
        return rows[0] if rows else None

    def add_row(self, focus=False, column=0):
        """Append one empty row (cheap: no full rebuild) and return its index."""
        if self.df.empty and not len(self.df.columns):
            return None
        index = len(self.df)
        self.df.loc[index] = ["" for _ in self.df.columns]
        self.tree.insert("", "end", iid=str(index),
                         values=["" for _ in self.df.columns])
        if hasattr(self, "row_tree"):
            self.row_tree.insert("", "end", iid=str(index),
                                 values=[str(index + 1)])
        self._changed()
        if focus:
            self.tree.see(str(index))
            if hasattr(self, "row_tree"):
                self.row_tree.see(str(index))
            column = max(0, min(int(column), len(self.df.columns) - 1))
            self.select_cell(index, column)
            self.after(1, lambda: self._begin_edit(str(index), column))
        return index

    # -- rows and columns around the selected cell --------------------------
    def shift_row_formulas(self, at, delta=1):
        """Make room: the formulas of the rows from `at` on move by `delta`."""
        self.cell_formulas = {((row + delta) if row >= at else row, col): formula
                              for (row, col), formula
                              in self.cell_formulas.items()}

    def shift_column_formulas(self, at, delta=1):
        """The same for the columns from `at` on."""
        self.cell_formulas = {(row, (col + delta) if col >= at else col): formula
                              for (row, col), formula
                              in self.cell_formulas.items()}

    def remap_row_formulas(self, old_rows):
        """`old_rows[i]` is the row that becomes row `i`."""
        place = {old: new for new, old in enumerate(old_rows)}
        self.cell_formulas = {(place[row], col): formula
                              for (row, col), formula
                              in self.cell_formulas.items() if row in place}

    def renumber_formulas(self, rows=None, columns=None):
        """Rewrite the *text* of every formula after a move of the table.

        Moving a formula to another cell is not enough: what it points at
        has moved too.  Inserting a row above row 14 turns `=log(A14)` into
        `=log(A15)` in every formula of the sheet - the one that moved down
        with it and the ones that only refer to that row - so that every
        formula goes on saying what it said before.

        `rows` is `(1-based row, how many)` and `columns` `(0-based
        column, how many)`; a negative count is a deletion, and a
        reference to something that is gone becomes `#REF!`.
        """
        if not self.cell_formulas:
            return False
        moved = {}
        for key, formula in self.cell_formulas.items():
            text = str(formula)
            if rows is not None and rows[1]:
                text = renumber_formula_rows(text, rows[0], rows[1])
            if columns is not None and columns[1]:
                text = renumber_formula_columns(text, columns[0], columns[1])
            moved[key] = text
        self.cell_formulas = moved
        return True

    def insert_row(self, at=None, focus=True):
        """Put one empty row at `at`; `None` appends it at the end.

        The row numbers below it move down, and so do the formulas that
        were stored in those cells.
        """
        if not len(self.df.columns):
            return None
        column = self.cursor[1] if self.cursor else 0
        total = len(self.df)
        if at is None or at >= total:
            return self.add_row(focus=focus, column=column)
        at = max(0, int(at))
        blank = pd.DataFrame([["" for _ in self.df.columns]],
                             columns=self.df.columns)
        frame = pd.concat([self.df.iloc[:at], blank, self.df.iloc[at:]],
                          ignore_index=True)
        self.shift_row_formulas(at, 1)          # the cells they sit in
        self.renumber_formulas(rows=(at + 1, 1))   # ... and what they read
        growing = getattr(self, "auto_columns", False)
        self.block = None
        self.set_dataframe(frame, check_all=False, keep_formulas=True)
        self.auto_columns = growing
        self.recalculate_all()
        column = max(0, min(column, len(self.df.columns) - 1))
        self.select_cell(at, column)
        if focus:
            self.tree.see(str(at))
            self.after(1, lambda: self._begin_edit(str(at), column))
        return at

    def insert_column(self, name, at=None):
        """Put a new empty column at `at`; `None` appends it at the right."""
        name = str(name).strip()
        if not name or name in [str(one) for one in self.df.columns]:
            return False
        if at is None or at > len(self.df.columns):
            at = len(self.df.columns)
        at = max(0, int(at))
        self.df.insert(at, name, ["" for _ in range(len(self.df))])
        self.shift_column_formulas(at, 1)
        self.renumber_formulas(columns=(at, 1))
        growing = getattr(self, "auto_columns", False)
        self.refresh()
        self.auto_columns = growing
        self.recalculate_all()      # the formulas point one column further
        self.current_column = name
        self.select_cell(self.cursor[0] if self.cursor else 0, at)
        self._changed()
        return True

    def remove_column(self, name):
        """Delete one column with its data, and its stored formulas."""
        columns = [str(one) for one in self.df.columns]
        name = str(name)
        if name not in columns or len(columns) <= 1:
            return False
        at = columns.index(name)
        # the formulas of that column go with it, the ones on its right
        # move one column to the left
        self.cell_formulas = {(row, col - 1 if col > at else col): formula
                              for (row, col), formula
                              in self.cell_formulas.items() if col != at}
        self.renumber_formulas(columns=(at, -1))
        growing = getattr(self, "auto_columns", False)
        self.current_column = None
        self.block = None
        self.set_dataframe(self.df.drop(columns=[name]), check_all=False,
                           keep_formulas=True)
        self.auto_columns = growing
        self.recalculate_all()
        self.select_cell(self.cursor[0] if self.cursor else 0,
                         max(0, min(at, len(self.df.columns) - 1)))
        return True

    def delete_row(self, index=None):
        """Delete one row, or every row of the block when none is given."""
        if index is None:
            return self.delete_selected_rows()
        self.block = None
        index = int(index)
        self.remap_row_formulas([one for one in range(len(self.df))
                                 if one != index])
        self.renumber_formulas(rows=(index + 1, -1))
        self.set_dataframe(self.df.drop(index=index), keep_formulas=True)
        self.recalculate_all()
        return True

    def add_column(self, name):
        if name in self.df.columns:
            return False
        self.df[name] = ["" for _ in range(len(self.df))]
        self.refresh()
        return True

    def rename_column(self, old, new):
        """Rename one column; returns False if the name is taken or invalid."""
        new = str(new).strip()
        if not new or new == old:
            return False
        if new in self.df.columns:
            return False
        index = list(self.df.columns).index(old)
        if str(old) in self.column_widths:     # the width goes with the name
            self.column_widths[str(new)] = self.column_widths.pop(str(old))
        self.df = self.df.rename(columns={old: new})
        self.refresh()
        self.current_column = new
        if self.on_rename:
            self.on_rename(old, new, index)
        return True

    # -- editing -----------------------------------------------------------
    def _cell_at(self, x, y):
        """(row, column) of the cell under the pointer, or None."""
        row_id = self.tree.identify_row(y)
        column_id = self.tree.identify_column(x)
        if not row_id or not column_id or not self.tree.exists(row_id):
            return None
        col = int(column_id[1:]) - 1
        if not (0 <= col < len(self.df.columns)):
            return None
        return (int(row_id), col)

    def _on_click(self, event):
        self.tree.focus_set()
        region = self.tree.identify_region(event.x, event.y)
        column_id = self.tree.identify_column(event.x)
        if region == "separator" and column_id:
            # the edge of a heading: Tk itself drags it; the new width is
            # taken over when the button is let go
            self._resizing = self._column_of(column_id)
            return None
        if region == "heading" and column_id:
            self.after(1, lambda: self._begin_heading_edit(column_id))
            return
        if region != "cell":
            return
        cell = self._cell_at(event.x, event.y)
        if cell is None:
            return
        row, col = cell
        self.select_cell(row, col)
        self._selecting = True          # a drag from here selects
        self._press = (event.x, cell)
        self._text_dragging = False
        # the editor is opened at once, so that dragging inside the cell can
        # select its text right away
        self._begin_edit(str(row), col)

    def _on_shift_click(self, event):
        """Shift+click: stretch the block from the anchor to this cell."""
        self.tree.focus_set()
        region = self.tree.identify_region(event.x, event.y)
        column_id = self.tree.identify_column(event.x)
        if region == "heading" and column_id:      # a whole column
            col = int(column_id[1:]) - 1
            if 0 <= col < len(self.df.columns) and len(self.df):
                self._commit_edit()
                self.select_block(0, col, len(self.df) - 1, col,
                                  anchor=(0, col), cursor=(len(self.df) - 1, col))
            return "break"
        cell = self._cell_at(event.x, event.y)
        if cell is None:
            return "break"
        self._commit_edit()
        self.extend_block_to(*cell)
        self._selecting = True
        return "break"

    def _header_height(self):
        """Where the rows start: the heading is above that."""
        children = self.tree.get_children()
        if children:
            bbox = self.tree.bbox(children[0], "#1")
            if bbox:
                return int(bbox[1])
        return 20

    def _pointer_inside(self, x, y):
        return (0 <= x <= self.tree.winfo_width()
                and self._header_height() <= y <= self.tree.winfo_height())

    def _on_drag(self, event):
        """Dragging selects the text of the cell, or a block of cells.

        Tk keeps sending the motion events to the table (that is where the
        button went down), so both the text selection of the cell editor and
        the automatic scrolling have to be driven from here.
        """
        if not self._selecting:
            return None
        self._drag_point = (event.x, event.y)
        inside = self._pointer_inside(event.x, event.y)
        cell = self._cell_at(event.x, event.y)
        editor = self._editor
        press_cell = self._press[1] if self._press else None
        text_drag = (editor is not None and press_cell is not None
                     and (int(editor[2]), editor[3]) == press_cell
                     and (cell == press_cell
                          or (cell is None and inside and self._text_dragging)))
        if text_drag:
            self._drag_text(editor[0], event.x)
            return "break"
        if not inside:                  # past the edge: scroll and follow
            self._start_auto_scroll()
            return "break"
        self._stop_auto_scroll()
        if cell is None:
            return None
        if cell != self.cursor or self._editor is not None:
            self._commit_edit()         # leaving the cell: select a block
            self.extend_block_to(*cell)
            self.tree.focus_set()
        if self._near_edge(event.x, event.y):
            self._start_auto_scroll()
        return "break"

    # -- scrolling on while the pointer is dragged past the edge ------------
    def _near_edge(self, x, y):
        """(dx, dy) of the scrolling the pointer asks for, or None."""
        height, width = self.tree.winfo_height(), self.tree.winfo_width()
        header = self._header_height()
        step_y = 0
        if y > height - AUTO_SCROLL_EDGE:
            step_y = 1
        elif y < header + AUTO_SCROLL_EDGE:
            step_y = -1
        step_x = 0
        if x > width - AUTO_SCROLL_EDGE:
            step_x = 1
        elif x < AUTO_SCROLL_EDGE:
            step_x = -1
        return (step_x, step_y) if (step_x or step_y) else None

    def _start_auto_scroll(self):
        if self._auto_scroll is None:
            self._auto_scroll = self.after(1, self._auto_scroll_step)

    def _stop_auto_scroll(self):
        if self._auto_scroll is not None:
            try:
                self.after_cancel(self._auto_scroll)
            except (tk.TclError, ValueError):
                pass
            self._auto_scroll = None

    def _auto_scroll_step(self):
        """Scroll one row (or column) and take the block with it."""
        self._auto_scroll = None
        if not self._selecting or self._drag_point is None:
            return
        x, y = self._drag_point
        step = self._near_edge(x, y)
        if step is None:
            return
        step_x, step_y = step
        first, last = self.tree.yview()
        if step_y > 0 and last < 1.0:
            self.tree.yview_scroll(1, "units")
        elif step_y < 0 and first > 0.0:
            self.tree.yview_scroll(-1, "units")
        if step_x:
            self.tree.xview_scroll(step_x * AUTO_SCROLL_PIXELS, "units")
        self.tree.update_idletasks()
        # the cell now under the pointer, pulled back into the visible area
        header = self._header_height()
        inside_y = min(max(y, header + 2), max(header + 2,
                                               self.tree.winfo_height() - 2))
        inside_x = min(max(x, 2), max(2, self.tree.winfo_width() - 2))
        cell = self._cell_at(inside_x, inside_y)
        if cell is not None:
            self._commit_edit()
            self.extend_block_to(*cell)
            self.tree.focus_set()
        self._refresh_outline()
        self._auto_scroll = self.after(AUTO_SCROLL_MS, self._auto_scroll_step)

    def _drag_text(self, entry, x):
        """Highlight the text of the edited cell with the pointer."""
        try:
            inside = x - entry.winfo_x()
            index = entry.index(f"@{max(0, int(inside))}")
            if not self._text_dragging:
                start = entry.index(f"@{max(0, int(self._press[0] - entry.winfo_x()))}")
                entry.selection_clear()
                entry.selection_from(start)
                entry.icursor(start)
                self._text_dragging = True
            entry.selection_to(index)
            entry.icursor(index)
            entry.focus_set()
        except (tk.TclError, AttributeError):
            pass

    def _on_drag_end(self, _event=None):
        if self._resizing is not None:
            name, self._resizing = self._resizing, None
            self.after_idle(lambda n=name: self.keep_column_width(n))
        self._stop_auto_scroll()
        self._selecting = False
        self._press = None
        self._text_dragging = False
        self._drag_point = None
        return None

    # -- column names ------------------------------------------------------
    def _heading_geometry(self, column_id):
        """Position of a column heading: (x, y, width, height)."""
        children = self.tree.get_children()
        if not children:
            return None
        bbox = self.tree.bbox(children[0], column_id)
        if not bbox:
            return None
        x, y, width, _height = bbox
        return x, 0, width, max(16, y)

    def _begin_heading_edit(self, column_id):
        self._commit_edit()
        self._cancel_heading_edit()
        col_index = int(column_id[1:]) - 1
        if not (0 <= col_index < len(self.df.columns)):
            return
        old = self.df.columns[col_index]
        self.current_column = old

        geometry = self._heading_geometry(column_id)
        if geometry is None:  # empty table: fall back to a small dialog
            new = simpledialog.askstring("Column name", "New column name:",
                                         initialvalue=old, parent=self)
            if new and not self.rename_column(old, new):
                messagebox.showerror("Error", f"'{new}' cannot be used.", parent=self)
            return

        x, y, width, height = geometry
        var = tk.StringVar(value=old)
        entry = tk.Entry(self.tree, textvariable=var, exportselection=False,
                         justify="center", borderwidth=1, relief="solid")
        entry.place(x=x, y=y, width=width, height=height)
        entry.focus_set()
        entry.select_range(0, "end")
        self._heading_editor = (entry, var, old)

        entry.bind("<Return>", lambda _e: self._commit_heading_edit())
        entry.bind("<KP_Enter>", lambda _e: self._commit_heading_edit())
        entry.bind("<Escape>", lambda _e: self._cancel_heading_edit())
        entry.bind("<FocusOut>", lambda _e: self._commit_heading_edit())
        self._bind_text_editing(entry)

    def _cancel_heading_edit(self):
        if self._heading_editor:
            entry, *_ = self._heading_editor
            self._heading_editor = None
            entry.destroy()
        return "break"

    def _commit_heading_edit(self):
        if not self._heading_editor:
            return "break"
        entry, var, old = self._heading_editor
        self._heading_editor = None
        new = var.get().strip()
        entry.destroy()
        if new and new != old and not self.rename_column(old, new):
            messagebox.showerror(
                "Error", f"'{new}' cannot be used as a column name "
                         "(it is empty or already exists).", parent=self)
        return "break"

    # -- selection / clipboard --------------------------------------------
    def _bind_text_editing(self, entry, cell=False):
        """Selection and copy bindings shared by the cell and heading editors."""
        for sequence in ("<Control-a>", "<Control-A>", "<Command-a>", "<Command-A>"):
            entry.bind(sequence, self._select_all)
        for sequence in ("<Control-c>", "<Control-C>", "<Command-c>", "<Command-C>"):
            entry.bind(sequence, self._copy_text)
        if not cell:                     # the heading editor holds text only
            entry.bind("<Shift-Up>", lambda e: self._extend_selection(e, "start"))
            entry.bind("<Shift-Down>", lambda e: self._extend_selection(e, "end"))
            return
        # in a cell, Shift+Up / Shift+Down grow the highlighted block
        entry.bind("<Shift-Up>", lambda _e: self._block_from_editor(-1, 0))
        entry.bind("<Shift-Down>", lambda _e: self._block_from_editor(1, 0))
        # Shift+Left / Shift+Right select the text of the cell, and grow the
        # block once the cursor has reached the end of it
        entry.bind("<Shift-Left>", lambda e: self._shift_arrow(e, -1))
        entry.bind("<Shift-Right>", lambda e: self._shift_arrow(e, 1))

    @staticmethod
    def _select_all(event):
        event.widget.select_range(0, "end")
        event.widget.icursor("end")
        return "break"

    @staticmethod
    def _copy_text(event):
        widget = event.widget
        if widget.selection_present():
            text = widget.get()[widget.index("sel.first"):widget.index("sel.last")]
        else:
            text = widget.get()
        widget.clipboard_clear()
        widget.clipboard_append(text)
        return "break"

    def _block_from_editor(self, d_row, d_col):
        """Leave the cell editor and grow the block of cells instead."""
        editor = self._editor
        if editor is not None:
            row_id, col_index = editor[2], editor[3]
            self._commit_edit()
            self.cursor = (int(row_id), col_index)
            if self.block is None:
                self.select_cell(int(row_id), col_index)
        self.tree.focus_set()
        self.extend_block(d_row, d_col)
        return "break"

    def _shift_arrow(self, event, d_col):
        """Shift+Left/Right: select text, then grow the block sideways."""
        widget = event.widget
        cursor = widget.index("insert")
        at_edge = (cursor == 0) if d_col < 0 else (cursor == len(widget.get()))
        if not at_edge:
            target = max(0, min(len(widget.get()), cursor + d_col))
            if not widget.selection_present():
                widget.selection_from(cursor)
            widget.selection_to(target)
            widget.icursor(target)
            return "break"
        return self._block_from_editor(0, d_col)

    @staticmethod
    def _extend_selection(event, where):
        """Shift+Up / Shift+Down inside a heading editor: whole text."""
        widget = event.widget
        target = 0 if where == "start" else len(widget.get())
        if not widget.selection_present():
            widget.selection_from(widget.index("insert"))  # set the anchor
        widget.selection_to(target)
        widget.icursor(target)
        return "break"

    def block_text(self):
        """The block as tab separated text, one line per row."""
        bounds = self.block_bounds()
        if bounds is None:
            return ""
        r0, c0, r1, c1 = bounds
        lines = []
        for row in range(r0, r1 + 1):
            values = []
            for col in range(c0, c1 + 1):
                value = self.df.iat[row, col]
                values.append("" if pd.isna(value) else str(value))
            lines.append("\t".join(values))
        return "\n".join(lines)

    def copy_block(self, _event=None):
        """Ctrl/Cmd+C: the whole highlighted block, rows and columns."""
        text = self.block_text()
        if not text:
            return False
        self.clipboard_clear()
        self.clipboard_append(text)
        return True

    def forget_formulas(self, cells):
        """A cell that was emptied or written over is not calculated any more.

        The formula of such a cell has to go with its value.  Left behind,
        it would put the old value back at the very next recalculation -
        the column would look empty and come back from the dead as soon as
        anything else in the sheet was touched.
        """
        gone = [key for key in self.cell_formulas if key in set(cells)]
        for key in gone:
            del self.cell_formulas[key]
        return len(gone)

    def clear_block(self, _event=None):
        """Delete: empty every cell of the block.

        The curves break at the emptied cells instead of jumping over them.
        """
        bounds = self.block_bounds()
        if bounds is None:
            return False
        r0, c0, r1, c1 = bounds
        for col in range(c0, c1 + 1):
            column = self.df.columns[col]
            if self.df[column].dtype != object:
                self.df[column] = self.df[column].astype(object)
            for row in range(r0, r1 + 1):
                self.df.iat[row, col] = ""
                if self.tree.exists(str(row)):
                    self.tree.set(str(row), column, "")
        # the formulas of those cells are gone with their values, and what
        # the rest of the sheet reads from them is worked out again
        self.forget_formulas([(row, col) for row in range(r0, r1 + 1)
                              for col in range(c0, c1 + 1)])
        self.recalculate_all()
        self._changed()
        self._update_formula_bar()
        self._update_status_bar()
        return True

    def cut_block(self, _event=None):
        """Ctrl/Cmd+X: copy the block and empty it."""
        if not self.copy_block():
            return False
        return self.clear_block()

    def duplicate_block(self, _event=None):
        """Ctrl/Cmd+D: the block again, in the rows just under it.

        The clipboard of the system is left alone: what was copied before
        is still there afterwards.
        """
        bounds = self.block_bounds()
        text = self.block_text()
        if bounds is None or not text:
            return False
        r0, c0, r1, _c1 = bounds
        rows = r1 - r0 + 1
        while len(self.df) < r1 + rows + 1:      # room for the second copy
            self.add_row()
        self.select_cell(r1 + 1, c0)
        self.paste_block(text)
        return True

    def paste_block(self, text=None, _event=None):
        """Ctrl/Cmd+V: write tab separated text starting at the block.

        The shape of the text decides the shape of what is written: two
        columns of numbers fill two columns of cells, starting at the top
        left cell of the highlighted block.
        """
        if text is None:
            text = self._clipboard_text()
            if not text:
                return False
        rows = [line.split("\t")
                for line in str(text).replace("\r\n", "\n").replace("\r", "\n").split("\n")]
        while rows and not any(cell.strip() for cell in rows[-1]):
            rows.pop()
        bounds = self.block_bounds()
        if bounds is None or not rows:
            return False
        r0, c0 = bounds[0], bounds[1]
        needed = r0 + len(rows)
        if needed > len(self.df):
            if self.config_obj.get("table", "auto_extend"):
                while len(self.df) < needed:
                    self.add_row()
            else:
                rows = rows[:len(self.df) - r0]
        columns = len(self.df.columns)
        written = []
        for offset, line in enumerate(rows):
            row = r0 + offset
            if row >= len(self.df):
                break
            for shift, cell in enumerate(line):
                col = c0 + shift
                if col >= columns:
                    break
                column = self.df.columns[col]
                value = coerce(cell.strip())
                try:
                    self.df.iat[row, col] = value
                except (ValueError, TypeError):
                    self.df[column] = self.df[column].astype(object)
                    self.df.iat[row, col] = value
                if self.tree.exists(str(row)):
                    self.tree.set(str(row), column,
                                  "" if value == "" else str(value))
                written.append((row, col))
        # a pasted value replaces a formula that stood in that cell
        self.forget_formulas(written)
        self.recalculate_all()
        last_row = min(len(self.df) - 1, r0 + len(rows) - 1)
        last_col = min(columns - 1, c0 + max(len(line) for line in rows) - 1)
        self.select_block(r0, c0, last_row, last_col)
        self._changed()
        return True

    def delete_selected_rows(self):
        """Remove every row the block touches."""
        rows = self.selected_rows()
        if not rows:
            return False
        keep = [index for index in range(len(self.df)) if index not in set(rows)]
        self.block = None
        self.remap_row_formulas(keep)      # the formulas follow their rows
        # ... and what they read moves up with the rows below them
        self.renumber_formulas(rows=(min(rows) + 1, -len(rows)))
        column = self.cursor[1] if self.cursor else 0
        self.set_dataframe(self.df.iloc[keep], keep_formulas=True)
        self.recalculate_all()
        first = min(rows)
        if len(self.df):
            self.select_cell(min(first, len(self.df) - 1),
                             max(0, min(column, len(self.df.columns) - 1)))
        return True

    def _begin_edit(self, row_id, col_index, retry=True):
        self._commit_edit()
        if not self.tree.exists(row_id) or not (0 <= col_index < len(self.df.columns)):
            return
        if self._selecting and self.block_cells()[0] > 1:
            return          # the pointer is drawing a block, not editing
        # opening a cell for editing makes that cell the whole selection
        self.select_cell(int(row_id), col_index)
        self.tree.see(row_id)
        self.update_idletasks()
        bbox = self.tree.bbox(row_id, f"#{col_index + 1}")
        if not bbox:
            if retry:  # the row was scrolled into view only now
                self.after(20, lambda: self._begin_edit(row_id, col_index, False))
            return

        x, y, width, height = bbox
        column = self.df.columns[col_index]
        self.current_column = column
        cell_formula = self.cell_formulas.get((int(row_id), col_index))
        init_val = cell_formula if cell_formula is not None else self.tree.set(row_id, column)
        var = tk.StringVar(value=init_val)
        # exportselection=False keeps the highlighted text visible even when
        # another widget (e.g. the Treeview) takes over the X selection.
        entry = tk.Entry(self.tree, textvariable=var, exportselection=False,
                         borderwidth=1, relief="solid", justify="center",
                         insertbackground=CARET_COLOR, insertwidth=2,
                         insertontime=CARET_ON_MS, insertofftime=CARET_OFF_MS)
        entry.place(x=x, y=y, width=width, height=height)
        entry.focus_set()
        entry.icursor("end")
        entry.select_range(0, "end")
        self._editor = (entry, var, row_id, col_index)
        # the editor must not bury the fill handle of the selection
        self._lift_overlays()
        # a diagram window that was just opened may still be holding the
        # keyboard: without it the cell shows no blinking cursor at all
        self._insist_editor_focus(entry)
        self.after(30, lambda box=entry: self._insist_editor_focus(box))

        for sequence, delta in (("<Return>", (1, 0)), ("<KP_Enter>", (1, 0)),
                                ("<Down>", (1, 0)), ("<Up>", (-1, 0)),
                                ("<Tab>", (0, 1)), ("<Shift-Tab>", (0, -1)),
                                ("<ISO_Left_Tab>", (0, -1))):
            entry.bind(sequence, lambda _e, d=delta: self._move(*d))
        # Left / Right walk inside the text and step to the neighbouring cell
        # when the cursor is already at the end of it
        entry.bind("<Left>", lambda e: self._arrow(e, 0, -1))
        entry.bind("<Right>", lambda e: self._arrow(e, 0, 1))
        for prefix in ("Control", "Command", "Alt"):
            for key, delta in (("Left", (0, -1)), ("Right", (0, 1)),
                               ("Up", (-1, 0)), ("Down", (1, 0))):
                entry.bind(f"<{prefix}-{key}>", lambda _e, d=delta: self._move(*d))
        entry.bind("<Escape>", lambda _e: self._leave_editor())
        entry.bind("<FocusOut>", lambda _e: self._commit_edit())
        # a block on the clipboard must fill a block of cells, not one cell
        for prefix in ("Control", "Command"):
            for letter in ("v", "V"):
                entry.bind(f"<{prefix}-{letter}>", self._paste_from_editor)
            for letter in ("x", "X"):
                entry.bind(f"<{prefix}-{letter}>", self._cut_from_editor)
        self._bind_text_editing(entry, cell=True)

    def _insist_editor_focus(self, entry):
        """Keep the keyboard - and the blinking cursor - inside the cell.

        A diagram window that has just been opened (or a property window
        that was used last) may still own the keyboard of the application.
        The cell editor then shows no cursor and swallows nothing that is
        typed, so it takes the keyboard back for itself.
        """
        if self._editor is None or self._editor[0] is not entry:
            return None
        try:
            if not entry.winfo_exists() or not entry.winfo_ismapped():
                return None
            if entry.focus_displayof() is not entry:
                entry.focus_force()
        except (tk.TclError, KeyError):
            pass
        return None

    # -- the clipboard while a cell is being edited -------------------------
    def _clipboard_text(self):
        try:
            return str(self.clipboard_get())
        except tk.TclError:
            return ""

    @staticmethod
    def is_block_text(text):
        """True when the clipboard holds more than one cell."""
        cleaned = str(text).replace("\r", "")
        while cleaned.endswith("\n"):
            cleaned = cleaned[:-1]
        return "\t" in cleaned or "\n" in cleaned

    def _paste_from_editor(self, _event=None):
        """Ctrl/Cmd+V in a cell: a block of cells fills a block of cells.

        A single value is left to the text editor, so it can be pasted into
        the middle of a cell; anything with tabs or line breaks is written
        into the table starting at the edited cell.
        """
        text = self._clipboard_text()
        if not self.is_block_text(text):
            return None                  # one value: the normal text paste
        editor = self._editor
        if editor is not None:
            row_id, col_index = editor[2], editor[3]
            self._commit_edit()
            self.select_cell(int(row_id), col_index)
        self.tree.focus_set()
        self.paste_block(text)
        return "break"

    def _cut_from_editor(self, event=None):
        """Ctrl/Cmd+X in a cell: the selected text, or the whole block."""
        entry = getattr(event, "widget", None)
        if entry is not None and entry.selection_present():
            return None                  # cutting text inside the cell
        editor = self._editor
        if editor is not None:
            row_id, col_index = editor[2], editor[3]
            self._commit_edit()
            self.select_cell(int(row_id), col_index)
        self.tree.focus_set()
        self.cut_block()
        return "break"

    def _leave_editor(self):
        """Escape: close the editor and work on the block with the keys."""
        editor = self._editor
        if editor is not None:
            self.cursor = (int(editor[2]), editor[3])
        self._cancel_edit()
        self.tree.focus_set()
        self._refresh_block()
        return "break"

    def _arrow(self, event, d_row, d_col):
        """Left/Right: move the text cursor, or jump to the neighbour cell."""
        entry = event.widget
        if entry.selection_present():
            return None                     # let the selection collapse first
        cursor = entry.index("insert")
        if d_col < 0 and cursor > 0:
            return None                     # still text to walk through
        if d_col > 0 and cursor < len(entry.get()):
            return None
        return self._move(d_row, d_col)

    def _move(self, d_row, d_col):
        if not self._editor:
            return "break"
        _entry, _var, row_id, col_index = self._editor
        columns = len(self.df.columns)
        self._commit_edit()

        row = int(row_id) + d_row
        col = col_index + d_col
        if col >= columns:
            col, row = 0, row + 1
        elif col < 0:
            col, row = columns - 1, row - 1

        if row >= len(self.df):
            if self.config_obj.get("table", "auto_extend"):
                while row >= len(self.df):  # grow the table as needed
                    self.add_row()
            else:
                row = len(self.df) - 1
        row = max(0, min(len(self.df) - 1, row))
        col = max(0, min(columns - 1, col))
        self.after(1, lambda: self._begin_edit(str(row), col))
        return "break"

    def _cancel_edit(self):
        if self._editor:
            entry, *_ = self._editor
            self._editor = None
            entry.destroy()
        return "break"

    def _commit_edit(self):
        if not self._editor:
            return
        entry, var, row_id, col_index = self._editor
        self._editor = None
        text = var.get()
        entry.destroy()

        row = int(row_id)
        if row >= len(self.df) or col_index >= len(self.df.columns):
            return
        column = self.df.columns[col_index]
        text_val = str(text).strip()
        if text_val.startswith("="):
            self.cell_formulas[(row, col_index)] = text_val
            value = self.eval_formula(text_val, row, col_index)
        else:
            self.cell_formulas.pop((row, col_index), None)
            value = coerce(text_val)

        try:
            self.df.iat[row, col_index] = value
        except (ValueError, TypeError):
            self.df[column] = self.df[column].astype(object)
            self.df.iat[row, col_index] = value

        self.recalculate_all()
        if self.tree.exists(row_id):
            self.tree.set(row_id, column, "" if value == "" else str(value))
        self._changed()
        self._update_formula_bar()
        self._update_status_bar()

    def eval_formula(self, formula_str, row, col):
        evaluator = FormulaEvaluator(self.df, self.cell_formulas,
                                     seed=self.random_seed)
        return evaluator.evaluate(formula_str, row, col)

    def new_random_numbers(self):
        """F9: every RAND() and RANDN() of this sheet draws a new number.

        Only the seed of the sheet changes, so the formulas themselves stay
        as they are; the change is one step that Undo takes back.
        """
        self.random_seed = new_random_seed()
        uses = any(RANDOM_IN_FORMULA.search(str(formula))
                   for formula in self.cell_formulas.values())
        if uses:
            self.recalculate_all()
            if self.on_change:
                self.on_change()
        return uses

    def recalculate_all(self):
        """Recalculate all formula cells across the table."""
        if not self.cell_formulas:
            return
        evaluator = FormulaEvaluator(self.df, self.cell_formulas,
                                     seed=self.random_seed)
        for (r, c), formula in list(self.cell_formulas.items()):
            if r < len(self.df) and c < len(self.df.columns):
                val = evaluator.evaluate(formula, r, c)
                col_name = self.df.columns[c]
                try:
                    self.df.iat[r, c] = val
                except (ValueError, TypeError):
                    self.df[col_name] = self.df[col_name].astype(object)
                    self.df.iat[r, c] = val
                if self.tree.exists(str(r)):
                    self.tree.set(str(r), col_name, "" if val == "" else str(val))

    def fill_down(self):
        """Excel-style Fill Down: repeat the top cell down the block.

        It has the button of the formula bar and the right-click menu;
        `Ctrl/Cmd+D` belongs to `Edit > Duplicate`.
        """
        bounds = self.block_bounds()
        if bounds is None:
            return False
        r0, c0, r1, c1 = bounds
        if r0 == r1:
            if r0 > 0:
                fill_r0 = r0 - 1
                fill_r1 = r0
            else:
                return False
        else:
            fill_r0 = r0
            fill_r1 = r1

        for c in range(c0, c1 + 1):
            top_formula = self.cell_formulas.get((fill_r0, c))
            top_val = self.df.iat[fill_r0, c]
            col_name = self.df.columns[c]
            for r in range(fill_r0 + 1, fill_r1 + 1):
                if top_formula is not None:
                    adjusted = adjust_formula_references(top_formula, delta_row=(r - fill_r0), delta_col=0)
                    self.cell_formulas[(r, c)] = adjusted
                else:
                    self.cell_formulas.pop((r, c), None)
                    try:
                        self.df.iat[r, c] = copy.deepcopy(top_val)
                    except (ValueError, TypeError):
                        self.df[col_name] = self.df[col_name].astype(object)
                        self.df.iat[r, c] = copy.deepcopy(top_val)

        self.recalculate_all()
        self._changed()
        self._update_formula_bar()
        self._update_status_bar()
        return True

    def select_cell_by_address(self, col_letter, row_1_based):
        col_idx = letter_to_col(col_letter)
        row_idx = row_1_based - 1
        if 0 <= row_idx < len(self.df) and 0 <= col_idx < len(self.df.columns):
            self.select_cell(row_idx, col_idx)
            self.tree.see(str(row_idx))

    def _update_formula_bar(self):
        if not hasattr(self, "formula_bar") or not len(self.df.columns) or not len(self.df):
            return
        r, c = self.cursor
        r = max(0, min(len(self.df) - 1, r))
        c = max(0, min(len(self.df.columns) - 1, c))
        c_letter = col_to_letter(c)
        c_name = str(self.df.columns[c])
        addr = f"{c_letter}{r + 1}"
        display_name = f"{addr} ({c_name})"

        if (r, c) in self.cell_formulas:
            formula_text = self.cell_formulas[(r, c)]
        else:
            val = self.df.iat[r, c]
            formula_text = "" if pd.isna(val) else str(val)
        self.formula_bar.set_cell(display_name, formula_text)

    def _update_status_bar(self):
        if not hasattr(self, "status_label"):
            return
        bounds = self.block_bounds()
        if bounds is None:
            self.status_label.configure(text="")
            return
        r0, c0, r1, c1 = bounds
        total_cells = (r1 - r0 + 1) * (c1 - c0 + 1)
        if total_cells <= 1:
            self.status_label.configure(text="")
            return

        nums = []
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                val = self.df.iat[r, c]
                if isinstance(val, (int, float)) and np.isfinite(val):
                    nums.append(float(val))
                else:
                    try:
                        n = float(str(val).strip().replace(",", "."))
                        if np.isfinite(n):
                            nums.append(n)
                    except (ValueError, TypeError):
                        pass

        if nums:
            count = len(nums)
            total = sum(nums)
            avg = total / count
            min_v = min(nums)
            max_v = max(nums)
            text = f"Selected: {total_cells} cells (Numeric: {count})  |  Sum: {total:.4g}  |  Average: {avg:.4g}  |  Min: {min_v:.4g}  |  Max: {max_v:.4g}"
        else:
            text = f"Selected: {total_cells} cells"
        self.status_label.configure(text=text)

    def _formula_bar_commit(self, text):
        r, c = self.cursor
        if not (0 <= r < len(self.df) and 0 <= c < len(self.df.columns)):
            return
        text_val = str(text).strip()
        column = self.df.columns[c]
        if text_val.startswith("="):
            self.cell_formulas[(r, c)] = text_val
            val = self.eval_formula(text_val, r, c)
        else:
            self.cell_formulas.pop((r, c), None)
            val = coerce(text_val)

        try:
            self.df.iat[r, c] = val
        except (ValueError, TypeError):
            self.df[column] = self.df[column].astype(object)
            self.df.iat[r, c] = val

        self.recalculate_all()
        if self.tree.exists(str(r)):
            self.tree.set(str(r), column, "" if val == "" else str(val))
        self._changed()
        self._update_formula_bar()
        self._update_status_bar()

    def _formula_bar_cancel(self):
        self._update_formula_bar()

    def open_column_math(self):
        ColumnMathDialog(self.winfo_toplevel(), self)

    def sort_column(self, col_idx, ascending=True):
        if not len(self.df) or not (0 <= col_idx < len(self.df.columns)):
            return
        col_name = self.df.columns[col_idx]
        try:
            num_series = pd.to_numeric(self.df[col_name], errors='coerce')
            if num_series.notna().sum() > len(self.df) * 0.5:
                sorted_df = self.df.iloc[num_series.argsort(kind='stable') if ascending else (-num_series).argsort(kind='stable')]
            else:
                sorted_df = self.df.sort_values(by=col_name, ascending=ascending, kind='stable')
        except Exception:
            sorted_df = self.df.sort_values(by=col_name, ascending=ascending, kind='stable')

        self.remap_row_formulas(list(sorted_df.index))
        self.set_dataframe(sorted_df.reset_index(drop=True),
                           check_all=False, keep_formulas=True)
        self.recalculate_all()
        self._changed()

    def _show_context_menu(self, event):
        region = self.tree.identify_region(event.x, event.y)
        column_id = self.tree.identify_column(event.x)
        if region == "heading" and column_id:
            col_idx = int(column_id[1:]) - 1
            if 0 <= col_idx < len(self.df.columns):
                self._show_header_context_menu(col_idx, event)
            return

        cell = self._cell_at(event.x, event.y)
        if cell is not None:
            bounds = self.block_bounds()
            if bounds is None or not (bounds[0] <= cell[0] <= bounds[2] and bounds[1] <= cell[1] <= bounds[3]):
                self.select_cell(*cell)

        menu = tk.Menu(self, tearoff=0)
        menu.add_command(label=f"Cut ({MODIFIER}+X)", command=self.cut_block)
        menu.add_command(label=f"Copy ({MODIFIER}+C)", command=self.copy_block)
        menu.add_command(label=f"Paste ({MODIFIER}+V)", command=self.paste_block)
        menu.add_separator()
        menu.add_command(label="Fill Down", command=self.fill_down)
        menu.add_command(label=f"Duplicate ({MODIFIER}+D)",
                         command=self.duplicate_block)
        menu.add_command(label="Column Math...", command=self.open_column_math)
        menu.add_separator()
        menu.add_command(label="Clear Cells (Delete)", command=self.clear_block)
        menu.add_separator()
        menu.add_command(label="Insert Row Above",
                         command=lambda: self.insert_row(self.cursor[0]))
        menu.add_command(label="Insert Row Below",
                         command=lambda: self.insert_row(self.cursor[0] + 1))
        menu.add_command(label="Delete Row(s)", command=self.delete_selected_rows)
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()

    def _ask_new_column(self, where, col_idx):
        """The program asks for the name and inserts the column."""
        if self.on_add_column:
            return self.on_add_column(where, col_idx)
        return self.insert_column(self.next_column_name(),
                                  col_idx if where == "before" else col_idx + 1)

    def _ask_delete_column(self, name):
        if self.on_delete_column:
            return self.on_delete_column(name)
        return self.remove_column(name)

    def _show_header_context_menu(self, col_idx, event):
        col_name = str(self.df.columns[col_idx])
        self.current_column = col_name

        menu = tk.Menu(self, tearoff=0)
        menu.add_command(label=f"Calculate Column '{col_name}'...", command=self.open_column_math)
        menu.add_separator()
        menu.add_command(label="Sort Ascending (A → Z)", command=lambda: self.sort_column(col_idx, ascending=True))
        menu.add_command(label="Sort Descending (Z → A)", command=lambda: self.sort_column(col_idx, ascending=False))
        menu.add_separator()
        menu.add_command(label="Fill Down", command=self.fill_down)
        menu.add_separator()
        menu.add_command(
            label="Insert Column Before...",
            command=lambda: self._ask_new_column("before", col_idx))
        menu.add_command(
            label="Insert Column After...",
            command=lambda: self._ask_new_column("after", col_idx))
        menu.add_command(label=f"Rename '{col_name}'...", command=lambda: self._begin_heading_edit(f"#{col_idx + 1}"))
        menu.add_command(label=f"Delete Column '{col_name}'",
                         command=lambda: self._ask_delete_column(col_name))
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            menu.grab_release()


# --------------------------------------------------------------------------
# interactive plot window
# --------------------------------------------------------------------------

def style_factor(was_width, was_height, width, height):
    """How much larger the graph has become, as one single number.

    The two axes may not have changed by the same amount (one of them can
    run into the edge of the page first), and a font has only one size, so
    the two are averaged the way an area is: the square root of their
    product.  Two axes both made ten per cent longer give exactly 1.1.
    """
    try:
        x_factor = float(width) / float(was_width)
        y_factor = float(height) / float(was_height)
    except (TypeError, ValueError, ZeroDivisionError):
        return 1.0
    if not (np.isfinite(x_factor) and np.isfinite(y_factor)):
        return 1.0
    if x_factor <= 0.0 or y_factor <= 0.0:
        return 1.0
    return float(np.sqrt(x_factor * y_factor))


def scale_style_document(document, factor):
    """Every size drawn on the paper, multiplied by `factor`.

    `Resize graph` does not only change the box the curves are drawn in:
    the whole diagram grows or shrinks with it, the way a picture does.
    A graph whose axes are twice as long therefore carries numbers twice
    as large, lines twice as thick and tick marks twice as long.

    Only the numbers that are a **length or a font size on the paper** are
    touched.  The data, the ranges, the colours, the number of ticks and
    the places of the objects are left exactly as they are - a place is a
    fraction of the plot area, so it follows the plot area by itself.

    Font sizes are whole points, so they are rounded to the nearest point
    and never fall below one; every other size keeps its exact value.
    """
    factor = float(factor)
    if not np.isfinite(factor) or factor <= 0.0 or abs(factor - 1.0) < 1e-12:
        return document

    def font(value):
        try:
            return max(1, int(round(float(value) * factor)))
        except (TypeError, ValueError):
            return value

    def length(value):
        try:
            return float(value) * factor
        except (TypeError, ValueError):
            return value

    def touch(holder, names, how):
        if not isinstance(holder, dict):
            return
        for name in names:
            if holder.get(name) is not None:
                holder[name] = how(holder[name])

    touch(document.get("title"), ("size",), font)
    touch(document.get("title"), ("pad",), length)
    touch(document.get("legend"), ("size",), font)
    touch(document.get("frame"),
          ("width", "major_tick_length", "minor_tick_length"), length)
    for axis in (document.get("axes") or {}).values():
        touch(axis, ("label_size", "tick_size"), font)
        touch(axis, ("label_pad", "tick_pad"), length)
        if isinstance(axis, dict):
            touch(axis.get("grid"), ("width",), length)
    offsets = document.get("text_offsets") or {}
    for name, value in list(offsets.items()):
        try:                      # how far a text was dragged (points)
            offsets[name] = [float(value[0]) * factor,
                             float(value[1]) * factor]
        except (TypeError, ValueError, IndexError):
            pass
    for curve in document.get("series") or ():
        if not isinstance(curve, dict):
            continue
        touch(curve, ("linewidth", "markersize", "markeredgewidth"), length)
        touch(curve, ("legend_size",), font)
        # the width of a bar is a fraction of the gap between two of them,
        # and the number of bins is a count: neither is a size on the paper
        touch(curve.get("bar_cfg"), ("edgewidth",), length)
        touch(curve.get("error_cfg"),
              ("capsize", "capthick", "elinewidth"), length)
        touch(curve.get("histogram_cfg"), ("edgewidth",), length)
        touch(curve.get("stairs_cfg"), ("width",), length)
        touch(curve.get("pie_cfg"), ("edgewidth",), length)
        touch(curve.get("pie_cfg"),
              ("label_size", "name_size", "pct_size"), font)
    for shape in document.get("shapes") or ():
        touch(shape, ("width",), length)      # the line around a drawing
    for arrow in document.get("arrows") or ():
        touch(arrow, ("width", "size"), length)
    for note in document.get("notes") or ():
        touch(note, ("size",), font)
    return document


class PlotWindow(tk.Toplevel):
    """Figure window: all plot related interaction lives here."""

    # the copied object, shared by every diagram window of the program
    _clipboard = None
    # when each of the two kinds of copy last happened, so that pasting
    # takes whichever was copied more recently
    _clipboard_stamp = 0.0
    _figure_stamp = 0.0
    # what the clipboard of the system looked like when this program last
    # copied something: anything else there now came from another program
    _clipboard_serial = None

    HINT = ("One click selects (a text turns blue), a slow second click "
            "writes the text, a double click opens its properties   |   "
            "A curve: two clicks   |   Drag: move   |   "
            "Drag a control point: resize   |   "
            "Drag the background: choose several\n"
            "\"T\", the shape and the arrow button: add text, drawings and "
            "arrows   |   Shift: arrows at 45 deg steps   |   "
            f"{ACCEL_NAME}+C: copy the object, or the whole figure   |   "
            f"{ACCEL_NAME}+V: paste   |   "
            f"{ACCEL_NAME}+S: save   |   {ACCEL_NAME}+E: export   |   "
            "Arrow keys: move   |   Delete: remove\n"
            f"The page keeps its size: wheel to scroll, {ACCEL_NAME}+wheel "
            f"(or the toolbar) to zoom, {ACCEL_NAME}+0 for its true size, "
            "middle button to slide it   |   "
            "Right click the paper: Resize graph")

    def __init__(self, master, df: pd.DataFrame, config: Config, app=None,
                 layout=None, plot_style="line_symbol"):
        super().__init__(master)
        self.title("Interactive Graph")
        self.settings = config
        self.app = app          # gives this window the full application menu
        plot_cfg = config.section("plot")
        grid_cfg = config.section("grid")
        self.geometry(f"{config.get('window', 'plot_width')}x"
                      f"{config.get('window', 'plot_height')}")

        self.df = df
        self.plot_style = plot_style
        self.series_style: dict = {}          # Y column name -> plot style code
        self.bar_containers: dict = {}        # Y column name -> BarContainer
        self.bar_cfg: dict = {}               # Y column name -> {width, color, alpha, edgecolor, edgewidth}
        self.errorbar_containers: dict = {}   # Y column name -> ErrorbarContainer
        self.error_cfg: dict = {}             # Y column name -> {type, value, column, capsize, capthick, elinewidth, color}
        self.histogram_cfg: dict = {}         # column name -> {bins, color, alpha, edgecolor, edgewidth}
        self.histogram_edges: dict = {}       # column name -> the bin edges it was counted with
        self.histogram_drawn: set = set()     # columns whose curve carries counts
        self.stairs_cfg: dict = {}            # column -> {edges, color, width, fill, ...}
        self.stairs_patches: dict = {}         # column -> the StepPatch of ax.stairs
        self.hist2d_cfg: dict = {}            # column -> {xbins, ybins, cmap, alpha, bar}
        self.hist2d_meshes: dict = {}         # column -> the QuadMesh of ax.hist2d
        self.hist2d_bars: dict = {}           # column -> the colour bar beside it
        self.pie_cfg: dict = {}               # column -> {start, percent, hole, labels, ...}
        self.pie_wedges: dict = {}            # column -> the wedges of ax.pie
        self.pie_texts: dict = {}             # column -> the texts drawn on it
        # in an error bar diagram: mean column -> the std column beside it
        self.error_partner: dict = {}
        # the column of the error downwards, for the style that has one
        self.error_partner_low: dict = {}
        self.lines: list[Line2D] = []
        self.series: dict = {}          # Y column name -> curve
        self.x_col = str(df.columns[0]) if len(df.columns) else ""
        self._auto_x_label = self.x_col   # the label as long as it is not renamed
        self.legends: dict = {}         # Y column name -> its own legend box
        # which axis every column belongs to: the single X column feeds the
        # bottom or the top X axis, every curve the left or the right Y axis
        self.layout = self._clean_layout(df, layout)
        self.x_side = self.layout["x_side"]
        self.series_axis: dict = {}     # Y column name -> "left" / "right"
        self._color_index = 0           # one colour per curve, on both axes
        self.ax2 = None                 # the right hand Y axis, when it is used
        self.legend_state: dict = {}    # Y column name -> {pos, loc, size, ...}
        self.fills: dict = {}           # Y column name -> filled area
        self.fill_state: dict = {}      # Y column name -> fill settings
        self._drag = None
        self._text_drag = None
        self.notes: dict = {}           # key -> free text box
        self.note_state: dict = {}      # key -> {text, pos, size, colour, box}
        self._note_counter = 0
        self._pending_text = False
        self.shapes: dict = {}          # key -> drawn patch
        self.shape_state: dict = {}     # key -> {kind, x, y, w, h, line, fill}
        self.shape_pictures: dict = {}  # key -> the picture drawn in that box
        self._shape_counter = 0
        self._pending_shape = False
        self._shape_drag = None
        self._plot_drag = None          # dragging the whole plot area about
        self._quiet_draws = False       # while a rebuild is under way
        self._zoom_wanted = None        # where the pushes of the wheel add up
        self._zoom_job = None           # ...and the moment they are drawn
        self._zoom_spot = None          # the point they should keep still
        self._zoom_cost = 0.0           # what the last drawing really took
        self._drag_before = None        # the diagram before the drag started
        self._change_depth = 0          # commands that call one another
        # where each curve stands in the stack; the drawings, the arrows and
        # the text boxes keep theirs in their own state, under "z"
        self.series_z: dict = {}        # Y column name -> its place in the stack
        # (kind, key) -> "left" / "right": which of the two axes a drawn
        # object is on, so that it can stand between the curves of both
        self._object_side: dict = {}
        self._top_side = "right"        # the axes that is drawn over the other
        self._object_menu = None        # the menu of the right click, while open
        # ("shape"|"arrow"|"note"|"legend"|"text", key) - one click selects,
        # a second click opens the properties of the selected object
        self.selection = None
        self._marked = None             # the text that wears the blue veil
        # several objects chosen at once with a rectangle drawn on the
        # background: they are marked together and move together
        self.group = []                 # [(kind, key), ...]
        self._group_marks = []          # the blue boxes drawn around them
        self._group_hidden = False      # ...left off a picture that is saved
        self._group_drag = None         # dragging all of them at once
        self._band = None               # the rectangle being drawn
        self._band_patch = None
        # while something is dragged: the page without it, drawn once
        self._still = None
        # the four sides of the plot area can be selected and pulled
        self.frame_sides = {name: name for name in FRAME_ENDS}
        self._inline = None             # the in-place text editor, while open
        self._rename_click = None       # (kind, key, time) of the last click
        self._rename_prev = None        # the same, one click earlier
        self._pending_rename = None     # a slow second click, waiting for the
                                        # release: a drag moves the text instead
        self._shift_down = False        # Shift snaps the arrows to 45 degrees
        self._handles = None
        self._rotator = None            # the round rotation control point
        self.shape_kind = code_of(SHAPE_KINDS,
                                  config.get("shape", "kind"), "rect")
        self.arrows: dict = {}          # key -> [shaft, head]
        self.arrow_state: dict = {}     # key -> {head, tail, tip, size, line}
        self._arrow_counter = 0
        self._pending_arrow = False
        self.arrow_head = code_of(ARROW_HEADS,
                                  config.get("arrow", "head"), "triangle")
        # how far the title and the axis labels were dragged, in pixels
        self.text_offset = {"title": (0.0, 0.0), "x": (0.0, 0.0),
                            "y": (0.0, 0.0), "y2": (0.0, 0.0)}
        self._text_base = {}
        self._cursor = ""
        self._dpi = float(plot_cfg["dpi"])
        self._dialogs: dict = {}
        self.fonts = config.section("fonts")
        self.legend_loc = plot_cfg["legend_location"]
        self.legend_visible = bool(plot_cfg["legend_visible"])

        grid_defaults = {
            "major": bool(grid_cfg["major"]), "minor": bool(grid_cfg["minor"]),
            "color": safe_hex(grid_cfg["color"], "#b0b0b0"),
            "style": code_of(GRID_STYLES, grid_cfg["style"], ":"),
            "width": float(grid_cfg["width"]),
        }
        self.axis_cfg = {
            which: {"auto": True, "step": None,
                    "minor": max(0, int(grid_cfg["minor_ticks"])),
                    "label_size": int(self.fonts["axis_label"]),
                    "tick_size": int(self.fonts["tick_label"]),
                    "label_color": safe_hex(self.fonts["axis_label_color"], "#000000"),
                    "tick_color": safe_hex(self.fonts["tick_label_color"], "#000000"),
                    "label_pad": float(self.fonts["axis_label_pad"]),
                    "tick_pad": self.default_tick_pad(which),
                    # every axis carries its own colour and its two switches
                    "axis_color": safe_hex(config.get("frame", "color"),
                                           "#000000"),
                    "label_on": True, "ticks_on": True, "tick_labels_on": True,
                    # which way the axis runs, and how its numbers are spread
                    "direction": "standard", "scale": "linear",
                    # where the axis stands in the stack: in front of the
                    # diagram to begin with, each of the three on its own
                    # step so that none of them is tied with another
                    "z": Z_DEFAULT["axis"] + step * Z_STACK_STEP,
                    "grid": dict(grid_defaults)}
            for step, which in enumerate(("x", "y", "y2"))
        }
        # no curve belongs to the right hand scale yet: it is not drawn
        self.axis_cfg["y2"]["direction"] = "off"

        # the page keeps its size whatever the window does; the zoom only
        # changes how large it is drawn, by changing the resolution
        self.page_size = (float(plot_cfg["fig_width"]),
                          float(plot_cfg["fig_height"]))
        self.base_dpi = float(plot_cfg["dpi"])
        self.zoom = 1.0
        self.fig = Figure(figsize=(self.page_size[0] / 2.54, self.page_size[1] / 2.54), dpi=self.base_dpi)
        self.ax = self.fig.add_subplot(111)
        self.watch_limits(self.ax)
        self.default_position = DEFAULT_POSITION
        frame = config.section("frame")
        chosen = (float(frame["left"]), float(frame["bottom"]),
                  float(frame["x_length"]), float(frame["y_length"]))
        # Migrate old default config to the new centered quarter layout
        if all(abs(one - other) < 1e-9 for one, other in zip(chosen, (0.35, 0.35, 0.36, 0.36))):
            chosen = self.default_position
        
        # We now use the exact fractions requested in the settings (DEFAULT_POSITION)
        # instead of overriding them dynamically with fit_position().
        self.frame_cfg = {
            "style": code_of(FRAME_STYLES, frame["style"], "none"),
            "width": float(frame["width"]),
            "color": safe_hex(frame["color"], "#000000"),
            "major_tick_length": float(frame["major_tick_length"]),
            "minor_tick_length": float(frame["minor_tick_length"]),
            "background": ("none" if frame.get("transparent_background")
                           else safe_hex(frame.get("background"), "#ffffff")),
            "figure_background": ("none" if frame.get("transparent_figure")
                                  else safe_hex(frame.get("figure_background"),
                                                "#ffffff")),
            "left": chosen[0], "bottom": chosen[1],
            "x_length": chosen[2], "y_length": chosen[3],
        }

        self._build_widgets()
        if not self._plot_data(plot_cfg):
            self.destroy()
            messagebox.showinfo("Plot", "There is no numeric data to plot.",
                                parent=master)
            return

        self._init_axes(plot_cfg)
        self.refresh_legend()
        self._connect_events()
        self.protocol("WM_DELETE_WINDOW", self.close_window)
        self.draw()

    # -- construction ------------------------------------------------------
    def _build_widgets(self):
        if self.app is not None:
            # the same menu bar as the spreadsheet window, plus this
            # diagram's own commands in the Plot menu
            self.app.build_menubar(self, plot=self)
        else:                       # stand-alone window without the App
            menubar = tk.Menu(self, tearoff=0)
            plot_menu = tk.Menu(menubar, tearoff=0)
            plot_menu.add_command(label="Axes properties...",
                                  command=lambda: self.open_axes_dialog("x"))
            plot_menu.add_command(label="Frame and origin...",
                                  command=lambda: self.open_axes_dialog("frame"))
            plot_menu.add_command(label="Title and fonts...",
                                  command=self.open_title_dialog)
            plot_menu.add_separator()
            plot_menu.add_command(label="Insert picture...",
                                  command=self.insert_picture_file)
            plot_menu.add_command(label="Copy object",
                                  accelerator=f"{ACCEL_NAME}+C",
                                  command=self.copy_selection)
            plot_menu.add_command(label="Cut object",
                                  accelerator=f"{ACCEL_NAME}+X",
                                  command=self.cut_selection)
            plot_menu.add_command(label="Paste object",
                                  accelerator=f"{ACCEL_NAME}+V",
                                  command=self.paste_clipboard)
            plot_menu.add_command(label="Delete object", accelerator="Del",
                                  command=self.delete_selection)
            plot_menu.add_separator()
            plot_menu.add_command(label="Bring to front",
                                  command=self.front_selection)
            plot_menu.add_command(label="Bring forward",
                                  command=self.raise_selection)
            plot_menu.add_command(label="Send backward",
                                  command=self.lower_selection)
            plot_menu.add_command(label="Send to back",
                                  command=self.back_selection)
            plot_menu.add_separator()
            plot_menu.add_command(label="Close", command=self.destroy)
            menubar.add_cascade(label="Plot", menu=plot_menu)
            self.configure(menu=menubar)

        self._build_desk()
        # the figure widget is a child of the desk, so that the desk can
        # carry it about and never draws over it
        self.canvas = FigureCanvasTkAgg(self.fig, master=self.view)
        self._bind_native_focus()
        toolbar = NavigationToolbar2Tk(self.canvas, self, pack_toolbar=False)
        toolbar.update()
        self.toolbar = toolbar
        self.restyle_toolbar(toolbar)     # drawn icons, as on the sheet
        # "add text" button, a little away from the save button
        tk.Frame(toolbar, width=26, height=1).pack(side="left")
        self._text_icon = plot_tool_icon("text") or make_letter_icon("T")
        self.text_button = tk.Button(toolbar, image=self._text_icon,
                                     command=self.arm_text_placement,
                                     relief="flat", borderwidth=1,
                                     highlightthickness=0)
        self.text_button.pack(side="left", padx=2, pady=2)
        self.text_button.bind(
            "<Enter>", lambda _e: toolbar.set_message(
                "Add text: click in the diagram to place a text box"))
        self.text_button.bind("<Leave>", lambda _e: toolbar.set_message(""))

        button_background = toolbar.cget("background")
        self.shape_button = ShapeToolButton(
            toolbar, kind=self.shape_kind, family="shape",
            background=button_background,
            on_draw=lambda: self.arm_shape_drawing(armed=True),
            on_menu=self.show_shape_menu)
        self.shape_button.pack(side="left", padx=(4, 2), pady=2)
        self.shape_button.bind(
            "<Enter>", lambda _e: toolbar.set_message(
                "Draw: click the icon and drag in the diagram, "
                "the arrow selects the shape"), add="+")
        self.shape_button.bind("<Leave>", lambda _e: toolbar.set_message(""),
                               add="+")

        self.arrow_button = ShapeToolButton(
            toolbar, kind=self.arrow_head, family="arrow",
            background=button_background,
            on_draw=lambda: self.arm_arrow_drawing(armed=True),
            on_menu=self.show_arrow_menu)
        self.arrow_button.pack(side="left", padx=(4, 2), pady=2)
        self.arrow_button.bind(
            "<Enter>", lambda _e: toolbar.set_message(
                "Arrow: click the icon and drag in the diagram, "
                "the small arrow selects the head"), add="+")
        self.arrow_button.bind("<Leave>", lambda _e: toolbar.set_message(""),
                               add="+")

        self._picture_icon = picture_tool_icon()
        self.picture_button = tk.Button(
            toolbar, image=self._picture_icon, text=("" if self._picture_icon
                                                     else "Picture"),
            command=self.insert_picture_file, relief="flat", borderwidth=1,
            highlightthickness=0)
        self.picture_button.pack(side="left", padx=(6, 2), pady=2)
        self.picture_button.bind(
            "<Enter>", lambda _e: toolbar.set_message(
                "Picture: choose a file - or paste one, or drop one "
                "into the diagram"))
        self.picture_button.bind("<Leave>", lambda _e: toolbar.set_message(""))
        self._build_zoom_buttons(toolbar)

        try:            # the standard Save button must not save the marks
            save_button = toolbar._buttons.get("Save")
            if save_button is not None:
                save_button.configure(command=self.save_figure_clean)
        except (AttributeError, tk.TclError):
            pass

        # a picture dropped from the Finder, when the system can do it
        self.drop_ready = enable_file_drop(self.canvas.get_tk_widget(),
                                           self.drop_pictures)

        self.bind("<Escape>", lambda _e: self.cancel_tools())
        self.canvas.get_tk_widget().bind("<Escape>",
                                         lambda _e: self.cancel_tools())
        self._bind_keys()
        toolbar.pack(side="top", fill="x")
        ttk.Label(self, text=self.HINT, anchor="center", justify="center",
                  padding=4, foreground="#444").pack(side="bottom", fill="x")
        self._place_page()

    # -- the page: a canvas of its own size, on a desk that scrolls --------
    def _build_desk(self):
        """The desk the page lies on: a canvas of its own, with scrollbars.

        The diagram is a **page**, like a slide: it keeps the size it was
        given whatever the window does, so its proportions never change.
        The window is only a view of that page - when the page is larger
        than the window the desk scrolls, and when it is smaller the page
        sits in the middle of it.  It is built before the figure, so that
        the figure can be made a child of it.
        """
        self._desk = ttk.Frame(self)
        self._desk.rowconfigure(0, weight=1)
        self._desk.columnconfigure(0, weight=1)
        self.view = tk.Canvas(self._desk, highlightthickness=0, borderwidth=0,
                              background=PAGE_BACKDROP)
        self.view.grid(row=0, column=0, sticky="nsew")
        self._view_bars = {
            "y": ttk.Scrollbar(self._desk, orient="vertical",
                               command=self.view.yview),
            "x": ttk.Scrollbar(self._desk, orient="horizontal",
                               command=self.view.xview),
        }
        self.view.configure(yscrollcommand=self._view_bars["y"].set,
                            xscrollcommand=self._view_bars["x"].set)
        self._bars_shown = {"x": False, "y": False}
        return self.view

    def _place_page(self):
        """Lay the page on the desk and let the desk be seen."""
        self._desk.pack(side="top", fill="both", expand=True)
        widget = self.canvas.get_tk_widget()
        widget.configure(highlightthickness=0, borderwidth=0)
        self._page_edge = self.view.create_rectangle(
            0, 0, 1, 1, outline=PAGE_EDGE, width=1)
        self._page_window = self.view.create_window(0, 0, anchor="nw",
                                                    window=widget)
        self.view.bind("<Configure>", lambda _e: self._layout_page())
        self._bind_wheel(self.view)
        self._bind_wheel(widget)
        self._bind_sliding(self.view)
        self._bind_sliding(widget)
        self._layout_page()

    def zoom_gesture(self, factor):
        """Zoom by `factor` around the pointer, wherever the wish came from.

        The toolbar and the keyboard use it; a **pinch** does not reach it,
        because the system never hands that gesture to Tk (see
        `gestures_reach_tk`).  Two fingers zoom by sliding them with
        `Ctrl`/`Cmd` held, which the system does send.
        """
        try:
            x, y = self.winfo_pointerxy()
        except tk.TclError:
            x = y = None
        spot = None if x is None else PointerSpot(x, y)
        return self.zoom_by(max(1e-6, float(factor)), event=spot)

    def _bind_sliding(self, widget):
        """The middle button slides the page about, as in a picture viewer."""
        widget.bind("<Button-2>", self._slide_start, add="+")
        widget.bind("<B2-Motion>", self._slide_move, add="+")
        return widget

    def _slide_start(self, event):
        try:
            self.view.scan_mark(event.x_root - self.view.winfo_rootx(),
                                event.y_root - self.view.winfo_rooty())
        except (AttributeError, tk.TclError):
            return None
        return "break"

    def _slide_move(self, event):
        try:
            self.view.scan_dragto(event.x_root - self.view.winfo_rootx(),
                                  event.y_root - self.view.winfo_rooty(),
                                  gain=1)
        except (AttributeError, tk.TclError):
            return None
        return "break"

    def screen_ratio(self):
        """How many screen pixels one drawn pixel takes on this display.

        A retina screen asks matplotlib for two pixels where the program
        counts one; the number is 1.0 on an ordinary one.
        """
        try:
            return float(getattr(self.canvas, "device_pixel_ratio", 1.0) or 1.0)
        except (AttributeError, TypeError, ValueError):
            return 1.0

    def render_dpi(self):
        """The resolution the page is drawn at just now: page x zoom."""
        return float(self.base_dpi) * float(self.zoom) * self.screen_ratio()

    def page_pixels(self):
        """The size of the page on the screen, in pixels.

        A part of a pixel is dropped, not rounded up - that is what
        matplotlib does with the same numbers, and the two have to agree or
        the widget and the figure would argue about one pixel for ever.
        """
        dpi = self.render_dpi()
        return (max(1, int(self.page_size[0] / 2.54 * dpi + 1e-8)),
                max(1, int(self.page_size[1] / 2.54 * dpi + 1e-8)))

    def _fix_page_size(self):
        """Tell the figure the true size of the page again.

        The widget is a whole number of pixels while the page is a length
        in centimetres, and matplotlib works the one out from the other
        every time the window changes - which would let the proportions of
        the page drift by a fraction of a per cent at every step.  The page
        is the measure, so it is simply set again.
        """
        if getattr(self, "_fixing_page", False):
            return False
        if (abs(self.fig.get_figwidth() * 2.54 - self.page_size[0]) <= 1e-6
                and abs(self.fig.get_figheight() * 2.54 - self.page_size[1]) <= 1e-6):
            return False
        self._fixing_page = True
        try:
            self.fig.set_size_inches(self.page_size[0] / 2.54, self.page_size[1] / 2.54, forward=False)
        except (ValueError, tk.TclError):
            return False
        finally:
            self._fixing_page = False
        return True

    def page_origin(self):
        """Where the top left corner of the page lies on the desk."""
        try:
            return tuple(float(one) for one in
                         self.view.coords(self._page_window))
        except (AttributeError, tk.TclError, TypeError, ValueError):
            return (0.0, 0.0)

    def _layout_page(self):
        """Put the page on the desk: centred if it fits, scrolled if not."""
        view = getattr(self, "view", None)
        if view is None or not view.winfo_exists():
            return False
        page_w, page_h = self.page_pixels()
        widget = self.canvas.get_tk_widget()
        if (widget.winfo_reqwidth() != page_w
                or widget.winfo_reqheight() != page_h):
            widget.configure(width=page_w, height=page_h)
        self._fix_page_size()
        room_w = max(1, view.winfo_width())
        room_h = max(1, view.winfo_height())
        desk_w = max(room_w, page_w + 2 * PAGE_MARGIN)
        desk_h = max(room_h, page_h + 2 * PAGE_MARGIN)
        x = max(PAGE_MARGIN, (desk_w - page_w) // 2)
        y = max(PAGE_MARGIN, (desk_h - page_h) // 2)
        view.coords(self._page_window, x, y)
        view.coords(self._page_edge, x - 1, y - 1, x + page_w, y + page_h)
        view.configure(scrollregion=(0, 0, desk_w, desk_h))
        self._show_bars(desk_w > room_w, desk_h > room_h)
        return True

    def _show_bars(self, need_x, need_y):
        """A scrollbar is only there while the page does not fit."""
        for name, need in (("x", bool(need_x)), ("y", bool(need_y))):
            if self._bars_shown.get(name) == need:
                continue
            bar = self._view_bars[name]
            try:
                if need:
                    if name == "x":
                        bar.grid(row=1, column=0, sticky="ew")
                    else:
                        bar.grid(row=0, column=1, sticky="ns")
                else:
                    bar.grid_remove()
            except tk.TclError:
                continue
            self._bars_shown[name] = need
        return True

    # -- zooming the view --------------------------------------------------
    def _bind_wheel(self, widget):
        """The wheel scrolls the desk; with Ctrl or Cmd it zooms."""
        widget.bind("<MouseWheel>", self._on_wheel, add="+")
        widget.bind("<Shift-MouseWheel>", self._on_wheel, add="+")
        for number in (4, 5, 6, 7):           # X11 sends buttons, not deltas
            try:                              # 6 and 7 are sideways, and
                widget.bind(f"<Button-{number}>", self._on_wheel, add="+")
            except tk.TclError:               # older Tk knows only 4 and 5
                continue
        return widget

    @staticmethod
    def _wheel_steps(event):
        """How far the wheel was turned, as a number of notches.

        It is a **fraction**, not a whole number, and that is the point: a
        mouse wheel clicks once and sends 120, while a trackpad sends a
        run of small pushes as the fingers slide.  Counting each of those
        as a whole notch is what makes a trackpad jump; here each push is
        worth its own small share of one, so the page glides.
        """
        number = getattr(event, "num", 0)
        if number in (4, 6):
            return 1.0
        if number in (5, 7):
            return -1.0
        delta = float(getattr(event, "delta", 0) or 0)
        if not delta:
            return 0.0
        steps = (delta / 120.0 if abs(delta) >= 120
                 else delta / max(1e-6, ZOOM_WHEEL_UNIT))
        return max(-ZOOM_MAX_NOTCHES, min(ZOOM_MAX_NOTCHES, steps))

    def _on_wheel(self, event):
        """One notch of the wheel: scroll the desk, or zoom with Ctrl/Cmd."""
        steps = self._wheel_steps(event)
        if not steps:
            return None
        state = int(getattr(event, "state", 0) or 0)
        # Control everywhere, and Command as well on a Mac (Tk reports it
        # as Mod1 or as Meta, depending on the build)
        control = bool(state & 0x0004)
        if sys.platform == "darwin":
            control = control or bool(state & 0x0008) or bool(state & 0x40000)
        sideways = bool(state & 0x0001) or getattr(event, "num", 0) in (6, 7)
        if control:
            self.zoom_by(ZOOM_STEP ** steps, event=event)
            return "break"
        lines = -steps * ZOOM_SCROLL_LINES
        # a small push must still move the desk by at least one line, or a
        # slow scroll on a trackpad would do nothing at all
        lines = int(lines) or (1 if lines > 0 else -1 if lines < 0 else 0)
        if not lines:
            return "break"
        try:
            if sideways:
                self.view.xview_scroll(lines, "units")
            else:
                self.view.yview_scroll(lines, "units")
        except tk.TclError:
            return None
        return "break"

    def zoom_ceiling(self):
        """As far in as the page may be zoomed on this screen.

        `ZOOM_MAX`, or less when the page is large: the whole page is
        drawn at every step, so a very large one has to stop sooner to
        stay quick under the fingers.
        """
        dpi = float(self.base_dpi) * self.screen_ratio()
        pixels = max(1.0, (self.page_size[0] / 2.54) * (self.page_size[1] / 2.54) * dpi * dpi)
        return max(ZOOM_MIN, min(ZOOM_MAX, math.sqrt(ZOOM_MAX_PIXELS / pixels)))

    def zoom_by(self, factor, event=None):
        """Make the page larger or smaller on the screen.

        The pushes of a wheel or of two fingers on a trackpad arrive far
        faster than a page can be drawn, so they are **gathered up**: each
        one moves the wanted zoom, and a moment later the page is drawn
        once, at the value the fingers have reached by then.  Without that
        the drawing falls behind the fingers and the page seems to stutter.
        """
        wanted = (self._zoom_wanted if self._zoom_wanted is not None
                  else self.zoom) * float(factor)
        wanted = min(max(wanted, ZOOM_MIN), self.zoom_ceiling())
        self._zoom_wanted = wanted
        if event is not None:
            self._zoom_spot = (getattr(event, "x_root", None),
                               getattr(event, "y_root", None))
        if self._zoom_job is None:
            waiting = int(min(max(self._zoom_cost * 1000.0, ZOOM_SETTLE_MS),
                              ZOOM_SETTLE_MAX_MS))
            try:
                self._zoom_job = self.after(waiting, self._apply_wanted_zoom)
            except tk.TclError:
                self._zoom_job = None
                return self.set_zoom(wanted, event=event)
        return wanted

    def _apply_wanted_zoom(self):
        """Draw the page at the zoom the pushes have added up to."""
        self._zoom_job = None
        wanted, self._zoom_wanted = self._zoom_wanted, None
        spot, self._zoom_spot = self._zoom_spot, None
        if wanted is None or not self.winfo_exists():
            return False
        holder = None
        if spot is not None and spot[0] is not None:
            holder = PointerSpot(spot[0], spot[1])
        started = time.monotonic()
        done = self.set_zoom(wanted, event=holder)
        try:                       # paint it now, so the wait below is true
            self.canvas.get_tk_widget().update_idletasks()
        except tk.TclError:
            pass
        self._zoom_cost = time.monotonic() - started
        return done

    def zoom_settled(self):
        """Draw a zoom that is still waiting, now.  Used by the tests."""
        if self._zoom_job is not None:
            try:
                self.after_cancel(self._zoom_job)
            except tk.TclError:
                pass
            self._zoom_job = None
            self._apply_wanted_zoom()
        return self.zoom

    def set_zoom(self, zoom, event=None):
        """Show the page at `zoom` times its own size.

        Only the **view** changes: the page keeps its size in centimetres
        and everything on it keeps its proportions.  It is done by drawing
        the same figure at a higher or lower resolution, so the curves, the
        texts and the line widths all grow and shrink together.  When the
        pointer is over the page, the point under it stays under it.
        """
        zoom = min(max(float(zoom), ZOOM_MIN), self.zoom_ceiling())
        if abs(zoom - self.zoom) < 1e-6:
            return self.zoom
        held = self._page_point_at(event)
        ratio = zoom / self.zoom
        self.zoom = zoom
        # everything below asks for a new drawing; they are held back and
        # one is made at the end, or the wheel would paint the diagram
        # three times over for every push
        with QuietDraws(self):
            # the dragged distances of the title and the axis labels are in
            # points of the page: they follow the new resolution by themselves
            self.fig.set_dpi(self.render_dpi())
            self._layout_page()
            self.update_idletasks()      # the widget takes its new size now
            self.apply_text_offsets()
            self.refresh_shapes()
            self.refresh_arrows()
            self._refresh_handles()
            if held is not None:
                self._keep_page_point(held, event)
        self.draw()
        self._show_zoom()
        self.flash(f"Zoom {self.zoom * 100:.0f}%")
        return self.zoom

    def reset_zoom(self, _event=None):
        """Back to the true size of the page."""
        return self.set_zoom(1.0)

    def zoom_to_fit(self, _event=None):
        """As large as the page can be drawn and still fit in the window."""
        view = getattr(self, "view", None)
        if view is None or not view.winfo_exists():
            return self.zoom
        room_w = max(1, view.winfo_width()) - 2 * PAGE_MARGIN
        room_h = max(1, view.winfo_height()) - 2 * PAGE_MARGIN
        page_w = (self.page_size[0] / 2.54) * self.base_dpi * self.screen_ratio()
        page_h = (self.page_size[1] / 2.54) * self.base_dpi * self.screen_ratio()
        if page_w <= 0 or page_h <= 0:
            return self.zoom
        return self.set_zoom(min(room_w / page_w, room_h / page_h))

    def _page_point_at(self, event):
        """Which point of the page the pointer is on, as two fractions."""
        if event is None:
            return None
        try:
            x = self.view.canvasx(event.x_root - self.view.winfo_rootx())
            y = self.view.canvasy(event.y_root - self.view.winfo_rooty())
        except (AttributeError, tk.TclError, TypeError):
            return None
        page_w, page_h = self.page_pixels()
        origin = self.page_origin()
        return (min(max((x - origin[0]) / page_w, 0.0), 1.0),
                min(max((y - origin[1]) / page_h, 0.0), 1.0))

    def _keep_page_point(self, point, event):
        """Scroll so that the point of the page stays under the pointer."""
        try:
            self.view.update_idletasks()
            region = [float(one) for one in
                      str(self.view.cget("scrollregion")).split()]
            if len(region) != 4:
                return False
            page_w, page_h = self.page_pixels()
            origin = self.page_origin()
            want_x = origin[0] + point[0] * page_w - (
                event.x_root - self.view.winfo_rootx())
            want_y = origin[1] + point[1] * page_h - (
                event.y_root - self.view.winfo_rooty())
            desk_w = max(1.0, region[2] - region[0])
            desk_h = max(1.0, region[3] - region[1])
            self.view.xview_moveto(min(max(want_x / desk_w, 0.0), 1.0))
            self.view.yview_moveto(min(max(want_y / desk_h, 0.0), 1.0))
        except (AttributeError, tk.TclError, TypeError, ValueError):
            return False
        return True

    # -- the size of the page ---------------------------------------------
    def fit_position(self, page=None):
        """The place of the plot area that fills the page and still fits.

        The texts around the plot area - the numbers, the axis labels and
        the title - are set in points, so the room they need is a length,
        not a fraction: a small page has to keep proportionally wider
        margins for exactly the same texts.  `FIT_MARGINS` holds those
        lengths in cm and this turns them into fractions of the page.
        """
        width, height = page or self.page_size
        width = max(1.0, float(width))
        height = max(1.0, float(height))
        left = min(0.45, FIT_MARGINS["left"] / width)
        bottom = min(0.45, FIT_MARGINS["bottom"] / height)
        right = min(0.30, FIT_MARGINS["right"] / width)
        top = min(0.30, FIT_MARGINS["top"] / height)
        return (round(left, 4), round(bottom, 4),
                round(max(MIN_AXIS_SIZE, 1.0 - left - right), 4),
                round(max(MIN_AXIS_SIZE, 1.0 - bottom - top), 4))

    def set_page_size(self, width, height, redraw=True):
        """Give the page another size in cm, and lay it out again."""
        width = max(1.0, float(width))
        height = max(1.0, float(height))
        self.page_size = (width, height)
        self.default_position = DEFAULT_POSITION
        self.fig.set_size_inches(width / 2.54, height / 2.54)
        self._layout_page()
        if redraw:
            self.draw()
        return self.page_size

    def _build_zoom_buttons(self, toolbar):
        """`-`, the zoom itself and `+`, at the end of the toolbar.

        Zooming by gesture is not in the program's gift - the system keeps
        pinches to itself (see `gestures_reach_tk`) - so it is here, one
        click away, beside the wheel and the keyboard.
        """
        tk.Frame(toolbar, width=22, height=1).pack(side="left")

        def small(text, command, hint):
            button = tk.Button(toolbar, text=text, width=2, relief="flat",
                               borderwidth=1, highlightthickness=0,
                               command=command)
            button.pack(side="left", padx=1, pady=2)
            button.bind("<Enter>",
                        lambda _e, words=hint: toolbar.set_message(words))
            button.bind("<Leave>", lambda _e: toolbar.set_message(""))
            return button

        self.zoom_out_button = small(
            "\u2212", lambda: self.zoom_gesture(1.0 / ZOOM_BUTTON_STEP),
            f"Zoom out ({ACCEL_NAME}+minus, or {ACCEL_NAME} and the wheel)")
        self.zoom_label = tk.Button(
            toolbar, text="100%", width=6, relief="flat", borderwidth=1,
            highlightthickness=0, command=self.show_zoom_menu)
        self.zoom_label.pack(side="left", padx=1, pady=2)
        self.zoom_label.bind(
            "<Enter>", lambda _e: toolbar.set_message(
                f"The zoom of the view - click for the usual ones "
                f"({ACCEL_NAME}+0 is the true size of the page)"))
        self.zoom_label.bind("<Leave>", lambda _e: toolbar.set_message(""))
        self.zoom_in_button = small(
            "+", lambda: self.zoom_gesture(ZOOM_BUTTON_STEP),
            f"Zoom in ({ACCEL_NAME}+plus, or {ACCEL_NAME} and the wheel)")
        self._show_zoom()
        return toolbar

    def _show_zoom(self):
        """Write the zoom of the view on its button."""
        button = getattr(self, "zoom_label", None)
        if button is None:
            return False
        try:
            button.configure(text=f"{self.zoom * 100:.0f}%")
        except tk.TclError:
            return False
        return True

    def show_zoom_menu(self, _event=None):
        """The usual zooms, and the two that work themselves out."""
        menu = tk.Menu(self, tearoff=0)
        for percent in ZOOM_PRESETS:
            menu.add_command(label=f"{percent}%",
                             command=lambda one=percent: self.set_zoom(one / 100.0))
        menu.add_separator()
        menu.add_command(label="Fit the window", command=self.zoom_to_fit)
        menu.add_command(label=f"True size ({ACCEL_NAME}+0)",
                         command=self.reset_zoom)
        self._zoom_menu = menu                  # kept, or Tk lets it go
        button = self.zoom_label
        try:
            menu.tk_popup(button.winfo_rootx(),
                          button.winfo_rooty() + button.winfo_height())
        except tk.TclError:
            return None
        finally:
            try:
                menu.grab_release()
            except tk.TclError:
                pass
        return menu

    def restyle_toolbar(self, toolbar):
        """Give matplotlib's own buttons the drawn icons of the program.

        The standard toolbar carries black pictures read from files, which
        look nothing like the drawn buttons of the spreadsheet
        window.  Emptying `_image_file` is what stops matplotlib from
        loading its own picture back over them when the resolution of the
        screen changes; the two tools that stay pressed - `Pan` and `Zoom` -
        get a second icon on a light blue plate, so it is plain to see which
        one is waiting for a click in the diagram.
        """
        self._tool_icons = {}
        buttons = getattr(toolbar, "_buttons", None) or {}
        for name, button in buttons.items():
            icon = TOOLBAR_ICONS.get(str(name))
            if icon is None:
                continue
            plain = plot_tool_icon(icon)
            if plain is None:
                continue                  # without Pillow nothing is drawn
            armed = plot_tool_icon(icon, armed=True) or plain
            self._tool_icons[str(name)] = (plain, armed)
            try:
                button._image_file = None
                button._ntimage = plain
                button._ntimage_alt = armed
                if isinstance(button, tk.Checkbutton):
                    # both at once, or Tk complains about the old picture
                    button.configure(image=plain, selectimage=armed,
                                     width=ICON_SIZE, height=ICON_SIZE)
                else:
                    button.configure(image=plain, width=ICON_SIZE,
                                     height=ICON_SIZE)
            except (tk.TclError, AttributeError):
                continue
        return self._tool_icons

    def take_focus(self, _event=None):
        """Give the keyboard to the diagram canvas.

        matplotlib runs the canvas clicks through its own event loop, which
        does not always hand the focus back to Tk - and after a property
        window has been used, the keyboard belongs to that window.  Setting
        the focus natively keeps the arrow keys, Delete and copy/paste alive.
        """
        if self._inline is not None:
            return None        # the keyboard belongs to the little text editor
        try:
            widget = self.canvas.get_tk_widget()
            if widget.winfo_exists():
                widget.focus_set()
        except (tk.TclError, AttributeError):
            pass
        return None            # never "break": matplotlib needs the click too

    def _bind_native_focus(self):
        """Every click in the diagram brings the keyboard back, natively."""
        widget = self.canvas.get_tk_widget()
        try:
            widget.configure(takefocus=True)
        except tk.TclError:
            pass
        for sequence in ("<Button-1>", "<Button-2>", "<Button-3>"):
            # add="+" keeps matplotlib's own handlers of these events
            widget.bind(sequence, self.take_focus, add="+")
        if sys.platform == "darwin":
            # Control and the one button of a Mac trackpad is a right click
            widget.bind("<Control-Button-1>", self._menu_click, add="+")
        # when the window itself is activated and nothing inside it holds the
        # keyboard, the diagram takes it
        self.bind("<FocusIn>", self._window_focused, add="+")

    def _menu_click(self, event):
        """A Tk click that must open the menu of the right button."""
        widget = self.canvas.get_tk_widget()
        self.show_object_menu(event.x, widget.winfo_height() - event.y,
                              getattr(event, "x_root", None),
                              getattr(event, "y_root", None))
        return "break"

    def _window_focused(self, _event=None):
        """This diagram window became the active one: it takes the keyboard.

        A widget of this very window keeps it (a text being written in the
        little in-place editor, for instance), and so does a cell of the
        spreadsheet that is open for editing - it must keep its blinking
        cursor.  The keyboard is taken back from anything else that belongs
        to another window: after a property dialog was used, its own field
        may still be holding it.
        """
        try:
            current = self.focus_displayof()
        except (tk.TclError, KeyError):
            current = None
        if current is None or current is self:
            self.take_focus()
            return None
        try:
            if current.winfo_toplevel() is self:
                return None            # a widget of this window: it keeps it
        except tk.TclError:
            current = None
        app = getattr(self, "app", None)
        if app is not None and current is not None:
            try:
                if app.keyboard_busy(current):
                    return None        # a cell is being written: leave it
            except (tk.TclError, AttributeError):
                pass
        self.take_focus()
        return None

    def _bind_keys(self):
        """Copy, paste, deleting and moving the selected object."""
        def wrap(function, *args):
            def handler(_event=None):
                function(*args)
                return "break"
            return handler

        canvas_widget = self.canvas.get_tk_widget()

        def bind_both(sequence, handler):
            # on the canvas (which owns the focus while the diagram is used)
            # and on the window (for the toolbar and the rest of it)
            self.bind(sequence, handler)
            try:
                canvas_widget.bind(sequence, handler)
            except tk.TclError:
                pass

        for modifier in ("Control", "Command"):
            for letter in ("c", "C"):
                bind_both(f"<{modifier}-{letter}>", wrap(self.copy_shortcut))
            for letter in ("v", "V"):
                bind_both(f"<{modifier}-{letter}>", wrap(self.paste_clipboard))
            for letter in ("x", "X"):
                bind_both(f"<{modifier}-{letter}>", wrap(self.cut_selection))
            for letter in ("d", "D"):
                bind_both(f"<{modifier}-{letter}>",
                          wrap(self.duplicate_selection))
            # the view of the page: true size, larger, smaller
            bind_both(f"<{modifier}-Key-0>", wrap(self.reset_zoom))
            for plus in ("plus", "equal", "KP_Add"):
                bind_both(f"<{modifier}-Key-{plus}>",
                          wrap(self.zoom_by, ZOOM_STEP))
            for minus in ("minus", "KP_Subtract"):
                bind_both(f"<{modifier}-Key-{minus}>",
                          wrap(self.zoom_by, 1.0 / ZOOM_STEP))
        for sequence in ("<Delete>", "<BackSpace>"):
            bind_both(sequence, wrap(self.delete_selection))

        steps = {"Left": (-1, 0), "Right": (1, 0), "Up": (0, 1), "Down": (0, -1)}
        for name, (sx, sy) in steps.items():
            bind_both(f"<{name}>",
                      wrap(self.nudge_selection, sx * NUDGE_STEP, sy * NUDGE_STEP))
            bind_both(f"<Shift-{name}>",
                      wrap(self.nudge_selection,
                           sx * NUDGE_BIG_STEP, sy * NUDGE_BIG_STEP))

        # Shift snaps the arrows: remember whether it is held down
        for sequence in ("<KeyPress-Shift_L>", "<KeyPress-Shift_R>"):
            bind_both(sequence, lambda _e: setattr(self, "_shift_down", True))
        for sequence in ("<KeyRelease-Shift_L>", "<KeyRelease-Shift_R>"):
            bind_both(sequence, lambda _e: setattr(self, "_shift_down", False))
        self.bind("<FocusOut>", lambda _e: setattr(self, "_shift_down", False),
                  add="+")

    # -- the four axes: bottom / top X, left / right Y ----------------------
    @staticmethod
    def _clean_layout(df, layout):
        """Which axis every column of the data belongs to, safely defaulted."""
        columns = [str(one) for one in df.columns]
        given = layout or {}
        side = "top" if str(given.get("x_side")) == "top" else "bottom"
        raw = given.get("y") or {}
        sides = {name: ("right" if str(raw.get(name, "left")) == "right"
                        else "left")
                 for name in columns[1:]}
        return {"x": columns[0] if columns else None,
                "x_side": side, "y": sides}

    def plot_axes(self):
        """Every axes that can carry curves: the main one and the twin."""
        return [self.ax] if self.ax2 is None else [self.ax, self.ax2]

    def series_side(self, column):
        """"left" or "right": the Y axis one curve is drawn against."""
        return self.series_axis.get(column, "left")

    def right_axis_carries_curves(self):
        """True while at least one curve is drawn against the right scale."""
        return any(side == "right" for side in self.series_axis.values())

    def right_axis_active(self):
        """True while the right hand Y axis is drawn.

        It is drawn as soon as a curve belongs to it - and also when it was
        asked for on its own page of the axes dialog, even with no curve on
        it at all: it then simply carries a scale of its own, 0 ... 1.
        """
        return self.axis_direction("y2") != "off"

    def right_axis_wanted(self):
        """True when the right Y axis was asked for without any curve."""
        return (self.axis_direction("y2") != "off"
                and not self.right_axis_carries_curves())

    # -- the direction an axis runs in, and the scale of its numbers -------
    def axis_direction(self, which):
        """"off", "standard" or "reverse" for one of the three axes.

        The right hand axis is the special one: as long as a curve belongs
        to it, it is drawn whatever the setting says - the curve would have
        no scale to be measured against otherwise.
        """
        cfg = self.axis_cfg.get(which) or {}
        direction = str(cfg.get("direction", "standard"))
        if direction not in AXIS_DIRECTIONS:
            direction = "standard"
        if (which == "y2" and direction == "off"
                and self.right_axis_carries_curves()):
            return "standard"
        return direction

    def axis_scale(self, which):
        """"linear", "log10", "log2" or "ln" for one of the three axes."""
        cfg = self.axis_cfg.get(which) or {}
        scale = str(cfg.get("scale", "linear"))
        return scale if scale in LOG_BASES or scale == "linear" else "linear"

    def axis_shown(self, which):
        """True while that axis is drawn at all."""
        if self.axis_direction(which) == "off":
            return False
        if which == "y2":
            return self.right_axis_active()
        if which == "y":
            return self.left_axis_shown()
        return True

    def axis_scale_matches(self, which):
        """True while the axis already carries the scale that was asked for.

        Telling matplotlib the scale again throws away the tick locators of
        the axis, so it is only told when something really changes.
        """
        if which == "y2" and self.ax2 is None:
            return True
        ax, axis, axis_name = self._axis_pair(which)
        scale = self.axis_scale(which)
        now = ax.get_xscale() if axis_name == "x" else ax.get_yscale()
        if scale == "linear":
            return now == "linear"
        if now != "log":
            return False
        try:
            return abs(float(axis.get_scale() == "log"
                             and axis._scale.base) - LOG_BASES[scale]) < 1e-9
        except (AttributeError, TypeError, ValueError):
            return False

    @staticmethod
    def log_major_base(base, step, limits=None):
        """How far apart the major ticks of a logarithmic axis stand.

        On such an axis the interval is not a distance but a **ratio**:
        `Major ticks interval` counts powers of the base.  On a `Log 10`
        axis one is the usual 1, 10, 100; two gives 1, 100, 10000; a half
        gives 1, 3.16, 10, and so on.

        An interval **wider than the axis itself** is not obeyed: it would
        leave the axis with a single tick or none at all, which can never
        be what was meant - and a file written while the number meant
        nothing here may carry anything.  It is then read as one power.
        """
        base = float(base)
        try:
            step = float(step)
        except (TypeError, ValueError):
            step = 1.0
        if not step or step <= 0 or not np.isfinite(step):
            step = 1.0
        step = min(step, LOG_STEP_MAX)         # so the power below is finite
        spacing = base ** step
        if not np.isfinite(spacing) or spacing <= 1.0000001:
            return base
        if limits:
            try:
                low, high = sorted(float(one) for one in limits)
            except (TypeError, ValueError):
                low = high = 0.0
            if low > 0 and high > low and spacing > high / low:
                return base                    # wider than the whole axis
        return spacing

    @staticmethod
    def log_minor_subs(base, count):
        """Where the minor ticks of a logarithmic axis stand.

        They stand on the **whole numbers** between one major tick and the
        next - 2, 3, ... 9 inside a decade - because that is what a reader
        of such an axis looks for.  `Minor ticks` says how many of them are
        drawn, and the ones kept are those that come nearest to standing at
        even distances **on the paper**: one is 3, two are 2 and 5, three
        are 2, 3 and 6, and eight are the whole decade, 2 to 9.

        When the interval holds no whole number at all - a `Log 2` axis
        holds none between 1 and 2 - or fewer than were asked for, it is
        divided into equal parts of the **value** instead, which gives the
        half, the quarters and so on.
        """
        base = float(base)
        count = min(max(0, int(count)), LOG_SUBS_MAX)
        if count <= 0 or not np.isfinite(base) or base <= 1.0:
            return ()
        top = int(math.floor(base)) if base <= LOG_SUBS_MAX + 1 else 0
        inside = [float(one) for one in range(2, top + 1) if 1.0 < one < base]
        if count > len(inside):        # no whole number fits, or too few
            reach = base - 1.0
            return tuple(1.0 + reach * one / (count + 1.0)
                         for one in range(1, count + 1))
        if count == len(inside):
            return tuple(inside)
        logs = {one: math.log(one) for one in inside}
        span = math.log(base)
        picked = []
        for number in range(1, count + 1):
            free = [one for one in inside if one not in picked]
            if not free:
                break
            wanted = span * number / (count + 1.0)
            picked.append(min(free, key=lambda one: abs(logs[one] - wanted)))
        return tuple(sorted(picked))

    def apply_axis_scale(self, which, redraw=False):
        """Spread the numbers of one axis linearly or logarithmically."""
        if which == "y2" and self.ax2 is None:
            return "linear"        # there is no right hand axis to set
        ax, axis, axis_name = self._axis_pair(which)
        scale = self.axis_scale(which)
        setter = ax.set_xscale if axis_name == "x" else ax.set_yscale
        if not self.axis_scale_matches(which):
            try:
                if scale == "linear":
                    setter("linear")
                else:
                    setter("log", base=LOG_BASES[scale])
            except (ValueError, TypeError, AttributeError):
                setter("linear")
                scale = "linear"
        if scale != "linear":
            # a logarithmic axis cannot start at zero or below it
            low, high = self.current_limits(which)
            if min(low, high) <= 0.0:
                top = max(low, high, LOG_FLOOR * 10.0)
                bottom = top / 1000.0
                (ax.set_xlim if axis_name == "x" else ax.set_ylim)(bottom, top)
        self.apply_axis_direction(which)
        if redraw:
            self.draw()
        return scale

    def apply_axis_direction(self, which):
        """Turn one axis round, or put it back the usual way."""
        if which == "y2" and self.ax2 is None:
            return False           # there is no right hand axis to turn
        ax, _axis, axis_name = self._axis_pair(which)
        reverse = self.axis_direction(which) == "reverse"
        try:
            inverted = (ax.xaxis_inverted() if axis_name == "x"
                        else ax.yaxis_inverted())
            if bool(inverted) != bool(reverse):
                (ax.invert_xaxis if axis_name == "x" else ax.invert_yaxis)()
        except (AttributeError, ValueError):
            return False
        return reverse

    def empty_axis_range(self, which):
        """Give an axis without any curve something to show: 0 ... 1."""
        if which != "y2" or not self.right_axis_wanted():
            return False
        cfg = self.axis_cfg.get("y2") or {}
        if not cfg.get("auto", True):
            return False
        ax = self.ensure_right_axis()
        low, high = EMPTY_RANGE
        if self.axis_scale("y2") != "linear":
            low = max(LOG_FLOOR, 0.1)
        ax.set_ylim(low, high)
        self.apply_axis_direction("y2")
        return True

    def axes_for_side(self, side):
        return self.ensure_right_axis() if side == "right" else self.ax

    def ensure_right_axis(self):
        """The second Y axis on the right, built the first time it is needed."""
        if self.ax2 is not None:
            return self.ax2
        ax2 = self.ax.twinx()          # same X axis, its own Y scale
        self.ax2 = ax2
        self.watch_limits(ax2)
        ax2.patch.set_visible(False)
        ax2.grid(False)
        for spine in ax2.spines.values():
            spine.set_visible(False)   # the frame is drawn by the main axes
        ax2.set_ylabel("")
        ax2.yaxis.label.set_picker(True)
        self._text_base["y2"] = ax2.yaxis.label.get_transform()
        self.apply_axis("y2", {**self.axis_cfg["y2"], "label": ""}, redraw=False)
        ax2.set_position(self.ax.get_position())
        return ax2

    def left_axis_active(self):
        """True while at least one curve belongs to the left Y axis."""
        return any(side == "left" for side in self.series_axis.values())

    def only_pies(self):
        """True while every curve of this diagram is a pie.

        A pie needs no axes at all, but one pie beside a curve still does -
        so it is the whole diagram that decides, not one series.
        """
        return self.styles_in_use() == {"pie"}

    def apply_style_axes(self, redraw=False):
        """Give the axes to the styles that are drawn on them.

        A **pie** has no axes: no label, no numbers, no frame line, and a
        square range with an equal aspect.  Every other style needs all of
        that back, so switching a curve away from a pie has to undo it -
        otherwise the curve is drawn far outside the little square the pie
        left behind and nothing at all appears.
        """
        pie = self.only_pies()
        if pie == getattr(self, "_pie_axes", None):
            return False                   # the axes already fit the styles
        if pie:
            # what the axes carried before, to be given back later on
            self._axis_memory = {
                which: {"label": self.axis_label(which),
                        "label_on": bool(self.axis_cfg[which].get("label_on",
                                                                  True)),
                        "ticks_on": bool(self.axis_cfg[which].get("ticks_on",
                                                                  True)),
                        "tick_labels_on": bool(self.axis_cfg[which].get("tick_labels_on",
                                                                        True))}
                for which in ("x", "y")}
            for which in ("x", "y"):
                self.apply_axis(which, {**self.axis_cfg[which], "label": "",
                                        "label_on": False, "ticks_on": False,
                                        "tick_labels_on": False},
                                redraw=False)
            # the square itself is not touched here: the pie may already be
            # drawn (a window that opens as a pie draws it first of all)
        else:
            memory = getattr(self, "_axis_memory", None) or {}
            plot_cfg = self.settings.section("plot")
            fallback = {"x": self.x_axis_name(),
                        "y": str(plot_cfg.get("y_label", ""))}
            self.ax.set_aspect("auto")
            for which in ("x", "y"):
                saved = memory.get(which) or {}
                # the square of a pie is no range for a curve: the automatic
                # one is worked out again from the data
                self.apply_axis(which, {
                    **self.axis_cfg[which],
                    "label": saved.get("label", fallback[which]),
                    "label_on": saved.get("label_on", True),
                    "ticks_on": saved.get("ticks_on", True),
                    "tick_labels_on": saved.get("tick_labels_on", True),
                    "auto": True, "min": None, "max": None}, redraw=False)
            self._axis_memory = None
            self._pie_span = None
        self._pie_axes = pie
        self.apply_frame(self.frame_cfg, redraw=False)
        self._rescale()
        self.apply_text_offsets()
        if redraw:
            self.draw()
        return True

    def used_sides(self):
        """The sides of the plot area that really carry an axis.

        `No frame (X and Y only)` draws exactly these: the X axis on the
        side the `x_B` / `x_T` check button chose, and the Y axis - or both
        Y axes - the curves are drawn against.  So a diagram of a top X axis
        and a right Y axis shows those two lines and nothing else.
        """
        if self.only_pies():
            return []                  # a pie stands on no axis
        sides = []
        # `No X axis` in the Direction box takes the line away as well: no
        # element of that axis is drawn at all.  (A closed frame is a frame
        # around the plot area, not an axis, and keeps all four of its
        # sides.)
        if self.axis_direction("x") != "off":
            sides.append("top" if self.x_side == "top" else "bottom")
        right = self.right_axis_active()
        if (self.left_axis_active() or not right) and self.left_axis_shown():
            sides.append("left")
        if right and self.axis_direction("y2") != "off":
            sides.append("right")
        return sides

    def left_axis_shown(self):
        """True while the left Y axis carries a scale worth drawing."""
        if self.axis_direction("y") == "off":
            return False           # the user asked for no left Y axis
        return self.left_axis_active() or not self.right_axis_active()

    def _apply_axis_sides(self):
        """Draw the X axis at the bottom or at the top, and the right Y axis.

        Only the axes that are really used show their numbers: with every
        curve on the right hand scale the left one disappears completely,
        numbers, tick marks and label together.
        """
        top = self.x_side == "top"
        both = self.frame_cfg.get("style") in ("box_in", "box_out")
        # `No X axis` (or no left / right Y axis) takes the line of that
        # axis away as well, so the sides are worked out again here - the
        # Direction box can change them without the frame dialog
        if not self.only_pies():
            used = self.used_sides()
            closed = str(self.frame_cfg.get("style", "none")) != "none"
            for name, spine in self.ax.spines.items():
                spine.set_visible(closed or name in used)
        if self.axis_direction("y2") != "off" and self.ax2 is None:
            self.ensure_right_axis()     # asked for, without a curve on it
        right = self.right_axis_active()
        left = self.left_axis_shown()
        # "No X axis" / "No left Y axis" / "No right Y axis" of the pages
        x_shown = self.axis_direction("x") != "off"
        # the "Tick range, labels and fonts" switch of each axis page
        x_ticks = bool(self.axis_cfg["x"].get("ticks_on", True)) and x_shown
        y_ticks = bool(self.axis_cfg["y"].get("ticks_on", True))
        y2_ticks = bool(self.axis_cfg["y2"].get("ticks_on", True))
        x_tick_labels = x_ticks and bool(self.axis_cfg["x"].get("tick_labels_on", True))
        y_tick_labels = y_ticks and bool(self.axis_cfg["y"].get("tick_labels_on", True))
        y2_tick_labels = y2_ticks and bool(self.axis_cfg["y2"].get("tick_labels_on", True))
        
        self.ax.xaxis.set_visible(x_shown)
        self.ax.xaxis.set_ticks_position("top" if top else "bottom")
        self.ax.xaxis.set_label_position("top" if top else "bottom")
        self.ax.tick_params(axis="x", which="both",
                            top=(both or top) and x_ticks,
                            bottom=(both or not top) and x_ticks,
                            labeltop=top and x_tick_labels,
                            labelbottom=(not top) and x_tick_labels)
        # with a closed frame the opposite side keeps its tick marks, but not
        # when the right hand Y axis has a scale of its own
        self.ax.yaxis.set_visible(left)
        self.ax.tick_params(axis="y", which="both",
                            left=(left or both) and y_ticks,
                            right=(both and not right) and y_ticks,
                            labelleft=left and y_tick_labels, labelright=False)
        if self.ax2 is not None:
            self.ax2.set_visible(right)
            self.ax2.yaxis.set_ticks_position("right")
            self.ax2.yaxis.set_label_position("right")
            self.ax2.tick_params(axis="y", which="both", left=False,
                                 right=right and y2_ticks,
                                 labelleft=False, labelright=right and y2_tick_labels)
        self._apply_y_grid()
        self._apply_axis_colors()
        # a curve that moved to the other scale changes which axes lies
        # over which, and so where the drawn objects have to be
        self.apply_stack_layers()
        # an automatic range straightens an axis out again: the ones that
        # were turned round are turned back, last of all
        for which in ("x", "y", "y2"):
            self.apply_axis_direction(which)
        return None

    def spine_owner(self, name):
        """Which axis page owns the colour of one side of the plot area."""
        if name in HORIZONTAL_SIDES:
            return "x"
        if name == "left":
            return "y"
        return "y2" if self.right_axis_active() else "y"

    def axis_color(self, which):
        """The colour of one axis line and of its tick marks."""
        cfg = self.axis_cfg.get(which) or {}
        return safe_hex(cfg.get("axis_color", "#000000"), "#000000")

    def _apply_axis_colors(self):
        """Every axis paints its own line and its own tick marks."""
        for name, spine in self.ax.spines.items():
            spine.set_color(self.axis_color(self.spine_owner(name)))
        self.ax.tick_params(axis="x", which="both", color=self.axis_color("x"))
        self.ax.tick_params(axis="y", which="both", color=self.axis_color("y"))
        if self.ax2 is not None:
            self.ax2.tick_params(axis="y", which="both",
                                 color=self.axis_color("y2"))
        return None

    def _apply_y_grid(self):
        """The Y grid belongs to the Y axis whose numbers are shown."""
        owner = "y" if self.left_axis_shown() else "y2"
        for which, ax in (("y", self.ax), ("y2", self.ax2)):
            if ax is None:
                continue
            cfg = self.axis_cfg[which]
            grid = cfg["grid"]
            if which == owner and grid["major"]:
                ax.grid(True, which="major", axis="y", color=grid["color"],
                        linestyle=grid["style"], linewidth=grid["width"])
            else:
                ax.grid(False, which="major", axis="y")
            if which == owner and grid["minor"] and cfg["minor"]:
                ax.grid(True, which="minor", axis="y", color=grid["color"],
                        linestyle=grid["style"],
                        linewidth=max(0.3, grid["width"] * 0.6))
            else:
                ax.grid(False, which="minor", axis="y")
        return None

    def set_x_side(self, side, redraw=True):
        """Put the X axis under or above the plot area."""
        side = "top" if str(side) == "top" else "bottom"
        if side == self.x_side:
            return False
        self.x_side = side
        self.layout["x_side"] = side
        self.apply_frame(self.frame_cfg, redraw=False)   # spines follow
        if redraw:
            self.draw()
        return True

    def move_series(self, column, side):
        """Draw one curve against the left or the right Y axis."""
        side = "right" if str(side) == "right" else "left"
        line = self.series.get(column)
        if line is None:
            return False
        target = self.axes_for_side(side)
        if line.axes is not target:
            try:
                line.remove()
            except (ValueError, AttributeError):
                pass
            target.add_line(line)
            line.set_transform(target.transData)
        changed = self.series_axis.get(column) != side
        self.series_axis[column] = side
        self.refresh_fill(column)
        if changed:
            self._rescale()
            self.apply_frame(self.frame_cfg, redraw=False)
        return changed

    def measure_data(self, ax, scalex=True, scaley=True):
        """Fit the automatic range to the curves, ignoring the filled areas.

        A fill that reaches "down to the axis" takes its baseline from the
        range that is valid at that moment.  Left in the calculation it
        would push that baseline further down at every redraw - the range
        would creep away, and a diagram would not even come back from its
        own file unchanged.  So the areas are hidden while the range is
        measured: they are a picture of the curves, not data of their own.
        """
        hidden = [fill for fill in self.fills.values()
                  if getattr(fill, "axes", None) is ax and fill.get_visible()]
        for fill in hidden:
            fill.set_visible(False)
        try:
            ax.relim(visible_only=True)
            ax.autoscale_view(scalex=scalex, scaley=scaley)
        finally:
            for fill in hidden:
                fill.set_visible(True)
        return None

    def _rescale(self):
        """Let the automatic ranges follow the data of both Y axes."""
        if self.only_pies():
            return                     # a pie has no range to follow
        auto_x = self.axis_cfg["x"]["auto"]
        auto_y = self.axis_cfg["y"]["auto"]
        if (auto_x or auto_y) and self.ax.lines:
            self.measure_data(self.ax, scalex=auto_x, scaley=auto_y)
        if self.ax2 is not None and self.ax2.lines:
            if self.axis_cfg["y2"]["auto"]:
                self.measure_data(self.ax2, scalex=False, scaley=True)

    @staticmethod
    def _series_data(df, x_col, y_col):
        """Numeric X/Y pairs of one column, gaps kept as gaps.

        Nothing is thrown away: every empty cell - in the Y column, in the X
        column, or a whole empty row - becomes "not a number", and matplotlib
        neither draws a point there nor connects the two sides of it.  So a
        gap left in the table really is a gap in the curve instead of a
        straight line across it.
        """
        data = pd.DataFrame({
            "x": df[x_col],
            "y": df[y_col],
        })
        
        # When plotting multiple tabs merged together, pd.merge(how="outer")
        # introduces np.nan for rows that only exist in the other tab. We MUST
        # drop those so they don't break our lines. Original gaps were marked
        # with GAP_MARK before the merge, so ~pd.isna() preserves them.
        valid = ~pd.isna(data["y"])
        data = data[valid].copy()
        
        data["x"] = pd.to_numeric(data["x"], errors="coerce")
        data["y"] = pd.to_numeric(data["y"], errors="coerce")
        
        return (data["x"].to_numpy(dtype=float),
                data["y"].to_numpy(dtype=float))

    @staticmethod
    def _cycle_color(index):
        """The index-th colour of matplotlib's own colour sequence."""
        cycle = matplotlib.rcParams.get("axes.prop_cycle")
        colors = list((cycle.by_key().get("color") if cycle else None) or [])
        if not colors:
            return PALETTE_FALLBACK
        return colors[int(index) % len(colors)]

    def _create_line(self, x, y, y_col, x_col, side="left", style=None):
        """New curve drawn with the defaults of the configuration file.

        The colour is taken from the sequence by hand, so that a curve on the
        right hand Y axis is not painted in the same colour as the first one
        on the left: the second axes would start the sequence again.
        """
        plot_cfg = self.settings.section("plot")
        target = self.axes_for_side(side)
        color = self._cycle_color(self._color_index)
        self._color_index += 1
        series_st = style or self.plot_style
        self.series_style[y_col] = series_st

        # a pie writes the names beside its slices: a box with one single
        # colour in it says nothing, so it starts switched off
        pie_label = "_nolegend_" if series_st == "pie" else str(y_col)
        if series_st == "line":
            l_style = code_of(LINE_STYLES, plot_cfg["line_style"], "-")
            if l_style.lower() == "none":
                l_style = "-"
            m_style = "None"
        elif series_st == "scatter":
            l_style = "none"
            m_style = code_of(MARKERS, plot_cfg["marker"], "o")
            if m_style.lower() == "none":
                m_style = "o"
        elif series_st in ("bar", "histogram", "stairs", "hist2d", "pie"):
            l_style = "none"        # the artist beside the curve is the plot
            m_style = "None"
        elif series_st in ERROR_STYLES:
            l_style = "none"
            m_style = code_of(MARKERS, plot_cfg["marker"], "o")
            if m_style.lower() == "none":
                m_style = "o"
        else:  # line_symbol
            l_style = code_of(LINE_STYLES, plot_cfg["line_style"], "-")
            if l_style.lower() == "none":
                l_style = "-"
            m_style = code_of(MARKERS, plot_cfg["marker"], "o")
            if m_style.lower() == "none":
                m_style = "o"

        line, = target.plot(
            x, y, color=color,
            linestyle=l_style,
            linewidth=float(plot_cfg["line_width"]),
            marker=m_style,
            markersize=float(plot_cfg["marker_size"]),
            markeredgewidth=float(plot_cfg["marker_edge_width"]),
            label=pie_label)           # the column name is the legend text
        if plot_cfg["hollow_markers"]:
            line.set_markerfacecolor("none")
            line.set_markeredgecolor(line.get_color())
        line.set_picker(True)
        line.set_pickradius(6)
        line.aplot_series = str(y_col)  # used to detect custom legend texts
        self.lines.append(line)
        self.series[y_col] = line
        self.series_axis[y_col] = "right" if target is self.ax2 else "left"
        self.fill_state.setdefault(y_col, self.default_fill_state(plot_cfg))
        self.refresh_series_visuals(y_col)
        # a curve drawn for the first time is given a place of its own at
        # the front of the stack.  Two curves at the same height are drawn
        # in whatever order matplotlib happens to hold them, and the parts
        # of a curve - its error bars, its filling - stand a little above
        # its own line, so a tie lets one curve's error bars cross another
        # curve: exactly how a fitted line comes out looking dashed.
        if str(y_col) not in self.series_z:
            self.set_series_zorder(y_col, self.top_z())
        return line

    def _clear_bar(self, column):
        old = self.bar_containers.pop(column, None)
        if old is not None:
            try:
                old.remove()
            except Exception:
                for patch in getattr(old, "patches", []):
                    try:
                        patch.remove()
                    except Exception:
                        pass

    def refresh_bar(self, column):
        self._clear_bar(column)
        st = self.series_style.get(column, self.plot_style)
        if st != "bar":
            return None
        line = self.series.get(column)
        if line is None:
            return None
        x_data, y_data = line.get_data()
        if len(x_data) == 0:
            return None
        target = line.axes if line.axes is not None else self.ax
        cfg = self.bar_cfg.setdefault(column, {
            "width": 0.8, "color": safe_hex(line.get_color()), "alpha": 0.85,
            "edgecolor": safe_hex(line.get_color()), "edgewidth": 1.0,
            "hatch": ""
        })
        cfg.setdefault("hatch", "")
        w = float(cfg.get("width", 0.8))
        try:
            x_arr = np.asarray(x_data, dtype=float)
            if len(x_arr) > 1:
                diffs = np.diff(np.sort(x_arr))
                pos_diffs = diffs[diffs > 0]
                if len(pos_diffs) > 0 and w <= 1.0:
                    w = float(cfg.get("width", 0.8)) * float(np.min(pos_diffs))
        except (ValueError, TypeError):
            pass

        container = target.bar(
            x_data, y_data, width=w,
            color=cfg.get("color", line.get_color()),
            edgecolor=cfg.get("edgecolor", safe_hex(line.get_color())),
            linewidth=float(cfg.get("edgewidth", 1.0)),
            alpha=float(cfg.get("alpha", 0.85)),
            hatch=(cfg.get("hatch") or None),
            label="_nolegend_",
            zorder=line.get_zorder() - 0.2
        )
        for patch in container.patches:
            patch.aplot_series = str(column)
            patch.set_picker(True)
        self.bar_containers[column] = container
        return container

    def _clear_errorbar(self, column):
        old = self.errorbar_containers.pop(column, None)
        if old is not None:
            try:
                old.remove()
            except Exception:
                for coll in getattr(old, "lines", []):
                    try:
                        coll.remove()
                    except Exception:
                        pass

    def partner_low_column(self, column):
        """The column that holds the **downward** error bars of one curve.

        Only `Error Bar (Median, +error, -error)` has one: its columns are
        read in threes - the values, the error upwards and the error
        downwards - so it is the second column after the values.  The other
        error bar style draws one length both ways and has none.
        """
        found = self.error_partner_low.get(column)
        if found and found in self.df.columns:
            return found
        if self.series_style.get(column, self.plot_style) != "errorbar_pm":
            return None
        names = [str(one) for one in self.df.columns]
        text = str(column)
        if text in names:
            index = names.index(text) + 2
            if index < len(names):
                return names[index]
        return None

    def partner_column(self, column):
        """The column that holds the error bars of one curve.

        In an error bar diagram the pairs are worked out when the curves are
        built (`curve_columns`).  For a single curve that was switched to
        this style by hand, the column standing right after it in the table
        is taken - which is what "the next column" means.
        """
        found = self.error_partner.get(column)
        if found and found in self.df.columns:
            return found
        names = [str(one) for one in self.df.columns]
        text = str(column)
        if text in names:
            index = names.index(text) + 1
            if index < len(names):
                return names[index]
        return None

    def series_rows(self, column):
        """The rows of the table this curve was really drawn from.

        A diagram that holds more than one sheet - a fitted curve beside
        its measurements, say - has rows that belong to the other sheet,
        and this column is empty in them.  The curve skips those rows
        (see `_series_data`), so anything else read for that curve has to
        skip exactly the same ones, or it would be read a row too early
        from the very first gap onwards.
        """
        column = str(column or "")
        if not column or column not in self.df.columns:
            return None
        try:
            return ~pd.isna(self.df[column])
        except (TypeError, ValueError):
            return None

    def _error_from_column(self, name, y_arr, rows=None):
        """The error bar lengths read from one column of the table.

        `rows` is the mask of the rows the curve itself was drawn from, so
        that the n-th bar belongs to the n-th point and not to the n-th
        row of a table that holds other sheets as well.
        """
        name = str(name or "")
        if not name or name not in self.df.columns:
            return None
        values = pd.to_numeric(self.df[name], errors="coerce")
        if rows is not None:
            try:
                values = values[rows]
            except (IndexError, KeyError, TypeError, ValueError):
                pass
        values = np.abs(values.to_numpy(float))
        if len(values) >= len(y_arr):
            return values[:len(y_arr)]
        return np.pad(values, (0, len(y_arr) - len(values)),
                      constant_values=np.nan)

    def refresh_errorbar(self, column):
        self._clear_errorbar(column)
        st = self.series_style.get(column, self.plot_style)
        if st not in ERROR_STYLES:
            return None
        line = self.series.get(column)
        if line is None:
            return None
        x_data, y_data = line.get_data()
        if len(x_data) == 0:
            return None
        target = line.axes if line.axes is not None else self.ax
        cfg = self.error_cfg.setdefault(column, {
            "type": "pair", "value": 5.0, "column": "",
            "capsize": 4.0, "capthick": 1.5, "elinewidth": 1.5,
            "color": line.get_color()
        })

        err_type = cfg.get("type", "pair")
        err_val = float(cfg.get("value", 5.0))
        y_arr = np.asarray(y_data, dtype=float)

        rows = self.series_rows(column)
        if err_type == "pair":
            # the column right after this one holds the standard deviation
            yerr = self._error_from_column(self.partner_column(column), y_arr,
                                           rows)
            if yerr is None:            # no column left over: fall back to 5 %
                yerr = np.abs(y_arr * 0.05)
            elif st == "errorbar_pm":
                # ...and the one after that the error downwards, which may
                # be a different length: matplotlib wants [down, up]
                down = self._error_from_column(self.partner_low_column(column),
                                               y_arr, rows)
                yerr = np.vstack([yerr if down is None else down, yerr])
        elif err_type == "percent":
            yerr = np.abs(y_arr * (err_val / 100.0))
        elif err_type == "fixed":
            yerr = np.full_like(y_arr, err_val)
        elif err_type == "std":
            finite_y = y_arr[np.isfinite(y_arr)]
            std = float(np.std(finite_y)) if len(finite_y) > 1 else 1.0
            yerr = np.full_like(y_arr, std)
        elif err_type == "column":
            yerr = self._error_from_column(cfg.get("column", ""), y_arr, rows)
            if yerr is None:
                yerr = np.abs(y_arr * 0.05)
        else:
            yerr = np.abs(y_arr * 0.05)

        color = cfg.get("color", line.get_color())
        capsize = float(cfg.get("capsize", 4.0))
        capthick = float(cfg.get("capthick", 1.5))
        elinewidth = float(cfg.get("elinewidth", 1.5))

        container = target.errorbar(
            x_data, y_data, yerr=yerr, fmt='none',
            ecolor=color, elinewidth=elinewidth,
            capsize=capsize, capthick=capthick,
            label="_nolegend_", zorder=line.get_zorder() + 0.1
        )
        for artist in container.get_children():
            artist.aplot_series = str(column)
            artist.set_picker(True)
        self.errorbar_containers[column] = container
        return container

    def _clear_histogram(self, column):
        self._clear_bar(f"hist_{column}")

    @staticmethod
    def _bin_widths(centers):
        """Bar widths that make the bars of a histogram touch each other."""
        centers = np.asarray(centers, dtype=float)
        if len(centers) < 2:
            return np.ones_like(centers)
        order = np.argsort(centers)
        steps = np.diff(centers[order])
        steps = steps[steps > 0]
        step = float(np.min(steps)) if len(steps) else 1.0
        return np.full_like(centers, step)

    # -- a histogram counts the values of one column by itself --------------
    @staticmethod
    def default_histogram_cfg(line=None):
        return {"bins": HISTOGRAM_BINS,
                "color": safe_hex(line.get_color() if line is not None
                                  else PALETTE_FALLBACK, PALETTE_FALLBACK),
                "alpha": 0.85, "edgecolor": "#ffffff", "edgewidth": 1.0,
                "hatch": ""}

    def histogram_bins(self, column):
        """How many bins the sample of one column is counted into."""
        cfg = self.histogram_cfg.get(column) or {}
        try:
            count = int(float(cfg.get("bins", HISTOGRAM_BINS)))
        except (TypeError, ValueError):
            count = HISTOGRAM_BINS
        return max(1, min(count, MAX_HISTOGRAM_BINS))

    @staticmethod
    def sample_values(df, column):
        """The numbers of one column: the sample a histogram counts.

        Empty cells and text are not values, so they are simply left out -
        a histogram has no gaps, it has counts.
        """
        if df is None or str(column) not in [str(one) for one in df.columns]:
            return np.array([], dtype=float)
        values = pd.to_numeric(df[column], errors="coerce").to_numpy(dtype=float)
        return values[np.isfinite(values)]

    def histogram_points(self, df, column):
        """The centre of every bin and how many values fell into it.

        This is the statistics `ax.hist` does: the range the sample covers
        is cut into `bins` equal parts and the values are counted.  One
        column of raw measurements is all a histogram needs, so the first
        column of the table is a sample of its own as well.
        """
        values = self.sample_values(df, column)
        if len(values) == 0:
            self.histogram_edges.pop(column, None)
            return np.array([], dtype=float), np.array([], dtype=float)
        counts, edges = np.histogram(values, bins=self.histogram_bins(column))
        self.histogram_edges[column] = edges
        centers = (edges[:-1] + edges[1:]) / 2.0
        return centers, counts.astype(float)

    # -- one single column: the X axis is the row number --------------------
    @staticmethod
    def has_numbers(df, column):
        """True when that column holds at least one number."""
        return bool(len(PlotWindow.sample_values(df, column)))

    def styles_in_use(self):
        """The plot styles this diagram really draws right now."""
        return ({self.series_style.get(name, self.plot_style)
                 for name in self.series} or {self.plot_style})

    def needs_x_axis(self):
        """True while at least one thing drawn here reads an X column.

        A histogram counts a column of its own accord and a pie has no axes
        at all, so a diagram made only of those needs no X values.  The
        styles of the **curves** decide it, not the style the window was
        opened with: one curve switched from a pie to a bar chart wants its
        X axis back at once.
        """
        return bool(self.styles_in_use() - {"histogram", "pie"})

    def row_numbers_mode(self, df=None):
        """True while the first column is the only column with numbers.

        One column of values is a series of measurements, not an X axis: it
        becomes the first curve and the **row number** of the table becomes
        the X axis, exactly as the numbers at the left of the spreadsheet
        show them.  A histogram never needs this - it counts every column
        of its own accord.
        """
        if not self.needs_x_axis():
            return False               # nothing drawn here reads an X axis
        frame = self.df if df is None else df
        if frame is None or not len(frame.columns):
            return False
        columns = [str(one) for one in frame.columns]
        if not self.has_numbers(frame, columns[0]):
            return False
        return not any(self.has_numbers(frame, name) for name in columns[1:])

    def text_x_mode(self, df=None):
        """True while the first column holds names instead of numbers.

        A table of `Solar, Wind, Hydro | 24, 19, 15` is the natural shape of
        a pie or a bar chart, but its first column is no X axis: there is
        not a single number in it.  Every other diagram then draws its
        curves against the **row number**, so switching such a curve away
        from a pie really shows something instead of an empty frame.
        """
        if not self.needs_x_axis():
            return False               # nothing drawn here reads an X axis
        frame = self.df if df is None else df
        if frame is None or len(frame.columns) < 2:
            return False
        columns = [str(one) for one in frame.columns]
        if self.has_numbers(frame, columns[0]):
            return False
        return any(self.has_numbers(frame, name) for name in columns[1:])

    def x_is_rows(self, df=None):
        """True while the X axis carries the row number of the table."""
        return self.row_numbers_mode(df) or self.text_x_mode(df)

    @staticmethod
    def row_number_points(df, column):
        """The values of one column against the row numbers of the table.

        The first row is 1, so the X value of a point is the number that
        stands beside it in the spreadsheet.  Empty cells stay gaps.
        """
        values = pd.to_numeric(df[column], errors="coerce").to_numpy(dtype=float)
        return (np.arange(1, len(values) + 1, dtype=float), values)

    def x_axis_name(self):
        """What the X axis carries: the first column, or the row number."""
        if self.x_is_rows():
            return ROW_AXIS_LABEL
        return str(self.df.columns[0]) if len(self.df.columns) else ""

    def series_points(self, df, x_col, y_col, style=None):
        """The X/Y pairs one curve is drawn from.

        Every style reads the first column as X and the column itself as Y.
        There are two exceptions: a **histogram** counts the raw values of
        the column itself, so the pairs are its bin centres and counts;
        and a table whose **first column is the only filled one** has no X
        column at all, so that column is drawn against the row numbers.
        """
        style = style or self.series_style.get(y_col, self.plot_style)
        if style == "histogram":
            return self.histogram_points(df, y_col)
        columns = [str(one) for one in df.columns]
        if columns and str(y_col) == columns[0] and self.row_numbers_mode(df):
            return self.row_number_points(df, y_col)
        if self.text_x_mode(df):
            # the first column names the rows: there is no X value to read
            return self.row_number_points(df, y_col)
        return self._series_data(df, x_col, y_col)

    def refresh_histogram(self, column):
        """Count the values of `column` again and draw the bars."""
        self._clear_histogram(column)
        st = self.series_style.get(column, self.plot_style)
        line = self.series.get(column)
        if st != "histogram" or line is None:
            return None
        cfg = self.histogram_cfg.setdefault(
            column, self.default_histogram_cfg(line))
        for key, value in self.default_histogram_cfg(line).items():
            cfg.setdefault(key, value)

        # the statistics is made here and now: a changed number of bins,
        # or changed data, is counted again
        centers, counts = self.histogram_points(self.df, column)
        line.set_data(centers, counts)     # the curve behind the bars
        self.histogram_drawn.add(column)
        if not len(centers):
            return None
        edges = self.histogram_edges.get(column)
        widths = (np.diff(np.asarray(edges, dtype=float))
                  if edges is not None and len(edges) > 1
                  else self._bin_widths(centers))
        target = line.axes if line.axes is not None else self.ax

        container = target.bar(
            centers, counts, width=widths, align="center",
            color=cfg.get("color", line.get_color()),
            edgecolor=cfg.get("edgecolor", "#ffffff"),
            linewidth=float(cfg.get("edgewidth", 1.0)),
            alpha=float(cfg.get("alpha", 0.85)),
            hatch=(cfg.get("hatch") or None),
            label="_nolegend_",
            zorder=line.get_zorder() - 0.2
        )
        for patch in container.patches:
            patch.aplot_series = str(column)
            patch.set_picker(True)
        self.bar_containers[f"hist_{column}"] = container
        return container

    def font_family(self):
        """The font this diagram is drawn with, or None for the usual one."""
        return known_font_family((self.fonts or {}).get("family"))

    def apply_font_family(self, family=None, redraw=False):
        """Give every text of this diagram the same font.

        A text made later takes its font from the settings of the program,
        so a diagram opened after the setting was changed is drawn with the
        new font from the first line; this brings the ones that are already
        on the paper over as well.
        """
        family = known_font_family(family) or self.font_family()
        if family is None:
            return False
        if self.fonts is not None:
            self.fonts["family"] = family
        for text in self.fig.findobj(Text):
            try:
                text.set_fontfamily(family)
            except (ValueError, AttributeError):
                continue
        if redraw:
            self.draw()
        return True

    def draw_as_smooth_line(self, names):
        """Draw these curves as a plain line: no markers, no bars.

        A fitted curve is written with many points close together, so the
        markers of a `Line + Symbol` diagram would be a solid band over the
        measurements it belongs to.
        """
        changed = False
        for name in names:
            # the style is remembered even for a column that carries no
            # curve yet: a fitted column that only becomes one at the next
            # `Update` is still a fitted curve, and is drawn as a line
            self.series_style[str(name)] = "line"
            line = self.series.get(name)
            if line is None:
                continue
            line.set_linestyle("-")
            line.set_marker("None")
            self.refresh_series_visuals(name)
            changed = True
        if changed:
            self.apply_style_axes()
            self._rescale()
            self.refresh_legend()
            self.draw()
        return changed

    def restore_series_data(self, column):
        """Put the values of a column back on its curve, whatever it drew.

        While a curve is drawn as a histogram it carries the counts of the
        bins, not the data of the table, and a style change may also change
        what the X axis carries (a pie reads no X column at all, so leaving
        one gives the curve its X values back).  So the points are worked
        out again from the table for the style the curve has now.
        """
        self.histogram_drawn.discard(column)
        self.histogram_edges.pop(column, None)
        line = self.series.get(column)
        if line is None or str(column) not in [str(one) for one in self.df.columns]:
            return False
        x_name = self.x_col if self.x_col in self.df.columns else \
            str(self.df.columns[0])
        line.set_data(*self.series_points(self.df, x_name, column))
        return True

    # -- a stepped outline: ax.stairs ---------------------------------------
    def _clear_stairs(self, column):
        patch = self.stairs_patches.pop(column, None)
        if patch is not None:
            try:
                patch.remove()
            except (ValueError, AttributeError):
                pass

    @staticmethod
    def default_stairs_cfg(line=None):
        return {"edges": "mid", "width": 1.8, "fill": False, "alpha": 0.35,
                "baseline": False,
                "color": safe_hex(line.get_color() if line is not None
                                  else PALETTE_FALLBACK, PALETTE_FALLBACK),
                "hatch": ""}

    @staticmethod
    def _step_of(distance):
        """A usable width: never zero, never "not a number"."""
        value = float(distance)
        return 1.0 if (not np.isfinite(value) or value == 0.0) else value

    @staticmethod
    def stairs_edges(x_data, mode="mid"):
        """The `N + 1` edges of `N` values: where the steps stand.

        `mid` puts the step halfway between two X values (every value is
        valid around its own X), `post` at the X value itself and `pre`
        just before it.

        The X values must be **numbers**: matplotlib refuses an edge that
        is "not a number", so a point with an empty X cell is left out by
        `stairs_points` before the edges are worked out.
        """
        x_arr = np.asarray(x_data, dtype=float)
        x_arr = x_arr[np.isfinite(x_arr)]      # a missing X is no edge
        count = len(x_arr)
        if count == 0:
            return np.array([0.0, 1.0])
        if count == 1:
            return np.array([x_arr[0] - 0.5, x_arr[0] + 0.5])
        first_step = PlotWindow._step_of(x_arr[1] - x_arr[0])
        last_step = PlotWindow._step_of(x_arr[-1] - x_arr[-2])
        if str(mode) == "post":
            return np.concatenate([x_arr, [x_arr[-1] + last_step]])
        if str(mode) == "pre":
            return np.concatenate([[x_arr[0] - first_step], x_arr])
        middles = (x_arr[:-1] + x_arr[1:]) / 2.0
        return np.concatenate([[x_arr[0] - first_step / 2.0], middles,
                               [x_arr[-1] + last_step / 2.0]])

    def stairs_points(self, column):
        """The points a staircase can stand on: those that have an X value.

        An empty cell in the **X** column leaves its point without a place
        on the axis, and an edge that is "not a number" is refused by
        matplotlib, so such a point is left out.  An empty cell in the
        **value** column is kept as it is: it becomes a gap in the
        staircase, exactly as it breaks any other curve.
        """
        line = self.series.get(column)
        if line is None:
            return np.array([], dtype=float), np.array([], dtype=float)
        x_arr = np.asarray(line.get_xdata(), dtype=float)
        y_arr = np.asarray(line.get_ydata(), dtype=float)
        standing = np.isfinite(x_arr)
        if len(y_arr) != len(x_arr):           # never, but never crash either
            return np.array([], dtype=float), np.array([], dtype=float)
        return x_arr[standing], y_arr[standing]

    def refresh_stairs(self, column):
        """Draw the values of one column as a staircase."""
        self._clear_stairs(column)
        st = self.series_style.get(column, self.plot_style)
        line = self.series.get(column)
        if st != "stairs" or line is None:
            return None
        cfg = self.stairs_cfg.setdefault(column,
                                         self.default_stairs_cfg(line))
        for key, value in self.default_stairs_cfg(line).items():
            cfg.setdefault(key, value)
        x_arr, y_arr = self.stairs_points(column)
        if not len(y_arr) or not bool(np.isfinite(y_arr).any()):
            return None
        edges = self.stairs_edges(x_arr, cfg.get("edges", "mid"))
        if len(edges) != len(y_arr) + 1 or not np.isfinite(edges).all():
            return None                # nothing sensible to stand the steps on
        target = line.axes if line.axes is not None else self.ax
        filled = bool(cfg.get("fill"))
        # a filled staircase needs a floor to stand on; an open one is a
        # line and may hang in the air
        baseline = 0.0 if (filled or cfg.get("baseline")) else None
        patch = target.stairs(
            y_arr, edges, baseline=baseline,
            fill=filled, color=cfg.get("color", line.get_color()),
            linewidth=float(cfg.get("width", 1.8)),
            alpha=(float(cfg.get("alpha", 0.35)) if filled else None),
            hatch=(cfg.get("hatch") or None),
            label="_nolegend_", zorder=line.get_zorder())
        if filled:
            # a crisp outline over a see-through face, as a filled area does
            colour = cfg.get("color", line.get_color())
            patch.set_alpha(None)
            patch.set_facecolor(to_rgba(colour, float(cfg.get("alpha", 0.35))))
            patch.set_edgecolor(colour)
        patch.aplot_series = str(column)
        patch.set_picker(True)
        self.stairs_patches[column] = patch
        return patch

    # -- the X/Y pairs counted in a grid: ax.hist2d -------------------------
    def _clear_hist2d(self, column):
        bar = self.hist2d_bars.pop(column, None)
        if bar is not None:
            try:
                bar.remove()               # the colour bar and its own axes
            except (ValueError, AttributeError, KeyError):
                pass
        mesh = self.hist2d_meshes.pop(column, None)
        if mesh is not None:
            try:
                mesh.remove()
            except (ValueError, AttributeError):
                pass

    @staticmethod
    def default_hist2d_cfg(_line=None):
        return {"xbins": HIST2D_BINS, "ybins": HIST2D_BINS, "cmap": "viridis",
                "alpha": 1.0, "colorbar": False, "hide_empty": True}

    def hist2d_bins(self, column, which="xbins"):
        cfg = self.hist2d_cfg.get(column) or {}
        try:
            count = int(float(cfg.get(which, HIST2D_BINS)))
        except (TypeError, ValueError):
            count = HIST2D_BINS
        return max(1, min(count, MAX_HIST2D_BINS))

    def hist2d_pairs(self, column):
        """The X/Y pairs of one curve, without the gaps."""
        line = self.series.get(column)
        if line is None:
            return np.array([], dtype=float), np.array([], dtype=float)
        x_arr = np.asarray(line.get_xdata(), dtype=float)
        y_arr = np.asarray(line.get_ydata(), dtype=float)
        good = np.isfinite(x_arr) & np.isfinite(y_arr)
        return x_arr[good], y_arr[good]

    def refresh_hist2d(self, column):
        """Count the X/Y pairs of one curve into a grid of cells."""
        self._clear_hist2d(column)
        st = self.series_style.get(column, self.plot_style)
        line = self.series.get(column)
        if st != "hist2d" or line is None:
            return None
        cfg = self.hist2d_cfg.setdefault(column, self.default_hist2d_cfg(line))
        for key, value in self.default_hist2d_cfg(line).items():
            cfg.setdefault(key, value)
        x_arr, y_arr = self.hist2d_pairs(column)
        if len(x_arr) < 2:
            return None
        target = line.axes if line.axes is not None else self.ax
        bins = [self.hist2d_bins(column, "xbins"),
                self.hist2d_bins(column, "ybins")]
        try:
            _counts, _xe, _ye, mesh = target.hist2d(
                x_arr, y_arr, bins=bins, cmap=str(cfg.get("cmap", "viridis")),
                alpha=float(cfg.get("alpha", 1.0)),
                cmin=(1 if cfg.get("hide_empty", True) else None),
                zorder=line.get_zorder() - 0.3)
        except (ValueError, TypeError):
            return None
        mesh.aplot_series = str(column)
        mesh.set_picker(True)
        mesh.set_label("_nolegend_")
        self.hist2d_meshes[column] = mesh
        if cfg.get("colorbar"):
            self._add_color_bar(column, mesh, target)
        return mesh

    def _add_color_bar(self, column, mesh, target):
        """A colour scale beside the plot area, in axes of its own.

        It is an inset of the plot area, so it follows it wherever the
        frame is dragged and never takes room away from the diagram.
        """
        try:
            cax = target.inset_axes([1.02, 0.0, 0.035, 1.0])
            bar = self.fig.colorbar(mesh, cax=cax)
            bar.outline.set_linewidth(float(self.frame_cfg.get("width", 1.0)))
            size = int(self.axis_cfg["y"].get("tick_size", 12))
            cax.tick_params(labelsize=size)
            for artist in (cax, bar.outline):
                artist.set_in_layout(True)
            self.hist2d_bars[column] = bar
            return bar
        except (ValueError, TypeError, AttributeError):
            return None

    # -- the values of one column as slices: ax.pie -------------------------
    def _clear_pie(self, column):
        for artist in (list(self.pie_wedges.pop(column, ()) or ())
                       + list(self.pie_texts.pop(column, ()) or ())):
            try:
                artist.remove()
            except (ValueError, AttributeError):
                pass

    @staticmethod
    def default_pie_cfg(_line=None):
        return {"start": PIE_START_ANGLE, "percent": True, "decimals": 1,
                "hole": 0.0, "labels": "column", "cmap": "tab10",
                "edgecolor": "#ffffff", "edgewidth": 1.0, "explode": 0.0,
                "clockwise": True, "label_size": 11,
                "labeldistance": PIE_LABEL_DISTANCE,
                "pctdistance": PIE_PCT_DISTANCE,
                "rotate_labels": False, "rotate_numbers": False,
                "names_on": True,
                "name_size": 11, "name_color": "#000000",
                "pct_size": 11, "pct_color": "#000000",
                "names": []}

    @staticmethod
    def pie_text_style(cfg, which):
        """Font size and colour of the names or of the numbers of a pie.

        `label_size` was the one size of both texts before they could be
        set apart, so a diagram saved then keeps its font.
        """
        old = cfg.get("label_size", 11)
        size = cfg.get("name_size" if which == "name" else "pct_size", old)
        color = cfg.get("name_color" if which == "name" else "pct_color",
                        "#000000")
        return max(1, to_int(size, 11)), safe_hex(color, "#000000")

    def pie_slice_data(self, column):
        """The value of every slice of a pie and the row it comes from.

        Empty cells and zeros are no slices, and a negative number is taken
        by its size.
        """
        names = [str(one) for one in self.df.columns]
        if str(column) not in names:
            return np.array([], dtype=float), np.array([], dtype=int)
        raw = pd.to_numeric(self.df[column], errors="coerce").to_numpy(float)
        good = np.isfinite(raw) & (np.abs(raw) > 0)
        return np.abs(raw[good]), np.nonzero(good)[0]

    def pie_source_names(self, column):
        """The name the table gives every slice, drawn or not.

        The legend box lists the slices by these names even while the texts
        around the pie itself are switched off.
        """
        names = [str(one) for one in self.df.columns]
        _values, rows = self.pie_slice_data(column)
        cfg = self.pie_cfg.get(column) or {}
        wanted = str(cfg.get("labels", "column"))
        if wanted == "row" or not names or names[0] == str(column):
            return [str(int(one) + 1) for one in rows]
        source = self.df[names[0]]
        return [("" if pd.isna(source.iat[int(one)])
                 else str(source.iat[int(one)])) for one in rows]

    def pie_names_on(self, column):
        """True while the names are written around the pie."""
        cfg = self.pie_cfg.get(column) or {}
        if str(cfg.get("labels", "column")) == "none":
            return False           # a file saved before the check button
        return bool(cfg.get("names_on", True))

    def pie_values(self, column):
        """The slices of a pie and the names written beside them.

        The names are an empty list while they are switched off - that is
        what `ax.pie` wants for a pie with no text around it.
        """
        values, _rows = self.pie_slice_data(column)
        if not len(values) or not self.pie_names_on(column):
            return values, []
        return values, self.pie_names(column, self.pie_source_names(column))

    def pie_names(self, column, automatic):
        """The slice names, with the ones written by hand on top of them.

        Every legend row of a pie can be renamed on its own (a slow second
        click on it).  What was typed in is kept per slice; a slice that was
        never touched keeps the name the table gives it.
        """
        automatic = list(automatic)
        if not automatic:
            return []
        chosen = (self.pie_cfg.get(column) or {}).get("names") or []
        for index, text in enumerate(list(chosen)[:len(automatic)]):
            if str(text).strip():
                automatic[index] = str(text)
        return automatic

    def pie_slice_names(self, column, count):
        """One name per slice, even when the pie writes none beside them."""
        source = self.pie_source_names(column)
        automatic = (list(source) if len(source) == count
                     else [str(index + 1) for index in range(count)])
        return self.pie_names(column, automatic)

    def set_pie_name(self, column, index, text):
        """Give one slice of a pie a name of its own ("" = the table's)."""
        cfg = self.pie_cfg.setdefault(column, self.default_pie_cfg())
        stored = list(cfg.get("names") or [])
        while len(stored) <= int(index):
            stored.append("")
        stored[int(index)] = str(text)
        cfg["names"] = stored
        return stored

    def refresh_pie(self, column):
        """Draw one column as a pie: one slice per row."""
        self._clear_pie(column)
        st = self.series_style.get(column, self.plot_style)
        line = self.series.get(column)
        if st != "pie" or line is None:
            return None
        cfg = self.pie_cfg.setdefault(column, self.default_pie_cfg(line))
        for key, value in self.default_pie_cfg(line).items():
            cfg.setdefault(key, value)
        values, labels = self.pie_values(column)
        if not len(values):
            return None
        target = line.axes if line.axes is not None else self.ax
        # what stood on the axes before: ax.pie() sets a range of its own
        was = (tuple(target.get_xlim()), tuple(target.get_ylim()))
        colors = self.slice_colors(cfg.get("cmap", "tab10"), len(values))
        explode = float(cfg.get("explode", 0.0) or 0.0)
        hole = max(0.0, min(float(cfg.get("hole", 0.0) or 0.0), 0.95))
        percent = None
        if cfg.get("percent"):
            percent = f"%.{max(0, int(cfg.get('decimals', 1)))}f%%"
        try:
            wedges, texts, *rest = target.pie(
                values, labels=(labels or None), colors=colors,
                startangle=float(cfg.get("start", PIE_START_ANGLE)),
                counterclock=bool(cfg.get("clockwise", True)),
                autopct=percent,
                labeldistance=float(cfg.get("labeldistance",
                                            PIE_LABEL_DISTANCE)),
                pctdistance=float(cfg.get("pctdistance", PIE_PCT_DISTANCE)),
                rotatelabels=bool(cfg.get("rotate_labels", False)),
                explode=([explode] + [0.0] * (len(values) - 1)
                         if explode else None),
                textprops={"fontsize": int(cfg.get("label_size", 11))},
                wedgeprops={"width": (1.0 - hole) if hole else None,
                            "edgecolor": cfg.get("edgecolor", "#ffffff"),
                            "linewidth": float(cfg.get("edgewidth", 1.0))})
        except (ValueError, TypeError):
            return None
        numbers = list(rest[0] if rest else [])
        written = list(texts) + numbers
        # the names and the numbers carry their own font and colour
        for which, group in (("name", list(texts)), ("pct", numbers)):
            size, color = self.pie_text_style(cfg, which)
            for text in group:
                text.set_fontsize(size)
                text.set_color(color)
        if cfg.get("rotate_numbers") and numbers:
            self.turn_with_slices(numbers, wedges)
        for wedge in wedges:
            wedge.aplot_series = str(column)
            wedge.set_picker(True)
        # the names and the numbers of the slices open the properties too:
        # a pie has no curve to click on
        for text in written:
            text.aplot_series = str(column)
            text.set_picker(True)
        self.pie_wedges[column] = list(wedges)
        self.pie_texts[column] = written
        if self.only_pies():
            self.fit_pie_area(target, explode, before=was)
        else:
            # a pie beside an ordinary curve: the axes belong to the curve,
            # so the frame and the range ax.pie() has just taken are put back
            self._pie_span = None
            target.set_frame_on(True)
            for setter, (low, high) in zip((target.set_xlim, target.set_ylim),
                                           was):
                if low is not None:
                    setter(low, high)
        return wedges

    @staticmethod
    def turn_with_slices(texts, wedges):
        """Lay the numbers of a pie along their own slice."""
        for text, wedge in zip(texts, wedges):
            middle = math.radians((float(wedge.theta1)
                                   + float(wedge.theta2)) / 2.0)
            outward = math.cos(middle) >= 0
            text.set_rotation(math.degrees(middle) + (0 if outward else 180))
            text.set_rotation_mode("anchor")
            text.set_ha("center")
            text.set_va("center")
        return texts

    def fit_pie_area(self, target, explode=0.0, before=None):
        """Give the pie the whole plot area, and keep it round.

        A pie is a circle of radius 1 around the origin, but the curve that
        carries its numbers still lies in the axes - and an automatic range
        would follow *that*, leaving the pie as a tiny dot in the corner.
        So the range becomes the square the pie really needs, and the axes
        keep an equal aspect, which makes the circle as tall as the plot
        area and centres it.

        `before` is the range that was on the axes before the pie was
        drawn: while it is still the square of the pie itself, the square
        may grow with the slices that are pulled out.  A range that was
        typed in by hand is never overruled.
        """
        span = round(1.12 + max(0.0, float(explode or 0.0)), 4)
        target.set_aspect("equal", adjustable="box", anchor="C")
        last = getattr(self, "_pie_span", None)
        limits = before or ((None, None), (None, None))
        for which, (low, high) in zip(("x", "y"), limits):
            stored = self.axis_cfg.get(which) or {}
            setter = target.set_xlim if which == "x" else target.set_ylim
            ours = (bool(last) and low is not None
                    and abs(low + last) < 1e-6 and abs(high - last) < 1e-6)
            if stored.get("auto", True) or ours:
                self.axis_cfg[which] = {**stored, "auto": False,
                                        "min": -span, "max": span}
                setter(-span, span)
            elif low is not None:
                setter(low, high)      # set by hand: ax.pie() had moved it
        self._pie_span = span
        return span

    @staticmethod
    def slice_colors(name, count):
        """`count` colours taken from a colour map, for the pie slices."""
        try:
            cmap = matplotlib.colormaps[str(name)]
        except (KeyError, AttributeError, TypeError):
            cmap = matplotlib.colormaps["tab10"]
        if getattr(cmap, "N", 256) <= 32:        # a table of distinct colours
            return [cmap(index % cmap.N) for index in range(max(1, count))]
        if count <= 1:
            return [cmap(0.5)]
        return [cmap(index / (count - 1)) for index in range(count)]

    # -- what every style draws beside (or instead of) its curve -----------
    # the styles that draw an artist of their own next to the curve
    EXTRA_ARTISTS = ("bar", "errorbar", "errorbar_pm", "histogram", "stairs",
                     "hist2d", "pie")
    # ... and those whose curve is not drawn at all: that artist is the plot
    CARRIER_ONLY = ("bar", "histogram", "stairs", "hist2d", "pie")

    def clear_extras(self, column, keep=None):
        """Remove what every other style drew beside this curve."""
        keep = "errorbar" if keep in ERROR_STYLES else keep
        for style in self.EXTRA_ARTISTS:
            if style in ERROR_STYLES:
                style = "errorbar"        # the two of them share one artist
            if style != keep:
                getattr(self, f"_clear_{style}")(column)

    def refresh_series_visuals(self, column):
        """Draw one curve the way its own plot style says.

        Every style has exactly one place here: what the other styles drew
        beside the curve is removed, the curve itself is given the line and
        the marker its style allows, and the artist of the style (bars,
        error bars, a staircase, a grid of counts, slices) is drawn.
        """
        st = self.series_style.get(column, self.plot_style)
        line = self.series.get(column)
        if line is not None:
            if st != "histogram":
                # the points follow the style: a curve that was a histogram
                # carried counts, and one that was a pie carried no X values
                self.restore_series_data(column)
            self.clear_extras(column, keep=st)
            if st in self.CARRIER_ONLY:
                # the curve itself is not drawn: the artist beside it is
                line.set_linestyle("none")
                line.set_marker("None")
            elif st == "line":
                line.set_marker("None")     # this style has no marker at all
            elif st == "scatter":
                line.set_linestyle("none")  # ... and this one no line
            # line_symbol and errorbar: the Line and the Marker check button
            # of the curve dialog decide, so nothing is put back here - or
            # those two switches (and a saved diagram) would lose what the
            # user chose.  A new curve gets its line and marker from
            # _create_line, and changing the style from _on_style_changed.
            if st in self.EXTRA_ARTISTS:
                # both error bar styles are drawn by the same method: one
                # of them simply reads a second column of error
                name = "errorbar" if st in ERROR_STYLES else st
                getattr(self, f"refresh_{name}")(column)
        self.refresh_fill(column)

    # -- filled area under a curve -----------------------------------------
    @staticmethod
    def default_fill_state(plot_cfg):
        return {
            "on": bool(plot_cfg.get("fill_under", False)),
            "follow": bool(plot_cfg.get("fill_follows_line", True)),
            "color": safe_hex(plot_cfg.get("fill_color"), PALETTE_FALLBACK),
            "alpha": float(plot_cfg.get("fill_alpha", 0.35)),
            "hatch": code_of(HATCH_PATTERNS, plot_cfg.get("fill_pattern"), ""),
            "base": code_of(FILL_BASES, plot_cfg.get("fill_base"), "bottom"),
        }

    def refresh_fill(self, column):
        """Draw (or remove) the filled area belonging to one curve."""
        old = self.fills.pop(column, None)
        if old is not None:
            try:
                old.remove()
            except (ValueError, AttributeError):
                pass
        line = self.series.get(column)
        cfg = self.fill_state.get(column)
        if line is None or not cfg or not cfg.get("on"):
            return None
        x_data, y_data = line.get_data()
        if len(x_data) == 0:
            return None

        color = line.get_color() if cfg.get("follow") else cfg["color"]
        alpha = min(1.0, max(0.0, float(cfg.get("alpha", 0.35))))
        hatch = cfg.get("hatch") or None
        ax = line.axes if line.axes is not None else self.ax
        base = 0.0 if cfg.get("base", "zero") == "zero" else ax.get_ylim()[0]
        # the filled area is only a picture of the curve: it must not grow
        # the data limits, or a fill reaching the bottom of the axes would
        # push that bottom further down at every redraw
        limits = ax.dataLim.get_points().copy()
        ignoring = getattr(ax, "ignore_existing_data_limits", False)
        fill = ax.fill_between(
            x_data, y_data, base,
            facecolor=to_rgba(color, alpha),
            edgecolor=to_rgba(color, 1.0) if hatch else "none",
            hatch=hatch, linewidth=0.0, label="_nolegend_",
            zorder=line.get_zorder() - 0.5)
        # fill_between() asks the axes to grow its limits around the new
        # polygon, and matplotlib does that lazily - so putting dataLim back
        # is not enough on its own.  Hanging the very same collection back
        # with autolim=False takes it out of the calculation for good.
        try:
            fill.remove()
            ax.add_collection(fill, autolim=False)
        except (AttributeError, ValueError):
            pass
        try:
            ax.dataLim.set_points(limits)
            ax.ignore_existing_data_limits = ignoring
        except (AttributeError, ValueError):
            pass
        # it belongs to that curve: it is moved with it in the stack
        fill.aplot_series = str(column)
        self.fills[column] = fill
        return fill

    def refresh_fills(self):
        for column in list(self.series):
            self.refresh_fill(column)

    def rename_series(self, old, new, is_x_column=False):
        """Follow a column rename in the spreadsheet.

        Legend texts and the X axis label are only changed when they still
        carry the automatic (column) name - custom texts are kept.
        """
        if is_x_column:
            if self.ax.get_xlabel() == old:
                self.ax.set_xlabel(new)
                self.ax.xaxis.label.set_picker(True)
            if getattr(self, "_auto_x_label", None) == old:
                self._auto_x_label = str(new)
            self.x_col = new
            if old not in self.series:
                self.draw()          # that column is only an X axis
                return
            # a histogram, or a single filled column, draws it as a curve
            # as well: it has to be renamed like any other curve
        line = self.series.get(old)
        if line is None:
            return
        # rebuild dictionaries so that the column order is kept
        self.series = {(new if key == old else key): value
                       for key, value in self.series.items()}
        self.series_axis = {(new if key == old else key): value
                            for key, value in self.series_axis.items()}
        self.legend_state = {(new if key == old else key): value
                             for key, value in self.legend_state.items()}
        self.fill_state = {(new if key == old else key): value
                           for key, value in self.fill_state.items()}
        self.fills = {(new if key == old else key): value
                      for key, value in self.fills.items()}
        if old in self.series_style:
            self.series_style[new] = self.series_style.pop(old)
        if old in self.bar_cfg:
            self.bar_cfg[new] = self.bar_cfg.pop(old)
        if old in self.error_cfg:
            self.error_cfg[new] = self.error_cfg.pop(old)
        for store in (self.histogram_cfg, self.stairs_cfg,
                      self.hist2d_cfg, self.pie_cfg, self.stairs_patches,
                      self.hist2d_meshes, self.hist2d_bars,
                      self.pie_wedges, self.pie_texts):
            if old in store:
                store[new] = store.pop(old)
        if old in self.bar_containers:
            self.bar_containers[new] = self.bar_containers.pop(old)
        if f"hist_{old}" in self.bar_containers:
            self.bar_containers[f"hist_{new}"] = \
                self.bar_containers.pop(f"hist_{old}")
        if old in self.histogram_edges:
            self.histogram_edges[new] = self.histogram_edges.pop(old)
        if old in self.histogram_drawn:
            self.histogram_drawn.discard(old)
            self.histogram_drawn.add(new)
        if old in self.errorbar_containers:
            self.errorbar_containers[new] = self.errorbar_containers.pop(old)
        if line.get_label() == getattr(line, "aplot_series", None):
            line.set_label(str(new))
        line.aplot_series = str(new)
        self.refresh_legend()
        self.draw()

    def curve_columns(self, columns):
        """Which columns become curves, and where their error bars come from.

        Every diagram reads the **first** column as the X axis and the
        second one as the values of the first curve.  An **error bar**
        diagram reads the columns in pairs after that: `x`, mean, std,
        mean, std, ... - so the third column is the length of the error bar
        of the second one, the fifth belongs to the fourth, and so on.  In
        every other kind of diagram each column after the first one is a
        curve of its own.

        A **histogram** is the exception: it counts the values of a column
        by itself and needs nothing else, so *every* column - the first one
        included - is a sample and a curve of its own.

        A table whose **first column is the only filled one** is the other
        exception: there is no X column to read, so that column is the one
        and only curve and the X axis becomes the row number.
        """
        columns = [str(one) for one in columns]
        if self.plot_style == "histogram":
            return columns, {}, {}
        if self.plot_style == "pie":
            # one pie fills the whole plot area, so exactly one column is
            # drawn: the first one that holds numbers.  The first column of
            # the table names the slices, unless it is the only one there is.
            candidates = columns[1:] or columns[:1]
            for name in candidates:
                if self.has_numbers(self.df, name):
                    return [name], {}, {}
            return candidates[:1], {}, {}
        if self.row_numbers_mode():
            return columns[:1], {}, {}
        if len(columns) < 2:
            return [], {}, {}
        rest = columns[1:]
        if self.plot_style not in ERROR_STYLES:
            return rest, {}, {}
        # one error column per curve, or two of them: upwards and downwards.
        #
        # An **empty** column never begins a group.  A sheet nearly always
        # carries a few blank columns at its end, and once a fitted curve
        # has been glued to that sheet they stand between the measurements
        # and the fit: counting them as curves would shift every group from
        # there on and swallow the fitted column as somebody's error bars -
        # which is how a fitted curve comes to be missing from a diagram.
        # A column of error bars is taken as it stands, full or empty: it
        # belongs to the curve before it wherever it is.
        step = 3 if self.plot_style == "errorbar_pm" else 2
        curves, partner, lower = [], {}, {}
        index = 0
        while index < len(rest):
            mean = rest[index]
            if not self.has_numbers(self.df, mean):
                index += 1          # nothing is drawn there: not a curve
                continue
            curves.append(mean)
            if index + 1 < len(rest):
                partner[mean] = rest[index + 1]
            if step == 3 and index + 2 < len(rest):
                lower[mean] = rest[index + 2]
            index += step
        return curves, partner, lower

    def _plot_data(self, _plot_cfg=None):
        columns = list(self.df.columns)
        if not columns:
            return 0
        x_col = columns[0]
        sides = self.layout.get("y", {})
        curves, partner, lower = self.curve_columns(columns)
        self.error_partner = dict(partner)
        self.error_partner_low = dict(lower)
        for y_col in curves:
            x, y = self.series_points(self.df, x_col, y_col,
                                      style=self.plot_style)
            if len(x) and bool(np.isfinite(y).any()):
                self._create_line(x, y, y_col, x_col,
                                  sides.get(str(y_col), "left"),
                                  style=self.plot_style)
        return len(self.lines)

    def remove_series(self, column):
        """Take one curve out of the diagram with everything that belongs to it."""
        line = self.series.pop(column, None)
        if line is None:
            return False
        if line in self.lines:
            self.lines.remove(line)
        dialog = self._dialogs.pop(id(line), None)
        if dialog is not None and dialog.winfo_exists():
            dialog.destroy()
        self.clear_extras(column)
        self.series_style.pop(column, None)
        self.bar_cfg.pop(column, None)
        self.error_cfg.pop(column, None)
        self.histogram_cfg.pop(column, None)
        self.stairs_cfg.pop(column, None)
        self.hist2d_cfg.pop(column, None)
        self.pie_cfg.pop(column, None)
        self.histogram_edges.pop(column, None)
        self.histogram_drawn.discard(column)
        fill = self.fills.pop(column, None)
        if fill is not None:
            fill.remove()
        self.fill_state.pop(column, None)
        legend = self.legends.pop(column, None)
        if legend is not None:
            legend.remove()
        self.legend_state.pop(column, None)
        self.series_axis.pop(column, None)
        line.remove()
        return True

    def update_data(self, df, layout=None):
        """Replace the plotted values but keep every style setting.

        Curves are matched by column name: existing ones only get new data,
        a new column becomes a new curve, a deleted column disappears.  The
        layout says which axis every column belongs to now, so moving a tick
        from `y_L` to `y_R` in the table moves that curve to the other side.
        """
        columns = list(df.columns)
        # one column on its own is enough: a histogram counts it, and every
        # other diagram draws it against the row numbers
        if not columns:
            return False
        self.df = df
        x_col = columns[0]
        self.x_col = x_col
        if layout is not None:
            self.layout = self._clean_layout(df, layout)
            self.x_side = self.layout["x_side"]
        sides = self.layout.get("y", {})
        curves, partner, lower = self.curve_columns(columns)
        self.error_partner = dict(partner)
        self.error_partner_low = dict(lower)

        for y_col in curves:
            x, y = self.series_points(df, x_col, y_col)
            side = sides.get(str(y_col), self.series_side(y_col))
            line = self.series.get(y_col)
            if line is None:
                # an empty column gets no curve (and no legend box) yet -
                # it becomes one as soon as a value is typed into it
                if len(x) and bool(np.isfinite(y).any()):
                    self._create_line(x, y, y_col, x_col, side)
            else:
                line.set_data(x, y)
                self.move_series(y_col, side)
                self.refresh_series_visuals(y_col)

        for y_col in [name for name in self.series if name not in curves]:
            self.remove_series(y_col)

        # the curves follow the order of the columns, so a column that is
        # ticked again comes back in its own place and not at the end
        order = [name for name in curves if name in self.series]
        self.series = {name: self.series[name] for name in order}
        self.series_axis = {name: self.series_axis[name] for name in order
                            if name in self.series_axis}

        self._refresh_x_label()  # a second filled column ends the row numbers
        self.apply_style_axes()  # the axes follow the styles that are drawn
        self._rescale()          # manual ranges are left untouched
        self.apply_frame(self.frame_cfg, redraw=False)
        self.refresh_fills()
        self.refresh_legend()
        self.draw()
        return True

    def _refresh_x_label(self):
        """Follow what the X axis carries, as long as it was never renamed.

        The name of the first column and the word "Row" swap places when a
        second column is filled (or emptied).  A label the user has written
        himself is never touched.
        """
        wanted = self.x_axis_name()
        remembered = getattr(self, "_auto_x_label", wanted)
        if wanted == remembered:
            return False
        automatic = str(self.axis_label("x")) == remembered
        self._auto_x_label = wanted
        if not automatic:
            return False            # it carries a text of its own now
        self.apply_axis("x", {**self.axis_cfg["x"], "label": wanted},
                        redraw=False)
        return True

    # -- the diagram as a matplotlib program -------------------------------
    @staticmethod
    def _literal(value):
        """One value as Python source."""
        if isinstance(value, (np.floating, float)):
            value = float(value)
            if not math.isfinite(value):
                return f"float({str(value)!r})"    # nan / inf / -inf
            return repr(round(value, 6))
        if isinstance(value, (np.integer, int)) and not isinstance(value, bool):
            return repr(int(value))
        if isinstance(value, (list, tuple)):
            return "[" + ", ".join(PlotWindow._literal(one) for one in value) + "]"
        if isinstance(value, np.ndarray):
            return PlotWindow._literal([float(one) for one in value])
        return repr(value)

    def _script_data(self):
        """The plotted columns as plain Python lists."""
        lines = ["DATA = {"]
        columns = []
        for name in [self.x_col] + list(self.series):
            if name not in columns:     # a histogram counts the X column too
                columns.append(name)
        for mean, std in self.error_partner.items():      # the error columns
            if std not in columns:
                columns.append(std)
        for name in list(self.series):     # ... the ones only implied by it
            if self.series_style.get(name, self.plot_style) not in ERROR_STYLES:
                continue
            for partner in (self.partner_column(name),
                            self.partner_low_column(name)):
                if partner is not None and partner not in columns:
                    columns.append(partner)
        for cfg in self.error_cfg.values():
            name = str(cfg.get("column", ""))
            if name and name not in columns:
                columns.append(name)
        for name in columns:
            if name not in self.df.columns:
                continue
            values = pd.to_numeric(self.df[name], errors="coerce").to_numpy(float)
            numbers = ", ".join("float('nan')" if not np.isfinite(one)
                                else repr(round(float(one), 10))
                                for one in values)
            lines.append(f"    {name!r}: [{numbers}],")
        lines.append("}")
        if self.x_is_rows() and columns:
            # a table with no X column is drawn against the row numbers
            lines.append("")
            lines.append("# the X values: the row numbers of the table")
            lines.append("ROWS = np.arange(1, len(DATA[%r]) + 1, dtype=float)"
                         % str(columns[0]))
        return lines

    def to_script(self):
        """A stand-alone matplotlib program that draws this very diagram."""
        lit = self._literal
        cfg = self.frame_cfg
        dpi = float(self.base_dpi)        # the page, not the zoomed view
        out = [
            '"""Diagram exported from ' + APP_NAME + '.',
            "",
            "Run it with:   python3 this_file.py",
            "It needs numpy and matplotlib and nothing else - the data is",
            "written into the file, so it runs anywhere.",
            '"""',
            "import base64",
            "import io",
            "import math",
            "import numpy as np",
            "import matplotlib.pyplot as plt",
            "from matplotlib.legend import Legend",
            "from matplotlib.image import BboxImage",
            "from matplotlib.patches import Ellipse, Polygon, Rectangle",
            "from matplotlib.ticker import (AutoMinorLocator, FuncFormatter,",
            "                               LogFormatterSciNotation, LogLocator,",
            "                               MultipleLocator, NullFormatter,",
            "                               NullLocator)",
            "from matplotlib.transforms import (Affine2D, Bbox, ScaledTranslation,",
            "                                   TransformedBbox)",
            "",
        ]
        out += self._script_data()
        family = self.font_family()
        if family:
            out += ["", "# the font of every text of the diagram",
                    f"plt.rcParams[\"font.family\"] = [{lit(family)}]"]
        out += [
            "",
            f"DPI = {lit(dpi)}",
            "PT = 72.0 / DPI          # the distances are given in pixels",
            "",
            "",
            "def in_front(artist, z):",
            '    """Put one curve - with everything drawn for it - at height z."""',
            "    parts = artist if isinstance(artist, (list, tuple)) else [artist]",
            "    for part in parts:",
            "        for one in (part if isinstance(part, (list, tuple)) else [part]):",
            "            if hasattr(one, 'set_zorder'):",
            "                one.set_zorder(z)",
            "",
            "",
            "def turned(ax, centre, angle):",
            '    """The plot area, turned by `angle` degrees around a point."""',
            "    if not angle:",
            "        return ax.transAxes",
            "    px, py = ax.transAxes.transform(centre)",
            "    return ax.transAxes + Affine2D().rotate_deg_around(",
            "        float(px), float(py), float(angle))",
            "",
            "",
            "def e_power_text(value, _pos=None):",
            '    """One number of a natural logarithmic axis, as a power of e."""',
            "    value = float(value)",
            "    if value <= 0 or not math.isfinite(value):",
            "        return \"\"",
            "    power = math.log(value)",
            "    whole = round(power)",
            "    if abs(power - whole) < 1e-6:",
            "        return r\"$\\mathdefault{e^{%d}}$\" % int(whole)",
            "    return r\"$\\mathdefault{e^{%.2f}}$\" % power",
            "",
            "",
            "fig = plt.figure(figsize=("
            f"{lit(round(self.page_size[0], 4))} / 2.54, "
            f"{lit(round(self.page_size[1], 4))} / 2.54), dpi=DPI)",
        ]
        figure_bg = cfg.get("figure_background", "#ffffff")
        out.append("fig.set_facecolor(%s)" % lit("none" if figure_bg == "none"
                                                 else figure_bg))
        out += [
            "ax = fig.add_subplot(111)",
            "ax.set_position([%s, %s, %s, %s])" % (
                lit(cfg["left"]), lit(cfg["bottom"]),
                lit(cfg["x_length"]), lit(cfg["y_length"])),
            "ax.set_facecolor(%s)" % lit(cfg.get("background", "#ffffff")),
        ]
        out += self._script_axes()
        out += self._script_curves()
        out += self._script_texts()
        out += self._script_objects()
        out += [
            "",
            "# fig.savefig(\"diagram.png\", dpi=300, bbox_inches=\"tight\")",
            "plt.show()",
            "",
        ]
        return "\n".join(out)

    def _script_axes(self):
        """Frame, ticks, ranges, grid - for every axis that is in use."""
        lit = self._literal
        cfg = self.frame_cfg
        style = cfg.get("style", "none")
        both = style in ("box_in", "box_out")
        top = self.x_side == "top"
        right = self.right_axis_active()
        left = self.left_axis_shown()
        used = self.used_sides()
        out = ["", "# ---------------------------------------------- the frame"]
        for name in ("left", "right", "top", "bottom"):
            visible = style != "none" or name in used
            out.append("ax.spines[%s].set_visible(%s)" % (lit(name), visible))
            if visible:
                out.append("ax.spines[%s].set_linewidth(%s)"
                           % (lit(name), lit(cfg["width"])))
                out.append("ax.spines[%s].set_color(%s)"
                           % (lit(name), lit(self.axis_color(
                               self.spine_owner(name)))))
                out.append("ax.spines[%s].set_zorder(%s)"
                           % (lit(name), lit(float(
                               self.object_z("axis", self.spine_owner(name))
                               or Z_DEFAULT["axis"]))))
        out.append("ax.tick_params(which='both', width=%s, direction=%s)"
                   % (lit(cfg["width"]),
                      lit("in" if style == "box_in" else "out")))
        out.append("ax.tick_params(which='major', length=%s)"
                   % lit(cfg["major_tick_length"]))
        out.append("ax.tick_params(which='minor', length=%s)"
                   % lit(cfg["minor_tick_length"]))
        # the ticks, the numbers and the label of an axis stand at its own
        # height, exactly as they do on the screen
        for which, artist in (("x", "ax.xaxis"), ("y", "ax.yaxis")):
            out.append("%s.set_zorder(%s)"
                       % (artist, lit(float(self.object_z("axis", which)
                                            or Z_DEFAULT["axis"]))))

        for which in ("x", "y", "y2"):
            if which == "y2" and not right:
                continue
            axis_cfg = self.axis_cfg[which]
            name = {"x": "ax", "y": "ax", "y2": "ax2"}[which]
            if which == "y2":
                # which of the two axes is drawn last is what decides
                # whether a drawing can stand over a curve of the other one
                top = getattr(self, "_top_side", "right")
                out += ["", "ax2 = ax.twinx()",
                        "ax.set_zorder(%s)" % lit(0.0 if top == "right" else 1.0),
                        "ax2.set_zorder(%s)" % lit(1.0 if top == "right" else 0.0),
                        "ax.patch.set_visible(%s)" % (top == "right"),
                        "ax2.patch.set_visible(%s)" % (top != "right"),
                        "ax2.set_facecolor(%s)"
                        % lit((self.frame_cfg or {}).get("background",
                                                         "#ffffff")),
                        "for spine in ax2.spines.values():",
                        "    spine.set_visible(False)",
                        "ax2.tick_params(which='both', width=%s, direction=%s)"
                        % (lit(cfg["width"]),
                           lit("in" if style == "box_in" else "out")),
                        "ax2.tick_params(which='major', length=%s)"
                        % lit(cfg["major_tick_length"]),
                        "ax2.tick_params(which='minor', length=%s)"
                        % lit(cfg["minor_tick_length"])]
            out.append("")
            out.append(f"# ---------------------------------- the "
                       f"{AXIS_NAMES.get(which, which)}")
            setter = {"x": "set_xlabel", "y": "set_ylabel",
                      "y2": "set_ylabel"}[which]
            out.append("%s.%s(%s, fontsize=%s, color=%s, labelpad=%s * PT)"
                       % (name, setter, lit(self.axis_label(which)),
                          lit(axis_cfg["label_size"]),
                          lit(axis_cfg["label_color"]),
                          lit(axis_cfg["label_pad"])))
            if not axis_cfg.get("label_on", True):
                out.append("%s.%saxis.label.set_visible(False)"
                           % (name, "x" if which == "x" else "y"))
            axis_name = "x" if which == "x" else "y"
            ticks_on = bool(axis_cfg.get("ticks_on", True))
            tick_labels_on = ticks_on and bool(axis_cfg.get("tick_labels_on", True))
            # the numbers are spread linearly or logarithmically
            scale = self.axis_scale(which)
            if scale != "linear":
                out.append("%s.set_%sscale('log', base=%s)"
                           % (name, axis_name, lit(LOG_BASES[scale])))
            out.append("%s.tick_params(axis=%s, which='both', labelsize=%s, "
                       "labelcolor=%s, pad=%s * PT, color=%s)"
                       % (name, lit(axis_name), lit(axis_cfg["tick_size"]),
                          lit(axis_cfg["tick_color"]), lit(axis_cfg["tick_pad"]),
                          lit(self.axis_color(which))))
            if which == "x":
                if not self.axis_shown("x"):
                    out.append("ax.xaxis.set_visible(False)")
                out.append("ax.xaxis.set_ticks_position(%s)"
                           % lit("top" if top else "bottom"))
                out.append("ax.xaxis.set_label_position(%s)"
                           % lit("top" if top else "bottom"))
                out.append("ax.tick_params(axis='x', which='both', top=%s, "
                           "bottom=%s, labeltop=%s, labelbottom=%s)"
                           % ((both or top) and ticks_on,
                              (both or not top) and ticks_on,
                              top and tick_labels_on, (not top) and tick_labels_on))
            elif which == "y":
                out.append("ax.yaxis.set_visible(%s)" % left)
                out.append("ax.tick_params(axis='y', which='both', left=%s, "
                           "right=%s, labelleft=%s, labelright=False)"
                           % ((left or both) and ticks_on,
                              (both and not right) and ticks_on,
                              left and tick_labels_on))
            else:
                out.append("ax2.yaxis.set_ticks_position('right')")
                out.append("ax2.yaxis.set_label_position('right')")
                out.append("ax2.tick_params(axis='y', which='both', left=False, "
                           "right=%s, labelleft=False, labelright=%s)"
                           % (ticks_on, tick_labels_on))
            # the limits are read as they stand: a reversed axis already
            # hands them over the other way round
            low, high = self.current_limits(which)
            out.append("%s.set_%slim(%s, %s)"
                       % (name, axis_name, lit(float(low)), lit(float(high))))
            step = axis_cfg.get("step")
            minor = int(axis_cfg.get("minor", 0) or 0)
            if scale != "linear":
                # on a logarithmic axis the step counts decades and the
                # minor ticks stand on the whole numbers inside one
                log_base = self.log_major_base(LOG_BASES.get(scale, 10.0),
                                               step, (low, high))
                out.append("%s.%saxis.set_major_locator(LogLocator("
                           "base=%s, subs=(1.0,), numticks=%s))"
                           % (name, axis_name, lit(float(log_base)),
                              lit(int(LOG_TICK_LIMIT))))
                subs = self.log_minor_subs(log_base, minor)
                if subs:
                    out.append("%s.%saxis.set_minor_locator(LogLocator("
                               "base=%s, subs=%s, numticks=%s))"
                               % (name, axis_name, lit(float(log_base)),
                                  "(" + ", ".join(lit(float(one))
                                                  for one in subs) + ",)",
                                  lit(int(LOG_TICK_LIMIT))))
                else:
                    out.append("%s.%saxis.set_minor_locator(NullLocator())"
                               % (name, axis_name))
                out.append("%s.%saxis.set_minor_formatter(NullFormatter())"
                           % (name, axis_name))
                if scale == "ln":      # read in powers of e, not in numbers
                    out.append("%s.%saxis.set_major_formatter("
                               "FuncFormatter(e_power_text))"
                               % (name, axis_name))
                else:
                    out.append("%s.%saxis.set_major_formatter("
                               "LogFormatterSciNotation(base=%s))"
                               % (name, axis_name,
                                  lit(float(LOG_BASES.get(scale, 10.0)))))
            else:
                if not axis_cfg.get("auto", True) and step:
                    out.append("%s.%saxis.set_major_locator(MultipleLocator(%s))"
                               % (name, axis_name, lit(float(step))))
                out.append("%s.%saxis.set_minor_locator(%s)"
                           % (name, axis_name,
                              f"AutoMinorLocator({minor + 1})" if minor
                              else "NullLocator()"))
            grid = axis_cfg["grid"]
            owner = (which == "x") or (which == ("y" if left else "y2"))
            for kind, on, factor in (("major", grid["major"], 1.0),
                                     ("minor", grid["minor"] and minor, 0.6)):
                if owner and on:
                    out.append("%s.grid(True, which=%s, axis=%s, color=%s, "
                               "linestyle=%s, linewidth=%s)"
                               % (name, lit(kind), lit(axis_name),
                                  lit(grid["color"]), lit(grid["style"]),
                                  lit(max(0.3, grid["width"] * factor))))
                else:
                    out.append("%s.grid(False, which=%s, axis=%s)"
                               % (name, lit(kind), lit(axis_name)))
        return out

    def _script_curves(self):
        """The curves, their filled areas and their legend boxes."""
        lit = self._literal
        out = ["", "# ---------------------------------------------- the curves",
               "curves = {}"]
        # with no X column of its own the X values are the row numbers
        x_data = ("ROWS" if self.x_is_rows()
                  else f"DATA[{lit(str(self.x_col))}]")
        for number, (column, line) in enumerate(self.series.items(), start=1):
            target = "ax2" if self.series_side(column) == "right" else "ax"
            st = self.series_style.get(column, self.plot_style)
            # a column name may be anything at all, so the helper variables
            # are numbered instead of being named after it
            tag = f"s{number}"
            if st == "bar":
                b_cfg = self.bar_cfg.get(column, {})
                bw = float(b_cfg.get("width", 0.8))
                ba = float(b_cfg.get("alpha", 0.85))
                bc = store_color(b_cfg.get("color", line.get_color()))
                bec = store_color(b_cfg.get("edgecolor", line.get_color()))
                bew = float(b_cfg.get("edgewidth", 1.0))
                out.append(
                    f"bars_{tag} = {target}.bar({x_data}, "
                    f"DATA[{lit(str(column))}], "
                    f"width={bw}, color={lit(bc)}, edgecolor={lit(bec)}, "
                    f"linewidth={bew}, alpha={ba}, "
                    f"label={lit(str(line.get_label()))})"
                )
                out.append(f"curves[{lit(str(column))}] = bars_{tag}[0]")
            elif st in ERROR_STYLES:
                e_cfg = self.error_cfg.get(column, {})
                err_type = e_cfg.get("type", "percent")
                err_val = float(e_cfg.get("value", 5.0))
                capsize = float(e_cfg.get("capsize", 4.0))
                capthick = float(e_cfg.get("capthick", 1.5))
                elinewidth = float(e_cfg.get("elinewidth", 1.5))
                ec = store_color(e_cfg.get("color", line.get_color()))
                values = f"np.asarray(DATA[{lit(str(column))}], float)"
                partner = self.partner_column(column)
                lower = self.partner_low_column(column)
                if (err_type == "pair" and st == "errorbar_pm"
                        and partner in self.df.columns
                        and lower in self.df.columns):
                    # two columns beside this one: the error upwards and the
                    # error downwards, which matplotlib takes as [down, up]
                    out.append(f"yerr_{tag} = np.vstack(["
                               f"np.abs(np.asarray(DATA[{lit(str(lower))}], float)), "
                               f"np.abs(np.asarray(DATA[{lit(str(partner))}], float))])")
                elif err_type == "pair" and partner in self.df.columns:
                    # the column beside this one holds the standard deviation
                    out.append(f"yerr_{tag} = np.abs(np.asarray("
                               f"DATA[{lit(str(partner))}], float))")
                elif err_type == "fixed":
                    out.append(f"yerr_{tag} = np.full_like({values}, {err_val})")
                elif err_type == "std":
                    out.append(f"yerr_{tag} = np.full_like({values}, "
                               f"np.nanstd({values}))")
                elif err_type == "column" and e_cfg.get("column") in self.df.columns:
                    out.append(f"yerr_{tag} = np.abs(np.asarray("
                               f"DATA[{lit(str(e_cfg['column']))}], float))")
                elif err_type == "percent":
                    out.append(f"yerr_{tag} = np.abs({values} * "
                               f"{err_val / 100.0})")
                else:
                    out.append(f"yerr_{tag} = np.abs({values} * 0.05)")
                out.append(
                    f"bars_{tag} = {target}.errorbar("
                    f"{x_data}, DATA[{lit(str(column))}], "
                    f"yerr=yerr_{tag}, "
                    f"color={lit(ec)}, fmt={lit(str(line.get_marker()))}, "
                    f"markersize={float(line.get_markersize())}, "
                    f"capsize={capsize}, capthick={capthick}, "
                    f"elinewidth={elinewidth}, "
                    f"label={lit(str(line.get_label()))})"
                )
                out.append(f"curves[{lit(str(column))}] = bars_{tag}")
            elif st == "stairs":
                s_cfg = self.stairs_cfg.get(column, {})
                s_filled = bool(s_cfg.get("fill"))
                s_color = store_color(s_cfg.get("color", line.get_color()))
                s_base = (0.0 if (s_filled or s_cfg.get("baseline")) else None)
                s_x, s_y = self.stairs_points(column)
                edges = self.stairs_edges(s_x, s_cfg.get("edges", "mid"))
                if len(edges) != len(s_y) + 1:
                    # nothing to stand a step on: an empty staircase draws
                    # nothing and still gives the legend its sample
                    s_y = np.array([np.nan])
                    edges = np.array([0.0, 1.0])
                out.append(f"edges_{tag} = {lit(edges)}")
                out.append(f"vals_{tag} = {lit(s_y)}")
                out.append(
                    f"bars_{tag} = {target}.stairs(vals_{tag}, "
                    f"edges_{tag}, baseline={lit(s_base)}, fill={s_filled}, "
                    f"color={lit(s_color)}, "
                    f"linewidth={float(s_cfg.get('width', 1.8))}, "
                    f"hatch={lit(s_cfg.get('hatch') or None)}, "
                    f"label={lit(str(line.get_label()))})"
                )
                if s_filled:
                    face = list(to_rgba(s_color,
                                        float(s_cfg.get("alpha", 0.35))))
                    out.append(f"bars_{tag}.set_alpha(None)")
                    out.append(f"bars_{tag}.set_facecolor({lit(face)})")
                    out.append(f"bars_{tag}.set_edgecolor({lit(s_color)})")
                out.append(f"curves[{lit(str(column))}] = bars_{tag}")
            elif st == "hist2d":
                g_cfg = self.hist2d_cfg.get(column, {})
                out.append(f"gx_{tag} = np.asarray({x_data}, float)")
                out.append(f"gy_{tag} = np.asarray("
                           f"DATA[{lit(str(column))}], float)")
                out.append(f"ok_{tag} = np.isfinite(gx_{tag}) "
                           f"& np.isfinite(gy_{tag})")
                out.append(
                    f"_counts, _xe, _ye, mesh_{tag} = {target}.hist2d("
                    f"gx_{tag}[ok_{tag}], gy_{tag}[ok_{tag}], "
                    f"bins=[{self.hist2d_bins(column, 'xbins')}, "
                    f"{self.hist2d_bins(column, 'ybins')}], "
                    f"cmap={lit(str(g_cfg.get('cmap', 'viridis')))}, "
                    f"alpha={float(g_cfg.get('alpha', 1.0))}, "
                    f"cmin={lit(1 if g_cfg.get('hide_empty', True) else None)})"
                )
                out.append(f"curves[{lit(str(column))}] = mesh_{tag}")
                if g_cfg.get("colorbar"):
                    out.append(f"cax_{tag} = {target}.inset_axes("
                               f"[1.02, 0.0, 0.035, 1.0])")
                    out.append(f"fig.colorbar(mesh_{tag}, cax=cax_{tag})")
            elif st == "pie":
                p_cfg = self.pie_cfg.get(column, {})
                values, labels = self.pie_values(column)
                colors = [list(to_rgba(one)) for one in
                          self.slice_colors(p_cfg.get("cmap", "tab10"),
                                            len(values))]
                hole = max(0.0, min(float(p_cfg.get("hole", 0.0) or 0.0), 0.95))
                explode = float(p_cfg.get("explode", 0.0) or 0.0)
                percent = (f"%.{max(0, int(p_cfg.get('decimals', 1)))}f%%"
                           if p_cfg.get("percent") else None)
                n_size, n_color = self.pie_text_style(p_cfg, "name")
                p_size, p_color = self.pie_text_style(p_cfg, "pct")
                out.append(f"vals_{tag} = {lit(values)}")
                out.append(
                    f"bars_{tag} = {target}.pie(vals_{tag}, "
                    f"labels={lit(labels or None)}, colors={lit(colors)}, "
                    f"startangle={float(p_cfg.get('start', PIE_START_ANGLE))}, "
                    f"counterclock={bool(p_cfg.get('clockwise', True))}, "
                    f"autopct={lit(percent)}, "
                    f"labeldistance="
                    f"{float(p_cfg.get('labeldistance', PIE_LABEL_DISTANCE))}, "
                    f"pctdistance="
                    f"{float(p_cfg.get('pctdistance', PIE_PCT_DISTANCE))}, "
                    f"rotatelabels={bool(p_cfg.get('rotate_labels', False))}, "
                    f"explode={lit(([explode] + [0.0] * (len(values) - 1)) if explode else None)}, "
                    f"textprops={{'fontsize': {n_size}}}, "
                    f"wedgeprops={{'width': {lit((1.0 - hole) if hole else None)}, "
                    f"'edgecolor': {lit(store_color(p_cfg.get('edgecolor', '#ffffff')))}, "
                    f"'linewidth': {float(p_cfg.get('edgewidth', 1.0))}}})"
                )
                out.append(f"for txt_{tag} in bars_{tag}[1]:")
                out.append(f"    txt_{tag}.set_color({lit(store_color(n_color))})")
                if p_cfg.get("percent"):
                    out.append(f"for txt_{tag} in bars_{tag}[2]:")
                    out.append(f"    txt_{tag}.set_fontsize({p_size})")
                    out.append(
                        f"    txt_{tag}.set_color({lit(store_color(p_color))})")
                if p_cfg.get("percent") and p_cfg.get("rotate_numbers"):
                    out.append(
                        f"for txt_{tag}, wdg_{tag} in zip(bars_{tag}[2], "
                        f"bars_{tag}[0]):")
                    out.append(
                        f"    mid_{tag} = math.radians("
                        f"(wdg_{tag}.theta1 + wdg_{tag}.theta2) / 2.0)")
                    out.append(
                        f"    txt_{tag}.set_rotation(math.degrees(mid_{tag}) "
                        f"+ (0 if math.cos(mid_{tag}) >= 0 else 180))")
                    out.append(f"    txt_{tag}.set_rotation_mode('anchor')")
                    out.append(f"    txt_{tag}.set_ha('center')")
                    out.append(f"    txt_{tag}.set_va('center')")
                out.append(f"bars_{tag} = bars_{tag}[0]")
                if self.only_pies():     # a pie alone owns the whole area
                    out.append(f"{target}.set_aspect('equal')")
                else:
                    # ax.pie() switched the frame off: the curve beside the
                    # pie needs its axes back
                    out.append(f"{target}.set_frame_on(True)")
                out.append(f"curves[{lit(str(column))}] = bars_{tag}[0]")
            elif st == "histogram":
                h_cfg = self.histogram_cfg.get(column, {})
                h_alpha = float(h_cfg.get("alpha", 0.85))
                h_color = store_color(h_cfg.get("color", line.get_color()))
                h_edge = store_color(h_cfg.get("edgecolor", "#ffffff"))
                h_width = float(h_cfg.get("edgewidth", 1.0))
                bins = self.histogram_bins(column)
                # the column holds raw values: matplotlib counts them itself
                out.append(f"sample_{tag} = np.asarray("
                           f"DATA[{lit(str(column))}], float)")
                out.append(f"sample_{tag} = sample_{tag}"
                           f"[np.isfinite(sample_{tag})]")
                out.append(
                    f"counts_{tag}, edges_{tag}, bars_{tag} = {target}.hist("
                    f"sample_{tag}, bins={bins}, "
                    f"color={lit(h_color)}, edgecolor={lit(h_edge)}, "
                    f"linewidth={h_width}, alpha={h_alpha}, "
                    f"label={lit(str(line.get_label()))})"
                )
                out.append(f"curves[{lit(str(column))}] = bars_{tag}[0]")
            else:
                out.append(
                    "curves[%s], = %s.plot(%s, DATA[%s], linestyle=%s, "
                    "linewidth=%s, color=%s, marker=%s, markersize=%s,"
                    % (lit(str(column)), target, x_data,
                       lit(str(column)), lit(str(line.get_linestyle())),
                       lit(float(line.get_linewidth())),
                       lit(store_color(line.get_color())),
                       lit(str(line.get_marker())),
                       lit(float(line.get_markersize()))))
                out.append(
                    "    markerfacecolor=%s, markeredgecolor=%s, "
                    "markeredgewidth=%s, label=%s)"
                    % (lit(store_color(line.get_markerfacecolor())),
                       lit(store_color(line.get_markeredgecolor())),
                       lit(float(line.get_markeredgewidth())),
                       lit(str(line.get_label()))))
            if not line.get_visible():
                out.append("curves[%s].set_visible(False)" % lit(str(column)))
            height = self.series_z.get(str(column))
            if height is not None:        # where the user put this curve
                out.append("in_front(%s, %s)"
                           % (("bars_%s" % tag) if st in STACK_CONTAINERS
                              else "curves[%s]" % lit(str(column)),
                              lit(float(height))))
            fill = self.fill_state.get(column) or {}
            if fill.get("on"):
                color = (store_color(line.get_color()) if fill.get("follow")
                         else fill.get("color", "#1f77b4"))
                base = ("0.0" if fill.get("base", "zero") == "zero"
                        else f"{target}.get_ylim()[0]")
                out.append(
                    "%s.fill_between(%s, DATA[%s], %s, facecolor=%s, "
                    "alpha=%s, hatch=%s, edgecolor=%s, linewidth=0.0, "
                    "label='_nolegend_', zorder=%s)"
                    % (target, x_data, lit(str(column)), base,
                       lit(color), lit(float(fill.get("alpha", 0.35))),
                       lit(fill.get("hatch") or None),
                       lit(color if fill.get("hatch") else "none"),
                       lit(self.fill_zorder(column, line))))
        if self.legend_visible and self.legends:
            out.append("")
            out.append("# every curve has a legend box of its own")
            for column in self.legends:
                state = self.legend_state.get(column) or {}
                line = self.series.get(column)
                if line is None:
                    continue
                edge = state.get("edge", "none")
                face = state.get("face", "none")
                if self.series_style.get(column,
                                         self.plot_style) == "pie":
                    # a pie box lists every slice, so the samples are the
                    # wedges themselves
                    tag = f"s{list(self.series).index(column) + 1}"
                    _handles, texts = self.legend_entries(column, line)
                    samples = f"list(bars_{tag})"
                    names = lit([str(one) for one in texts])
                else:
                    samples = "[curves[%s]]" % lit(str(column))
                    names = "[%s]" % lit(str(line.get_label()))
                out.append(
                    "legend = Legend(ax, %s, %s, loc=%s, "
                    "bbox_to_anchor=%s, bbox_transform=ax.transAxes, "
                    "prop={'size': %s}, framealpha=1.0)"
                    % (samples, names,
                       lit(state.get("loc", "upper right")),
                       lit([float(one) for one in state.get("pos", (0.5, 0.5))]),
                       lit(int(state.get("size", 10)))))
                out.append("for text in legend.get_texts():")
                out.append("    text.set_color(%s)"
                           % lit(state.get("color", "#000000")))
                out.append("legend.get_frame().set_edgecolor(%s)" % lit(edge))
                out.append("legend.get_frame().set_linewidth(%s)"
                           % lit(0.0 if edge == "none" else 0.8))
                out.append("legend.get_frame().set_facecolor(%s)" % lit(face))
                out.append("ax.add_artist(legend)")
        return out

    def _script_texts(self):
        """The title and the dragged places of the three axis texts."""
        lit = self._literal
        out = ["", "# ----------------------------------- the title and the texts",
               "ax.set_title(%s, fontsize=%s, color=%s, pad=%s * PT)"
               % (lit(self.ax.get_title()),
                  lit(float(self.ax.title.get_fontsize())),
                  lit(store_color(self.ax.title.get_color())),
                  lit(float(self.fonts["title_pad"])))]
        artists = {"title": "ax.title", "x": "ax.xaxis.label",
                   "y": "ax.yaxis.label", "y2": "ax2.yaxis.label"}
        for name, artist in artists.items():
            if name == "y2" and self.ax2 is None:
                continue
            dx, dy = self.text_offset.get(name, (0.0, 0.0))
            if not dx and not dy:
                continue
            dx, dy = float(dx), float(dy)          # points of the page
            if name == "title":
                out.append("ax._autotitlepos = False")
            out.append("%s.set_transform(%s.get_transform() + "
                       "ScaledTranslation(%s / 72, %s / 72, fig.dpi_scale_trans))"
                       % (artist, artist, lit(dx), lit(dy)))
        return out

    def script_host(self, kind, key):
        """"ax" or "ax2": the axes one object is drawn on in the script."""
        if not self.right_axis_active() or self.ax2 is None:
            return "ax"                    # the script builds no second axes
        return "ax2" if self.stack_side(kind, key) == "right" else "ax"

    def _script_objects(self):
        """The text boxes, the drawings and the arrows, as they are drawn."""
        lit = self._literal
        out = []
        if self.note_state:
            out += ["", "# ------------------------------------- the text boxes"]
        for key, state in self.note_state.items():
            host = self.script_host("note", key)
            edge, face = state.get("edge", "none"), state.get("face", "none")
            out.append(
                "%s.text(%s, %s, %s, transform=ax.transAxes, fontsize=%s, "
                "color=%s, ha='left', va='center', rotation=%s,"
                % (host, lit(float(state["pos"][0])), lit(float(state["pos"][1])),
                   lit(str(state["text"])), lit(int(state["size"])),
                   lit(state["color"]), lit(float(state.get("angle", 0.0) or 0.0))))
            out.append(
                "        rotation_mode='anchor', clip_on=False, zorder=%s,"
                % lit(float(state.get("z") or Z_DEFAULT["note"])))
            out.append(
                "        bbox={'boxstyle': 'round,pad=0.35', 'facecolor': %s, "
                "'edgecolor': %s, 'linewidth': %s})"
                % (lit(face), lit(edge), lit(0.0 if edge == "none" else 0.8)))

        if self.shape_state:
            out += ["", "# --------------------------------------- the drawings"]
        for key, state in self.shape_state.items():
            host = self.script_host("shape", key)
            kind = state["kind"]
            x, y = float(state["x"]), float(state["y"])
            w, h = float(state["w"]), float(state["h"])
            angle = self.angle_of(state)
            centre = self.shape_centre(state)
            face = state.get("face", "none")
            height = float(state.get("z") or Z_DEFAULT["shape"])
            common = ("transform=turned(ax, (%s, %s), %s), clip_on=False, "
                      "zorder=%s, edgecolor=%s, linestyle=%s, linewidth=%s, "
                      "facecolor=%s"
                      % (lit(centre[0]), lit(centre[1]), lit(angle), lit(height),
                         lit(state["edge"]), lit(state["style"]),
                         lit(float(state["width"])),
                         lit("none" if face == "none"
                             else to_hex(to_rgba(face, state.get("alpha", 0.6)),
                                         keep_alpha=True))))
            if kind == "line":
                ends = ([[x, y + h], [x + w, y]] if state.get("flip")
                        else [[x, y], [x + w, y + h]])
                out.append("%s.add_patch(Polygon(%s, closed=False, fill=False, %s))"
                           % (host, lit(ends), common))
            elif kind == "triangle":
                points = [[x + w / 2, y + h], [x, y], [x + w, y]]
                out.append("%s.add_patch(Polygon(%s, closed=True, %s))"
                           % (host, lit(points), common))
            elif kind in ("circle", "ellipse"):
                out.append("%s.add_patch(Ellipse((%s, %s), %s, %s, %s))"
                           % (host, lit(x + w / 2), lit(y + h / 2), lit(w),
                              lit(h), common))
            elif kind == PICTURE_KIND:
                # the picture itself travels with the program, in one line
                out.append("picture_%s = plt.imread(io.BytesIO(base64."
                           "b64decode(%s)), format='png')" % (key, lit(str(state.get("picture", "")))))
                out.append("box_%s = TransformedBbox(Bbox.from_bounds(%s, %s, "
                           "%s, %s), ax.transAxes)"
                           % (key, lit(x), lit(y), lit(w), lit(h)))
                out.append("art_%s = BboxImage(box_%s, "
                           "interpolation='antialiased', zorder=%s, alpha=%s)"
                           % (key, key, lit(height - Z_PICTURE_GAP),
                              lit(float(state.get("alpha", 1.0)))))
                out.append("art_%s.set_data(picture_%s)" % (key, key))
                out.append("art_%s.set_clip_on(False)" % key)
                out.append("%s.add_artist(art_%s)" % (host, key))
                if state.get("style", "none") != "none":
                    out.append("%s.add_patch(Rectangle((%s, %s), %s, %s, %s))"
                               % (host, lit(x), lit(y), lit(w), lit(h), common))
            else:
                out.append("%s.add_patch(Rectangle((%s, %s), %s, %s, %s))"
                           % (host, lit(x), lit(y), lit(w), lit(h), common))

        if self.arrow_state:
            out += ["", "# ----------------------------------------- the arrows"]
        for key, state in self.arrow_state.items():
            host = self.script_host("arrow", key)
            points, shaft_end = self._head_polygon(state)
            height = float(state.get("z") or Z_DEFAULT["arrow"])
            out.append(
                "%s.plot([%s, %s], [%s, %s], transform=ax.transAxes, color=%s, "
                "linestyle=%s, linewidth=%s, solid_capstyle='butt', "
                "clip_on=False, zorder=%s, label='_nolegend_')"
                % (host, lit(float(state["tail"][0])), lit(float(shaft_end[0])),
                   lit(float(state["tail"][1])), lit(float(shaft_end[1])),
                   lit(state["color"]), lit(state["style"]),
                   lit(float(state["width"])), lit(height)))
            if points is None:
                continue
            corners = [[float(one[0]), float(one[1])] for one in points]
            if state["head"] == "chevron":
                out.append(
                    "%s.plot(%s, %s, transform=ax.transAxes, color=%s, "
                    "linestyle='-', linewidth=%s, solid_joinstyle='miter', "
                    "clip_on=False, zorder=%s, label='_nolegend_')"
                    % (host, lit([one[0] for one in corners]),
                       lit([one[1] for one in corners]),
                       lit(state["color"]), lit(float(state["width"])),
                       lit(height)))
            else:
                out.append(
                    "%s.add_patch(Polygon(%s, closed=True, "
                    "transform=ax.transAxes, facecolor=%s, edgecolor=%s, "
                    "linewidth=%s, clip_on=False, zorder=%s))"
                    % (host, lit(corners), lit(state["color"]),
                       lit(state["color"]),
                       lit(max(0.2, float(state["width"]) * 0.5)), lit(height)))
        return out

    # -- saving / restoring the whole diagram ------------------------------
    def to_state(self):
        """Everything that makes this diagram look the way it looks."""
        axes = {}
        for which in ("x", "y", "y2"):
            if which == "y2" and self.ax2 is None:
                continue
            low, high = self.current_limits(which)
            cfg = self.axis_cfg[which]
            axes[which] = {
                "label": self.axis_label(which), "auto": cfg["auto"],
                "min": float(low), "max": float(high),
                "step": cfg["step"], "minor": cfg["minor"],
                "label_size": cfg["label_size"], "tick_size": cfg["tick_size"],
                "label_color": cfg["label_color"], "tick_color": cfg["tick_color"],
                "label_pad": cfg["label_pad"], "tick_pad": cfg["tick_pad"],
                "z": float(self.object_z("axis", which)
                           or cfg.get("z") or Z_DEFAULT["axis"]),
                "axis_color": self.axis_color(which),
                "label_on": bool(cfg.get("label_on", True)),
                "ticks_on": bool(cfg.get("ticks_on", True)),
                "tick_labels_on": bool(cfg.get("tick_labels_on", True)),
                "direction": self.axis_direction(which),
                "scale": self.axis_scale(which),
                "grid": dict(cfg["grid"]),
            }
        series = []
        for y_col, line in self.series.items():
            state = self.legend_state.get(y_col) or self.default_legend_state(0)
            series.append({
                "column": str(y_col), "label": line.get_label(),
                "axis": self.series_side(y_col),
                "plot_style": self.series_style.get(y_col, self.plot_style),
                "bar_cfg": dict(self.bar_cfg.get(y_col, {})),
                "error_cfg": dict(self.error_cfg.get(y_col, {})),
                "histogram_cfg": dict(self.histogram_cfg.get(y_col, {})),
                "stairs_cfg": dict(self.stairs_cfg.get(y_col, {})),
                "hist2d_cfg": dict(self.hist2d_cfg.get(y_col, {})),
                "pie_cfg": dict(self.pie_cfg.get(y_col, {})),
                "legend_pos": [float(state["pos"][0]), float(state["pos"][1])],
                "legend_loc": state["loc"], "legend_size": int(state["size"]),
                "legend_color": safe_hex(state.get("color", "#000000"), "#000000"),
                "legend_edge": state.get("edge", "#000000"),
                "legend_face": state.get("face", "#ffffff"),
                "fill": dict(self.fill_state.get(y_col)
                             or self.default_fill_state(self.settings.section("plot"))),
                "auto_label": line.get_label() == getattr(line, "aplot_series", None),
                "color": store_color(line.get_color()),
                "linestyle": str(line.get_linestyle()),
                "linewidth": float(line.get_linewidth()),
                "marker": str(line.get_marker()),
                "markersize": float(line.get_markersize()),
                "markerfacecolor": store_color(line.get_markerfacecolor()),
                "markeredgecolor": store_color(line.get_markeredgecolor()),
                "markeredgewidth": float(line.get_markeredgewidth()),
                "visible": bool(line.get_visible()),
                "z": float(self.object_z("series", y_col) or Z_DEFAULT["series"]),
            })
        return {
            "geometry": self.geometry(),
            "plot_style": self.plot_style,
            "font_family": self.font_family() or "",
            "figure": {"width": float(self.page_size[0]),
                       "height": float(self.page_size[1]),
                       "dpi": float(self.base_dpi),
                       "zoom": float(self.zoom)},
            "title": {"text": self.ax.get_title(), "size": self.fonts["title"],
                      "color": safe_hex(self.fonts["title_color"], "#000000"),
                      "pad": float(self.fonts["title_pad"])},
            "legend": {"visible": self.legend_visible, "location": self.legend_loc,
                       "size": self.fonts["legend"],
                       "color": safe_hex(self.fonts["legend_color"], "#000000")},
            "frame": dict(self.frame_cfg),
            # in points of the page, so that the file depends neither on
            # the zoom of the view nor on the screen it was made on
            "text_offsets": {name: [float(value[0]), float(value[1])]
                             for name, value in self.text_offset.items()},
            "text_offset_unit": "pt",
            # a name beginning with "_" is something the program keeps for
            # itself (the pixels of a picture), not a part of the graph
            "shapes": [{**{key_: (float(value)
                                  if key_ in ("x", "y", "w", "h", "angle",
                                              "width", "alpha")
                                  else value)
                           for key_, value in state.items()
                           if not str(key_).startswith("_")},
                        "name": str(name)}
                       for name, state in self.shape_state.items()],
            "arrows": [{"name": str(name), "head": state["head"],
                        "tail": [float(state["tail"][0]), float(state["tail"][1])],
                        "tip": [float(state["tip"][0]), float(state["tip"][1])],
                        "size": float(state["size"]), "style": state["style"],
                        "width": float(state["width"]), "color": state["color"],
                        "z": float(state.get("z") or Z_DEFAULT["arrow"])}
                       for name, state in self.arrow_state.items()],
            "notes": [{"name": str(name), "text": state["text"],
                       "pos": [float(state["pos"][0]), float(state["pos"][1])],
                       "angle": float(state.get("angle", 0.0) or 0.0),
                       "size": int(state["size"]), "color": state["color"],
                       "edge": state["edge"], "face": state["face"],
                       "z": float(state.get("z") or Z_DEFAULT["note"])}
                      for name, state in self.note_state.items()],
            "axes": axes,
            "series": series,
            "x_side": self.x_side,
            "error_partner": {str(mean): str(std)
                              for mean, std in self.error_partner.items()},
            # the second error column of `Error Bar (Median, +error, -error)`
            "error_partner_low": {str(mean): str(low) for mean, low
                                  in self.error_partner_low.items()},
        }

    def apply_state(self, state):
        """Rebuild the appearance stored by to_state()."""
        figure = state.get("figure") or {}
        if figure:
            self.base_dpi = float(figure.get("dpi", self.base_dpi) or self.base_dpi)
            self.zoom = min(max(float(figure.get("zoom", self.zoom) or 1.0),
                                ZOOM_MIN), ZOOM_MAX)   # the ceiling needs
            self.zoom = min(self.zoom, self.zoom_ceiling())   # the page size
            self.fig.set_dpi(self.render_dpi())
            self.set_page_size(figure.get("width", self.page_size[0]),
                               figure.get("height", self.page_size[1]),
                               redraw=False)

        if "plot_style" in state:
            self.plot_style = state["plot_style"]

        family = known_font_family(state.get("font_family"))
        if family:
            self.fonts["family"] = family

        legend = state.get("legend") or {}
        self.legend_visible = bool(legend.get("visible", self.legend_visible))
        self.legend_loc = legend.get("location", self.legend_loc)
        self.fonts["legend"] = int(legend.get("size", self.fonts["legend"]))
        self.fonts["legend_color"] = legend.get("color", self.fonts["legend_color"])

        side = state.get("x_side")
        if side in ("bottom", "top"):
            self.x_side = side
            self.layout["x_side"] = side

        pairs = state.get("error_partner")
        if isinstance(pairs, dict):      # which column holds which error
            self.error_partner = {str(mean): str(std)
                                  for mean, std in pairs.items()}
        lows = state.get("error_partner_low")
        if isinstance(lows, dict):       # ...and which one the error downwards
            self.error_partner_low = {str(mean): str(low)
                                      for mean, low in lows.items()}

        saved_series = state.get("series")
        if saved_series is not None:
            # the file decides which curves exist: a column that was not
            # plotted when it was saved does not appear now either
            found = {}
            for entry in saved_series:
                match = self.matching_series(entry.get("column"))
                if match is not None:
                    found[entry.get("column")] = match
            wanted = set(found.values())
            for column in [name for name in self.series if name not in wanted]:
                self.remove_series(column)

        for index, entry in enumerate(saved_series or []):
            column = found.get(entry.get("column"))
            line = None if column is None else self.series.get(column)
            if line is None:
                continue
            self.move_series(column, entry.get("axis", "left"))
            self.layout.setdefault("y", {})[str(column)] = self.series_side(column)
            saved = self.default_legend_state(index)
            position = entry.get("legend_pos")
            self.legend_state[column] = {
                "pos": tuple(position) if position else saved["pos"],
                "loc": entry.get("legend_loc", saved["loc"]),
                "size": int(entry.get("legend_size", saved["size"])),
                "color": entry.get("legend_color", saved["color"]),
                "edge": entry.get("legend_edge", saved["edge"]),
                "face": entry.get("legend_face", saved["face"]),
            }
            fill = entry.get("fill")
            if fill:
                self.fill_state[column] = {
                    **self.default_fill_state(self.settings.section("plot")), **fill}
            if "plot_style" in entry:
                self.series_style[column] = entry["plot_style"]
            if "bar_cfg" in entry:
                self.bar_cfg[column] = dict(entry["bar_cfg"])
            if "error_cfg" in entry:
                self.error_cfg[column] = dict(entry["error_cfg"])
            if "histogram_cfg" in entry:
                self.histogram_cfg[column] = dict(entry["histogram_cfg"])
            if "stairs_cfg" in entry:
                self.stairs_cfg[column] = dict(entry["stairs_cfg"])
            if "hist2d_cfg" in entry:
                self.hist2d_cfg[column] = dict(entry["hist2d_cfg"])
            if "pie_cfg" in entry:
                self.pie_cfg[column] = dict(entry["pie_cfg"])
            line.set_label(entry.get("label", line.get_label()))
            line.set_color(entry.get("color", line.get_color()))
            line.set_linestyle(entry.get("linestyle", line.get_linestyle()))
            line.set_linewidth(entry.get("linewidth", line.get_linewidth()))
            line.set_marker(entry.get("marker", line.get_marker()))
            line.set_markersize(entry.get("markersize", line.get_markersize()))
            line.set_markerfacecolor(entry.get("markerfacecolor",
                                               line.get_markerfacecolor()))
            line.set_markeredgecolor(entry.get("markeredgecolor",
                                               line.get_markeredgecolor()))
            line.set_markeredgewidth(entry.get("markeredgewidth",
                                               line.get_markeredgewidth()))
            line.set_visible(entry.get("visible", True))
            self.refresh_series_visuals(column)
            if entry.get("z") is not None:     # where it stands in the stack
                self.series_z[str(column)] = float(entry["z"])

        # the styles of the file decide whether the axes are drawn at all
        self.apply_style_axes()

        # a histogram counted its bins again just now: the automatic range
        # follows those counts (a range that was set by hand is restored
        # below and wins over this)
        self._rescale()

        # a file written before the axis colours existed carried one colour
        # for the whole frame: give it to all three axes, so it looks the same
        old_color = (state.get("frame") or {}).get("color")
        for which in ("x", "y", "y2"):
            cfg = (state.get("axes") or {}).get(which)
            if cfg is None:
                continue
            if (which == "y2" and self.ax2 is None
                    and str(cfg.get("direction", "off")) == "off"
                    and not self.right_axis_active()):
                continue          # no curve on the right: nothing to restore
            if "axis_color" not in cfg and old_color:
                cfg = {**cfg, "axis_color": old_color}
            self.apply_axis(which, cfg, redraw=False)

        frame = state.get("frame")
        if frame:
            self.apply_frame({**self.frame_cfg, **frame}, redraw=False)

        title = state.get("title") or {}
        self.fonts["title"] = int(title.get("size", self.fonts["title"]))
        self.fonts["title_color"] = title.get("color", self.fonts["title_color"])
        self.fonts["title_pad"] = float(title.get("pad", self.fonts["title_pad"]))
        self.ax.set_title(title.get("text", self.ax.get_title()),
                          fontsize=self.fonts["title"],
                          color=safe_hex(self.fonts["title_color"], "#000000"),
                          pad=self.page_points(self.fonts["title_pad"]))
        self.ax.title.set_picker(True)

        # points since the unit is written down; before that, pixels of the
        # page at its own resolution
        to_points = (1.0 if state.get("text_offset_unit") == "pt"
                     else 72.0 / (float(self.base_dpi) * self.screen_ratio()))
        for name, value in (state.get("text_offsets") or {}).items():
            if name in self.text_offset and value:
                self.text_offset[name] = (float(value[0]) * to_points,
                                          float(value[1]) * to_points)
        self.apply_text_offsets()

        self.apply_series_stack()      # the curves first: the drawings that
                                       # follow are laid on top of them
        for key in list(self.shape_state):          # replace the drawings
            self.remove_shape(key)
        for shape in state.get("shapes") or []:
            kind = shape.get("kind", "rect")
            base = self.default_shape_state(kind, 0.4, 0.4, 0.2, 0.15)
            saved = {key_: value for key_, value in shape.items()
                     if key_ != "name"}
            self.add_shape(state={**base, **saved, "kind": kind},
                           key=shape.get("name"))

        for key in list(self.arrow_state):           # replace the arrows
            self.remove_arrow(key)
        for arrow in state.get("arrows") or []:
            head = arrow.get("head", "triangle")
            base = self.default_arrow_state(head, arrow.get("tail", (0.3, 0.3)),
                                            arrow.get("tip", (0.5, 0.5)))
            merged = {**base, **arrow, "head": head}
            merged["tail"] = (float(merged["tail"][0]), float(merged["tail"][1]))
            merged["tip"] = (float(merged["tip"][0]), float(merged["tip"][1]))
            self.add_arrow(state={key_: value for key_, value in merged.items()
                                  if key_ != "name"}, key=arrow.get("name"))

        for key in list(self.note_state):          # replace the text boxes
            self.remove_note(key)
        for note in state.get("notes") or []:
            position = note.get("pos") or (0.5, 0.5)
            self.add_note(position, state={
                **self.default_note_state(position),
                **{k: v for k, v in note.items() if k not in ("pos", "name")},
                "pos": (float(position[0]), float(position[1]))},
                key=note.get("name"))

        geometry = state.get("geometry")
        if geometry:
            try:
                self.geometry(geometry)
            except tk.TclError:
                pass
        self.refresh_fills()
        self.refresh_legend()
        self.apply_font_family()     # after everything has been drawn again
        # a graph written before every curve had a place of its own can
        # carry two of them at the same height: they are spread out again,
        # which changes nothing that can be seen but makes the order one
        # that `Bring to front` and `Send to back` can work on
        if not self.stack_is_tidy():
            self._restack(redraw=False)
        # everything is there now: the two axes can be laid in the order the
        # stack asks for, and the drawn objects handed to the right one
        self.apply_stack_layers()
        self.draw()

    def matching_series(self, name):
        """The curve a saved column name belongs to, or None.

        A sheet that is drawn together with another one lends its name to
        its columns - `Signal (Fit)` instead of `Signal` - so the very same
        curve may be called one thing in the file and another on the screen
        once the sheets have been regrouped.  The plain name is compared
        when the full one is not there, in both directions.
        """
        if name is None:
            return None
        name = str(name)
        if name in self.series:
            return name

        def plain(text):
            text = str(text)
            if text.endswith(")") and " (" in text:
                return text.rsplit(" (", 1)[0]
            return text

        wanted = plain(name)
        if wanted in self.series:
            return wanted
        for one in self.series:
            if plain(one) == wanted:
                return one
        return None

    def _init_axes(self, plot_cfg):
        # what the X axis really carries: the first column, or - when that
        # column is the only filled one - the row number of the table
        x_col = self.x_axis_name()
        self._auto_x_label = x_col
        try:
            title = str(plot_cfg["title_template"]).format(x=x_col)
        except (KeyError, IndexError, ValueError):
            title = str(plot_cfg["title_template"])
        self.ax.set_title(title, fontsize=self.fonts["title"],
                          color=safe_hex(self.fonts["title_color"], "#000000"),
                          pad=self.page_points(self.fonts["title_pad"]))
        self.ax.set_xlabel(x_col)
        self.ax.set_ylabel(str(plot_cfg["y_label"]))
        for which in ("x", "y"):
            self.apply_axis(which, {**self.axis_cfg[which],
                                    "label": self.axis_label(which)}, redraw=False)
        self.apply_frame(self.frame_cfg, redraw=False)
        for text in (self.ax.title, self.ax.xaxis.label, self.ax.yaxis.label):
            text.set_picker(True)
        # remember the automatic placement: the drag offsets sit on top of it
        self._text_base = {"title": self.ax.title.get_transform(),
                           "x": self.ax.xaxis.label.get_transform(),
                           "y": self.ax.yaxis.label.get_transform()}
        if self.ax2 is not None:
            self._text_base["y2"] = self.ax2.yaxis.label.get_transform()
            if not self.ax2.get_ylabel():
                # the name of the first column drawn there is a useful start
                right = [name for name, side in self.series_axis.items()
                         if side == "right"]
                if right:
                    self.apply_axis("y2", {**self.axis_cfg["y2"],
                                           "label": str(right[0])}, redraw=False)
        self._pie_axes = None       # nothing was decided about the axes yet
        self.apply_style_axes()     # a pie window opens without axes
        self.apply_font_family()
        self._rescale()

    def _reapply_distances(self):
        """Turn the stored pixel distances into points for the current dpi."""
        for which in ("x", "y", "y2"):
            if which == "y2" and self.ax2 is None:
                continue
            ax, axis, axis_name = self._axis_pair(which)
            axis.labelpad = self.page_points(self.axis_cfg[which]["label_pad"])
            ax.tick_params(axis=axis_name, which="both",
                           pad=self.page_points(self.axis_cfg[which]["tick_pad"]))
        self.ax.set_title(self.ax.get_title(), fontsize=self.fonts["title"],
                          color=safe_hex(self.fonts["title_color"], "#000000"),
                          pad=self.page_points(self.fonts["title_pad"]))
        self.ax.title.set_picker(True)
        self.apply_text_offsets()

    def _on_resize(self, _event=None):
        """The Tk canvas may change the resolution: keep the pixels honest."""
        if self._inline is not None:   # the editor would sit in the wrong place
            self.commit_inline_edit()
        self._fix_page_size()          # the page keeps its own proportions
        dpi = self.fig.get_dpi()
        if abs(dpi - self._dpi) > 0.01:
            self._dpi = dpi
            self._reapply_distances()
        # circles keep their shape and the arrow heads their size only if the
        # geometry is rebuilt for the new aspect ratio
        self.refresh_shapes()
        self.refresh_arrows()
        self._refresh_highlight()
        self.draw()

    def _connect_events(self):
        self._dpi = self.fig.get_dpi()
        self.canvas.mpl_connect("resize_event", self._on_resize)
        self.canvas.mpl_connect("pick_event", self._on_pick)
        self.canvas.mpl_connect("button_press_event", self._on_button_press)
        self.canvas.mpl_connect("motion_notify_event", self._on_motion)
        self.canvas.mpl_connect("button_release_event", self._on_release)

    # -- drawing / legend --------------------------------------------------
    def draw(self):
        # a curve that was drawn again (another style, another colour, new
        # data) comes back at its usual height: it is put back where the
        # user had moved it, before anything is painted
        if getattr(self, "_quiet_draws", False):
            return                       # one drawing is coming at the end
        if self._still is not None:      # a drag: paint only what moves
            if self._dragged_objects() is not None:
                if self.group or self._group_marks:
                    self._refresh_group_marks()
                if self._still_frame():
                    return
            self._end_still(draw=False)
        self.apply_series_stack()
        self.apply_axis_stack()
        self.sync_axes_dialog()
        if self.group or self._group_marks:
            self._refresh_group_marks()  # the boxes follow their objects
        self.canvas.draw_idle()

    def sync_frame_dialog(self):
        """An open `Frame and origin` follows the diagram it belongs to."""
        dialog = self._dialogs.get("axes")
        if dialog is None:
            return False
        try:
            if not dialog.winfo_exists():
                return False
            dialog.frame_tab.sync_all()
        except (AttributeError, tk.TclError):
            return False
        return True

    def sync_axes_dialog(self):
        """An open `Axes properties` follows the ranges of the diagram.

        Whatever moved an automatic range - new data, a curve carried to
        the other scale, Undo, the zoom tool of the toolbar - the two
        boxes of that axis say what the axis says.  A range set by hand is
        the user's own and is not touched.
        """
        if getattr(self, "_measuring", False):
            return False        # a range is being tried out, not set
        # ...and not only the ranges: every open properties window of this
        # diagram shows what the diagram says (see `DiagramMirror`)
        self.sync_dialogs()
        dialog = self._dialogs.get("axes")
        if dialog is None:
            return False
        try:
            if not dialog.winfo_exists():
                return False
        except (AttributeError, tk.TclError):
            return False
        return True

    def sync_dialogs(self):
        """Every open window of this diagram follows what the diagram says.

        The axes, the title, the curve, the legend and the text box windows
        all hold a copy of what they show.  Each is told, whenever the
        diagram is drawn, to look again - leaving alone only what the user
        has changed in it and not applied yet.
        """
        count = 0
        for dialog in list(self._dialogs.values()):
            mirror = getattr(dialog, "mirror", None)
            if mirror is None:
                continue
            try:
                if not dialog.winfo_exists():
                    continue
                mirror()
                count += 1
            except (AttributeError, KeyError, TypeError, ValueError,
                    tk.TclError):
                continue
        return count

    def default_legend_state(self, index):
        """Start position of the index-th legend box, from the chosen corner."""
        x, y, loc = LEGEND_ANCHORS.get(self.legend_loc, LEGEND_ANCHORS["best"])
        direction = -1 if y >= 0.5 else 1
        plot_cfg = self.settings.section("plot")
        edge = ("none" if not plot_cfg.get("legend_frame", True)
                else safe_hex(plot_cfg.get("legend_edge_color"), "#000000"))
        face = ("none" if plot_cfg.get("legend_transparent") else
                safe_hex(plot_cfg.get("legend_background"), "#ffffff"))
        return {"pos": (x, y + index * LEGEND_STACK_STEP * direction),
                "loc": loc, "size": int(self.fonts["legend"]),
                "color": safe_hex(self.fonts["legend_color"], "#000000"),
                "edge": edge, "face": face}

    def reset_legend_positions(self):
        """Stack the legend boxes again from the configured corner."""
        for index, y_col in enumerate(self.series):
            self.legend_state[y_col] = self.default_legend_state(index)
        self.refresh_legend()
        self.draw()

    def legend_handle(self, column, line):
        """What is drawn in front of the legend text of one curve.

        A bar chart and a histogram draw their curve with no line and no
        marker at all - the bars are patches beside it - so the curve itself
        would leave an empty space in front of the text.  One of the bars is
        used instead, and an error bar plot shows its own container, so the
        little sample really looks like what is in the diagram.
        """
        style = self.series_style.get(column, self.plot_style)
        if style == "stairs":
            patch = self.stairs_patches.get(column)
            return patch if patch is not None else line
        if style == "pie":
            wedges = self.pie_wedges.get(column) or []
            return wedges[0] if wedges else line
        if style == "hist2d":
            # a QuadMesh cannot be drawn in a legend box: a little patch of
            # the middle colour of its scale stands for it
            cfg = self.hist2d_cfg.get(column) or {}
            colors = self.slice_colors(cfg.get("cmap", "viridis"), 3)
            return Rectangle((0, 0), 1, 1, facecolor=colors[len(colors) // 2],
                             edgecolor="none")
        if style == "bar":
            container = self.bar_containers.get(column)
        elif style == "histogram":
            container = self.bar_containers.get(f"hist_{column}")
        elif style in ERROR_STYLES:
            container = self.errorbar_containers.get(column)
            # the marker of the curve and one error bar through it, so the
            # sample in front of the text looks like a point of the diagram
            return (line, container) if container is not None else line
        else:
            return line
        patches = list(getattr(container, "patches", ()) or ())
        return patches[0] if patches else line

    def legend_entries(self, column, line):
        """The samples and the texts of one legend box.

        Every kind of diagram has **one** sample in front of **one** text -
        except a pie, where one colour would say nothing: there the box
        lists **every slice** with the name that belongs to it.
        """
        label = str(line.get_label())
        if self.series_style.get(column, self.plot_style) != "pie":
            return [self.legend_handle(column, line)], [label]
        wedges = list(self.pie_wedges.get(column) or ())
        if not wedges:
            return [self.legend_handle(column, line)], [label]
        return wedges, [str(one) for one
                        in self.pie_slice_names(column, len(wedges))]

    def refresh_legend(self):
        """One legend box per curve, each at its own (movable) position."""
        for legend in self.legends.values():
            legend.remove()
        self.legends.clear()
        for y_col in [name for name in self.legend_state if name not in self.series]:
            del self.legend_state[y_col]
        if not self.legend_visible:
            return
        index = 0
        for y_col, line in self.series.items():
            label = line.get_label()
            if not label or label.startswith("_") or not line.get_visible():
                continue
            state = self.legend_state.get(y_col)
            if state is None:
                state = self.default_legend_state(index)
                self.legend_state[y_col] = state
            handles, texts = self.legend_entries(y_col, line)
            legend = Legend(self.ax, handles, texts, loc=state["loc"],
                            bbox_to_anchor=state["pos"],
                            bbox_transform=self.ax.transAxes,
                            prop={"size": state["size"]}, framealpha=1.0,
                            # ndivide=1: the parts are drawn over each other, so a marker with
                            # an error bar through it is one single sample
                            handler_map={tuple: HandlerTuple(ndivide=1)})
            family = self.font_family()
            for text in legend.get_texts():
                text.set_color(state.get("color", "#000000"))
                if family:                   # a box built after a font change
                    text.set_fontfamily(family)
            box = legend.get_frame()            # surrounding box of this legend
            edge = state.get("edge", "#000000")
            face = state.get("face", "#ffffff")
            box.set_edgecolor("none" if edge == "none" else edge)
            box.set_linewidth(0.0 if edge == "none" else 0.8)
            box.set_facecolor("none" if face == "none" else face)
            self.ax.add_artist(legend)
            self.legends[y_col] = legend
            index += 1
        if self.selection is not None and self.selection[0] == "legend":
            if self.selection[1] not in self.legends:
                self.select_object(None, None)
            else:
                self._refresh_highlight()

    # -- drawn objects (rectangle, triangle, circle, ellipse) --------------
    def arm_shape_drawing(self, kind=None, armed=None):
        """Wait for a press-drag in the diagram and draw a shape there."""
        if kind is not None:
            self.shape_kind = kind
            self.settings.set("shape", "kind",
                              name_of(SHAPE_KINDS, kind, "Rectangle"))
            try:                       # remember it for the next start as well
                self.settings.save()
            except OSError:
                pass
            self.shape_button.set_shape(kind)
        wanted = (not self._pending_shape) if armed is None else armed
        self._pending_shape = bool(wanted)
        if self._pending_shape:                  # only one tool at a time
            self.arm_text_placement(False)
            self.arm_arrow_drawing(armed=False)
        widget = self.canvas.get_tk_widget()
        try:
            self.shape_button.set_active(self._pending_shape)
            widget.configure(cursor="tcross" if self._pending_shape else "")
            self.toolbar.set_message(
                "Draw: press and drag in the diagram" if self._pending_shape else "")
        except (tk.TclError, AttributeError):
            pass
        if not self._pending_shape:
            self._cursor = ""
        return self._pending_shape

    def show_shape_menu(self, event=None, popup=True):
        """The popup list of the drawing objects, each with its picture."""
        entries = [(label, shape_tool_icon(code),
                    lambda c=code: self.arm_shape_drawing(c, True))
                   for label, code in SHAPE_KINDS]
        where = None
        if popup:
            where = (self.shape_button.winfo_rootx(),
                     self.shape_button.winfo_rooty()
                     + self.shape_button.winfo_height())
        return popup_icon_menu(self, entries, where)

    def default_shape_state(self, kind, x, y, width=0.0, height=0.0):
        cfg = self.settings.section("shape")
        return {
            "kind": kind, "x": float(x), "y": float(y),
            "w": float(width), "h": float(height), "angle": 0.0,
            "flip": False,          # a line drawn from top left to bottom right
            "style": code_of(LINE_STYLES, cfg["line_style"], "-"),
            "width": float(cfg["line_width"]),
            "edge": safe_hex(cfg["line_color"], "#000000"),
            "face": ("none" if cfg["no_fill"]
                     else safe_hex(cfg["fill_color"], "#cfe3f7")),
            "alpha": float(cfg["fill_alpha"]),
        }

    def add_shape(self, *args, **kwargs):
        """One command: it can be taken back with Undo."""
        with self.changed('the drawing'):
            return self._add_shape(*args, **kwargs)

    def _add_shape(self, kind=None, position=(0.4, 0.4), size=(0.2, 0.15),
                  state=None, key=None):
        key = self.claim_key("shape", key)
        state = state or self.default_shape_state(
            kind or self.shape_kind, position[0], position[1], size[0], size[1])
        if state.get("z") is None:
            state["z"] = self.top_z()      # a new object stands in front
        self.shape_state[key] = state
        self.refresh_shape(key)
        self.draw()
        return key

    def remove_shape(self, *args, **kwargs):
        """One command: it can be taken back with Undo."""
        with self.changed('the drawing'):
            return self._remove_shape(*args, **kwargs)

    def _remove_shape(self, key):
        patch = self.shapes.pop(key, None)
        if patch is not None:
            patch.remove()
        self._clear_picture(key)
        self.shape_state.pop(key, None)
        if self.selected_shape == key:
            self.select_shape(None)
        dialog = self._dialogs.pop(f"shape-{key}", None)
        if dialog is not None and dialog.winfo_exists():
            dialog.destroy()
        self.draw()

    def _axes_aspect(self):
        box = self.ax.get_window_extent()
        return (box.width / box.height) if box.height else 1.0

    def refresh_shape(self, key):
        """Build the patch of one drawn object from its state."""
        patch = self.shapes.pop(key, None)
        if patch is not None:
            patch.remove()
        self._clear_picture(key)
        state = self.shape_state.get(key)
        if state is None:
            return None
        x, y = state["x"], state["y"]
        if state["kind"] in OPEN_SHAPES:   # a horizontal line stays horizontal
            w, h = state["w"], state["h"]
        else:
            w = max(MIN_SHAPE_SIZE, state["w"])
            h = max(MIN_SHAPE_SIZE, state["h"])
        if state["kind"] == "circle":      # keep it round on the screen
            h = w * self._axes_aspect()
            state["h"] = h
        face = state.get("face", "none")
        host = self.object_axes("shape", key)
        common = {
            "transform": self._shape_transform(state),
            "clip_on": False,
            "zorder": float(state.get("z") or Z_DEFAULT["shape"]),
            "edgecolor": state["edge"], "linestyle": state["style"],
            "linewidth": state["width"],
            "facecolor": ("none" if face == "none"
                          else to_rgba(face, state.get("alpha", 0.6))),
        }
        if state["kind"] == "line":
            ends = ([[x, y + h], [x + w, y]] if state.get("flip")
                    else [[x, y], [x + w, y + h]])
            common["facecolor"] = "none"        # a stroke has nothing to fill
            patch = Polygon(ends, closed=False, fill=False, **common)
        elif state["kind"] == "triangle":
            patch = Polygon([[x + w / 2, y + h], [x, y], [x + w, y]],
                            closed=True, **common)
        elif state["kind"] in ("circle", "ellipse"):
            patch = Ellipse((x + w / 2, y + h / 2), w, h, **common)
        else:
            patch = Rectangle((x, y), w, h, **common)
        host.add_patch(patch)
        self.shapes[key] = patch
        if state["kind"] == PICTURE_KIND:
            self._refresh_picture(key, state, patch)
        if self.selected_shape == key:
            self._refresh_handles()
        return patch

    # -- a picture pasted or dropped into the diagram ----------------------
    def _clear_picture(self, key):
        artist = self.shape_pictures.pop(key, None)
        if artist is not None:
            try:
                artist.remove()
            except (ValueError, AttributeError):
                pass
        return None

    def _refresh_picture(self, key, state, patch):
        """Draw the picture of one object in the box of its rectangle."""
        self._clear_picture(key)
        values = state.get("_pixels")
        if values is None:
            values = picture_from_text(state.get("picture"))
            state["_pixels"] = values
        if values is None:
            return None
        box = TransformedBbox(
            Bbox.from_bounds(float(state["x"]), float(state["y"]),
                             max(MIN_SHAPE_SIZE, float(state["w"])),
                             max(MIN_SHAPE_SIZE, float(state["h"]))),
            self.ax.transAxes)
        height = float(state.get("z") or Z_DEFAULT["shape"])
        # the smaller copies are made once and kept with the picture: a
        # drag that builds the artist anew for every step reuses them
        kept = state.get("_levels")
        if not kept or kept[0] is not values:
            kept = picture_levels(values)
            state["_levels"] = kept
        artist = PictureImage(box, kept, interpolation="antialiased",
                              zorder=height - Z_PICTURE_GAP,
                              alpha=float(state.get("alpha", 1.0)))
        artist.set_clip_on(False)
        artist.set_in_layout(False)
        self.object_axes("shape", key).add_artist(artist)
        self.shape_pictures[key] = artist
        patch.set_facecolor("none")        # the picture is the filling
        patch.set_zorder(height)
        return artist

    @staticmethod
    def picture_ratio(state):
        """Height / width of the picture itself, or None."""
        values = state.get("_pixels")
        if values is None:
            values = picture_from_text(state.get("picture"))
            state["_pixels"] = values
        if values is None or not len(np.shape(values)) >= 2:
            return None
        height, width = np.shape(values)[0], np.shape(values)[1]
        return (float(height) / float(width)) if width else None

    def picture_size(self, state, width=None):
        """The box a picture fills at its own proportions."""
        ratio = self.picture_ratio(state) or 1.0
        wide = float(width or PICTURE_START_WIDTH)
        # the axes are wider than they are tall, so a square picture needs
        # a taller box in axes coordinates to look square on the screen
        tall = wide * ratio * self._axes_aspect()
        if tall > 0.9:                      # never taller than the plot area
            wide *= 0.9 / tall
            tall = 0.9
        return wide, tall

    def add_picture(self, *args, **kwargs):
        """One command: it can be taken back with Undo."""
        with self.changed('the picture'):
            return self._add_picture(*args, **kwargs)

    def _add_picture(self, source, centre=None, state=None):
        """Put a picture into the diagram; it can be moved and resized.

        `source` is anything a drop, a paste or the file dialog hands over:
        a file name, a picture, or the bytes of one.  `centre` is where it
        is laid (the middle of the plot area by default).
        """
        if state is None:
            text = picture_as_text(source)
            if text is None:
                return None
            cfg = self.settings.section("shape")
            state = {
                "kind": PICTURE_KIND, "picture": text,
                "x": 0.0, "y": 0.0, "w": 0.0, "h": 0.0, "angle": 0.0,
                "style": "none",          # no frame around it to begin with
                "width": float(cfg["line_width"]),
                "edge": safe_hex(cfg["line_color"], "#000000"),
                "face": "none", "alpha": 1.0,
            }
            width, height = self.picture_size(state)
            middle = centre or (0.5, 0.5)
            # it is laid around that point, and pulled back inside the plot
            # area when the point is close to an edge
            x = min(max(float(middle[0]) - width / 2.0, 0.0), 1.0 - width)
            y = min(max(float(middle[1]) - height / 2.0, 0.0), 1.0 - height)
            state["x"], state["y"] = x, y
            state["w"], state["h"] = width, height
        key = self.claim_key("shape")
        self.shape_state[key] = state
        self.refresh_shape(key)
        self.select_object("shape", key)
        self.draw()
        self.flash("Picture added - drag it to move it, "
                   "drag a corner to resize it")
        return key

    def fit_picture_ratio(self, key):
        """Give a picture the shape it really has, keeping its width."""
        state = self.shape_state.get(key)
        if state is None or state.get("kind") != PICTURE_KIND:
            return False
        width, height = self.picture_size(state, width=state["w"])
        state["w"], state["h"] = width, height
        self.refresh_shape(key)
        self._refresh_handles()
        self._refresh_highlight()
        self.draw()
        return True

    def paste_picture(self, _event=None, centre=None):
        """A picture from the clipboard, in the middle of the diagram."""
        picture = clipboard_picture(self.canvas.get_tk_widget())
        if picture is None:
            return None
        return self.add_picture(picture, centre=centre)

    def insert_picture_file(self, *_args):
        """`Insert picture...`: choose a picture file and place it."""
        path = filedialog.askopenfilename(title="Insert picture",
                                          filetypes=PICTURE_PATTERNS,
                                          parent=self)
        if not path:
            return None
        key = self.add_picture(path)
        if key is None:
            messagebox.showerror("Picture",
                                 "That file could not be read as a picture.",
                                 parent=self)
        return key

    def drop_pictures(self, data, root_x=None, root_y=None):
        """Pictures dropped on the diagram from the Finder.

        The first one is laid where it was dropped, the others beside it.
        """
        keys = []
        centre = self._axes_point_of(root_x, root_y)
        for name in dropped_names(data):
            step = 0.03 * len(keys)
            spot = None
            if centre is not None:
                spot = (centre[0] + step, centre[1] - step)
            key = self.add_picture(name, centre=spot)
            if key is not None:
                keys.append(key)
        if not keys:
            self.flash("There was no picture in what was dropped")
        return keys

    def _axes_point_of(self, root_x, root_y):
        """A point of the screen in axes coordinates, or None."""
        if root_x is None or root_y is None:
            return None
        try:
            widget = self.canvas.get_tk_widget()
            x = float(root_x) - widget.winfo_rootx()
            y = float(root_y) - widget.winfo_rooty()
            if not (0 <= x <= widget.winfo_width()
                    and 0 <= y <= widget.winfo_height()):
                return None
            point = self.ax.transAxes.inverted().transform(
                (x, float(widget.winfo_height()) - y))
        except (ValueError, TypeError, tk.TclError):
            return None
        return (float(point[0]), float(point[1]))

    def refresh_shapes(self):
        for key in list(self.shape_state):
            self.refresh_shape(key)

    # -- rotation ----------------------------------------------------------
    @staticmethod
    def angle_of(state):
        try:
            return float(state.get("angle", 0.0) or 0.0)
        except (TypeError, ValueError):
            return 0.0

    @staticmethod
    def shape_centre(state):
        return (state["x"] + state["w"] / 2.0, state["y"] + state["h"] / 2.0)

    def _rotation(self, centre, angle):
        """Turn by `angle` degrees around `centre`, measured on the screen."""
        px, py = self.ax.transAxes.transform(centre)
        return Affine2D().rotate_deg_around(float(px), float(py), float(angle))

    def _shape_transform(self, state):
        """Axes coordinates plus the rotation of that object, in pixels.

        Rotating in pixels (and not in axes coordinates) keeps the object
        undistorted whatever the proportions of the plot area.
        """
        angle = self.angle_of(state)
        if not angle:
            return self.ax.transAxes
        return self.ax.transAxes + self._rotation(self.shape_centre(state), angle)

    def _turn_point(self, point, centre, angle):
        """One point of the plot area turned around `centre`."""
        if not angle:
            return (float(point[0]), float(point[1]))
        base = self.ax.transAxes
        turned = self._rotation(centre, angle).transform(base.transform(point))
        back = base.inverted().transform(turned)
        return (float(back[0]), float(back[1]))

    def rotation_centre(self):
        """The point the selected object turns around, in axes coordinates."""
        kind, key = self.selection or (None, None)
        if kind == "shape" and key in self.shape_state:
            state = self.shape_state[key]
            if state["kind"] in OPEN_SHAPES:
                return None      # its two ends give the direction, as an arrow
            return self.shape_centre(state)
        if kind == "note" and key in self.note_state:
            return tuple(self.note_state[key]["pos"])
        return None

    def rotation_handle_position(self):
        """Where the round rotation control point sits, or None."""
        kind, key = self.selection or (None, None)
        centre = self.rotation_centre()
        if centre is None:
            return None
        base = self.ax.transAxes
        if kind == "shape":
            state = self.shape_state[key]
            if state.get("kind") == PICTURE_KIND:
                return None          # a picture is not turned, only resized
            top = self.shape_handle_positions(state)[6]     # top, middle
            start = np.array(base.transform(centre), dtype=float)
            end = np.array(base.transform(top), dtype=float)
            vector = end - start
            length = float(np.hypot(*vector))
            if length < 1e-6:
                return None
            point = end + vector / length * ROTATE_GAP
        else:
            artist = self.notes.get(key)
            if artist is None:
                return None
            try:
                box = artist.get_window_extent(self._renderer())
            except (RuntimeError, ValueError, AttributeError, TypeError):
                return None
            point = np.array([(box.x0 + box.x1) / 2.0, box.y1 + ROTATE_GAP])
        back = base.inverted().transform(point)
        return (float(back[0]), float(back[1]))

    def rotate_selection(self, angle, snap=False):
        """Turn the selected drawing or text box to `angle` degrees."""
        kind, key = self.selection or (None, None)
        state = self.selected_state()
        if state is None or kind not in ("shape", "note"):
            return False
        if snap:
            angle = round(angle / ROTATE_SNAP) * ROTATE_SNAP
        state["angle"] = float(angle) % 360.0
        if kind == "shape":
            self.refresh_shape(key)
        else:
            self.refresh_note(key)
        self._refresh_handles()
        self._refresh_highlight()
        self.draw()
        return True

    def _pointer_angle(self, event, centre):
        point = np.array(self.ax.transAxes.transform(centre), dtype=float)
        vector = np.array([event.x, event.y], dtype=float) - point
        if float(np.hypot(*vector)) < 1e-6:
            return None
        return float(np.degrees(np.arctan2(vector[1], vector[0])))

    # -- arrows ------------------------------------------------------------
    def arm_arrow_drawing(self, head=None, armed=None):
        """Wait for a press-drag in the diagram and draw an arrow there."""
        if head is not None:
            self.arrow_head = head
            self.settings.set("arrow", "head",
                              name_of(ARROW_HEADS, head, "Triangle head"))
            try:
                self.settings.save()
            except OSError:
                pass
            self.arrow_button.set_shape(head)
        wanted = (not self._pending_arrow) if armed is None else armed
        self._pending_arrow = bool(wanted)
        if self._pending_arrow:
            self.arm_text_placement(False)
            self.arm_shape_drawing(armed=False)
        widget = self.canvas.get_tk_widget()
        try:
            self.arrow_button.set_active(self._pending_arrow)
            widget.configure(cursor="tcross" if self._pending_arrow else "")
            self.toolbar.set_message(
                "Arrow: press at the tail and drag to the tip"
                if self._pending_arrow else "")
        except (tk.TclError, AttributeError):
            pass
        if not self._pending_arrow:
            self._cursor = ""
        return self._pending_arrow

    def show_arrow_menu(self, event=None, popup=True):
        """The popup list of the arrow heads, each drawn beside its name."""
        entries = [(label, arrow_head_icon(code),
                    lambda c=code: self.arm_arrow_drawing(c, True))
                   for label, code in ARROW_HEADS]
        where = None
        if popup:
            where = (self.arrow_button.winfo_rootx(),
                     self.arrow_button.winfo_rooty()
                     + self.arrow_button.winfo_height())
        return popup_icon_menu(self, entries, where)

    def default_arrow_state(self, head, tail, tip):
        cfg = self.settings.section("arrow")
        return {
            "head": head, "tail": (float(tail[0]), float(tail[1])),
            "tip": (float(tip[0]), float(tip[1])),
            "size": float(cfg["head_size"]),
            "style": code_of(LINE_STYLES, cfg["line_style"], "-"),
            "width": float(cfg["line_width"]),
            "color": safe_hex(cfg["color"], "#000000"),
        }

    def add_arrow(self, *args, **kwargs):
        """One command: it can be taken back with Undo."""
        with self.changed('the arrow'):
            return self._add_arrow(*args, **kwargs)

    def _add_arrow(self, head=None, tail=(0.3, 0.3), tip=(0.5, 0.5),
                   state=None, key=None):
        key = self.claim_key("arrow", key)
        state = state or self.default_arrow_state(
            head or self.arrow_head, tail, tip)
        if state.get("z") is None:
            state["z"] = self.top_z()      # a new arrow stands in front
        self.arrow_state[key] = state
        self.refresh_arrow(key)
        self.draw()
        return key

    def remove_arrow(self, *args, **kwargs):
        """One command: it can be taken back with Undo."""
        with self.changed('the arrow'):
            return self._remove_arrow(*args, **kwargs)

    def _remove_arrow(self, key):
        for artist in self.arrows.pop(key, ()):
            artist.remove()
        self.arrow_state.pop(key, None)
        if self.selection == ("arrow", key):
            self.select_object(None, None)
        dialog = self._dialogs.pop(f"arrow-{key}", None)
        if dialog is not None and dialog.winfo_exists():
            dialog.destroy()
        self.draw()

    def _head_polygon(self, state):
        """Head corners in axes coordinates, built in pixels so it is true."""
        transform = self.ax.transAxes
        inverse = transform.inverted()
        tail = np.array(transform.transform(state["tail"]), dtype=float)
        tip = np.array(transform.transform(state["tip"]), dtype=float)
        direction = tip - tail
        length = float(np.hypot(*direction))
        if length < 1e-6:
            return None, state["tip"]
        unit = direction / length
        normal = np.array([-unit[1], unit[0]])
        size = min(float(state["size"]), max(4.0, length))
        half = size * 0.42
        base = tip - unit * size
        left, right = base + normal * half, base - normal * half
        kind = state["head"]
        if kind == "chevron":
            points = [left, tip, right]
        elif kind == "concave":
            points = [tip, left, base + unit * size * 0.35, right]
        elif kind == "convex":
            points = [tip, left, base - unit * size * 0.22, right]
        else:
            points = [tip, left, right]
        shaft_end = tip if kind == "chevron" else base + unit * size * 0.15
        return ([inverse.transform(point) for point in points],
                inverse.transform(shaft_end))

    def refresh_arrow(self, key):
        for artist in self.arrows.pop(key, ()):
            artist.remove()
        state = self.arrow_state.get(key)
        if state is None:
            return None
        points, shaft_end = self._head_polygon(state)
        height = float(state.get("z") or Z_DEFAULT["arrow"])
        host = self.object_axes("arrow", key)
        shaft, = host.plot(
            [state["tail"][0], shaft_end[0]], [state["tail"][1], shaft_end[1]],
            transform=self.ax.transAxes, color=state["color"],
            linestyle=state["style"], linewidth=state["width"],
            solid_capstyle="butt", clip_on=False, zorder=height,
            label="_nolegend_")
        artists = [shaft]
        if points is not None:
            if state["head"] == "chevron":
                head, = host.plot(
                    [p[0] for p in points], [p[1] for p in points],
                    transform=self.ax.transAxes, color=state["color"],
                    linestyle="-", linewidth=state["width"],
                    solid_joinstyle="miter", clip_on=False, zorder=height,
                    label="_nolegend_")
            else:
                head = Polygon(points, closed=True, transform=self.ax.transAxes,
                               facecolor=state["color"],
                               edgecolor=state["color"],
                               linewidth=max(0.2, state["width"] * 0.5),
                               clip_on=False, zorder=height)
                host.add_patch(head)
            artists.append(head)
        self.arrows[key] = artists
        if self.selection == ("arrow", key):
            self._refresh_handles()
        return artists

    def refresh_arrows(self):
        for key in list(self.arrow_state):
            self.refresh_arrow(key)

    @staticmethod
    def arrow_handle_positions(state):
        return [tuple(state["tail"]), tuple(state["tip"])]

    def arrow_at(self, x, y, tolerance=6.0):
        """Key of the arrow under the pointer, or None."""
        if x is None or y is None:
            return None
        point = np.array([x, y], dtype=float)
        for key in reversed(list(self.arrow_state)):
            state = self.arrow_state[key]
            tail = np.array(self.ax.transAxes.transform(state["tail"]))
            tip = np.array(self.ax.transAxes.transform(state["tip"]))
            segment = tip - tail
            length = float(np.hypot(*segment))
            if length < 1e-6:
                continue
            position = float(np.clip(np.dot(point - tail, segment) / length ** 2,
                                     0.0, 1.0))
            distance = float(np.hypot(*(point - (tail + position * segment))))
            if distance <= tolerance + state["width"] + state["size"] * 0.25:
                return key
        return None

    def edit_arrow(self, key):
        state = self.arrow_state.get(key)
        if state is None:
            return None

        def apply(values):
            current = self.arrow_state.get(key)   # Undo may have replaced it
            if current is None:
                return
            current.update(values)
            self.refresh_arrow(key)
            self.draw()

        return self._show_dialog(f"arrow-{key}", lambda: ArrowDialog(
            self, state, apply, on_delete=lambda: self.remove_arrow(key),
            on_close=lambda _d: self._dialogs.pop(f"arrow-{key}", None),
            source=lambda: self.arrow_state.get(key)))

    # -- selection and control points --------------------------------------
    @staticmethod
    def handle_positions(state):
        x, y, w, h = state["x"], state["y"], state["w"], state["h"]
        return [(x, y), (x + w, y), (x + w, y + h), (x, y + h),
                (x + w / 2, y), (x + w, y + h / 2),
                (x + w / 2, y + h), (x, y + h / 2)]

    @property
    def selected_shape(self):
        kind, key = self.selection or (None, None)
        return key if kind == "shape" else None

    @property
    def selected_arrow(self):
        kind, key = self.selection or (None, None)
        return key if kind == "arrow" else None

    def select_shape(self, key):
        self.select_object("shape", key)

    def _selection_store(self, kind):
        return {"shape": self.shape_state, "arrow": self.arrow_state,
                "note": self.note_state, "legend": self.legend_state,
                "text": self.text_offset, "axis": self.frame_sides}.get(kind)

    def select_object(self, kind, key):
        """Remember the object the keyboard commands work on."""
        store = self._selection_store(kind)
        if store is not None and key in store:
            if kind == "text" and not self.text_shown(key):
                kind = None             # only a text that is really there
            if kind == "axis" and not self.ax.spines[key].get_visible():
                kind = None             # only a line that is really drawn
        if store is not None and key in store and kind is not None:
            self.selection = (kind, key)
            if self.group:              # one object chosen: the group lets go
                self.group = []
                self._refresh_group_marks()
        else:
            self.selection = None
        self._refresh_handles()
        self._refresh_highlight()

    def selected_state(self):
        """The dictionary of the selected object, or None."""
        kind, key = self.selection or (None, None)
        store = self._selection_store(kind)
        return None if store is None else store.get(key)

    def highlighted_artist(self):
        """The text of the selection - drawings show control points instead."""
        kind, key = self.selection or (None, None)
        if kind == "note":
            return self.notes.get(key)
        if kind == "legend":
            return self.legends.get(key)
        if kind == "text":
            return self.text_artist(key) if self.text_shown(key) else None
        return None

    def is_marked(self):
        """True while a text, a label or a legend box wears the blue veil."""
        return self._marked is not None

    def _plain_look(self, marked):
        """Give one text its own appearance back."""
        kind, key = marked
        if kind == "text":
            artist = self.text_artist(key)
            if artist is not None:
                artist.set_bbox(None)
        elif kind == "note":
            self.refresh_note(key)             # rebuilt from its own state
        elif kind == "legend":
            legend, state = self.legends.get(key), self.legend_state.get(key)
            if legend is not None and state is not None:
                edge, face = state.get("edge", "none"), state.get("face", "#ffffff")
                frame = legend.get_frame()
                frame.set_alpha(1.0)
                frame.set_edgecolor("none" if edge == "none" else edge)
                frame.set_linewidth(0.0 if edge == "none" else 0.8)
                frame.set_facecolor("none" if face == "none" else face)

    def _refresh_highlight(self):
        """A light blue veil marks the selected text, label or legend box.

        The mark belongs to the artist itself, so it follows the text
        wherever matplotlib puts it - no stale pixel coordinates.
        """
        kind, key = self.selection or (None, None)
        wanted = (kind, key) if kind in ("text", "note", "legend") else None
        if self._marked is not None and self._marked != wanted:
            self._plain_look(self._marked)
            self._marked = None
        if wanted is None:
            return None
        if kind == "text":
            artist = self.text_artist(key)
            if artist is None or not self.text_shown(key):
                return None
            artist.set_bbox(dict(SELECT_BOX))
        elif kind == "note":
            artist = self.notes.get(key)
            if artist is None:
                return None
            patch = artist.get_bbox_patch()
            if patch is None:
                artist.set_bbox(dict(SELECT_BOX))
            else:
                patch.set_facecolor(SELECT_FACE)
                patch.set_edgecolor(SELECT_EDGE)
                patch.set_linewidth(1.0)
        else:
            legend = self.legends.get(key)
            if legend is None:
                return None
            frame = legend.get_frame()
            frame.set_alpha(None)      # let the translucent veil through
            frame.set_facecolor(SELECT_FACE)
            frame.set_edgecolor(SELECT_EDGE)
            frame.set_linewidth(1.2)
        self._marked = wanted
        return self.highlighted_artist()

    # -- writing a text in place -------------------------------------------
    def text_value(self, kind, key):
        """The text of one editable object, as the user sees it."""
        if kind == "note":
            state = self.note_state.get(key)
            return "" if state is None else str(state.get("text", ""))
        if kind == "text":
            return self.ax.get_title() if key == "title" else self.axis_label(key)
        if kind == "legend":
            line = self.series.get(key)
            if line is None:
                return ""
            if self.series_style.get(key, self.plot_style) == "pie":
                wedges = self.pie_wedges.get(key) or []
                names = self.pie_slice_names(key, len(wedges))
                row = self.legend_row(key)
                return str(names[row]) if 0 <= row < len(names) else ""
            label = str(line.get_label())
            return "" if not label or label.startswith("_") else label
        return ""

    def set_text_value(self, kind, key, text):
        """Give one editable object a new text, everything else unchanged."""
        text = str(text)
        if kind == "text":
            if key == "title":
                self.ax.set_title(
                    text, fontsize=self.fonts["title"],
                    color=safe_hex(self.fonts["title_color"], "#000000"),
                    pad=self.page_points(self.fonts["title_pad"]))
                self.ax.title.set_picker(True)
                self.apply_text_offset("title")   # set_title resets the place
            else:
                cfg = dict(self.axis_cfg[key])
                cfg["label"] = text
                self.apply_axis(key, cfg)
        elif kind == "note":
            state = self.note_state.get(key)
            if state is None:
                return None
            state["text"] = text
            self._marked = None            # the artist itself is rebuilt
            if not text.strip():
                self.remove_note(key)      # an empty text box goes away
                return None
            self.refresh_note(key)
        elif kind == "legend":
            line = self.series.get(key)
            if line is None:
                return None
            if self.series_style.get(key, self.plot_style) == "pie":
                # every row of a pie box belongs to one slice: the name goes
                # to that slice and the box is not switched off by an empty
                # text (the slice would have no name at all)
                self.set_pie_name(key, self.legend_row(key), text.strip())
                self._marked = None
                self.refresh_series_visuals(key)
                self.refresh_legend()
            else:
                line.set_label(text.strip() if text.strip() else "_nolegend_")
                self._marked = None
                self.refresh_legend()
        else:
            return None
        self._refresh_highlight()
        return None

    def inline_target(self, kind, key):
        """The artist an in-place editor would sit on, or None."""
        if kind == "note":
            return self.notes.get(key)
        if kind == "text":
            return self.text_artist(key) if self.text_shown(key) else None
        if kind == "legend":
            legend = self.legends.get(key)
            if legend is None:
                return None
            texts = list(legend.get_texts())
            if not texts:
                return None
            # a pie box has one row per slice: the one that was clicked is
            # the one that is written on, so every name stands on its own
            row = self.legend_row(key)
            return texts[row] if 0 <= row < len(texts) else texts[0]
        return None

    def legend_row(self, column):
        """Which row of a legend box was clicked last (0 when unknown)."""
        rows = getattr(self, "_legend_row", None) or {}
        try:
            return int(rows.get(str(column), 0))
        except (TypeError, ValueError):
            return 0

    def legend_row_at(self, legend, x, y):
        """The index of the legend row under the pointer, or None."""
        if legend is None or x is None or y is None:
            return None
        renderer = self._renderer()
        for index, text in enumerate(legend.get_texts()):
            try:
                box = text.get_window_extent(renderer)
            except (RuntimeError, ValueError, AttributeError):
                continue
            if box.expanded(1.25, 1.6).contains(x, y):
                return index
        return None

    def is_editing_inline(self):
        """True while a text is being written straight on the diagram."""
        return self._inline is not None

    def _inline_font(self, artist):
        """A Tk font of about the size the artist is drawn with."""
        try:
            points = float(artist.get_fontsize())
        except (AttributeError, TypeError, ValueError):
            points = 12.0
        pixels = max(8, int(round(points * float(self.fig.get_dpi()) / 72.0)))
        try:
            return tkfont.Font(family=INLINE_FAMILY, size=-pixels)
        except tk.TclError:
            return tkfont.Font(size=-pixels)

    def _inline_centre(self, artist):
        """The middle of a text, in pixels of the canvas widget."""
        widget = self.canvas.get_tk_widget()
        widget.update_idletasks()
        width_px = max(1, widget.winfo_width())
        height_px = max(1, widget.winfo_height())
        try:
            box = artist.get_window_extent(self._renderer())
            return (0.5 * (box.x0 + box.x1),
                    height_px - 0.5 * (box.y0 + box.y1))
        except (RuntimeError, ValueError, AttributeError):
            return (0.5 * width_px, 0.5 * height_px)

    def _inline_geometry(self, artist, font, value, centre=None):
        """Where the little editor goes and how big it is, in widget pixels.

        It is as wide as the text it holds plus the width of one more
        letter - room for the next one and for the cursor - and it stays
        centred on the text it rewrites, the way the label itself grows
        from its middle.
        """
        widget = self.canvas.get_tk_widget()
        width_px = max(1, widget.winfo_width())
        height_px = max(1, widget.winfo_height())
        if centre is None:
            centre = self._inline_centre(artist)
        lines = value.split("\n") or [""]
        text_w = max([font.measure(line) for line in lines] + [0])
        line_h = font.metrics("linespace")
        width = max(INLINE_MIN_WIDTH,
                    text_w + font.measure("M") + 2 * INLINE_PAD + 6)
        width = min(width, width_px)
        height = len(lines) * line_h + 2 * INLINE_PAD + 4
        x = int(round(centre[0] - width / 2.0))
        y = int(round(centre[1] - height / 2.0))
        x = max(0, min(x, width_px - int(width)))
        y = max(0, min(y, height_px - int(height)))
        return x, y, int(width), int(height)

    def begin_inline_edit(self, kind, key, x=None, y=None):
        """Open a small text box over one text, cursor where the pointer is.

        This is the second, slower click of the Finder-like rename: one click
        selects the object, a second one within RENAME_DELAY milliseconds -
        too slow to be a double click - lets the text itself be rewritten.
        """
        if kind not in EDITABLE_KINDS:
            return None
        artist = self.inline_target(kind, key)
        if artist is None:
            return None
        self.cancel_inline_edit()
        widget = self.canvas.get_tk_widget()
        value = self.text_value(kind, key)
        font = self._inline_font(artist)
        centre = self._inline_centre(artist)
        left, top, width, height = self._inline_geometry(artist, font, value,
                                                         centre)
        # the blinking cursor: its colour is set by hand, because the colour
        # the system gives it can be white - invisible on the white editor
        caret = max(2, int(round(font.metrics("linespace") / 9.0)))
        editor = tk.Text(widget, font=font, wrap="none", undo=True,
                         borderwidth=1, relief="solid", highlightthickness=1,
                         highlightcolor=SELECT_COLOR, highlightbackground=SELECT_COLOR,
                         padx=INLINE_PAD, pady=INLINE_PAD,
                         insertwidth=caret, insertborderwidth=0,
                         insertbackground=CARET_COLOR,
                         insertontime=CARET_ON_MS, insertofftime=CARET_OFF_MS,
                         selectbackground=SELECT_COLOR, selectforeground="#ffffff",
                         background="#ffffff", foreground="#000000")
        try:      # older Tk versions do not know this one
            editor.configure(insertunfocussed="hollow")
        except tk.TclError:
            pass
        editor.insert("1.0", value)
        # the arrow keys, Delete and copy/paste of the window would move or
        # remove the selected object: inside the editor they belong to the text
        editor.bindtags((str(editor), "Text", "all"))
        editor.bind("<Return>", self._inline_return)
        editor.bind("<KP_Enter>", self._inline_return)
        editor.bind("<Shift-Return>", lambda _e: None)
        editor.bind("<Escape>", lambda _e: (self.cancel_inline_edit(), "break")[1])
        editor.bind("<FocusOut>", lambda _e: self.commit_inline_edit())
        editor.place(x=left, y=top, width=width, height=height)
        self._inline = {"kind": kind, "key": key, "editor": editor,
                        "value": value, "artist": artist, "font": font,
                        "centre": centre, "size": (width, height)}
        # it grows (and shrinks) with what is written: every change of the
        # text - a key, a paste, Undo - fits it to its new width
        editor.edit_modified(False)
        editor.bind("<<Modified>>", self._inline_changed)
        editor.bind("<KeyRelease>", lambda _e: self.fit_inline_editor(), add="+")
        artist.set_visible(False)          # the editor takes its place
        self.draw()
        editor.focus_set()
        try:
            editor.update_idletasks()      # the text has to be laid out first
        except tk.TclError:
            pass
        if x is not None and y is not None:
            try:
                pointer_x = int(round(float(x))) - left
                pointer_y = int(round(widget.winfo_height() - float(y))) - top
                editor.mark_set("insert", f"@{pointer_x},{pointer_y}")
            except (tk.TclError, TypeError, ValueError):
                editor.mark_set("insert", "end")
        else:
            editor.mark_set("insert", "end")
        editor.see("insert")
        # the cursor only blinks in the widget that holds the keyboard, and
        # the click that opened the editor is still on its way to the canvas
        self._insist_inline_focus(editor)
        self.after(30, lambda box=editor: self._insist_inline_focus(box))
        self.flash("Write the text and press Enter - Escape keeps the old one")
        return editor

    def _inline_changed(self, _event=None):
        inline = self._inline
        if inline is None:
            return None
        try:
            inline["editor"].edit_modified(False)   # to hear the next one
        except tk.TclError:
            return None
        self.fit_inline_editor()
        return None

    def fit_inline_editor(self):
        """Make the open editor as wide (and as tall) as its text."""
        inline = self._inline
        if inline is None:
            return None
        editor = inline["editor"]
        text = self.inline_text()
        if text is None:
            return None
        left, top, width, height = self._inline_geometry(
            inline["artist"], inline["font"], text, inline["centre"])
        try:
            editor.place_configure(x=left, y=top, width=width, height=height)
            # whatever was scrolled out of the narrow box comes back
            editor.xview_moveto(0.0)
            editor.see("insert")
        except tk.TclError:
            return None
        inline["size"] = (width, height)
        return width, height

    def _insist_inline_focus(self, editor):
        """Keep the keyboard - and with it the blinking cursor - in the editor."""
        if self._inline is None or self._inline["editor"] is not editor:
            return None
        try:
            if not editor.winfo_exists():
                return None
            if editor.focus_displayof() is not editor:
                editor.focus_force()
        except (tk.TclError, KeyError):
            pass
        return None

    def _inline_return(self, _event=None):
        self.commit_inline_edit()
        return "break"

    def inline_text(self):
        """What the open editor holds at the moment, or None."""
        if self._inline is None:
            return None
        try:
            return self._inline["editor"].get("1.0", "end-1c")
        except tk.TclError:
            return None

    def _close_inline(self):
        """Take the editor away and show the text again."""
        inline, self._inline = self._inline, None
        self._pending_rename = None
        if inline is None:
            return None
        artist = inline["artist"]
        try:
            artist.set_visible(True)
        except AttributeError:
            pass
        editor = inline["editor"]
        try:
            if editor.winfo_exists():
                editor.destroy()
        except tk.TclError:
            pass
        self.take_focus()
        return inline

    def commit_inline_edit(self, _event=None):
        """Keep what was written and close the editor."""
        if self._inline is None:
            return None
        text = self.inline_text()
        inline = self._close_inline()
        if inline is None:
            return None
        if text is None:
            text = inline["value"]
        if text != inline["value"]:
            # writing on the graph is a command like any other: Undo takes
            # it back
            with self.changed("the text"):
                self.set_text_value(inline["kind"], inline["key"], text)
        self.select_object(inline["kind"], inline["key"])
        self._rename_click = None
        self.draw()
        return text

    def cancel_inline_edit(self, _event=None):
        """Throw the writing away and close the editor."""
        inline = self._close_inline()
        if inline is None:
            return None
        self._rename_click = None
        self.draw()
        return inline["value"]

    def _arm_inline_edit(self, kind, key, event):
        """Remember a slow second click on an already selected text.

        The editor is not opened here but when the button is released: a
        press that turns into a drag moves the text, exactly as before, and
        only a press-and-release on the same spot starts the writing.
        """
        now = time.monotonic()
        previous, self._rename_prev = self._rename_prev, None
        self._rename_click = (kind, key, now)
        self._pending_rename = None
        if (previous is None or previous[0] != kind or previous[1] != key
                or self.selection != (kind, key)
                or (now - previous[2]) * 1000.0 > RENAME_DELAY):
            return False
        self._rename_click = None
        self._pending_rename = {"kind": kind, "key": key,
                                "x": event.x, "y": event.y}
        return True

    def _open_pending_rename(self):
        """The release after a slow second click opens the little editor."""
        pending, self._pending_rename = self._pending_rename, None
        if pending is None or self._inline is not None:
            return None
        return self.begin_inline_edit(pending["kind"], pending["key"],
                                      pending["x"], pending["y"])

    # -- clipboard, keyboard moving and deleting ---------------------------
    def _axes_delta(self, dx_pixels, dy_pixels):
        """A pixel offset as an offset in the coordinates of the plot area."""
        inverse = self.ax.transAxes.inverted()
        origin = inverse.transform((0.0, 0.0))
        moved = inverse.transform((float(dx_pixels), float(dy_pixels)))
        return (float(moved[0] - origin[0]), float(moved[1] - origin[1]))

    @staticmethod
    def _shifted_state(kind, state, dx, dy):
        """A copy of one object state moved by (dx, dy) in axes coordinates."""
        moved = copy.deepcopy(state)
        if kind == "shape":
            moved["x"] = float(moved["x"]) + dx
            moved["y"] = float(moved["y"]) + dy
        elif kind == "arrow":
            for end in ("tail", "tip"):
                moved[end] = (float(moved[end][0]) + dx,
                              float(moved[end][1]) + dy)
        else:                                   # a text box
            moved["pos"] = (float(moved["pos"][0]) + dx,
                            float(moved["pos"][1]) + dy)
        return moved

    # -- which object is in front of which ---------------------------------
    def changed(self, label="the diagram"):
        """`with window.changed("..."):` remembers a command for Undo."""
        return PlotChange(self, label)

    def claim_key(self, kind, wanted=None):
        """The name a new object gets.

        Normally it is the next free one - `shape7`, `arrow2`, `note3`.
        When a diagram is rebuilt (opening a file, Undo, Redo) the names
        that were saved with it are asked for by `wanted`, so that an
        object keeps its name and stays the same object for everything
        that refers to it.
        """
        store = self.stack_store(kind) or {}
        counter = f"_{kind}_counter"
        if wanted:
            wanted = str(wanted)
            if wanted not in store:
                if wanted.startswith(kind) and wanted[len(kind):].isdigit():
                    number = int(wanted[len(kind):])
                    if number > getattr(self, counter, 0):
                        setattr(self, counter, number)
                return wanted
        while True:                      # never step on a name in use
            setattr(self, counter, getattr(self, counter, 0) + 1)
            key = f"{kind}{getattr(self, counter)}"
            if key not in store:
                return key

    def stack_store(self, kind):
        """The dictionary that keeps the state of one kind of object."""
        return {"shape": self.shape_state, "arrow": self.arrow_state,
                "note": self.note_state, "axis": self.axis_cfg}.get(kind)

    def axis_key(self, key):
        """The axis page ("x", "y", "y2") one name means.

        An axis is found under the pointer as the **side** of the plot area
        it is drawn on - "bottom", "left" and so on - while everything that
        is remembered about it belongs to its page.  Both names reach the
        same axis here.
        """
        name = str(key)
        if name in ("x", "y", "y2"):
            return name
        if name in FRAME_ENDS:
            return self.spine_owner(name)
        return None

    def axis_drawn(self, which):
        """True while this axis is drawn at all, line, ticks and numbers."""
        which = self.axis_key(which)
        if which is None or which not in self.axis_cfg:
            return False
        if self.axis_direction(which) == "off":
            return False
        if which == "y":
            return self.left_axis_shown()
        if which == "y2":
            return self.ax2 is not None and self.right_axis_active()
        return True

    def axis_artists(self, which):
        """Everything matplotlib draws for one axis, as artists.

        The `Axis` itself carries the tick marks, the numbers, the label -
        and the grid lines of that axis, which matplotlib draws inside it -
        so all of them travel together; the lines of the plot area it sits
        on are the rest of it.
        """
        which = self.axis_key(which)
        found = []
        if which == "x":
            found.append(self.ax.xaxis)
            found += [self.ax.spines[name] for name in HORIZONTAL_SIDES
                      if name in self.ax.spines]
        elif which == "y":
            found.append(self.ax.yaxis)
            if "left" in self.ax.spines:
                found.append(self.ax.spines["left"])
            if not self.right_axis_active() and "right" in self.ax.spines:
                found.append(self.ax.spines["right"])
        elif which == "y2":
            if self.ax2 is not None:
                found.append(self.ax2.yaxis)
            if self.right_axis_active() and "right" in self.ax.spines:
                found.append(self.ax.spines["right"])
        return found

    def apply_axis_z(self, which):
        """Put one axis, with everything drawn for it, at its own height."""
        which = self.axis_key(which)
        if which is None:
            return False
        cfg = self.axis_cfg.get(which) or {}
        z = cfg.get("z")
        z = float(Z_DEFAULT["axis"]) if z is None else float(z)
        for artist in self.axis_artists(which):
            try:
                artist.set_zorder(z)
            except (AttributeError, TypeError, ValueError):
                continue
        return True

    def apply_axis_stack(self):
        """Every axis back at the height it was given, after a redraw."""
        for which in ("x", "y", "y2"):
            self.apply_axis_z(which)
        return True

    def object_name(self, kind, key=None):
        """What one object is called in a menu or in a message."""
        if kind == "axis":
            side = self.axis_side(key) or str(key)
            return SIDE_NAMES.get(side, STACK_NAMES["axis"])
        if kind == "shape":
            state = self.shape_state.get(key) or {}
            if state.get("kind") == PICTURE_KIND:
                return STACK_NAMES["picture"]
        return STACK_NAMES.get(kind) or OBJECT_NAMES.get(kind, str(kind))

    def series_artists(self, name):
        """Every artist one curve is drawn with: the line, its filling ..."""
        found, seen = [], set()
        line = self.series.get(name)
        if line is not None:
            found.append(line)
            seen.add(id(line))
        for axes in self.plot_axes():
            for artist in list(axes.get_children()):
                if getattr(artist, "aplot_series", None) != str(name):
                    continue
                if id(artist) not in seen:
                    seen.add(id(artist))
                    found.append(artist)
        return found

    def set_series_zorder(self, name, z):
        """Put one curve - with everything drawn for it - at height `z`.

        A curve is more than one artist: the filling under it, its error
        bars, the bars of a bar chart.  They were laid out at distances of
        a few tenths from the line itself; the **order** of those parts is
        kept but the distances are squeezed together, so that the whole
        curve occupies one single place of the stack.  Without that, an
        object pushed behind the curve would still be drawn over its filled
        area - its outline showing through the filling.
        """
        line = self.series.get(name)
        if line is None:
            return False
        base = float(line.get_zorder())
        artists, offsets = [], []
        for artist in self.series_artists(name):
            offset = getattr(artist, "aplot_zoffset", None)
            if offset is None:
                offset = float(artist.get_zorder()) - base
                artist.aplot_zoffset = offset
            artists.append(artist)
            offsets.append(float(offset))
        span = (max(offsets) - min(offsets)) if offsets else 0.0
        scale = (Z_SERIES_SPREAD / span) if span > Z_SERIES_SPREAD else 1.0
        for artist, offset in zip(artists, offsets):
            try:
                artist.set_zorder(float(z) + offset * scale)
            except (AttributeError, TypeError, ValueError):
                continue
        self.series_z[str(name)] = float(z)
        return True

    def fill_zorder(self, column, line):
        """Where the filled area of one curve really is, for the export."""
        artist = self.fills.get(column)
        if artist is not None:
            try:
                return float(artist.get_zorder())
            except (AttributeError, TypeError, ValueError):
                pass
        return float(line.get_zorder()) - 0.5

    def apply_series_stack(self):
        """Give the curves the places they had after they were drawn again."""
        for name in list(self.series):
            z = self.series_z.get(str(name))
            if z is not None:
                self.set_series_zorder(name, z)
        return True

    def object_z(self, kind, key):
        """Where one object stands in the stack now, or None."""
        if kind == "axis":
            which = self.axis_key(key)
            if which is None or not self.axis_drawn(which):
                return None       # an axis that is not drawn is not a member
            z = (self.axis_cfg.get(which) or {}).get("z")
            return float(Z_DEFAULT["axis"]) if z is None else float(z)
        if kind == "series":
            if key not in self.series:
                return None
            stored = self.series_z.get(str(key))
            if stored is not None:
                return float(stored)
            line = self.series.get(key)
            return float(line.get_zorder()) if line is not None \
                else Z_DEFAULT["series"]
        store = self.stack_store(kind)
        state = None if store is None else store.get(key)
        if state is None:
            return None
        z = state.get("z")
        return float(z) if z is not None else float(Z_DEFAULT.get(kind, 5.0))

    def set_object_z(self, kind, key, z):
        """Put one object at height `z` and remember it there."""
        if kind == "series":
            return self.set_series_zorder(key, z)
        if kind == "axis":
            which = self.axis_key(key)
            if which is None or which not in self.axis_cfg:
                return False
            self.axis_cfg[which]["z"] = float(z)
            return self.apply_axis_z(which)
        store = self.stack_store(kind)
        state = None if store is None else store.get(key)
        if state is None:
            return False
        state["z"] = float(z)
        if kind == "shape":
            patch = self.shapes.get(key)
            if patch is not None:
                patch.set_zorder(float(z))
            picture = self.shape_pictures.get(key)
            if picture is not None:      # the pixels just under their frame
                picture.set_zorder(float(z) - Z_PICTURE_GAP)
        elif kind == "arrow":
            for artist in self.arrows.get(key) or []:
                artist.set_zorder(float(z))
        elif kind == "note":
            artist = self.notes.get(key)
            if artist is not None:
                artist.set_zorder(float(z))
        return True

    # -- the two axes lie one over the other -------------------------------
    def stack_side(self, kind, key):
        """"left" or "right": which of the two axes a member is drawn on.

        A curve belongs to the axes that carries its scale.  A drawing, a
        picture, an arrow or a text box belongs wherever the stack needs it
        to be - `stack_layers` works that out.
        """
        if kind == "series":
            return self.series_side(key)
        return (self._object_side or {}).get((kind, key), "left")

    def stack_layers(self, order=None):
        """Work out how the two axes have to lie for one stacking order.

        matplotlib draws one **axes** completely before the next one, and
        the per-artist heights only order the artists inside one of them.
        With a right hand Y axis in use the curves live on two axes, so an
        object could never be drawn between a curve of the one and a curve
        of the other - and that is why a drawing could not be brought in
        front of a curve of the right hand scale.

        The cure is to lay the two axes themselves in the right order and
        to hand every drawn object to the axes it has to be on: the ones
        below the first curve of the upper axes stay on the lower one, the
        ones above it are moved up.  It returns
        `(order, "left"/"right" on top, where each object goes)`.
        """
        order = self.stack_members() if order is None else list(order)
        sides = {}
        if self.ax2 is None:                 # one axes only: nothing to do
            return order, "right", {one: "left" for one in order
                                    if one[0] != "series"}
        last = {"left": -1, "right": -1}
        first = {"left": len(order), "right": len(order)}
        for index, (kind, key) in enumerate(order):
            if kind != "series":
                continue
            side = self.series_side(key)
            last[side] = max(last[side], index)
            first[side] = min(first[side], index)
        # the axes whose topmost curve is higher up is the one on top
        top = "right" if last["right"] >= last["left"] else "left"
        split = first[top]                   # its first curve
        bottom = "left" if top == "right" else "right"
        for index, (kind, key) in enumerate(order):
            if kind == "series":
                continue
            sides[(kind, key)] = bottom if index < split else top
        return order, top, sides

    def apply_stack_layers(self, order=None):
        """Lay the two axes in the order the stack asks for."""
        order, top, sides = self.stack_layers(order)
        previous = dict(self._object_side or {})
        self._object_side = sides
        self._top_side = top
        if self.ax2 is not None:
            # matplotlib draws the axes of a figure in the order of their
            # own height, and the one that is drawn last is on top
            self.ax.set_zorder(0.0 if top == "right" else 1.0)
            self.ax2.set_zorder(1.0 if top == "right" else 0.0)
            self.apply_axes_background()
        moved = [one for one in sides
                 if previous.get(one, "left") != sides[one]]
        for kind, key in moved:              # drawn again, on the other axes
            if kind == "shape":
                self.refresh_shape(key)
            elif kind == "arrow":
                self.refresh_arrow(key)
            elif kind == "note":
                self.refresh_note(key)
        if moved:
            self._refresh_handles()
        return top, sides

    def object_axes(self, kind=None, key=None):
        """The axes one drawn object has to be added to."""
        if self.ax2 is None:
            return self.ax
        side = (self._object_side or {}).get((kind, key), "left")
        return self.ax2 if side == "right" else self.ax

    def top_axes(self):
        """The one of the two axes that is drawn last, over the other."""
        if self.ax2 is None:
            return self.ax
        return self.ax2 if getattr(self, "_top_side", "right") == "right" \
            else self.ax

    def apply_axes_background(self, colour=None):
        """The colour of the plot area belongs to the axes at the bottom.

        Whichever of the two is drawn first carries it; the other one must
        stay clear, or it would paint over everything below it.
        """
        if colour is None:
            colour = (getattr(self, "frame_cfg", None) or {}).get("background",
                                                                  "#ffffff")
        colour = "none" if colour == "none" else colour
        axes = self.plot_axes()
        top = self.top_axes()
        # with one axes it carries the colour; with two, the lower of them
        lower = axes[0] if len(axes) < 2 else next(
            (one for one in axes if one is not top), axes[0])
        for one in axes:
            one.patch.set_visible(True)
            one.set_facecolor(colour if one is lower else "none")
        return lower

    def stack_members(self):
        """Every object that can change places, from the back to the front."""
        entries = []
        for rank, kind in enumerate(STACK_KINDS):
            keys = (list(self.series) if kind == "series"
                    else list(self.stack_store(kind) or {}))
            for order, key in enumerate(keys):
                z = self.object_z(kind, key)
                if z is None:
                    continue
                entries.append((z, rank, order, kind, key))
        entries.sort(key=lambda one: (one[0], one[1], one[2]))
        return [(kind, key) for _z, _rank, _order, kind, key in entries]

    def restack(self, *args, **kwargs):
        """One command: it can be taken back with Undo."""
        with self.changed('the order of the objects'):
            return self._restack(*args, **kwargs)

    def _restack(self, order=None, redraw=True):
        """Lay the whole stack out again, evenly, from the back forward."""
        order = self.stack_members() if order is None else list(order)
        # first which axes lies over which, and where every drawn object
        # belongs; then the heights inside each of them
        self.apply_stack_layers(order)
        if order:
            step = min(Z_STACK_STEP, Z_STACK_SPAN / float(len(order)))
            for index, (kind, key) in enumerate(order):
                self.set_object_z(kind, key, Z_STACK_BASE + index * step)
        if redraw:
            self.draw()
        return order

    def top_z(self, kinds=None):
        """The height a new object needs to stand in front of everything.

        The **axes** are left out of the count: their lines, tick marks and
        numbers are drawn over the diagram to begin with, and something
        newly drawn belongs in front of the other objects, not in front of
        the frame.  `Bring to front` still lifts anything over them.
        """
        kinds = tuple(kinds) if kinds else tuple(one for one in STACK_KINDS
                                                 if one != "axis")
        heights = [self.object_z(kind, key)
                   for kind, key in self.stack_members() if kind in kinds]
        heights = [one for one in heights if one is not None]
        return (max(heights) if heights else Z_STACK_BASE) + Z_STACK_STEP

    def stack_is_tidy(self):
        """True when every object really stands above the one before it.

        Two objects at the same height are drawn in the order matplotlib
        happens to hold them, which is not an order the user can change -
        and since the parts of a curve are drawn a little above its line,
        a tie can put one curve's error bars over another curve.  A file
        written before every curve was given a place of its own carries
        such ties, so `Bring to front` has to be able to break them.
        """
        heights = [self.object_z(kind, key)
                   for kind, key in self.stack_members()]
        heights = [one for one in heights if one is not None]
        return all(later > earlier
                   for earlier, later in zip(heights, heights[1:]))

    def move_in_stack(self, kind, key, step=1):
        """One step forward (step = 1) or backward (step = -1) in the stack.

        The object changes places with its neighbour, so one click moves it
        past exactly one other object - a drawing walks behind the curves
        one by one, and a curve can be brought out in front of the others.
        """
        if kind == "axis":
            key = self.axis_key(key)     # a side name means its axis page
        order = self.stack_members()
        try:
            index = order.index((kind, key))
        except ValueError:
            return False
        target = max(0, min(len(order) - 1, index + int(step)))
        if target == index:
            if not self.stack_is_tidy():
                # it cannot move any further, but the stack has objects
                # standing at the same height: laying it out again is what
                # the user asked for, and it does show
                self.restack(order)
                self.flash(f"{self.object_name(kind, key)} is "
                           + ("in front of everything now" if step > 0
                              else "behind everything now"))
                return True
            self.flash(f"{self.object_name(kind, key)} is already "
                       + ("in front of everything" if step > 0
                          else "behind everything"))
            return False
        order.insert(target, order.pop(index))
        self.restack(order)
        name = self.object_name(kind, key)
        if target == len(order) - 1:
            self.flash(f"{name} is in front of everything now")
        elif target == 0:
            self.flash(f"{name} is behind everything now")
        else:
            neighbour = order[index]     # the one it changed places with
            self.flash(f"{name} moved "
                       + ("in front of " if step > 0 else "behind ")
                       + self.object_name(*neighbour).lower())
        return True

    def bring_to_front(self, kind, key):
        return self.move_in_stack(kind, key, len(self.stack_members()))

    def send_to_back(self, kind, key):
        return self.move_in_stack(kind, key, -len(self.stack_members()))

    # -- what the right click found ---------------------------------------
    def _mouse_event(self, x, y, button=1):
        """A matplotlib click at one point of the canvas, for the hit tests."""
        try:
            return MouseEvent("button_press_event", self.canvas,
                              float(x), float(y), button)
        except (TypeError, ValueError, AttributeError):
            return None

    def stack_object_at(self, x, y):
        """(kind, key) of the object under the pointer, the front one first.

        Unlike `object_at`, which asks the kinds of object in a fixed order,
        this one asks the **stack**: what is drawn in front is what the
        pointer finds, so a curve that was brought forward is picked
        before the drawing it now covers.
        """
        candidates = []
        for kind, finder in (("arrow", self.arrow_at), ("shape", self.shape_at),
                             ("note", self.note_at)):
            key = finder(x, y)
            if key is not None:
                candidates.append((kind, key))
        name = self.series_at(self._mouse_event(x, y))
        if name is not None:
            candidates.append(("series", name))
        side = self.frame_side_at(x, y)
        if side is not None and self.axis_key(side) is not None:
            candidates.append(("axis", self.axis_key(side)))
        if not candidates:
            return (None, None)
        candidates.sort(key=lambda one: self.object_z(*one) or 0.0)
        return candidates[-1]

    def show_object_menu(self, x, y, root_x=None, root_y=None):
        """The menu of a right click: copy, cut, paste, duplicate, stacking.

        It opens over any object - a drawing, a picture, an arrow, a text
        box or a curve - and over the empty paper as well, where the only
        thing that can be done is pasting.
        """
        kind, key = self.stack_object_at(x, y)
        point = self._axes_point_at(x, y)
        if kind in ("shape", "arrow", "note"):
            self.select_object(kind, key)      # show what the menu works on
            self.draw()
        menu = tk.Menu(self, tearoff=0)
        able = "normal" if kind in COPYABLE else "disabled"
        stackable = "normal" if kind is not None else "disabled"
        menu.add_command(label=(self.object_name(kind, key) if kind is not None
                                else "The paper of the diagram"),
                         state="disabled")
        menu.add_separator()
        menu.add_command(label="Copy", accelerator=f"{ACCEL_NAME}+C", state=able,
                         command=lambda: self.copy_object(kind, key))
        menu.add_command(label="Cut", accelerator=f"{ACCEL_NAME}+X", state=able,
                         command=lambda: self.cut_object(kind, key))
        menu.add_command(label="Paste", accelerator=f"{ACCEL_NAME}+V",
                         command=lambda: self.paste_clipboard(at=point))
        menu.add_command(label="Duplicate", accelerator=f"{ACCEL_NAME}+D",
                         state=able,
                         command=lambda: self.duplicate_object(kind, key))
        menu.add_separator()
        menu.add_command(label="Bring to front", state=stackable,
                         command=lambda: self.bring_to_front(kind, key))
        menu.add_command(label="Bring forward", state=stackable,
                         command=lambda: self.move_in_stack(kind, key, 1))
        menu.add_command(label="Send backward", state=stackable,
                         command=lambda: self.move_in_stack(kind, key, -1))
        menu.add_command(label="Send to back", state=stackable,
                         command=lambda: self.send_to_back(kind, key))
        if kind is None:               # the paper: the size of the graph
            menu.add_separator()
            sizes = tk.Menu(menu, tearoff=0)
            sizes.add_command(
                label="Smaller",
                command=lambda: self.scale_plot_area(1.0 - PLOT_RESIZE_STEP))
            sizes.add_command(
                label="Larger",
                command=lambda: self.scale_plot_area(1.0 + PLOT_RESIZE_STEP))
            sizes.add_command(label="Fit to page", command=self.fit_to_page)
            menu.add_cascade(label="Resize graph", menu=sizes)
            self._resize_menu = sizes           # kept, or Tk lets it go
        self._object_menu = menu                # kept, or Tk lets it go
        if root_x is None or root_y is None:
            widget = self.canvas.get_tk_widget()
            root_x = widget.winfo_rootx() + int(x)
            root_y = widget.winfo_rooty() + int(widget.winfo_height() - y)
        try:
            menu.tk_popup(int(root_x), int(root_y))
        except tk.TclError:
            return None
        finally:
            try:
                menu.grab_release()
            except tk.TclError:
                pass
        return menu

    def _axes_point_at(self, x, y):
        """One point of the canvas in axes coordinates."""
        try:
            point = self.ax.transAxes.inverted().transform((float(x), float(y)))
        except (ValueError, TypeError):
            return (0.5, 0.5)
        return (float(point[0]), float(point[1]))

    # -- copy, cut and paste ----------------------------------------------
    def copy_object(self, kind, key):
        """Keep one object, with all of its properties, for pasting."""
        store = self.stack_store(kind) if kind in COPYABLE else None
        state = None if store is None else store.get(key)
        if state is None:
            if kind is None:
                self.flash("Select an object first, then copy it")
            else:
                self.flash(f"{self.object_name(kind, key)} cannot be copied - "
                           "text boxes, drawings, pictures and arrows can")
            return None
        PlotWindow._clipboard = {
            "kind": kind, "pasted": 0,
            "state": {name: value for name, value in copy.deepcopy(state).items()
                      if not str(name).startswith("_")}}
        PlotWindow._clipboard_stamp = time.monotonic()
        self.remember_clipboard()
        self.flash(f"{self.object_name(kind, key)} copied - "
                   f"paste it with {PASTE_HINT}")
        return kind

    def cut_object(self, *args, **kwargs):
        """One command: it can be taken back with Undo."""
        with self.changed('cutting out'):
            return self._cut_object(*args, **kwargs)

    def _cut_object(self, kind, key):
        """Copy one object and take it out of the diagram."""
        if self.copy_object(kind, key) is None:
            return None
        remover = {"shape": self.remove_shape, "arrow": self.remove_arrow,
                   "note": self.remove_note}.get(kind)
        if remover is None:
            return None
        name = self.object_name(kind, key)
        remover(key)
        self.flash(f"{name} cut out - paste it with {PASTE_HINT}")
        return kind

    def duplicate_object(self, kind=None, key=None):
        """A second copy of one object, a little beside the first one.

        It does not touch the clipboard: what was copied before is still
        there to be pasted afterwards.
        """
        if kind is None:
            kind, key = self.selection or (None, None)
        store = self.stack_store(kind) if kind in COPYABLE else None
        state = None if store is None else store.get(key)
        if state is None:
            self.flash("Select a text box, a drawing, a picture or an arrow "
                       "to duplicate it")
            return None
        with self.changed("the copy"):
            clean = {name: value
                     for name, value in copy.deepcopy(state).items()
                     if not str(name).startswith("_")}
            dx, dy = self._axes_delta(PASTE_STEP, -PASTE_STEP)
            moved = self._shifted_state(kind, clean, dx, dy)
            moved.pop("z", None)          # the copy goes in front
            if kind == "shape":
                made = self.add_shape(state=moved)
            elif kind == "arrow":
                made = self.add_arrow(state=moved)
            else:
                made = self.add_note(moved["pos"], state=moved)
            self.select_object(kind, made)
            self.draw()
        self.flash(f"{self.object_name(kind, made)} duplicated")
        return made

    def copy_selection(self, _event=None):
        """Ctrl/Cmd+C: keep the selected object with all of its properties."""
        kind, key = self.selection or (None, None)
        if kind is not None and kind not in COPYABLE:
            self.flash(f"{OBJECT_NAMES.get(kind, kind)} cannot be copied - "
                       "text boxes, drawings and arrows can")
            return None
        return self.copy_object(kind, key)

    def duplicate_selection(self, _event=None):
        """Ctrl/Cmd+D: a second copy of the selected object."""
        return self.duplicate_object()

    def cut_selection(self, _event=None):
        """Ctrl/Cmd+X: the selected object goes to the clipboard and away."""
        kind, key = self.selection or (None, None)
        if kind is None:
            self.flash("Select an object first, then cut it")
            return None
        return self.cut_object(kind, key)

    def _stack_command(self, step):
        """One of the four stacking commands, on whatever is selected."""
        kind, key = self.selection or (None, None)
        if kind is None:
            self.flash("Select an object first, or use the right button on it")
            return False
        return self.move_in_stack(kind, key, step)

    def front_selection(self, _event=None):
        """The menu: the selected object in front of everything."""
        return self._stack_command(len(self.stack_members()) or 1)

    def raise_selection(self, _event=None):
        """The menu: one step forward with the selected object."""
        return self._stack_command(1)

    def lower_selection(self, _event=None):
        """The menu: one step backward with the selected object."""
        return self._stack_command(-1)

    def back_selection(self, _event=None):
        """The menu: the selected object behind everything."""
        return self._stack_command(-(len(self.stack_members()) or 1))

    def paste_clipboard(self, *args, **kwargs):
        """One command: it can be taken back with Undo."""
        with self.changed('pasting'):
            return self._paste_clipboard(*args, **kwargs)

    def remember_clipboard(self):
        """Write down what is on the clipboard of the system just now.

        Every copy of this program - an object or the whole figure - ends
        with this, so that a paste afterwards can tell whether anything
        *else* has been copied in the meantime.
        """
        try:
            widget = self.canvas.get_tk_widget()
        except (AttributeError, tk.TclError):
            widget = None
        PlotWindow._clipboard_serial = clipboard_serial(widget)
        return PlotWindow._clipboard_serial

    def clipboard_came_from_outside(self):
        """True when another program has copied since this program did.

        A picture copied in a presentation program, a browser or a photo
        editor carries no time of its own, so the clipboard itself is
        asked: if it no longer holds what it held at the last copy of this
        program, then it holds something newer, and that is what a paste
        must take.
        """
        mark = PlotWindow._clipboard_serial
        if mark is None:
            return False               # this system cannot tell: assume not

        try:
            widget = self.canvas.get_tk_widget()
        except (AttributeError, tk.TclError):
            widget = None
        now = clipboard_serial(widget)
        return now is not None and now != mark

    def _paste_clipboard(self, _event=None, at=None):
        """Ctrl/Cmd+V: the copied object, or a picture from the clipboard.

        Two things can be waiting: an object copied inside the program, and
        a picture on the clipboard of the system.  **The newer of the two
        wins.**

        Between the program's own two ways of copying - an object and
        `Copy figure to the clipboard` - the time of the copy decides, so
        copying the figure and then an object pastes the object, and the
        other way round pastes the picture.

        A picture copied in *another* program carries no time of its own.
        For that one the clipboard of the system is compared with what it
        held when this program last copied: when it has changed since, the
        picture is the newer thing and it wins over the object that is
        still being kept here.  `at` is a point of the plot area - the menu
        of a right click pastes where the pointer was.
        """
        data = PlotWindow._clipboard
        mine_is_newer = bool(data) and (PlotWindow._clipboard_stamp
                                        >= PlotWindow._figure_stamp)
        if mine_is_newer and self.clipboard_came_from_outside():
            mine_is_newer = False      # another program copied after us
        if not mine_is_newer:
            key = self.paste_picture(centre=at)
            if key is not None:
                return key
        if not data:
            self.flash("Nothing has been copied yet - copy an object, or a "
                       "picture in another program")
            return None
        kind = data["kind"]
        if at is not None:                      # pasted where it was asked for
            dx, dy = self._to_point_delta(kind, data["state"], at)
        else:
            data["pasted"] += 1                 # repeated pastes cascade
            step = PASTE_STEP * data["pasted"]
            dx, dy = self._axes_delta(step, -step)
        state = self._shifted_state(kind, data["state"], dx, dy)
        if kind == "shape":
            key = self.add_shape(state=state)
        elif kind == "arrow":
            key = self.add_arrow(state=state)
        else:
            key = self.add_note(state["pos"], state=state)
        self.select_object(kind, key)
        self.draw()
        self.flash(f"{self.object_name(kind, key)} pasted")
        return key

    @staticmethod
    def _to_point_delta(kind, state, point):
        """How far one object must move to sit around `point`."""
        if kind == "shape":
            now = (float(state["x"]) + float(state["w"]) / 2.0,
                   float(state["y"]) + float(state["h"]) / 2.0)
        elif kind == "arrow":
            now = ((float(state["tail"][0]) + float(state["tip"][0])) / 2.0,
                   (float(state["tail"][1]) + float(state["tip"][1])) / 2.0)
        else:
            now = (float(state["pos"][0]), float(state["pos"][1]))
        return (float(point[0]) - now[0], float(point[1]) - now[1])

    def nudge_selection(self, *args, **kwargs):
        """One command: it can be taken back with Undo."""
        with self.changed('moving the object'):
            return self._nudge_selection(*args, **kwargs)

    def _nudge_selection(self, dx_pixels, dy_pixels):
        """Move the selected object (or every object of the group) with the
        arrow keys."""
        if self.group:
            moved = self.move_group(dx_pixels, dy_pixels)
            self.draw()
            return moved
        kind, key = self.selection or (None, None)
        state = self.selected_state()
        if state is None:
            return False
        if kind == "axis":
            return self.move_axes(dx_pixels, dy_pixels)
        self._move_object(kind, key, dx_pixels, dy_pixels)
        self._refresh_handles()
        self._refresh_highlight()
        self.draw()
        return True

    # -- several objects at once: the rectangle drawn on the background ---
    GROUP_KINDS = ("legend", "note", "text", "shape", "arrow")

    def object_extent(self, kind, key):
        """The box one object covers on the screen (pixels), or None."""
        renderer = self._renderer()
        artist = None
        try:
            if kind == "legend":
                artist = self.legends.get(key)
            elif kind == "note":
                artist = self.notes.get(key)
            elif kind == "text":
                artist = (self.text_artist(key) if self.text_shown(key)
                          else None)
            elif kind == "shape":
                artist = self.shapes.get(key)
            elif kind == "arrow":
                parts = [one.get_window_extent(renderer)
                         for one in (self.arrows.get(key) or [])]
                return Bbox.union(parts) if parts else None
            if artist is None or not artist.get_visible():
                return None
            return artist.get_window_extent(renderer)
        except (RuntimeError, ValueError, AttributeError, TypeError):
            return None

    def group_candidates(self):
        """Every object a rectangle can take, topmost kinds first."""
        found = [("arrow", key) for key in self.arrow_state]
        found += [("shape", key) for key in self.shape_state]
        found += [("note", key) for key in self.note_state]
        found += [("legend", key) for key in self.legends]
        found += [("text", name) for name in ("title", "x", "y", "y2")
                  if self.text_shown(name)]
        return found

    def objects_in(self, box):
        """The objects the rectangle `box` (pixels) touches."""
        touched = []
        for kind, key in self.group_candidates():
            extent = self.object_extent(kind, key)
            if extent is None:
                continue
            if (extent.x1 >= box.x0 and extent.x0 <= box.x1
                    and extent.y1 >= box.y0 and extent.y0 <= box.y1):
                touched.append((kind, key))
        return touched

    def set_group(self, members):
        """Choose these objects together (one of them is simply selected)."""
        members = [tuple(one) for one in members
                   if one[0] in self.GROUP_KINDS
                   and one[1] in (self._selection_store(one[0]) or {})]
        unique = []
        for one in members:
            if one not in unique:
                unique.append(one)
        if len(unique) == 1:
            self.group = []
            self.select_object(*unique[0])
            self.announce_selection()
        else:
            if self.selection is not None:
                self.select_object(None, None)
            self.group = unique
            if unique:
                self.flash(f"{len(unique)} objects selected - drag any of "
                           "them to move them all, or use the arrow keys")
        self._refresh_group_marks()
        return list(self.group)

    def clear_group(self):
        if self.group:
            self.group = []
            self._refresh_group_marks()
            return True
        return False

    def in_group(self, kind, key):
        return (kind, key) in self.group

    def _refresh_group_marks(self):
        """A light blue box around every object of the group."""
        for mark in self._group_marks:
            try:
                mark.remove()
            except (ValueError, AttributeError):
                pass
        self._group_marks = []
        # what was taken away in the meantime (Undo, Delete) leaves the group
        self.group = [(kind, key) for kind, key in self.group
                      if key in (self._selection_store(kind) or {})]
        if not self.group or self._group_hidden:
            return 0
        for kind, key in self.group:
            box = self.object_extent(kind, key)
            if box is None:
                continue
            pad = 3.0
            mark = Rectangle((box.x0 - pad, box.y0 - pad),
                             box.width + 2 * pad, box.height + 2 * pad,
                             transform=IdentityTransform(),
                             facecolor=SELECT_FACE, edgecolor=SELECT_EDGE,
                             linewidth=1.2, zorder=1000, clip_on=False)
            mark.set_in_layout(False)      # a mark, not a part of the picture
            self.fig.add_artist(mark)
            self._group_marks.append(mark)
        return len(self._group_marks)

    def hide_group_marks(self, hidden=True):
        """Leave the marks off a picture that is being saved (or put them back)."""
        self._group_hidden = bool(hidden)
        self._refresh_group_marks()

    def move_group(self, dx_pixels, dy_pixels):
        """Shift every object of the group by the same number of pixels."""
        moved = False
        for kind, key in list(self.group):
            moved = self._move_object(kind, key, dx_pixels, dy_pixels) or moved
        self._refresh_group_marks()
        return moved

    def numbers_at(self, x, y):
        """The axis whose numbers are under the pointer ("x", "y", "y2")."""
        if x is None or y is None:
            return None
        renderer = self._renderer()
        axes = [("x", self.ax.xaxis), ("y", self.ax.yaxis)]
        if self.ax2 is not None:
            axes.append(("y2", self.ax2.yaxis))
        for which, axis in axes:
            try:
                low, high = sorted(axis.get_view_interval())
            except (ValueError, TypeError):
                continue
            span = abs(high - low) * 1e-6
            for tick in axis.get_major_ticks():
                try:
                    where = float(tick.get_loc())
                except (TypeError, ValueError):
                    continue
                if not (low - span <= where <= high + span):
                    continue            # a tick matplotlib does not draw
                for label in (tick.label1, tick.label2):
                    if not (label.get_visible() and label.get_text()):
                        continue
                    try:
                        box = label.get_window_extent(renderer)
                    except (RuntimeError, ValueError, AttributeError):
                        continue
                    if box.expanded(1.15, 1.4).contains(x, y):
                        return which
        return None

    def _start_band(self, event):
        """The button went down on the background: a rectangle begins."""
        if event is None or event.x is None or event.y is None \
                or self.toolbar_busy():
            self._band = None
            return None
        adding = self._shift_active(event)
        base = list(self.group)
        if adding and not base and self.selection is not None \
                and self.selection[0] in self.GROUP_KINDS:
            base = [tuple(self.selection)]
        if not adding:
            base = []
            if self.selection is not None:
                self.select_object(None, None)
            if self.clear_group():
                self.draw()
        self._band = {"x0": float(event.x), "y0": float(event.y),
                      "x1": float(event.x), "y1": float(event.y),
                      "base": base, "moved": False}
        return self._band

    def _band_box(self, band=None):
        band = self._band if band is None else band
        return Bbox.from_extents(min(band["x0"], band["x1"]),
                                 min(band["y0"], band["y1"]),
                                 max(band["x0"], band["x1"]),
                                 max(band["y0"], band["y1"]))

    def _stretch_band(self, event):
        band = self._band
        if band is None or event.x is None or event.y is None:
            return False
        band["x1"], band["y1"] = float(event.x), float(event.y)
        if abs(band["x1"] - band["x0"]) > 3 or abs(band["y1"] - band["y0"]) > 3:
            band["moved"] = True
        box = self._band_box()
        if self._band_patch is None:
            self._band_patch = Rectangle(
                (box.x0, box.y0), box.width, box.height,
                transform=IdentityTransform(), facecolor=SELECT_FACE,
                edgecolor=SELECT_EDGE, linewidth=1.0, linestyle="--",
                zorder=1001, clip_on=False)
            self._band_patch.set_in_layout(False)
            self.fig.add_artist(self._band_patch)
        else:
            self._band_patch.set_bounds(box.x0, box.y0, box.width, box.height)
        # what the rectangle touches is marked while it is being drawn
        if band["moved"]:
            self.group = band["base"] + [one for one in self.objects_in(box)
                                         if one not in band["base"]]
            self._refresh_group_marks()
        self.draw()
        return True

    def _finish_band(self):
        band, self._band = self._band, None
        if self._band_patch is not None:
            try:
                self._band_patch.remove()
            except (ValueError, AttributeError):
                pass
            self._band_patch = None
        if band is None:
            return None
        if not band["moved"]:              # a plain click on the background
            self.group = band["base"]
            self._refresh_group_marks()
            self.draw()
            return []
        box = self._band_box(band)
        members = band["base"] + [one for one in self.objects_in(box)
                                  if one not in band["base"]]
        chosen = self.set_group(members)
        self.draw()
        return chosen if chosen else ([self.selection] if self.selection
                                      else [])

    def _move_object(self, kind, key, dx_pixels, dy_pixels):
        """Shift one object by a number of pixels, whatever kind it is."""
        store = self._selection_store(kind)
        state = None if store is None else store.get(key)
        if state is None:
            return False
        dx, dy = self._axes_delta(dx_pixels, dy_pixels)
        if kind == "text":
            # the title and the axis labels keep their shift in points
            offset = self.text_offset[key]
            self.text_offset[key] = (offset[0] + self.points(dx_pixels),
                                     offset[1] + self.points(dy_pixels))
            self.apply_text_offset(key)
        elif kind == "legend":
            position = (float(state["pos"][0]) + dx,
                        float(state["pos"][1]) + dy)
            state["pos"] = position
            legend = self.legends.get(key)
            if legend is not None:
                legend.set_bbox_to_anchor(position, transform=self.ax.transAxes)
        else:
            state.update(self._shifted_state(kind, state, dx, dy))
            if kind == "shape":
                self.refresh_shape(key)
            elif kind == "arrow":
                self.refresh_arrow(key)
            else:
                self._move_note(key, state["pos"])
        return True

    def delete_selection(self, _event=None):
        """Delete or Backspace: remove the selected object.

        With a group chosen, every drawing, arrow and text box of it goes
        (in one step of Undo); a legend box or an axis label cannot be
        deleted, so those simply stay.
        """
        if self.group:
            removable = [(kind, key) for kind, key in self.group
                         if kind in ("shape", "arrow", "note")]
            if not removable:
                self.flash("Legend boxes and axis texts cannot be deleted")
                return False
            with self.changed("deleting the objects"):
                for kind, key in removable:
                    {"shape": self.remove_shape, "arrow": self.remove_arrow,
                     "note": self.remove_note}[kind](key)
            self.set_group([one for one in self.group
                            if one not in removable])
            self.draw()
            return True
        kind, key = self.selection or (None, None)
        remover = {"shape": self.remove_shape, "arrow": self.remove_arrow,
                   "note": self.remove_note}.get(kind)
        if remover is None:
            return False
        remover(key)
        return True

    def announce_selection(self):
        """Tell in the toolbar what is selected and what a second click does."""
        kind, _key = self.selection or (None, None)
        if kind is None:
            return
        self.flash(f"{OBJECT_NAMES.get(kind, kind)} selected - "
                   "click it again for its properties")

    def close_window(self, *_args):
        """The window button: an edited graph is not thrown away silently."""
        app = self.app
        if app is not None and hasattr(app, "plot_closing"):
            if not app.plot_closing(self):
                return False
        self.destroy()
        if app is not None and hasattr(app, "plot_closed"):
            app.plot_closed(self)
        return True

    def figure_image(self, path=None, dpi=None, transparent=None):
        """Write a picture of the diagram, without the selection marks."""
        if path is None:
            path = os.path.join(tempfile.gettempdir(),
                                f"aplot_figure_{os.getpid()}.png")
        selection = self.selection
        self.select_object(None, None)
        self.hide_group_marks(True)
        try:
            self.canvas.draw()
            if transparent is None:
                transparent = self.frame_cfg.get("figure_background") == "none"
            # the picture is of the page, not of the zoomed view
            self.fig.savefig(path, dpi=dpi or self.base_dpi,
                             bbox_inches="tight", pad_inches=EXPORT_PAD,
                             transparent=bool(transparent),
                             facecolor=self.fig.get_facecolor())
        finally:
            self.hide_group_marks(False)
            if selection is not None:
                self.select_object(*selection)
            self.canvas.draw_idle()
        return path

    def thumbnail_background(self):
        """The paper colour of the thumbnail: the colour chosen around the
        axes, or white when that is transparent - a file manager draws the
        picture on its own background, light or dark."""
        paper = self.frame_cfg.get("figure_background", "#ffffff")
        if paper == "none":
            return "#ffffff"
        return safe_hex(paper, "#ffffff")

    def preview_page(self, pdf):
        """This diagram as one page of the preview PDF (`PdfPages`)."""
        selection = self.selection
        self.select_object(None, None)
        self.hide_group_marks(True)
        try:
            self.canvas.draw()
            pdf.savefig(self.fig, bbox_inches="tight",
                        pad_inches=THUMBNAIL_PAD, transparent=False,
                        facecolor=self.thumbnail_background(),
                        edgecolor="none")
        finally:
            self.hide_group_marks(False)
            if selection is not None:
                self.select_object(*selection)
            self.canvas.draw_idle()
        return True

    def thumbnail_png(self, size=THUMBNAIL_SIZE):
        """A small picture of the graph, as PNG bytes.

        The graph is cut out of the page the way `Copy figure` does it, and
        drawn so that its longer side is `size` pixels.  It is never
        transparent: the paper is the colour around the axes, or white.
        The selection marks are not on it.
        """
        selection = self.selection
        self.select_object(None, None)
        self.hide_group_marks(True)
        try:
            self.canvas.draw()
            renderer = self.canvas.get_renderer()
            box = self.fig.get_tightbbox(renderer)      # in inches
            longest = max(float(box.width), float(box.height)) \
                + 2.0 * THUMBNAIL_PAD
            dpi = max(8.0, float(size) / max(longest, 1e-3))
            holder = io.BytesIO()
            self.fig.savefig(holder, format="png", dpi=dpi,
                             bbox_inches="tight", pad_inches=THUMBNAIL_PAD,
                             transparent=False,
                             facecolor=self.thumbnail_background(),
                             edgecolor="none")
        finally:
            self.hide_group_marks(False)
            if selection is not None:
                self.select_object(*selection)
            self.canvas.draw_idle()
        return holder.getvalue()

    def copy_figure_to_clipboard(self, *_args):
        """Cmd/Ctrl+C with nothing selected: the whole diagram as a picture."""
        try:
            path = self.figure_image(dpi=CLIPBOARD_DPI)
        except (OSError, ValueError) as error:
            messagebox.showerror("Error", f"Could not draw the picture: {error}",
                                 parent=self)
            return False
        if copy_png_to_clipboard(path):
            PlotWindow._figure_stamp = time.monotonic()
            self.remember_clipboard()
            self.flash("The diagram is on the clipboard as a picture")
            return True
        messagebox.showinfo(
            "Clipboard",
            "This system has no tool to put a picture on the clipboard.\n"
            f"The picture was written to:\n{path}", parent=self)
        return False

    def copy_shortcut(self, *_args):
        """Cmd/Ctrl+C: the selected object, or the whole diagram as a picture."""
        if self.selection is not None:
            return self.copy_selection()
        return self.copy_figure_to_clipboard()

    def export_figure(self, *_args):
        """Save the diagram as an image file, without the selection marks."""
        return self.save_figure_clean()

    def save_figure_clean(self, *_args):
        """Write the diagram to a file: the graph, not the whole page.

        What is saved is what `Copy figure to the clipboard` copies - the
        graph and everything drawn beside it, cut out of the page with a
        little air around it - so that the two ways out of the program
        give the same picture.  The selection marks are never on it.
        """
        selection = self.selection
        self.select_object(None, None)
        self.hide_group_marks(True)
        try:
            self.canvas.draw()
            # matplotlib's own dialog knows every format it can write, and
            # it is told through the settings to cut the page down
            # the picture is of the page at its own resolution: how far
            # the view happens to be zoomed must not change the file
            settings = {"savefig.bbox": "tight",
                        "savefig.pad_inches": EXPORT_PAD,
                        "savefig.dpi": float(self.base_dpi)}
            if self.frame_cfg.get("figure_background") == "none":
                settings["savefig.transparent"] = True
            with matplotlib.rc_context(settings):
                written = self.toolbar.save_figure()
                # the dialog remembers the folder in the same settings,
                # which would be forgotten again when this block ends
                folder = matplotlib.rcParams["savefig.directory"]
            matplotlib.rcParams["savefig.directory"] = folder
            return written
        finally:
            self.hide_group_marks(False)
            if selection is not None:
                self.select_object(*selection)
            self.canvas.draw_idle()

    def flash(self, message):
        """A short note in the message area of the toolbar."""
        try:
            self.toolbar.set_message(message)
            self.after(2500, lambda: self.toolbar.set_message(""))
        except (tk.TclError, AttributeError):
            pass

    def shape_handle_positions(self, state):
        """The eight control points, turned with the object."""
        points = self.handle_positions(state)
        angle = self.angle_of(state)
        if not angle:
            return points
        centre = self.shape_centre(state)
        return [self._turn_point(point, centre, angle) for point in points]

    def selected_handle_positions(self):
        kind, key = self.selection or (None, None)
        if kind == "axis" and self.axis_side(key) is not None:
            return self.axis_handle_positions(key)
        if kind == "shape" and key in self.shape_state:
            state = self.shape_state[key]
            if state["kind"] in OPEN_SHAPES:
                return list(self.line_ends(state))   # the two ends, as an arrow
            return self.shape_handle_positions(state)
        if kind == "arrow" and key in self.arrow_state:
            return self.arrow_handle_positions(self.arrow_state[key])
        return None

    @staticmethod
    def handle_alpha():
        """The opacity of the control points: None (solid) unless
        TRANSPARENT_HANDLES is switched on."""
        return HANDLE_ALPHA if TRANSPARENT_HANDLES else None

    def handle_scale(self):
        """Points of the page for one point of the screen: the control
        points are drawn on the page, which the zoom makes larger, but
        they keep their size on the screen."""
        try:
            zoom = float(self.zoom)
        except (AttributeError, TypeError, ValueError):
            zoom = 1.0
        return 1.0 / zoom if zoom > 0 else 1.0

    def _refresh_handles(self):
        points = self.selected_handle_positions()
        # the control points belong on the axes that is drawn last, or the
        # curves of the upper one would be painted over them
        host = self.top_axes()
        if (self._handles is not None
                and getattr(self._handles, "axes", None) is not host):
            try:
                self._handles.remove()
            except (ValueError, AttributeError):
                pass
            self._handles = None
        if self._handles is None and points is not None:
            self._handles, = host.plot(
                [], [], linestyle="none", marker="s",
                markerfacecolor="#ffffff", markeredgecolor=HANDLE_COLOR,
                alpha=self.handle_alpha(), transform=self.ax.transAxes,
                clip_on=False, zorder=8, label="_nolegend_")
            # a control point is a tool, not a part of the picture: it must
            # not make a saved image any bigger
            self._handles.set_in_layout(False)
        if self._handles is not None:
            scale = self.handle_scale()
            self._handles.set_markersize(HANDLE_SIZE * scale)
            self._handles.set_markeredgewidth(HANDLE_EDGE * scale)
            if points is None:
                self._handles.set_data([], [])
            else:
                self._handles.set_data([p[0] for p in points],
                                       [p[1] for p in points])
        self._refresh_rotation_handle()

    def _refresh_rotation_handle(self):
        """The round control point that turns a drawing or a text box."""
        point = self.rotation_handle_position()
        host = self.top_axes()
        if (self._rotator is not None
                and getattr(self._rotator, "axes", None) is not host):
            try:
                self._rotator.remove()
            except (ValueError, AttributeError):
                pass
            self._rotator = None
        if self._rotator is None:
            if point is None:
                return
            self._rotator, = host.plot(
                [], [], linestyle="-", color=HANDLE_COLOR,
                marker="o", markerfacecolor="#ffffff",
                markeredgecolor=HANDLE_COLOR, alpha=self.handle_alpha(),
                markevery=[1], transform=self.ax.transAxes,
                clip_on=False, zorder=8, label="_nolegend_")
            self._rotator.set_in_layout(False)
        if point is None:
            self._rotator.set_data([], [])
            return
        scale = self.handle_scale()
        self._rotator.set_markersize(ROTATOR_SIZE * scale)
        self._rotator.set_markeredgewidth(HANDLE_EDGE * scale)
        self._rotator.set_linewidth(ROTATOR_STEM * scale)
        centre = self.rotation_centre()
        kind, key = self.selection or (None, None)
        if kind == "shape":
            anchor = self.shape_handle_positions(self.shape_state[key])[6]
        else:
            anchor = centre
        self._rotator.set_data([anchor[0], point[0]], [anchor[1], point[1]])

    def handle_at(self, x, y, tolerance=8.0):
        """Index of the control point of the selected object, or None.

        `ROTATE_HANDLE` (8) is the round one that turns the object.
        """
        if x is None or y is None:
            return None
        for index, point in enumerate(self.selected_handle_positions() or ()):
            px, py = self.ax.transAxes.transform(point)
            if abs(px - x) <= tolerance and abs(py - y) <= tolerance:
                return index
        point = self.rotation_handle_position()
        if point is not None:
            px, py = self.ax.transAxes.transform(point)
            if abs(px - x) <= tolerance and abs(py - y) <= tolerance:
                return ROTATE_HANDLE
        return None

    def line_ends(self, state):
        """The two ends of a drawn line, in the coordinates of the plot area."""
        x, y, w, h = state["x"], state["y"], state["w"], state["h"]
        ends = ([(x, y + h), (x + w, y)] if state.get("flip")
                else [(x, y), (x + w, y + h)])
        angle = self.angle_of(state)
        if angle:
            centre = self.shape_centre(state)
            ends = [self._turn_point(point, centre, angle) for point in ends]
        return ends

    def set_line_ends(self, key, first, second):
        """Put the two ends of a drawn line where they are asked for.

        The ends are the line, exactly as the tip and the tail are the arrow,
        so any earlier rotation is taken into the new pair of points.
        """
        state = self.shape_state.get(key)
        if state is None or state["kind"] not in OPEN_SHAPES:
            return False
        (x0, y0), (x1, y1) = first, second
        state["x"], state["w"] = float(min(x0, x1)), float(abs(x1 - x0))
        state["y"], state["h"] = float(min(y0, y1)), float(abs(y1 - y0))
        state["flip"] = bool((x1 - x0) * (y1 - y0) < 0)
        state["angle"] = 0.0
        self.refresh_shape(key)
        return True

    def _line_hit(self, state, x, y, tolerance=None):
        """Distance test against a drawn line: a stroke has no inside."""
        first, second = (np.array(self.ax.transAxes.transform(point), dtype=float)
                         for point in self.line_ends(state))
        segment = second - first
        length = float(np.hypot(*segment))
        if length < 1e-6:
            return False
        point = np.array([x, y], dtype=float)
        position = float(np.clip(np.dot(point - first, segment) / length ** 2,
                                 0.0, 1.0))
        distance = float(np.hypot(*(point - (first + position * segment))))
        return distance <= (tolerance if tolerance is not None
                            else max(4.0, float(state["width"]) + 3.0))

    def shape_at(self, x, y):
        """Key of the drawn object under the pointer, or None."""
        if x is None or y is None:
            return None
        for key in reversed(list(self.shapes)):        # topmost first
            state = self.shape_state.get(key)
            if state is not None and state["kind"] in OPEN_SHAPES:
                if self._line_hit(state, x, y):
                    return key
                continue
            patch = self.shapes[key]
            try:
                inside = patch.get_path().contains_point(
                    (x, y), patch.get_transform(),
                    radius=max(3.0, patch.get_linewidth()))
            except (ValueError, AttributeError):
                continue
            if inside:
                return key
        return None

    OPPOSITE_HANDLE = {0: 2, 1: 3, 2: 0, 3: 1, 4: 6, 5: 7, 6: 4, 7: 5}

    @staticmethod
    def _resize_ratio(drag, shift):
        """The proportions this drag has to keep, or None to stretch freely.

        A **picture** keeps its own shape when a corner is dragged - that
        is what a picture is - while any other drawing is free.  `Shift`
        turns the rule round, so a picture can be squashed on purpose and a
        rectangle can be kept square.
        """
        if drag.get("index") not in CORNER_HANDLES:
            return None                    # a side always stretches
        locked = bool(drag.get("locked"))
        return drag.get("ratio") if locked != bool(shift) else None

    def shape_ratio(self, state):
        """How wide one object is against its height, **on the screen**.

        The plot area is not square, so the proportions a reader sees are
        not the width and the height the object is stored with: they have
        to be measured in pixels.
        """
        try:
            wide = float(state["w"]) * self._axes_aspect()
            tall = float(state["h"])
            return wide / tall if tall > 1e-12 else None
        except (KeyError, TypeError, ValueError, ZeroDivisionError):
            return None

    def _resize_shape(self, key, index, point, ratio=None):
        """Drag one control point of an object to its new place.

        `ratio` keeps the proportions: the box is made to that width
        against height (as it looks on the screen) around the control
        point **opposite** the one being dragged, which is what a corner
        of a picture does.  A side control point never gets one, so it
        stretches or squashes the object as before.
        """
        state = self.shape_state[key]
        angle = self.angle_of(state)
        anchor_before = None
        if angle:
            # work in the frame of the object and keep the opposite control
            # point where it is on the screen
            anchor = self.OPPOSITE_HANDLE.get(index, index)
            anchor_before = self.ax.transAxes.transform(
                self.shape_handle_positions(state)[anchor])
            point = self._turn_point(point, self.shape_centre(state), -angle)
        x0, y0 = state["x"], state["y"]
        x1, y1 = x0 + state["w"], y0 + state["h"]
        if ratio and index in CORNER_HANDLES:
            # the corner across the box stays where it is, and the box is
            # made as large as the pointer asks for while keeping its shape
            aspect = self._axes_aspect() or 1.0
            held_x = x1 if index in (0, 3) else x0
            held_y = y1 if index in (0, 1) else y0
            wide = max(abs(float(point[0]) - held_x) * aspect,
                       MIN_SHAPE_SIZE * aspect)
            tall = max(abs(float(point[1]) - held_y), MIN_SHAPE_SIZE)
            if wide / tall > ratio:            # too wide: grow it downwards
                tall = wide / ratio
            else:
                wide = tall * ratio
            new_w, new_h = wide / aspect, tall
            x0, x1 = ((held_x - new_w, held_x) if point[0] < held_x
                      else (held_x, held_x + new_w))
            y0, y1 = ((held_y - new_h, held_y) if point[1] < held_y
                      else (held_y, held_y + new_h))
        else:
            if index in (0, 3, 7):
                x0 = point[0]
            elif index in (1, 2, 5):
                x1 = point[0]
            if index in (0, 1, 4):
                y0 = point[1]
            elif index in (2, 3, 6):
                y1 = point[1]
        state["x"], state["w"] = min(x0, x1), max(MIN_SHAPE_SIZE, abs(x1 - x0))
        state["y"], state["h"] = min(y0, y1), max(MIN_SHAPE_SIZE, abs(y1 - y0))
        if anchor_before is not None:
            anchor = self.OPPOSITE_HANDLE.get(index, index)
            after = self.ax.transAxes.transform(
                self.shape_handle_positions(state)[anchor])
            dx, dy = self._axes_delta(anchor_before[0] - after[0],
                                      anchor_before[1] - after[1])
            state["x"] += dx
            state["y"] += dy
        self.refresh_shape(key)

    def edit_shape(self, key):
        state = self.shape_state.get(key)
        if state is None:
            return None

        def apply(values):
            current = self.shape_state.get(key)   # Undo may have replaced it
            if current is None:
                return
            current.update(values)
            self.refresh_shape(key)
            self.draw()

        return self._show_dialog(f"shape-{key}", lambda: ShapeDialog(
            self, state, apply, on_delete=lambda: self.remove_shape(key),
            on_fit=lambda: self.fit_picture_ratio(key),
            on_close=lambda _d: self._dialogs.pop(f"shape-{key}", None),
            source=lambda: self.shape_state.get(key)))

    # -- free text boxes ---------------------------------------------------
    def arm_text_placement(self, armed=None):
        """Wait for a click in the diagram and put a new text box there."""
        self._pending_text = (not self._pending_text) if armed is None else armed
        if self._pending_text:                   # only one tool at a time
            self.arm_shape_drawing(armed=False)
            self.arm_arrow_drawing(armed=False)
        widget = self.canvas.get_tk_widget()
        try:
            if self._pending_text:
                self.text_button.configure(relief="sunken")
                widget.configure(cursor="xterm")     # a vertical line
                self.toolbar.set_message("Click in the diagram to place the text")
            else:
                self.text_button.configure(relief="flat")
                widget.configure(cursor="")
                self._cursor = ""
                self.toolbar.set_message("")
        except (tk.TclError, AttributeError):
            pass
        return self._pending_text

    def _shift_active(self, event=None):
        """True while Shift is held down (from Tk or from the mouse event)."""
        if self._shift_down:
            return True
        modifiers = getattr(event, "modifiers", None) or ()
        try:
            if "shift" in modifiers:
                return True
        except TypeError:
            pass
        return "shift" in str(getattr(event, "key", "") or "")

    def _snap_point(self, anchor, point):
        """`point` pulled onto the nearest 45 degree direction from `anchor`.

        The angles are measured on the screen, so a snapped arrow really is
        vertical, horizontal or diagonal whatever the size of the plot area.
        """
        transform = self.ax.transAxes
        start = np.array(transform.transform(anchor), dtype=float)
        end = np.array(transform.transform(point), dtype=float)
        vector = end - start
        if float(np.hypot(*vector)) < 1e-6:
            return (float(point[0]), float(point[1]))
        angle = np.round(np.arctan2(vector[1], vector[0]) / SNAP_ANGLE) * SNAP_ANGLE
        unit = np.array([np.cos(angle), np.sin(angle)])
        length = max(2.0, float(np.dot(vector, unit)))
        snapped = transform.inverted().transform(start + unit * length)
        return (float(snapped[0]), float(snapped[1]))

    def cancel_tools(self):
        """Escape: none of the three toolbar tools stays armed, and a group
        of chosen objects is let go."""
        if self.clear_group():
            self.draw()
        self.cancel_inline_edit()
        self.arm_text_placement(False)
        self.arm_shape_drawing(armed=False)
        self.arm_arrow_drawing(armed=False)

    def default_note_state(self, position):
        cfg = self.settings.section("text")
        return {
            "text": "Text", "pos": (float(position[0]), float(position[1])),
            "angle": 0.0,
            "size": int(cfg["size"]), "color": safe_hex(cfg["color"], "#000000"),
            "edge": ("none" if not cfg["frame"]
                     else safe_hex(cfg["edge_color"], "#000000")),
            "face": ("none" if cfg["transparent"]
                     else safe_hex(cfg["background"], "#ffffff")),
        }

    def add_note(self, *args, **kwargs):
        """One command: it can be taken back with Undo."""
        with self.changed('the text box'):
            return self._add_note(*args, **kwargs)

    def _add_note(self, position, text=None, state=None, key=None):
        """Create a text box at `position` (axes coordinates)."""
        key = self.claim_key("note", key)
        state = state or self.default_note_state(position)
        if state.get("z") is None:
            state["z"] = self.top_z()      # a new text box stands in front
        self.note_state[key] = state
        if text is not None:
            self.note_state[key]["text"] = text
        self.refresh_note(key)
        self.draw()
        return key

    def remove_note(self, *args, **kwargs):
        """One command: it can be taken back with Undo."""
        with self.changed('the text box'):
            return self._remove_note(*args, **kwargs)

    def _remove_note(self, key):
        artist = self.notes.pop(key, None)
        if artist is not None:
            artist.remove()
        self.note_state.pop(key, None)
        if self._marked == ("note", key):
            self._marked = None
        if self.selection == ("note", key):
            self.select_object(None, None)
        dialog = self._dialogs.pop(f"note-{key}", None)
        if dialog is not None and dialog.winfo_exists():
            dialog.destroy()
        self.draw()

    def refresh_note(self, key):
        artist = self.notes.pop(key, None)
        if artist is not None:
            artist.remove()
        state = self.note_state.get(key)
        if state is None or not str(state["text"]).strip():
            return None
        edge, face = state.get("edge", "none"), state.get("face", "none")
        box = {"boxstyle": "round,pad=0.35",
               "facecolor": "none" if face == "none" else face,
               "edgecolor": "none" if edge == "none" else edge,
               "linewidth": 0.0 if edge == "none" else 0.8}
        host = self.object_axes("note", key)
        artist = host.text(state["pos"][0], state["pos"][1], state["text"],
                              transform=self.ax.transAxes,
                              fontsize=state["size"], color=state["color"],
                              ha="left", va="center", bbox=box,
                              zorder=float(state.get("z") or Z_DEFAULT["note"]),
                              rotation=self.angle_of(state),
                              rotation_mode="anchor",
                              picker=True, clip_on=False)
        self.notes[key] = artist
        if self.selection == ("note", key) and self._marked != ("note", key):
            self._refresh_highlight()
        return artist

    def refresh_notes(self):
        for key in list(self.note_state):
            self.refresh_note(key)

    def note_at(self, x, y):
        """Key of the text box under the pointer, or None."""
        if x is None or y is None:
            return None
        renderer = self._renderer()
        for key, artist in self.notes.items():
            try:
                box = artist.get_window_extent(renderer)
            except (RuntimeError, ValueError, AttributeError):
                continue
            if box.expanded(1.15, 1.4).contains(x, y):
                return key
        return None

    def edit_note(self, key):
        state = self.note_state.get(key)
        if state is None:
            return None

        def apply(values):
            # the box as it is now: Undo may have put a fresh one in its place
            current = self.note_state.get(key)
            if current is None:
                return
            current.update(values)
            if not str(current["text"]).strip():
                self.remove_note(key)
                return
            self.refresh_note(key)
            self.draw()

        return self._show_dialog(f"note-{key}", lambda: TextBoxDialog(
            self, "Text box", state["text"], state, apply, rotation=True,
            hint="An empty text deletes this box.",
            on_delete=lambda: self.remove_note(key),
            on_close=lambda _d: self._dialogs.pop(f"note-{key}", None),
            source=lambda: (None if key not in self.note_state else
                            (self.note_state[key].get("text", ""),
                             self.note_state[key]))))

    # -- movable title and axis labels -------------------------------------
    def text_shown(self, name):
        """True while one of the three axis texts is really on the diagram."""
        artist = self.text_artist(name)
        if artist is None or not artist.get_text() or not artist.get_visible():
            return False
        if name == "y":
            return self.left_axis_shown()
        if name == "y2":
            return self.right_axis_active()
        return True

    def text_artist(self, name):
        if name == "y2":
            return None if self.ax2 is None else self.ax2.yaxis.label
        return {"title": self.ax.title,
                "x": self.ax.xaxis.label,
                "y": self.ax.yaxis.label}.get(name)

    def _base_transform(self, name):
        """The automatic placement of a text, without any drag offset.

        set_title() builds a fresh offset transform for the title every time
        the distance changes, so that one has to be read again here.
        """
        if name == "title":
            return self.ax.transAxes + self.ax.titleOffsetTrans
        return self._text_base.get(name)

    def apply_text_offset(self, name):
        """Shift one text by its dragged offset, keeping the automatic place."""
        base = self._base_transform(name)
        artist = self.text_artist(name)
        if base is None or artist is None:
            return
        dx, dy = self.text_offset.get(name, (0.0, 0.0))
        if dx or dy:
            # the distance is kept in points of the page and handed to
            # matplotlib as such: it grows and shrinks with the resolution
            # the figure is drawn at - the zoom of the view, a Retina
            # screen, a copied or saved picture - exactly as the fonts and
            # the axes do, so a moved label never creeps onto its axis
            artist.set_transform(base + ScaledTranslation(
                float(dx) / 72.0, float(dy) / 72.0, self.fig.dpi_scale_trans))
        else:
            artist.set_transform(base)
        if name == "title":
            # matplotlib keeps lifting the title above the tick labels, which
            # would cancel a vertical drag: freeze that while it is moved
            try:
                self.ax._autotitlepos = not (dx or dy)
            except AttributeError:
                pass

    def apply_text_offsets(self):
        for name in ("title", "x", "y", "y2"):
            self.apply_text_offset(name)

    def reset_text_offsets(self):
        for name in ("title", "x", "y", "y2"):
            self.text_offset[name] = (0.0, 0.0)
        self.apply_text_offsets()
        self.draw()

    def text_at(self, x, y):
        """Name of the movable text under the pointer, or None."""
        if x is None or y is None:
            return None
        renderer = self._renderer()
        for name in ("title", "x", "y", "y2"):
            artist = self.text_artist(name)
            if artist is None or not self.text_shown(name):
                continue
            try:
                box = artist.get_window_extent(renderer)
            except (RuntimeError, ValueError, AttributeError):
                continue
            if box.expanded(1.2, 1.5).contains(x, y):
                return name
        return None

    def _start_text_drag(self, name, event):
        if name.startswith(NOTE_KEY):
            origin = tuple(self.note_state[name[len(NOTE_KEY):]]["pos"])
        else:
            origin = tuple(self.text_offset[name])
        self._text_drag = {"name": name, "x": event.x, "y": event.y,
                           "offset": origin, "moved": False}

    def _move_note(self, key, position):
        self.note_state[key]["pos"] = (float(position[0]), float(position[1]))
        artist = self.notes.get(key)
        if artist is not None:
            artist.set_position(self.note_state[key]["pos"])

    # -- legend hit testing / dragging -------------------------------------
    def _renderer(self):
        try:
            return self.canvas.get_renderer()
        except AttributeError:
            return None

    def legend_at(self, x, y):
        """(column, legend) of the legend box under the pointer."""
        if x is None or y is None:
            return None, None
        renderer = self._renderer()
        for y_col, legend in self.legends.items():
            try:
                box = legend.get_window_extent(renderer)
            except (RuntimeError, ValueError, AttributeError):
                continue
            if box.contains(x, y):
                return y_col, legend
        return None, None

    def legend_sample_hit(self, column, x, y):
        """True when (x, y) is on the legend box of `column` but not on its
        text: on the sample of the curve, or the margin around it."""
        legend = self.legends.get(column)
        if legend is None or x is None or y is None:
            return False
        try:
            box = legend.get_window_extent(self._renderer())
        except (RuntimeError, ValueError, AttributeError):
            return False
        if not box.contains(x, y):
            return False
        # the text exactly (a long label must not reach over the sample)
        renderer = self._renderer()
        for text in legend.get_texts():
            try:
                area = text.get_window_extent(renderer)
            except (RuntimeError, ValueError, AttributeError):
                continue
            pad = 2.0 * self.screen_ratio()
            if (area.x0 - pad <= x <= area.x1 + pad
                    and area.y0 - pad <= y <= area.y1 + pad):
                return False
        return True

    def _legend_text_hit(self, legend, x, y):
        renderer = self._renderer()
        for text in legend.get_texts():
            try:
                box = text.get_window_extent(renderer)
            except (RuntimeError, ValueError, AttributeError):
                continue
            if box.expanded(1.25, 1.6).contains(x, y):
                return True
        return False

    def _axes_point(self, event):
        x, y = self.ax.transAxes.inverted().transform((event.x, event.y))
        return (float(x), float(y))

    def _grab_offset(self, index, event):
        """How far (pixels) the control point `index` lies from the pointer
        that grabs it.  The point keeps that distance while it is dragged,
        so it never jumps onto the pointer: grabbed a little off its
        centre, the tip of an arrow stays exactly where it was until the
        mouse moves."""
        try:
            point = (self.selected_handle_positions() or [])[index]
            px, py = self.ax.transAxes.transform(point)
            return (float(px) - float(event.x), float(py) - float(event.y))
        except (IndexError, TypeError, ValueError):
            return (0.0, 0.0)

    def _grabbed_point(self, event, drag):
        """Where a dragged control point goes: the pointer, plus the
        distance it was grabbed at (axes coordinates)."""
        dx, dy = drag.get("grab") or (0.0, 0.0)
        return self._axes_point_at(float(event.x) + dx, float(event.y) + dy)

    def _start_legend_drag(self, y_col, event):
        pos = self.legend_state[y_col]["pos"]
        point = self._axes_point(event)
        self._drag = {"column": y_col,
                      "dx": pos[0] - point[0], "dy": pos[1] - point[1]}

    # -- dragging: the still part of the page is drawn once ---------------
    def _dragged_objects(self):
        """The objects the running drag moves, as (kind, key) pairs.

        None when no drag is running, or when the drag changes the whole
        diagram (the graph carried along, an axis made longer): then every
        step draws the whole page, as it must.
        """
        if self._band is not None:
            return []                    # only the rectangle and its marks
        if self._group_drag is not None:
            return [tuple(one) for one in self.group]
        if self._plot_drag is not None:
            return None
        drag = self._shape_drag
        if drag is not None:
            mode = str(drag.get("mode", ""))
            if mode == "axis-end":
                return None
            if mode.startswith("arrow"):
                return [("arrow", drag["key"])]
            if mode == "rotate":
                return [(drag.get("kind") or "shape", drag["key"])]
            return [("shape", drag["key"])]
        if self._text_drag is not None:
            name = str(self._text_drag["name"])
            if name.startswith(NOTE_KEY):
                return [("note", name[len(NOTE_KEY):])]
            return [("text", name)]
        if self._drag is not None:
            return [("legend", self._drag["column"])]
        return None

    def object_artists(self, kind, key):
        """What matplotlib draws for one object (the artists)."""
        found = []
        if kind == "shape":
            found = [self.shapes.get(key), self.shape_pictures.get(key)]
        elif kind == "arrow":
            found = list(self.arrows.get(key) or [])
        elif kind == "note":
            found = [self.notes.get(key)]
        elif kind == "legend":
            found = [self.legends.get(key)]
        elif kind == "text":
            found = [self.text_artist(key)]
        return [one for one in found if one is not None]

    def _moving_artists(self):
        """Everything that is painted again at each step of the drag."""
        still = self._still
        objects = (still["objects"] if still is not None
                   else self._dragged_objects()) or []
        found = []
        for kind, key in objects:
            found += self.object_artists(kind, key)
        # the tools that go with them: the control points, the rectangle
        # that chooses and the blue boxes of a group
        found += [self._handles, self._rotator, self._band_patch]
        found += list(self._group_marks)
        seen, unique = set(), []
        for one in found:
            if one is not None and id(one) not in seen:
                seen.add(id(one))
                unique.append(one)
        return unique

    def _extent_of(self, artist, renderer):
        """The box (pixels) an artist covers, with its frame, or None."""
        try:
            box = artist.get_window_extent(renderer)
            patch = getattr(artist, "get_bbox_patch", lambda: None)()
            if patch is not None:
                box = Bbox.union([box, patch.get_window_extent(renderer)])
        except (RuntimeError, ValueError, AttributeError, TypeError):
            return None
        if box is None or not np.all(np.isfinite(box.get_points())) \
                or box.width < 0 or box.height < 0:
            return None
        return box

    def _begin_still(self):
        """A drag has begun: draw the page once without what it moves."""
        if not FAST_DRAGS or self._still is not None:
            return False
        objects = self._dragged_objects()
        if objects is None:
            return False
        canvas = self.canvas
        if not hasattr(canvas, "copy_from_bbox") \
                or not hasattr(canvas, "restore_region"):
            return False
        self._still = {"objects": objects}
        # a see-through page cannot be painted over in parts - the old
        # pixels would show through, as a trail - so while the drag lasts
        # it wears the colour that shows through it anyway
        patch = self.fig.patch
        face = tuple(patch.get_facecolor())
        if not patch.get_visible() or float(face[3]) < 1.0:
            behind = self._colour_behind_page()
            if behind is not None:
                self._still["paper"] = (patch.get_visible(), face)
                patch.set_visible(True)
                patch.set_facecolor(behind)
        movers = self._moving_artists()
        try:
            renderer = canvas.get_renderer()
            dirty = [self._extent_of(one, renderer) for one in movers
                     if one.get_visible()]
        except (RuntimeError, ValueError, AttributeError, TypeError):
            dirty = []
        hidden = [one for one in movers if one.get_visible()]
        places = [(one, one.get_position()) for one in hidden
                  if isinstance(one, Text)]
        background = None
        with QuietDraws(self):
            for one in hidden:
                one.set_visible(False)
            try:
                # only matplotlib's own drawing: the screen keeps showing
                # the page as it was until the first step paints over it
                FigureCanvasAgg.draw(canvas)
                background = canvas.copy_from_bbox(self.fig.bbox)
            except Exception:          # no fast drag - the usual one then
                background = None
            finally:
                for one in hidden:
                    one.set_visible(True)
                # matplotlib places a title it cannot see far off: each
                # text is put back where it stood before the still page
                for one, spot in places:
                    one.set_position(spot)
        if background is None:
            self._end_still(draw=False)
            canvas.draw_idle()
            return False
        self._still.update(background=background,
                           size=tuple(self.fig.bbox.bounds),
                           dirty=[box for box in dirty if box is not None])
        return True

    def _colour_behind_page(self):
        """The colour the screen shows through a see-through page."""
        try:
            widget = self.canvas.get_tk_widget()
            red, green, blue = widget.winfo_rgb(widget.cget("background"))
        except (tk.TclError, AttributeError, ValueError):
            return None
        return (red / 65535.0, green / 65535.0, blue / 65535.0, 1.0)

    def _still_frame(self):
        """One step of a drag: the still page, what moves, on the screen."""
        still = self._still
        canvas = self.canvas
        if tuple(self.fig.bbox.bounds) != still.get("size"):
            return False                  # zoomed or resized meanwhile
        try:
            canvas.restore_region(still["background"])
            renderer = canvas.get_renderer()
            boxes = []
            for artist in sorted(self._moving_artists(),
                                 key=lambda one: one.get_zorder()):
                if not artist.get_visible():
                    continue
                try:
                    self.fig.draw_artist(artist)
                except Exception:
                    continue
                box = self._extent_of(artist, renderer)
                if box is not None:
                    boxes.append(box)
            # the pixels that change: where the object was, and where it is
            changed = boxes + list(still.get("dirty") or [])
            still["dirty"] = boxes
            if not changed:
                return True
            face = self.fig.patch.get_facecolor()
            if not self.fig.patch.get_visible() or float(face[3]) < 1.0:
                canvas.blit()             # see-through: it is sent whole
                return True
            pad = STILL_PAD * self.screen_ratio()
            area = Bbox.union(changed)
            area = Bbox.from_extents(area.x0 - pad, area.y0 - pad,
                                     area.x1 + pad, area.y1 + pad)
            canvas.blit(area)
        except Exception:                 # draw the whole page instead
            return False
        return True

    def _end_still(self, draw=True):
        """The drag is over: the whole page is drawn again, as it is."""
        still, self._still = self._still, None
        if still is None:
            return False
        paper = still.get("paper")
        if paper is not None:              # the page is see-through again
            self.fig.patch.set_visible(paper[0])
            self.fig.patch.set_facecolor(paper[1])
        if draw:
            self.draw()
        return True

    def _on_motion(self, event):
        pending = self._pending_rename
        if pending is not None and event.x is not None and event.y is not None:
            if (abs(event.x - pending["x"]) > 3.0
                    or abs(event.y - pending["y"]) > 3.0):
                self._pending_rename = None    # this is a drag, not a rename
        if self._still is None and event.x is not None:
            self._begin_still()                # only when a drag is running
        if self._band is not None:             # the rectangle that chooses
            self._stretch_band(event)
            return
        if self._group_drag is not None:       # the whole group follows
            if event.x is None or event.y is None:
                return
            drag = self._group_drag
            dx, dy = float(event.x) - drag["x"], float(event.y) - drag["y"]
            if dx or dy:
                self.move_group(dx, dy)
                drag["x"], drag["y"] = float(event.x), float(event.y)
                drag["moved"] = True
                self.draw()
            return
        if self._plot_drag is not None:
            self._drag_plot_to(event)
            return
        if self._shape_drag is not None:
            if event.x is None or event.y is None:
                return
            drag = self._shape_drag
            key = drag["key"]
            mode = drag["mode"]
            if mode == "axis-end":             # pull the end of an axis
                self.resize_axis(drag["key"], drag["index"],
                                 self._figure_point(event))
                self._refresh_handles()
                self.draw()
                return
            if mode == "rotate":
                pointer = self._pointer_angle(event, drag["centre"])
                if pointer is None:
                    return
                # the object turns by as much as the pointer did, so grabbing
                # the handle never makes it jump
                self.rotate_selection(drag["angle"] + pointer - drag["pointer"],
                                      snap=self._shift_active(event))
                return
            if mode.startswith("arrow"):
                if key not in self.arrow_state:
                    self._shape_drag = None
                    return
                point = (self._grabbed_point(event, drag) if mode == "arrow-end"
                         else self._axes_point(event))
                state = self.arrow_state[key]
                snap = self._shift_active(event)
                if mode == "arrow-new":
                    state["tip"] = (self._snap_point(state["tail"], point)
                                    if snap else point)
                elif mode == "arrow-end":
                    moving = "tail" if drag["index"] == 0 else "tip"
                    fixed = "tip" if drag["index"] == 0 else "tail"
                    state[moving] = (self._snap_point(state[fixed], point)
                                     if snap else point)
                else:
                    shift = (point[0] - drag["start"][0],
                             point[1] - drag["start"][1])
                    state["tail"] = (drag["tail"][0] + shift[0],
                                     drag["tail"][1] + shift[1])
                    state["tip"] = (drag["tip"][0] + shift[0],
                                    drag["tip"][1] + shift[1])
                    drag["moved"] = True
                self.refresh_arrow(key)
                self._refresh_handles()
                self.draw()
                return
            if key not in self.shape_state:
                self._shape_drag = None
                return
            point = (self._grabbed_point(event, drag)
                     if mode in ("line-end", "resize") else self._axes_point(event))
            state = self.shape_state[key]
            snap = self._shift_active(event)
            if mode == "line-end":             # one end of a line, as an arrow
                fixed = drag.get("fixed")
                if fixed is None:
                    fixed = self.line_ends(state)[1 - drag["index"]]
                if snap:
                    point = self._snap_point(fixed, point)
                self.set_line_ends(key, fixed, point)
                self._refresh_handles()
                self.draw()
                return
            if drag["mode"] == "new":          # rubber band from the anchor
                anchor = drag["anchor"]
                if state["kind"] in OPEN_SHAPES:
                    # Shift keeps the new line at 45 degree steps, as an arrow
                    if snap:
                        point = self._snap_point(anchor, point)
                    self.set_line_ends(key, anchor, point)
                    self.draw()
                    return
                state["x"], state["w"] = min(anchor[0], point[0]), abs(point[0] - anchor[0])
                state["y"], state["h"] = min(anchor[1], point[1]), abs(point[1] - anchor[1])
                self.refresh_shape(key)
            elif drag["mode"] == "resize":
                self._resize_shape(key, drag["index"], point,
                                   ratio=self._resize_ratio(drag, snap))
            else:
                state = self.shape_state[key]
                state["x"] = drag["origin"][0] + point[0] - drag["start"][0]
                state["y"] = drag["origin"][1] + point[1] - drag["start"][1]
                drag["moved"] = True
                self.refresh_shape(key)
            self.draw()
            return
        if self._text_drag is not None:
            if event.x is None or event.y is None:
                return
            drag = self._text_drag
            dx = event.x - drag["x"]
            dy = event.y - drag["y"]
            if abs(dx) > 2 or abs(dy) > 2:
                drag["moved"] = True
            name = drag["name"]
            if name.startswith(NOTE_KEY):     # text boxes live in axes coords
                inverse = self.ax.transAxes.inverted()
                start = inverse.transform((drag["x"], drag["y"]))
                now = inverse.transform((event.x, event.y))
                self._move_note(name[len(NOTE_KEY):],
                                (drag["offset"][0] + now[0] - start[0],
                                 drag["offset"][1] + now[1] - start[1]))
            else:                             # pixels of the view -> points
                self.text_offset[name] = (drag["offset"][0] + self.points(dx),
                                          drag["offset"][1] + self.points(dy))
                self.apply_text_offset(name)
            self._refresh_highlight()
            self.draw()
            return
        if self._drag is None:
            self._update_cursor(event)
            return
        if event.x is None or event.y is None:
            return
        y_col = self._drag["column"]
        legend = self.legends.get(y_col)
        if legend is None:
            self._drag = None
            return
        point = self._axes_point(event)
        pos = (point[0] + self._drag["dx"], point[1] + self._drag["dy"])
        self.legend_state[y_col]["pos"] = pos
        legend.set_bbox_to_anchor(pos, transform=self.ax.transAxes)
        self._refresh_highlight()
        self.draw()

    def _on_release(self, event=None):
        self._end_still()                      # the whole page is drawn again
        moved_plot = (self._plot_drag or {}).get("moved", False)
        moved_group = (self._group_drag or {}).get("moved", False)
        self._group_drag = None
        if self._band is not None:
            self._finish_band()
        dragged = (self._shape_drag is not None or self._drag is not None
                   or moved_plot or moved_group)
        self._plot_drag = None
        self._finish_drag(event)
        self._open_pending_rename()
        before, self._drag_before = getattr(self, "_drag_before", None), None
        app = getattr(self, "app", None)
        if dragged and before is not None and app is not None:
            app.record_plot(self, "moving the graph" if moved_plot
                            else "moving the objects" if moved_group
                            else "moving the object", before)
        if moved_plot:
            self._set_cursor("")
            self.flash("The graph was moved - Undo puts it back")

    def _finish_drag(self, _event=None):
        self._drag = None
        shape_drag, self._shape_drag = self._shape_drag, None
        if shape_drag is not None and shape_drag["mode"].startswith("arrow"):
            key = shape_drag["key"]
            state = self.arrow_state.get(key)
            if state is not None:
                if shape_drag["mode"] == "arrow-new":
                    tail = np.array(self.ax.transAxes.transform(state["tail"]))
                    tip = np.array(self.ax.transAxes.transform(state["tip"]))
                    if float(np.hypot(*(tip - tail))) < 12.0:   # a plain click
                        state["tip"] = (state["tail"][0] + 0.18,
                                        state["tail"][1])
                        self.refresh_arrow(key)
                        self._refresh_handles()
                self.draw()
            return
        if shape_drag is not None and shape_drag["mode"] in ("rotate", "axis-end"):
            self._refresh_handles()
            self.draw()
            return
        if shape_drag is not None:
            key = shape_drag["key"]
            state = self.shape_state.get(key)
            if state is not None:
                if shape_drag["mode"] == "new" and state["kind"] in OPEN_SHAPES:
                    ends = self.line_ends(state)
                    first = np.array(self.ax.transAxes.transform(ends[0]))
                    second = np.array(self.ax.transAxes.transform(ends[1]))
                    if float(np.hypot(*(second - first))) < 12.0:  # a plain click
                        self.set_line_ends(key, ends[0],
                                           (ends[0][0] + 0.18, ends[0][1]))
                        self._refresh_handles()
                elif shape_drag["mode"] == "new" and (
                        state["w"] < 0.02 or state["h"] < 0.02):
                    state["w"] = max(state["w"], 0.18)   # a plain click
                    state["h"] = max(state["h"], 0.14)
                    self.refresh_shape(key)
                self.draw()
            return
        drag, self._text_drag = self._text_drag, None
        if drag is None:
            return
        if not drag["moved"]:      # a click that only selected: put it back
            name = drag["name"]
            if name.startswith(NOTE_KEY):
                self._move_note(name[len(NOTE_KEY):], drag["offset"])
            else:
                self.text_offset[name] = drag["offset"]
                self.apply_text_offset(name)
        self._refresh_highlight()
        self.draw()

    def _update_cursor(self, event):
        if self._pending_text or self._pending_shape or self._pending_arrow:
            return                     # the tool cursor stays until the click
        cursor = ""
        _y_col, legend = self.legend_at(event.x, event.y)
        index = self.handle_at(event.x, event.y)
        axis_end = self.axis_end_at(event.x, event.y)
        if axis_end is not None:
            _kind, which = self.selection
            cursor = ("sb_h_double_arrow"
                      if self.axis_side(which) in HORIZONTAL_SIDES
                      else "sb_v_double_arrow")
        elif index == ROTATE_HANDLE:
            cursor = "exchange"            # a round arrow: turn the object
        elif index is not None:
            cursor = "sizing"
        elif self.arrow_at(event.x, event.y) is not None:
            cursor = "fleur"
        elif self.shape_at(event.x, event.y) is not None:
            cursor = "fleur"
        elif self.note_at(event.x, event.y) is not None:
            cursor = "fleur"
        elif self.text_at(event.x, event.y) is not None:
            cursor = "fleur"
        elif legend is not None:
            cursor = "fleur"           # one click selects it, then it is moved
        elif (self.frame_hit(event.x, event.y)
              or self.series_at(event) is not None
              or self.numbers_at(event.x, event.y) is not None):
            # the frame, a curve and the numbers carry the whole graph; the
            # empty background draws the rectangle that chooses objects
            cursor = "fleur"
        self._set_cursor(cursor)

    def _set_cursor(self, cursor):
        """The pointer shape over the canvas, set only when it changes."""
        if cursor == self._cursor:
            return False
        self._cursor = cursor
        try:
            self.canvas.get_tk_widget().configure(cursor=cursor)
        except tk.TclError:
            return False
        return True

    # -- axis helpers ------------------------------------------------------
    def axis_label(self, which):
        if which == "x":
            return self.ax.get_xlabel()
        if which == "y2":
            return "" if self.ax2 is None else self.ax2.get_ylabel()
        return self.ax.get_ylabel()

    def current_limits(self, which):
        if which == "x":
            return self.ax.get_xlim()
        if which == "y2":
            return (0.0, 1.0) if self.ax2 is None else self.ax2.get_ylim()
        return self.ax.get_ylim()

    def watch_limits(self, ax):
        """Tell an open `Axes properties` whenever this axes changes range.

        The zoom and the pan tools of the toolbar move the two ends
        without going through the program at all, so the dialog is told by
        matplotlib itself rather than by the command that did it.
        """
        try:
            for event in ("xlim_changed", "ylim_changed"):
                ax.callbacks.connect(event, lambda _ax: self.sync_axes_dialog())
        except (AttributeError, TypeError):
            return False
        return True

    def automatic_limits(self, which):
        """The two ends the data would give this axis, without setting them.

        `Automatic range and ticks` is a promise about the data, and the
        dialog has to be able to show what that promise says before it is
        applied.  The axis is measured exactly the way the automatic range
        measures it and then put back as it was - the two ends and the two
        automatic flags of both axes - so nothing on the screen moves.
        """
        if which == "y2" and self.ax2 is None:
            return None
        try:
            ax, _axis, name = self._axis_pair(which)
        except (AttributeError, TypeError, ValueError, tk.TclError):
            return None
        # a twinned axes shares its X with the other one, so both are put
        # back, not only the one that was measured
        family = [one for one in (self.ax, self.ax2) if one is not None]
        keep = [(one, one.get_xlim(), one.get_ylim(),
                 one.get_autoscalex_on(), one.get_autoscaley_on())
                for one in family]
        self._measuring = True
        try:
            ax.autoscale(enable=True, axis=name)
            self.measure_data(ax, scalex=(name == "x"), scaley=(name == "y"))
            found = ax.get_xlim() if name == "x" else ax.get_ylim()
            return float(found[0]), float(found[1])
        except (AttributeError, RuntimeError, TypeError, ValueError):
            return None
        finally:
            for one, x_limits, y_limits, auto_x, auto_y in keep:
                try:
                    one.set_xlim(x_limits, emit=False, auto=auto_x)
                    one.set_ylim(y_limits, emit=False, auto=auto_y)
                except (AttributeError, RuntimeError, ValueError):
                    pass
            self._measuring = False

    def _axis_pair(self, which):
        """(axes, axis, "x"/"y") of one of the three axis pages."""
        if which == "y2":
            ax = self.ensure_right_axis()
            return ax, ax.yaxis, "y"
        if which == "x":
            return self.ax, self.ax.xaxis, "x"
        return self.ax, self.ax.yaxis, "y"

    # -- distances are given in pixels, matplotlib wants points ------------
    def default_tick_pad(self, which):
        """How far the numbers stand from an axis unless told otherwise:
        the X axis has one distance of its own, the two Y axes another."""
        fonts = self.fonts
        if str(which) == "x":
            return float(fonts.get("tick_label_pad", 7.0))
        return float(fonts.get("tick_label_pad_y",
                               fonts.get("tick_label_pad", 5.0)))

    def points(self, pixels):
        """Pixels of the view (as the pointer moves them) in points."""
        return float(pixels) * 72.0 / float(self.fig.get_dpi())

    def page_points(self, pixels):
        """Pixels of the page itself - the unit of every distance setting
        (`Label offset [px]`, `Number offset [px]`, the title distance) - in
        points.  A pixel of the page is one at 100 % zoom, so the distances
        stay the same on the paper whatever the view is zoomed to, and in
        every picture made of the graph, as the fonts do."""
        return float(pixels) * 72.0 / float(getattr(self, "base_dpi", 0)
                                            or self.fig.get_dpi())

    def pixels(self, points):
        return float(points) * float(self.fig.get_dpi()) / 72.0

    # -- frame and axes geometry -------------------------------------------
    @staticmethod
    def check_frame(cfg):
        """Returns an error message when the geometry is not usable."""
        if cfg["x_length"] <= 0.02 or cfg["y_length"] <= 0.02:
            return "The width and the height of the axes must be positive."
        if cfg["left"] < 0 or cfg["bottom"] < 0:
            return "The distances from the edges cannot be negative."
        if cfg["left"] + cfg["x_length"] > 1.001:
            return ("The width plus the distance from the left is larger than "
                    "the page.")
        if cfg["bottom"] + cfg["y_length"] > 1.001:
            return ("The height plus the distance from the bottom is larger "
                    "than the page.")
        return None

    def apply_frame(self, cfg, redraw=True):
        """Frame style, thickness, colour and the size/origin of the axes."""
        style = cfg.get("style", "box")
        width = float(cfg.get("width", 1.0))
        color = cfg.get("color", "#000000")
        major_length = max(0.0, to_float(cfg.get("major_tick_length"), 3.5))
        minor_length = max(0.0, to_float(cfg.get("minor_tick_length"), 2.0))
        closed = style != "none"

        used = self.used_sides()
        # ax.pie() switches the whole frame of the axes off, which takes the
        # spines with it however they are set - so it is put back here for
        # every other style, and only a pie is left standing on nothing
        pie = self.only_pies()
        self.ax.set_frame_on(not pie)
        for name, spine in self.ax.spines.items():
            # a closed frame draws all four sides, "no frame" only the lines
            # the axes in use actually sit on
            spine.set_visible(not pie and (closed or name in used))
            spine.set_linewidth(width)
            spine.set_picker(6)          # clicking the frame opens this dialog

        # the colours belong to the three axis pages (see _apply_axis_colors)
        self.ax.tick_params(
            which="both", width=width,
            top=(style == "box_in" or style == "box_out"),
            right=(style == "box_in" or style == "box_out"),
            direction="in" if style == "box_in" else "out")
        self.ax.tick_params(which="major", length=major_length)
        self.ax.tick_params(which="minor", length=minor_length)
        if self.ax2 is not None:
            for spine in self.ax2.spines.values():
                spine.set_visible(False)   # the main axes draws the frame
            self.ax2.tick_params(which="both", width=width,
                                 direction="in" if style == "box_in" else "out")
            self.ax2.tick_params(which="major", length=major_length)
            self.ax2.tick_params(which="minor", length=minor_length)
            self.ax2.set_facecolor("none")

        background = cfg.get("background", "#ffffff")
        figure_background = cfg.get("figure_background", "#ffffff")
        # the lower of the two axes carries the colour of the plot area
        self.apply_axes_background(background)
        self.fig.set_facecolor("none" if figure_background == "none"
                               else figure_background)

        self.ax.set_position([cfg["left"], cfg["bottom"],
                              cfg["x_length"], cfg["y_length"]])
        if self.ax2 is not None:
            self.ax2.set_position(self.ax.get_position())
        self.frame_cfg = {"style": style, "width": width, "color": color,
                          "major_tick_length": major_length,
                          "minor_tick_length": minor_length,
                          "background": background,
                          "figure_background": figure_background,
                          "left": float(cfg["left"]), "bottom": float(cfg["bottom"]),
                          "x_length": float(cfg["x_length"]),
                          "y_length": float(cfg["y_length"])}
        self._apply_axis_sides()     # bottom or top X, left or right Y
        kind, key = self.selection or (None, None)
        if kind == "axis" and not self.ax.spines[key].get_visible():
            self.select_object(None, None)   # that line is not drawn any more
        # the plot area moved: the pixel geometry of the objects is rebuilt
        self.refresh_shapes()
        self.refresh_arrows()
        self._refresh_handles()
        # an open `Frame and origin` holds a copy of all of this: it reads
        # the new page, so that its next Apply cannot put the old one back
        self.sync_frame_dialog()
        if redraw:
            self.draw()

    def apply_axis(self, which, cfg, redraw=True):
        """Range / ticks / minor ticks / grid / fonts of one axis."""
        stored = self.axis_cfg.get(which, {})
        chosen = str(cfg.get("direction", stored.get("direction", "standard")))
        if chosen not in AXIS_DIRECTIONS:
            chosen = "standard"
        # what is remembered is what was chosen; a curve on the right hand
        # scale draws that axis anyway, without changing the choice - so it
        # disappears again by itself when its last curve leaves
        wanted = chosen
        if which == "y2" and wanted == "off" and self.right_axis_carries_curves():
            wanted = "standard"
        if which == "y2" and wanted == "off" and self.ax2 is None:
            # there is no right hand axis and none is wanted: the settings
            # are only remembered, ready for the day one is asked for
            keep = {name: value for name, value in cfg.items()
                    if name not in ("label", "min", "max")}
            keep["direction"] = "off"
            if "grid" in keep:
                keep["grid"] = dict(keep["grid"])
            self.axis_cfg["y2"] = {**stored, **keep}
            self._apply_axis_sides()
            if redraw:
                self.draw()
            return None
        ax, axis, axis_name = self._axis_pair(which)

        if "label" in cfg:
            (ax.set_xlabel if which == "x" else ax.set_ylabel)(cfg["label"])
        label_size = int(cfg.get("label_size", self.fonts["axis_label"]))
        tick_size = int(cfg.get("tick_size", self.fonts["tick_label"]))
        # font colours: 'labelcolor' is the text of the numbers, while the
        # colour of the tick marks themselves belongs to the frame
        label_color = safe_hex(cfg.get("label_color",
                                       self.fonts["axis_label_color"]), "#000000")
        tick_color = safe_hex(cfg.get("tick_color",
                                      self.fonts["tick_label_color"]), "#000000")
        label_pad = to_float(cfg.get("label_pad"), self.fonts["axis_label_pad"])
        tick_pad = to_float(cfg.get("tick_pad"), self.default_tick_pad(which))
        axis_color = safe_hex(cfg.get("axis_color",
                                      stored.get("axis_color", "#000000")),
                              "#000000")
        label_on = bool(cfg.get("label_on", stored.get("label_on", True)))
        ticks_on = bool(cfg.get("ticks_on", stored.get("ticks_on", True)))
        tick_labels_on = bool(cfg.get("tick_labels_on", stored.get("tick_labels_on", True)))
        direction = chosen
        scale = str(cfg.get("scale", stored.get("scale", "linear")))
        if scale != "linear" and scale not in LOG_BASES:
            scale = "linear"

        axis.label.set_fontsize(label_size)
        axis.label.set_color(label_color)
        axis.label.set_visible(label_on)     # the section switch of the dialog
        axis.label.set_picker(True)
        axis.labelpad = self.page_points(label_pad)  # distance of the label
        ax.tick_params(axis=axis_name, which="both", labelsize=tick_size,
                       labelcolor=tick_color, pad=self.page_points(tick_pad))

        # the scale comes first: telling matplotlib about it throws away
        # the tick locators, which the range below sets.  The height of the
        # axis is its place in the stack, not something this page sets, so
        # it is carried over from what was there (or from the file).
        height = cfg.get("z", stored.get("z"))
        self.axis_cfg[which] = {**stored, "scale": scale}
        if height is not None:
            self.axis_cfg[which]["z"] = float(height)
        if not self.axis_scale_matches(which):
            self.apply_axis_scale(which)

        # a logarithmic axis counts in ratios, not in distances, so the
        # step and the minor ticks mean something else on it - but they
        # mean it just as much (see log_major_base and log_minor_subs)
        log = scale != "linear"
        step = cfg.get("step")
        log_base = None
        if cfg["auto"]:
            if not log:
                axis.set_major_locator(AutoLocator())
            ax.autoscale(enable=True, axis=axis_name)
            self.measure_data(ax)
            if log:
                # the range is the data's; the spacing is still asked for,
                # and it is measured against the range the data gave
                log_base = self.log_major_base(LOG_BASES.get(scale, 10.0),
                                               step, self.current_limits(which))
                axis.set_major_locator(LogLocator(base=log_base, subs=(1.0,),
                                                  numticks=LOG_TICK_LIMIT))
        else:
            now_low, now_high = self.current_limits(which)
            low = cfg.get("min") if cfg.get("min") is not None else now_low
            high = cfg.get("max") if cfg.get("max") is not None else now_high
            low, high = sorted((low, high))
            if log:                      # it never reaches zero
                high = max(high, LOG_FLOOR * 10.0)
                low = low if low > 0.0 else high / 1000.0
            (ax.set_xlim if which == "x" else ax.set_ylim)(low, high)
            if log:
                log_base = self.log_major_base(LOG_BASES.get(scale, 10.0),
                                               step, (low, high))
                axis.set_major_locator(LogLocator(base=log_base, subs=(1.0,),
                                                  numticks=LOG_TICK_LIMIT))
            elif step and step > 0:
                count = int(round((high - low) / step)) + 1
                if 1 < count <= 1000:
                    axis.set_major_locator(FixedLocator(low + step * np.arange(count)))
                else:
                    axis.set_major_locator(MultipleLocator(step))
            else:
                axis.set_major_locator(AutoLocator())

        minor = max(0, int(cfg.get("minor", 0)))
        if log:
            subs = self.log_minor_subs(log_base, minor)
            axis.set_minor_locator(
                LogLocator(base=log_base, subs=subs, numticks=LOG_TICK_LIMIT)
                if subs else NullLocator())
            # the minor ticks of a logarithmic axis carry no numbers, just
            # as they carry none on a linear one
            axis.set_minor_formatter(NullFormatter())
            # a natural logarithm is read in powers of e, not in numbers
            axis.set_major_formatter(
                NaturalLogFormatter() if scale == "ln"
                else LogFormatterSciNotation(base=LOG_BASES.get(scale, 10.0)))
        else:
            axis.set_minor_locator(AutoMinorLocator(minor + 1) if minor
                                   else NullLocator())

        grid = cfg.get("grid", self.axis_cfg[which]["grid"])
        if which == "x":
            if grid["major"]:
                ax.grid(True, which="major", axis="x", color=grid["color"],
                        linestyle=grid["style"], linewidth=grid["width"])
            else:
                ax.grid(False, which="major", axis="x")
            if grid["minor"] and minor:
                ax.grid(True, which="minor", axis="x", color=grid["color"],
                        linestyle=grid["style"],
                        linewidth=max(0.3, grid["width"] * 0.6))
            else:
                ax.grid(False, which="minor", axis="x")

        self.axis_cfg[which] = {
            "auto": cfg["auto"], "step": cfg.get("step"), "minor": minor,
            "label_size": label_size, "tick_size": tick_size,
            "label_color": label_color, "tick_color": tick_color,
            "label_pad": label_pad, "tick_pad": tick_pad,
            "axis_color": axis_color, "label_on": label_on,
            "ticks_on": ticks_on, "tick_labels_on": tick_labels_on,
            "direction": direction, "scale": scale,
            # the place of the axis in the stack is not this page's to set:
            # it comes from the file, or from where the user put it
            "z": float(Z_DEFAULT["axis"] if height is None else height),
            "grid": dict(grid),
        }
        self.apply_axis_z(which)
        # the axis runs the usual way or backwards, and a range that could
        # not be shown on a logarithmic scale is lifted off zero
        self.apply_axis_scale(which)
        self.empty_axis_range(which)
        if which in ("y", "y2"):  # fills reaching the bottom follow the range
            for column, fill_cfg in self.fill_state.items():
                if (fill_cfg.get("on") and fill_cfg.get("base") == "bottom"
                        and self.series_side(column) == ("right" if which == "y2"
                                                         else "left")):
                    self.refresh_fill(column)
        self._apply_axis_sides()     # which numbers are shown, and the grid
        if redraw:
            self.draw()

    # -- events ------------------------------------------------------------
    def _on_pick(self, event):
        """matplotlib offers the artist a click was on.

        Nothing is done with it any more.  Everything in the diagram is
        found by its own hit test in the press handler below - which is the
        only way to reach the curves of the left axis once a right axis
        lies over them - and a single click now grabs the graph rather than
        opening anything.  The handler stays connected so that the picker
        settings of the artists keep their meaning.
        """
        return None

    def object_at(self, x, y):
        """(kind, key) of the object under the pointer, the topmost first."""
        if self.selection is not None and self.handle_at(x, y) is not None:
            return self.selection            # a control point of the selection
        key = self.arrow_at(x, y)
        if key is not None:
            return ("arrow", key)
        key = self.shape_at(x, y)
        if key is not None:
            return ("shape", key)
        key = self.note_at(x, y)
        if key is not None:
            return ("note", key)
        name = self.text_at(x, y)
        if name is not None:
            return ("text", name)
        column, legend = self.legend_at(x, y)
        if legend is not None:
            return ("legend", column)
        if self.frame_hit(x, y):
            return ("frame", "frame")
        return (None, None)

    def axis_end_at(self, x, y, tolerance=8.0):
        """Index of the axis control point under the pointer, or None."""
        kind, key = self.selection or (None, None)
        if kind != "axis":
            return None
        for index, point in enumerate(self.axis_handle_positions(key)):
            px, py = self.ax.transAxes.transform(point)
            if abs(px - x) <= tolerance and abs(py - y) <= tolerance:
                return index
        return None

    def open_properties(self, kind, key):
        """The property window of one object, whatever kind it is."""
        if kind == "arrow":
            return self.edit_arrow(key)
        if kind == "shape":
            return self.edit_shape(key)
        if kind == "note":
            return self.edit_note(key)
        if kind == "legend":
            return self.edit_legend_entry(key)
        if kind == "text":
            return (self.edit_title() if key == "title"
                    else self.edit_axis_label(key))
        if kind in ("frame", "axis"):
            return self.open_axes_dialog("frame")
        return None

    def _on_double_click(self, event):
        """The second click opens the properties of what is under it.

        A single click moves things about - the whole graph included - so
        every property window is reached by clicking twice: a drawing, an
        arrow, a text box, a legend entry, a **curve**, the frame and the
        numbers of an axis alike.

        A legend box has two parts: its **text** opens the legend editor,
        and its **sample** - the little line, marker or patch in front of
        the text - opens the properties of the curve it stands for.
        """
        kind, key = self.object_at(event.x, event.y)
        if kind == "legend" and self.legend_sample_hit(key, event.x, event.y):
            line = self.series.get(key)
            if line is not None:
                if self.selection is not None:
                    self.select_object(None, None)
                    self.draw()
                self.open_series_dialog(line)
                return True
        if kind is not None and kind != "frame":
            self.select_object(kind, key)
            self.draw()
            self.open_properties(kind, key)
            return True
        name = self.series_at(event)       # a curve of either Y axis
        if name is not None:
            if self.selection is not None:
                self.select_object(None, None)
                self.draw()
            self.open_series_dialog(self.series[name])
            return True
        if kind == "frame":                # the frame itself is not selected
            self.open_properties(kind, key)
            return True
        which = self._axis_hit(event)      # the numbers or the label of an axis
        if which:
            self.open_axes_dialog(which)
            return True
        return False

    def _on_button_press(self, event):
        # the keyboard focus is taken by the native <Button-1> binding of the
        # canvas widget (see take_focus), not from inside this handler
        if self._inline is not None:       # a click elsewhere finishes writing
            self.commit_inline_edit()
        if event.button == 3:              # the right button opens the menu
            gui = getattr(event, "guiEvent", None)
            self.show_object_menu(event.x, event.y,
                                  getattr(gui, "x_root", None),
                                  getattr(gui, "y_root", None))
            return
        if event.dblclick:                 # every object needs two clicks
            self._rename_click = None      # a real double click is not a rename
            self._rename_prev = None
            self._pending_rename = None
            self._on_double_click(event)
            return
        if event.button != 1:
            return
        self._pending_rename = None
        # only a second click on the very same, already selected text opens
        # the in-place editor: any other click starts the count again
        self._rename_prev, self._rename_click = self._rename_click, None
        if self._pending_text:            # place a new text box here
            if event.x is not None and event.y is not None:
                key = self.add_note(self._axes_point(event))
                self.arm_text_placement(False)
                self.after(1, lambda k=key: self.edit_note(k))
            return
        if self._pending_shape:           # start drawing a new object
            if event.x is not None and event.y is not None:
                point = self._axes_point(event)
                key = self.add_shape(self.shape_kind, point, (0.0, 0.0))
                self._shape_drag = {"key": key, "mode": "new", "anchor": point}
                self.arm_shape_drawing(armed=False)
                self.select_shape(key)
            return
        if self._pending_arrow:           # start drawing a new arrow
            if event.x is not None and event.y is not None:
                point = self._axes_point(event)
                key = self.add_arrow(self.arrow_head, point, point)
                self._shape_drag = {"key": key, "mode": "arrow-new"}
                self.arm_arrow_drawing(armed=False)
                self.select_object("arrow", key)
            return

        # a drag is one single step: what the diagram looked like before
        # the button went down is what Undo puts back
        app = getattr(self, "app", None)
        self._drag_before = (app.plot_document(self)
                             if app is not None and not app.undo.busy()
                             else None)
        index = self.handle_at(event.x, event.y)
        if index == ROTATE_HANDLE:        # turn the selected object
            kind, key = self.selection
            centre = self.rotation_centre()
            start = self._pointer_angle(event, centre)
            if centre is not None and start is not None:
                self._shape_drag = {"key": key, "mode": "rotate", "kind": kind,
                                    "centre": centre, "pointer": start,
                                    "angle": self.angle_of(self.selected_state())}
            return
        if index is not None:             # resize the selected object
            kind, key = self.selection
            mode = "resize"
            if kind == "axis":
                mode = "axis-end"
            elif kind == "arrow":
                mode = "arrow-end"
            elif (kind == "shape"
                  and self.shape_state[key]["kind"] in OPEN_SHAPES):
                mode = "line-end"         # a line is dragged by its two ends
            self._shape_drag = {"key": key, "index": index, "mode": mode,
                                "grab": self._grab_offset(index, event)}
            if mode == "resize" and kind == "shape":
                state = self.shape_state[key]
                self._shape_drag["ratio"] = self.shape_ratio(state)
                self._shape_drag["locked"] = (state.get("kind")
                                              == PICTURE_KIND)
            if mode == "line-end":
                # the end that stays is remembered, so that dragging one end
                # past the other one does not swap them mid-drag
                ends = self.line_ends(self.shape_state[key])
                self._shape_drag["fixed"] = tuple(ends[1 - index])
            return
        if self.group:                    # grabbing one of a group: all move
            hit = self.object_at(event.x, event.y)
            if hit is not None and tuple(hit) in self.group:
                self._group_drag = {"x": float(event.x), "y": float(event.y),
                                    "moved": False}
                self._set_cursor("fleur")
                return
        key = self.arrow_at(event.x, event.y)
        if key is not None:               # select an arrow and drag it
            self.select_object("arrow", key)
            self.announce_selection()
            self.draw()
            state = self.arrow_state[key]
            self._shape_drag = {"key": key, "mode": "arrow-move", "moved": False,
                                "start": self._axes_point(event),
                                "tail": tuple(state["tail"]),
                                "tip": tuple(state["tip"])}
            return
        key = self.shape_at(event.x, event.y)
        if key is not None:               # select a drawing and drag it
            self.select_shape(key)
            self.announce_selection()
            self.draw()
            state = self.shape_state[key]
            self._shape_drag = {"key": key, "mode": "move", "moved": False,
                                "start": self._axes_point(event),
                                "origin": (state["x"], state["y"])}
            return
        key = self.note_at(event.x, event.y)
        if key is not None:               # select a text box and drag it
            self._arm_inline_edit("note", key, event)
            self.select_object("note", key)
            self.announce_selection()
            self.draw()
            self._start_text_drag(f"{NOTE_KEY}{key}", event)
            return
        name = self.text_at(event.x, event.y)
        if name is not None:              # the title or an axis label
            self._arm_inline_edit("text", name, event)
            self.select_object("text", name)
            self.announce_selection()
            self.draw()
            self._start_text_drag(name, event)
            return
        y_col, legend = self.legend_at(event.x, event.y)
        if legend is not None:            # select a legend box and drag it
            row = self.legend_row_at(legend, event.x, event.y)
            if not hasattr(self, "_legend_row"):
                self._legend_row = {}
            self._legend_row[str(y_col)] = 0 if row is None else int(row)
            self._arm_inline_edit("legend", y_col, event)
            self.select_object("legend", y_col)
            self.announce_selection()
            self.draw()
            self._start_legend_drag(y_col, event)
            return
        side = self.frame_axis_at(event.x, event.y)
        if side is not None:              # an axis line: select it to resize
            self.select_object("axis", side)
            self.draw()
            self.flash(f"{SIDE_NAMES.get(side, side)} selected - drag the line "
                       "to move the graph, drag one of its ends to resize it, "
                       "double click for frame and origin")
            self._start_plot_drag(event)  # ...and dragging it carries the graph
            return
        name = self.series_at(event)      # a curve of either Y axis
        if name is not None:
            # a curve is never "selected", and a single click no longer opens
            # its properties: it grabs the graph, and two clicks open the
            # curve.  What was selected before is let go, as with any click.
            if self.selection is not None or self.group:
                self.select_object(None, None)
                self.clear_group()
                self.draw()
            self._start_plot_drag(event)
            return
        if (self.numbers_at(event.x, event.y) is not None
                or self.frame_hit(event.x, event.y)):
            # the numbers of an axis and the frame are the graph as well:
            # grabbed, they carry it, just as an axis line or a curve does
            if self.selection is not None or self.group:
                self.select_object(None, None)
                self.clear_group()
                self.draw()
            self._start_plot_drag(event)
            return
        # the background - the paper, or the empty plot area - no longer
        # carries the graph: a rectangle is drawn instead, and whatever it
        # touches is chosen, to be moved together
        self._start_band(event)

    def series_at(self, event):
        """The curve under the pointer, whichever Y axis it belongs to.

        matplotlib offers a click only to the artists of the axes the
        pointer is in, and the second Y axis lies over the first one - so
        the curves of the **left** axis would never hear a click as soon as
        a right axis exists.  The hit test is therefore done here, over
        every curve of the diagram and over everything drawn for it (the
        bars, the staircase, the slices, the filled area).
        """
        if event is None or event.x is None or event.y is None:
            return None
        for axes in reversed(self.plot_axes()):        # the topmost first
            for artist in reversed(list(axes.get_children())):
                name = getattr(artist, "aplot_series", None)
                if name is None or name not in self.series:
                    continue
                try:
                    if not artist.get_visible():
                        continue
                    hit, _info = artist.contains(event)
                except (ValueError, TypeError, AttributeError, RuntimeError):
                    continue
                if hit:
                    return name
        return None

    def frame_side_at(self, x, y):
        """Name of the visible frame side under the pointer, or None."""
        if x is None or y is None:
            return None
        box = self.ax.get_window_extent()
        tolerance = max(4.0, self.frame_cfg["width"] + 3.0)
        vertical = box.y0 - tolerance <= y <= box.y1 + tolerance
        horizontal = box.x0 - tolerance <= x <= box.x1 + tolerance
        sides = {"left": horizontal and vertical and abs(x - box.x0) <= tolerance,
                 "right": horizontal and vertical and abs(x - box.x1) <= tolerance,
                 "bottom": horizontal and vertical and abs(y - box.y0) <= tolerance,
                 "top": horizontal and vertical and abs(y - box.y1) <= tolerance}
        for name, hit in sides.items():
            if hit and self.ax.spines[name].get_visible():
                return name
        return None

    def frame_axis_at(self, x, y):
        """The side of the plot area whose line is under the pointer.

        One of "bottom", "top", "left" and "right" - the side itself, so
        that the control points appear on the line that was clicked.
        """
        return self.frame_side_at(x, y)

    def frame_hit(self, x, y):
        """True when the pointer is on one of the visible frame sides."""
        return self.frame_side_at(x, y) is not None

    # -- the whole graph is dragged to another place ----------------------
    def scale_plot_area(self, factor):
        """`Resize graph`: the graph grows or shrinks around its own middle.

        One step of the menu is ten per cent of the length of both axes.
        The middle of the plot area stays where it is, and the graph is
        kept inside the page; everything drawn in it - the curves, the
        legend boxes, the text boxes, the drawings and the arrows - keeps
        its place inside the plot area and follows.

        The **look** of the diagram follows as well: the fonts, the line
        widths, the tick marks and the distances of the texts are all
        multiplied by the same factor (see `scale_style_document`), so a
        graph made larger is the very same picture, only larger.
        """
        factor = float(factor)
        if factor <= 0:
            return False
        cfg = self.frame_cfg
        width = float(cfg.get("x_length", 0.7))
        height = float(cfg.get("y_length", 0.7))
        new_width = min(max(width * factor, MIN_AXIS_SIZE), 1.0)
        new_height = min(max(height * factor, MIN_AXIS_SIZE), 1.0)
        if abs(new_width - width) < 1e-9 and abs(new_height - height) < 1e-9:
            self.flash("The graph cannot be made any "
                       + ("larger" if factor > 1 else "smaller"))
            return False
        middle_x = float(cfg.get("left", 0.13)) + width / 2.0
        middle_y = float(cfg.get("bottom", 0.125)) + height / 2.0
        left = min(max(middle_x - new_width / 2.0, 0.0), 1.0 - new_width)
        bottom = min(max(middle_y - new_height / 2.0, 0.0), 1.0 - new_height)
        with self.changed("the size of the graph"):
            self.apply_frame({**cfg, "left": left, "bottom": bottom,
                              "x_length": new_width, "y_length": new_height})
            # the axes may have run into the edge of the page, so the step
            # the drawing really took is measured, not the one asked for
            self.scale_graph_style(style_factor(width, height,
                                                new_width, new_height))
        self.flash(f"The graph is {'larger' if factor > 1 else 'smaller'} - "
                   f"{new_width * 100:.0f}% x {new_height * 100:.0f}% of the page")
        return True

    def drawn_size(self):
        """The room the whole diagram takes on the page, in cm.

        Not the plot area alone: the numbers, the axis labels, the title,
        the legend boxes and everything drawn in the diagram are measured
        with it - the same box an exported picture is cropped to.  It is
        `(width, height, middle x, middle y)`, all of them in cm from the
        bottom left corner of the page, or None when nothing can be
        measured (a window that has never been drawn).
        """
        try:
            box = self.fig.get_tightbbox(self._renderer())
        except (AttributeError, RuntimeError, ValueError, tk.TclError):
            return None
        if box is None:
            return None
        try:                       # matplotlib measures it in inches
            width, height = float(box.width) * 2.54, float(box.height) * 2.54
            middle_x = (float(box.x0) + float(box.x1)) / 2.0 * 2.54
            middle_y = (float(box.y0) + float(box.y1)) / 2.0 * 2.54
        except (TypeError, ValueError):
            return None
        if not (np.isfinite(width) and np.isfinite(height)):
            return None
        if width <= 1e-6 or height <= 1e-6:
            return None
        return width, height, middle_x, middle_y

    def fit_to_page(self, _event=None):
        """`Resize graph > Fit to page`: the diagram fills the whole page.

        The graph is made as large as it can be while the whole of it -
        the plot area **and** the numbers, the axis labels, the title and
        the legend boxes around it - still stands on the page with about
        `PAGE_FIT_MARGIN` cm of white around it, and it is put in the
        middle of the page.  The two directions are fitted on their own,
        so the white left over is the same strip on all four sides; on a
        small page a long title can keep a millimetre or two of it, since
        a font size is a whole number of points and cannot shrink further.

        The fonts, the line widths and the tick marks grow with the axes
        (see `scale_style_document`), so the whole diagram is scaled like
        a picture: what fills the page is the same graph, larger.  That is
        also why the fit converges in one or two rounds - it is measured
        again after every round, because a font size is a whole number of
        points and cannot follow the axes to the last per cent.
        """
        room_w = max(1.0, float(self.page_size[0]) - 2.0 * PAGE_FIT_MARGIN)
        room_h = max(1.0, float(self.page_size[1]) - 2.0 * PAGE_FIT_MARGIN)
        page_middle = (float(self.page_size[0]) / 2.0,
                       float(self.page_size[1]) / 2.0)
        done = False
        with self.changed("the size of the graph"):
            for _round in range(PAGE_FIT_ROUNDS):
                drawn = self.drawn_size()
                if drawn is None:
                    break
                width, height, middle_x, middle_y = drawn
                # the two directions are fitted on their own, so the white
                # left over is the same margin on all four sides; the room
                # the texts need does not follow one axis alone, which is
                # why the fit is measured again after every round
                factor_x = room_w / width
                factor_y = room_h / height
                moved = (abs(middle_x - page_middle[0]) / self.page_size[0],
                         abs(middle_y - page_middle[1]) / self.page_size[1])
                if (abs(factor_x - 1.0) < 0.002 and abs(factor_y - 1.0) < 0.002
                        and max(moved) < 0.002):
                    break             # as large and as central as it gets
                done = self._fit_round(factor_x, factor_y, page_middle) or done
            # should the rounds have stopped a hair over the margin, one
            # last even step takes the whole diagram back inside it
            drawn = self.drawn_size()
            if drawn is not None:
                guard = min(room_w / drawn[0], room_h / drawn[1])
                if guard < 0.999:
                    done = self._fit_round(guard, guard, page_middle) or done
        if not done:
            self.flash("The graph already fills the page")
            return False
        self.flash("The graph fills the page")
        return True

    def _fit_round(self, factor_x, factor_y, page_middle):
        """One round of `Fit to page`: grow the graph, then centre it.

        The growing comes first and keeps the middle of the plot area
        where it is; only then is the diagram measured again and carried
        to the middle of the page.  The plot area is not in the middle of
        its own drawing - the numbers and the labels stand on two sides of
        it - so the two steps cannot be done in one.
        """
        cfg = self.frame_cfg
        width = float(cfg.get("x_length", 0.7))
        height = float(cfg.get("y_length", 0.7))
        left = float(cfg.get("left", 0.13))
        bottom = float(cfg.get("bottom", 0.125))
        new_width = min(max(width * factor_x, MIN_AXIS_SIZE), 1.0)
        new_height = min(max(height * factor_y, MIN_AXIS_SIZE), 1.0)
        grew = (abs(new_width - width) > 1e-9
                or abs(new_height - height) > 1e-9)
        if grew:
            middle_x = left + width / 2.0
            middle_y = bottom + height / 2.0
            left = min(max(middle_x - new_width / 2.0, 0.0), 1.0 - new_width)
            bottom = min(max(middle_y - new_height / 2.0, 0.0),
                         1.0 - new_height)
            self.apply_frame({**cfg, "left": left, "bottom": bottom,
                              "x_length": new_width, "y_length": new_height})
            self.scale_graph_style(style_factor(width, height,
                                                new_width, new_height))
        drawn = self.drawn_size()
        if drawn is None:
            return grew
        shift_x = (page_middle[0] - drawn[2]) / float(self.page_size[0])
        shift_y = (page_middle[1] - drawn[3]) / float(self.page_size[1])
        if max(abs(shift_x), abs(shift_y)) < 1e-6:
            return grew
        self.move_plot_area(left + shift_x, bottom + shift_y)
        return True

    def scale_graph_style(self, factor):
        """Multiply every size drawn on the paper by `factor`.

        It belongs to `Resize graph` alone: nothing else in the program
        changes the look of a diagram behind the user's back.  Dragging
        the end of an axis, typing a length into `Frame and origin` or
        resizing the window all leave the fonts and the lines exactly as
        they were.
        """
        try:
            factor = float(factor)
        except (TypeError, ValueError):
            return False
        if not np.isfinite(factor) or factor <= 0.0 or abs(factor - 1.0) < 1e-9:
            return False
        self.apply_state(scale_style_document(self.to_state(), factor))
        return True

    def move_plot_area(self, left, bottom, redraw=True):
        """Put the plot area somewhere else in the window, same size.

        Only the two distances of the origin change - the length of the two
        axes, the ranges, the ticks and everything drawn in the plot area
        stay as they are and travel with it.  The place is kept inside the
        window, so the graph cannot be pushed out of sight.
        """
        width = float(self.frame_cfg.get("x_length", 0.7))
        height = float(self.frame_cfg.get("y_length", 0.7))
        left = min(max(float(left), 0.0), max(0.0, 1.0 - width))
        bottom = min(max(float(bottom), 0.0), max(0.0, 1.0 - height))
        self.ax.set_position([left, bottom, width, height])
        if self.ax2 is not None:
            self.ax2.set_position(self.ax.get_position())
        self.frame_cfg["left"] = left
        self.frame_cfg["bottom"] = bottom
        # the objects are placed in the coordinates of the plot area, so
        # their pixels have to be worked out again where it now stands
        self.refresh_shapes()
        self.refresh_arrows()
        self._refresh_handles()
        dialog = self._dialogs.get("axes")
        if dialog is not None and dialog.winfo_exists():
            try:
                dialog.frame_tab.sync_position()
            except (AttributeError, tk.TclError):
                pass
        if redraw:
            self.draw()
        return (left, bottom)

    def plot_area_hit(self, x, y):
        """True when the pointer is inside the plot area (or on its edge)."""
        if x is None or y is None:
            return False
        box = self.ax.get_window_extent()
        tolerance = max(4.0, float(self.frame_cfg.get("width", 1.0)) + 3.0)
        return (box.x0 - tolerance <= x <= box.x1 + tolerance
                and box.y0 - tolerance <= y <= box.y1 + tolerance)

    def toolbar_busy(self):
        """True while the pan or the zoom tool of the toolbar is switched on.

        Those two drive the canvas themselves - one moves the data inside
        the axes, the other draws a rectangle - so the graph must not be
        carried about under them.
        """
        try:
            return bool(str(getattr(self.toolbar, "mode", "") or ""))
        except (AttributeError, tk.TclError):
            return False

    def _start_plot_drag(self, event):
        """Remember where the graph stood when the button went down."""
        if event is None or event.x is None or event.y is None \
                or self.toolbar_busy():
            self._plot_drag = None
            return None
        bounds = self.ax.get_position().bounds
        self._plot_drag = {"x": float(event.x), "y": float(event.y),
                           "left": float(bounds[0]),
                           "bottom": float(bounds[1]), "moved": False}
        return self._plot_drag

    def _drag_plot_to(self, event):
        """Carry the graph along with the pointer."""
        drag = self._plot_drag
        if drag is None or event.x is None or event.y is None:
            return False
        dx = float(event.x) - drag["x"]
        dy = float(event.y) - drag["y"]
        if not drag["moved"] and abs(dx) < PLOT_DRAG_START \
                and abs(dy) < PLOT_DRAG_START:
            return False               # still a click, not yet a drag
        width = float(self.fig.get_figwidth() * self.fig.dpi)
        height = float(self.fig.get_figheight() * self.fig.dpi)
        if width <= 0 or height <= 0:
            return False
        if not drag["moved"]:
            drag["moved"] = True
            self.flash("Moving the graph - let go where it should stand")
            self._set_cursor("fleur")
        self.move_plot_area(drag["left"] + dx / width,
                            drag["bottom"] + dy / height)
        return True

    # -- the axes are resized by their two ends ----------------------------
    @staticmethod
    def axis_side(which):
        """The frame side one name means ("x" and "y" are the old names)."""
        name = SIDE_ALIASES.get(str(which), str(which))
        return name if name in FRAME_ENDS else None

    def axis_handle_positions(self, which):
        """The two ends of one axis, in the coordinates of the plot area.

        Each of the four sides has its own pair: the bottom and the top line
        end in the lower and the upper corners, the left and the right line
        in the corners of their own edge.
        """
        side = self.axis_side(which)
        if side is None:
            return [(0.0, 0.0), (1.0, 0.0)]
        return [tuple(point) for point in FRAME_ENDS[side]]

    def _figure_point(self, event):
        """The pointer as a fraction of the whole figure."""
        point = self.fig.transFigure.inverted().transform((event.x, event.y))
        return (float(point[0]), float(point[1]))

    def resize_axis(self, which, index, point):
        """Pull one end of an axis: the plot area grows or shrinks there.

        The two horizontal sides (the bottom and the top X axis) carry the
        width of the diagram, the two vertical ones (the left and the right
        Y axis) its height - whichever of them is pulled.
        """
        side = self.axis_side(which) or "bottom"
        cfg = dict(self.frame_cfg)
        left, bottom = float(cfg["left"]), float(cfg["bottom"])
        width, height = float(cfg["x_length"]), float(cfg["y_length"])
        if side in HORIZONTAL_SIDES:
            if index == 0:                      # the left end moves
                right = left + width
                left = min(max(0.02, point[0]), right - MIN_AXIS_SIZE)
                width = right - left
            else:                               # the right end moves
                width = min(max(MIN_AXIS_SIZE, point[0] - left), 0.995 - left)
        else:
            if index == 0:                      # the bottom end moves
                top = bottom + height
                bottom = min(max(0.02, point[1]), top - MIN_AXIS_SIZE)
                height = top - bottom
            else:                               # the top end moves
                height = min(max(MIN_AXIS_SIZE, point[1] - bottom), 0.995 - bottom)
        cfg.update({"left": left, "bottom": bottom,
                    "x_length": width, "y_length": height})
        self.apply_frame(cfg)
        return cfg

    def move_axes(self, dx_pixels, dy_pixels):
        """Shift the whole plot area, keeping its size (the arrow keys)."""
        cfg = dict(self.frame_cfg)
        width = float(self.fig.get_figwidth() * self.fig.get_dpi())
        height = float(self.fig.get_figheight() * self.fig.get_dpi())
        if width <= 0 or height <= 0:
            return False
        left = float(cfg["left"]) + float(dx_pixels) / width
        bottom = float(cfg["bottom"]) + float(dy_pixels) / height
        cfg["left"] = min(max(0.02, left), 0.995 - float(cfg["x_length"]))
        cfg["bottom"] = min(max(0.02, bottom), 0.995 - float(cfg["y_length"]))
        self.apply_frame(cfg)
        return True

    def _axis_hit(self, event):
        """Which axis region (tick labels / axis label) was clicked?"""
        if event.x is None or event.y is None:
            return None
        box = self.ax.get_window_extent()
        if box.x0 <= event.x <= box.x1:
            if self.x_side == "top":
                if box.y1 < event.y <= box.y1 + 80:
                    return "x"
            elif box.y0 - 80 <= event.y < box.y0:
                return "x"
        if box.y0 <= event.y <= box.y1:
            if box.x0 - 90 <= event.x < box.x0 and self.left_axis_shown():
                return "y"
            if self.right_axis_active() and box.x1 < event.x <= box.x1 + 90:
                return "y2"
        return None

    # -- dialogs -----------------------------------------------------------
    def _show_dialog(self, key, factory):
        existing = self._dialogs.get(key)
        if existing is not None and existing.winfo_exists():
            existing.lift()
            existing.focus_force()
            return existing
        dialog = factory()
        self._dialogs[key] = dialog
        return dialog

    def open_series_dialog(self, line):
        column = getattr(line, "aplot_series", None)
        state = self.legend_state.get(column) or {}

        def set_legend_style(size, color):
            if column in self.legend_state:
                self.legend_state[column]["size"] = size
                self.legend_state[column]["color"] = color

        def set_fill(values):
            if column is not None:
                self.fill_state[column] = values
                self.refresh_fill(column)

        def set_plot_style(st):
            if column is not None:
                self.series_style[column] = st
                # a pie owns the whole area: the axes step aside for it and
                # come back the moment a curve needs them again
                self.apply_style_axes()
                self.refresh_series_visuals(column)
                # a pie reads no X column, so leaving it may bring the row
                # numbers (or the first column) back to the X axis
                self._refresh_x_label()
                # a histogram carries its own counts: the range follows
                self._rescale()
                self.refresh_legend()
                self.draw()

        def set_bar_cfg(cfg):
            if column is not None:
                self.bar_cfg[column] = cfg
                self.refresh_series_visuals(column)

        def set_histogram_cfg(cfg):
            if column is None:
                return
            before = self.histogram_bins(column)
            self.histogram_cfg[column] = cfg
            self.refresh_series_visuals(column)
            if before != self.histogram_bins(column):
                self._rescale()      # other bins, other counts and range

        def set_stairs_cfg(cfg):
            if column is not None:
                self.stairs_cfg[column] = cfg
                self.refresh_series_visuals(column)
                self._rescale()      # other edges, other range

        def set_hist2d_cfg(cfg):
            if column is not None:
                self.hist2d_cfg[column] = cfg
                self.refresh_series_visuals(column)

        def set_pie_cfg(cfg):
            if column is not None:
                # merged, not replaced: the names typed into the legend rows
                # are not settings of the dialog and must survive every
                # other change made there
                self.pie_cfg[column] = {**(self.pie_cfg.get(column) or {}),
                                        **cfg}
                self.refresh_series_visuals(column)
                self.refresh_legend()
                self.draw()

        def set_error_cfg(cfg):
            if column is not None:
                self.error_cfg[column] = cfg
                self.refresh_series_visuals(column)

        cols = list(self.df.columns)
        return self._show_dialog(id(line), lambda: SeriesStyleDialog(
            self, line,
            on_change=lambda: (self.refresh_series_visuals(column), self.refresh_legend(), self.draw()),
            on_close=lambda _d: self._dialogs.pop(id(line), None),
            legend_size=state.get("size", self.fonts["legend"]),
            legend_color=state.get("color", self.fonts["legend_color"]),
            on_legend_style=set_legend_style,
            fill=self.fill_state.get(column),
            on_fill=set_fill,
            plot_style=self.series_style.get(column, self.plot_style),
            on_plot_style=set_plot_style,
            bar_cfg=self.bar_cfg.get(column),
            on_bar_cfg=set_bar_cfg,
            histogram_cfg=self.histogram_cfg.get(column),
            on_histogram_cfg=set_histogram_cfg,
            stairs_cfg=self.stairs_cfg.get(column),
            on_stairs_cfg=set_stairs_cfg,
            hist2d_cfg=self.hist2d_cfg.get(column),
            on_hist2d_cfg=set_hist2d_cfg,
            pie_cfg=self.pie_cfg.get(column),
            on_pie_cfg=set_pie_cfg,
            error_cfg=self.error_cfg.get(column),
            on_error_cfg=set_error_cfg,
            available_columns=cols))

    def open_axes_dialog(self, which="x"):
        existing = self._dialogs.get("axes")
        if existing is not None and existing.winfo_exists():
            existing.mirror()               # the diagram may have moved on
            existing.select_tab(which)      # jump to the requested tab
            existing.lift()
            existing.focus_force()
            return existing
        return self._show_dialog("axes", lambda: AxesDialog(
            self, self, which, on_close=lambda _d: self._dialogs.pop("axes", None)))

    def open_title_dialog(self):
        return self._show_dialog("title", lambda: TitleFontDialog(
            self, self, on_close=lambda _d: self._dialogs.pop("title", None)))

    def edit_title(self):
        def apply(text, size, color, distance):
            self.fonts["title"] = size
            self.fonts["title_color"] = color
            if distance is not None:
                self.fonts["title_pad"] = distance
            self.ax.set_title(text, fontsize=size, color=color,
                              pad=self.page_points(self.fonts["title_pad"]))
            self.ax.title.set_picker(True)
            self.apply_text_offset("title")   # set_title resets the placement
            self.draw()

        return self._show_dialog("title-text", lambda: TextStyleDialog(
            self, "Plot title", self.ax.get_title(), self.fonts["title"], apply,
            color=safe_hex(self.fonts["title_color"], "#000000"),
            distance=self.fonts["title_pad"],
            distance_label="Distance from the axes [px]:",
            hint="The distance is measured from the top of the plot area.",
            on_close=lambda _d: self._dialogs.pop("title-text", None),
            source=lambda: (self.ax.get_title(), self.fonts["title"],
                            self.fonts["title_color"],
                            self.fonts["title_pad"])))

    def edit_axis_label(self, which):
        def apply(text, size, color, distance):
            cfg = dict(self.axis_cfg[which])
            cfg.update({"label": text, "label_size": size, "label_color": color})
            if distance is not None:
                cfg["label_pad"] = distance
            self.apply_axis(which, cfg)

        return self._show_dialog(f"label-{which}", lambda: TextStyleDialog(
            self, f"{AXIS_NAMES.get(which, which.upper())} label",
            self.axis_label(which),
            self.axis_cfg[which]["label_size"], apply,
            color=self.axis_cfg[which]["label_color"],
            distance=self.axis_cfg[which]["label_pad"],
            distance_label="Distance from the axis [px]:",
            hint="The colour and the distance of the numbers are on the\n"
                 "axis tab of the axes properties dialog.",
            on_close=lambda _d: self._dialogs.pop(f"label-{which}", None),
            source=lambda: (self.axis_label(which),
                            self.axis_cfg[which]["label_size"],
                            self.axis_cfg[which]["label_color"],
                            self.axis_cfg[which]["label_pad"])))

    def edit_legend_entry(self, column):
        line = self.series.get(column)
        if line is None:
            return None
        state = self.legend_state.setdefault(column, self.default_legend_state(0))

        def apply(values):
            # the curve and its box as they are now, not as they were when
            # the window opened
            current = self.series.get(column)
            if current is None:
                return
            text = values.pop("text", "").strip()
            current.set_label(text if text else "_nolegend_")
            self.legend_state.setdefault(
                column, self.default_legend_state(0)).update(values)
            self.refresh_legend()
            self.draw()

        return self._show_dialog(f"legend-{column}", lambda: TextBoxDialog(
            self, f"Legend of '{column}'", line.get_label(), state, apply,
            hint="An empty text hides this legend box.",
            on_close=lambda _d: self._dialogs.pop(f"legend-{column}", None),
            source=lambda: (None if self.series.get(column) is None else
                            (self.legend_text(column),
                             self.legend_state.get(column) or {}))))

    def legend_text(self, column):
        """The legend text of one curve; empty while its box is hidden."""
        line = self.series.get(column)
        label = "" if line is None else str(line.get_label())
        return "" if label.startswith("_") else label


# --------------------------------------------------------------------------
# documentation
# --------------------------------------------------------------------------

DOCUMENTATION = """\
# APlot - Data Visualizer

APlot is a small desktop program for typing or loading tabular data and
turning it into a Matplotlib diagram whose every detail can be changed by
clicking on it.  It is a **single Python file**.

Start it with:

    python3 aplot.py

It also answers a few questions on the command line:

    python3 aplot.py --help          what these are
    python3 aplot.py --version       which APlot this is
    python3 aplot.py FILE.aplt       start with that graph open
    python3 aplot.py --make-app      build APlot.app on macOS (see below)
    python3 aplot.py --icon FILE     write the icon into a PNG file
    python3 aplot.py --install-desktop   Linux: icons, thumbnails and
                                         "open with" for .aplt (see below)


## Version

This is **APlot 1.0.0 (2026-10-01)**.  The number is written in one place
only, `APP_VERSION` near the top of `aplot.py` (with `APP_VERSION_DATE`
beside it); the About window, `python3 aplot.py --version`, APlot.app on a
Mac and every saved `.aplt` file (`application_version` in
`document.json`) all read it from there.

The numbers follow **Semantic Versioning**, `MAJOR.MINOR.PATCH`:

| Step | Example | When |
| --- | --- | --- |
| PATCH | 1.0.0 -> 1.0.1 | a fix: nothing new to learn, the files stay the same |
| MINOR | 1.0.1 -> 1.1.0 | something new; every older `.aplt` file still opens |
| MAJOR | 1.1.0 -> 2.0.0 | a change older versions cannot follow, such as a new kind of `.aplt` file |

A release is made in four small steps: raise `APP_VERSION` and set
`APP_VERSION_DATE`, write the same number into the description at the top
of `aplot.py`, add a line to the **Version history** below, and - with git
keeping the history of the code - commit and tag it:

    git commit -am "APlot 1.0.1"
    git tag -a v1.0.1 -m "APlot 1.0.1"

`git log` then lists every change, `git diff v1.0.0 v1.0.1` shows what a
release changed, and `git checkout v1.0.0` brings back an older version
exactly as it was.

### Version history

| Version | Date | What changed |
| --- | --- | --- |
| 1.0.0 | 2026-10-01 | The first numbered version: the spreadsheet with its sheets, formulas and fits, the diagrams with every property window, drawings, arrows and pictures, the `.aplt` container with its pictures and the previews of macOS and Linux. |


## What it needs

Four packages have to be there; everything else is part of Python itself.

| Package | Used for | Install |
| --- | --- | --- |
| `tkinter` | the whole user interface: windows, menus, the table | comes with Python (on some Linux systems as the separate `python3-tk` package) |
| `numpy` | every calculation: the curves, the histograms, the fitting | `pip install numpy` |
| `pandas` | the sheets themselves and the reading of data files | `pip install pandas` |
| `matplotlib` | the diagrams, and the pictures that are exported | `pip install matplotlib` |

All four at once:

    pip install numpy pandas matplotlib

### Optional packages

The program **starts and works without every one of these**.  Each of them
switches one convenience on, and when it is missing the program says so
quietly or simply leaves that one thing out.

| Package | What it adds when it is there | Without it |
| --- | --- | --- |
| **`tkinterdnd2`** | **dropping a picture** from the Finder onto a diagram (it brings the `tkdnd` extension of Tk, which Tk itself has no drop support without) | pictures still arrive by pasting (`Ctrl/Cmd+V`), through the picture button of the toolbar and through `Plot > Insert picture...` |
| `pillow` (`PIL`) | the drawn **toolbar icons**, reading a **picture** that is pasted or dropped, and the clipboard of the system | the buttons carry their names in words and pictures cannot be inserted |
| `openpyxl` | opening and saving **Excel** (`.xlsx`) files, one sheet per tab | CSV, TXT, DAT and the program's own `.aplt` files work as usual |
| `pyobjc-framework-Cocoa` | the bold application menu on **macOS** is called `APlot` | that menu keeps the name of the Python interpreter (the Dock label is settled by `--make-app` either way) |

    pip install tkinterdnd2 pillow openpyxl
    pip install pyobjc-framework-Cocoa        # macOS only

An optional package is always imported inside a `try`, so a missing one is
never an error.  An editor that checks the imports (VS Code with Pylance,
for instance) may still mark such a line as unresolved - that is the editor
saying the package is not installed in the interpreter **it** has selected,
not a fault in the program.

**Install into the interpreter that really runs APlot.**  A bare `pip` often
belongs to another Python than the `python3` that starts the program; this
always lands in the right place:

    python3 -m pip install tkinterdnd2

and `python3 -c "import sys; print(sys.executable)"` says which interpreter
that is.

### The one file

Beside `aplot.py` the program writes `~/.aplot/config.json` the first time
the settings are saved, and nothing else.  No `icons` folder, no data
directory: the toolbar icons are drawn by the program itself, and a graph
carries its data, its formulas and even its pictures inside its own `.aplt`
file.

### The icon, and the name in the Dock

The program **draws its own icon**: a spectrum, its blue body under an
orange outline, on a rounded square and nothing else on it.  It is drawn,
not carried as a picture file, so it is sharp at whatever size the system
asks for and the single file stays the only thing to copy.  Every window
wears it - on Linux and Windows in the task bar, on macOS in the Dock.

Three constants at the top of `aplot.py` decide how it is drawn:

| Constant | What it sets |
| --- | --- |
| `APP_ICON_SIZE` (512) | the number of pixels the icon is drawn at - how **sharp** it is, not how big it appears. |
| `APP_ICON_SIZES` | the sizes written into `APlot.app`'s `.icns`, each also at `@2x`. |
| `APP_ICON_MARGIN` (0.1) | the **free border** left around the rounded square, as a part of the whole picture. |

How large the icon *appears* in the Dock is not the program's to decide: it
is the size of the Dock tile, which is a setting of macOS itself.  What the
margin does is leave the same free border around the square that Apple's
own icons have, so APlot sits at the same size as its neighbours instead of
filling its tile edge to edge.  Setting it to `0.0` fills the tile
completely; the whole drawing - the square, its rounded corners and the
spectrum on it - scales with it.

`python3 aplot.py --icon aplot.png` writes it out, for a launcher, a
shortcut or a `.desktop` file of your own.

#### The name under the icon on macOS

The Dock shows the icon at once, but the **name above it** is a different
matter: a program started as `python3 aplot.py` *is* the Python interpreter
as far as macOS is concerned, so the label reads `python3.12`.  No setting
inside a running program changes that - the name comes from the application
the system thinks it launched.

The cure is a small **application bundle**, and APlot builds one for
itself.  The first time it is started on a Mac it offers to do so, and the
offer is made **once**, whatever the answer.  It can also be asked at any
time:

* the **`APlot > Install APlot in the Dock...`** menu item (it is there
  only while the name is still borrowed), or
* from a terminal:

        python3 aplot.py --make-app

Either way `~/Applications/APlot.app` is written.  It is a folder, not a
copy: it holds the icon, the name and a three-line launcher that starts
**this same `aplot.py`**, wherever it lies - nothing is compiled and
nothing is duplicated.  Start APlot from there (and keep it in the Dock)
and the label says `APlot`.  Give the command a folder of your own to put
the bundle somewhere else:

    python3 aplot.py --make-app /Applications

Run it again after moving `aplot.py`, so that the launcher points at the
new place.

With `pyobjc-framework-Cocoa` installed the program also tells macOS its
name and its bundle directly, which is what the **bold application menu**
reads; the Dock label, though, only the bundle settles for good.

#### The graph files in the Finder

`APlot.app` also tells macOS about the **kind of file** APlot writes: the
`.aplt` extension is given the name `hu.feti.aplot.graph` and APlot as its
owner.  After `--make-app` (run it again if the bundle is older than
this) the Finder therefore

* shows an **icon of its own** for every graph - a sheet of paper with the
  spectrum across it - instead of the blank page with a question mark, and
* **opens a graph in APlot** with a double click, or when the file is
  dropped onto APlot in the Dock.  A graph that is open and edited is not
  replaced without the usual question about saving it.

From a terminal a graph can be opened the same way:

    python3 aplot.py "Zanax dose.aplt"

#### The picture of the graph in the Finder, and the Space bar

Every graph carries a **picture of itself** and a **PDF of all its
diagrams** (see `4. Files`).  To make the Finder show the picture - the
first diagram of the file - as the icon of the file, and show every
diagram, one page each, when the Space bar is pressed, macOS needs two
small **Quick Look extensions**.
They cannot be written in Python: they are in the separate
`APlotQuickLook` folder, in Swift, with a script that builds and installs
them - Xcode (free in the App Store) is all it needs:

    cd APlotQuickLook
    sh build.sh
    sh install.sh

`APlotQuickLook/README.md` explains the rest, including what to do when
macOS does not take the extensions at once.  In the Space bar window the
pages are scrolled through like a PDF (the sidebar button shows them all
small); a graph saved before the PDF came in shows its one picture until
it is saved again.  Extensions built before that version show only the
picture as well: run `sh build.sh` and `sh install.sh` once more.

#### The graph files on a Linux desktop

On Linux one command does it all - nothing is compiled:

    python3 aplot.py --install-desktop

It writes the few small files the freedesktop.org standards ask for, under
`~/.local` for the user who runs it:

| File | What it does |
| --- | --- |
| `share/mime/packages/aplot.xml` | names the kind of file `application/x-aplot` - by the `.aplt` extension, and by the first bytes of the file, so a graph without its extension is known too |
| `share/icons/hicolor/.../application-x-aplot.png` | the icon of the graph files (the sheet with the spectrum), in eight sizes, and APlot's own icon beside it |
| `bin/aplot-thumbnailer` | a tiny program that copies the picture stored in a graph out of it, at the size the file manager asks for |
| `share/thumbnailers/aplot.thumbnailer` | tells the file managers to use it for the graphs |
| `share/applications/aplot.desktop` | APlot in the application menu, and as the program that opens a graph with a double click |
| `bin/aplot-preview` | opens the PDF of every diagram of a graph in the PDF viewer of the desktop |
| `share/applications/aplot-preview.desktop` | puts **Preview all graphs (APlot)** in the `Open With` list of the graphs (it is not in the application menu) |
| `share/kio/servicemenus/aplot-preview.desktop` | the same in the right-click menu of KDE's Dolphin (and under `kservices5/ServiceMenus` for Plasma 5) |
| `share/nautilus/scripts/Preview all graphs (APlot)` | the same under `Scripts` in the right-click menu of GNOME Files (only for one user: GNOME Files has no scripts for every user) |
| `share/sushi/viewers/aplot.js` | the Space bar preview of GNOME Files: every diagram, page by page (always in the home folder of a user, see below) |

The databases of the desktop are brought up to date at once
(`update-mime-database`, `update-desktop-database`, the icon cache), and
APlot is made the program that opens the graphs.  Then restart the file
manager (GNOME Files: `nautilus -q`) and, if it had given up on the graphs
before, remove its list of failures: `rm -rf ~/.cache/thumbnails/fail`.
Graphs saved by an older APlot carry no picture yet: open and save them
once.

The file managers that follow the standard - **GNOME Files** (Nautilus),
**Nemo**, **Caja**, **Thunar** (with its `tumbler` service) and others -
then show the picture of every graph as its icon.  GNOME Files runs a
thumbnailer in a sandbox that cannot look into the home folder, so if the
pictures do not appear there, install it for every user of the computer
instead:

    sudo python3 aplot.py --install-desktop --system

which writes the same files under `/usr/local`.  KDE's Dolphin has a
thumbnail system of its own and may need a plugin of its own.

**Every diagram of a graph.**  The icon is the first diagram of the file.
To see all of them without starting APlot, right-click the graph and
choose **Preview all graphs (APlot)** (in `Open With`, or under `Scripts`
in GNOME Files, or at the top of Dolphin's menu).  It copies the PDF
stored in the graph into a folder of its own and opens it with the PDF
viewer of the desktop (Papers, Evince, Okular...), one diagram a page;
choosing several graphs opens each of them.  A graph saved before the PDF
came in opens its one picture instead, and a plain JSON graph of an older
APlot is refused with a message.

**The Space bar in GNOME Files.**  Pressing the Space bar on a graph in
GNOME Files (the previewer called Sushi) shows every diagram of the graph
as well, one page each, with the page buttons and the `Open With APlot`
button of Sushi; a graph with only a picture shows the picture, and a
plain JSON graph what Sushi shows for any file.  Sushi takes extra viewers
from the home folder of each user only, so `--install-desktop` writes one
there, `~/.local/share/sushi/viewers/aplot.js`; with `sudo ... --system`
it goes into the home of the user who ran `sudo` (anyone else runs
`python3 aplot.py --install-desktop` once as themselves).  Close a Space
bar preview that is still open after the install, so that Sushi starts
again with the new viewer.  It is tried with the Sushi of Ubuntu 20.04
(3.34) and 24.04 (46); the one of 22.04 (41) reads viewers the same way.  The
thumbnailer needs nothing but Python; with Pillow installed it makes the
picture exactly the size asked for, without it the file manager scales the
stored picture itself.

`python3 aplot.py --uninstall-desktop` (with `--system` for the other
kind) takes every one of these files away again.  Run the install again
after moving `aplot.py`, so that the menu entry points at the new place.


## 0. The name

APlot may mean AlphaPlot or AdvancedPlot or AgilePlot or ArticulatePlot
and maybe some other word composition can be looked for.  This software
is an easy to use start (alpha) to create good looking (articulate)
scientific (advanced) plots quickly (agile).


## 1. The spreadsheet window

The main window holds the data table.  The first column is normally the
independent variable (the X axis); every further column is drawn as a
separate curve.  Two cases do without an X column: a **histogram** counts
every column as a sample of raw values, and a sheet whose **first column is
the only filled one** draws that column against the **row numbers**.

The table is not one sheet but as many as are needed: the **tabs** along its
bottom edge each hold a table of their own (section 1.1).

### Toolbar

The toolbar has **two rows**.  The first one carries everything that acts on
the table, the second one the regression and the check button that draws two
sheets together:

| Button | Row | What it does |
| --- | --- | --- |
| Plot (split button) | first | The word `Plot` beside a picture of the style it will draw. Clicking it opens a NEW diagram with that style; clicking the arrow on its right opens the style menu to choose among 9 styles. |
| Update | first | Sends the current data to the diagrams that are already open, keeping every style setting. |
| Open graph (folder icon) | first | Opens a `.aplt` file: the data and every diagram in it.  `Cmd/Ctrl+O`. |
| Import data (arrow icon) | first | Reads a text data file (CSV, TXT, DAT) into the sheet.  `Cmd/Ctrl+I`. |
| Save graph (disc icon) | first | Writes the whole graph - the sheets and the diagrams - into the `.aplt` file.  `Cmd/Ctrl+S`. |
| (the Plot icon) | first | A picture of the style that will be drawn - it changes with the style chosen from the arrow. |
| Add row (icon, split button) | first | Inserts an empty row **around the selected cell** and starts editing it. The arrow chooses the place: above, below, or at the end of the sheet. |
| Delete row (icon) | first | Deletes every row the highlighted block touches. |
| Add column (icon, split button) | first | Asks for a name and inserts an empty column **around the selected cell**. The arrow chooses: before, after, or at the right end of the sheet. |
| Delete column (icon) | first | Deletes the column of the selected cell (after a confirmation). |
| Settings... | first | Opens the settings editor (see section 5). |
| **Regression** | second | Fits a curve to the columns of this sheet - see section 1.2.  `Ctrl/Cmd+R`, or `Plot > Regression...`. |
| **Plot with previous tab** | second | Glues this sheet to the one before it, so that they are drawn in the same diagram (see `Sheets that are drawn together`).  Ticking it redraws nothing by itself: the next `Update` or `Plot` uses it.  It stands beside `Regression` on every sheet; on the first one there is nothing before it, so it cannot be ticked. |

Clearing, copying and pasting cells are done with the keys (`Delete`,
`Ctrl/Cmd+C`, `Ctrl/Cmd+V`, `Ctrl/Cmd+X`) or with the `Edit` menu, which
also takes a change back (`Ctrl/Cmd+Z`, see section 3); `Random data` is in
the `File` menu.

### 1.1 Sheets (tabs)

Along the bottom of the table there is a **tab for every sheet** and a `+`
that makes a new one.  The tabs wear the dark grey of the toolbar buttons
with their names written in a light colour; the sheet in front has the
lighter tab and a bold name.  Each sheet is a full table of its own: its own
columns, its own values, its own formulas and its own check buttons.  The
sheet in front is the one every command of the toolbar and of the menus
works on.

* **A new sheet**: click `+`.  It opens empty and is called `Data 2`,
  `Data 3`, and so on.
* **Renaming**: click the tab of the sheet that is **already in front** a
  second time - exactly as a title or an axis label of a diagram is renamed
  - and the name can be written **on the tab itself**; `Enter` keeps it,
  `Esc` leaves it as it was.  A double click does the same, and
  `Rename tab` in the right click menu asks for the name in a little
  window.  The name of a sheet matters: it is what a curve of that sheet is
  called in a diagram that draws several sheets at once, and the diagrams
  follow the new name at once.
* **Colouring, duplicating and deleting**: right click (or Ctrl-click) a
  tab.  `Tab colour` paints a small square on it, which is useful for
  telling a fit, a measurement and a calculation apart at a glance.
  **`Duplicate tab`** puts a second sheet with the same contents after
  it - after the sheets glued to it with `Plot with previous tab` (its
  fits), never between them - and brings it to the front: the numbers, the formulas (random
  ones draw the very same numbers), the column names, which columns are
  plotted against which axis and the colour of the tab.  It is called
  after the original - `Signals copy`, `Signals copy 2` - and it is a
  sheet of its own from then on; its `Plot with previous tab` is left off.
  The last sheet is never deleted.  When a sheet with glued sheets after
  it is deleted, those stay together as a group of their own instead of
  being glued to the sheet before it.
* **Moving a sheet**: press on its tab and **drag it sideways**.  A blue
  line shows the gap it will land in, and it goes there when the button is
  let go; near either end of a long row the row scrolls along, so a far
  place can be reached as well.  The moved sheet stays in front, every
  diagram keeps drawing its own sheet, and `Undo` puts the tab back.  The
  sheets glued to it by `Plot with previous tab` - a `Fit` sheet, say -
  **move with it**, as one block, so its diagram keeps its fitted curves;
  and a sheet dropped between another one and its glued sheets goes after
  that whole group instead, so it cannot take them over.  A glued sheet
  dragged by its own tab moves alone and joins the sheet it is dropped
  after - that is how a fit is given to another sheet on purpose.  As
  always, the diagrams follow at the next `Update`.  A short movement is
  still just a click.
* **Many sheets, long names**: when the tabs no longer fit into the width
  of the window the row **scrolls**.  Two small arrows appear at its right
  end, with the `+` beside them, so the `+` never slides out of the
  window; the arrows scroll the row (hold one down to keep going), and so
  do the wheel of the mouse or a sideways swipe on a trackpad over the
  row.  The tab that comes to the front is always brought into view.  While
  everything fits the arrows are not there and the `+` stands right after
  the last tab.
* **Every sheet is written into the `.aplt` file** with its name, **its
  colour**, its data, its formulas, which of its columns are ticked, and
  whether it is drawn with the one before it.  A file written by an older
  version - one single table - opens as a single sheet.

**Sheets that are drawn together.**  Two data files loaded into two sheets
are often two measurements of the same thing.  Ticking **`Plot with
previous tab`** on the second sheet glues it to the first one, and the run
of sheets that are stuck together is a **group**: the X columns are matched
up and every curve of the group stands in the same diagram.

The X columns do not have to agree.  Whole numbers in one sheet and
fractions in the other are compared as fractions, X values that are words
are compared as words, and an X value that only one of the sheets has
simply carries **no point** for the other one - its curve is not broken
there.  An **empty cell inside** a sheet is a different matter: it stays a
real hole in that curve, exactly as it would be if the sheet were drawn on
its own.

The glue holds **in both directions**.  A diagram opened from **any** sheet
of a group draws the **whole** group, so it makes no difference whether the
box was ticked before or after the diagram was opened, or which sheet of
the group was in front at the time.

A sheet whose box is **not** ticked **begins a new group**.  With five
sheets and the box ticked on the second and on the fifth, the groups are
`1+2`, `3` alone and `4+5`: the fifth is drawn with the fourth, and not
with the first three.

Every curve keeps **its own column name**.  Only a name that is already
taken by an earlier sheet of the group gets the name of its own sheet after
it - `Signal` and `Signal (Tuesday)` - so that two curves never share one
name, and ticking the box does not rename (and so does not restyle) a
single curve that was already drawn.

**Ticking the box changes nothing on the screen.**  It says what the next
drawing will contain, and the diagrams that are open stay exactly as they
are until:

* **`Update`** brings every open diagram up to date - each of them from its
  own group; or
* **`Plot`** opens a **new** diagram of the group the sheet in front
  belongs to, as the boxes stand at that moment.

The one exception is a **regression**: the sheet it writes arrives with the
box already ticked, and the diagram of the measurements is refreshed at
once, so the fitted curve appears over the points without asking.

Every diagram remembers **which sheet it was opened from**, so `Update`
brings each of them up to date from its own group and one group never
overwrites the diagram of another.

### 1.2 Regression: fitting a curve to the data

The `Regression` button of the second toolbar row opens a window that fits a
curve to the columns of the sheet in front.  The **methods stand on the
left**; choosing one shows on the right exactly what it needs.

Eight methods are offered, and every one of them works out its own starting
values, so all of them fit **out of the box** - there is nothing to set up
before pressing `Fit`:

| Method | The curve | Its parameters |
| --- | --- | --- |
| Straight line | `y = a*x + b` | slope, intercept |
| Polynomial | `y = c0 + c1*x + c2*x^2 + ...` | the coefficients (the **order** is a setting) |
| Exponential growth | `y = Y0 * exp(k*x)` | Y0, rate (and the doubling time) |
| One phase decay | `y = (Y0 - Plateau)*exp(-K*x) + Plateau` | Y0, plateau, rate (and the half life) |
| Two phase decay | `y = Plateau + Fast*exp(-Kf*x) + Slow*exp(-Ks*x)` | plateau, two spans, two rates (and both half lives) |
| Logistic curve | `y = Bottom + (Top-Bottom)/(1 + exp(-k*(x-x50)))` | bottom, top, midpoint, steepness |
| Gaussian distribution | `y = Base + A*exp(-(x-Mean)^2/(2*SD^2))` | baseline, amplitude, mean, width (and the FWHM and the area) |
| Moving average | the running mean of n points | the window (a setting, not a fitted number) |

Everything but the moving average is fitted by **least squares**: the sum of
the squared distances between the data and the curve is made as small as it
goes.  The straight line and the polynomial are solved exactly; the four
curved ones are fitted with the **Levenberg-Marquardt** method, written into
the program itself, so nothing beyond numpy is needed.

**What the right hand side offers**

* **Settings** of the method that has them: the `Order` of a polynomial
  (1 to 10), the `Window` of a moving average.
* **Columns to fit**: every column after the first one.  The ones that are
  ticked for plotting are chosen to begin with; click, `Shift`-click or
  `Ctrl/Cmd`-click to choose others.  The **first column holds the X
  values** (a first column of names counts the rows instead).
  **A column that holds error bars is not chosen**, and neither is an
  **empty** one.  The scatter of a measurement is not a measurement of its
  own, so a curve fitted to it would be a curve fitted to the noise:
  whichever column a drawn curve reads its bars from (the one after it, or
  the one named in `Curve properties > Source`) is left unticked, and only
  the means are fitted and drawn.  Both are still in the list, so either
  can be ticked by hand.
* **Parameters**: one line for every parameter of the method.  Leaving the
  `Start value` empty lets the program work it out from the data, which is
  what usually happens.  Typing one in says where the fit should set out
  from - useful when a difficult fit runs away - and ticking `Hold` beside
  it **keeps that parameter fixed** at the value typed in while the others
  are fitted (a plateau that is known, a baseline that is zero).
* **The curve that is written**: how many `Points` it is drawn with (100)
  and how far `Past the data` it reaches (5 per cent of the range at both
  ends).  A moving average says nothing outside the measurements, so it is
  never drawn past them.

**What `Fit` does**

1. Every chosen column is fitted, and a **new sheet** appears right after
   the sheet that was fitted, called `Fit` (`Fit 2`, `Fit 3`, ...).
2. That sheet holds the **X values** of the curve in its first column and
   the fitted curve of every column beside it (`A fit`, `B fit`, ...) - 100
   points over the range of the data, widened by 5 per cent.
3. Then **one column is left empty**, and after it come the **parameters**:
   a column of names (`Parameter`) and one column of values for every curve
   that was fitted.  Under the parameters stand what follows from them (a
   half life, the FWHM...), then `R squared`, `RMSE`, the number of points
   fitted and the name of the method.
4. The parameter columns are **not data to draw**: their `y_L` / `y_R` check
   buttons are switched off, so they never become curves.
5. The new sheet has **`Plot with previous tab` ticked**, and the diagram is
   refreshed at once - the one place where a drawing is brought up to date
   without the `Update` button: the measurements keep their markers and the
   fitted curve is drawn over them as a **smooth line**.

Everything in the new sheet is an ordinary sheet: the numbers can be edited,
copied, saved with the graph and plotted in any style.

### The toolbar icons

Every icon of the toolbar is **drawn by the program itself** - there are no
picture files to carry around.  Each one is painted four times as large as
it is shown and then shrunk, which is what gives it smooth edges.  They
are drawn in **clear flat colours** - soft but saturated fills, each with a
darker edge of its own colour, on white paper - so they are easy to see on
a light toolbar and still stay quiet beside the table.

The icons are **24 pixels** large, and every outline is drawn a good pixel
wide, so that none of them fades away when it is shrunk.  The buttons of
the main toolbar fit tightly around them, with no wide empty rim, and all
of them are **equally tall**: a button with words only (`Update`,
`Settings...`, `Regression`) carries an invisible picture as tall as an
icon, so it stands exactly as high as the ones with icons.  A few constants at the top of
`aplot.py` set the look:

| Constant | What it sets |
| --- | --- |
| `ICON_SIZE` (24) | how large the icons are, in pixels - the buttons grow with them |
| `ICON_LINE_WEIGHT` (1.6) | how much stronger the thin outlines are drawn |
| `ICON_STROKE_WEIGHT` (1.07) | ... and the strokes of the little curves |
| `TOOLBUTTON_PADDING` (1, 0) | the free room around a picture on its button of the main toolbar |
| `ICON_BLUE`, `ICON_SAGE`, `ICON_SAND`, `ICON_ROSE`, `ICON_LILAC`, `ICON_EDGE`, ... | the colours themselves |

The **Plot** button carries a little picture of the style it will draw, and
that picture **follows the style**: a line, a line with markers, scattered
points, bars, error bars, a histogram, a staircase, a grid of counts or a
pie.  Choosing another style from its arrow menu changes the icon at once,
so the button always shows what clicking it will open.

The four row and column tools are a tiny picture of a **sheet of three
bands** - lying down for the rows, standing up for the columns - with a
small badge in the corner:

* **Blue and a `+` add.**  The blue band is the new row or column,
  and it is drawn **where it will appear**: at the near end for
  *above* / *before*, at the far end for *below* / *after*, and standing
  **apart** from the other two for *at the end of the sheet*.
* **Red and a `-` delete.**  The red band in the middle is the row
  or column that goes away.

The three file tools beside them - an open folder, an arrow running into a
sheet and a disk - are drawn in the same shades.

**The diagram window uses the very same set.**  The buttons matplotlib
brings with it - `Home`, `Back`, `Forward`, `Pan`, `Zoom`, `Subplots` and
`Save` - carried small black pictures of their own; they are replaced, one
for one, with drawn ones in the same colours: a little house, two arrows, the four-way
arrow, a magnifier, the plot area with its two handles, and the same disk
as on the spreadsheet.  `Pan` and `Zoom` stay pressed while they are in
use, and then show their icon on a **light blue plate**, so it is plain
which of them is waiting for a click in the diagram.  The `T` of the text
tool, the drawing tool, the arrow tool and the picture button are painted
in the same shades, and the two split buttons stand on the toolbar itself
instead of on a grey block.

Resting the pointer on any of them brings a **popup text** that spells the
operation out in words - *"Insert row below (click arrow for options)"*,
*"Delete column"*, and so on.  The text follows the place that is chosen, so
the button always says what it is about to do.

The icons are painted with **Pillow** (one of the optional packages, see
`What it needs`).  Without it every button simply carries its name in words
and everything else works exactly the same.

**Adding around the selected cell.**  The two adding icons are **split
buttons**, like `Plot`:

* **Clicking the icon** inserts the row or column at the place the icon
  shows, measured from the **selected cell** (or from the highlighted
  block).  A new row pushes the rows below it down, a new column pushes
  the columns on its right to the right, and the formulas of those cells
  move with them - **references and all**, see below.
* **Clicking the arrow** opens the three places.  Choosing one does it
  right away **and** becomes the new default of the icon, so the next
  click repeats it.

| Place | Where the new row / column goes |
| --- | --- |
| Above / Before | Directly above the selected row, or directly to the left of the selected column. |
| Below / After | Directly below the selected row, or directly to the right of the selected column (the default). |
| At the end | The bottom of the sheet, or its right hand end - the old behaviour. |

A column inserted **before the first one** becomes the new X column: the
`x_B` / `x_T` check buttons move to it and the old first column becomes a
curve.  The same tools sit in the right click menus as well: `Insert Row
Above` / `Insert Row Below` on a cell, and `Insert Column Before...` /
`Insert Column After...` on a column heading.

### Plotting styles (Plot Split Button)

The **Plot** button in the main window toolbar is a split button that combines
an immediate action with a style menu:

* **Clicking the main button** opens a new diagram drawn with whichever style is
  currently active (indicated by its vector icon on the button face).
* **Clicking the dropdown arrow** opens the menu of all the plotting styles,
  each line with the little picture of its diagram - the same picture the
  button shows once that style is chosen:
  * **Line + Symbol**: A smooth or solid line connecting data points, with
    distinct marker symbols (circles, squares, diamonds, etc.).
  * **Line**: Clean continuous lines without markers, ideal for dense time
    series, spectra, and continuous functions.
  * **Scatter**: Discrete data markers without connecting lines (crosses `x`,
    plus signs `+`, circles, squares, etc.), ideal for point clouds and
    uncorrelated samples.
  * **Bar Chart**: Vertical rectangular bars for categorical, discrete, or
    binned data. Bar width, fill opacity (alpha), edge line width, and colors
    can be customized in Curve Properties.
  * **Error Bar (Median, SD)**: Data points with vertical error bars and
    horizontal end caps, the **same length up and down**.  The columns are
    read **in pairs** - `x`, median, SD, median, SD, ... - so two Y columns
    make one curve.  The length can also be worked out by the program (a
    percentage, a fixed value, the standard deviation of the column) or
    taken from any other column; see `Error Bar properties`.
  * **Error Bar (Median, +error, -error)**: the same points with a bar that
    may be **longer one way than the other**.  Its columns are read **in
    threes** - `x`, median, error upwards, error downwards, median, ... -
    so three Y columns make one curve and the next three the one after it.
    Everything else (the marker, the caps, the colours) works exactly as in
    the other error bar style.
  * **Histogram**: The distribution of a column of raw values, counted by
    the diagram itself into a given number of bins (20 by default, set per
    curve in `Curve properties`). Every column is a sample of its own, and
    one single column is enough.
  * **Stairs**: A stepped outline of the values (`ax.stairs`) - one flat
    tread per point instead of a straight line between two of them. The
    step may stand midway between two X values, at the X value itself or
    just before it, and the staircase can be left open or filled with a
    colour and a pattern.
  * **2D Histogram**: The X/Y **pairs** counted in a grid of cells
    (`ax.hist2d`): where the points crowd together the cell is brighter.
    The number of bins across X and up Y, the colour scale, the opacity and
    an optional colour bar are all settings of the curve.
  * **Pie Chart**: The values of **one** column as slices of a circle
    (`ax.pie`). The first column of the table names the slices, the
    percentages can be written on them, and the pie may be turned, pulled
    apart or opened into a doughnut.  The names and the percentages can be
    switched off, moved in or out, laid along their own slice and given
    their own font size and colour, and every name can be changed on its
    own.

Selecting a style updates the button icon and immediately opens a diagram
rendered in that style. Any curve's style can also be switched individually at
any time from the **Curve properties** dialog.

### The formula bar and Excel-like operations

Directly above the table sits the **Formula Bar**, giving APlot full spreadsheet
capabilities similar to Excel:

* **Cell Address Box** (left): Displays the coordinate of the currently focused
  cell (e.g., `A1`, `B3`). You can type any valid cell reference here and press
  `Enter` to jump straight to that cell.
* **fx Symbol**: Indicates formula entry mode.
* **Formula / Value Entry**: Displays and edits either the raw formula (starting
  with `=`) or the plain text value of the active cell.
* **Commit (`✓`) button**: Confirms and saves the formula or value (`Enter`).
* **Cancel (`✕`) button**: Discards edits and restores previous content (`Esc`).

The bar carries nothing else: **filling down** and the **column operations**
live where they are needed and do not take room above the sheet.

* **Fill down**: the black fill handle of the selection, or `Fill Down` in
  the right click menu of a cell or a heading (`Ctrl/Cmd+D` now belongs to
  `Edit > Duplicate`, see section 3).  It copies the
  top cell's formula or value down across the selected block of rows,
  automatically adjusting relative row references (e.g. `=A1+B1` becomes
  `=A2+B2`, `=A3+B3`) while preserving absolute references (e.g. `$A$1`).
  Pulled with the **black square**, two selected numbers make a series
  instead of a copy - see `Pulling a series out of two numbers` below.
* **Column Math**: `Column Math...` in the right click menu of a cell, or
  `Calculate Column '<name>'...` in the right click menu of a heading.  It
  calculates entire columns at once using presets or mathematical formulas.

### Excel-style cell fill handle and row/column numbering

* **Interactive Fill Handle (black square)**:
  * When any cell or block of cells is selected, a solid black square handle appears at the bottom-right corner of the selection outline.
  * **Click and Drag Down**: Pulling the black square down carries the
    selection on across the rows below, with a real-time feedback outline,
    and computes the results at once.  What is written depends on what was
    selected - a **series**, a **formula** or a **copy**; see the next
    section.
  * **Option+Double-Click / Double-Click**: Double-clicking the fill handle (or pressing `Option`/`Alt` while double-clicking) automatically fills down all rows until the adjacent left or right column has empty cells, exactly like Microsoft Excel - and if there is no neighbouring column with data, down to the last row of the sheet.  Only the **columns of the selection** are filled: the handle of a single cell fills that one column, and a formula in the cell beside it is left as it is.
  * The handle has to be **pulled** by a few pixels before it fills
    anything, so a click on it - or the first click of a double click,
    with the little twitch of the hand that goes with it - never fills
    the neighbouring cell by accident (half of the square lies over the
    next column).
  * The handle is always **on top of the cell editor**, so it can be grabbed
    at once - also right after walking to the cell with the arrow keys,
    while the cell is still open for typing.

#### Pulling a series out of two numbers

Selecting **two or more cells** of a column before pulling the black square
turns the fill handle into a **series generator**: the step is worked out
from the numbers themselves and the series is continued for as many rows as
the handle is pulled over.

| Selected | Pulled down |
| --- | --- |
| `1` | `1, 1, 1, 1, ...` - one cell alone is copied, as before |
| `1`, `3` | `5, 7, 9, 11, ...` - the difference is the step |
| `10`, `8` | `6, 4, 2, 0, -2, ...` - a falling series counts down |
| `0.5`, `0.75` | `1.0, 1.25, 1.5, ...` - fractions are exact |
| `2`, `4`, `6` | `8, 10, 12, ...` - three or more cells work as well |

* The step of **two** cells is simply their difference.  With **more** than
  two it is their **average** difference, so an evenly spaced selection is
  continued exactly and an uneven one carries on from the last value with
  the average step.
* **`Option`/`Alt`+double click** (or a plain double click) on the black
  square writes the series all the way down: to the end of the data in the
  neighbouring column, or to the last row of the sheet if there is none.
* Every **column** of the selection decides for itself, so a block of two
  rows and three columns pulled down gives three series with three
  different steps.
* Whole numbers stay whole (`1, 3, 5`, never `1.0, 3.0, 5.0`).
* Anything that is **not a plain number** - a text, an empty cell - is
  copied, exactly as it was before, and a **formula** is still replicated
  with its row references moved along (`=A1*10` becomes `=A2*10`,
  `=A3*10`, ...).
* While the handle is being pulled, the **status bar** at the bottom says
  what will be written: *"Series, step 2:  5, 7, 9, ...   (7 rows)"* or
  *"Fill down: the value is copied into 3 more rows"*.
* **Held against the bottom edge of the sheet, the table scrolls on by
  itself**, one row at a time, and the fill follows it down - so a series
  can be pulled far past the rows that happen to be on the screen without
  letting go of the button.  The top edge does the same upwards.  Bringing
  the pointer back inside the table stops it at once, and the scrolling
  ends at the last (or the first) row of the sheet.
* **Column Letters (A, B, C, ..., AA, AB, ...)**:
  * Displayed directly below the axis selection checkboxes in the axis check bar.
  * Also displayed in the column table headers (e.g. `A  (Time)`, `B  (Voltage)`).
  * **Clicking a letter selects that whole column**, exactly the way clicking
    a row number selects the whole row - see below.
* **Row Line Numbers (1, 2, 3, ...)**:
  * Displayed in a fixed left-side header column, painted with the very
    background of the table itself, so the strip of numbers never stands
    out against the cells (the themes of the systems differ - the one of
    macOS is a dark grey).
  * Stays pinned on the left when scrolling horizontally, while scrolling vertically in lockstep with the spreadsheet table data.
  * Clicking or dragging along row numbers selects full rows.
  * Clicking the top-left corner indicator (`◢`) selects all cells in the spreadsheet.

#### Selecting a whole column or a whole row from its heading

The letters above the columns and the numbers beside the rows work the same
way, so a whole line of the table is always one click away:

| Click | What is selected |
| --- | --- |
| a column letter (`A`, `B`, `C`, ...) | that **whole column**, from the first row to the last |
| a row number (`1`, `2`, `3`, ...) | that **whole row**, from the first column to the last |
| the corner (`◢`) | the **whole table** |

* **Dragging** along the letters (or along the numbers) takes a **range** of
  columns (or rows), and it may be dragged in either direction.
* **Held against an edge of the sheet, the table scrolls on by itself** -
  downwards and upwards along the numbers, sideways along the letters -
  and the block grows with it, so a range can reach far past the rows and
  the columns that happen to be on the screen without letting go of the
  button.  Bringing the pointer back inside stops it at once, and the
  scrolling ends at the last (or the first) row or column of the sheet.
  The black fill handle behaves the same way, in both directions.
* **`Shift`+clicking** another letter stretches the block from the one that
  was clicked first to that one.
* The letter of every column the block touches is **tinted**, just as the
  numbers of the rows it touches are - so it is always visible what the
  block covers, even where it has scrolled out of sight.
* What is selected is an ordinary block, so everything works on it:
  `Ctrl/Cmd+C` copies the column, `Delete` empties it, `Ctrl/Cmd+D`
  duplicates it under itself, and the arrow keys walk on from the cell the
  click left the cursor in.  `Ctrl/Cmd+Space` does the same thing from the keyboard.
* **`Shift`+an arrow key** stretches the block one cell at a time, and the
  sheet **follows the end of it in both directions**: down into the rows
  and sideways into the columns that were not on the screen, and back
  again.  A plain arrow key does the same for the cell the cursor moves
  to.
* **Right clicking** a letter opens the menu of that column -
  `Calculate Column...`, `Sort`, `Insert Column Before / After...`,
  `Rename...`, `Delete Column` - the same menu as a right click on the
  column heading itself.

#### Formula syntax and functions

Formulas begin with an equals sign (`=`). Standard Excel cell coordinates (e.g.
`A1`, `B2`), absolute coordinates (`$A$1`, `A$1`, `$A1`), and ranges (`A1:A10`,
`B2:D10`) are fully supported:

* **Arithmetic**: `+`, `-`, `*`, `/`, `^` (exponentiation), `%`.
* **Comparisons**: `=`, `<>`, `<`, `<=`, `>`, `>=`.
* **Math & Statistics**: `SUM(range)`, `AVERAGE(range)` / `AVG(range)`,
  `COUNT(range)`, `MIN(...)`, `MAX(...)`, `ABS(x)`, `ROUND(x, decimals)`,
  `INT(x)`, `SQRT(x)`, `POWER(base, exp)`, `EXP(x)`, `LN(x)` / `LOG(x)`,
  `LOG10(x)`, `LOG2(x)`, `MOD(n, d)`.  A function whose name ends in digits
  is read as a function, never as a cell (`LOG10(A1)` is the base-10
  logarithm of `A1`, not the cell `LOG10`).
* **Trigonometry**: `SIN(x)`, `COS(x)`, `TAN(x)`, `ASIN(x)`, `ACOS(x)`,
  `ATAN(x)`, `DEGREES(rad)`, `RADIANS(deg)`, `PI()`.
* **Constants**: `pi`, `e` and `tau` are numbers on their own, so they can be
  written straight into an expression - `=sin((B1+C1)+pi/6)`, `=2*pi*A1`,
  `=B1/e`. `PI()` and `E()` still work as functions as well. A column that
  really carries one of these names (or, for `e`, a sheet wide enough for a
  column `E`) keeps its own meaning: the column always wins over the constant.
* **Logic**: `IF(condition, value_if_true, value_if_false)`, `AND(c1, c2)`,
  `OR(c1, c2)`, `NOT(c)`.
* **Random numbers**: `RAND()` draws a number with a **uniform**
  distribution between 0 and 1, `RAND(low, high)` one between `low` and
  `high`.  `RANDN()` draws one with a **normal** (Gaussian) distribution of
  mean 0 and standard deviation 1, `RANDN(mean, sd)` one of the mean and
  standard deviation given.  Filled down a column (the fill handle, or
  `Fill Down`), every row gets a number of its own, and they can be part
  of a larger formula: `=A1 + RANDN(0, 0.05)` adds noise to a column.

  Unlike Excel, the numbers **stay what they are** while the sheet is
  worked on - an edit elsewhere, Undo, saving and opening the file do not
  change them, so a diagram of them does not change under the user's
  hands either.  **`Edit > New random numbers`** (`F9`, as in Excel) draws
  all of them anew for the sheet in front; it is one step that `Undo`
  takes back.  Column Math knows `rand()`, `rand(low, high)`, `randn()`
  and `randn(mean, sd)` as well, with one number for every row.

#### Error reporting and safety

Formulas are evaluated using an AST-based calculation engine with cycle
detection. When an invalid expression or calculation issue occurs, Excel-style
error codes are displayed:

* `#DIV/0!`: Division by zero.
* `#NAME?`: Unrecognized function or variable name.
* `#CYCLE!`: Circular dependency detected between cells (e.g., `A1` depends on
  `B1` which depends back on `A1`).
* `#REF!`: A cell reference outside the table - or one whose row or column
  has been deleted.
* `#VALUE!`: Incompatible operand types.

#### The formulas follow the rows and columns that move

A formula does not only live in a cell, it also **points** at cells, and
inserting or deleting rows and columns moves both.  Every stored formula of
the sheet is rewritten so that it goes on saying what it said before:

* **Inserting a row** above row 14 turns `=log(A14)/log(10)` into
  `=log(A15)/log(10)` - in the formula that moved down with that row and in
  every other formula that referred to it.  A reference to a row **above**
  the new one is left alone.
* **Deleting rows** moves the references of the rows below them **up** by as
  many rows as were removed; a reference to a row that is **gone** becomes
  `#REF!`, so a broken calculation says so instead of quietly reading the
  wrong cell.
* **Inserting a column** in front of another shifts the letters: `=A1*100`
  becomes `=B1*100`.  **Deleting** one shifts them back, and a reference to
  the deleted column becomes `#REF!` as well.
* Ranges move with everything else, so a new row inside `=SUM(A1:A5)` makes
  it `=SUM(A1:A6)`.
* This is what a spreadsheet does, and unlike **pulling a formula down**
  (where `$A$1` stays put on purpose), a **fixed** reference moves here too:
  `$A$14` becomes `$A$15`, because it is the values themselves that moved.
* Whole columns of calculated cells therefore survive editing: pull
  `=log(A1)/log(10)` down over a thousand rows, insert or delete rows
  anywhere, and every cell still reads the value beside it.

#### Status bar summary

Whenever a block of cells is selected in the table, the status bar at the bottom
of the window immediately shows a live statistical summary of the numeric
cells.  The strip keeps the plain background of the window and writes in
the **blue of the row numbers and the column letters**, so the numbers at
the foot of the sheet plainly belong with the heads of the block they are
about:

> `Average: 24.50   Count: 12   Sum: 294.00   Min: 10.00   Max: 45.00`

#### Right-click context menus

Right-clicking inside the table opens a context menu:
* On any **cell**: `Cut`, `Copy`, `Paste`, `Fill Down`, `Duplicate`,
  `Column Math...`, `Clear Cells`, `Insert Row Above`, `Insert Row Below`,
  `Delete Row(s)`.
* On any **column header**: `Calculate Column '<name>'...`, `Sort Ascending`,
  `Sort Descending`, `Fill Down`, `Insert Column Before...`,
  `Insert Column After...`, `Rename '<name>'...`, `Delete Column '<name>'`.

### Column Math dialog

The **Column Math** dialog (`Column Math...` in the right click menu of a
cell, or `Calculate Column '<name>'...` on a column heading) lets you
compute entire columns quickly without
having to drag formulas across every row:

* **Target column**: Choose an existing column to overwrite, or select `[New Column]`
  to create a new one automatically.
* **Presets**:
  * **Scale and Offset**: `a * x + b` (e.g., multiply by a gain factor and add a bias).
  * **Normalize**: Rescales values linearly into the range `[0, 1]`.
  * **Standardize (z-score)**: Subtracts the mean and divides by standard deviation:
    `(x - mean) / std`.
  * **Subtract Mean**: Centers the column around zero: `x - mean(x)`.
  * **Cumulative Sum**: Running sum down the column: `cumsum(x)`.
  * **Difference / Gradient**: Numerical derivative: `diff(x)`.
  * **Moving Average / Smooth**: Rolling window mean: `smooth(x, window=5)`.
  * **Linspace / Index**: Evenly spaced numbers or row index sequence:
    `linspace(0, 100)`.
* **Custom Expressions**: Write any algebraic expression referencing column
  names or letters directly (e.g., `A * 2 + B` or `col('Y1') / 1000`).

### What the columns mean

**Every** diagram reads the table the same way: the **first column is the X
axis** and the **second one is the value** of the first curve.  What follows
depends on the kind of diagram:

| Diagram | The columns |
| --- | --- |
| Line + Symbol, Line, Scatter, Bar Chart | `x`, `y1`, `y2`, `y3`, ... - one curve per column |
| Error Bar (Median, SD) | `x`, `mean1`, `std1`, `mean2`, `std2`, ... - **in pairs** |
| Error Bar (Median, +error, -error) | `x`, `mean1`, `up1`, `down1`, `mean2`, ... - **in threes** |
| Histogram | **every** column on its own: a sample of raw values that the diagram counts itself |
| Only the first column filled | that column is the **curve** and the X axis is the **row number** |
| The first column holds **names** (no numbers at all) | every other column is a curve and the X axis is the **row number** |

An **error bar** diagram therefore reads the columns two by two: the third
column is the length of the error bar of the second one, the fifth belongs
to the fourth, and so on.  Five columns give **two** curves with their own
error bars, seven columns give three, and so on.  The **(Median, +error,
-error)** style reads them three by three instead: the third column is how
far the bar reaches **up** from the second one and the fourth how far it
reaches **down**, then the fifth column is the next curve.  Seven columns
give **two** curves there.  Both lengths are taken as lengths, so a minus
sign in front of the downward error changes nothing.

**An empty column never begins a pair (or a group of three).**  A sheet
nearly always carries a few blank columns at its end, and once a fitted
curve has been glued to that sheet they stand between the measurements and
the fit; counting them as curves would shift every group from there on and
swallow the fitted column as somebody's error bars.  So a group starts at
the first column that really holds numbers, and the one (or two) columns
after it are its errors, full or empty.  Type a value into a blank column
and it becomes a curve at the next `Update`, exactly as in every other
kind of diagram.  The `std` columns are used
up as the errors and are not drawn as curves of their own, so every one of
them has to stay ticked in the strip above the table.  A last `mean` column
with no `std` beside it still gets a curve (with a 5 % error, which can be
changed in `Curve properties`).

A **histogram** is the one diagram that does not read the first column as an
X axis, because it does not need one.  Each column is a **sample of raw
measurements** and the diagram makes the statistics itself, exactly as
`ax.hist` does: the range the values of that column cover is cut into
**bins** of equal width and the values are counted.  The X axis is then the
value of the measurement and the Y axis is how many of them fell into each
bin.

* **One column is enough.**  A thousand numbers in the first column alone
  give a histogram straight away - no second column, no counting by hand.
* **Every filled column gets its own histogram**, the first one included,
  and each of them is counted separately over its own range.  A column that
  is empty (or ticked off in the strip above the table) is simply left out.
* **The number of bins is 20 by default** and belongs to the curve: open
  `Curve properties` (double click the bars) and set `Bins` in the
  **Histogram properties** section.  The sample is counted again at once and
  the range follows.  Every histogram can have a different number of bins.
* Empty cells and text are not measurements, so they are left out of the
  counting: only the numbers are counted.
* The bars are exactly as wide as a bin, so they stand side by side with no
  gap, and the counts start at zero.

Bins that are already counted in the table (one row per bar, `x` = the
position of the bar and `y` = its height) are a **bar chart**, not a
histogram - that is what the `Bar Chart` style is for.

### One single column: the row number is the X axis

A column of numbers on its own is a **series of measurements**, not an X
axis, so it does not need a second column to be plotted:

* Type (or load) values into the **first column only** and press `Plot`:
  that column becomes the curve and the X axis becomes the **row number of
  the table** - `1` for the first row, `2` for the second, exactly the
  numbers standing beside the cells.  The X axis is called `Row`.
* It works for **every style**: line, line with symbols, scatter, bar chart
  and error bar all draw the values against the row numbers.  (A histogram
  needs no X axis at all: it counts that column, see above.)
* The other columns of the sheet may be there as long as they are **empty** -
  the blank columns a fresh sheet fills the window with change nothing.
* As soon as a **second column is filled**, the first one goes back to being
  the X axis and the diagram is drawn against it - and the label of the X
  axis follows, unless a text was written into it by hand.
* Empty cells stay **gaps**: the row numbering keeps counting, and the curve
  is simply broken at the missing point.
* This is a fallback for a sheet that has nothing else, not a way around the
  check buttons: if a filled column was **switched off** on purpose, the
  program asks for a tick instead of quietly drawing the first column alone.

**A first column of names counts the rows too.**  A table like
`Solar, Wind, Hydro | 24, 19, 15` is the natural shape of a pie or a bar
chart, but its first column holds not a single number, so it is no X axis
either.  Every column after it then becomes a curve drawn against the **row
number**, and the X axis is again called `Row`.  That is what makes a pie of
such a table switchable to a line or a bar chart and back without an empty
frame in between.  A number typed into the first column makes it the X axis
again at once.

### Which columns are plotted, and against which axis

Above the column headings there is a strip with **two check buttons for
every column**, side by side:

| Above | The two boxes | What they mean |
| --- | --- | --- |
| the first column | `x_B` and `x_T` | the **bottom** and the **top** X axis |
| every other column | `y_L` and `y_R` | the **left** and the **right** Y axis |

Resting the pointer on any of them pops up its full name - `Bottom x-axis`,
`Top x-axis`, `Left y-axis`, `Right y-axis` - so the short labels never have
to be guessed.  A column is never made **narrower than its two check
buttons**: pulling the window in stops there and the horizontal scroll bar
takes over, so neither the switches nor the numbers under them can be
squeezed out of sight.  `Settings > Spreadsheet > Column width` sets the
starting width; anything smaller than that minimum is raised to it.

**A column is made wider or narrower** by dragging the right edge of its
heading, and it **keeps that width**: it no longer stretches with the
window, so neither a redrawing of the sheet nor a resized window pulls the
edge back.  The other columns still share out the rest of the window, and
when the columns are wider than the window, the table scrolls sideways.
The width follows the column when it is renamed, is copied with
`Duplicate tab` and is written into the `.aplt` file.

The rules are simple:

* **one axis per column.**  Ticking one of the two boxes clears the other
  one, so a column is never drawn against both axes at once.
* the **first column** always feeds one of the two X axes: `x_B` is ticked
  when the data arrives, and clicking `x_T` moves the whole X scale - its
  numbers and its label - **above** the plot area.  Clicking the ticked box
  does not switch it off; the data has to have an X axis.  In a
  **histogram** that column is a sample like any other and is counted as
  well, while its `x_B` / `x_T` tick still decides whether the value scale
  is drawn below or above the bars.
* every **other column** may have **both boxes empty**: then that column is
  simply not plotted.  The data stays in the table, it is only left out of
  the diagram.
* ticking `y_R` gives that curve **its own scale on the right**, with its
  own range, its own numbers and its own label.  This is what makes two
  quantities of completely different size - per cent and counts, degrees and
  volts - readable in one diagram.
* `Plot` opens a diagram of the ticked columns, and `Update plot` follows
  every change: a column that was unticked disappears, one that is ticked
  again comes back, and moving a tick from `y_L` to `y_R` **moves that curve
  to the other scale** while it keeps its colour, its line style and its
  legend box.
* with nothing ticked the program says so instead of drawing an empty
  diagram - as long as there really is a filled column that was switched
  off.  **One single filled column** needs no tick of its own: it is drawn
  against the row numbers (or counted, in a histogram).
* the ticks are kept while the table is edited (adding rows, renaming a
  column, adding a column - a new column starts on `y_L`) and are reset to
  the first axis of every column whenever new data is loaded.

The colours are handed out per curve, not per axis, so the first curve on
the right is **not** painted in the same colour as the first one on the
left.

A saved `.aplt` file always contains the **whole** table, and the diagrams
in it keep exactly the curves they had when they were saved, each one on
the axis it was drawn against.

### How many columns there are

The **blank sheet the program starts with** is filled with as many columns
as the window can show: the names from
`Settings > Spreadsheet > Column names` come first (`X`, `Y1`, ...) and the
rest are added as `Y2`, `Y3`, ... until the width of the window is used up.

* **Widening the window brings more columns**, one for every column width
  that fits.
* **Narrowing it keeps every column** that is there and lets the horizontal
  scroll bar take over, so nothing can be lost by making the window small.
* As soon as **one value is typed** into the sheet - or a data file is
  loaded - the columns stop appearing by themselves: from then on the table
  is your data and only `Add column` changes its shape.
* A sheet that is emptied again (a fresh start) fills the window again.

`Add column` and `Delete column` work at any time, and a column that is
empty from top to bottom is simply not plotted, so a few spare columns cost
nothing.

### Editing cells

* The sheet has the keyboard **as soon as the window opens**: cell `A1` is
  already marked, the arrow keys walk from cell to cell and typing starts
  writing - nothing has to be clicked first.  The sheet that is brought to
  the front, and the one left in front by an opened graph, take the
  keyboard the same way.
* **Coming back to the window** - a click on its title bar, on its icon in
  the Dock, `Cmd+Tab` - gives the keyboard back to the sheet as well, so
  the arrows and the typing work at once, without clicking a cell first.
  The same happens after a toolbar button was clicked.  A cell that is
  being written, the formula bar and the name of a tab keep the keyboard,
  and a key that would otherwise have gone nowhere is handed to the sheet,
  so even the very first arrow or digit is not lost.
* **Just start typing**: the first character opens the cell under the
  cursor and is the first character in it, as in a spreadsheet.  `Enter`
  or `F2` opens it with the value that is there instead.
* Click a cell to edit it.  The text is selected, so typing replaces it.
* `Enter` or `Down` moves one row down, `Up` one row up.
* `Tab` moves right, `Shift+Tab` moves left; at the end of a row the cursor
  wraps to the beginning of the next one.
* Leaving the last row appends a new row automatically, so the table grows
  as long as you keep typing.  This can be switched off in the settings.
* `Left` and `Right` move the text cursor inside the cell, and step to the
  neighbouring cell once the cursor has reached the end of the text (at the
  end of a row they wrap to the next one, exactly like `Tab`).
* `Ctrl`, `Cmd` or `Alt` together with any arrow key always jumps to the
  neighbouring cell, whatever the text cursor is doing.
* `Esc` cancels the edit and keeps the previous value.
* Text can be selected **with the pointer**: press in the cell and drag
  across the characters - the editor opens with the press, so the drag
  highlights exactly the part you sweep over (leaving the cell during the
  drag selects a block of cells instead).  A plain click selects the whole
  text, a double click a word.
* While a block is dragged out, holding the pointer at the bottom (or the
  top, or a side) of the table keeps scrolling it row by row, and the block
  follows - the selection is not limited to what is on the screen.
* `Shift+Left/Right` extend the selection inside the cell, `Ctrl+A`
  (`Cmd+A` on macOS) selects the whole text of the cell and `Ctrl+C`
  (`Cmd+C`) copies it.
* `Esc` closes the editor and leaves the keyboard on the table itself,
  where the arrow keys walk from cell to cell.

Values that look like numbers are stored as numbers; everything else is
kept as text and is ignored when plotting.

### Selecting several rows and columns

The table always has a **highlighted block** of cells, marked by a blue
rectangle around it.  It can be one cell or a whole rectangle of rows and
columns.  Rows are **tinted** light blue only when the block covers every
column of them - that is, when whole rows were selected on purpose (with
`Shift+Space`, `Ctrl/Cmd+A`, or by taking the selection across all the
columns).  Clicking or editing a single cell marks that cell alone and
leaves its row quiet.

| Action | What happens |
| --- | --- |
| Click a cell | That cell alone is the block, and it is opened for editing. |
| Drag with the pointer | Inside the pressed cell it highlights its text; leaving that cell it selects the block between the pressed and the released cell.  Dragging to the edge of the table **scrolls it on** as long as the pointer stays there, so rows and columns below or beside the window can be selected as well. |
| `Shift`+click a cell | Stretches the block from where it started to that cell. |
| Click a column letter (`A`, `B`, ...) | Selects that **whole column**; dragging along the letters takes a range of them, and `Shift`+click stretches the block. |
| Click a row number (`1`, `2`, ...) | Selects that **whole row**; dragging along the numbers takes a range of them. |
| Click the corner (`◢`) | The whole table. |
| `Shift`+click a heading | Selects that whole column. |
| `Shift`+arrow keys | One row or column more (or less) in the block - this also works while a cell is being edited, where `Shift+Up/Down` leaves the editor at once and `Shift+Left/Right` first select the text of the cell. |
| Arrow keys (no Shift) | Walk from cell to cell; the block collapses to that one cell. |
| `Shift+Space` | The whole rows the block touches (they become tinted). |
| `Ctrl/Cmd+Space` | The whole columns the block touches. |
| `Ctrl/Cmd+A` | The whole table. |
| `Enter` or `F2` | Opens the cell under the cursor for editing. |
| Any letter, digit or sign | Opens the cell under the cursor and writes that character into it (what was there is replaced).  `Ctrl`, `Cmd` and `Alt` together with a key stay commands and never write. |

The open cell always carries a **blinking blue cursor** and always has the
keyboard, even when a diagram window was the one in front a moment before
(after a graph was opened, for instance): the cell takes the keyboard back
for itself, and a diagram window never takes it away from a cell that is
being edited.  Clicking in the diagram, as always, gives the keyboard back
to the diagram.

The block is what the data operations work on:

| Keys | What happens |
| --- | --- |
| `Ctrl/Cmd+C` | Copies the block as tab separated text - several rows and columns at once, ready for a spreadsheet program. |
| `Ctrl/Cmd+V` | Writes tab separated text (from this program or another one) into the table, starting at the **top left cell of the block**; the shape of the text decides the shape of what is written, so a block of two columns fills two columns even when only one cell is selected.  The table grows if the text has more rows.  This also works while a cell is being edited - only a single value (no tabs, no line breaks) is pasted into the text of that cell. |
| `Ctrl/Cmd+X` | Copies the block and empties it (inside a cell editor it cuts the selected text instead). |
| `Ctrl/Cmd+D` | `Edit > Duplicate`: the block again, in the rows just under it.  (Filling down keeps the fill handle and the `Fill Down` line of the right click menu.) |
| `Ctrl/Cmd+Z` | Takes the last change back; `Shift+Ctrl/Cmd+Z` does it again (see section 3). |
| `Delete` or `Backspace` | Empties the cells of the block. |
| `Delete row` button | Removes every row of the block. |

**Copying carries the values, not the formulas.**  What goes on the
clipboard is what the cells **show**: copying a calculated column and
pasting it somewhere else gives the numbers there, not the expressions
behind them.  That is what makes it possible to hand a result to another
program, or to freeze a calculated column into plain data.

**An emptied cell is really empty.**  A cell that is **cut**, **cleared**
(`Delete`) or **written over** with a pasted value loses the formula that
stood in it, together with its value: it is not a calculated cell any more.
Every other formula of the sheet is then worked out again at once, so a
formula that read one of those cells shows its new result immediately.

### Leaving a gap in a curve

An **empty cell is a gap, not a zero**: the curve is cut there instead of
being drawn straight across the missing point.  So a range of data can be
plotted in pieces:

1. select the cells that should not be plotted - a block, a whole row, or
   parts of a few columns,
2. press `Delete` (or `Clear cells` in the toolbar),
3. press `Update plot`.

Every curve whose cells were emptied is now drawn in two (or more) separate
pieces, with the markers of the remaining points where they belong.  Filling
the cells again joins the curve back together.

Nothing is thrown away and nothing is bridged: an empty cell in the Y
column, an empty cell in the X column and a **completely empty row** all
break the curve at that place.  So simply leaving a row empty in the middle
of the data is enough to cut the curve in two.

The only case with no curve at all is a column that is empty from top to
bottom.

### Column names

Click a column heading to edit its name.  The name is used

* as the legend text of that curve, and
* for the first column, as the label of the X axis.

Renaming a column later also renames the legend entry and the X axis label
in the open diagrams **of that sheet** - the ones opened from it, or from a
sheet glued to it with `Plot with previous tab` - unless you gave them your
own text, which is never overwritten.  A diagram of another sheet is never
touched, even when that sheet happens to have a column of the same name
(two sheets easily both have a `Y4`).  When the first column is drawn as a curve of its own (a
histogram, or a single filled column against the row numbers), renaming it
renames that curve and its legend box as well.


## 2. The diagram window

### The page

A diagram is a **page**, like a slide: it has a size of its own - the
`Page width` and `Page height` of the settings - and it keeps that size
whatever happens to the window.  The window is only a view of the page:

* **Resizing the window never changes the diagram.**  The proportions, the
  lengths of the axes, the font sizes and everything else stay exactly as
  they are; only more or less of the desk around the page becomes visible.
* When the window is **larger** than the page, the page sits in the middle
  of the desk.
* When the window is **smaller**, scrollbars appear and the page can be
  moved about: with the **wheel** (`Shift`+wheel sideways), by dragging with
  the **middle button**, or with the scrollbars themselves.
* **Zooming** changes how large the page is drawn, not what is on it.
  There are three ways to it, and all three zoom around the **pointer** -
  the point under it stays under it:
  * `Ctrl/Cmd` held while the **wheel** turns, which is also what two
    fingers sliding on a trackpad send;
  * the **`-`**, the zoom and the **`+`** at the end of the toolbar, where
    the zoom also opens a little menu of the usual ones, `Fit the window`
    and `True size`;
  * `Ctrl/Cmd`+`+` and `Ctrl/Cmd`+`-` from the keyboard, with `Ctrl/Cmd+0`
    for the true size of the page.

  The zoom starts at 15%, and is written both on the toolbar button and in
  its message line.
* The zoom is a property of the **view**, so it changes nothing that is
  saved or exported: a picture, a copy on the clipboard and an exported
  matplotlib program are always of the page itself.

The size of the page is stored in the `.aplt` file together with the zoom,
so a graph opens looking exactly as it was left.

#### Zooming smoothly

The whole page is drawn again at every step of a zoom, and that drawing is
the slow part.  Three things keep it from stuttering:

* **Every push is worth a fraction of a notch.**  A mouse wheel clicks once
  and sends a big number; a trackpad sends a run of small pushes as the
  fingers slide.  Each push moves the zoom by its own small share, so two
  fingers glide instead of jumping.
* **The pushes are gathered up.**  They arrive far faster than a page can be
  drawn, so they are added together and the page is drawn **once**, at the
  value the fingers have reached by then - never at a value they have long
  passed.  The wait before that drawing grows with what the last one really
  cost, so a heavy diagram keeps answering the fingers.
* **One drawing, not three.**  Resizing the canvas used to make matplotlib
  repaint the diagram two or three times for a single push; now the asking
  is held back and one drawing is made at the end.

Five constants at the top of `aplot.py` set the feel of it:

| Constant | What it sets |
| --- | --- |
| `ZOOM_STEP` (1.035) | how much **one notch** zooms.  Raise it for coarser, faster steps, lower it for finer ones. |
| `ZOOM_WHEEL_UNIT` (4.0) | what counts as **one notch** when the system sends small numbers instead of the 120 a mouse wheel clicks (macOS does this for both the wheel and the trackpad).  **Raise it if the zoom runs away under two fingers**, lower it if it is too slow to answer. |
| `ZOOM_MAX_NOTCHES` (2.0) | the most a **single** push may zoom, so one flick cannot jump across the whole range. |
| `ZOOM_SETTLE_MS` (15) and `ZOOM_SETTLE_MAX_MS` (120) | the shortest and the longest wait before the gathered pushes are drawn. |
| `ZOOM_MAX_PIXELS` (6 million) | the largest the page is ever drawn.  However far you zoom in, the page stops here - a page of tens of millions of pixels would crawl.  It is why `Ctrl/Cmd`+`+` stops at a different place for a large page than for a small one. |
| `ZOOM_BUTTON_STEP` (1.25) | one press of `-` or `+` on the toolbar. |
| `ZOOM_SCROLL_LINES` (0.2) | how far the desk **scrolls** for one notch, in scroll units (one unit is a tenth of what the window shows). |
| `ZOOM_PRESETS` | the percentages the zoom button's menu offers. |

**Why there is no pinch gesture.**  macOS sends a pinch to **Cocoa**, and
Tk never sees it.  It can be picked up from Cocoa with `pyobjc`, and an
earlier version of this program did exactly that - but the gesture then
calls back into Python from inside Tk's own event loop, where Python has
let go of the interpreter lock, and the program dies on the spot:

    Fatal Python error: PyEval_RestoreThread: the function must be called
    with the GIL held ... the GIL is released

There is no way to make that safe while Tk runs the loop, so APlot does not
listen for the gesture at all.  What a trackpad *does* send to Tk is the
wheel: **two fingers sliding with `Ctrl`/`Cmd` held zoom exactly as a pinch
would**, and the `-` and `+` of the toolbar are always there.

**A new diagram starts at a set place on the page**, the one the `Frame`
tab of the settings holds (`left`, `bottom`, `x_length`, `y_length` as
fractions of the page) - and `Default layout` in `Frame and origin` puts
that place back.  It is deliberately modest, so that there is room to work
around the graph; `Resize graph > Fit to page` is the one command that
blows the whole diagram up to fill the page.  A size and origin of your
own, typed in `Frame and origin` or set in the settings, is used as it
stands.

### Clicking

Every text, label, axis and object reacts to the mouse, and all of them
follow the same rule:

> **One click selects, a second click opens the properties.**

A selected object can be moved with the pointer or with the arrow keys,
copied, pasted and deleted, so a whole diagram can be arranged without
opening a single dialog.  What is selected is always visible:

* a **text** - the title, an axis label, a legend box or a text box - is
  covered with a light **blue veil** in a blue frame,
* a **drawing** or an **arrow** shows its **control points** instead,
* clicking an empty part of the diagram deselects everything, and
  dragging there chooses several objects at once (see `Choosing several
  objects at once`).

The single exception is a **curve**: it is never selected, because there is
nothing to move or copy on it by itself.  A curve is opened by clicking it
**twice**; one click takes hold of the whole graph and carries it to
another place (see `Moving the whole graph`).

| Action | Result |
| --- | --- |
| Drag a curve, an axis line or the numbers of an axis | **Moves the whole graph** to another place in the window (see `Moving the whole graph`). |
| Drag on the empty background | Draws a **rectangle**: every legend box, text box, title, axis label, drawing and arrow it touches is chosen, and they then move together (see `Choosing several objects at once`).  `Shift` adds to what is already chosen. |
| Click a curve twice | Curve properties: line and marker settings separately.  One click does not open it - it grabs the graph. |
| Click twice on the **sample** of a legend box (the little line, marker or patch in front of its text) | The curve properties of that curve, the same window as clicking the curve itself twice. |
| Click twice on the **text** of a legend box | The legend editor of that entry (its text, size, colour and frame).  Only the text opens it. |
| Click the title, an axis label, a legend box, a text box, a drawing or an arrow | Selects it (a text turns blue, a drawing shows control points). |
| Click the selected object again | Its property window: text, font, colours, distances - whatever belongs to that object. |
| Drag any selected-able object | Moves it (the title, the axis labels, the legend boxes, text boxes, drawings and arrows all move freely). |
| Drag a control point | Resizes a drawing, moves the tip or the tail of an arrow or of a line, or makes an axis longer or shorter.  On a **picture** the four **corner** points keep its proportions and the four **side** points squeeze or stretch it (see `Resizing with the control points`). |
| Drag the round control point above a drawing or a text box | Turns it around its centre (a text box around its own anchor); `Shift` keeps 15 degree steps.  A line has no such point: its two ends give the direction. |
| Arrow keys | Move the selected object by one pixel, with `Shift` by ten. |
| Right click (`Ctrl`+click on a Mac) | The menu of that object: `Copy`, `Cut`, `Paste`, `Duplicate`, `Bring to front`, `Bring forward`, `Send backward`, `Send to back` (see `Which object is in front`).  On the **paper** the same menu ends with `Resize graph`. |
| Wheel / `Ctrl/Cmd`+wheel | Scrolls the page in the window / zooms the view around the pointer; the toolbar's `-`, zoom and `+` do the same (see `The page`). |
| `Ctrl/Cmd+C`, `Ctrl/Cmd+X`, `Ctrl/Cmd+V` | Copies or cuts out the selected text box, drawing, picture or arrow with all of its properties, and pastes another copy of it.  Of the two things that can be waiting - an object copied here and a picture on the clipboard of the system - `Ctrl/Cmd+V` takes the **newer** one. |
| `Ctrl/Cmd+D` | `Edit > Duplicate`: a second copy of the selected object at once, a little to the lower right, without touching the clipboard. |
| `Ctrl/Cmd+Z` | Takes the last change back; `Shift+Ctrl/Cmd+Z` does it again (see section 3). |
| Drop a picture file on the diagram | Lays that picture where it was dropped (see `Pictures in the diagram`). |
| `Delete` / `Backspace` | Removes the selected text box, drawing, picture or arrow. |
| Click an axis line (the frame) | Selects that axis: a control point appears on each of its two ends. |
| Drag the axis line itself | Moves the whole graph, the same as dragging a curve. |
| Drag one of those two points | Makes that axis longer or shorter - the other end stays where it is. |
| Click the selected axis line again | Frame and origin settings. |
| Click twice beside an axis (on the numbers or the label) | Axes properties, opened on the tab of that axis (the window also carries the title page and both Y axis pages). |
| Hold Shift while drawing or resizing an arrow or a line | Keeps it horizontal, vertical or at 45, 135, 225, 315 degrees. |
| Plot menu | The axes dialog (axes, frame and origin), the title/fonts dialog, copy, cut, paste and delete of the selected object, the four stacking commands, plus closing this diagram. |
| Toolbar | The Matplotlib tools (home, back, forward, pan, zoom, subplots, saving the figure as an image) in the drawn icons of the program, the **T** button that adds a text box, the drawing tool, the arrow tool and the picture button. |

The blue veil and the control points are only on the screen: they are left
out of the image that the save button of the toolbar writes.

The control points are small, slightly see-through squares (25 %
transparent), so the tip of an arrow or the corner of a picture shows
through the point that moves it.  Near the top of `aplot.py`,
`TRANSPARENT_HANDLES = False` makes them solid white squares instead, and
`HANDLE_ALPHA` beside it is how much of a see-through point shows (0.75).
They keep **the same size on the screen at every zoom**: at 200 % they are
no larger than at 100 %, while the diagram under them is twice as large -
which is the comfortable way to place a tip exactly.  A point grabbed a
little off its centre does not jump onto the pointer: it keeps that small
distance and moves exactly as far as the mouse does.

**Dragging is fast at any zoom.**  When a drag begins, the page is drawn
once without the object that moves; every step of the drag then paints
only that object (with its control points) over the still page and sends
just the few pixels that changed to the screen.  When the mouse is let
go, the whole page is drawn again as it really is.  During the drag the
moving object is shown on top of everything; its real place in the stack
(see below) is back as soon as it is dropped.  Moving the whole graph and
pulling an axis end still draw the whole page at each step, since they
change all of it.  `FAST_DRAGS = False` near the top of `aplot.py` goes
back to drawing the whole page at every step.

**Large pictures** - a scan or a photograph of 300 dpi has millions of
pixels - are kept whole in the graph and in its file, but they are not
shrunk from all those pixels at each drawing: a few smaller copies, each
half as large as the one before, are made once, and the smallest one that
still has at least as many pixels as the picture's box on the screen is
drawn.  An exported picture, a copied figure or the thumbnail asks for as
many pixels as it needs, and gets a larger copy or the whole picture.

### Which object is in front

Everything drawn inside the plot area stands in one **stack**: the curves,
the drawings, the pictures, the arrows, the text boxes **and the three
axes** together.  What is higher in the stack is painted over what is
lower, and every one of them can be moved up and down in it - so a picture
can be pushed **behind** the curves as a background, one curve can be
brought out **in front of** another one, and a drawing can be laid over the
frame or sent back under it.

* A **right click** on any of them (`Ctrl`+click on a Mac, or the right
  button of the mouse) opens a small menu.  Its first line names what was
  found under the pointer - `Curve`, `Drawing`, `Picture`, `Arrow`,
  `Text box`, `Bottom X axis` and the other axis names, or `The paper of
  the diagram` when the pointer was on the empty paper.
* Four commands move it: **Bring to front** and **Send to back** take it
  the whole way in one click, while **Bring forward** and **Send backward**
  lift it past exactly **one** neighbour - clicking the same line again and
  again walks it through the stack, and the toolbar says at every step what
  it has just passed.  All four are in the **Plot** menu as well, for
  whatever is selected.
* **Copy** and **Cut** put a text box, a drawing, a picture or an arrow
  aside - `Cut` takes it out of the diagram as well.  A **curve** belongs
  to the spreadsheet, so those two lines are greyed out over a curve; it
  can still be moved in the stack.
* **Paste** lays the copied object - or a picture waiting on the clipboard
  of the system - exactly **where the right button was pressed**, on top of
  everything.  This is what the empty paper is for: right click anywhere in
  the diagram and paste.
* What the pointer finds is what is **in front** at that point, so after a
  curve has been moved over a drawing the same click reaches the curve.
* A newly drawn object always appears in front of everything, and so does
  a **curve drawn for the first time** - a fitted curve above all, which
  lands on top of the measurements it was fitted to and is never crossed by
  their markers or error bars.  The whole order is written into the `.aplt`
  file and into the exported matplotlib program.
* **Every object has a place of its own.**  Two objects at the same height
  are painted in whatever order matplotlib happens to hold them, which is
  no order at all to a reader and none the user can change; and since the
  parts of a curve are drawn a little above its own line, a tie can let one
  curve's error bars cross another curve, which makes a line look dashed
  where it passes them.  A graph written before this was so opens with its
  stack spread out again - nothing that can be seen changes - and
  `Bring to front` on an object that is tied with its neighbours breaks the
  tie instead of reporting that there is nothing to do.
* The stack reaches **across both Y scales**.  Matplotlib draws one set of
  axes completely before the other, so a drawing could otherwise never
  stand over a curve of the **right hand** scale, whatever its place in the
  stack said.  APlot therefore lays the two axes themselves in the order
  the stack asks for and hands every drawn object to the one it has to be
  on - all of it by itself, so an ellipse really does come out in front of
  a curve of the right scale, and that curve really does go behind it.
* A curve is more than one drawn thing - its line, the **filled area**
  under it, its error bars, its bars.  They keep their own order among
  themselves but move as **one** object, so something pushed behind a
  filled curve disappears under the filling completely, not only under the
  line.
* **An axis is one object too**, and all of it moves together: its line on
  the plot area, its **tick marks, its numbers and its label** - and the
  **grid lines** of that axis, which matplotlib draws with it.  Each of the
  three axes has a height of its own, and all three stand **in front of
  the diagram** to begin with, which is where the frame has always been
  drawn.  Two things follow from that:
  * the numbers and the tick marks are no longer stuck **behind**
    everything: a drawing laid over the axis hides them only if it is
    brought in front of that axis on purpose;
  * a **grid** now stands in front of the curves with its axis.  One
    `Send to back` on that axis puts the grid (and its numbers) under the
    curves again, which is the classic look.
  Right click the axis **line** to reach its menu, and the height is kept
  in the `.aplt` file and written into the exported matplotlib program.
* Something newly drawn is placed in front of the other **objects** but
  still **behind the axes**, so adding a drawing never hides the frame by
  itself.

### Drawing rectangles, triangles, circles, ellipses and lines

The button next to **T** is the drawing tool.  Its icon shows the shape
that will be drawn, with a small arrow in its lower right corner:

* clicking the **icon** starts drawing with the shape that is shown (a
  rectangle at the first start, later whatever was used last),
* clicking the **arrow** opens the list `Rectangle`, `Triangle`, `Circle`,
  `Ellipse`, `Line`, each line with a little picture of its shape; after
  choosing one the tool is armed with it and the icon changes to that
  shape.

While the tool is armed the button stays pressed and the pointer becomes a
cross.  Press in the diagram and drag: the object is drawn between the
press and the release point with the default line and fill.  A plain click
without dragging gives an object of a comfortable default size.  `Esc` or
clicking the icon again cancels.

An object that was drawn behaves like the other decorations:

* it is **selected** by one click, and eight small square **control
  points** appear on its corners and on the middle of its sides; dragging
  one of them **resizes** the object (the pointer becomes a resize cross),
* dragging the object itself **moves** it, and so do the arrow keys,
* a **second click** opens its **properties**, where the name of the `Line`
  and of the `Fill` section is its own **check button**: switched off, that
  part of the object is simply not drawn (so the style lists have no "None"
  entry, and the settings are remembered while a section is off).  The
  sections hold the line style (solid, dashed, dash-dot, dotted), the line
  thickness and colour, the fill colour with an opacity, the rotation, and
  a `Delete` button,
* clicking an empty part of the diagram deselects it,
* a circle keeps its round shape: its height follows its width and the
  proportions of the plot area,
* a **line** is drawn between the two points of the drag and is clicked on
  the stroke itself, not anywhere in its bounding box.  It behaves like an
  arrow: it has **two control points**, one on each end, dragging either of
  them changes the length and the direction, and holding **Shift** while
  drawing it or while dragging an end keeps it at 45 degree steps (exactly
  horizontal, vertical or diagonal).  It has no fill and no rotation of its
  own, so its property window has only the `Line` section,
* it can be **turned** to any angle: see below.

The positions and sizes are kept in the coordinates of the plot area, so
the objects follow the graph wherever it is moved or resized on the page,
and they are stored in `.aplt` files.  The starting line and fill of new objects come
from the `Drawings` tab of the settings.

### The second Y axis and the top X axis

The `y_R` and `x_T` check buttons of the spreadsheet (see `Which columns are
plotted, and against which axis`) give the diagram two more axes:

* the **right hand Y axis** is a scale of its own.  It appears as soon as a
  curve is drawn against it and goes away again when the last such curve is
  unticked.  It has its own range, its own numbers, its own label and its
  own automatic scaling, so a curve of a few tenths and one of tens of
  thousands can share a diagram and both be readable.
* the **top X axis** is the same X scale drawn above the plot area instead
  of below it: the numbers and the axis label move up together, and with
  `No frame` the line above the plot area is the one that is drawn while
  the one below it stays away.

Everything else works exactly as on the two original axes:

* `Axes properties` always carries a **`Right Y axis`** page beside
  `X axis` and `Left Y axis` - range, step, minor ticks, label, fonts,
  colours, direction, scale and distances, all of it separately from the
  left axis.  While no curve is drawn there its `Direction` box reads
  `No right Y axis`; choosing `Standard` brings the axis out with a free
  0 ... 1 scale.  Its grid is left to the main axes, so no line is drawn
  twice.
* a **double click** next to the right hand numbers opens that page, just
  as a double click under the X numbers opens the `X axis` page; with `x_T`
  the X region is above the plot area instead of below it.
* the **right axis label** is a text like any other: one click selects it
  (blue veil), a slow second click rewrites it in place, a double click
  opens its dialog, and the arrow keys move it.
* a **filled area** under a curve on the right is filled on the right hand
  scale, and `Fill down to the bottom of the axes` means the bottom of that
  scale.
* both new lines are **resized by the pointer** exactly like the two
  original ones: click the line, drag one of its two ends (see `Resizing
  the axes with the pointer`).
* the whole arrangement - which side the X axis is on and which curve
  belongs to which Y axis - is stored in `.aplt` files.  Files written by
  an older version load with everything on the bottom and the left, as
  before.

### Resizing the axes with the pointer

The plot area does not have to be sized in a dialog: **click any axis
line** and a small square control point appears on each of its two ends.
All four sides work, each with the points on its own line:

| Clicked line | Its two points | Dragging them |
| --- | --- | --- |
| bottom X axis | the lower two corners | the width |
| top X axis | the upper two corners | the width |
| left Y axis | the left two corners | the height |
| right Y axis | the right two corners | the height |

* The **horizontal** lines carry the width of the diagram: dragging the
  right point makes it wider or narrower and leaves the origin where it is,
  dragging the left one moves the origin and keeps the right end in place.
  The **vertical** lines work the same way upwards, with the height.
* So a diagram drawn against the **top X axis** and the **right Y axis** is
  sized exactly like any other one - by the two lines that are actually
  there.
* Only a line that is really **drawn** can be clicked, and a line that
  disappears (because the X axis moved to the other side, or the last curve
  of one Y axis was unticked) drops out of the selection by itself.
* Dragging an axis **line** (anywhere but its two ends) moves the whole
  graph - see `Moving the whole graph` just below.
* The arrow keys move the **whole plot area** while an axis is selected
  (`Shift`: ten pixels), keeping its size.
* Everything in the diagram - the curves, the legend boxes, the text
  boxes, the drawings and the arrows - keeps its place inside the plot
  area and follows it.
* **Double clicking** an axis line opens `Frame and origin`, where the same
  numbers can be typed in fractions, centimetres or inches; the dialog
  always shows what the pointer has made.
* The size is kept in fractions of the **page**, so it is the same
  whatever the window does and at any zoom, and it is stored in `.aplt`
  files.

### Moving the whole graph

The plot area does not have to stay where the program put it.  **Grab a
part of the graph itself and drag**, and the whole graph travels with the
pointer:

* any **curve** - grabbing a line no longer opens its properties, it takes
  hold of the graph (the properties are two clicks away now),
* any **axis line** of the frame - the same line whose two ends resize the
  axis, so its middle moves the graph and its ends stretch it - and the
  other lines of a closed frame,
* the **numbers** of an axis.

The **empty background** - the paper around the graph and the empty inside
of the plot area - does not move the graph: dragging there draws a
rectangle that chooses objects (see `Choosing several objects at once`).

Only the two distances of the origin change.  The length of both axes, the
ranges, the ticks and everything drawn inside - the curves, the legend
boxes, the text boxes, the drawings, the pictures and the arrows - stay as
they are and travel along.  The pointer turns into a four way arrow over
everything that can carry the graph, and the graph is kept inside the
**page**, so it cannot be pushed off it.

The whole drag is **one step**: `Edit > Undo` (`Ctrl/Cmd+Z`) puts the graph
back where it was.  The arrow keys still move it by single pixels while an
axis is selected, and `Frame and origin` still takes the same two distances
as numbers.

While the **pan** or the **zoom** tool of the toolbar is switched on the
canvas belongs to that tool, and dragging does what the tool says instead.

### Resizing the graph on the page

**Right click the paper** - anywhere that is not an object - and the menu
ends with `Resize graph`:

| Item | What it does |
| --- | --- |
| `Smaller` | Takes **ten per cent** off the length of both axes. |
| `Larger` | Puts **ten per cent** on. |
| `Fit to page` | The diagram is made **as large as the page allows**: the whole of it - the plot area *and* the numbers, the axis labels, the title and the legend boxes - is grown and centred until only a narrow strip of white is left around it (half a centimetre, `PAGE_FIT_MARGIN`). |

`Fit to page` measures the **whole drawing**, not the plot area alone:
the numbers, the axis labels, the title, the legend boxes and every text
box, drawing or arrow count, exactly as they do when a picture is
exported.  The two directions are fitted separately, so the same narrow
strip of white is left on all four sides, and the diagram is put in the
middle of the page.  Asking for it twice does nothing the second time -
the program says `The graph already fills the page` - and on a small page
a long title may keep a millimetre or two of the strip for itself, because
a font size is a whole number of points and cannot shrink any further.

`Smaller` and `Larger` keep the **middle** of the graph where it is, so it
grows and shrinks in place, and the graph is kept inside the page.
Everything drawn in the plot area - the curves, the legend boxes, the text
boxes, the drawings, the pictures and the arrows - keeps its place inside it
and follows.  Each choice is **one step** of `Edit > Undo`.

This changes the **graph on the page**, not the page and not the window:
`Resize graph` makes the drawing itself bigger or smaller, the zoom only
changes how large the page is shown, and the size of the page is set by
`Page width` and `Page height` in the settings.

#### The whole look is scaled with the graph

`Resize graph` does not only move the four sides of the plot area: it
scales the **whole drawing**, the way a picture is scaled.  Every size
that is a length or a font on the paper is multiplied by the same factor
as the axes, so a graph whose axes are **twice as long** is drawn with

* a title, axis labels, numbers and legend texts of **twice the font
  size** (12 pt becomes 24 pt),
* curves **twice as thick** and markers twice as large (a line width of
  1.5 becomes 3.0), with their edges to match,
* **tick marks twice as long** - major and minor - and a frame and grid
  lines twice as thick,
* the numbers, the axis labels and the title standing **twice as far**
  from the axes (`Number offset`, `Label offset` and `Title distance`),
* the drawings, the arrows and the text boxes carrying twice as thick
  lines, twice as large arrow heads and twice as large a font.

Nothing else changes: the data, the ranges, the number of ticks, the
colours and the **places** of everything in the plot area stay exactly as
they are.  A place is kept as a fraction of the plot area, so it follows
the plot area by itself and a text box that stood in the top right corner
stands there afterwards too.  Font sizes are whole points, so they are
rounded to the nearest point (and never fall below one).

`Fit to page` scales the sizes in the same way, by however much it had to
grow the axes, so the diagram that fills the page is the same picture, only
larger.  When the two axes did not change by the same amount - `Fit to
page` fits the two directions on their own, and one of them can reach the
edge of the page first - the factor the fonts and the lines follow is the
average of the two, the square root of their product.

**Only this menu does it.**  Dragging the end of an axis, typing an axis
length into `Frame and origin`, moving the graph about, resizing the
window and zooming the view all leave the fonts and the line widths
exactly where the user set them.  And every `Resize graph` choice is a
single step of `Edit > Undo`, sizes included.

### Which frame lines are drawn

`Frame and origin` offers four frame styles.  `Full frame` and the two
`Frame with ticks` styles always draw **all four** lines, as before.
`No frame (X and Y only)` draws exactly the axes that are **in use**:

| In use | `No frame` draws |
| --- | --- |
| `x_B` + `y_L` | the bottom and the left line (the classical pair) |
| `x_T` + `y_R` | the top and the right line - and nothing else |
| `x_B` + `y_R` | the bottom and the right line; the left and the top stay away |
| `x_B` + `y_L` + `y_R` | the bottom line and **both** vertical lines |

An axis that carries no curve is not only left without a frame line: its
**numbers, tick marks and label disappear** as well, so a diagram whose
every curve is on the right hand scale has no empty left axis standing
next to it.

**`No X axis` (and `No left / right Y axis`) in the `Direction` box now
takes the line away too.**  Switching an axis off leaves *nothing* of it:
no line, no tick marks, no numbers, no label.  `Standard` and `Reverse`
always draw at least the **line**, even with the
`Tick range, labels and fonts` section switched off, and the numbers, the
ticks and the label come with it as their own switches say.  A **closed**
frame style (`Full frame`, `Frame with ticks`) is a frame around the plot
area rather than an axis, so it keeps all four of its sides whatever the
`Direction` box says.  The Y **grid** follows the Y axis whose numbers are shown, so
it is drawn once, on the scale it belongs to.

### Turning the drawings and the text boxes

A selected drawing shows one more control point: a **round** one on a short
line above it.  Dragging that point turns the object around its centre, and
holding **Shift** while dragging keeps the angle in 15 degree steps.  A
selected text box has the same round point above it and turns around its
own anchor, so it stays where it was put.

The exact angle is in the property window of the object as
`Rotation > Angle [deg]`, with an `Upright` button that puts it back to
zero.  Angles are counted counter-clockwise and any value is accepted;
negative angles and angles above 360 are wrapped.

The rotation is measured on the **screen**, so an object keeps its shape
and its size whatever the proportions of the plot area: a rectangle stays a
rectangle with square corners, a circle stays round, and a text stays
readable.  Everything else keeps working on a turned object:

* the eight square control points turn with it, and dragging one of them
  keeps the opposite corner exactly where it is (a line has two control
  points instead, one on each end),
* the pointer finds the object where it is really drawn, so a turned
  rectangle is not clicked by the empty corner beside it,
* moving with the pointer or with the arrow keys, copying, pasting and
  deleting leave the angle alone - a copy is turned like its original,
* the angle is stored in `.aplt` files (older files simply open upright).

### Arrows

The third button of the group is the arrow tool.  Its icon is an arrow head
pointing to the right - the head that will be drawn - with the same small
arrow in its lower right corner:

* clicking the **icon** arms the tool with the head that is shown (a
  triangle head at the first start, later whatever was used last),
* clicking the **arrow** in the corner opens the list `Triangle head`,
  `Chevron head`, `Concave head`, `Convex head`, each with a little arrow
  wearing that very head beside its name; the icon changes to the chosen
  one.

Press in the diagram at the **tail** of the arrow and drag: the arrow
follows the pointer, so its length and its direction are drawn immediately,
and it is finished by releasing the button at the **tip**.  A plain click
without dragging gives a short horizontal arrow.  `Esc` or clicking the
icon again cancels.

Holding **Shift** while the arrow is drawn - or later while its tip or tail
is dragged - snaps it to the nearest 45 degrees, so it becomes exactly
horizontal, exactly vertical or an exact diagonal (45, 135, 225, 315
degrees).  The angle is measured on the screen, so the arrow really looks
that way whatever the proportions of the plot area.  The end that is not
dragged stays where it is.

An arrow behaves like the drawn objects:

* it is **selected** by one click, and two **control points** appear, one on
  the tip and one on the tail; dragging either of them changes the length,
  the direction and the position of that end,
* dragging the shaft or the head **moves** the whole arrow (the arrow keys
  move it by one pixel, with `Shift` by ten),
* a **second click** opens its **properties**: the arrow head
  (`Triangle`, `Chevron`, `Concave`, `Convex`), the head size in pixels,
  the line style, the line thickness, the colour and a `Delete` button,
* clicking an empty part of the diagram deselects it.

The tip and the tail are kept in the coordinates of the plot area, so the
arrows follow the graph wherever it is moved or resized on the page, while
the head keeps its size in points.  They are stored in `.aplt` files, and the head, size,
line and colour of new arrows come from the `Arrows` tab of the settings.

### Pictures in the diagram

A picture - a logo, a photograph of the sample, a sketch, a screenshot -
can be laid on a diagram in three ways:

* **Paste it.**  Copy a picture anywhere (a browser, a photo program, the
  Finder) and press `Ctrl/Cmd+V` in the diagram window.  If the clipboard
  holds a picture it is laid in the middle of the plot area; when it holds
  no picture, the same keys paste the object that was copied inside the
  program, exactly as before.
* **Drop it.**  Drag a picture file from the Finder (or from any file
  manager) onto the diagram: it is laid **where it was dropped**, and
  several files at once become several pictures, one beside the other.  A
  file that is not a picture is quietly ignored.
* **Choose it.**  The **picture button** of the toolbar - the little framed
  landscape beside the arrow tool - and `Plot > Insert picture...` open a
  file dialog.

A picture is one of the **drawn objects**, so everything that is true of a
drawing is true of it:

* one click **selects** it and shows its eight control points, a second
  click opens its **properties**,
* dragging it **moves** it, dragging a control point **resizes** it, and
  the arrow keys move it by one pixel (with `Shift` by ten),
* `Ctrl/Cmd+C` copies it and `Delete` removes it.

It is laid at its **own proportions** to begin with, taking about a third
of the width of the plot area, and `Its own proportions` in its properties
undoes a squeeze at any time, keeping the width.  A picture is never
rotated, so it has no round handle above it.

#### Resizing with the control points

The eight control points of a selected object do two different things, and
which is which is the same everywhere in the program:

* the four points at the **corners** resize the object **diagonally**, and
* the four points in the **middle of the sides** move that one side only,
  so they squeeze the object or stretch it.

For a **picture** the corners also **keep its proportions**.  A photograph
pulled by a corner therefore stays the photograph it was - never a little
taller or a little wider than it should be - however far the corner is
dragged, and in whatever direction: the object follows the longer of the
two directions the pointer went, and the corner opposite the one being
dragged stays exactly where it is.  The side points are left free on
purpose: they are the way to compress or elongate a picture deliberately.

Holding **Shift** while dragging a corner **turns the rule around**.  On a
picture `Shift` lets the corner resize it freely, and on the drawings -
rectangles, ellipses, triangles and the rest, whose corners resize freely
by default - `Shift` makes the corner keep the proportions the object has
at that moment.  So a circle is kept a circle by holding `Shift`, and a
logo is squashed on purpose in the same way.

The proportions are measured **on the screen**, not in the coordinates of
the axes, so a picture stays undistorted whatever the shape of the plot
area, and it stays undistorted after the graph itself has been made
smaller or larger.

Its **properties** are short: `Frame` draws a line around it (style,
thickness, colour - switched off to begin with) and `Opacity (0-1)` lets
the diagram show through it, which is what a watermark needs.

The picture itself is **written into the `.aplt` file** and into the
**exported matplotlib program**, so a saved graph carries its pictures with
it and the exported program runs anywhere without the original files.  A
photograph larger than 1600 pixels is made smaller first, which keeps the
files a sensible size and is still sharper than any screen.

**Dropping needs one extra package.**  Tk itself cannot take a drop; the
`tkdnd` extension does it, and it comes with `tkinterdnd2`
(`pip install tkinterdnd2`).  Without it everything else works as usual and
pictures arrive by pasting or through the button.

### Choosing several objects at once

Moving the legend boxes of five curves one by one is tedious, so several
objects can be taken together.  **Press on the empty background and drag**:
a dashed rectangle follows the pointer, and every object it **touches** -
it does not have to cover it whole - is marked with a light blue box at
once.  When the button is let go, those objects are chosen together:

* **drag any one of them** and all of them move by the same amount, so
  they keep their places relative to each other; the whole move is one
  step of `Undo`,
* the **arrow keys** move all of them (`Shift`: ten pixels),
* **`Delete`** removes the text boxes, drawings, pictures and arrows among
  them in one step; legend boxes and the axis texts cannot be deleted, so
  they simply stay chosen,
* **`Shift`** held while drawing the rectangle **adds** what it touches to
  the objects already chosen,
* a click on the empty background, `Esc`, or a click on any single object
  lets the group go.

Legend boxes, text boxes, the title and the axis labels, drawings,
pictures and arrows can be chosen this way.  The curves and the axes are
not: they belong to the graph, which is moved by grabbing it.  A rectangle
that touches only one object simply selects it, as a click would.  The
light blue boxes are never part of a saved picture, a copied figure or the
thumbnail of the file.

### Selecting, copying, moving and deleting the objects

One click selects; what is selected is shown by the **blue veil** on a text
(the title, an axis label, a legend box, a text box) or by the **control
points** of a drawing or an arrow.  Everything that is selected can then be
worked on from the keyboard:

| Keys | What happens |
| --- | --- |
| `Ctrl+C` / `Cmd+C` | The selected object goes to the clipboard with every one of its properties - and with **nothing** selected, a picture of the whole diagram. |
| `Ctrl+V` / `Cmd+V` | Another copy appears a little to the lower right of the original and is selected; each further paste steps further, so a series of copies does not pile up. |
| Left / Right / Up / Down | Moves the selected object by one pixel. |
| `Shift` + an arrow key | Moves it by ten pixels. |
| `Delete` or `Backspace` | Removes it. |

The same commands are in the `Plot` menu as `Copy object`, `Paste object`
and `Delete object`.

A text that is selected can also be **rewritten on the spot** with a slow
second click - see `Writing a text in place` below.

The keys always belong to the window that was clicked last, so after a
property window has been used, **one click anywhere in the diagram** brings
them back - the click also keeps or changes the selection, so nothing is
lost.  The property window stays open while this happens.

Copying, pasting and deleting work on **text boxes, drawings and arrows**.
The title, the axis labels and the legend boxes belong to the diagram and
are not copied or deleted - but they are selected and moved with the arrow
keys just like everything else.

So a circle that has its final line style, thickness, line colour, fill and
opacity does not have to be built again: select it, `Ctrl/Cmd+C`, then
`Ctrl/Cmd+V` as many times as needed and move the copies where they belong
- with the pointer or with the arrow keys.  The same holds for arrows (head
type, head size, thickness, colour) and for text boxes (text, font, frame,
background).

The clipboard belongs to the program, not to one window, so an object can
be copied in one diagram and pasted into another one.  It is not the
clipboard of the operating system: `Ctrl/Cmd+C` in the diagram does not
disturb text that was copied elsewhere.

`Edit > Duplicate` (`Ctrl/Cmd+D`) is the short way of the same thing: one
key makes the copy, places it a little to the lower right and selects it,
and what was on the clipboard before stays there.

**Two things can be waiting, and the newer one wins.**  An object copied
here is kept inside the program; a picture lies on the clipboard of the
system - put there by `File > Copy figure to the clipboard`, or by any
other program.  `Ctrl/Cmd+V` always takes the one that was copied **last**:

* Between the two ways of copying inside the program the time of the copy
  decides, so copying the figure and then an object pastes the object, and
  the other way round pastes the picture.
* A picture copied in **another** program - a slide in PowerPoint or
  Keynote, a picture in a browser, a drawing in a photo editor - carries no
  time of its own.  For that one the clipboard itself is looked at: if it
  no longer holds what it held when this program last copied, then
  something newer is on it, and that is what is pasted, even when an object
  is still being kept here.  On macOS this is read from the counter the
  system keeps for it; elsewhere the picture is compared with the one that
  was there before.

So copying an ellipse here, then a picture in another program, and pressing
`Ctrl/Cmd+V` lays the **picture** into the diagram - and it goes on doing
so until something is copied here again, which puts the object back in
front.

### Writing a text in place

The title, both axis labels, the legend boxes and the text boxes can be
rewritten **on the diagram itself**, without opening any dialog.  It works
exactly like renaming a file in the Finder of macOS or in a file manager:

1. **click** the text once - it is selected and turns blue,
2. **click it a second time**, slowly - about half a second to one and a
   half seconds after the first click, clearly slower than a double click,
3. a small white box appears over the text with a **blinking blue cursor
   where the pointer was**, and the text can be edited there,
4. `Enter` keeps the new text, `Esc` keeps the old one; clicking anywhere
   else also keeps what was written.

| Click | What happens |
| --- | --- |
| one click | selects the text (blue veil) |
| a second click within 1.5 seconds | writes the text in place |
| a double click (two fast clicks) | opens the property window |

So nothing is lost: the property window - with the font size, the colour,
the distance, the frame and the background - is still one double click
away, and the fast way of fixing a typo or a unit is the slow second click.

The editor **grows with the text** while it is being written: it is
always as wide as what it holds plus one letter, centred on the text it
replaces, so a one-letter label such as `X` can be rewritten into a long
one with every letter in view.  It shrinks again when letters are taken
away, gets taller with a second line, and never grows wider than the
window.

The cursor is a vertical line in the colour of the selection, as thick as
the text is big, and it blinks - so it can be found at a glance even in a
large title.  It is drawn by the program itself and not by the operating
system, so it stays visible in a dark desktop theme as well.

Moving the text is not disturbed either: the editor waits for the button to
be **released** on the same spot, so pressing on a selected text and
**dragging** it moves it, exactly as before.

While the little editor is open the arrow keys, `Delete`, `Ctrl/Cmd+C` and
`Ctrl/Cmd+V` belong to the **text**, not to the selected object, so the
text is edited the way any text field is edited.  `Shift+Enter` starts a
new line inside a text box.  Only the text is changed; the font size, the
colour, the position, the distance from the axis, the frame and the
background all stay as they were.

Two texts are special, in the same way as in their dialogs:

* writing **nothing** into a text box deletes that box,
* writing **nothing** into a legend box hides that legend, exactly as an
  empty text does in the legend dialog.

Writing in place is a command like any other: `Undo` takes it back.  A
property window that is open at the same time shows the new text at once
(see `The property windows`).

Drawings and arrows hold no text, so a second click on them does nothing -
they are simply selected.

### Text boxes on the diagram

The **T** button on the right end of the toolbar, a little apart from the
save button, adds free text to the diagram:

1. press **T** - the button stays pressed and the pointer becomes a
   vertical line,
2. click in the diagram where the text should be - a text box appears there
   and its dialog opens,
3. type the text and press `OK`.

`Esc` or pressing **T** again cancels the placement without adding
anything.

A text box behaves like a legend box:

* **click** it to select it - it turns blue - and **drag** it with the
  pointer to move it (the pointer becomes a move cross over it), or move it
  with the arrow keys,
* **click it a second time, slowly** to rewrite the text right there (see
  `Writing a text in place`), or **double click** it to open its dialog:
  text, font size, font colour, and the `Surrounding box` section - the name
  of that section is a **check button**, so switching it off leaves the
  frame away, while its colour and the background (a colour, or fully
  transparent) stay inside it.  A new text box is **only its text**: the
  surrounding box is off and the background transparent, unless the
  `Text boxes` tab of the settings says otherwise,
* `Delete` in that dialog - or an empty text - removes the box,
* **turn** it with the round handle above it or with `Angle [deg]` in its
  dialog; it turns around its own anchor point, so it stays in place,
* the position is kept in the coordinates of the plot area, so the box
  follows the graph wherever it is moved or resized on the page,
* any number of text boxes can be added, and they are all stored in
  `.aplt` files.

The starting font, frame and background of new boxes come from the
`Text boxes` tab of the settings.

### Moving the title and the axis labels

The title and both axis labels can be dragged with the pointer, just like
the legend boxes: press on the text, move it, release it.  The pointer
becomes a move cross over them.  Pressing and releasing without moving is a
click, so it only selects the text (it turns blue); a slow second click
writes the text in place (see `Writing a text in place`) and a double click
opens its dialog.  A selected label also moves with the arrow keys, one
pixel at a time, or ten with `Shift` - handy for the last bit of fine
tuning.

The drag is stored as a shift **on top of** the automatic placement,
measured in **points of the page** - the unit the fonts are measured in -
however far the view happens to be zoomed when the text is moved.  So a
label moved inside the plot area stays exactly there at every zoom, in a
copied or exported picture at any resolution and in the thumbnail of the
file, just as a text box does.  (Files saved before this kept the shift in
pixels of the page; they are converted when opened.)  The distances of the
settings - `Label offset [px]`, `Number offset [px]`, the title distance -
are pixels of the page at 100 % zoom, so they stay the same on paper
whatever the zoom as well.  This has two further useful consequences:

* the text keeps following the diagram - it stays in place when the window
  is resized, when the axes are moved in `Frame and origin`, or when longer
  numbers appear next to the axis,
* the **distance** setting still works: it moves the text with respect to
  the axis, and the drag is added to that.

`Plot > Title and fonts... > Reset dragged texts` puts the title and both
labels back to their automatic places.

### Legend boxes

Every curve has its **own** legend box, so they can be placed
independently.

* Click a box anywhere - on its frame or on its text - to select it: it is
  covered with the blue veil.  Then drag it to a new place with the
  pointer, or move it with the arrow keys (`Shift`: ten pixels).
* Click the selected box a second time, slowly, to rewrite its text on the
  diagram itself (see `Writing a text in place`).
* **Double click** it to open its own dialog: the text, the font size and
  the font colour, the **frame** around the box (its colour, or no frame at
  all) and the **background** (its colour, or fully transparent).  An empty
  text hides the box.
* The boxes keep their position when the data is updated, when the curve
  style changes and when a column is renamed, and they are stored in
  `.aplt` files.
* `Plot > Title and fonts...` sets one font size for every box, the corner
  where new boxes start, and can stack all boxes again with
  `Reset positions`.

### The property windows

The dialogs (curve properties, axes properties, title and fonts, legend)
are ordinary windows:

* they open **next to** the diagram window, not on top of it (to the right
  if there is room on the screen, otherwise to the left),
* the diagram can be **clicked in front of them** while they stay open, so
  a change can be looked at without a dialog covering the curves,
* clicking the same curve, axis or legend twice again brings its window
  back to the front,
* they stay open until they are closed, and several of them can be open at
  the same time.

If the old behaviour is preferred, `Property windows always on top` in the
`Windows` tab of the settings keeps them above the diagram again.

**An open window always says what the diagram says.**  The diagram and its
windows can be used side by side: a title or an axis label written on the
graph itself, a legend renamed there, a text box or a drawing turned by its
handle, `Resize graph`, a step of `Undo` or `Redo` - all of it appears at
once in every window that shows it (`Axes properties` with all its pages,
`Title and fonts`, `Curve properties`, the title, label, legend, text box,
drawing and arrow windows).  So `Apply` never puts an old text or an old
size back next to the one thing that was really changed: with `Axes
properties` open, write a new title on the graph, then change the number
of minor ticks and press `Apply` - the new title stays.

A field that has been **changed in the window and not applied yet** is the
user's own: the diagram does not write over it, and `Apply` (or, in the
windows that apply at once, the change itself) sends it to the diagram.
From then on the field follows the diagram again.

The `Font size (all)` and `Font colour (all)` of the legends in `Title and
fonts` reach every legend box when they are **set** there; applying the
window for anything else leaves a legend that was given a size or a colour
of its own in its curve window as it is.

### Curve properties

**Click a curve twice** to open it: line, bar, slice, filled area, the
staircase - anything drawn for that column.  A single click grabs the graph
and moves it (see `Moving the whole graph`), so the properties need the
second click, exactly like a text box or a drawing.

At the top of the dialog, a **Plot Style** dropdown selector allows switching the
representation of any individual curve between all 10 styles: **Line +
Symbol**, **Line**, **Scatter**, **Bar Chart**, **Error Bar (Median, SD)**,
**Error Bar (Median, +error, -error)**, **Histogram**, **Stairs**,
**2D Histogram** and **Pie Chart**.  A single curve switched to an error
bar style by hand reads the column after it (or the two columns after it)
for its errors.  The dialog shows exactly
the sections that style can use, and nothing else:

| Style | Sections |
| --- | --- |
| Line + Symbol | Legend, Line, Marker, Fill under the curve |
| Line | Legend, Line, Fill under the curve |
| Scatter | Legend, Marker, Fill under the curve |
| Bar Chart | Legend, Bar properties |
| Error Bar (Median, SD) | Legend, Marker, Line, Error bar properties |
| Error Bar (Median, +error, -error) | Legend, Marker, Line, Error bar properties |
| Histogram | Legend, Histogram properties |
| Stairs | Legend, Stairs properties |
| 2D Histogram | Legend, 2D histogram properties |
| Pie Chart | Legend, Pie properties |

The dialog sections each have **their own check button as the title**: switched
off, that part of the curve is simply not drawn.  The settings that belong
together share a line, and the sections share their column widths so everything
lines up cleanly.  Whatever style is chosen, the **`Close` button stays at the
bottom** of the window, under the sections that come and go with the style.

Changing the style also gives the **axes** to whatever is drawn on them.  A
pie needs no axes, so switching a curve to `Pie Chart` takes the axis labels,
the numbers **and the axis lines** away and keeps the square the circle
needs; switching it back to any other style gives the labels, the numbers,
the frame (whatever style it had - two lines or a closed box) and the
automatic range straight back, so the curve appears again exactly where it
was.  The **values
of the curve are worked out again** at the same time, which matters for the
two styles that read the table differently: a histogram carries the counts of
its bins and a pie reads no X column at all, so a curve leaving either of
them is given its own points back.

* **Legend**: the `Text` of this curve's legend box, then its `Font size`
  with the `Colour` of the text next to it.  An empty text removes the box.
  A **pie** is the one exception: its box has one row per slice, so there is
  no single text to type and the `Text` field is switched off (see
  `Pie properties` below).
* **Line**: `Style` (solid, dashed, dash-dot, dotted), then `Width` with
  the `Colour` of the line next to it.
* **Marker**: `Hollow (no fill)` at the top of the section - an outlined
  marker has no fill colour at all - then `Style` (12 shapes), `Size` with
  `Fill colour` next to it, and `Edge width` with `Edge colour` next to it.
The **legend** of every kind of diagram shows what that diagram really
looks like in front of the text: a line with its marker for a curve, a
**coloured bar** for a bar chart and a histogram, a marker with an
**error bar** through it for an error bar plot, the **staircase** itself for
a stairs plot, one **slice** for a pie and a patch of the **colour scale**
for a 2D histogram.

* **Bar properties** (visible for Bar Charts):
  * `Width`: the width of the bars in X-axis data units.
  * `Opacity (0-1)`: transparency of the bar fill (0.0 transparent, 1.0 opaque).
  * `Edge width`: thickness of the bar outline.
  * `Bar colour` and `Edge colour`: independently selectable colours for the
    bar body and border.
  * `Pattern`: a hatching over the colour - the same choice a filled area
    has, which is what makes bars tell each other apart in a black and
    white print.
  * *Tip:* Clicking any bar directly inside the diagram window opens this dialog.
* **Histogram properties** (the same section, for Histograms): the bars of a
  histogram touch, so there is no width to set - the **number of bins** takes
  its place.
  * `Bins`: how many equal parts the range of the sample is cut into, `20`
    to begin with and anything from 1 to 1000.  Changing it counts the
    column again at once and the range follows the new counts.  Every
    histogram carries its own number of bins, and it is written into the
    `.aplt` file with the rest of the curve.
  * `Opacity (0-1)`, `Edge width`, `Bar colour`, `Edge colour` and
    `Pattern` work exactly as they do for a bar chart (the edges start out
    white, which is what separates bars that touch).
* **Error Bar properties** (visible for Error Bars):
  * `Source`: determines how error bars are calculated:
    * `Next column (x, mean, std)` **(default)**: the column standing right
      after this one holds the length of the error bars - see
      `What the columns mean` above.  On a curve drawn as
      **(Median, +error, -error)** this one source means the **two**
      columns after it: the error upwards and the error downwards.
    * `Percentage`: symmetric error computed as a percentage of the Y value (e.g. ±5%).
    * `Fixed value`: constant symmetric error across all points (e.g. ±0.5).
    * `Standard deviation`: column standard deviation used as uniform error bounds.
    * `From column`: select any other column from the table to specify individual error values for each row.
  * `Value / Column`: sets the percentage or fixed value, or selects the error column.
  * `Cap width`: width of the horizontal end caps.
  * `Line width`: thickness of the error bar stems.
  * `Cap thickness`: how thick the end caps themselves are drawn.
  * `Colour`: colour of the error bars.
  * *Tip:* Clicking on any error bar stem or horizontal cap directly opens this dialog.
  * The bars are read from the **rows of their own curve**.  When a diagram
    holds more than one sheet - a fitted curve beside its measurements, for
    example - the table has rows that belong to the other sheet and are
    empty here; the curve skips them and the bars skip exactly the same
    ones, so fitting a curve through a measurement leaves every one of its
    error bars where it was.
* **Stairs properties** (visible for Stairs):
  * The **place of the step** (a list at the top): midway between two X
    values - every value is valid around its own X - or at the X value
    itself, with the step after it or before it.
  * `Line width` with the `Colour` of the staircase next to it.
  * `Fill it` with `Opacity (0-1)` next to it: a filled staircase keeps a
    crisp outline over a see-through face.
  * `Pattern`: the same choice of hatchings a filled area has.
  * `Close it down to the zero line`: an open staircase is a line and may
    hang in the air; closed, it stands on zero like a bar chart.
  * **Empty cells.**  A step needs a place to stand, so a point whose cell
    in the **X column** is empty is left out and the treads beside it widen
    over it.  An empty cell in the **value** column stays a gap, exactly as
    it breaks any other curve: the staircase - filled or not - is cut there
    instead of dropping to zero.
* **2D histogram properties** (visible for 2D Histograms):
  * `Bins across X` and `Bins up Y`: the grid the pairs are counted into
    (20 x 20 to begin with, up to 500 either way).
  * `Colour scale`: 21 colour maps, from `Viridis` to `Greys`.
  * `Opacity (0-1)` with a `Colour bar` switch next to it.  The colour bar
    is drawn **beside the plot area, in axes of its own**, so it follows the
    frame wherever it is dragged and never takes room away from the diagram.
  * `Leave the empty cells white`: on (the default) a cell with nothing in
    it is not painted at all, so the background stays visible; off, it is
    painted with the lowest colour of the scale.
* **Pie properties** (visible for Pie Charts):
  * `Slice colours`: the colour map the slices are taken from - `Tab10` and
    `Tab20` give distinct colours, the others a smooth scale.
  * `Start angle` (90 degrees is the top) with the `Edge colour` beside it.
  * `Hole (0-0.9)` turns the pie into a **doughnut**, `Edge width` sets the
    line between the slices.
  * `Pull out the first` moves the first slice out of the circle.
  * The two texts of a slice - its **name** and its **number** - form two
    little groups of their own, and **the title of each group is a check
    button**: switched off, that text is not written at all.  A pie with no
    text around it (names off) or a plain pie of bare slices (both off) is
    one click away, and the slices themselves are of course untouched.
  * **The names of the slices** (the texts standing around the pie):
    * A list says **where the names come from**: the text of the first
      column of the table, or the row number.
    * `Distance`: **where they stand**.  `1.0` is the rim of the circle,
      less puts the name on the slice, more beside the pie; they start at
      `1.1`, just outside.
    * `Font size` and `Colour`: their own font, independent of the numbers.
    * `Turn them` lays every name along its own slice instead of standing
      it upright.
  * **The numbers on the slices** (the percentages) have the same:
    * `Distance` (they start at `0.6`, inside the slice), `Font size` and
      `Colour` - white numbers on strong slice colours read best.
    * `Turn them` lays each number along its own slice, which is what makes
      many thin slices readable at all.
    * `Decimals` says how precisely the percentage is written.
  * `Go round anticlockwise` reverses the direction.  Changing the
    direction - or any other setting here - never touches the **names typed
    into the legend rows**; they belong to their slices and stay there.
  * Only **one** column can be a pie, and one pie fills the whole plot
    area: the first ticked column with numbers in it is the one that is
    drawn.  (A pie that stands **beside an ordinary curve** - one curve
    switched to `Pie Chart` while another stays a line - leaves the axes to
    that curve and is drawn as a small circle around the origin instead.)  Empty cells and zeros are not slices, and a negative number is
    taken by its size.  A pie has no axes at all - no numbers, no labels,
    no frame lines - and it stays round whatever the shape of the window.
  * **The circle is as big as the plot area.**  The range of the axes is
    the square the pie needs, so it is drawn as large as any other diagram
    and grows when a slice is pulled out.  A range typed into `Axes
    properties` by hand is never overruled, so the pie can be made smaller
    (or bigger) there if that is wanted.
  * **The legend box starts switched off.**  A pie of five slices in one
    colour with one name says nothing, so there is no box to begin with -
    the names stand beside the slices instead.  Switching the names off and
    the box on moves them from around the pie into the box, which is what a
    crowded pie of thin slices wants.  Switching `Legend` on gives
    a box that lists **every slice** with its own colour and its own name,
    which is the useful form of a legend for a pie.
  * **Every row of that box is a name of its own.**  Because a pie has no
    single legend text, the `Text` field of the `Legend` section is switched
    off for it.  To rename one slice, click its row in the box, wait a
    moment and click it again: a little editor opens **on that row alone**,
    and what is typed there belongs to that slice - beside the pie and in
    the box.  An empty text gives the slice the name the table gives it
    back.  The names that were typed in are written into the `.aplt` file
    and into the exported program with the rest of the curve, and **no other
    setting of the dialog takes them away** - not the direction of the
    slices, not the colour map, nothing.
  * The `Font size` and the `Colour` of the `Legend` section belong to the
    **box**; the font and the colour of the texts standing around the pie
    are set in `Pie properties`, under `The names of the slices`.
  * **A pie is clicked like any other curve.**  It has no line to hit, so
    the slices *and* the names and percentages written on them all open
    `Curve properties` on the **second** click - which is where their font,
    their colour and their distance are.
* **Fill under the curve**: `Same colour as the curve` at the top, then
  `Fill colour` with `Opacity (0-1)` next to it, a **pattern** (diagonal,
  vertical, horizontal, crossed, circles, dots, stars and their dense
  variants), and finally `Fill down to zero line`.
  * That last check button is **off** to begin with: the area is then
    filled all the way down to the axis, and it follows the axis when the
    range is changed.
  * Switched **on**, the area is filled between the curve and the **zero
    line** instead, so positive and negative parts are shown separately.
  * The pattern is drawn in the full colour over the semi-transparent area,
    so both stay visible.  The filled area never changes the automatic
    range of the axis: it is a picture of the curve, not data of its own.
* **Marker colour = line colour** copies the line colour into both marker
  colours.

The line and the marker are independent: a red line with green markers is
perfectly possible.  The legend always mirrors what the curve looks like.

### Axes properties

One window with five tabs: **Title and fonts**, **X axis**, **Left Y
axis**, **Right Y axis** and **Frame and origin**.  All of them are always
there - the right hand page too, even while no curve is drawn against it.

The first page, **Title and fonts**, is exactly the window that
`Plot > Title and fonts...` opens: the title with its font, colour and
distance, and the legend boxes.  Whichever of the two is used, the settings
are the same ones.

#### Direction and Scale

Every axis page begins, just under the tabs, with **two drop-down boxes
side by side** that decide what the axis is at all:

| Direction | What it does |
| --- | --- |
| `No X axis` / `No left Y axis` / `No right Y axis` | That axis is not drawn: no line, no numbers, no label. |
| `Standard` | The usual direction, values growing to the right and upwards. |
| `Reverse` | The axis runs the other way - useful for a wavelength that falls, a depth that grows downwards, an inverted scale. |

| Scale | The spacing of the numbers |
| --- | --- |
| `Linear` | Equal steps (the usual one). |
| `Log 10` | Powers of ten. |
| `Log 2` | Powers of two. |
| `Log (natural)` | Powers of `e`. |

A logarithmic axis cannot reach zero: a range that starts at or below it is
lifted onto the first positive decade.

**A `Log (natural)` axis is read in powers of `e`**: its numbers are
written `e⁰`, `e¹`, `e²` ... rather than 1, 2.718, 7.389, which is what
such an axis is for.  `Log 10` and `Log 2` keep the powers of ten and of
two matplotlib writes for them.

**`Major ticks interval` and `Minor ticks` work there too** - they simply
count in ratios instead of distances.

* **`Major ticks interval`** is how many **powers of the base** lie between
  one major tick and the next, and the line under the box says which base
  that is - `powers of 10`, `powers of 2`, `powers of e`.  On a `Log 10`
  axis `1` gives the usual 1, 10, 100; `2` gives 10⁻⁴, 10⁻², 10⁰ ...;
  `0.5` gives 1, 3.16, 10.  It works with an automatic range as well as
  with one of your own - on a logarithmic axis the spacing of the ticks
  and the range are two separate questions.
* Because a hundred is a sensible interval on a linear axis and an absurd
  one in powers of ten, **each scale keeps its own number**: switching to a
  logarithmic scale offers `1`, switching back brings the linear number
  you had.
* **`Minor ticks`** stand on the **whole numbers** inside the interval -
  2, 3, ... 9 within a decade - because that is what a reader of a
  logarithmic axis looks for.  The number says how many are drawn, and the
  ones kept are those that come nearest to standing at even distances on
  the paper:

  | Between 1 and 10 | The minor ticks |
  | --- | --- |
  | `1` | 3 |
  | `2` | 2 and 5 |
  | `3` | 2, 3 and 6 |
  | `8` | 2, 3, 4, 5, 6, 7, 8, 9 - the whole decade |

  An interval that holds **no whole number** - a `Log 2` axis holds none
  between 1 and 2 - or fewer than were asked for is divided into equal
  parts of the **value** instead: one minor tick is then the half (1.5 on
  a `Log 2` axis), three are the quarters (1.25, 1.5, 1.75).

  As on a linear axis, the minor ticks carry no numbers of their own.

One limit keeps a number typed in haste - or left in an older file, where
the interval meant nothing on a logarithmic axis - from asking the
impossible: an interval **wider than the axis itself** would leave a single
tick or none, so it is read as one power.

The **right hand Y axis** is the one whose Direction says the most:

* while nothing is drawn against it the box reads `No right Y axis`,
* choosing `Standard` or `Reverse` **makes it appear** even with no curve
  of its own - it then simply carries a free scale from **0 to 1**, ready
  for an arrow, a text box or a second reading,
* a curve moved to `y_R` draws that axis whatever the box said, and taking
  the last such curve away lets it disappear again.

#### The three sections of an axis page

Every axis tab has the same three sections, and **the name of each section
is its own check button**:

The three sections share their column widths - the labels **and** the
boxes behind them - so every second setting of a shared line (`To`,
`Minor ticks`, and all three `Colour` boxes) starts at exactly the same
place on the page.

**Axis label and fonts** (switched on)

* the label **text**, then its **font size** with the **Colour** of the
  label next to it on the same line, and `Label offset [px]` - the distance
  from the axis: larger values push the label away from the diagram,
  negative values pull it inwards.
* Switching the section **off** makes the label disappear; the text is
  remembered, so switching it on again brings it back unchanged.

**Tick range, labels and fonts** (switched on)

* the **font size** of the numbers with their **Colour** next to it, and
  `Number offset [px]` (measured from the end of the tick marks).  A new
  diagram starts with the numbers **7** away from the X axis and **5** away
  from the two Y axes - the `X axis numbers distance` and `Y axis numbers
  distance` of the `Fonts` tab of the settings,
* **Automatic range and ticks**, or an explicit range - `From` and `To`
  side by side on one line - and `Major ticks interval` with `Minor ticks`
  (how many minor ones sit between two major ones) on the next line.  On a
  **logarithmic** axis the interval counts powers of the base, and a short
  line under the box says which base; see `Direction and Scale` above,

  **`From` and `To` always say what the axis says.**  While the range is
  automatic the two boxes are a *report*, not a setting: the axis works
  its two ends out from the data, and the boxes are read again whenever
  the diagram changes - new data, a curve carried to the other scale, a
  step of `Undo`, even the zoom and the pan tools of the toolbar, which
  move the ends without going through the program at all.  Each of the
  three pages reports its own axis, so the left and the right Y scale can
  never be mistaken for one another.

  **Switching `Automatic range and ticks` off** hands the two boxes to
  you, starting from the range that is on the screen, and nothing writes
  in them again until you switch it back on.  **Switching it back on**
  puts the range the data gives into them straight away, so the numbers
  standing there are the ones the axis is about to take; the axis itself
  changes when `Apply` or `OK` is pressed.  After every `Apply` the boxes
  are read from the axes once more, so what they show is what was really
  taken - a range that had to be tidied (a logarithmic axis, say) shows
  as it ended up, not as it was asked for.
* **Axis colour** at the end of the section: the colour of *this* axis line
  and of *its* tick marks.  Each of the three axes has its own, so a black
  bottom axis and a red right axis - matching a red curve - are one click
  apart.  It is deliberately not the colour of the numbers: the number
  colour is the row above it, so a black axis can carry grey numbers.
* Switching the section **off** removes the **numbers and both the major
  and the minor tick marks** of that axis.  The axis line itself and the
  label stay.

**Grid of this axis** (switched off)

* the section title itself draws the **major grid lines**; inside it,
  **Minor grid lines** adds the finer ones,
* **Style** with its **Colour** next to it, and the **Width** of the lines.
* The Y grid is drawn by the Y axis whose numbers are shown, so it appears
  once even when both Y axes are in use.

### Frame and origin

The last tab of the axes dialog, also reachable with
`Plot > Frame and origin...`.

**Frame**

* **Style**:
  * `No frame (X and Y only) (default)` - only the sides that carry an axis
    in use are drawn (see `Which frame lines are drawn`),
  * `Full frame` - all four sides, ticks on the bottom and on the left, as
    matplotlib draws it by default,
  * `Frame with ticks (inward)` - all four sides with ticks on every side,
    pointing into the diagram,
  * `Frame with ticks (outward)` - all four sides with ticks on every side,
    pointing outwards.
* **Thickness** of the frame lines; the tick marks follow it.
* The **colour** is not here: every axis paints its own line and its own
  tick marks with the `Axis colour` of its page (see `Axes properties`).
  In a full frame the two horizontal sides take the colour of the X axis,
  the left side that of the left Y axis and the right side that of the
  right Y axis.
* **Major tick length** and **Minor tick length** in points.  Zero hides
  that kind of tick mark.

**Background**

* **Plot area**: the colour behind the curves, or **Transparent plot area**
  to let the colour around the axes show through.
* **Around the axes**: the colour of the paper the graph sits on, or
  **Transparent around the axes** to leave it away altogether.  This one
  is **ticked to begin with**, so a copied or saved picture drops onto a
  slide or a page with nothing around the graph; untick it (here or in the
  `Frame` tab of the settings, for every new diagram) to get the white
  paper back.

Both switches travel into the picture: with the second one ticked, a copied
or saved **PNG, PDF or SVG has no background at all**, so the graph can be
dropped onto a coloured slide or a printed page without a white box around
it.  (JPEG has no transparency of its own and fills it with white.)  The
starting state of both comes from the `Frame` tab of the settings, so every
new diagram can begin transparent if that is what you want.

Clicking any side of the frame on the diagram (the X axis line, the Y axis
line, or the top and right sides when they are drawn) opens this dialog;
the pointer becomes a hand over the frame.

### The menu bar of the diagram window

A diagram window carries the same menu bar as the spreadsheet window
(`APlot`, `File`, `Edit`, `Plot`, `Help`), so files can be opened and saved
and the settings and the documentation can be reached without going back to
the main window.  The `Edit` menu acts on the window it was opened from, so
the very same `Cut`, `Copy`, `Paste` and `Duplicate` work on the selected
object here and on the block of cells there (section 3).  This matters on macOS, where the menu bar always belongs to
the window that has the focus.  In a diagram window the `Plot` menu holds
the commands of that diagram after a separator: `Axes properties...`,
`Frame and origin...`, `Title and fonts...` and `Close this diagram`.

**Size and origin of the axes**

* **Units**: `Fraction of page`, `cm` or `inch`.  Fractions are what is
  really stored; the centimetre and inch values are worked out from the
  size of the page, and the line under the fields always shows the present
  size in centimetres.
* **Width (length of the X axis)** and **Height (length of the Y axis)**.
* **Y axis distance from the left** and **X axis distance from the bottom**
  - the position of the origin inside the window.
* **Default layout** puts back the place a new diagram starts at (the one
  in the `Frame` tab of the settings): unless it was changed there, an X
  axis `0.32` and a Y axis `0.30` of the page long, standing `0.35` from
  the left and `0.35` from the bottom.  It moves and resizes the plot area
  only: unlike `Resize graph`, it leaves the fonts and the line widths
  alone.  To fill the page, use `Resize graph > Fit to page`.

**The page follows the diagram.**  This window holds a copy of everything
it shows - the frame, the two background colours and the four numbers of
the size - and that copy is what `Apply` sends back.  So whenever the
diagram changes while the window stands open (`Resize graph`, an axis
pulled by its end, the graph dragged about, a step of `Undo`, a file
opened), the page reads the diagram again.  Changing only a colour
afterwards therefore changes only that colour: it can no longer drag the
graph back to a size it had a minute ago.

The four numbers are the same values as `left`, `bottom`, `width` and
`height` of a matplotlib axes, so `left + width` and `bottom + height` must
stay inside the window; the dialog says so if they do not.

`Apply` applies all three tabs, `OK` applies them and closes the window.

### Title and fonts

Every text around the diagram has a **distance** in pixels next to its font
size and colour: the title from the top of the plot area, the axis labels
from their axis, and the axis numbers from the end of the tick marks.  The
values are converted to the units matplotlib works in with the resolution
of the figure, so a distance of 10 px really is ten pixels on the screen.

Font **size**, font **colour** and **distance** can be set in three places,
always together:

* the **title**: click it on the diagram, use
  `Plot > Title and fonts...`, or open the **first tab of the axes
  dialog** - the same page under another roof,
* the **axis labels** and the **axis numbers**: click the label (label text,
  size and colour), or use the matching tab of the axes dialog (label and
  numbers, size and colour),
* the **legend boxes**: click the text of a box for that box alone, the
  curve properties dialog for the same box, or
  `Plot > Title and fonts...` for all of them at once (legend boxes have no
  distance: they are placed by dragging them).

`Plot > Title and fonts...` also switches the legend boxes on and off,
chooses the corner where they start, and puts them back into a stack.

The starting colours of all four (title, axis labels, axis numbers, legend)
come from the `Fonts` tab of the settings.


## 3. Taking a step back

Every command that changes something can be taken back, in the sheet and in
the diagram alike.  The `Edit` menu is the same in both windows and always
works on the window it was opened from.

| Menu item | Key | What it does |
| --- | --- | --- |
| Undo | `Cmd/Ctrl+Z` | Takes back the last change - a cell that was written, a drawing that was added, an object that was moved, a whole block that was pasted. |
| Redo | `Shift+Cmd/Ctrl+Z` | Does it again. |
| Cut | `Cmd/Ctrl+X` | The selected object of the diagram, or the highlighted block of cells, goes to the clipboard and away. |
| Copy | `Cmd/Ctrl+C` | The same, without removing anything.  With **nothing** selected in a diagram this copies a picture of the whole diagram. |
| Paste | `Cmd/Ctrl+V` | Puts back what was copied. |
| Duplicate | `Cmd/Ctrl+D` | A second copy at once: in the diagram a little to the lower right of the original, in the sheet in the rows just under the block.  The clipboard is left alone. |

**The line says what it will take back.**  With something on the list the
first line of the menu reads `Undo the drawing`, `Undo the sheet`,
`Undo pasting` and so on, so it is clear beforehand what is about to
happen.  With nothing on the list both lines are grey.

**One command, one step.**  Pasting an object, duplicating it or bringing
it to the front is a single step even though the program does several
things for it, so one `Undo` puts everything back as it was.  Pressing
`Apply` or `OK` in `Axes properties` is one step too, however many pages
of it were changed at once - `Undo the axes and the frame` puts the whole
window back - and so is `Apply` in `Title and fonts`.  The last 60 steps
are kept; opening a file starts a fresh, empty list, because the file
itself is the state to go back to.

**What a step remembers.**  A change in a sheet remembers that sheet - its
values, its formulas and its column names; a change in a diagram remembers
that diagram - every curve, axis, drawing, text box and arrow with all of
its properties.  Objects keep their names through `Undo` and `Redo`, so
whatever was selected is still the same object afterwards.

**A cell that is open keeps the keys for its text.**  While a cell or a
text box is being written in, `Cmd/Ctrl+C`, `Cmd/Ctrl+V` and `Cmd/Ctrl+X`
belong to the characters of that text, exactly as everywhere else.


## 4. Files

| Menu item | Key | What it does |
| --- | --- | --- |
| Open graph (.aplt) | `Cmd/Ctrl+O` | Loads a complete APlot document: the data and the diagrams.  This is the **folder button** of the toolbar. |
| Save graph (.aplt) | `Cmd/Ctrl+S` | Saves the data together with every diagram that is open.  This is the **disc button** of the toolbar. |
| Save graph as... | | The same, always asking for a new name. |
| Import data (CSV, TXT, DAT)... | `Cmd/Ctrl+I` | Reads a text data file into the sheet; the separator is recognised automatically.  This is the **arrow button** of the toolbar. |
| Export data (CSV, TXT, DAT)... | `Shift+Cmd/Ctrl+S` | Writes the sheet into a text data file (`.csv`, `.txt`, `.dat`). |
| Export figure (image)... | `Cmd/Ctrl+E` | Writes the graph as a picture (PNG, PDF, SVG, ...), cut out of the page. |
| Export as matplotlib script... | `Shift+Cmd/Ctrl+E` | Writes the diagram as a Python program. |
| Copy figure to the clipboard | `Cmd/Ctrl+C` | Puts a picture of the diagram on the clipboard. |

**Saving with one key.**  `Cmd/Ctrl+S` asks for a name only the **first**
time.  From then on the graph belongs to that file: every further
`Cmd/Ctrl+S` simply brings it up to date, with no dialog and no message,
and the name of the file is shown in the title bar of the table window.
`Save graph as...` asks for a new name whenever it is needed.

**Nothing is lost by accident.**  The program knows whether anything has
been changed since the last save (moving or resizing a window does not
count).  If it has, then closing the diagram or leaving the program asks
first:

> This graph has been edited and not saved.  Save it now?

`Yes` saves it (asking for a name if the graph is new), `No` throws the
changes away, `Cancel` leaves everything as it is.  With several diagrams
open, closing one of them does not ask - only the **last** one carries the
whole graph.

**Every way out asks the same question**: the close button of the window,
`Quit` in the menu, and **`Cmd/Ctrl+Q`** - from the spreadsheet window and
from a diagram window alike.  On a Mac, `Cmd+Q` and `Quit APlot` in the
apple menu are one and the same Apple event, and the program takes it over
so that it can ask; `Cancel` there simply leaves the program running.

**Opening a file never asks.**  `Open graph`, `Import data` and the
random data of the `Data` menu simply replace what is on the screen: the
question about unsaved work belongs to **leaving** the program (and to
closing the last diagram), where something really can be lost.

**Closing a window is not an edit.**  A graph that is in step with its file
stays in step when its diagram window is closed, so closing the diagram and
then the spreadsheet does not ask twice - and does not ask at all when
nothing was changed since the last save.

### Exporting the diagram

* **Export figure (image)...** (`Cmd/Ctrl+E`) is the same as the save
  button of the toolbar: a picture in any format matplotlib can write, and
  the control points of a selected object are never on it.  What is written
  is the **graph, not the whole page** - the page is cut down to what is
  drawn on it, with a little air around that, exactly as `Copy figure to
  the clipboard` does, so the two ways out of the program give the same
  picture.  The **zoom of the view** never reaches the file either: a
  picture is always of the page at the resolution the settings give it.
* **Copy figure to the clipboard** (`Cmd/Ctrl+C` in the diagram window,
  with nothing selected) puts a 200 dpi picture on the clipboard, ready to
  be pasted into a text editor, a presentation or an e-mail.  Tick
  **`Transparent around the axes`** in `Frame and origin` and that picture
  has **no background at all** - it drops onto a coloured slide without a
  white box around it.  Both switches of that section are carried into the
  picture: the plot area and the paper around it, each on its own.  With an
  object **selected**, the same key copies that object instead, as before -
  so both uses of `Cmd/Ctrl+C` live side by side.  If the system has no
  tool for pictures on the clipboard, the program says where it wrote the
  file instead.
* **Export as matplotlib script...** (`Shift+Cmd/Ctrl+E`) writes a
  **stand-alone Python program** that draws the very same diagram.  It
  needs nothing but numpy and matplotlib: the data is written into the file
  as plain lists, and so is everything else - the two or three axes with
  their ranges, ticks, colours and grids, the frame, every curve with its
  style and its filled area, the legend boxes at their places, the title
  with its dragged position, the text boxes, the drawings and the arrows.
  Run it with `python3 diagram.py`, change a number, and it is a diagram of
  your own; the last line is a commented-out `savefig` for a batch run.

An `.aplt` file is a **ZIP container**, the way the files of an office
suite are.  Renamed to `.zip` it opens in any archive program, and inside
there are four entries:

| Entry | What it is |
| --- | --- |
| `mimetype` | The words `application/x-aplot`.  It is the very first entry and is stored uncompressed, so a program can tell what the file is from its first bytes. |
| `document.json` | The data and every diagram: a readable JSON document (described below). |
| `Thumbnails/thumbnail.png` | A picture of the **first** diagram, about 2048 pixels along its longer side, for the file managers (and for anyone who opens the container).  It is stored uncompressed, so a viewer can read it without unpacking anything. |
| `Thumbnails/preview.pdf` | **Every** diagram of the graph, one page each, in the order of the windows: what the Space bar shows on a Mac and in GNOME Files, and `Preview all graphs` on Linux.  It is stored uncompressed too. |

**The picture** shows the first diagram of the file - the first one
opened, and the first page of the PDF - whichever window happens to be in
front when the graph is saved, so the icon of a file does not change by
itself.  It is cut out of the page with a little air around it, exactly as
`Copy figure` does.  Its paper is the colour chosen `Around the axes` in `Frame and
origin`, or **white** when that is transparent: a file manager draws the
picture on its own background, light or dark, so it is never transparent.
The selection marks are never on it.  A graph saved with no diagram open
has no picture; a picture that cannot be drawn for any reason leaves the
data and the diagrams saved all the same.

**The PDF** has one page for each diagram, cut out and coloured the same
way.  Its pages stay drawings - lines and letters, not pixels - so they
are sharp at any zoom, and a diagram is usually only some 20-60 KB of
it.  A diagram that cannot be drawn is left out of it, and the rest are
still there.

The picture is what a file manager needs to show the graph instead of a
blank page.  The file managers do not look into an unknown container by
themselves: a small viewer extension on macOS (the `APlotQuickLook`
folder, see `The picture of the graph in the Finder`), a thumbnailer entry
on Linux (`python3 aplot.py --install-desktop`, see `The graph files on a
Linux desktop`) or a thumbnail handler on Windows has to be installed, and each of
them only has to copy this one picture out.  It is drawn 2048 pixels
along its longer side: the Space bar preview shows it 1024 points wide -
far larger than an icon - and it is still sharp there on a Retina screen.
That makes a graph file some 200 KB larger than its data alone (and the
PDF a few tens of KB for each diagram), and saving takes a fraction of a
second longer.

The file is written next to its final place and only then put there, so a
save that fails half way never leaves a broken graph behind.

**Older files** - every `.aplt` written before the container came in is a
plain JSON file - open exactly as before.  Saving such a graph again
writes the new kind.  A file that is neither is refused with a message.

Besides the table, `document.json` stores for each open diagram:

* the curves with their colour, line style and width, marker type, size,
  fill and edge colour, edge width, visibility, legend text, the position,
  corner, font, frame and background of their own legend box, and the
  settings of the filled area under the curve,
* the title with its font size, colour and distance, the dragged positions
  of the title and of both axis labels, and the visibility, starting
  corner, default font size and colour of the legend boxes,
* both axes: label, the size, colour and distance of the label and of the
  numbers, automatic or fixed range, step, number of minor ticks, and the
  grid settings of the axis,
* the frame: style, thickness, colour, major and minor tick length, the
  background of the plot area and of the window, and the size and origin of
  the axes inside the window,
* every text box with its text, position, angle, font, frame and background,
* every drawn object with its shape, position, size, angle, line and fill,
* every arrow with its head type and size, tip, tail, line and colour,
* the figure size, resolution and the window geometry.

Loading an `.aplt` file replaces the table and closes the diagrams that are
open, then reopens the saved ones exactly as they were saved.

### Data files with any separator

`Import data` reads `.csv`, `.txt`, `.dat`, `.tsv` and `.asc` files (and
anything else, with `All files`).  Nothing has to be prepared by hand:

* the **separator** is recognised from the first lines of the file, in this
  order: tabulator, semicolon, `|`, comma, then one or more spaces.  It is
  accepted when it gives the same number of values in most of the lines, so
  a `;` separated file lands in as many columns as it has values;
* the **decimal sign** is recognised too: numbers written as `1,5` (with no
  dotted numbers in the file) are read as decimal comma, and then the comma
  is never taken for a separator;
* **comment and header lines** at the top starting with `#`, `%`, `!` or
  `//` are skipped, and empty lines are ignored everywhere;
* the **column names** come from the first line when it is not numeric;
  otherwise the columns are named `X`, `Y1`, `Y2`, ... automatically;
* **UTF-8** and Latin-1 files are both read, and a line with a wrong number
  of values is left out with a warning instead of stopping the reading.

The title bar of the spreadsheet window shows the file name together with
what was recognised, for example
`APlot - Meas057_Acquisition_Spectrum.csv  [semicolon separated, decimal
'.', 1296 rows x 3 columns]`.

If a file is unusual, the recognition can be overridden in the settings:
`Field separator` accepts `auto`, `comma`, `semicolon`, `tab`, `space` or
`|`, and `Decimal sign` accepts `auto`, `.` or `,`.  These settings are also
used when a data file is written.


## 5. Settings

`Settings...` on the toolbar, in the `APlot` menu, or `Cmd+,` in the
application menu on macOS.  The values are written to

    ~/.aplot/config.json

and are read again at every start.  `Restore defaults` puts back the
built-in values.

Settings that belong together stand **side by side on one line** - the width
and the height of the figure, the style and the width of the line, the size
and the edge width of the marker, the colour and the opacity of the fill -
and the boxes are only as wide as what goes into them: a number needs far
less room than a title.

| Tab | Contents |
| --- | --- |
| Windows | Start size of the main window and of the diagram windows, and whether the property windows stay above the diagram. |
| Spreadsheet | Number of rows and column names at start, column width, font size, automatic row adding. |
| Plot | **Page size** (the size of the diagram itself - see `The page`) and resolution, the title pattern (`{x}` is the name of the X column), default Y label, default line style and width, default marker, size and edge width, hollow markers, legend visibility, starting corner, frame and background of the legend boxes, and the default fill under the curves (colour, opacity, pattern, baseline). |
| Fonts | **The font of the diagrams** (first line), then the size and colour of the title, the axis labels, the axis numbers and the legend boxes, and the starting distance (in pixels) of the title, the axis labels and the axis numbers. |
| Grid | Default grid: major and minor lines, colour, style, width, number of minor ticks. |
| Frame | Default frame style, thickness, colour, tick lengths, background colours, and the default size and origin of the axes (as fractions of the page). |
| Text boxes | Font size and colour, frame and background of the text boxes added with the **T** button. |
| Drawings | The shape the drawing tool starts with, and the line style, thickness, colour, fill colour and opacity of new objects. |
| Arrows | The head type the arrow tool starts with, the head size in pixels, and the line style, thickness and colour of new arrows. |
| Data files | Field separator and decimal sign of text data files (`auto` recognises them). |

Window sizes and plot defaults are used by windows opened after saving;
diagrams that are already open keep their settings.

### The font of the diagrams

The first line of the `Fonts` tab is a list of **every font this computer
has**.  Whatever is chosen there is used for the whole diagram - the title,
the axis labels, the numbers on the axes, the legend boxes, the text boxes,
the names on a pie - and, unlike the other settings, it reaches the diagrams
that are **already open** as well, so the effect can be seen at once.

* The starting value is the font the program was drawing with anyway
  (`DejaVu Sans`, which comes with matplotlib), so nothing changes until
  another one is chosen.
* The font is written into the `.aplt` file with the rest of the diagram,
  so a graph opens with the font it was saved with even on a computer whose
  setting says something else.
* The **exported matplotlib program** sets the same font in its first lines,
  so the picture it draws matches the one on the screen.
* A font that this computer does not have is quietly ignored and the usual
  one is kept.


## 6. Typical workflow

1. `Random data` (File menu), `Import data` or type the numbers by hand.
   Untick the columns that should not be drawn.
2. Rename the columns by clicking their headings - these names become the
   legend texts and the X axis label.
3. `Plot`.
4. Click the curves, and click the labels and the axes twice, until the
   diagram looks right,
   and drag the legend boxes where they do not cover the data.  Add text
   boxes, drawings and arrows to point out what matters - style one of them
   and copy it (`Ctrl/Cmd+C`, `Ctrl/Cmd+V`) instead of building the next
   one from the beginning.
5. Correct or extend the data in the table and press `Update plot`; the
   diagram keeps its appearance and only the values change.  Emptying a
   block of cells (select it, `Delete`) breaks the curves there, so a
   measurement can be shown in separate pieces.
6. `Save graph (.aplt)` to be able to continue later, or the save button of
   the Matplotlib toolbar to export a PNG/PDF image.


## 7. Notes

* On macOS the first (bold) menu is named after the running program.  APlot
  renames it to "APlot" through the Cocoa bundle information, which needs
  pyobjc: `pip install pyobjc-framework-Cocoa`.  Without it the menu keeps
  the name of the Python interpreter; everything else works the same way.
* Every empty cell (or a cell that is not a number) breaks the curve at
  that point - an empty Y cell, an empty X cell and an empty row alike.
  The points on the two sides of the gap are never connected.
* A curve whose line style AND marker are both "None" is invisible and can
  no longer be clicked; reach it again through its legend box.
* The keyboard follows the click: the diagram takes it on every click in
  the plot area (this is done by Tk itself, not through matplotlib's event
  loop, so it is not lost when a property window has been used), and a
  property window gives it back to the diagram when it is closed.
* A curve whose properties are needed is clicked once; everything else
  needs two clicks, because the first one selects it.  This is what makes
  moving, copying and the arrow keys possible on all of those objects.
* The three tools of the toolbar (**T**, the shape and the arrow button)
  are exclusive: arming one cancels the others, and `Esc` cancels all of
  them.
* A legend box can be dragged outside the axes area (for example beside the
  diagram); `Reset positions` brings every box back.
"""


def load_documentation():
    """The README next to the program if it exists, otherwise the built-in text."""
    try:
        readme = Path(__file__).with_name("README.md")
        if readme.is_file():
            return readme.read_text(encoding="utf-8")
    except (OSError, NameError):
        pass
    return DOCUMENTATION


class HelpWindow(tk.Toplevel):
    """Read-only documentation viewer."""

    def __init__(self, master, text):
        super().__init__(master)
        self.title(f"{APP_NAME} documentation")
        self.geometry("820x640")
        frame = ttk.Frame(self, padding=8)
        frame.pack(fill="both", expand=True)

        widget = tk.Text(frame, wrap="word", padx=12, pady=10,
                         font=("TkFixedFont", 11), borderwidth=0)
        scroll = ttk.Scrollbar(frame, orient="vertical", command=widget.yview)
        widget.configure(yscrollcommand=scroll.set)
        scroll.pack(side="right", fill="y")
        widget.pack(side="left", fill="both", expand=True)

        widget.insert("1.0", text)
        widget.configure(state="disabled")
        self.text = widget

        ttk.Button(self, text="Close", command=self.destroy).pack(pady=(0, 8))
        self.bind("<Escape>", lambda _e: self.destroy())


# --------------------------------------------------------------------------
# main application
# --------------------------------------------------------------------------

class App:
    def __init__(self, root, config: Config | None = None):
        self.root = root
        self.settings = config or Config()
        self.root.title(f"{APP_NAME} - Data Visualizer")
        self.root.geometry(f"{self.settings.get('window', 'main_width')}x"
                           f"{self.settings.get('window', 'main_height')}")
        self.root.wm_iconname(APP_NAME)
        # the drawn icon: the Dock on a Mac, the task bar elsewhere, and
        # every window this one opens later
        apply_app_icon(self.root)
        self.plot_windows: list[PlotWindow] = []
        # every change worth taking back again, newest last
        self.undo = UndoStack()
        self._edit_menus = []           # the Edit menus of every window
        self._help_window = None
        # the .aplt file this graph belongs to, and how it looked when it was
        # last written: everything else is "edited but not saved"
        self.project_path = None
        self._saved_signature = None
        self._just_saved = False        # the last question ended in a save
        self._was_saved = False         # ... or nothing had been edited at all

        self._build_toolbar()
        
        # the notebook holds the sheets; its own tabs are not drawn - the
        # row under it (`SheetTabBar`) is, because that one can scroll
        style = ttk.Style()
        style.configure('Sheets.TNotebook', tabposition='sw', tabmargins=0)
        style.layout('Sheets.TNotebook.Tab', [])
        self.tab_bar = None
        self.notebook = SheetNotebook(self.root, style='Sheets.TNotebook',
                                      on_tabs=self._tabs_changed)
        self.tab_bar = SheetTabBar(
            self.root, self.notebook, names=self.tab_names,
            colors=self.tab_color,
            handlers={"click": self._on_tab_click,
                      "double": self._on_tab_double_click,
                      "menu": self._show_tab_context_menu,
                      "move": lambda places: self.move_tab(*places),
                      "plus": lambda _e=None: self.add_sheet()})
        self.tab_bar.pack(side="bottom", fill="x", padx=10, pady=(0, 8))
        self.notebook.pack(fill="both", expand=True, padx=10, pady=(0, 0))
        
        self.tables = []
        self.tab_images = {}
        
        self._tab_editor = None         # the little box that writes a name
        self._tab_click = None          # the tab of the click before this one
        self.notebook.bind("<<NotebookTabChanged>>", self._on_tab_changed)

        # the "+" of the row of tabs stands for this empty page: choosing it
        # makes a new sheet (see `_on_tab_changed`)
        self.plus_frame = ttk.Frame(self.notebook)
        self.notebook.add(self.plus_frame, text=" + ")
        self.tab_bar.plus_frame = self.plus_frame
        
        self.add_tab("Data 1", blank=True)
        self.notebook.select(0)

        self._build_menu()
        use_font_family(self.settings.get("fonts", "family"))
        self.root.protocol("WM_DELETE_WINDOW", self.quit_app)
        # coming back to the window: the sheet takes the keyboard again
        for sequence in ("<FocusIn>", "<Activate>"):
            try:
                self.root.bind(sequence, self._window_came_back, add="+")
            except tk.TclError:
                pass
        # ...and a key that lands nowhere is handed to the sheet
        self.root.bind("<Key>", self._stray_key, add="+")
        self._saved_signature = self.project_signature()
        self.root.after_idle(self._focus)
        # macOS calls a plain script after its interpreter: asked once,
        # the program can build the little bundle that carries its own name
        self.root.after(600, self._offer_app_bundle)

    # -- helpers -----------------------------------------------------------
    def _empty_frame(self):
        rows = max(1, int(self.settings.get("table", "rows")))
        columns = [name.strip() for name
                   in str(self.settings.get("table", "columns")).split(",")
                   if name.strip()] or ["X", "Y1"]
        return pd.DataFrame({col: [""] * rows for col in columns})

    @property
    def df(self):
        if not self.table:
            return pd.DataFrame()
        return self.table.df

    @property
    def active_tab_index(self):
        try:
            return self.notebook.index("current")
        except tk.TclError:
            return 0
            
    @property
    def table(self):
        idx = self.active_tab_index
        if idx < len(self.tables):
            return self.tables[idx]
        return self.tables[0] if self.tables else None

    def use_tabs(self, count):
        """Have exactly `count` sheets, using the ones that are open.

        A sheet that is there already is emptied and filled again rather
        than destroyed and built anew, so nothing that holds on to it is
        left pointing at a widget that no longer exists.
        """
        count = max(1, int(count))
        while len(self.tables) > count:
            table = self.tables.pop()
            self.tab_images.pop(str(table.master), None)
            self.notebook.forget(table.master)
            table.master.destroy()
        while len(self.tables) < count:
            self.add_tab(f"Data {len(self.tables) + 1}")
        for index, table in enumerate(self.tables):   # a clean sheet to fill
            table.plot_with_previous_var.set(False)
            table.cell_formulas = {}
            self.set_tab_color(index, None)
        return self.tables

    def add_tab(self, name, blank=False, at=None):
        """A new sheet, at the end or (with `at`) in the middle."""
        frame = ttk.Frame(self.notebook)
        table = DataTable(frame, self.settings,
                          on_change=lambda one=None: self._table_changed(table),
                          on_rename=lambda old, new, index: self._column_renamed(
                              old, new, index, table=table),
                          on_add_column=self.add_column,
                          on_delete_column=self.delete_column)
        table.pack(fill="both", expand=True)
        if blank:
            table.set_dataframe(self._empty_frame(), check_all=True, blank=True)

        last = len(self.tables) if at is None else max(0, min(int(at),
                                                             len(self.tables)))
        # a sheet slipped in before a diagram's own sheet moves that sheet
        # one place on: the diagram has to be told
        for window in self.open_windows():
            where = getattr(window, "source_tab", None)
            if where is not None and int(where) >= last:
                window.source_tab = int(where) + 1
        self.tables.insert(last, table)
        table._undo_document = None     # filled in as soon as it has data
        if hasattr(self, "plus_frame") and str(self.plus_frame) in self.notebook.tabs():
            end = self.notebook.index(self.plus_frame)
            self.notebook.insert(min(last, end), frame, text=name)
        else:
            self.notebook.insert(min(last, len(self.notebook.tabs())),
                                 frame, text=name)
        return table

    def tab_names(self):
        return [str(self.notebook.tab(index, "text"))
                for index in range(len(self.tables))]

    def free_tab_name(self, stem):
        """`stem`, `stem 2`, `stem 3`... - whatever is not taken yet."""
        taken = set(self.tab_names())
        if stem not in taken:
            return stem
        number = 2
        while f"{stem} {number}" in taken:
            number += 1
        return f"{stem} {number}"

    def add_fit_tab(self, frame, quiet_columns=(), plot=True, name=None):
        """The answer of a regression: a sheet of its own after this one.

        It goes right after the sheet it was fitted to, with "Plot with
        previous tab" ticked, so the curve and the measurements stand in
        the same diagram.  The columns holding the parameters are not data
        to draw: their two check buttons are switched off.
        """
        source = self.active_tab_index
        title = name or self.free_tab_name(FIT_TAB_PREFIX)
        table = self.add_tab(title, at=source + 1)
        table.set_dataframe(frame, check_all=True)
        for column in quiet_columns:
            table.set_column_axis(column, None)
        table.plot_with_previous_var.set(True)
        self.notebook.select(source + 1)
        self._follow_active_tab()
        if plot:
            # the new sheet is glued to the one that was fitted, so the
            # diagrams of that sheet now draw the fitted curve as well -
            # this is the one case where the drawing is brought up to date
            # by itself, without the Update button
            if self.open_windows():
                self.update_plot()
            else:
                self.open_plot(self.current_plot_style)
            # a fitted curve is a smooth line of a hundred points: markers
            # on every one of them would hide the measurements behind it
            quiet = set(str(one) for one in quiet_columns)
            drawn = [str(one) for one in frame.columns][1:]
            names = [one for one in drawn if one not in quiet]
            names += [f"{one} ({title})" for one in names]
            # ...only in the diagrams that draw this group of sheets: a
            # diagram of another sheet may well have a column of that name
            for window in self.open_windows():
                if source + 1 in self.tab_chain(self.window_tab(window)):
                    window.draw_as_smooth_line(names)
        return table

    def open_regression(self, *_args):
        """The regression window of the sheet in front."""
        window = getattr(self, "_regression", None)
        if window is not None:
            try:
                if window.winfo_exists():
                    window.refresh_columns()
                    window.lift()
                    window.focus_force()
                    return window
            except tk.TclError:
                pass
        self._regression = RegressionDialog(
            self.root, self,
            on_close=lambda _d=None: setattr(self, "_regression", None))
        return self._regression

    def _on_tab_changed(self, event):
        idx = self.notebook.index("current")
        if hasattr(self, "plus_frame") and idx == self.notebook.index(self.plus_frame):
            name = f"Data {len(self.tables) + 1}"
            self.add_tab(name, blank=True)
            self.notebook.select(len(self.tables) - 1)
            idx = len(self.tables) - 1
            
        self._follow_active_tab()
        # the sheet that came to the front is the one the keyboard writes on
        self.root.after_idle(self.focus_sheet)
        window = getattr(self, "_regression", None)
        if window is not None:
            try:
                if window.winfo_exists():
                    window.refresh_columns()
            except tk.TclError:
                self._regression = None

    def _follow_active_tab(self):
        """Point the check button of the toolbar at the sheet in front."""
        box = getattr(self, "plot_with_previous_cb", None)
        if box is None or not hasattr(self, "notebook"):
            return False               # the toolbar is built first
        idx = self.active_tab_index
        if not (0 <= idx < len(self.tables)):
            return False
        box.configure(variable=self.tables[idx].plot_with_previous_var,
                      state=("disabled" if idx == 0 else "normal"))
        return True

    def _plot_with_previous_changed(self):
        """Ticking it only says what the next drawing will look like.

        The diagrams that are open are deliberately left as they are: the
        box decides what `Update` will send them and what `Plot` will put
        into a new window, and nothing is redrawn until one of those two
        buttons is pressed.
        """
        self._follow_active_tab()
        return True

    def _tabs_changed(self):
        """A tab came, went, was renamed or coloured: draw the row again."""
        bar = getattr(self, "tab_bar", None)
        if bar is not None:
            bar.refresh()

    def add_sheet(self):
        """The `+` of the row of tabs: a new, empty sheet at the end."""
        self.notebook.select(self.plus_frame)   # see `_on_tab_changed`
        return self.table

    def _show_tab_context_menu(self, event):
        idx = self._tab_at(event.x, event.y)
        if idx is None:
            return
        if hasattr(self, "plus_frame") and idx == self.notebook.index(self.plus_frame):
            return # Don't show menu for the "+" tab
            
        menu = tk.Menu(self.root, tearoff=0)
        menu.add_command(label="Rename tab", command=lambda: self.rename_tab(idx))
        menu.add_command(label="Tab colour", command=lambda: self.color_tab(idx))
        menu.add_command(label="Duplicate tab",
                         command=lambda: self.duplicate_tab(idx))
        menu.add_command(label="Delete tab", command=lambda: self.delete_tab(idx))
        menu.tk_popup(event.x_root, event.y_root)

    def tab_group_end(self, index):
        """The last sheet of the run glued (`Plot with previous tab`) after
        the sheet at `index` - `index` itself when nothing is glued to it."""
        last = int(index)
        while self.tab_ticked(last + 1):
            last += 1
        return last

    def move_tab(self, source, target, record=True):
        """Put the sheet at `source` to the place `target` in the row of tabs.

        `target` is the place it gets among the other tabs (0 = first).
        Everything that knows a sheet by its place follows it: the diagrams
        (each keeps drawing its own sheet), the steps that Undo can take
        back, the sheet in front.

        The sheets glued to it with `Plot with previous tab` - a fitted
        curve, say - **go with it**, as one block: they belong to its
        diagram, and left behind they would be glued to whichever sheet
        happened to come before them then.  For the same reason a sheet is
        never put between another one and the sheets glued to that one: it
        goes after the whole group.  A glued sheet dragged by itself moves
        alone and joins the sheets it is dropped at.  The move is one step
        that Undo takes back.
        """
        count = len(self.tables)
        try:
            source, target = int(source), int(target)
        except (TypeError, ValueError):
            return False
        if not (0 <= source < count and 0 <= target < count) or source == target:
            return False
        head = not self.tab_ticked(source)
        last = self.tab_group_end(source) if head else source
        block = list(range(source, last + 1))
        rest = [one for one in range(count) if one not in block]
        followers = len(block) - 1
        # `target` counts the tabs without the dragged one; its own glued
        # sheets stand right after it in that count
        if target <= source:
            place = target
        elif target >= source + followers:
            place = target - followers
        else:
            return False                  # dropped inside its own group
        if head:                          # not between a sheet and its fits
            while place < len(rest) and self.tab_ticked(rest[place]):
                place += 1
        order = rest[:place] + block + rest[place:]
        if order == list(range(count)):
            return False
        return self._apply_tab_order(order, record=record,
                                     front=order.index(source))

    def _apply_tab_order(self, order, record=True, front=None,
                         label="moving the tab"):
        """Put the sheets into the order `order` (their old places)."""
        count = len(self.tables)
        if sorted(order) != list(range(count)):
            return False
        self.cancel_tab_rename()
        for table in self.tables:
            table._commit_edit()
        new_place = {old: new for new, old in enumerate(order)}
        tables = [self.tables[old] for old in order]
        self.tables[:] = tables
        for place, table in enumerate(tables):
            self.notebook.insert(place, table.master)   # the tabs move along
        for window in self.open_windows():
            where = getattr(window, "source_tab", None)
            if where is not None and int(where) in new_place:
                window.source_tab = new_place[int(where)]
        self._remap_sheet_steps(new_place)
        if front is not None:
            self.notebook.select(int(front))
        self._follow_active_tab()
        if record and not self.undo.busy():
            back = [new_place[old] for old in range(count)]
            # undone, the sheet in front goes back to where it came from
            before = {"order": back,
                      "front": order[front] if front is not None else None}
            after = {"order": list(order), "front": front}
            self.undo.push(UndoStep(
                label, before, after,
                lambda step: self._apply_tab_order(step["order"], record=False,
                                                   front=step["front"])))
            self.refresh_edit_menus()
        self._tabs_changed()
        self.root.after_idle(self.focus_sheet)
        return True

    def _remap_sheet_steps(self, new_place):
        """The steps of Undo that know a sheet by its place follow a move."""
        for step in list(self.undo.done) + list(self.undo.undone):
            if getattr(step, "restore", None) != self.apply_tab_document:
                continue
            for snapshot in (step.before, step.after):
                if isinstance(snapshot, dict) and "index" in snapshot:
                    old = int(snapshot["index"])
                    snapshot["index"] = new_place.get(old, old)

    def duplicate_tab(self, idx):
        """A second sheet with the same contents, after this one and the
        sheets glued to it.

        Everything the sheet holds is copied: the numbers, the formulas
        (the random ones draw the very same numbers), the column names,
        which columns are plotted against which axis, and the colour of the
        tab.  The copy is not tied to the diagram of the original - its
        `Plot with previous tab` is left off - and it comes to the front.
        """
        idx = int(idx)
        if not (0 <= idx < len(self.tables)):
            return None
        self.tables[idx]._commit_edit()
        snapshot = self.tab_document(idx)
        name = self.free_tab_name(f"{snapshot['name']} copy")
        # after the sheets glued to this one, never between them: put right
        # after it, the copy would take its fitted curves away from it
        place = self.tab_group_end(idx) + 1
        self.undo.hold()           # building the copy is not an edit of it
        try:
            table = self.add_tab(name, at=place)
            snapshot.update(index=place, name=name,
                            plot_with_previous=False)
            self.apply_tab_document(snapshot)
        finally:
            self.undo.release()
        table._undo_document = self.tab_document(place)
        self.root.after_idle(self.focus_sheet)
        return table

    def rename_tab(self, idx):
        """Ask for a new name (the right click menu of a tab)."""
        current_name = self.notebook.tab(idx, "text")
        new_name = simpledialog.askstring("Rename Tab", "New tab name:",
                                          initialvalue=current_name,
                                          parent=self.root)
        if new_name:
            self.set_tab_name(idx, new_name)
        return new_name

    def set_tab_name(self, idx, name):
        """Give one sheet a new name; the diagrams follow it."""
        name = str(name).strip()
        if not name or not (0 <= int(idx) < len(self.tables)):
            return None
        self.notebook.tab(idx, text=name)
        # a curve of this sheet carries its name: "Signal (Monday)"
        self.refresh_windows(idx)
        return name

    def refresh_windows(self, index=None):
        """Bring the diagrams up to date without asking any questions.

        `update_plot` is the command of the toolbar and says so when there
        is nothing to draw; this is the quiet one used when something else
        (a renamed sheet, say) has to reach the diagrams.
        """
        for window in self.open_windows():
            where = self.window_tab(window)
            if index is not None and int(index) not in self.tab_chain(where):
                continue
            window.update_data(self.plot_data(index=where),
                               layout=self.plot_layout(index=where))
        return True

    # -- writing the name of a tab straight on the tab ---------------------
    def _tab_at(self, x, y):
        """The number of the tab under a point of the row of tabs, or None."""
        try:
            return self.tab_bar.tab_at(int(x), int(y))
        except (tk.TclError, ValueError, TypeError, AttributeError):
            return None

    def tab_box(self, idx):
        """(x, y, width, height) of one tab in the row of tabs, or None.

        The row is scrolled first, if it has to be, so that the whole tab
        is in view.
        """
        try:
            return self.tab_bar.tab_box(int(idx))
        except (tk.TclError, ValueError, TypeError, AttributeError):
            return None

    def begin_tab_rename(self, idx=None):
        """Write the name of a sheet on the tab itself.

        The second click on the tab that is already in front opens it, just
        as a second click on an axis label of a diagram does.
        """
        idx = self.active_tab_index if idx is None else int(idx)
        if not (0 <= idx < len(self.tables)):
            return None
        self.cancel_tab_rename()
        box = self.tab_box(idx)
        if box is None:
            return self.rename_tab(idx)      # a window too small to write on
        x, y, width, height = box
        editor = tk.Entry(self.tab_bar, justify="center", relief="solid",
                          borderwidth=1, highlightthickness=0,
                          insertbackground=CARET_COLOR, insertwidth=2)
        editor.insert(0, self.notebook.tab(idx, "text"))
        editor.select_range(0, "end")
        editor.place(in_=self.tab_bar, x=x, y=y,
                     width=max(width, 60), height=height)
        editor.bind("<Return>", lambda _e: self.commit_tab_rename())
        editor.bind("<KP_Enter>", lambda _e: self.commit_tab_rename())
        editor.bind("<Escape>", lambda _e: self.cancel_tab_rename())
        editor.bind("<FocusOut>", lambda _e: self.commit_tab_rename())
        self._tab_editor = (editor, idx)
        editor.focus_force()
        return editor

    def commit_tab_rename(self, _event=None):
        """Keep what was written on the tab."""
        holder, self._tab_editor = getattr(self, "_tab_editor", None), None
        if holder is None:
            return None
        editor, idx = holder
        try:
            text = editor.get()
        except tk.TclError:
            text = ""
        try:
            editor.destroy()
        except tk.TclError:
            pass
        return self.set_tab_name(idx, text)

    def cancel_tab_rename(self, _event=None):
        """Throw the writing away."""
        holder, self._tab_editor = getattr(self, "_tab_editor", None), None
        if holder is None:
            return None
        try:
            holder[0].destroy()
        except tk.TclError:
            pass
        return None

    def _on_tab_click(self, event):
        """A second click on the tab in front writes its name."""
        if getattr(self, "_tab_editor", None) is not None:
            self.commit_tab_rename()
        idx = self._tab_at(event.x, event.y)
        if idx is None:
            return None
        if hasattr(self, "plus_frame") and idx == self.notebook.index(self.plus_frame):
            self._tab_click = None
            return None
        previous, self._tab_click = getattr(self, "_tab_click", None), None
        now = time.monotonic()
        if (previous is not None and previous[0] == idx
                and idx == self.active_tab_index
                and (now - previous[1]) * 1000.0 <= RENAME_DELAY):
            self.root.after_idle(lambda where=idx: self.begin_tab_rename(where))
            return None
        self._tab_click = (idx, now)
        return None

    def _on_tab_double_click(self, event):
        """Two quick clicks write the name as well."""
        idx = self._tab_at(event.x, event.y)
        self._tab_click = None
        if idx is None:
            return None
        if hasattr(self, "plus_frame") and idx == self.notebook.index(self.plus_frame):
            return None
        self.root.after_idle(lambda where=idx: self.begin_tab_rename(where))
        return "break"
            
    def color_tab(self, idx):
        _, hex_value = colorchooser.askcolor(title="Choose Tab Colour",
                                             parent=self.root)
        if hex_value:
            self.set_tab_color(idx, hex_value)
        return hex_value

    def set_tab_color(self, idx, hex_value):
        """Paint the little square on one tab (None takes it away).

        The colour is kept by the sheet itself, so it stays with it when a
        tab before it is deleted, and it is written into the `.aplt` file.
        """
        if not (0 <= int(idx) < len(self.tables)):
            return None
        table = self.tables[int(idx)]
        color = safe_hex(hex_value, None) if hex_value else None
        table.tab_color = color
        key = str(table.master)
        if color is None:
            self.tab_images.pop(key, None)
            self.notebook.tab(idx, image="", compound="none")
            return None
        img = tk.PhotoImage(width=14, height=14)
        img.put(color, to=(0, 0, 14, 14))
        # kept by the sheet itself: a number would point at the wrong
        # tab as soon as one before it is deleted, and the picture would
        # be collected while its tab still shows it
        self.tab_images[key] = img
        self.notebook.tab(idx, image=img, compound="left")
        return color

    def tab_color(self, idx):
        """The colour of one tab, or None."""
        if not (0 <= int(idx) < len(self.tables)):
            return None
        return getattr(self.tables[int(idx)], "tab_color", None)

    def delete_tab(self, idx):
        if len(self.tables) <= 1:
            messagebox.showinfo("Information", "Cannot delete the last tab.")
            return
            
        current_name = self.notebook.tab(idx, "text")
        if messagebox.askyesno("Delete Tab", f"Delete tab '{current_name}' with its data?", parent=self.root):
            # the sheets glued to this one stay together, as a group of
            # their own: they are not handed over to the sheet before it
            if not self.tab_ticked(idx) and self.tab_ticked(idx + 1):
                self.tables[idx + 1].plot_with_previous_var.set(False)
            table = self.tables.pop(idx)
            self.notebook.forget(idx)
            self.tab_images.pop(str(table.master), None)
            table.master.destroy()   # the frame that holds the sheet
            # the diagrams know which sheet they draw: the ones after the
            # deleted sheet moved up by one
            for window in self.open_windows():
                where = getattr(window, "source_tab", None)
                if where is None:
                    continue
                if where > idx:
                    window.source_tab = where - 1
                elif where == idx:
                    window.source_tab = min(idx, len(self.tables) - 1)
            
            if self.active_tab_index >= len(self.tables):
                self.notebook.select(len(self.tables) - 1)

    def _focus(self):
        self.root.lift()
        self.root.attributes("-topmost", True)
        self.root.attributes("-topmost", False)
        self.root.focus_force()
        self.focus_sheet()

    # widgets of the main window that take no typing: the keyboard is no
    # use to them, so it is handed on to the sheet in front
    IDLE_CLASSES = ("Tk", "TNotebook", "TFrame", "Frame", "Canvas", "TLabel",
                    "Label", "TLabelframe", "Labelframe", "TSeparator",
                    "TScrollbar", "Scrollbar", "TPanedwindow", "Panedwindow")
    # ...and the buttons, which keep the keys that press them (Space) but
    # must not keep the keyboard once they have been clicked
    BUTTON_CLASSES = ("TButton", "Button", "TCheckbutton", "Checkbutton",
                      "TRadiobutton", "Radiobutton", "TMenubutton",
                      "Menubutton")
    # the keys a sheet moves with or acts on
    SHEET_KEYS = ("Up", "Down", "Left", "Right", "Return", "KP_Enter", "F2",
                  "Delete", "BackSpace", "Home", "End", "Prior", "Next")

    def _widget_class(self, widget):
        try:
            return str(widget.winfo_class())
        except (tk.TclError, AttributeError):
            return ""

    def keyboard_nowhere(self, widget, buttons=True):
        """True when `widget` (holding the keyboard) cannot use it.

        The window itself, the notebook, a frame, the row of tabs - and,
        with `buttons`, a button that was just clicked.  A text field (the
        formula bar, a cell, the name of a tab), the sheet itself and any
        widget of another window are not.
        """
        if widget is None:
            return True
        try:
            if widget.winfo_toplevel() is not self.root:
                return False
        except (tk.TclError, AttributeError, KeyError):
            return False
        kind = self._widget_class(widget)
        if kind in self.IDLE_CLASSES:
            return True
        return buttons and kind in self.BUTTON_CLASSES

    def _window_came_back(self, _event=None):
        """The main window is the active one again.

        When the user comes back to it (a click on its title bar, the
        Dock, Cmd+Tab) the system may hand the keyboard to the window
        itself instead of to the cell that had it; the arrows and the
        typing then went nowhere until a cell was clicked.  Whatever holds
        the keyboard is looked at once things have settled, and if it has
        no use for it the sheet in front takes it.
        """
        try:
            self.root.after_idle(self._settle_keyboard)
        except tk.TclError:
            pass
        return None

    def _settle_keyboard(self):
        try:
            current = self.root.focus_get()
        except (tk.TclError, KeyError):
            current = None
        if current is not None and not self.keyboard_nowhere(current):
            return False
        return self.focus_sheet(force=True)

    def _stray_key(self, event):
        """A key pressed while the keyboard was on something that cannot use
        it (see `keyboard_nowhere`): the sheet in front gets it.

        The sheet takes the keyboard for good, and this very key is handed
        to it as well, so the first arrow or the first digit is not lost.
        """
        widget = getattr(event, "widget", None)
        if not self.keyboard_nowhere(widget, buttons=False):
            return None
        try:
            if int(event.state or 0) & TYPING_COMMAND_KEYS:
                return None           # a command: the menus deal with it
        except (TypeError, ValueError):
            pass
        table = self.table
        if table is None or not self.focus_sheet(force=True):
            return None
        keysym = str(getattr(event, "keysym", "") or "")
        if keysym in self.SHEET_KEYS:
            try:
                table.tree.event_generate("<KeyPress>", keysym=keysym,
                                          state=int(event.state or 0))
            except (tk.TclError, TypeError, ValueError):
                return None
            return "break"
        if table._on_grid_typing(event) == "break":
            return "break"
        return None

    def focus_sheet(self, _event=None, force=False):
        """The sheet in front takes the keyboard, ready to be typed into.

        Without this the window itself held the keyboard when the program
        started, so the arrow keys moved no cell selector and nothing typed
        arrived until a cell had been clicked.
        """
        table = self.table
        if table is None:
            return False
        try:
            current = self.root.focus_displayof()
        except (tk.TclError, KeyError):
            current = None
        if current is not None and self.keyboard_busy(current):
            return False            # a cell that is open keeps the keyboard
        if current is not None and not force:   # a dialog or a diagram
            try:
                if current.winfo_toplevel() is not self.root:
                    return False
            except (tk.TclError, AttributeError):
                return False
        if getattr(self, "_tab_editor", None) is not None:
            return False            # a tab name is being written
        return table.take_keyboard()

    # -- user interface ----------------------------------------------------
    def as_tall_as_icons(self, button):
        """A button with words only stands as tall as the ones with icons.

        It carries an invisible picture one pixel wide and as tall as an
        icon, laid under its words (`compound="center"`), so it takes no
        room of its own sideways.
        """
        spacer = getattr(self, "_icon_spacer", None)
        if spacer is None:
            try:
                spacer = tk.PhotoImage(width=1, height=ICON_SIZE)
            except tk.TclError:
                return None
            self._icon_spacer = spacer
        try:
            button.configure(image=spacer, compound="center")
        except tk.TclError:
            return None
        return spacer

    @staticmethod
    def _set_tool_icon(button, name, words):
        """Give a toolbar button its drawn icon (or words without Pillow)."""
        picture = file_tool_icon(name)
        if picture is None:
            button.configure(text=words)
        else:
            button.icon_img = picture        # kept, or Tk lets it go
            button.configure(image=picture, compound="left")
        return picture

    def _build_toolbar(self):
        alt = "Opt" if sys.platform == "darwin" else "Alt"
        # tidy buttons: as tall as their icons, with no wide empty rim
        try:
            ttk.Style().configure(TOOLBAR_STYLE, padding=TOOLBUTTON_PADDING)
        except tk.TclError:
            pass
        bar = ttk.Frame(self.root, padding=(10, 8))
        bar.pack(fill="x")
        self.current_plot_style = "line_symbol"
        # where a new row / column goes: remembered from the split buttons
